window.EXPLAIN = {"01-01":{"s":"貸金業法上の用語の定義（第2条）を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"貸金業には、金銭の貸付けだけでなく、金銭の貸借の媒介で業として行うものも「含まれます」。","w":"貸金業法第2条第1項。","r":[["貸金業法","2"]]},"2":{"t":false,"p":"債務者等とは、「債務者又は債務者であった者」ではなく「債務者又は保証人」をいいます。","w":"貸金業法第2条第5項。","r":[["貸金業法","2"]]},"3":{"t":true,"w":"貸金業法第2条第2項。","r":[["貸金業法","2"]]},"4":{"t":false,"p":"顧客等には、資金需要者である顧客だけでなく、保証人となろうとする者も「含まれます」。","w":"貸金業法第2条第4項。","r":[["貸金業法","2"]]}}},"01-02":{"s":"貸金業務取扱主任者の設置を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"主任者は従業者の数の50分の1以上となる数を置くもので、営業所等ごとに複数置くことも「できます」。","w":"貸金業法第12条の3第1項、施行規則第10条の8。","r":[["貸金業法","12の3"],["貸金業法施行規則","10の8"]]},"2":{"t":true,"w":"貸金業法第12条の3第1項、施行規則第10条の8。","r":[["貸金業法","12の3"],["貸金業法施行規則","10の8"]]},"3":{"t":false,"p":"主任者は営業所等に常時勤務する者でなければなりませんが、営業時間中「常時駐在させること」までは求められていません（公式正答による）。","w":"施行規則第10条の7第1項第1号。","r":[["貸金業法施行規則","10の7"]]},"4":{"t":false,"p":"従業者名簿には、主任者であるか否かの別や登録番号も記載「しなければなりません」。","w":"貸金業法第12条の3第4項、第12条の4第2項、施行規則第10条の9の2第1項第3号・第4号。","r":[["貸金業法","12の4"],["貸金業法施行規則","10の9の2"]]}}},"01-03":{"s":"登録申請書に記載すべき役員・政令で定める使用人を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"貸金業法施行令第3条、施行規則第3条第3号。","r":[["貸金業法施行令","3"],["貸金業法施行規則","3"]]},"2":{"t":false,"p":"金銭の出納業務のみに従事する事務員は、営業所等の業務を統括する者などに当たらず、政令で定める使用人に「当たりません」。","w":"施行規則第3条各号。","r":[["貸金業法施行規則","3"]]},"3":{"t":false,"p":"業務を執行する取締役が未成年者である場合、その法定代理人も役員に「当たります」。","w":"貸金業法第4条第1項第2号、施行規則第2条第1項第4号。","r":[["貸金業法","4"],["貸金業法施行規則","2"]]},"4":{"t":false,"p":"議決権の100分の25を超える株式を「他人の名義」で所有している個人も、役員に「当たります」。","w":"施行規則第2条第1項第1号（自己又は他人（仮設人を含む）の名義）。","r":[["貸金業法施行規則","2"]]}}},"01-04":{"s":"資力を明らかにする書面等の提出が必要な場合（貸金業法第13条第3項）の穴埋め問題です。正しいのは①です（ア50万円・イ100万円・ウ40万円）。","items":{"1":{"t":true,"w":"貸金業法第13条第3項第1号・第2号。Ｃ社の残高60万円と合わせて100万円を超えるのは、Ａ社の貸付金額が40万円を超える場合です。","r":[["貸金業法","13"]]},"2":{"t":false,"p":"ウは「20万円」ではなく「40万円」です（100万円－Ｃ社の残高60万円）。","r":[["貸金業法","13"]]},"3":{"t":false,"p":"アは「100万円」ではなく「50万円」、イは「200万円」ではなく「100万円」、ウは「40万円」です。","r":[["貸金業法","13"]]},"4":{"t":false,"p":"アは「50万円」、イは「100万円」、ウは「140万円」ではなく「40万円」です。","r":[["貸金業法","13"]]}}},"01-05":{"s":"マンスリーステートメント（一定期間の取引状況を記載した書面）を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"マンスリーステートメントは、極度方式基本契約を締結したときではなく、「極度方式貸付けに係る契約」を締結した場合に、相手方の「承諾を得て」交付できるものです。","w":"貸金業法第17条第6項。","r":[["貸金業法","17"]]},"2":{"t":false,"p":"電磁的方法による提供には、「あらかじめ」相手方の承諾を得る必要があります。事後の承諾では「足りません」。","w":"貸金業法第17条第7項、施行令第3条の4。","r":[["貸金業法","17"],["貸金業法施行令","3の4"]]},"3":{"t":false,"p":"マンスリーステートメントを交付するときは、契約締結時の書面の交付に「代えて」簡素化書面を交付でき、両方を交付する必要は「ありません」。","w":"貸金業法第17条第6項。","r":[["貸金業法","17"]]},"4":{"t":true,"w":"貸金業法第18条第3項。","r":[["貸金業法","18"]]}}},"01-06":{"s":"特定公正証書（強制執行に服する旨が記載された公正証書）の制限（貸金業法第20条）を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"貸金業法第20条第1項。","r":[["貸金業法","20"]]},"2":{"t":false,"p":"代理人の選任について、推薦その他これに類する関与をしては「なりません」。","w":"貸金業法第20条第2項。","r":[["貸金業法","20"]]},"3":{"t":false,"p":"直ちに強制執行に服することとなる旨に加え、債務者等の法律上の利益に与える影響に関する事項も説明「しなければなりません」。","w":"貸金業法第20条第3項第1号・第2号。","r":[["貸金業法","20"]]},"4":{"t":false,"p":"説明は口頭ではなく「書面を交付して」しなければなりません。","w":"貸金業法第20条第3項。","r":[["貸金業法","20"]]}}},"01-07":{"s":"加入貸金業者による個人信用情報の提供を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"提供が必要なのは、信用情報提供契約の締結時点で「貸付けの残高があるもの」に限られます。","w":"貸金業法第41条の35第1項。","r":[["貸金業法","41の35"]]},"2":{"t":false,"p":"提供すべき事項には、個人顧客の勤務先の商号又は名称も「含まれます」。","w":"施行規則第30条の13第1項第5号。","r":[["貸金業法","41の35"],["貸金業法施行規則","30の13"]]},"3":{"t":true,"w":"貸金業法第41条の35第2項。","r":[["貸金業法","41の35"]]},"4":{"t":false,"p":"信用情報提供契約の締結前に締結した契約に係る債権の管理に必要な場合は、資金需要者の同意は「不要」です。","w":"貸金業法第41条の36第1項、施行規則第30条の14第1項第2号。","r":[["貸金業法","41の36"],["貸金業法施行規則","30の14"]]}}},"01-08":{"s":"指定信用情報機関を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"指定を受けられる法人からは、外国の法令に準拠して設立された法人は「除かれます」。","w":"貸金業法第41条の13第1項第1号。","r":[["貸金業法","41の13"]]},"2":{"t":false,"p":"職員で「あった者」も秘密保持義務を負い、秘密を漏らせば刑事罰を科されることが「あります」。","w":"貸金業法第41条の16、第47条の3第1項第5号。","r":[["貸金業法","41の16"],["貸金業法","47の3"]]},"3":{"t":false,"p":"支障を生ずるおそれがないと認められる業務は、内閣総理大臣の承認を受けて行うことが「できます」。","w":"貸金業法第41条の18第1項ただし書。","r":[["貸金業法","41の18"]]},"4":{"t":true,"w":"貸金業法第41条の19第1項。","r":[["貸金業法","41の19"]]}}},"01-09":{"s":"受取証書（貸金業法第18条）を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"受取証書は、債権の全部だけでなく「一部」の弁済を受けたときも、その都度、直ちに交付しなければなりません。","w":"貸金業法第18条第1項。","r":[["貸金業法","18"]]},"2":{"t":false,"p":"受取証書には、契約年月日も記載「しなければなりません」。","w":"貸金業法第18条第1項第2号。","r":[["貸金業法","18"]]},"3":{"t":false,"p":"受取証書は、債務者ではなく「弁済をした者」（この場合は第三者）に交付します。","w":"貸金業法第18条第1項、施行規則第15条第1項第4号。","r":[["貸金業法","18"],["貸金業法施行規則","15"]]},"4":{"t":true,"w":"貸金業法第18条第2項。","r":[["貸金業法","18"]]}}},"01-10":{"s":"出資法と利息制限法の金利規制を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"業として行わない場合、出資法で刑事罰の対象となるのは年109.5％を「超える」利息の契約で、年40％では対象に「なりません」。","w":"出資法第5条第1項・第2項、利息制限法第1条第2号（10万円以上100万円未満は年1割8分）。","r":[["出資法","5"],["利息制限法","1"]]},"2":{"t":false,"p":"業として行う場合でも、出資法で刑事罰の対象となるのは年20％を「超える」利息の契約で、年20％ちょうどは対象に「なりません」。","w":"出資法第5条第2項、利息制限法第1条第3号。","r":[["出資法","5"],["利息制限法","1"]]},"3":{"t":true,"w":"出資法第5条第1項（業でなければ年109.5％超が対象）、利息制限法第1条第1号（10万円未満は年2割）。","r":[["出資法","5"],["利息制限法","1"]]},"4":{"t":false,"p":"元本50万円の上限は年1割5分ではなく「年1割8分」なので、無効になるのは年18％を超える部分です。","w":"出資法第5条第1項（年109.5％超は業かどうかを問わず対象）、利息制限法第1条第2号。","r":[["出資法","5"],["利息制限法","1"]]}}},"01-11":{"s":"みなし利息（利息制限法第6条）を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"利息制限法第6条第2項第2号。","r":[["利息制限法","6"]]},"2":{"t":false,"p":"公租公課の支払に充てられるべきものは、利息とみなされ「ません」。","w":"利息制限法第6条第2項第1号。","r":[["利息制限法","6"]]},"3":{"t":false,"p":"政令で定める額の範囲内のATM利用料は、利息とみなされ「ません」。","w":"利息制限法第6条第2項第3号。","r":[["利息制限法","6"]]},"4":{"t":false,"p":"債務者の要請によるカードの再発行の手数料は、利息とみなされ「ません」。","w":"利息制限法第6条第1項。","r":[["利息制限法","6"]]}}},"01-12":{"s":"業務改善命令（貸金業法第24条の6の3）の穴埋め問題です。正しいのは④です（ア資金需要者等の利益の保護を図るため必要がある・イ業務の方法の変更・ウ1年以下の懲役もしくは300万円以下の罰金、又はこれの併科）。","law":"出題時の「懲役」は、現行法では「拘禁刑」に改められています。現行の第48条は「1年以下の拘禁刑若しくは300万円以下の罰金」です。","items":{"1":{"t":false,"p":"アは「法令違反がある」ではなく「資金需要者等の利益の保護を図るため必要がある」です。","r":[["貸金業法","24の6の3"]]},"2":{"t":false,"p":"アは「資金需要者等の利益の保護を図るため必要がある」、イは「登録の取消し」ではなく「業務の方法の変更」、ウは「1年以下の懲役もしくは300万円以下の罰金」です。","r":[["貸金業法","24の6の3"],["貸金業法","48"]]},"3":{"t":false,"p":"イは「登録の取消し」ではなく「業務の方法の変更」、ウは「5年以下」ではなく「1年以下の懲役もしくは300万円以下の罰金」です。","r":[["貸金業法","24の6の3"],["貸金業法","48"]]},"4":{"t":true,"w":"貸金業法第24条の6の3第1項、第48条第1項第8号の2。","r":[["貸金業法","24の6の3"],["貸金業法","48"]]}}},"01-13":{"s":"内部管理態勢の整備を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"他に従業者がいない個人の貸金業者は、内部監査に代わる措置として、外部監査や協会の監査のほか、「自己検証」（自ら業務を検証すること）を利用することも認められています。","w":"監督指針（内部監査に代わる措置：外部監査・協会の監査・自己検証）。","r":[]},"2":{"t":true,"w":"監督指針Ⅱ－１（１）①（注）。","r":[]},"3":{"t":true,"w":"施行規則第10条の4。","r":[["貸金業法施行規則","10の4"]]},"4":{"t":true,"w":"自主規制基本規則第5条（業務の透明性の確保）。","r":[]}}},"01-14":{"s":"業務の適切な運営を確保するための措置を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"公式正答では適切です（監督指針の法令等遵守態勢の着眼点）。","r":[]},"2":{"t":true,"w":"監督指針Ⅱ－２－２（顧客等に関する情報管理態勢）。","r":[]},"3":{"t":true,"w":"施行規則第10条の6。","r":[["貸金業法施行規則","10の6"]]},"4":{"t":false,"p":"この措置の対象は、「個人又は法人」ではなく「個人である」資金需要者等の返済能力に関する情報です。","w":"施行規則第10条の3。","r":[["貸金業法施行規則","10の3"]]}}},"01-15":{"s":"無登録営業などの罰則を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"貸金業法第11条第1項、第47条第2号。","r":[["貸金業法","11"],["貸金業法","47"]]},"2":{"t":true,"w":"貸金業法第47条第1号。","r":[["貸金業法","47"]]},"3":{"t":true,"w":"取立て行為の規制は「貸金業を営む者」に適用されます。貸金業法第21条第1項第6号、第47条の3第1項第3号。","r":[["貸金業法","21"],["貸金業法","47の3"]]},"4":{"t":false,"p":"無登録の者による貸金業を営む旨の表示又は広告は、目的を問わず禁止され、刑事罰の対象に「なります」（目的が要件となるのは勧誘です）。","w":"貸金業法第11条第2項第1号・第2号、第47条の3第1項第2号。","r":[["貸金業法","11"],["貸金業法","47の3"]]}}},"01-16":{"s":"登録事項の変更の届出（貸金業法第8条）を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"貸金業法第8条第1項（営業所又は事務所の名称及び所在地の変更はあらかじめ届出）。","r":[["貸金業法","8"],["貸金業法","4"]]},"2":{"t":false,"p":"役員の変更は、「あらかじめ」ではなく、変更があった日から「2週間以内」に届け出ます。","w":"貸金業法第8条第1項、第4条第1項第2号。","r":[["貸金業法","8"],["貸金業法","4"]]},"3":{"t":true,"w":"貸金業法第8条第3項（内閣府令で定める書類を添付）。添付書類の内容は公式正答によります。","r":[["貸金業法","8"]]},"4":{"t":true,"w":"貸金業法第50条第1項第1号。","r":[["貸金業法","50"]]}}},"01-17":{"s":"貸付条件等と標識の掲示を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"掲示するのは、営業所の業務を統括する者ではなく、「貸金業務取扱主任者」の氏名です。","w":"貸金業法第14条第1項第4号。","r":[["貸金業法","14"]]},"2":{"t":true,"w":"施行規則第11条第4項。","r":[["貸金業法施行規則","11"]]},"3":{"t":true,"w":"施行規則第11条第5項ただし書。","r":[["貸金業法施行規則","11"]]},"4":{"t":true,"w":"貸金業法第23条第1項。","r":[["貸金業法","23"]]}}},"01-18":{"s":"極度方式基本契約の書面を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"貸金業法第17条第2項前段。","r":[["貸金業法","17"]]},"2":{"t":false,"p":"極度額を引き下げる変更は、契約変更時の書面の交付が「不要」な場合に当たります。","w":"貸金業法第17条第2項後段、施行規則第13条第5項第1号。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"3":{"t":true,"w":"貸金業法第17条第2項第1号、施行規則第13条第3項第1号イ・ロ。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"4":{"t":true,"w":"自主規制基本規則第26条（極度額が30万円を超える場合は原則5年以内）。","r":[]}}},"01-19":{"s":"保証契約に関する書面を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"貸金業法第16条の2第3項（2種類の書面を同時に交付することは公式正答による）。","r":[["貸金業法","16の2"]]},"2":{"t":true,"w":"貸金業法第17条第3項前段。","r":[["貸金業法","17"]]},"3":{"t":true,"w":"貸金業法第17条第3項後段、施行規則第13条第7項。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"4":{"t":false,"p":"保証の対象となる貸付けに係る契約が複数あっても、それらの契約の書面を1つの書面に「まとめなければならない」わけではありません（公式正答による）。","w":"貸金業法第17条第4項。","r":[["貸金業法","17"]]}}},"01-20":{"s":"返済能力の調査と過剰貸付けの禁止を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"貸金業法第13条の3第2項、施行規則第10条の25第1項（3月以内）。","r":[["貸金業法","13の3"],["貸金業法施行規則","10の25"]]},"2":{"t":true,"w":"貸金業法第13条第5項、施行規則第10条の19。","r":[["貸金業法","13"],["貸金業法施行規則","10の19"]]},"3":{"t":false,"p":"返済能力の調査義務は、個人だけでなく「法人」である顧客との契約にも適用されます。","w":"貸金業法第13条第1項（顧客等に限定はありません）。","r":[["貸金業法","13"]]},"4":{"t":true,"w":"貸金業法第13条第4項、施行規則第10条の18。","r":[["貸金業法","13"],["貸金業法施行規則","10の18"]]}}},"01-21":{"s":"個人過剰貸付契約（総量規制）の除外・例外を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"借換えの例外に当たるのは、1か月の負担が既存債務の1か月の負担を「上回らない」ものです。上回るものは例外に「当たりません」。","w":"施行規則第10条の23第1項第1号イ。","r":[["貸金業法施行規則","10の23"]]},"2":{"t":true,"w":"施行規則第10条の21第1項第2号。","r":[["貸金業法施行規則","10の21"]]},"3":{"t":true,"w":"施行規則第10条の21第1項第3号。","r":[["貸金業法施行規則","10の21"]]},"4":{"t":true,"w":"施行規則第10条の21第1項第4号。","r":[["貸金業法施行規則","10の21"]]}}},"01-22":{"s":"保証契約と総量規制の関係を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"貸金業法第13条第1項・第2項（保証人となろうとする者も顧客等）。","r":[["貸金業法","13"],["貸金業法","2"]]},"2":{"t":false,"p":"総量規制（個人過剰貸付契約の禁止）は、個人顧客を相手方とする「貸付けに係る契約」に適用され、保証契約には「適用されません」。","w":"貸金業法第13条の2第2項。保証契約は、返済能力を超えると認められる場合に禁止されます（同条第1項）。","r":[["貸金業法","13の2"]]},"3":{"t":true,"w":"貸金業法第13条の2第1項。","r":[["貸金業法","13の2"]]},"4":{"t":true,"w":"施行規則第10条の18第2項第2号。","r":[["貸金業法施行規則","10の18"]]}}},"01-23":{"s":"生命保険契約の締結に係る規制を問う問題です。適切でないのは②です。","law":"③の商法第674条第1項（被保険者の同意）は、現行法では保険法第38条などに移っています（貸金業法第16条の3第1項）。","items":{"1":{"t":true,"w":"公式正答では適切です（規定が設けられた経緯）。","r":[["貸金業法","12の7"]]},"2":{"t":false,"p":"住宅資金貸付契約などは規制の対象から「除かれ」、自殺による死亡を保険事故とすることは禁止されて「いません」。","w":"貸金業法第12条の7（住宅資金貸付契約その他の内閣府令で定める契約を除く）。","r":[["貸金業法","12の7"]]},"3":{"t":true,"w":"貸金業法第16条の3第1項（現行法では保険法第38条又は第67条第1項の同意）。","r":[["貸金業法","16の3"]]},"4":{"t":true,"w":"貸金業法第48条第1項第1号の3。","r":[["貸金業法","48"]]}}},"01-24":{"s":"帳簿（貸金業法第19条）を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"貸金業法第19条。","r":[["貸金業法","19"]]},"2":{"t":true,"w":"貸金業法第19条の2。","r":[["貸金業法","19の2"]]},"3":{"t":false,"p":"保証人も債務者等に当たり、主たる債務に係る帳簿のうち利害関係がある部分の閲覧を請求できるので、拒むことは「できません」。","w":"貸金業法第19条の2、第2条第5項。","r":[["貸金業法","19の2"],["貸金業法","2"]]},"4":{"t":true,"w":"施行規則第17条第1項。","r":[["貸金業法施行規則","17"]]}}},"01-25":{"s":"取立て行為の規制を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"貸金業法第24条の6の4第1項第2号。","r":[["貸金業法","24の6の4"]]},"2":{"t":true,"w":"施行規則第19条第2項。","r":[["貸金業法施行規則","19"]]},"3":{"t":true,"w":"貸金業法第21条第3項、施行規則第19条第6項ただし書。","r":[["貸金業法","21"],["貸金業法施行規則","19"]]},"4":{"t":false,"p":"取立ての委託を受けた者も、書面に代わる電磁的記録の送付によって支払を催告「できます」。","w":"貸金業法第21条第2項、施行規則第19条第2項。","r":[["貸金業法","21"],["貸金業法施行規則","19"]]}}},"01-26":{"s":"債権譲渡と取立ての委託の規制を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"貸金業法第24条第3項第1号（暴力団員等）。","r":[["貸金業法","24"]]},"2":{"t":false,"p":"商号や取立てを行う者の氏名などを明らかにする義務は、相手方の「請求があったとき」のものです。","w":"貸金業法第21条第3項。","r":[["貸金業法","21"]]},"3":{"t":true,"w":"貸金業法施行令第3条の7第3号。","r":[["貸金業法施行令","3の7"]]},"4":{"t":true,"w":"貸金業法施行令第3条の7第4号、施行規則第26条の24第1項。","r":[["貸金業法施行令","3の7"],["貸金業法施行規則","26の24"]]}}},"01-27":{"s":"日本貸金業協会の業務規程の記載事項（貸金業法第32条）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"貸金業法第32条第1号。","r":[["貸金業法","32"]]},"2":{"t":true,"w":"貸金業法第32条第4号。","r":[["貸金業法","32"]]},"3":{"t":true,"w":"貸金業法第32条第7号。","r":[["貸金業法","32"]]},"4":{"t":false,"p":"「営利の目的をもってする経営指導」に関する事項は、業務規程の記載事項に「含まれていません」。","w":"貸金業法第32条各号（協会員に対する監査、苦情の解決、研修など）。","r":[["貸金業法","32"]]}}},"01-28":{"s":"監督指針の「不正又は著しく不当な行為」に該当するおそれが大きい行為を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"監督指針Ⅱ－２－１０（２）②イｅ。","r":[["貸金業法","12の6"]]},"2":{"t":true,"w":"監督指針Ⅱ－２－１０（２）②ニ。","r":[["貸金業法","12の6"]]},"3":{"t":true,"w":"監督指針Ⅱ－２－１０（２）②。","r":[["貸金業法","12の6"]]},"4":{"t":false,"p":"おそれが大きいとされているのは、印鑑や運転免許証など社会生活上必要な証明書等そのものを徴求すること（預かること）です。証明書の「写し」の徴求は挙げられて「いません」。","w":"監督指針Ⅱ－２－１０（２）②イｃ。","r":[["貸金業法","12の6"]]}}},"01-29":{"s":"協会員の新聞・雑誌・電話帳広告の遵守事項を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"公式正答では適切です。現行の貸金業者の広告に関する細則Ⅰ．４．（１）④では、指定紛争解決機関の名称を表示することとされています。","r":[]},"2":{"t":true,"w":"貸金業者の広告に関する細則Ⅰ．４．（２）①（貸金業協会マークは視認性が確保される程度の大きさ）。","r":[]},"3":{"t":false,"p":"ギャンブル専門紙は、表現に留意すべき媒体ではなく、掲出そのものに留意すべき「出稿先」として挙げられています。","w":"貸金業者の広告に関する細則Ⅰ．４．（４）①（出稿先について：ギャンブル専門）。","r":[]},"4":{"t":true,"w":"貸金業者の広告に関する細則Ⅰ．４．（１）③・（２）②。","r":[]}}},"01-30":{"s":"監督指針の外部委託（Ⅱ－２－３）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"外部委託には、委託された業務が「海外で行われる場合も含む」とされており、海外の場合を除く扱いでは「ありません」。","w":"監督指針Ⅱ－２－３（１）③（注）。","r":[]},"2":{"t":true,"w":"監督指針Ⅱ－２－３（１）②。","r":[]},"3":{"t":true,"w":"監督指針Ⅱ－２－３（１）①。","r":[]},"4":{"t":true,"w":"監督指針Ⅱ－２－３（１）④。","r":[]}}},"01-31":{"s":"契約の成立を問う問題です。公式正答は③です。","law":"この回の基準日は2020年4月の民法改正の前です。出題時は、隔地者間の契約は承諾の通知を発した時に成立するとされていました（旧第526条第1項）。現行法では承諾も通知が到達した時に効力を生じる（第97条第1項）ため、②は現行法では適切です。また現行法では、書面でする消費貸借は、引き渡すことを約するだけで成立する諾成契約とされています（第587条の2）。","items":{"1":{"t":false,"p":"民法の消費貸借は、借主が金銭などを「受け取ることによって」成立する契約（要物契約）とされています。","w":"民法第587条。現行法では、書面でする消費貸借は諾成契約です（第587条の2第1項）。","r":[["民法","587"],["民法","587の2"]]},"2":{"t":false,"now":true,"p":"出題時の民法では、隔地者間の契約は承諾の通知を「発した時」に成立しました（旧第526条第1項。公式正答による）。","w":"現行法では、承諾の通知が到達した時に効力を生じ、契約が成立します（第97条第1項）。","r":[["民法","97"]]},"3":{"t":true,"w":"出題時の電子契約法の特例による記述です（公式正答による）。現行法でも、民法第97条第1項により承諾の通知が到達した時に成立します。","r":[["民法","97"]]},"4":{"t":false,"p":"諾否の通知を発しなかったときは、拒絶ではなく、申込みを「承諾したもの」とみなされます。","w":"商法第509条第2項。","r":[["商法","509"]]}}},"01-32":{"s":"債務不履行を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"不確定期限のときは、期限が到来した時ではなく、期限の到来した後に履行の請求を受けた時又は期限の到来を「知った時」のいずれか早い時から遅滞の責任を負います。","w":"民法第412条第2項。","r":[["民法","412"]]},"2":{"t":false,"p":"債務の全部の履行が不能であるときは、催告を「しなくても」直ちに契約を解除できます。","w":"民法第542条第1項第1号。","r":[["民法","542"]]},"3":{"t":false,"p":"賠償の対象は、条件関係にある全損害ではなく、「通常生ずべき損害」と、予見すべきであった「特別の事情による損害」です。","w":"民法第416条。","r":[["民法","416"]]},"4":{"t":true,"w":"民法第419条第3項。","r":[["民法","419"]]}}},"01-33":{"s":"犯罪収益移転防止法の本人確認（現行法では取引時確認）を問う問題です。適切なのは②です。","law":"出題時の「本人確認」は、現行法では「取引時確認」（第4条）とされ、本人特定事項のほか取引を行う目的や職業なども確認事項とされています。","items":{"1":{"t":false,"p":"金銭の貸借の媒介を内容とする契約の締結も、確認が「必要」な取引です（公式正答による）。","w":"犯罪収益移転防止法第4条第1項、施行令第7条。","r":[["犯罪による収益の移転防止に関する法律","4"],["犯罪による収益の移転防止に関する法律施行令","7"]]},"2":{"t":true,"w":"犯罪収益移転防止法第4条第1項第1号。","r":[["犯罪による収益の移転防止に関する法律","4"]]},"3":{"t":false,"p":"既に確認を行い、確認記録を作成・保存している顧客との取引は、契約の都度の確認が「不要」とされています。","w":"犯罪収益移転防止法第4条第3項。","r":[["犯罪による収益の移転防止に関する法律","4"]]},"4":{"t":false,"p":"確認記録は、契約が終了するまでではなく、契約が終了した日などから「7年間」保存しなければなりません。","w":"犯罪収益移転防止法第6条第2項。","r":[["犯罪による収益の移転防止に関する法律","6"]]}}},"01-34":{"s":"保証契約と連帯保証を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"民法第446条第2項・第3項。","r":[["民法","446"]]},"2":{"t":false,"p":"連帯保証でも、主たる債務が弁済で消滅すれば、保証債務も消滅します（付従性）。保証人は消滅を主張「できます」（公式正答による）。","w":"民法第446条第1項（保証人は主たる債務者が履行しないときに履行する責任を負う）。","r":[["民法","446"]]},"3":{"t":false,"p":"連帯保証人には、催告の抗弁（まず主たる債務者に催告せよと求める権利）は「ありません」。","w":"民法第454条。","r":[["民法","454"],["民法","452"]]},"4":{"t":false,"p":"連帯保証人は、人数で分けた額ではなく、主たる債務の「全額」について保証債務を負います（分別の利益がない。公式正答による）。","w":"民法第456条（分別の利益は各別の行為で保証した保証人の規定）、第454条。","r":[["民法","456"]]}}},"01-35":{"s":"物権変動を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"特約がなければ、所有権は代金の支払時ではなく、「意思表示（売買契約）の時」に移転します。","w":"民法第176条。","r":[["民法","176"]]},"2":{"t":true,"w":"民法第177条（二重譲渡では先に登記をした者が優先）。","r":[["民法","177"]]},"3":{"t":false,"p":"動産の譲渡は、引渡しがなければ第三者に対抗「できません」。","w":"民法第178条。","r":[["民法","178"]]},"4":{"t":false,"p":"即時取得は、買主が「善意であり、かつ、過失がない」ときに限り成立します。","w":"民法第192条。","r":[["民法","192"]]}}},"01-36":{"s":"弁済を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"金銭債務の弁済場所は、借主の住所ではなく「債権者（貸主）の現在の住所」です（持参債務）。","w":"民法第484条第1項。","r":[["民法","484"]]},"2":{"t":false,"p":"弁済の費用は、別段の意思表示がなければ、債権者ではなく「債務者」が負担します。","w":"民法第485条。","r":[["民法","485"]]},"3":{"t":true,"w":"民法第489条第1項（費用、利息、元本の順に充当）。","r":[["民法","489"]]},"4":{"t":false,"p":"当事者が第三者の弁済を禁止する意思表示をしたときは、第三者は弁済「できません」。","w":"民法第474条第4項。","r":[["民法","474"]]}}},"01-37":{"s":"強制執行を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"民事執行法第25条ただし書。","r":[["民事執行法","25"]]},"2":{"t":false,"p":"執行証書による強制執行には、執行文の付された正本が「必要」です（執行文が不要なのは少額訴訟の確定判決などに限られます）。","w":"民事執行法第25条本文・ただし書。","r":[["民事執行法","25"]]},"3":{"t":false,"p":"債務名義などの送達は、強制執行の開始後ではなく、「あらかじめ、又は同時に」されていなければなりません。","w":"民事執行法第29条。","r":[["民事執行法","29"]]},"4":{"t":false,"p":"執行文の付された債務名義の正本が滅失したときは、執行文を更に付与することが「できます」。","w":"民事執行法第28条第1項。","r":[["民事執行法","28"]]}}},"01-38":{"s":"相続の放棄を問う問題です。公式正答はｂｄです。","items":{"a":{"t":false,"p":"配偶者も相続の放棄をすることが「できます」。民法に配偶者の放棄を禁じる規定は「ありません」。","w":"民法第915条第1項、第938条（相続人一般の規定）。","r":[["民法","915"],["民法","938"]]},"b":{"t":true,"w":"民法第915条第1項、第938条。","r":[["民法","915"],["民法","938"]]},"c":{"t":false,"p":"相続の放棄は、3か月の期間内でも撤回「できません」。","w":"民法第919条第1項。","r":[["民法","919"]]},"d":{"t":true,"w":"民法第939条。","r":[["民法","939"]]}}},"01-39":{"s":"取締役会設置会社の取締役会を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"会社法第362条第2項第1号。","r":[["会社法","362"]]},"2":{"t":false,"p":"支店その他の重要な組織の設置、変更及び廃止は、取締役に委任「できません」。","w":"会社法第362条第4項第4号。","r":[["会社法","362"]]},"3":{"t":true,"w":"会社法第362条第2項第2号。","r":[["会社法","362"]]},"4":{"t":true,"w":"会社法第362条第3項。","r":[["会社法","362"]]}}},"01-40":{"s":"受託弁済（貸金業者の委託による第三者の弁済）を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"貸金業法第24条の3第3項第2号。","r":[["貸金業法","24の3"]]},"2":{"t":false,"p":"正当な利益（利害関係）を有しない第三者でも、債務者の意思に反しなければ弁済「できます」。","w":"民法第474条第1項・第2項。","r":[["民法","474"]]},"3":{"t":true,"w":"貸金業法第24条の3第2項（第21条を準用）。","r":[["貸金業法","24の3"],["貸金業法","21"]]},"4":{"t":true,"w":"貸金業法第24条の3第2項（第24条の6の10を準用し、都道府県知事と読み替え）。","r":[["貸金業法","24の3"],["貸金業法","24の6の10"]]}}},"01-41":{"s":"支払督促を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"民事訴訟法第383条第1項。","r":[["民事訴訟法","383"]]},"2":{"t":true,"w":"民事訴訟法第388条第2項。","r":[["民事訴訟法","388"]]},"3":{"t":false,"p":"仮執行の宣言は、職権ではなく「債権者の申立てにより」します。","w":"民事訴訟法第391条第1項。","r":[["民事訴訟法","391"]]},"4":{"t":true,"w":"民事訴訟法第392条。","r":[["民事訴訟法","392"]]}}},"01-42":{"s":"破産法の目的（第1条）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"破産法第1条。","r":[["破産法","1"]]},"2":{"t":true,"w":"破産法第1条。","r":[["破産法","1"]]},"3":{"t":true,"w":"破産法第1条。","r":[["破産法","1"]]},"4":{"t":false,"p":"裁判所の認可を受けた再生計画を定めることは、破産法ではなく「民事再生法」の目的に規定されています。","w":"民事再生法第1条。","r":[["民事再生法","1"],["破産法","1"]]}}},"01-43":{"s":"金融分野ガイドラインの安全管理措置を問う問題です。適切なのは③です。","law":"問題文の個人情報保護法第21条（従業者の監督）・第22条（委託先の監督）は、現行法ではそれぞれ第24条・第25条です。","items":{"1":{"t":false,"p":"組織的・人的・技術的安全管理措置などは、「いずれか」ではなく、そのすべてを含む措置を講じなければなりません。","w":"金融分野ガイドライン第8条第1項（現行は物理的安全管理措置と外的環境の把握も含む）。","r":[["個人情報保護法","23"]]},"2":{"t":false,"p":"漏えい事案等への対応についても、取扱規程を整備する必要が「あります」（公式正答による）。","w":"金融分野ガイドライン第8条（組織的安全管理措置）。","r":[["個人情報保護法","23"]]},"3":{"t":true,"w":"金融分野ガイドライン第10条第1項（現行の個人情報保護法第25条）。","r":[["個人情報保護法","25"]]},"4":{"t":false,"p":"監督の対象となる従業者には、雇用関係にない取締役、監査役、派遣社員等も「含まれます」。","w":"金融分野ガイドライン第9条第2項（現行の個人情報保護法第24条）。","r":[["個人情報保護法","24"]]}}},"01-44":{"s":"消費者契約法を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"事業として又は事業のために契約の当事者となる個人も、消費者契約法上の事業者に「当たります」。","w":"消費者契約法第2条第2項。","r":[["消費者契約法","2"]]},"2":{"t":true,"w":"消費者契約法第8条第1項第1号。","r":[["消費者契約法","8"]]},"3":{"t":false,"p":"賠償額の予定（違約金）も利息に含めて年109.5％を超える場合は、貸金業法により消費貸借の契約自体が無効に「なります」（公式正答による）。","w":"貸金業法第42条第1項（利息には債務の不履行について予定される賠償額を含む）。","r":[["貸金業法","42"]]},"4":{"t":false,"p":"取消しができるのは、事実と異なることを告げられて消費者が「誤認」し、それによって契約した場合です。誤認していなければ取り消せ「ません」。","w":"消費者契約法第4条第1項第1号。","r":[["消費者契約法","4"]]}}},"01-45":{"s":"ダイレクトメールによる勧誘を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"広告や多数の者に同様の内容で行う勧誘では、貸金業者登録簿に登録された電話番号「以外」を表示することは「できません」。","w":"貸金業法第15条第2項、施行規則第12条第4項・第5項。","r":[["貸金業法","15"],["貸金業法施行規則","12"]]},"2":{"t":true,"w":"貸金業法第16条第2項第3号。","r":[["貸金業法","16"]]},"3":{"t":false,"p":"拒否の意思表示には「応じなければならず」（一定期間の勧誘の拒否であれば最低6か月間は勧誘を見合わせる）、拒否の事実を記録・保存する必要もあります。","w":"自主規制基本規則第55条第1項第2号。","r":[]},"4":{"t":false,"p":"現行の自主規制基本規則では、勧誘を見合わせる期間は「最低1年間」で、期間経過後も、電話・ダイレクトメール・訪問など私生活や業務に与える影響が大きい方法による勧誘は「行わない」こととされています。","w":"自主規制基本規則第55条第1項第1号。","r":[]}}},"01-46":{"s":"契約締結前の書面（貸金業法第16条の2）を問う問題です。適切でないのは①です。","law":"②の「日本工業規格」は、現行法では「日本産業規格」と改称されています。","items":{"1":{"t":false,"p":"契約締結前の書面には、契約年月日や相手方の氏名・住所の記載は「求められていません」（これらは契約締結時の書面の記載事項です）。","w":"貸金業法第16条の2第1項各号、施行規則第12条の2第1項。","r":[["貸金業法","16の2"],["貸金業法施行規則","12の2"]]},"2":{"t":true,"w":"施行規則第12条の2第9項。","r":[["貸金業法施行規則","12の2"]]},"3":{"t":true,"w":"貸金業法第16条の2第2項。","r":[["貸金業法","16の2"]]},"4":{"t":true,"w":"貸金業法第16条の2第3項（2種類の書面を同時に交付することは公式正答による）。","r":[["貸金業法","16の2"]]}}},"01-47":{"s":"協会員による相談・助言と協会の苦情処理を問う問題です。適切でないのは④です。","law":"出題時の「苦情処理及び相談対応に関する規則」は、現在は「紛争解決等業務に関する規則」や「貸付自粛対応に関する規則」などに改められています。②③④は公式正答によります。","items":{"1":{"t":true,"w":"貸金業法第12条の9。","r":[["貸金業法","12の9"]]},"2":{"t":true,"w":"公式正答では適切です。現行の紛争解決等業務に関する規則第45条第2項にも同じ趣旨の定めがあります。","r":[]},"3":{"t":true,"w":"公式正答では適切です（出題時の規則による）。","r":[]},"4":{"t":false,"p":"正当な利害関係を有する近親者も、助言等を求めることが「できる」とされていました（公式正答による）。","w":"出題時の苦情処理規則による記述です。","r":[]}}},"01-48":{"s":"企業会計原則の一般原則の穴埋め問題です。正しいのは①です（ア真実な報告・イ正規の簿記・ウ財務諸表）。","items":{"1":{"t":true,"w":"企業会計原則 第一 一般原則 一・二・四。"},"2":{"t":false,"p":"イは「健全な会計処理」ではなく「正規の簿記」、ウは「会計記録」ではなく「財務諸表」です。"},"3":{"t":false,"p":"アは「正確な報告」ではなく「真実な報告」、ウは「会計記録」ではなく「財務諸表」です。"},"4":{"t":false,"p":"アは「真実な報告」、イは「正規の簿記」です。"}}},"01-49":{"s":"決算書等を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"一定期間の収益と費用から利益を示し、経営成績を表すのは、貸借対照表ではなく「損益計算書」です。","w":"企業会計原則 第二 損益計算書原則 一、第三 貸借対照表原則 一。","r":[]},"2":{"t":false,"p":"資産・負債・純資産を示し、一定時点の財政状態を表すのは、損益計算書ではなく「貸借対照表」です。","w":"企業会計原則 第三 貸借対照表原則 一。","r":[]},"3":{"t":true,"w":"公式正答では適切です（キャッシュ・フロー計算書の作成基準は取り込んだ資料にありません）。","r":[]},"4":{"t":false,"p":"株式会社の会計帳簿は、会社法で、適時に正確に作成することが「義務付けられています」。","w":"会社法第432条第1項。","r":[["会社法","432"]]}}},"01-50":{"s":"資力を明らかにする書面（施行規則第10条の17）を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"施行規則第10条の17第1項第1号、第2項第1号。","r":[["貸金業法施行規則","10の17"]]},"2":{"t":true,"w":"施行規則第10条の17第1項第4号、第2項第3号。","r":[["貸金業法施行規則","10の17"]]},"3":{"t":false,"p":"給与の支払明細書は、1年以内の任意の2か月分ではなく、「直近2月分以上」のものでなければなりません。","w":"施行規則第10条の17第1項第3号、第2項第2号。","r":[["貸金業法施行規則","10の17"]]},"4":{"t":true,"w":"施行規則第10条の17第1項第10号、第2項第1号。","r":[["貸金業法施行規則","10の17"]]}}},"02-01":{"s":"業務運営に関する措置（施行規則）を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"情報の取扱いを第三者に委託することは「禁止されていません」。委託する場合は、委託先の監督について必要かつ適切な措置を講じます。","w":"施行規則第10条の2第1項。","r":[["貸金業法施行規則","10の2"]]},"2":{"t":false,"p":"特別の非公開情報は、「一切」利用できないのではなく、適切な業務の運営の確保その他必要と認められる目的以外の目的に利用しないことを確保します。","w":"施行規則第10条の4。","r":[["貸金業法施行規則","10の4"]]},"3":{"t":true,"w":"施行規則第10条の3。","r":[["貸金業法施行規則","10の3"]]},"4":{"t":false,"p":"重要な事項の説明のための措置も、社内規則等で定める措置に「含まれます」。","w":"施行規則第10条の6。","r":[["貸金業法施行規則","10の6"]]}}},"02-02":{"s":"監督指針Ⅱ－２－６（反社会的勢力による被害の防止）を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"監督指針Ⅱ－２－６（１）②。","r":[]},"2":{"t":false,"p":"反社会的勢力と判明した後は、「合理的な理由がない限り資金提供等を行わない」のではなく、「可能な限り速やかに関係を解消する」ための態勢整備が求められています。","w":"監督指針Ⅱ－２－６（１）。","r":[]},"3":{"t":false,"p":"反社会的勢力をとらえる際は、行為要件「のみ」ではなく、暴力団などの「属性要件」にも着目することが重要とされています。","w":"監督指針Ⅱ－２－６（反社会的勢力のとらえ方）。","r":[]},"4":{"t":false,"p":"不当要求には、民事上の法的対抗手段を講じてはならないのではなく、「あらゆる民事上の法的対抗手段を講ずる」とともに、刑事事件化も躊躇しない対応を行うこととされています。","w":"監督指針Ⅱ－２－６（１）ハ。","r":[]}}},"02-03":{"s":"貸金業務取扱主任者の設置を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"主任者は業務に従事する者の50分の1以上の数なので、30人のＣ営業所にも「1人以上」置く必要があります。","w":"貸金業法第12条の3第1項、施行規則第10条の8。","r":[["貸金業法","12の3"],["貸金業法施行規則","10の8"]]},"2":{"t":false,"p":"主任者の変更（第4条第1項第6号の事項の変更）は、「30日以内」ではなく変更の日から「2週間以内」に届け出ます（公式正答による）。","w":"貸金業法第8条第1項、第4条第1項第6号。","r":[["貸金業法","8"]]},"3":{"t":false,"p":"定年退職は予見し難い事由に当たらないので、2週間の猶予は「ありません」。","w":"貸金業法第12条の3第3項、監督指針Ⅱ－２－９（２）③。","r":[["貸金業法","12の3"]]},"4":{"t":true,"w":"貸金業法第12条の3第4項。","r":[["貸金業法","12の3"]]}}},"02-04":{"s":"貸金業の登録を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"どの行政庁の登録を受けるかは、使用人の数ではなく、営業所又は事務所を「2以上の都道府県に設置するかどうか」で決まります。","w":"貸金業法第3条第1項。","r":[["貸金業法","3"]]},"2":{"t":false,"p":"申請書に記載するのは、主任者の「氏名及び住所」ではなく「氏名及び登録番号」です。","w":"貸金業法第4条第1項第6号。","r":[["貸金業法","4"]]},"3":{"t":true,"w":"施行規則第4条第4項第10号ただし書（登録の申請の日を含む事業年度に設立された法人は成立の時の貸借対照表）。","r":[["貸金業法施行規則","4"]]},"4":{"t":false,"p":"旅券や住民基本台帳カードの写しの「すべて」の添付が求められるわけではありません（公式正答による）。","w":"施行規則第4条（添付書類）。","r":[["貸金業法施行規則","4"]]}}},"02-05":{"s":"広告・勧誘の規制を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"貸金業法第16条第2項第1号。","r":[["貸金業法","16"]]},"2":{"t":false,"p":"返済能力がない者を対象として勧誘する旨の表示（第16条第2項第2号）の違反は、行政処分の対象ですが、刑事罰の対象では「ありません」。","w":"罰則（第48条第1項第3号）は第16条第1項の違反に限られます。","r":[["貸金業法","16"],["貸金業法","48"]]},"3":{"t":false,"p":"インターネット上の表示も広告に「該当します」。","w":"監督指針Ⅱ－２－１５（２）②ト。","r":[["貸金業法","15"]]},"4":{"t":false,"p":"破産免責を受けた者にも容易に貸付けを行う旨の表現は、借入意欲をそそる表示に該当する「おそれが大きい」とされています。","w":"監督指針Ⅱ－２－１５（２）④ロ。","r":[["貸金業法","16"]]}}},"02-06":{"s":"極度方式基本契約の書面の再交付を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"貸付けの利率の引下げは相手方の利益となる変更なので、再交付は「不要」です。","w":"施行規則第13条第4項第1号イ。","r":[["貸金業法施行規則","13"]]},"2":{"t":true,"w":"施行規則第13条第4項第1号イ（期限の利益の喪失の定め。第3項第1号ヌ）。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"3":{"t":false,"p":"極度額を引き下げた後、元の額を上回らない額まで引き上げたときは、再交付は「不要」です。","w":"施行規則第13条第5項第2号。","r":[["貸金業法施行規則","13"]]},"4":{"t":false,"p":"相手方の住所の変更は、再交付が必要な事項に「含まれません」。","w":"施行規則第13条第4項。","r":[["貸金業法施行規則","13"]]}}},"02-07":{"s":"極度方式基本契約の書面を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"貸金業者の住所は法律で定める記載事項で、登録番号を記載しても省略「できません」。","w":"貸金業法第16条の2第2項第1号。","r":[["貸金業法","16の2"]]},"2":{"t":true,"w":"貸金業法第17条第2項第3号（極度額を下回る額を提示する場合は当該下回る額及び極度額）。","r":[["貸金業法","17"]]},"3":{"t":false,"p":"マンスリーステートメントを交付する場合でも、契約締結時の書面に代えて簡素化書面を交付する必要が「あります」。","w":"貸金業法第17条第6項（簡素化書面は契約締結時の書面に代えて交付するもの）。","r":[["貸金業法","17"]]},"4":{"t":false,"p":"契約締結前の書面を交付していても、契約締結時の書面を交付する必要が「あります」。","w":"貸金業法第17条第2項。","r":[["貸金業法","17"]]}}},"02-08":{"s":"返済能力の調査を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"保証人となろうとする者も顧客等に含まれ、その返済能力の調査も「必要」です。","w":"貸金業法第13条第1項、第2条第4項。","r":[["貸金業法","13"],["貸金業法","2"]]},"2":{"t":false,"p":"極度方式貸付けに係る契約は、信用情報の使用義務の対象から「除かれています」。","w":"貸金業法第13条第2項、施行規則第10条の16第1号。","r":[["貸金業法","13"],["貸金業法施行規則","10の16"]]},"3":{"t":true,"w":"貸金業法第13条第4項。","r":[["貸金業法","13"]]},"4":{"t":false,"p":"返済能力の調査義務の違反は、登録の取消しの対象にも「なります」。","w":"貸金業法第24条の6の4第1項第2号。","r":[["貸金業法","24の6の4"]]}}},"02-09":{"s":"総量規制の例外（施行規則第10条の23）を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"事業を営む個人顧客への貸付けの例外は、返済能力を「超えない」と認められるものに限られます。","w":"施行規則第10条の23第1項第4号ロ。","r":[["貸金業法施行規則","10の23"]]},"2":{"t":false,"p":"個人顧客の居宅を担保とする貸付けは、例外にも除外にも「該当しません」。","w":"施行規則第10条の21第1項第6号（居宅などは除かれる）、第10条の23。","r":[["貸金業法施行規則","10の21"]]},"3":{"t":true,"w":"高額療養費の資金の貸付けは、例外（第10条の23）ではなく除外（施行規則第10条の21第1項第4号）の契約です。","r":[["貸金業法施行規則","10の21"]]},"4":{"t":false,"p":"借換えの例外に当たるには、1か月の負担が既存債務の1か月の負担を「上回らない」ことも必要です。","w":"施行規則第10条の23第1項第1号イ。","r":[["貸金業法施行規則","10の23"]]}}},"02-10":{"s":"利息制限法の上限を超える約定の効果を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"貸金業法で契約自体が無効になるのは年109.5％を超える場合で、年20％では無効に「なりません」。","w":"貸金業法第42条第1項。","r":[["貸金業法","42"]]},"2":{"t":false,"p":"元本100万円の上限は年1割8分ではなく「年1割5分」なので、有効なのは年15％に相当する部分までです。","w":"利息制限法第1条第3号。","r":[["利息制限法","1"]]},"3":{"t":false,"p":"出資法で刑事罰の対象となるのは、業として年20％を「超える」利息の契約です。年20％ちょうどは対象に「なりません」。","w":"出資法第5条第2項。","r":[["出資法","5"]]},"4":{"t":true,"w":"貸金業法第12条の8第1項、第24条の6の4第1項第2号。","r":[["貸金業法","12の8"],["貸金業法","24の6の4"]]}}},"02-11":{"s":"取立て行為の規制を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"商号や取立てを行う者の氏名などを明らかにする義務は、相手方の「請求があったとき」のものです。","w":"貸金業法第21条第3項。","r":[["貸金業法","21"]]},"2":{"t":false,"p":"保証人に対して取立てをするときも、主たる債務の契約内容（第17条第1項各号の事項など）を明らかに「しなければなりません」。","w":"施行規則第19条第5項第2号・第5号。","r":[["貸金業法施行規則","19"]]},"3":{"t":false,"p":"取立ての委託を受けた者が明らかにすべき事項を偽った場合も、刑事罰の対象に「なります」。","w":"貸金業法第21条第3項（委託を受けた者も対象）、第49条第7号。","r":[["貸金業法","21"],["貸金業法","49"]]},"4":{"t":true,"w":"施行規則第19条第2項。","r":[["貸金業法施行規則","19"]]}}},"02-12":{"s":"債権譲渡等の規制を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"貸金業法第24条第4項、第24条の6の4第1項第9号。","r":[["貸金業法","24"],["貸金業法","24の6の4"]]},"2":{"t":false,"p":"取立て制限者と知りながら債権を譲渡した従業者（行為者）も、刑事罰の対象と「なります」（両罰規定により法人も罰せられます）。","w":"貸金業法第51条第1項（両罰規定）。","r":[["貸金業法","51"],["貸金業法","24"]]},"3":{"t":false,"p":"法人である貸金業者の役員（取締役など）は、密接な関係を有する者に「当たります」。","w":"貸金業法施行令第3条の7第2号。","r":[["貸金業法施行令","3の7"],["貸金業法","24"]]},"4":{"t":false,"p":"取立て制限者であることを知らなかったことに相当の理由があることを「証明できたとき」は、この理由による処分の対象に「なりません」。","w":"貸金業法第24条の6の4第1項第4号イ。","r":[["貸金業法","24の6の4"]]}}},"02-13":{"s":"貸金業者に対する監督を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"信用情報提供契約の締結の届出は、「1か月以内」ではなく、その日から「2週間以内」です。","w":"貸金業法第24条の6の2第2号、施行規則第26条の25第2項。","r":[["貸金業法","24の6の2"],["貸金業法施行規則","26の25"]]},"2":{"t":false,"p":"名義貸し（第12条）の違反は、登録を取り消「さなければならない」事由です。","w":"貸金業法第24条の6の5第1項第4号。","r":[["貸金業法","24の6の5"]]},"3":{"t":false,"p":"立入検査は、資金需要者等の利益の保護を図るため必要があると認めるときに行うもので、毎事業年度1回以上受けなければならないものでは「ありません」。","w":"貸金業法第24条の6の10第3項。","r":[["貸金業法","24の6の10"]]},"4":{"t":true,"w":"貸金業法第24条の6の9。","r":[["貸金業法","24の6の9"]]}}},"02-14":{"s":"日本貸金業協会と協会員を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"協会員の名簿は「公衆の縦覧」に供されます。","w":"貸金業法第37条第7項。","r":[["貸金業法","37"]]},"2":{"t":false,"p":"協会は、「すべて」ではなく「政令で定める割合以上」の貸金業者を協会員としなければなりません。","w":"貸金業法第37条第2項。","r":[["貸金業法","37"]]},"3":{"t":false,"p":"協会員と誤認されるおそれのある文字を用いた者は、刑事罰を科され「ます」。","w":"貸金業法第37条第8項、第49条第9号。","r":[["貸金業法","37"],["貸金業法","49"]]},"4":{"t":true,"w":"貸金業法第37条第6項。","r":[["貸金業法","37"]]}}},"02-15":{"s":"登録の拒否事由を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"営業所等ごとに在籍が必要なのは、貸付けの業務に「3年以上」ではなく「1年以上」従事した者です。","w":"施行規則第5条の7第1項第3号。","r":[["貸金業法施行規則","5の7"]]},"2":{"t":true,"w":"施行規則第5条の7第1項第2号。","r":[["貸金業法施行規則","5の7"]]},"3":{"t":true,"w":"施行規則第5条の7第1項第4号・第2項。","r":[["貸金業法施行規則","5の7"]]},"4":{"t":true,"w":"貸金業法第6条第1項第9号ロ・第6号。","r":[["貸金業法","6"]]}}},"02-16":{"s":"登録の取消しを問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"公式正答では適切です。出資法違反で罰金の刑に処せられれば登録拒否事由（第6条第1項第5号）に該当し、登録の取消し（第24条の6の5第1項第1号）の対象となります。","r":[["貸金業法","6"],["貸金業法","24の6の5"]]},"2":{"t":false,"p":"所在を確知できない場合は「直ちに」取り消すのではなく、その事実を公告し、公告の日から「30日」を経過しても申出がないときに取り消すことができます。","w":"貸金業法第24条の6の6第1項第1号。","r":[["貸金業法","24の6の6"]]},"3":{"t":true,"w":"貸金業法第24条の6の6第1項第2号。","r":[["貸金業法","24の6の6"]]},"4":{"t":true,"w":"貸金業法第24条の6の6第1項第2号。","r":[["貸金業法","24の6の6"]]}}},"02-17":{"s":"無登録営業と名義貸しの禁止を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"貸金業法第11条第3項、第47条の3第1項第2号。","r":[["貸金業法","11"],["貸金業法","47の3"]]},"2":{"t":true,"w":"貸金業法第11条第2項第1号（表示・広告には目的の要件がない）、第47条の3第1項第2号。","r":[["貸金業法","11"],["貸金業法","47の3"]]},"3":{"t":false,"p":"名義貸しは、登録の取消しだけでなく、刑事罰の対象にも「なります」。","w":"貸金業法第12条、第47条第3号、第24条の6の5第1項第4号。","r":[["貸金業法","12"],["貸金業法","47"]]},"4":{"t":true,"w":"貸金業法第11条第1項（無登録営業の禁止）、第47条第2号。","r":[["貸金業法","11"],["貸金業法","47"]]}}},"02-18":{"s":"利息制限法の元本額の特則（第5条）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"重ねての貸付けで上限が変わるのは、後の貸付け（第二貸付契約）の利息です。先にした第一貸付契約の利息は無効に「なりません」。","w":"利息制限法第5条第1号。","r":[["利息制限法","5"]]},"2":{"t":true,"w":"利息制限法第5条第1号：残高30万円＋70万円＝100万円で、上限は年1割5分。","r":[["利息制限法","5"],["利息制限法","1"]]},"3":{"t":true,"w":"利息制限法第5条第1号・第2号：残高30万円＋同時の50万円と100万円＝180万円で、上限は年1割5分。","r":[["利息制限法","5"],["利息制限法","1"]]},"4":{"t":true,"w":"利息制限法第5条第1号・第2号：残高3万円＋同時の10万円と5万円＝18万円で、上限は年1割8分。","r":[["利息制限法","5"],["利息制限法","1"]]}}},"02-19":{"s":"みなし利息（利息制限法第6条）を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"利息制限法第6条第2項第1号。","r":[["利息制限法","6"]]},"2":{"t":false,"p":"政令で定める額の範囲内のATM利用料は、利息とみなされ「ません」。","w":"利息制限法第6条第2項第3号、施行令第2条。","r":[["利息制限法","6"],["利息制限法施行令","2"]]},"3":{"t":true,"w":"営業的金銭消費貸借では、利息とみなされない費用は第6条第2項の各号に限られ、契約書の作成手数料はこれに当たりません。","r":[["利息制限法","6"]]},"4":{"t":true,"w":"利息制限法第6条第1項、施行令第1条第1号。","r":[["利息制限法","6"],["利息制限法施行令","1"]]}}},"02-20":{"s":"従業者の証明書と従業者名簿を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"貸金業法第12条の4第2項。","r":[["貸金業法","12の4"]]},"2":{"t":true,"w":"施行規則第10条の9第3項。","r":[["貸金業法施行規則","10の9"]]},"3":{"t":true,"w":"施行規則第10条の9第1項第1号。","r":[["貸金業法施行規則","10の9"]]},"4":{"t":false,"p":"勧誘を伴わない広告のみを行う業務は、証明書を携帯させるべき業務に「含まれません」。","w":"施行規則第10条の9第2項。","r":[["貸金業法施行規則","10の9"]]}}},"02-21":{"s":"禁止行為（貸金業法第12条の6）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"監督指針Ⅱ－２－１０（２）②なお書き。","r":[["貸金業法","12の6"]]},"2":{"t":true,"w":"監督指針Ⅱ－２－１０（２）②ホ。","r":[["貸金業法","12の6"]]},"3":{"t":true,"w":"貸金業法第48条第1項第1号の2。","r":[["貸金業法","48"]]},"4":{"t":false,"p":"保証人となろうとする者に主たる債務者が確実に弁済すると誤解させる告知（第12条の6第3号）は、行政処分の対象ですが、刑事罰の対象では「ありません」。","w":"罰則は第12条の6第1号の虚偽告知に限られます（第48条第1項第1号の2）。","r":[["貸金業法","12の6"],["貸金業法","48"]]}}},"02-22":{"s":"受取証書（貸金業法第18条）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"電磁的方法による提供の承諾は、窓口での「口頭」ではなく「書面又は電磁的方法」で得る必要があります（公式正答による）。","w":"貸金業法第18条第4項（政令で定めるところにより承諾を得る）。","r":[["貸金業法","18"]]},"2":{"t":true,"w":"貸金業法第18条第2項。","r":[["貸金業法","18"]]},"3":{"t":true,"w":"貸金業法第18条第1項、施行規則第15条第1項。","r":[["貸金業法","18"],["貸金業法施行規則","15"]]},"4":{"t":true,"w":"施行規則第15条第3項。","r":[["貸金業法施行規則","15"]]}}},"02-23":{"s":"監督指針の返済能力調査・貸付審査の着眼点を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"監督指針Ⅱ－２－１３－１（１）①ロｂⅰ）。","r":[]},"2":{"t":true,"w":"公式正答では適切です（現行の監督指針で同じ記述は確認できません）。","r":[]},"3":{"t":true,"w":"監督指針Ⅱ－２－１３－１（１）①ロｂⅱ）。","r":[]},"4":{"t":false,"p":"売却予定であることが客観的に明らかな不動産担保貸付けは、保証や担保権実行を主な回収手段とする貸付けの防止措置の対象から「除かれています」。","w":"監督指針Ⅱ－２－１３－２（１）①ロｂⅰ）（※）。","r":[]}}},"02-24":{"s":"基準額超過極度方式基本契約を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"貸金業法第13条の3第5項。","r":[["貸金業法","13の3"]]},"2":{"t":true,"w":"施行規則第10条の24第1項第2号。","r":[["貸金業法施行規則","10の24"]]},"3":{"t":false,"p":"調査が不要になるのは、当該極度方式基本契約だけでなく他の極度方式基本契約の残高も「含めた合計額」が10万円以下の場合です。","w":"施行規則第10条の25第3項第1号。","r":[["貸金業法施行規則","10の25"]]},"4":{"t":true,"w":"貸金業法第13条の4、施行規則第10条の29。","r":[["貸金業法","13の4"],["貸金業法施行規則","10の29"]]}}},"02-25":{"s":"帳簿（貸金業法第19条）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"交渉の経過の記録も、帳簿に記載する必要が「あります」。","w":"施行規則第16条第1項第7号。","r":[["貸金業法施行規則","16"]]},"2":{"t":true,"w":"施行規則第17条第1項。","r":[["貸金業法施行規則","17"]]},"3":{"t":true,"w":"貸金業法第19条（営業所等ごとにその業務に関する帳簿を備える）。","r":[["貸金業法","19"]]},"4":{"t":true,"w":"施行規則第17条第2項。","r":[["貸金業法施行規則","17"]]}}},"02-26":{"s":"取立て行為の規制（貸金業法第21条）を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"貸金業法第21条第1項第1号、施行規則第19条第1項（午後9時から午前8時まで）。","r":[["貸金業法","21"],["貸金業法施行規則","19"]]},"2":{"t":false,"p":"勤務先への電話などが禁止されるのは「正当な理由がないのに」する場合です。債務者が自ら勤務先を連絡先として指定しているなどの正当な理由があれば、禁止「されません」。","w":"貸金業法第21条第1項第3号。","r":[["貸金業法","21"]]},"3":{"t":true,"w":"貸金業法第21条第1項第8号。","r":[["貸金業法","21"]]},"4":{"t":true,"w":"貸金業法第21条第1項第5号（債務者の借入れに関する事実を債務者等以外の者に明らかにすること）。","r":[["貸金業法","21"]]}}},"02-27":{"s":"保証業者に関する規制（貸金業法第24条の2）を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"貸金業法第24条の2第4項、施行令第3条の7第2号（法人の役員は密接な関係を有する者）。","r":[["貸金業法","24の2"],["貸金業法施行令","3の7"]]},"2":{"t":true,"w":"貸金業法第24条の2第2項（第21条を準用）。","r":[["貸金業法","24の2"],["貸金業法","21"]]},"3":{"t":false,"p":"貸金業者が保証業者を取立て制限者（暴力団員等）と「知りながら」保証契約を締結した場合に禁止され、刑事罰の対象になります。知らなかったときに「常に」刑事罰を科されるわけでは「ありません」。","w":"貸金業法第24条の2第3項、第48条第1項。","r":[["貸金業法","24の2"],["貸金業法","48"]]},"4":{"t":true,"w":"貸金業法第24条の2第2項（第12条の7を準用）。","r":[["貸金業法","24の2"],["貸金業法","12の7"]]}}},"02-28":{"s":"指定信用情報機関を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"貸金業法第13条第2項。","r":[["貸金業法","13"]]},"2":{"t":false,"p":"他の指定信用情報機関からの依頼には、「必要性が高いときに限り」ではなく、「正当な理由がある場合を除き」応じなければなりません。","w":"貸金業法第41条の24第1項。","r":[["貸金業法","41の24"]]},"3":{"t":true,"w":"貸金業法第41条の24第2項。","r":[["貸金業法","41の24"]]},"4":{"t":true,"w":"貸金業法第41条の20第1項第6号。","r":[["貸金業法","41の20"]]}}},"02-29":{"s":"指定信用情報機関の業務を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"貸金業法第41条の18第1項ただし書。","r":[["貸金業法","41の18"]]},"2":{"t":false,"p":"加入貸金業者（信用情報提供契約を結んだ貸金業者）に対する監督に関する事項も、業務規程に定める必要が「あります」。","w":"貸金業法第41条の20第1項第7号。","r":[["貸金業法","41の20"]]},"3":{"t":true,"w":"施行規則第30条の6第1項。","r":[["貸金業法","41の19"],["貸金業法施行規則","30の6"]]},"4":{"t":true,"w":"貸金業法第41条の19第2項。","r":[["貸金業法","41の19"]]}}},"02-30":{"s":"日本貸金業協会の苦情処理の規則を問う問題です。適切でないのは③です。","law":"出題時の「苦情処理及び相談対応に関する規則」は、現在は「紛争解決等業務に関する規則」などに改められています。①②は公式正答によります。","items":{"1":{"t":true,"w":"公式正答では適切です（出題時の規則の構成）。","r":[]},"2":{"t":true,"w":"公式正答では適切です。貸付自粛（本人の申告により、貸付けをしないよう信用情報機関に登録する制度）は、現在は「貸付自粛対応に関する規則」で定められています。","r":[]},"3":{"t":false,"p":"不受理の決定に対する不服申立ては、行政庁ではなく、受付窓口を経由して協会の「委員会」に対して行います。","w":"紛争解決等業務に関する規則第43条第1項・第2項。","r":[]},"4":{"t":true,"w":"紛争解決等業務に関する規則第44条第1項。","r":[]}}},"02-31":{"s":"任意代理（委任による代理）を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"代理人が権限内で本人のためにすることを示した意思表示は、本人の追認がなくても、本人に対して「直接に効力を生じます」。","w":"民法第99条第1項。","r":[["民法","99"]]},"2":{"t":true,"w":"民法第101条第1項。","r":[["民法","101"]]},"3":{"t":false,"p":"無権代理（代理権のない者がした代理）の契約も、本人が追認すれば本人に対して効力を「生じます」。","w":"民法第113条第1項、第116条。","r":[["民法","113"],["民法","116"]]},"4":{"t":false,"p":"代理権は、本人の死亡だけでなく、代理人の死亡によっても「消滅します」。","w":"民法第111条第1項第2号。","r":[["民法","111"]]}}},"02-32":{"s":"消滅時効の中断を問う問題です。公式正答はｂｄです。","law":"この回の基準日は2020年4月の民法改正の前で、「時効の中断」の制度で出題されています。現行法では「時効の完成猶予」と「時効の更新」に改められました。現行法では、承認は更新（第152条）、催告は6箇月の完成猶予（第150条）の事由です。訴えの取下げや調停の不成立など権利が確定せずに終わった場合は、その終了の時から6箇月を経過するまで時効の完成が猶予されますが、更新はされません（第147条第1項）。","items":{"a":{"t":false,"p":"債務の承認があれば、時効は中断「します」（現行法では更新）。","w":"民法第152条第1項。","r":[["民法","152"]]},"b":{"t":true,"w":"出題時の民法（旧第149条：訴えの取下げの場合は中断の効力を生じない）による記述です（公式正答による）。現行の第147条第1項では、取下げの時から6箇月の完成猶予があります。","r":[["民法","147"]]},"c":{"t":false,"p":"請求書の交付は裁判外の請求（催告）にすぎず、直ちに中断の効力を「生じません」（出題時は6か月以内に裁判上の請求などが必要）。","w":"現行の民法第150条第1項（催告は6箇月の完成猶予）。","r":[["民法","150"]]},"d":{"t":true,"w":"出題時の民法（旧第151条）による記述です（公式正答による）。現行の第147条第1項第3号では、調停が調わずに終了した時から6箇月の完成猶予があります。","r":[["民法","147"]]}}},"02-33":{"s":"債務不履行と裁判手続を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"金銭債務の不履行による損害賠償では、債権者は損害の証明をする必要が「ありません」。","w":"民法第419条第2項。","r":[["民法","419"]]},"2":{"t":true,"w":"民事訴訟法第271条（簡易裁判所では口頭で訴えを提起できる）。","r":[["民事訴訟法","271"]]},"3":{"t":false,"p":"裁判所は、訴訟がどの程度にあるかを問わず、和解を試みることが「できます」。","w":"民事訴訟法第89条第1項。","r":[["民事訴訟法","89"]]},"4":{"t":false,"p":"民事調停は、自己の営業所の所在地ではなく、「相手方」の住所、居所、営業所若しくは事務所の所在地を管轄する簡易裁判所（又は合意で定める裁判所）に申し立てます。","w":"民事調停法第3条第1項。","r":[["民事調停法","3"]]}}},"02-34":{"s":"少額訴訟を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"少額訴訟の対象は、「140万円以下」ではなく「60万円以下」の金銭の支払の請求です。","w":"民事訴訟法第368条第1項。","r":[["民事訴訟法","368"]]},"2":{"t":false,"p":"証拠調べは即時に取り調べることができる証拠に限られますが、証人の尋問も「できます」（宣誓をさせないですることもできます）。","w":"民事訴訟法第371条、第372条第1項。","r":[["民事訴訟法","371"],["民事訴訟法","372"]]},"3":{"t":true,"w":"民事訴訟法第377条。","r":[["民事訴訟法","377"]]},"4":{"t":false,"p":"請求を認容する判決で、分割払いの定めをすることが「できます」。","w":"民事訴訟法第375条第1項。","r":[["民事訴訟法","375"]]}}},"02-35":{"s":"仮差押え（判決前に財産を仮に押さえておく手続）を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"強制執行の前に仮差押えをしなければならないという定めは「ありません」（公式正答による）。","w":"民事執行法第22条・第25条（強制執行は債務名義により行う）。","r":[["民事執行法","22"]]},"2":{"t":false,"p":"仮差押命令は、条件付又は期限付の債権についても発することが「できます」。","w":"民事保全法第20条第2項。","r":[["民事保全法","20"]]},"3":{"t":false,"p":"訴訟が係属している間も、仮差押えを申し立てることが「できます」（本案の管轄裁判所も保全命令事件を管轄します）。","w":"民事保全法第12条第1項。","r":[["民事保全法","12"]]},"4":{"t":true,"w":"民事保全法第21条ただし書。","r":[["民事保全法","21"]]}}},"02-36":{"s":"債権に対する強制執行を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"民事執行法第143条。","r":[["民事執行法","143"]]},"2":{"t":false,"p":"差押命令では、第三債務者に対し債務者への弁済を禁止「しなければなりません」。","w":"民事執行法第145条第1項。","r":[["民事執行法","145"]]},"3":{"t":false,"p":"債権証書は、執行裁判所ではなく「差押債権者」に引き渡します。","w":"民事執行法第148条第1項。","r":[["民事執行法","148"]]},"4":{"t":false,"p":"給料などの債権は、すべてではなく、支払期に受けるべき給付の「4分の3に相当する部分」が差押禁止です。","w":"民事執行法第152条第1項。","r":[["民事執行法","152"]]}}},"02-37":{"s":"契約の申込みと承諾を問う問題です。適切でないのは④です。","law":"出題時の電子契約法には電子承諾通知に関する特例がありましたが、現行の同法にこの規定はありません（第4条は存在しません）。現行法では、民法の原則どおり承諾も通知が到達した時に効力を生じます（第97条第1項）。④は現行法でも適切でありません。","items":{"1":{"t":true,"w":"民法第523条第2項。","r":[["民法","523"]]},"2":{"t":true,"w":"商法第508条第1項。","r":[["商法","508"]]},"3":{"t":true,"w":"民法第97条第1項。","r":[["民法","97"]]},"4":{"t":false,"p":"電子承諾通知による契約は、通知を「発した時」ではなく、通知が「到達した時」に成立します。","w":"出題時は電子契約法の特例によります（公式正答による）。現行法では民法第97条第1項。","r":[["民法","97"]]}}},"02-38":{"s":"保証人を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"民法第453条（検索の抗弁）。","r":[["民法","453"]]},"2":{"t":true,"w":"民法第448条第1項。","r":[["民法","448"]]},"3":{"t":false,"p":"各別の行為で保証した数人の保証人は、全額ではなく、人数で等しく分けた額についてのみ責任を負います（分別の利益）。","w":"民法第456条、第427条。","r":[["民法","456"],["民法","427"]]},"4":{"t":true,"w":"民法第457条第1項（出題時は「時効の中断」、現行法では「時効の完成猶予及び更新」）。","r":[["民法","457"]]}}},"02-39":{"s":"弁済を問う問題です。適切でないのは①です。","law":"③の「債権の準占有者」に対する弁済の規定（旧第478条）は、2020年4月の改正で「受領権者としての外観を有する者」に対する弁済に改められました（第478条）。","items":{"1":{"t":false,"p":"債務の弁済は、原則として第三者も「することができます」。","w":"民法第474条第1項。","r":[["民法","474"]]},"2":{"t":true,"w":"民法第492条。","r":[["民法","492"]]},"3":{"t":true,"w":"出題時の民法（旧第478条）による記述です（公式正答による）。現行の民法第478条。","r":[["民法","478"]]},"4":{"t":true,"w":"民法第485条。","r":[["民法","485"]]}}},"02-40":{"s":"物権を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"民法第176条。","r":[["民法","176"]]},"2":{"t":false,"p":"物権は、民法その他の法律に定めるもののほか、創設することが「できません」（物権法定主義）。","w":"民法第175条。","r":[["民法","175"]]},"3":{"t":true,"w":"民法第177条。","r":[["民法","177"]]},"4":{"t":true,"w":"民法第178条。","r":[["民法","178"]]}}},"02-41":{"s":"犯罪収益移転防止法を問う問題です。適切でないのは①です。","law":"出題時の「本人確認」は、現行法では「取引時確認」（第4条）とされています。","items":{"1":{"t":false,"p":"疑わしい取引の届出先は「行政庁」だけで、指定信用情報機関に届け出る必要は「ありません」。","w":"犯罪収益移転防止法第8条第1項。","r":[["犯罪による収益の移転防止に関する法律","8"]]},"2":{"t":true,"w":"犯罪収益移転防止法第4条第1項（現行法では取引時確認）。","r":[["犯罪による収益の移転防止に関する法律","4"]]},"3":{"t":true,"w":"犯罪収益移転防止法第5条。","r":[["犯罪による収益の移転防止に関する法律","5"]]},"4":{"t":true,"w":"犯罪収益移転防止法第4条第1項第1号。","r":[["犯罪による収益の移転防止に関する法律","4"]]}}},"02-42":{"s":"暴力団対策法の暴力的要求行為を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"暴力団対策法第9条第1号。","r":[["暴力団員による不当な行為の防止等に関する法律","9"]]},"2":{"t":true,"w":"暴力団対策法第10条第1項。","r":[["暴力団員による不当な行為の防止等に関する法律","10"]]},"3":{"t":true,"w":"暴力団対策法第10条第2項。","r":[["暴力団員による不当な行為の防止等に関する法律","10"]]},"4":{"t":false,"p":"相手方の生活の平穏などが害されていると認めれば、反復のおそれが「なくても」中止を命ずることができます（反復のおそれは、すでに行為をした場合の再発防止命令の要件です）。","w":"暴力団対策法第11条第1項・第2項。","r":[["暴力団員による不当な行為の防止等に関する法律","11"]]}}},"02-43":{"s":"個人情報保護法と金融分野ガイドラインを問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"「自社の所要の目的で用いる」といった抽象的な利用目的は、「できる限り特定」したものと「なりません」。","w":"金融分野ガイドライン第2条第1項。","r":[["個人情報保護法","17"]]},"2":{"t":false,"p":"利用目的の達成に必要な範囲内で個人データの取扱いを委託する場合は、委託先は第三者に当たらないので、本人の同意は「不要」です。","w":"個人情報保護法第27条第5項第1号。","r":[["個人情報保護法","27"]]},"3":{"t":true,"w":"個人情報保護法第34条第2項。","r":[["個人情報保護法","34"]]},"4":{"t":false,"p":"あらかじめ利用目的を公表している場合は、通知（又は公表）は「不要」です。通知する場合に原則として書面によるとされています。","w":"個人情報保護法第21条第1項、金融分野ガイドライン第6条第1項。","r":[["個人情報保護法","21"]]}}},"02-44":{"s":"ホームページでの広告の表示を問う問題です。公式正答はａｃです。","items":{"a":{"t":true,"w":"貸金業法第15条第1項第3号、施行規則第12条第1項第1号ロ・第11条第3項第1号イ。","r":[["貸金業法","15"],["貸金業法施行規則","12"],["貸金業法施行規則","11"]]},"b":{"t":false,"p":"商品紹介ページには、返済シミュレーションの専用ページに誘導するハイパーリンクや画像を表示する方法でも「足ります」。","w":"貸金業者の広告に関する細則（インターネット広告の表示事項のなお書き）（返済シミュレーションには、専用ページに誘導するハイパーリンク又は画像の表示を含む）。","r":[]},"c":{"t":true,"w":"貸金業者の広告に関する細則Ⅰ．４．（１）③・（２）②（貸付条件又は契約内容の確認、使い過ぎ・借り過ぎへの注意、計画的な借入れ）。","r":[]},"d":{"t":false,"p":"登録簿に登録できる電話番号は場所を特定するものなどに限られ、携帯電話の番号を表示してよいわけでは「ありません」（ホームページアドレスを表示するときは登録された電話番号を表示します）。","w":"施行規則第12条第1項第3号、第3条の2第1項第1号、貸金業法第15条第2項。","r":[["貸金業法施行規則","12"],["貸金業法施行規則","3の2"],["貸金業法","15"]]}}},"02-45":{"s":"帳簿の閲覧・謄写の請求（貸金業法第19条の2）を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"債務者等「であった者」も、帳簿の閲覧又は謄写を請求「できます」。","w":"貸金業法第19条の2。","r":[["貸金業法","19の2"]]},"2":{"t":false,"p":"閲覧させる義務があるのは「営業時間内」で、営業時間外の請求は拒むことが「できます」。","w":"施行規則第17条の3。","r":[["貸金業法施行規則","17の3"]]},"3":{"t":false,"p":"保証人も債務者等に当たり、権利の行使に関する調査を目的としないことが明らかな場合を除き、請求「できます」。","w":"貸金業法第19条の2、第2条第4項。","r":[["貸金業法","19の2"],["貸金業法","2"]]},"4":{"t":true,"w":"貸金業法第19条の2、施行規則第17条の2第1項第2号、第17条の3。","r":[["貸金業法","19の2"],["貸金業法施行規則","17の2"],["貸金業法施行規則","17の3"]]}}},"02-46":{"s":"自主規制基本規則の「不正又は著しく不当な行為」に該当するおそれがある行為を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"自主規制基本規則第15条第4号。","r":[["貸金業法","12の6"]]},"2":{"t":false,"p":"該当するおそれがあるのは、虚偽の記載を「勧め又は示唆する」ことです。協会員の勧めによらない虚偽の申込書を、知らずに受け付けることは挙げられて「いません」。","w":"自主規制基本規則第15条第1号ホ。","r":[["貸金業法","12の6"]]},"3":{"t":true,"w":"自主規制基本規則第15条第5号。","r":[["貸金業法","12の6"]]},"4":{"t":true,"w":"自主規制基本規則第15条第1号ニ。","r":[["貸金業法","12の6"]]}}},"02-47":{"s":"日本貸金業協会の苦情への対応（貸金業法第41条の7）を問う問題です。適切でないのは②です。","law":"協会が指定紛争解決機関の指定を受けている場合は、第41条の7第1項は適用されません（同条第5項）。現在、苦情処理は紛争解決等業務として行われています。","items":{"1":{"t":true,"w":"貸金業法第41条の7第1項。","r":[["貸金業法","41の7"]]},"2":{"t":false,"p":"協会が説明を求めるのは苦情の解決に「必要があると認めるとき」で、その方法も文書に限らず「口頭」や資料の提出の求めでもよいとされています。","w":"貸金業法第41条の7第2項。","r":[["貸金業法","41の7"]]},"3":{"t":true,"w":"貸金業法第41条の7第3項。","r":[["貸金業法","41の7"]]},"4":{"t":true,"w":"貸金業法第41条の7第4項。","r":[["貸金業法","41の7"]]}}},"02-48":{"s":"キャッシュ・フロー計算書の区分の穴埋め問題です。正しいのは③です（ア営業活動・イ投資活動・ウ財務活動）。キャッシュ・フロー計算書の作成基準は取り込んだ資料にないため、公式正答によります。","items":{"1":{"t":false,"p":"アは「経常活動」ではなく「営業活動」、イは「資産活動」ではなく「投資活動」です。"},"2":{"t":false,"p":"アは「営業活動」、ウは「資金活動」ではなく「財務活動」です。"},"3":{"t":true,"w":"公式正答による。"},"4":{"t":false,"p":"イは「資産活動」ではなく「投資活動」、ウは「資金活動」ではなく「財務活動」です。"}}},"02-49":{"s":"給与所得者の収入を示す書面の穴埋め問題です。正しいのは①です（ア源泉徴収票・イ支払金額・ウ可処分所得）。所得税法や源泉徴収票の様式は取り込んだ資料にないため、公式正答によります。","items":{"1":{"t":true,"w":"公式正答による。"},"2":{"t":false,"p":"イは「収入金額等」ではなく「支払金額」、ウは「税引後当期純利益」ではなく「可処分所得」です。"},"3":{"t":false,"p":"アは「所得証明書」ではなく「源泉徴収票」、ウは「可処分所得」です。"},"4":{"t":false,"p":"アは「源泉徴収票」、イは「支払金額」です。"}}},"02-50":{"s":"企業会計原則の一般原則を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"真実な報告を提供するものでなければならないとする原則は、「明瞭性の原則」ではなく「真実性の原則」と呼ばれます。","w":"企業会計原則 第一 一般原則 一（明瞭性の原則は四）。","r":[]},"2":{"t":true,"w":"企業会計原則 第一 一般原則 二。","r":[]},"3":{"t":true,"w":"企業会計原則 第一 一般原則 三。","r":[]},"4":{"t":true,"w":"企業会計原則 第一 一般原則 五。","r":[]}}},"03-01":{"s":"貸金業法の目的（第1条）の穴埋め問題です。正しいのは②です（ア登録制度・イ認可・ウ資金需要者等）。","items":{"1":{"t":false,"p":"イは「指定」ではなく「認可」、ウは「貸金業者等」ではなく「資金需要者等」です。"},"2":{"t":true,"w":"貸金業法第1条。","r":[["貸金業法","1"]]},"3":{"t":false,"p":"アは「許可制度」ではなく「登録制度」、ウは「貸金業者等」ではなく「資金需要者等」です。"},"4":{"t":false,"p":"アは「許可制度」ではなく「登録制度」、イは「指定」ではなく「認可」です。"}}},"03-02":{"s":"貸金業法の用語の定義を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"国又は地方公共団体が行うものは、貸金業から「除かれます」。","w":"貸金業法第2条第1項第1号。","r":[["貸金業法","2"]]},"2":{"t":false,"p":"貸金業者とは登録を受けた者をいい、休止の届出をしていても貸金業者に「含まれます」。","w":"貸金業法第2条第2項。","r":[["貸金業法","2"]]},"3":{"t":false,"p":"債務者等とは、「債務者又は債務者であった者」ではなく「債務者又は保証人」をいいます。","w":"貸金業法第2条第5項・第6項。","r":[["貸金業法","2"]]},"4":{"t":true,"w":"貸金業法第2条第7項。","r":[["貸金業法","2"]]}}},"03-03":{"s":"業務運営に関する措置（施行規則）を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"安全管理措置の対象は「資金需要者等」に関する情報で、保証人となろうとする者の情報も「含まれます」。","w":"施行規則第10条の2第1項、貸金業法第2条第4項・第6項。","r":[["貸金業法施行規則","10の2"],["貸金業法","2"]]},"2":{"t":false,"p":"途上与信のために取得した信用情報を勧誘に二次利用することも、返済能力の調査以外の目的による使用に「該当します」。","w":"監督指針Ⅱ－２－１４（１）③ハｂ（注）、施行規則第10条の3。","r":[["貸金業法施行規則","10の3"]]},"3":{"t":false,"p":"特別の非公開情報は、「一切」利用しないのではなく、適切な業務の運営の確保その他必要と認められる目的以外の目的に利用しないことを確保します。","w":"施行規則第10条の4。","r":[["貸金業法施行規則","10の4"]]},"4":{"t":true,"w":"施行規則第10条の5第3号。","r":[["貸金業法施行規則","10の5"]]}}},"03-04":{"s":"登録の拒否の審査基準（施行規則第5条の7）を問う問題です。適切なのはａｃです。","items":{"a":{"t":true,"w":"施行規則第5条の7第1項第1号。","r":[["貸金業法施行規則","5の7"]]},"b":{"t":false,"p":"常務に従事する役員に求められる経験は、貸付けの業務に「5年以上」ではなく「3年以上」です。","w":"施行規則第5条の7第1項第2号。","r":[["貸金業法施行規則","5の7"]]},"c":{"t":true,"w":"施行規則第5条の7第1項第3号。","r":[["貸金業法施行規則","5の7"]]},"d":{"t":false,"p":"社内規則には、貸金業の業務に関する責任体制を明確化する規定を含める必要が「あります」。","w":"施行規則第5条の7第1項第4号・第2項。","r":[["貸金業法施行規則","5の7"]]}}},"03-05":{"s":"変更の届出（貸金業法第8条）を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"営業所等の名称・所在地の変更は、変更後2週間以内ではなく、「あらかじめ」届け出ます。","w":"貸金業法第8条第1項、第4条第1項第5号。","r":[["貸金業法","8"],["貸金業法","4"]]},"2":{"t":false,"p":"主任者の氏名・登録番号の変更は、「あらかじめ」ではなく、変更の日から「2週間以内」に届け出ます。","w":"貸金業法第8条第1項、第4条第1項第6号。","r":[["貸金業法","8"],["貸金業法","4"]]},"3":{"t":true,"w":"貸金業法第8条第1項・第3項（添付書類）。登記事項証明書の添付は公式正答によります。","r":[["貸金業法","8"]]},"4":{"t":false,"p":"業務の種類及び方法の変更も、2週間以内に届け出る「必要があります」。","w":"貸金業法第8条第1項、第4条第1項第8号。","r":[["貸金業法","8"],["貸金業法","4"]]}}},"03-06":{"s":"貸金業務取扱主任者を問う問題です。適切なのはｂｃです。","items":{"a":{"t":false,"p":"他の営業所等の主任者として登録されている者は、変更の届出をしなければ、別の営業所等の主任者に「なれません」（兼務はできません）。","w":"施行規則第10条の7第1項第2号。","r":[["貸金業法施行規則","10の7"]]},"b":{"t":true,"w":"貸金業法第24条の25第3項。","r":[["貸金業法","24の25"]]},"c":{"t":true,"w":"貸金業法第24条の25第4項。","r":[["貸金業法","24の25"]]},"d":{"t":false,"p":"講習を受けても、主任者登録の更新には「申請が必要」です。","w":"貸金業法第24条の32第1項（主任者登録は申請により更新する）。","r":[["貸金業法","24の32"]]}}},"03-07":{"s":"媒介手数料の上限（出資法第4条第1項）の計算を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"割合は「3％」ではなく「5％」で、期間が1年未満なので日割り計算します。"},"2":{"t":false,"p":"割合は「3％」ではなく「5％」です。"},"3":{"t":true,"w":"出資法第4条第1項：貸借の金額の100分の5（期間が1年未満のときは年5％の割合で日数に応じて計算）。","r":[["出資法","4"]]},"4":{"t":false,"p":"割合は「10％」ではなく「5％」です。"}}},"03-08":{"s":"標識の掲示（貸金業法第23条）を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"自動契約受付機などの設備のみの営業所等とそれ以外とで、標識の様式は「同じではありません」（公式正答による）。","w":"施行規則第20条第1項（別紙様式第7号）。様式の細目は取り込んだ資料で確認できません。","r":[["貸金業法施行規則","20"]]},"2":{"t":false,"p":"代理店の標識には、代理人であるＡの氏名なども表示する必要が「あります」（公式正答による）。","w":"施行規則第20条第1項（別紙様式第7号）。","r":[["貸金業法施行規則","20"]]},"3":{"t":false,"p":"標識の掲示に違反した場合は、行政処分だけでなく、刑事罰の対象にも「なります」。","w":"貸金業法第49条第7号の2（第23条違反）。","r":[["貸金業法","23"],["貸金業法","49"]]},"4":{"t":true,"w":"貸金業法第23条第1項。","r":[["貸金業法","23"]]}}},"03-09":{"s":"返済能力の調査を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"極度方式貸付けに係る契約は、信用情報の使用義務の対象から「除かれています」。貸付けのたびに信用情報を使用する必要はありません。","w":"貸金業法第13条第2項、施行規則第10条の16第1号。","r":[["貸金業法","13"],["貸金業法施行規則","10の16"]]},"2":{"t":true,"w":"施行規則第10条の24第1項第2号。","r":[["貸金業法","13の3"],["貸金業法施行規則","10の24"]]},"3":{"t":false,"p":"変更後の勤務先が確認され、変更後の勤務先で2月分以上の給与を受けていない場合は、変更前の書面等を「用いることができます」。1か月分の明細書で直ちに提出を受けなければならないわけではありません。","w":"施行規則第10条の17第3項。","r":[["貸金業法施行規則","10の17"]]},"4":{"t":false,"p":"返済能力の調査義務の違反は、業務停止だけでなく、登録の取消しの対象にも「なります」。","w":"貸金業法第24条の6の4第1項第2号。","r":[["貸金業法","24の6の4"]]}}},"03-10":{"s":"貸金業協会を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"協会は、定款で、違反した協会員に「過怠金を課す」旨も定めなければ「なりません」。","w":"貸金業法第38条第1項。","r":[["貸金業法","38"]]},"2":{"t":false,"p":"協会員は、貸金業者又は貸金業に類する業務を行う者に「限られます」。","w":"貸金業法第37条第1項。","r":[["貸金業法","37"]]},"3":{"t":false,"p":"業務停止命令や除名を受けた者の加入を拒否できる旨は協会の「定款」で定めることができるもので、貸金業法が加入を「禁止」しているのではありません。","w":"貸金業法第37条第4項・第6項。","r":[["貸金業法","37"]]},"4":{"t":true,"w":"貸金業法第41条の7第1項。","r":[["貸金業法","41の7"]]}}},"03-11":{"s":"外部委託（監督指針Ⅱ－２－３・施行規則第10条の5）を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"監督指針Ⅱ－２－３（１）①。","r":[]},"2":{"t":false,"p":"形式上外部委託契約が結ばれていなくても、実態において外部委託と同視しうる場合は、外部委託に「含まれます」。","w":"監督指針Ⅱ－２－３（１）③（注）。","r":[]},"3":{"t":false,"p":"委託業務に関する苦情等について、委託元である貸金業者への直接の連絡体制を設けるなど苦情相談態勢が整備されているかも、着眼点と「されています」。","w":"監督指針Ⅱ－２－３（１）②・⑪。","r":[]},"4":{"t":false,"p":"受託者の業務の実施状況を定期的に確認するなどして検証し、必要に応じ改善させる措置も講じる必要が「あります」。","w":"施行規則第10条の5第1号・第2号。","r":[["貸金業法施行規則","10の5"]]}}},"03-12":{"s":"監督指針Ⅱ－２－１９（取立行為規制）を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"反復継続して電子メールやファクシミリで送信することは、私生活や業務の平穏を害する言動に該当する「おそれが大きい」とされています。","w":"監督指針Ⅱ－２－１９（２）①イ。","r":[["貸金業法","21"]]},"2":{"t":false,"p":"反復継続して保証人の居宅を訪問することも、該当する「おそれが大きい」とされています。","w":"監督指針Ⅱ－２－１９（２）①イ。","r":[["貸金業法","21"]]},"3":{"t":false,"p":"保険金による債務の弁済を強要又は示唆することも、該当する「おそれが大きい」とされています。","w":"監督指針Ⅱ－２－１９（２）①ロ。","r":[["貸金業法","21"]]},"4":{"t":true,"w":"貸金業法第21条第1項第1号の「正当な理由」には、債務者等の自発的な承諾がある場合が該当する可能性が高いとされています（監督指針Ⅱ－２－１９（２）②イａ）。不適当な時間帯は施行規則第19条第1項（午後9時から午前8時まで）。","r":[["貸金業法","21"],["貸金業法施行規則","19"]]}}},"03-13":{"s":"登録換え（貸金業法第7条）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"貸金業法第7条第2号。","r":[["貸金業法","7"]]},"2":{"t":true,"w":"貸金業法第7条第1号。","r":[["貸金業法","7"]]},"3":{"t":true,"w":"貸金業法第7条第3号。","r":[["貸金業法","7"]]},"4":{"t":false,"p":"登録換えで新たに受けた登録の有効期間は、最初の内閣総理大臣の登録の時からではなく、「新たに登録を受けた時」から3年です（公式正答による）。","w":"貸金業法第3条第2項、第7条（新たな登録を受けたときは従前の登録は効力を失う）。","r":[["貸金業法","3"],["貸金業法","7"]]}}},"03-14":{"s":"誇大広告の禁止等を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"貸金業法第16条第5項。","r":[["貸金業法","16"]]},"2":{"t":false,"p":"貸金業法・同施行規則・景品表示法「のみ」ではなく、屋外広告物法に基づく条例その他の法令も守る必要があります。","w":"施行規則第12条第6項。","r":[["貸金業法施行規則","12"]]},"3":{"t":true,"w":"貸金業法第16条第2項第2号。","r":[["貸金業法","16"]]},"4":{"t":true,"w":"貸金業法第16条第4項。","r":[["貸金業法","16"]]}}},"03-15":{"s":"貸付条件の広告等（貸金業法第15条）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"「貸付けの条件について広告をする」とは、貸付けの条件の具体的内容を「すべて」表示した広告ではなく、「1つでも」表示した広告をすることをいいます。","w":"監督指針Ⅱ－２－１５（２）①。","r":[["貸金業法","15"]]},"2":{"t":true,"w":"監督指針Ⅱ－２－１５（２）②ト。","r":[["貸金業法","15"]]},"3":{"t":true,"w":"貸金業法第15条第1項、施行規則第12条第1項第2号（金銭の貸借の媒介は媒介手数料の計算の方法）。","r":[["貸金業法","15"],["貸金業法施行規則","12"]]},"4":{"t":true,"w":"貸金業法第15条第2項、施行規則第12条第4項・第5項。","r":[["貸金業法","15"],["貸金業法施行規則","12"]]}}},"03-16":{"s":"禁止行為と保険契約の制限を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"住宅の建設・購入・改良の資金の貸付け（住宅資金貸付契約）は、自殺による死亡を保険事故とする保険契約の禁止から「除かれています」。","w":"貸金業法第12条の7の括弧書（住宅資金貸付契約その他の内閣府令で定める契約を除く）。","r":[["貸金業法","12の7"]]},"2":{"t":true,"w":"公式正答では適切です。監督指針Ⅱ－２－１０（２）②イｄでも、合理的理由がないのに過大な担保又は保証人を徴求することは第12条の6第4号に該当するおそれが大きいとされています。","r":[["貸金業法","12の6"]]},"3":{"t":true,"w":"貸金業法第48条第1項第1号の2。","r":[["貸金業法","12の6"],["貸金業法","48"]]},"4":{"t":true,"w":"貸金業法第12条の8第1項。","r":[["貸金業法","12の8"]]}}},"03-17":{"s":"受取証書（貸金業法第18条）を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"施行規則第15条第1項。","r":[["貸金業法施行規則","15"]]},"2":{"t":true,"w":"貸金業法第18条第2項。","r":[["貸金業法","18"]]},"3":{"t":false,"p":"電磁的方法で提供するための承諾は、「口頭」ではなく「書面又は電磁的方法」で得る必要があります（公式正答による）。","w":"貸金業法第18条第4項（政令で定めるところにより承諾を得る）。契約締結前の書面については施行令第3条の2の5第1項が「書面又は電磁的方法による承諾」と定めています。","r":[["貸金業法","18"],["貸金業法施行令","3の2の5"]]},"4":{"t":true,"w":"施行規則第15条第3項（現行の表記は「日本産業規格」）。","r":[["貸金業法施行規則","15"]]}}},"03-18":{"s":"契約締結前の書面の記載事項を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"施行規則第12条の2第1項第1号イ。","r":[["貸金業法施行規則","12の2"]]},"2":{"t":false,"p":"契約の相手方となろうとする者の氏名及び住所は、契約締結前の書面の記載事項に「含まれません」（契約締結時の書面の記載事項です）。","w":"施行規則第12条の2第1項第1号、第13条第1項第1号ロ。","r":[["貸金業法施行規則","12の2"],["貸金業法施行規則","13"]]},"3":{"t":true,"w":"施行規則第12条の2第1項第1号ロ。","r":[["貸金業法施行規則","12の2"]]},"4":{"t":true,"w":"施行規則第12条の2第1項第1号ホ。","r":[["貸金業法施行規則","12の2"]]}}},"03-19":{"s":"極度方式貸付けの書面を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"施行規則第13条第1項第1号イ（利息制限法の上限を超えない極度方式貸付けでは登録番号の記載を省略可）。","r":[["貸金業法施行規則","13"]]},"2":{"t":false,"p":"相手方の承諾を得れば、契約締結時の書面の記載事項を電磁的方法で提供「できます」。","w":"貸金業法第17条第7項。","r":[["貸金業法","17"]]},"3":{"t":true,"w":"施行規則第13条第1項第1号ロ。","r":[["貸金業法施行規則","13"]]},"4":{"t":true,"w":"貸金業法第18条第3項。","r":[["貸金業法","18"]]}}},"03-20":{"s":"極度方式基本契約の調査と措置を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"期間の末日の残高の合計額が10万円以下（5万円）なら、調査は「不要」です。","w":"施行規則第10条の25第3項第1号。","r":[["貸金業法施行規則","10の25"]]},"2":{"t":true,"w":"貸金業法第13条第5項。","r":[["貸金業法","13"]]},"3":{"t":true,"w":"貸金業法第13条の4。","r":[["貸金業法","13の4"]]},"4":{"t":true,"w":"貸金業法第13条の3第4項。","r":[["貸金業法","13の3"]]}}},"03-21":{"s":"個人過剰貸付契約から除かれる契約を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"自動車購入資金の貸付けが除かれるのは、自動車の所有権を貸金業者が取得し、又は自動車が譲渡により担保の目的となっているものに「限られます」。","w":"施行規則第10条の21第1項第3号。","r":[["貸金業法施行規則","10の21"]]},"2":{"t":true,"w":"施行規則第10条の21第1項第1号。","r":[["貸金業法施行規則","10の21"]]},"3":{"t":true,"w":"施行規則第10条の21第1項第2号。","r":[["貸金業法施行規則","10の21"]]},"4":{"t":true,"w":"施行規則第10条の21第1項第4号。","r":[["貸金業法施行規則","10の21"]]}}},"03-22":{"s":"返済能力の調査と過剰貸付けの禁止を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"例外契約（個人顧客の利益の保護に支障を生ずることがない契約）の残高は、個人顧客合算額に「加算されます」。合算額から除かれるのは住宅資金貸付契約等（除外契約）の残高です。","w":"貸金業法第13条の2第2項（住宅資金貸付契約等に係る貸付けの残高を除く）。","r":[["貸金業法","13の2"]]},"2":{"t":true,"w":"貸金業法第13条第2項。","r":[["貸金業法","13"]]},"3":{"t":true,"w":"貸金業法第13条第4項。","r":[["貸金業法","13"]]},"4":{"t":true,"w":"貸金業法第48条第1項第1号の4。","r":[["貸金業法","13"],["貸金業法","48"]]}}},"03-23":{"s":"利息制限法を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"利息制限法第7条第1項。","r":[["利息制限法","7"]]},"2":{"t":false,"p":"営業的でない金銭消費貸借の賠償額の予定の上限は、第1条の率の「1.2倍」ではなく「1.46倍」です。","w":"利息制限法第4条第1項。","r":[["利息制限法","4"]]},"3":{"t":true,"w":"利息制限法第8条第1項。","r":[["利息制限法","8"]]},"4":{"t":true,"w":"利息制限法第3条。","r":[["利息制限法","3"]]}}},"03-24":{"s":"保証等に係る求償権等の行使の規制（貸金業法第24条の2・第24条の4）を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"貸金業法第24条の2第3項。","r":[["貸金業法","24の2"]]},"2":{"t":true,"w":"貸金業法第48条第1項第7号（取立て制限者のうち暴力団員等であることを知りながら保証契約を締結した者）。","r":[["貸金業法","24の2"],["貸金業法","48"]]},"3":{"t":false,"p":"密接な関係を有する保証業者と保証契約を締結したときは、その保証業者が取立て規制に違反したり罪を犯したりしないよう、相当の注意を払う義務を「負います」。","w":"貸金業法第24条の2第4項。","r":[["貸金業法","24の2"]]},"4":{"t":true,"w":"貸金業法第24条の4第1項。","r":[["貸金業法","24の4"]]}}},"03-25":{"s":"監督指針の不祥事件への対応（Ⅱ－２－８）と業務の透明性の確保（Ⅱ－３）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"資金需要者等から告訴、告発され又は検挙された行為も、不祥事件に「含まれます」。","w":"監督指針Ⅱ－２－８（不祥事件の定義）。","r":[]},"2":{"t":true,"w":"監督指針Ⅱ－２－８（１）①。","r":[]},"3":{"t":true,"w":"監督指針Ⅱ－２－８（２）。","r":[]},"4":{"t":true,"w":"監督指針Ⅱ－３（１）②。","r":[]}}},"03-26":{"s":"指定信用情報機関を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"貸金業法第41条の13第1項第1号。","r":[["貸金業法","41の13"]]},"2":{"t":true,"w":"貸金業法第41条の13第1項第5号、施行規則第28条第2項第1号。","r":[["貸金業法","41の13"],["貸金業法施行規則","28"]]},"3":{"t":false,"p":"内閣総理大臣の承認を受けて委託できるのは、信用情報提供等業務の「全部」ではなく「一部」です。","w":"貸金業法第41条の19第1項。","r":[["貸金業法","41の19"]]},"4":{"t":true,"w":"貸金業法第41条の25。","r":[["貸金業法","41の25"]]}}},"03-27":{"s":"監督指針Ⅱ－２－２０（債権譲渡等）を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"監督指針Ⅱ－２－２０（１）①。","r":[]},"2":{"t":true,"w":"監督指針Ⅱ－２－２０（１）②。","r":[["貸金業法","24"]]},"3":{"t":false,"p":"着眼点は、債権の保全・回収に重点を置いた契約かどうかではなく、債務者等からの問合せや取引履歴の開示請求に適切に対応するための規定や、「債務者等の保護の確保に努めるための規定」が置かれているかです。","w":"監督指針Ⅱ－２－２０（１）④。","r":[]},"4":{"t":true,"w":"監督指針Ⅱ－２－２０（１）③。","r":[]}}},"03-28":{"s":"日本貸金業協会の広告に関する規則・細則を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"自主規制基本規則第45条第1項。","r":[]},"2":{"t":false,"p":"ラジオＣＭについても放送時間帯の留意事項が「定められています」（午後10時から午前3時までの放送を行わない）。","w":"貸金業者の広告に関する細則（ラジオＣＭに関する遵守事項等）⑶。","r":[]},"3":{"t":true,"w":"貸金業者の広告に関する細則Ⅴ．２．⑴（屋外広告看板等に関する留意事項）。","r":[]},"4":{"t":true,"w":"貸金業者の広告に関する細則（自社ホームページの広告：メインのページに啓発文言などを表示）。","r":[]}}},"03-29":{"s":"日本貸金業協会の自主規制規則の取引履歴の開示を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"弁護士から債務整理等に係る受任の通知を受ける方法も、取引履歴の開示について委任を受けたことの確認方法に「含まれます」。この場合、請求を拒むことはできません。","w":"自主規制基本規則（取引履歴の開示に関する規則）：弁護士等から、委任を受けた旨と属性情報が十分に記載された通知（債務整理等に係る受任の通知を含む）を受ける方法。","r":[]},"2":{"t":true,"w":"自主規制基本規則（取引履歴の開示に関する規則）：本人確認書類（写しを含む）の提示を求めることもできます（現行の規則では犯罪収益移転防止法施行規則第7条の本人確認書類）。","r":[]},"3":{"t":true,"w":"自主規制基本規則（取引履歴の開示に関する規則）。確認方法の細目は公式正答によります。","r":[]},"4":{"t":true,"w":"自主規制基本規則第63条第2項。","r":[]}}},"03-30":{"s":"期間の計算と期限を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"民法第140条（初日不算入なので3月1日から起算）、第143条第2項（起算日に応当する日の前日に満了）により、翌年2月28日が返済期限です。","r":[["民法","140"],["民法","143"]]},"2":{"t":false,"p":"初日（6月1日）は算入しないので6月2日から起算し、返済期限は「6月5日」ではなく「6月6日」です。","w":"民法第140条、第141条。","r":[["民法","140"]]},"3":{"t":false,"p":"返還の時期を定めなかったときは、貸主は「相当の期間を定めて」返還を催告できます。直ちに返還を求めることはできません。","w":"民法第591条第1項。","r":[["民法","591"]]},"4":{"t":false,"p":"期限の利益は放棄「できます」。","w":"民法第136条第2項。","r":[["民法","136"]]}}},"03-31":{"s":"保証を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"保証契約は、口頭の合意ではなく「書面」（又は電磁的記録）でしなければ効力を生じません。","w":"民法第446条第2項・第3項。","r":[["民法","446"]]},"2":{"t":false,"p":"主たる債権が譲渡されると保証債務もこれに伴って移るので、譲渡人Ａは保証人Ｃに履行を請求「できません」（請求できるのは譲受人Ｄです。公式正答による）。","w":"保証債務の随伴性による考え方です（判例の考え方による）。","r":[]},"3":{"t":true,"w":"民法第452条（催告の抗弁）。","r":[["民法","452"]]},"4":{"t":false,"p":"連帯保証かどうかにかかわらず、保証債務は主たる債務の「利息」も包含するので、Ｃに請求「できます」。","w":"民法第447条第1項。","r":[["民法","447"]]}}},"03-32":{"s":"相殺を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"破産法第67条第1項（破産手続開始の時に破産者に対して債務を負担していれば、破産手続によらないで相殺できます）。","r":[["破産法","67"]]},"2":{"t":false,"p":"相殺の効力は、意思表示をした時点ではなく、双方の債務が互いに相殺に適するようになった時に「さかのぼって」生じます。","w":"民法第506条第2項。","r":[["民法","506"]]},"3":{"t":false,"p":"自働債権（貸金債権）が弁済期にあれば、受働債権（売掛金債務）の期限の利益を放棄して相殺「できます」。","w":"民法第505条第1項、第136条第2項。","r":[["民法","505"],["民法","136"]]},"4":{"t":false,"p":"差押え「前」に取得した債権による相殺は、差押債権者に対抗「できます」。取得時期の先後は問題になります。","w":"民法第511条第1項。","r":[["民法","511"]]}}},"03-33":{"s":"相続の承認・限定承認・放棄を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"相続の承認は、熟慮期間（3か月）内であっても撤回「できません」。","w":"民法第919条第1項。","r":[["民法","919"]]},"2":{"t":true,"w":"民法第922条。","r":[["民法","922"]]},"3":{"t":false,"p":"相続人が数人あるときは、限定承認は「共同相続人の全員が共同して」のみできます。","w":"民法第923条。","r":[["民法","923"]]},"4":{"t":false,"p":"相続の放棄は、他の相続人への意思表示ではなく、「家庭裁判所に申述」してします。","w":"民法第938条、第939条。","r":[["民法","938"],["民法","939"]]}}},"03-34":{"s":"約束手形を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"満期の記載がない約束手形も無効ではなく、「一覧払」のものとみなされます。","w":"手形法第76条第2項。","r":[["手形法","76"]]},"2":{"t":false,"p":"支払約束は「単純な」ものでなければならず、条件を付けた約束手形は手形「自体が無効」です（公式正答による）。","w":"手形法第75条第2号、第76条第1項。","r":[["手形法","75"],["手形法","76"]]},"3":{"t":false,"p":"支払呈示の期間は支払期日だけでなく「これに次ぐ2取引日内」も含み、その後も振出人に対する権利が直ちに消えるわけではありません（公式正答による）。","w":"手形法第38条第1項（約束手形には第77条で準用）。","r":[["手形法","38"],["手形法","77"]]},"4":{"t":true,"w":"手形法第14条第1項（約束手形には第77条第1項第1号で準用）。","r":[["手形法","14"],["手形法","77"]]}}},"03-35":{"s":"民事再生手続を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"強制執行が中止されるのは再生手続開始の「決定」があったときで、申立ての通知を受けただけでは、原則として強制執行は「妨げられません」。","w":"民事再生法第39条第1項。","r":[["民事再生法","39"]]},"2":{"t":true,"w":"民事再生法第53条第1項・第2項（抵当権は別除権）。","r":[["民事再生法","53"]]},"3":{"t":false,"p":"可決には、出席等した議決権者の過半数の同意と、議決権総額の2分の1以上の議決権を有する者の同意が必要です。3分の1の議決権を有する者が反対しても、他の全員が同意すれば可決「されます」。","w":"民事再生法第172条の3第1項。","r":[["民事再生法","172の3"]]},"4":{"t":false,"p":"再生計画認可の決定が確定すると再生債権者表の記載に基づいて強制執行ができるので、別途債務名義を取得する必要は「ありません」。","w":"民事再生法第180条第2項・第3項。","r":[["民事再生法","180"]]}}},"03-36":{"s":"強制執行と破産手続を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"強制執行は確定判決に「限らず」、仮執行宣言付判決、仮執行宣言付支払督促、執行証書などの債務名義によってもできます。","w":"民事執行法第22条。","r":[["民事執行法","22"]]},"2":{"t":false,"p":"給与債権は「4分の3」が差押禁止なので、差し押さえられるのは「4分の1」です。","w":"民事執行法第152条第1項第2号。","r":[["民事執行法","152"]]},"3":{"t":true,"w":"民事執行法第160条。","r":[["民事執行法","160"]]},"4":{"t":false,"p":"破産手続開始の決定があると、破産財団に属する財産に対する強制執行は「効力を失います」。","w":"破産法第42条第1項・第2項。","r":[["破産法","42"]]}}},"03-37":{"s":"強制執行と特定公正証書の制限を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"執行証書に基づく強制執行にも、執行文の付与が「必要」です。","w":"民事執行法第25条（強制執行は執行文の付された債務名義の正本に基づいて実施）。","r":[["民事執行法","25"]]},"2":{"t":false,"p":"強制執行の前に仮差押えをしなければならないという定めは「ありません」（公式正答による）。","w":"民事執行法第22条・第25条。","r":[["民事執行法","22"]]},"3":{"t":false,"p":"債務者が所有する動産に対しても強制執行（動産執行）を申し立てることが「できます」。","w":"民事執行法第122条第1項。","r":[["民事執行法","122"]]},"4":{"t":true,"w":"貸金業法第20条第1項。","r":[["貸金業法","20"]]}}},"03-38":{"s":"未成年者との契約を問う問題です。適切でないのは④です。","law":"④は出題時の民法の婚姻による成年擬制（旧第753条）による記述です。現行法では成年年齢は18歳で（第4条）、婚姻も18歳にならなければできない（第731条）ため、婚姻した未成年者は生じません。","items":{"1":{"t":true,"w":"民法第824条（親権者は子の財産に関する法律行為について子を代表する）。","r":[["民法","824"]]},"2":{"t":true,"w":"民法第5条第1項・第2項。","r":[["民法","5"]]},"3":{"t":true,"w":"民法第21条。","r":[["民法","21"]]},"4":{"t":false,"p":"出題時の民法では、婚姻した未成年者は成年に達したものとみなされたため、親権者は契約を取り消すことが「できません」でした（旧第753条、公式正答による）。","w":"現行の民法第4条、第731条。","r":[["民法","4"],["民法","731"]]}}},"03-39":{"s":"債権証書の返還・期限・債務不履行を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"貸金業法第22条（返還義務は全部の弁済を受けた場合）。","r":[["貸金業法","22"]]},"2":{"t":false,"p":"全部の弁済を受けたときは、請求がなくても「遅滞なく」債権証書を返還しなければなりません。","w":"貸金業法第22条。","r":[["貸金業法","22"]]},"3":{"t":true,"w":"民法第135条第1項。","r":[["民法","135"]]},"4":{"t":true,"w":"民法第412条第1項、第415条第1項。","r":[["民法","412"],["民法","415"]]}}},"03-40":{"s":"利息に関する法規制を問う問題です。公式正答は①（適切でない）です。","law":"2020年4月の改正で、民法の法定利率は年5％から年3％（3年ごとに見直し）に改められ（第404条）、商法の商事法定利率（年6％。旧第514条）は廃止されました。現行法では②③は適切でありません。","items":{"1":{"t":false,"p":"利息制限法では、上限を超える利息の約定は「超過部分」が無効になるだけで、消費貸借契約自体は無効に「なりません」。","w":"利息制限法第1条。","r":[["利息制限法","1"]]},"2":{"t":true,"now":false,"p":"現行法では、商事法定利率（年6％）は「廃止」され、商行為による債務にも民法の法定利率が適用されます。","w":"出題時の商法（旧第514条）による記述です（公式正答による）。現行の商法第514条は削除されています。","r":[["商法","514"],["民法","404"]]},"3":{"t":true,"now":false,"p":"現行法の法定利率は、「年5％」ではなく「年3％」（3年ごとに見直し）です。","w":"出題時の民法（旧第404条）による記述です（公式正答による）。現行の民法第404条第2項・第3項。","r":[["民法","404"]]},"4":{"t":true,"w":"貸金業法第42条第1項。","r":[["貸金業法","42"]]}}},"03-41":{"s":"債権譲渡を問う問題です。公式正答は②（適切でない）です。","law":"この回の基準日は2020年4月の民法改正の前です。④の異議をとどめない承諾の規定（旧第468条第1項）は削除され、現行の第468条第1項では、債務者は対抗要件具備時までに譲渡人に対して生じた事由を譲受人に対抗できます。①の譲渡禁止特約も、現行の第466条第2項では譲渡制限の意思表示がされても譲渡は有効とされています。","items":{"1":{"t":true,"w":"出題時の民法（旧第466条）による記述です。現行の第466条第2項・第3項を参照。","r":[["民法","466"]]},"2":{"t":false,"p":"債務者への通知は、「譲受人」ではなく「譲渡人」がしなければ対抗できません。","w":"民法第467条第1項。","r":[["民法","467"]]},"3":{"t":true,"w":"民法第467条第2項。","r":[["民法","467"]]},"4":{"t":true,"now":false,"p":"現行法では、異議をとどめない承諾による抗弁の切断の規定はなく、債務者は対抗要件具備時までに生じた事由を譲受人に対抗「できます」。","w":"出題時の民法（旧第468条第1項）による記述です（公式正答による）。現行の民法第468条第1項。","r":[["民法","468"]]}}},"03-42":{"s":"民事訴訟手続を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"民事訴訟法第134条第1項。","r":[["民事訴訟法","134"]]},"2":{"t":true,"w":"民事訴訟法第158条。","r":[["民事訴訟法","158"]]},"3":{"t":false,"p":"控訴期間は、判決書の送達を受けた日から「30日以内」ではなく「2週間」の不変期間内です。","w":"民事訴訟法第285条。","r":[["民事訴訟法","285"]]},"4":{"t":true,"w":"民事執行法第22条第1号。","r":[["民事執行法","22"]]}}},"03-43":{"s":"総量規制の例外となる契約を問う問題です。公式正答はａｃです。","law":"現行の施行規則では、売却予定の不動産の売却代金により弁済される貸付け（ｃ）は、例外（第10条の23）ではなく、総量規制の対象から除かれる契約（第10条の21第1項第7号）に位置づけられています。","items":{"a":{"t":true,"w":"施行規則第10条の23第1項第4号。","r":[["貸金業法施行規則","10の23"]]},"b":{"t":false,"p":"借換えの例外に当たるには、1か月の負担が既存債務の1か月の負担を「上回らない」ことが必要です。","w":"施行規則第10条の23第1項第1号イ。","r":[["貸金業法施行規則","10の23"]]},"c":{"t":true,"now":false,"p":"現行の施行規則では、この契約は例外（第10条の23）ではなく除外（第10条の21第1項第7号）の契約です。","w":"公式正答では例外の契約とされています。現行の施行規則第10条の21第1項第7号。","r":[["貸金業法施行規則","10の21"]]},"d":{"t":false,"p":"個人顧客の居宅を担保とする貸付けは、例外にも除外にも「該当しません」（不動産担保の除外でも居宅は除かれています）。","w":"施行規則第10条の21第1項第6号。","r":[["貸金業法施行規則","10の21"]]}}},"03-44":{"s":"景品表示法の不当表示を問う問題です。公式正答はｂｃです。","law":"出題時の景品表示法では、資料の提出の要求や措置命令などは公正取引委員会が行うとされていました（公式正答による）。現行法ではこれらは内閣総理大臣が行います。不当な表示の禁止は現行の第5条、措置命令は第7条です。","items":{"a":{"t":false,"p":"インターネット上のウェブサイトで行う表示も、景品表示法上の表示に「該当します」（公式正答による）。","w":"景品表示法第2条第4項（表示は内閣総理大臣が指定）。","r":[["景品表示法","2"]]},"b":{"t":true,"w":"現行の景品表示法第5条第1号（優良誤認表示）。現行の条文では「一般消費者による自主的かつ合理的な選択を阻害するおそれ」と表現されています。","r":[["景品表示法","5"]]},"c":{"t":true,"now":false,"p":"現行法では、資料の提出を求めるのは「公正取引委員会」ではなく「内閣総理大臣」です。","w":"出題時の景品表示法による記述です（公式正答による）。現行の第7条第2項。","r":[["景品表示法","7"]]},"d":{"t":false,"p":"違反行為が既になくなっている場合でも、再発防止に必要な事項などを命ずることが「できます」。","w":"現行の景品表示法第7条第1項後段。","r":[["景品表示法","7"]]}}},"03-45":{"s":"個人情報保護法を問う問題です。適切なのは④です。","law":"②について、出題時は取り扱う個人の数が5,000以下の事業者は個人情報取扱事業者から除かれていましたが、2017年施行の改正でこの除外は廃止されました。③の「主務大臣」の権限も、現在は個人情報保護委員会が持っています。","items":{"1":{"t":false,"p":"日本に居住する外国人に関する情報も、生存する個人に関する情報として個人情報に「該当します」。","w":"個人情報保護法第2条第1項。","r":[["個人情報保護法","2"]]},"2":{"t":false,"p":"出題時の法令では、取り扱う個人の数が5,000以下の事業者は個人情報取扱事業者から除かれていました（公式正答による）。","w":"現行法では5,000人の基準は廃止され、個人情報データベース等を事業の用に供している者が個人情報取扱事業者です（第16条第2項）。","r":[["個人情報保護法","16"]]},"3":{"t":false,"p":"本人に損害を賠償しても、安全管理措置の義務違反について勧告を受けないことにはなり「ません」（公式正答による）。","w":"個人情報保護法第23条（安全管理措置）。現行法で勧告を行うのは個人情報保護委員会です。","r":[["個人情報保護法","23"]]},"4":{"t":true,"w":"個人情報保護法第22条。","r":[["個人情報保護法","22"]]}}},"03-46":{"s":"帳簿と帳簿の閲覧・謄写を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"貸金業法第19条の2。","r":[["貸金業法","19の2"]]},"2":{"t":true,"w":"施行規則第17条の2第1項第3号。","r":[["貸金業法施行規則","17の2"]]},"3":{"t":true,"w":"貸金業法第49条第6号。","r":[["貸金業法","49"]]},"4":{"t":false,"p":"帳簿には、債務者等その他の者との交渉の経過の記録も記載する必要が「あります」。","w":"施行規則第16条第1項第7号。","r":[["貸金業法施行規則","16"]]}}},"03-47":{"s":"金融分野ガイドラインの第三者提供の制限を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"公式正答では適切です（第三者の定義）。","r":[["個人情報保護法","27"]]},"2":{"t":true,"w":"金融分野ガイドライン第12条第1項。","r":[["個人情報保護法","27"]]},"3":{"t":false,"p":"本人の同意を得るのは、会員企業「のいずれか」ではなく、個人信用情報機関に個人データを「提供する」個人情報取扱事業者です。","w":"金融分野ガイドライン第12条（個人信用情報機関に対する提供）。","r":[["個人情報保護法","27"]]},"4":{"t":true,"w":"公式正答では適切です。現行の個人情報保護法第27条第2項（オプトアウト）。","r":[["個人情報保護法","27"]]}}},"03-48":{"s":"企業会計原則の損益計算書の区分の穴埋め問題です。正しいのは④です（ア営業損益・イ経常損益・ウ営業利益・エ経常利益）。","items":{"1":{"t":false,"p":"イは「特別損益」ではなく「経常損益」、エは「当期純利益」ではなく「経常利益」です。"},"2":{"t":false,"p":"アは「売上高」ではなく「営業損益」、イは「経常損益」、ウは「売上原価」ではなく「営業利益」です。"},"3":{"t":false,"p":"アは「営業損益」、ウは「営業利益」、エは「経常利益」です。"},"4":{"t":true,"w":"企業会計原則 第二 損益計算書原則 二Ａ・Ｂ。"}}},"03-49":{"s":"企業会計原則の貸借対照表原則を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"企業会計原則 貸借対照表原則 四（一）Ａ。","r":[]},"2":{"t":true,"w":"企業会計原則 貸借対照表原則 四（二）Ａ。","r":[]},"3":{"t":false,"p":"営業権、特許権及び商標権は、「投資その他の資産」ではなく「無形固定資産」に属します。","w":"企業会計原則 貸借対照表原則 四（一）Ｂ。","r":[]},"4":{"t":true,"w":"企業会計原則 貸借対照表原則 四（二）Ｂ。","r":[]}}},"03-50":{"s":"返済能力の調査に関する記録（施行規則第10条の18）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"契約締結前の書面又はその写しは、返済能力の調査に関する記録に「含まれません」。","w":"施行規則第10条の18第1項各号（契約年月日、書面等の提出を受けた年月日、資力・借入れの状況の調査結果、調査に使用した書面など）。","r":[["貸金業法施行規則","10の18"]]},"2":{"t":true,"w":"施行規則第10条の18第1項第3号。","r":[["貸金業法施行規則","10の18"]]},"3":{"t":true,"w":"施行規則第10条の18第1項第4号。","r":[["貸金業法施行規則","10の18"]]},"4":{"t":true,"w":"施行規則第10条の18第1項第2号。","r":[["貸金業法施行規則","10の18"]]}}},"04-01":{"s":"登録拒否の基準となる純資産額を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"施行規則第5条の9第1項第1号。","r":[["貸金業法","6"],["貸金業法施行規則","5の9"]]},"2":{"t":false,"p":"純資産額の要件は個人にも適用され、5,000万円に満たないことは拒否事由に「該当します」。","w":"貸金業法第6条第1項第14号、施行令第3条の2（5,000万円）。個人の純資産額の計算は施行規則第5条の9第1項第2号。","r":[["貸金業法","6"],["貸金業法施行令","3の2"],["貸金業法施行規則","5の9"]]},"3":{"t":false,"p":"記述の要件を満たす非営利の法人（非営利特例対象法人）は、純資産額が「500万円以上」であればよく、2,000万円なら拒否事由に「該当しません」。","w":"施行規則第5条の6第2項第2号（出題時の条番号は第5条の3）。","r":[["貸金業法施行規則","5の6"]]},"4":{"t":false,"p":"純資産額が最低純資産額に満たなくなった場合は、業務停止だけでなく、登録の取消しの対象にも「なります」。","w":"貸金業法第24条の6の4第1項第1号（第6条第1項第14号に該当することとなったとき）。","r":[["貸金業法","24の6の4"]]}}},"04-02":{"s":"廃業等の届出と登録換えを問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"合併により消滅した場合、登録は「効力を失い」、存続する法人に承継「されません」。","w":"貸金業法第10条第1項第2号・第2項。","r":[["貸金業法","10"]]},"2":{"t":true,"w":"貸金業法第10条第1項第5号。","r":[["貸金業法","10"]]},"3":{"t":false,"p":"2以上の都道府県に営業所等を有することとなった場合は、他の都道府県知事ではなく「内閣総理大臣」の登録を受けます（登録換え）。","w":"貸金業法第3条第1項、第7条第3号。","r":[["貸金業法","3"],["貸金業法","7"]]},"4":{"t":false,"p":"相続人が引き続き貸金業を営めるのは、死亡後「1年間」ではなく「60日間」です。","w":"貸金業法第10条第3項。","r":[["貸金業法","10"]]}}},"04-03":{"s":"登録の更新を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"1つの都道府県内にのみ営業所等を設置している貸金業者の登録・更新は、「財務局長」ではなく「都道府県知事」に申請します。","w":"貸金業法第3条第1項。","r":[["貸金業法","3"]]},"2":{"t":false,"p":"内閣総理大臣の登録の更新を受けようとする者は、手数料を納める必要が「あります」。","w":"貸金業法第3条第3項、施行令第2条第1項（15万円）。","r":[["貸金業法","3"],["貸金業法施行令","2"]]},"3":{"t":false,"p":"更新の申請期限は、有効期間満了の日の「1か月前」ではなく「2月前」までです。","w":"施行規則第5条。","r":[["貸金業法施行規則","5"]]},"4":{"t":true,"w":"貸金業法第24条の6の5第1項第2号。","r":[["貸金業法","24の6の5"]]}}},"04-04":{"s":"貸付条件等の掲示（貸金業法第14条）を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"営業所等に置かれる貸金業務取扱主任者の氏名も、掲示する必要が「あります」。","w":"貸金業法第14条第1項第4号。","r":[["貸金業法","14"]]},"2":{"t":false,"p":"貸付けの利率は、年率を百分率で「少なくとも小数点以下一位まで」表示します。","w":"施行規則第11条第4項。","r":[["貸金業法施行規則","11"]]},"3":{"t":true,"w":"施行規則第11条第5項。","r":[["貸金業法施行規則","11"]]},"4":{"t":false,"p":"第14条の違反は、業務改善命令だけでなく、業務の全部又は一部の停止や登録の取消しの対象にも「なります」。","w":"貸金業法第24条の6の4第1項第2号（罰則は第49条第4号）。","r":[["貸金業法","24の6の4"],["貸金業法","49"]]}}},"04-05":{"s":"保証契約に関して交付すべき書面を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"概要書面と詳細書面は、「いずれか一方」ではなく「2種類の書面を同時に」交付します。","w":"施行規則第12条の2第7項。","r":[["貸金業法施行規則","12の2"]]},"2":{"t":false,"p":"保証契約における契約締結時の書面の記載事項は、契約締結前の書面と「全く同一」ではありません（保証契約の契約年月日などが加わります）。","w":"貸金業法第17条第3項、施行規則第13条第6項。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"3":{"t":false,"p":"保証契約について物的担保を供させたときは、保証人からの請求の有無にかかわらず、担保の内容を記載した書面を交付「しなければなりません」。","w":"施行規則第13条第7項第1号ロ（第12条の2第6項第9号）。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"4":{"t":true,"w":"貸金業法第17条第3項・第4項。","r":[["貸金業法","17"]]}}},"04-06":{"s":"個人過剰貸付契約から除かれる契約（施行規則第10条の21）を問う問題です。該当するのはｃｄです。","items":{"a":{"t":false,"p":"売却予定の不動産の売却代金で弁済される貸付けは、売却により個人顧客の生活に支障を来すと認められる場合を「除く」ものです。支障を来すものは該当しません。","w":"施行規則第10条の21第1項第7号。","r":[["貸金業法施行規則","10の21"]]},"b":{"t":false,"p":"事業を営む個人顧客への貸付けの例外（第10条の23第1項第4号）は、返済能力を「超えない」と認められるものに限られます。また、これは除外（第10条の21）ではなく例外の契約です。","w":"施行規則第10条の23第1項第4号。","r":[["貸金業法施行規則","10の23"]]},"c":{"t":true,"w":"施行規則第10条の21第1項第1号。","r":[["貸金業法施行規則","10の21"]]},"d":{"t":true,"w":"施行規則第10条の21第1項第3号。","r":[["貸金業法施行規則","10の21"]]}}},"04-07":{"s":"3か月ごとの調査（貸金業法第13条の3第2項）が必要な場合を問う問題です。公式正答は②です。","law":"現行の施行規則第10条の25第3項第1号では、期間の末日の極度方式貸付けの残高の合計額（他の極度方式基本契約の分を含む）が「10万円以下」なら調査は不要です。②は3万円＋7万円＝10万円なので、現行法では調査は不要となります（出題時の基準は取り込んだ資料で確認できません）。","items":{"1":{"t":false,"p":"残高の合計額が10万円以下（5万円）なので、調査は「不要」です。","w":"施行規則第10条の25第3項第1号。","r":[["貸金業法施行規則","10の25"]]},"2":{"t":true,"now":false,"p":"現行法では、残高の合計額が10万円「以下」なら調査は不要で、3万円＋7万円＝10万円はこれに当たります。","w":"公式正答では調査が必要とされています。現行の施行規則第10条の25第3項第1号。","r":[["貸金業法施行規則","10の25"]]},"3":{"t":false,"p":"貸金業者を債権者とする金銭の貸借の媒介に係る契約は、調査は「不要」です。","w":"施行規則第10条の25第3項第4号。","r":[["貸金業法施行規則","10の25"]]},"4":{"t":false,"p":"期間の末日に新たな極度方式貸付けを停止する措置が講じられている場合は、調査は「不要」です。","w":"施行規則第10条の25第3項第2号・第3号。","r":[["貸金業法施行規則","10の25"]]}}},"04-08":{"s":"債権譲渡等の規制（貸金業法第24条）を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"施行規則第21条第1項第3号（保証契約を締結したときは第17条第3項の事項）。","r":[["貸金業法","24"],["貸金業法施行規則","21"]]},"2":{"t":false,"p":"通知は書面で行い、書面に代えられるのは譲受人の承諾を得た「電磁的方法」です。「口頭」で告げる方法は認められていません。","w":"施行規則第21条第3項・第4項。","r":[["貸金業法施行規則","21"]]},"3":{"t":false,"p":"通知では、第12条の7、第16条の2第3項など、譲受人に適用される「具体的な規定」の適用がある旨を明らかにします（公式正答による）。","w":"貸金業法第24条第1項（適用される規定が列挙されています）。","r":[["貸金業法","24"]]},"4":{"t":false,"p":"譲受人が貸金業者であっても、通知する義務を「負います」。","w":"貸金業法第24条第1項には、譲受人が貸金業者である場合の例外はありません。","r":[["貸金業法","24"]]}}},"04-09":{"s":"受取証書と債権証書の返還を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"受取証書には、受領年月日だけでなく「契約年月日」も記載する必要が「あります」。","w":"貸金業法第18条第1項第2号・第5号。","r":[["貸金業法","18"]]},"2":{"t":false,"p":"利息制限法の上限を超える利息の約定は、任意に弁済して受取証書を交付しても有効に「なりません」（超過部分は無効です）。","w":"利息制限法第1条。貸金業者による超過利息の受領は禁止されています（貸金業法第12条の8第4項）。","r":[["利息制限法","1"],["貸金業法","12の8"]]},"3":{"t":false,"p":"口座への払込みによる弁済でも、弁済をした者から請求があれば受取証書を交付「しなければなりません」。","w":"貸金業法第18条第2項。","r":[["貸金業法","18"]]},"4":{"t":true,"w":"貸金業法第22条：全部の弁済を受けたときは、遅滞なく、債権の証書を「その弁済をした者」に返還します。","r":[["貸金業法","22"]]}}},"04-10":{"s":"利息制限法を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"元本50万円の上限金利は、「年2割」ではなく「年1割8分」です。","w":"利息制限法第1条第2号。","r":[["利息制限法","1"]]},"2":{"t":false,"p":"1万円以下の弁済の際のATM利用料は、政令で定める額（現行110円、出題時105円）までなら利息とみなされ「ません」。","w":"利息制限法第6条第2項第3号、施行令第2条第1号。","r":[["利息制限法","6"],["利息制限法施行令","2"]]},"3":{"t":true,"w":"利息制限法第6条第2項第2号（公の機関が行う手続に関してその機関に支払うべきもの）。公証人手数料をこれに当たるとする点は公式正答によります。","r":[["利息制限法","6"]]},"4":{"t":false,"p":"営業的金銭消費貸借の賠償額の予定の上限は、第1条の率の「2倍」ではなく「年2割」です。","w":"利息制限法第4条第1項、第7条第1項。","r":[["利息制限法","4"],["利息制限法","7"]]}}},"04-11":{"s":"上限金利を超える約定の効果（利息制限法・貸金業法・出資法）を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"利息制限法では、無効になるのは上限（元本100万円なら年1割5分）を「超える部分」で、契約自体は無効に「なりません」。","w":"利息制限法第1条第3号。","r":[["利息制限法","1"]]},"2":{"t":true,"w":"貸金業法第42条第1項（年109.5％を超える利息の契約をした消費貸借の契約は無効）。","r":[["貸金業法","42"]]},"3":{"t":false,"p":"利息制限法の上限（年1割5分）を超える利息の契約は貸金業法第12条の8第1項に違反し、登録の取消しなどの対象と「なり得ます」。","w":"貸金業法第12条の8第1項、第24条の6の4第1項第2号。","r":[["貸金業法","12の8"],["貸金業法","24の6の4"]]},"4":{"t":false,"p":"出資法で刑事罰の対象となるのは、業として年20％を「超える」利息の契約です。年20％ちょうどは対象に「なりません」。","w":"出資法第5条第2項。","r":[["出資法","5"]]}}},"04-12":{"s":"禁止行為・保険契約の制限・相談助言を問う問題です。適切なのはａｂｄの3個です。","items":{"a":{"t":true,"w":"貸金業法第12条の6第1号、第48条第1項第1号の2。","r":[["貸金業法","12の6"],["貸金業法","48"]]},"b":{"t":true,"w":"自主規制基本規則（法第12条の6に係る禁止行為に関する規則）：生命保険、損害保険等の保険金により貸付金の弁済を要求すること。","r":[]},"c":{"t":false,"p":"禁止されているのは、自殺による死亡を保険事故と「する」保険契約です（住宅資金貸付契約などを除く）。自殺を保険事故と「しない」保険契約が住宅資金貸付契約などに限られるわけではありません。","w":"貸金業法第12条の7。","r":[["貸金業法","12の7"]]},"d":{"t":true,"w":"貸金業法第12条の9。","r":[["貸金業法","12の9"]]}}},"04-13":{"s":"貸金業務取扱主任者を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"貸金業法第24条の25第4項、施行規則第26条の51第1項。","r":[["貸金業法","24の25"],["貸金業法施行規則","26の51"]]},"2":{"t":false,"p":"2週間の猶予があるのは「予見し難い事由」の場合です。産後休暇は予見できるので、2週間の猶予は「ありません」（事前に主任者を手当てしておく必要があります）。","w":"貸金業法第12条の3第3項、監督指針Ⅱ－２－９（２）③（会社として予見できると思われるものは含まれない）。予見し難い事由に当たらないとする点は公式正答によります。","r":[["貸金業法","12の3"]]},"3":{"t":true,"w":"施行規則第10条の8（50分の1以上）、貸金業法第6条第1項第13号。","r":[["貸金業法施行規則","10の8"],["貸金業法","6"]]},"4":{"t":true,"w":"貸金業法第24条の26第2項。","r":[["貸金業法","24の26"]]}}},"04-14":{"s":"契約締結時の書面と再交付を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"貸金業法第17条第1項第1号〜第4号。","r":[["貸金業法","17"]]},"2":{"t":true,"w":"施行規則第13条第1項第1号カ。","r":[["貸金業法施行規則","13"]]},"3":{"t":false,"p":"貸付けの利率の引下げは相手方の利益となる変更なので、再交付は「不要」です。","w":"施行規則第13条第2項第1号イ。","r":[["貸金業法施行規則","13"]]},"4":{"t":true,"w":"施行規則第13条第2項第1号ロ（第1項第1号ト）。","r":[["貸金業法施行規則","13"]]}}},"04-15":{"s":"極度方式基本契約・極度方式貸付けの書面を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"貸金業法第16条の2第2項。","r":[["貸金業法","16の2"]]},"2":{"t":false,"p":"極度方式貸付けに係る契約は、契約締結前の書面（第16条の2第1項）の交付義務の対象から「除かれています」。","w":"貸金業法第16条の2第1項の括弧書。","r":[["貸金業法","16の2"]]},"3":{"t":true,"w":"貸金業法第17条第2項第3号（当該下回る額及び極度額）。","r":[["貸金業法","17"]]},"4":{"t":true,"w":"施行規則第13条第4項第1号イ（期限の利益の喪失の定め。第3項第1号ヌ）：相手方の利益となる変更でなければ再交付が必要です。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]}}},"04-16":{"s":"書面に代えて電磁的方法で提供する場合を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"貸金業法第16条の2第4項、施行令第3条の2の5第1項。","r":[["貸金業法","16の2"],["貸金業法施行令","3の2の5"]]},"2":{"t":false,"p":"保証人となろうとする者に電磁的方法で提供する場合も、その者の承諾を得る必要が「あります」。","w":"貸金業法第16条の2第4項、施行令第3条の2の5第1項（保証人となろうとする者の承諾）。","r":[["貸金業法","16の2"],["貸金業法施行令","3の2の5"]]},"3":{"t":true,"w":"貸金業法第17条第7項（相手方の承諾を得て提供）。","r":[["貸金業法","17"]]},"4":{"t":true,"w":"貸金業法第18条第4項。","r":[["貸金業法","18"]]}}},"04-17":{"s":"マンスリーステートメントと簡素化書面を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"貸金業法第17条第6項、施行規則第13条第17項。記載事項の細目は公式正答によります。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"2":{"t":true,"w":"貸金業法第17条第6項。","r":[["貸金業法","17"]]},"3":{"t":false,"p":"弁済を受けたときの簡素化書面は、「1か月以内」ではなく、「直ちに」交付します（受取証書に代わる書面）。","w":"貸金業法第18条第1項・第3項。","r":[["貸金業法","18"]]},"4":{"t":true,"w":"貸金業法第17条第7項。","r":[["貸金業法","17"]]}}},"04-18":{"s":"返済能力の調査を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"貸金業法第13条第3項ただし書。","r":[["貸金業法","13"]]},"2":{"t":true,"w":"施行規則第10条の18第2項第1号。","r":[["貸金業法施行規則","10の18"]]},"3":{"t":true,"w":"施行規則第10条の17第3項：変更後の勤務先が確認され、変更後の勤務先で2月分以上の給与を受けていない場合を除き、変更後の書面等が必要です。","r":[["貸金業法施行規則","10の17"]]},"4":{"t":false,"p":"返済能力の調査義務の違反は、業務改善命令だけでなく、業務の全部又は一部の停止や登録の取消しの対象にも「なります」。","w":"貸金業法第24条の6の4第1項第2号。","r":[["貸金業法","13"],["貸金業法","24の6の4"]]}}},"04-19":{"s":"保証人となろうとする者の返済能力の調査を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"貸金業法第13条第2項。","r":[["貸金業法","13"]]},"2":{"t":true,"w":"貸金業法第13条の2第1項（顧客等の返済能力を超える貸付けの契約の禁止）。","r":[["貸金業法","13の2"]]},"3":{"t":false,"p":"資力を明らかにする書面等の提出義務は「個人顧客」についてのもので、保証人となろうとする者は対象では「ありません」。","w":"貸金業法第13条第3項。","r":[["貸金業法","13"]]},"4":{"t":true,"w":"貸金業法第13条第4項。","r":[["貸金業法","13"]]}}},"04-20":{"s":"貸付限度額の増額と返済能力の調査を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"貸付限度額の増額も極度額の増額として扱われ、調査の際は指定信用情報機関の信用情報を使用する必要が「あります」。","w":"貸金業法第13条第5項（第2項の準用。極度額を下回る額を提示している場合はその額）。","r":[["貸金業法","13"]]},"2":{"t":true,"w":"貸金業法第13条の2第1項（第13条第5項の場合も含む）。","r":[["貸金業法","13の2"]]},"3":{"t":true,"w":"貸金業法第13条第5項で準用する第4項。","r":[["貸金業法","13"]]},"4":{"t":true,"w":"施行規則第10条の19。","r":[["貸金業法施行規則","10の19"]]}}},"04-21":{"s":"公的給付に係る預金通帳等の保管等の制限（貸金業法第20条の2）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"公的給付とは、法令の規定により差し押さえることだけでなく、「譲り渡し、担保に供すること」もできないこととされている給付です。","w":"貸金業法第20条の2。","r":[["貸金業法","20の2"]]},"2":{"t":true,"w":"貸金業法第20条の2第1号。","r":[["貸金業法","20の2"]]},"3":{"t":true,"w":"貸金業法第20条の2第2号（特定受給権者には債務者等の親族その他の者を含む）。","r":[["貸金業法","20の2"]]},"4":{"t":true,"w":"貸金業法第20条の2（主語は「貸金業を営む者」で、無登録の者も含まれます）。","r":[["貸金業法","20の2"]]}}},"04-22":{"s":"帳簿と帳簿の閲覧・謄写を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"監督指針Ⅱ－２－１８（１）③（実費は適正かつ適切な金額）。","r":[["貸金業法","19の2"]]},"2":{"t":true,"w":"施行規則第17条第1項ただし書（極度方式基本契約の解除の日又は最終の返済期日のうちいずれか遅い日から10年間）。","r":[["貸金業法施行規則","17"]]},"3":{"t":false,"p":"「債務者等であった者」も閲覧・謄写を請求でき、完済から5年を経過すると請求できなくなるという定めは「ありません」。","w":"貸金業法第19条の2（債務者等又は債務者等であった者）。","r":[["貸金業法","19の2"]]},"4":{"t":true,"w":"貸金業法第19条の2（利害関係がある部分に限る）。","r":[["貸金業法","19の2"]]}}},"04-23":{"s":"取立ての委託を受けた者の取立て行為の規制を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"貸金業法第21条第3項。","r":[["貸金業法","21"]]},"2":{"t":false,"p":"支払を催告する書面には、残存債務の額だけでなく「貸付けの利率」も記載しなければ「なりません」。","w":"貸金業法第21条第2項第5号、施行規則第19条第3項第1号。","r":[["貸金業法","21"],["貸金業法施行規則","19"]]},"3":{"t":true,"w":"施行規則第19条第6項ただし書。","r":[["貸金業法施行規則","19"]]},"4":{"t":true,"w":"貸金業法第49条第7号（第21条第3項違反）、第51条第1項（両罰規定）。","r":[["貸金業法","49"],["貸金業法","51"]]}}},"04-24":{"s":"事業報告書（貸金業法第24条の6の9）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"金銭の貸借の媒介のみを行う貸金業者も、事業報告書を提出する義務が「あります」（例外の定めはありません）。","w":"貸金業法第24条の6の9。","r":[["貸金業法","24の6の9"]]},"2":{"t":true,"w":"貸金業法第24条の6の9。","r":[["貸金業法","24の6の9"]]},"3":{"t":true,"w":"公式正答では適切です（個人の事業年度の定めは、取り込んだ資料で確認できません）。","r":[]},"4":{"t":true,"w":"施行規則第26条の29第3項第1号イ。","r":[["貸金業法施行規則","26の29"]]}}},"04-25":{"s":"登録行政庁による監督と届出を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"届出が必要な「貸金業の開始」には、広告・勧誘や債権の取立てに係る業務の開始も「含まれます」。","w":"貸金業法第24条の6の2第1号。","r":[["貸金業法","24の6の2"]]},"2":{"t":true,"w":"貸金業法第24条の6の10第3項。","r":[["貸金業法","24の6の10"]]},"3":{"t":true,"w":"貸金業法第24条の6の10第1項。","r":[["貸金業法","24の6の10"]]},"4":{"t":true,"w":"貸金業法第24条の6の2第2号。","r":[["貸金業法","24の6の2"]]}}},"04-26":{"s":"指定信用情報機関制度を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"貸金業法第41条の13第1項第5号、施行規則第28条第2項第1号（加入貸金業者の数が100以上）。","r":[["貸金業法","41の13"],["貸金業法施行規則","28"]]},"2":{"t":true,"w":"貸金業法第41条の14第2項第2号。","r":[["貸金業法","41の14"]]},"3":{"t":false,"p":"指定信用情報機関は、加入貸金業者の名簿を「公衆の縦覧に供しなければなりません」。閲覧させてはならないのではありません。","w":"貸金業法第41条の25。","r":[["貸金業法","41の25"]]},"4":{"t":true,"w":"貸金業法第41条の26。","r":[["貸金業法","41の26"]]}}},"04-27":{"s":"指定信用情報機関への信用情報の提供等に係る同意を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"貸金業法第41条の36第2項第1号。","r":[["貸金業法","41の36"]]},"2":{"t":true,"w":"貸金業法第41条の36第2項第3号。","r":[["貸金業法","41の36"]]},"3":{"t":true,"w":"貸金業法第41条の36第2項第2号。","r":[["貸金業法","41の36"]]},"4":{"t":false,"p":"信用情報の提供の依頼をする場合は、原則として、あらかじめ書面又は電磁的方法による同意を得る必要が「あります」。","w":"貸金業法第41条の36第1項。","r":[["貸金業法","41の36"]]}}},"04-28":{"s":"貸金業協会の苦情への対応（貸金業法第41条の7）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"貸金業法第41条の7第1項。","r":[["貸金業法","41の7"]]},"2":{"t":true,"w":"貸金業法第41条の7第2項。","r":[["貸金業法","41の7"]]},"3":{"t":true,"w":"貸金業法第41条の7第3項。","r":[["貸金業法","41の7"]]},"4":{"t":false,"p":"協会は、苦情の申出、事情及び解決の結果について、協会員に「周知しなければなりません」。","w":"貸金業法第41条の7第4項（協会が指定紛争解決機関の指定を受けている場合は第1項は適用されません。第5項）。","r":[["貸金業法","41の7"]]}}},"04-29":{"s":"貸金業協会と協会員を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"過怠金を課すのは「内閣総理大臣」ではなく「協会」で、定款で定めるところによります。また「課さなければならない」ものではありません。","w":"貸金業法第38条第1項（協会は、定款において、違反行為をした協会員に過怠金を課し、定款で定める協会員の権利の停止若しくは制限を命じ、又は除名する旨を定めなければならない）。","r":[["貸金業法","38"]]},"2":{"t":true,"w":"貸金業法第34条第2項。","r":[["貸金業法","34"]]},"3":{"t":true,"w":"貸金業法第37条第3項。","r":[["貸金業法","37"]]},"4":{"t":true,"w":"貸金業法第41条の9。","r":[["貸金業法","41の9"]]}}},"04-30":{"s":"監督指針Ⅱ－２－８（不祥事件に対する監督上の対応）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"監督指針Ⅱ－２－８（不祥事件の定義）。","r":[]},"2":{"t":true,"w":"監督指針Ⅱ－２－８（１）①イ。","r":[]},"3":{"t":true,"w":"監督指針Ⅱ－２－８（１）②イ。","r":[]},"4":{"t":false,"p":"重大な問題の有無を問わず業務停止命令・登録取消しを「しなければならない」のではありません。重大な問題があれば業務改善命令、重大・悪質な法令違反があれば業務停止命令等の発出を「検討する」とされています。","w":"監督指針Ⅱ－２－８（２）。","r":[["貸金業法","24の6の3"],["貸金業法","24の6の4"]]}}},"04-31":{"s":"意思表示を問う問題です。適切なのは②です。","law":"この回の基準日は2020年4月の民法改正の前で、錯誤は「無効」とされていました。現行の第95条では「取り消すことができる」とされ、表意者に重大な過失があるときは、相手方が悪意・重過失のときなどを除き取り消せません。④は現行法でも適切ではありません。","items":{"1":{"t":false,"p":"詐欺による取消しは、善意（現行法では善意かつ無過失）の第三者に対抗「できません」。","w":"民法第96条第3項。","r":[["民法","96"]]},"2":{"t":true,"w":"民法第96条第3項が第三者を保護するのは詐欺の場合だけなので、強迫による取消しは善意の第三者にも対抗できます。","r":[["民法","96"]]},"3":{"t":false,"p":"虚偽表示の無効は、善意の第三者に対抗「できません」。","w":"民法第94条第2項。","r":[["民法","94"]]},"4":{"t":false,"p":"表意者に重大な過失があるときは、表意者は自ら錯誤を主張「できません」。","w":"民法第95条第3項（出題時は旧第95条ただし書）。","r":[["民法","95"]]}}},"04-32":{"s":"履行遅滞と遅延損害金を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"民法第412条第1項（確定期限）。","r":[["民法","412"]]},"2":{"t":false,"p":"期限の定めがない債務は、履行の請求を受けた時から遅滞の責任を「負います」（消費貸借では相当の期間を定めて催告できます）。期間経過後も返済しなければ遅滞の責任を負います。","w":"民法第412条第3項、第591条第1項。","r":[["民法","412"],["民法","591"]]},"3":{"t":false,"p":"不確定期限の場合、期限の到来を知らなかったときは、到来した時からではなく、履行の請求を受けた時（又は到来を知った時）のいずれか早い時から遅滞の責任を負います。","w":"民法第412条第2項（出題時は「知った時」から）。","r":[["民法","412"]]},"4":{"t":false,"p":"約定がない場合の遅延損害金は、年14.6％ではなく「法定利率」によります。","w":"民法第419条第1項、第404条。","r":[["民法","419"],["民法","404"]]}}},"04-33":{"s":"債権の消滅原因を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"代物弁済には、債権者の同意（現行法では債権者との契約）が「必要」です。","w":"民法第482条。","r":[["民法","482"]]},"2":{"t":true,"w":"民法第519条：免除は債権者の一方的な意思表示でできます。","r":[["民法","519"]]},"3":{"t":false,"p":"更改は「一方的意思表示」ではなく「契約」によって行います。","w":"民法第513条。","r":[["民法","513"]]},"4":{"t":false,"p":"供託は「裁判所」ではなく「供託所」にします（公式正答による）。","w":"民法第494条第1項第1号（受領拒絶による供託）、第495条（供託の方法）。","r":[["民法","494"]]}}},"04-34":{"s":"相続と債務の承継・限定承認を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"公式正答では適切です。遺産分割で債務の承継者を決めても、債権者は各相続人に法定相続分の限度で請求できるという考え方です（判例の考え方による）。相続分の指定がある場合は民法第902条の2が同じ趣旨を定めています。","r":[["民法","902の2"]]},"2":{"t":false,"p":"相続人は相続分に応じて債務を承継するので、Ｂ社がＤに請求できるのは「全額」ではなく「Ｄの相続分」の限度です。","w":"民法第899条。","r":[["民法","899"]]},"3":{"t":false,"p":"公告は「あらかじめ」ではなく、限定承認を「した後5日以内に」行います。","w":"民法第927条第1項。","r":[["民法","927"]]},"4":{"t":false,"p":"限定承認をしても、相続によって得た財産の限度では弁済を受けられるので、貸付金を回収できなくなるわけでは「ありません」。","w":"民法第922条。","r":[["民法","922"]]}}},"04-35":{"s":"抵当権を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"物上保証の抵当権設定契約は、債権者と所有者（第三者）の間で結べば足り、債務者を加えた3者の契約は「不要」です（公式正答による）。","w":"民法第369条第1項（債務者又は第三者が担保に供した不動産）。","r":[["民法","369"]]},"2":{"t":false,"p":"土地の抵当権の効力は、抵当地の上に存する建物には「及びません」。","w":"民法第370条。","r":[["民法","370"]]},"3":{"t":true,"w":"民法第372条・第304条（物上代位）。","r":[["民法","372"],["民法","304"]]},"4":{"t":false,"p":"地上権及び永小作権も、抵当権の目的とすることが「できます」。","w":"民法第369条第2項。","r":[["民法","369"]]}}},"04-36":{"s":"犯罪収益移転防止法を問う問題です。適切なのは④です。","law":"出題時の「本人確認」は、現行法では「取引時確認」と呼ばれ、疑わしい取引の届出は第8条、行政庁は第22条に定められています。","items":{"1":{"t":false,"p":"対面での確認は運転免許証などの本人確認書類の「原本」の提示を受ける方法で、「写し」の提示では足りません（公式正答による）。","w":"犯罪収益移転防止法第4条第1項（主務省令で定める方法による確認）。","r":[["犯収法","4"]]},"2":{"t":false,"p":"法人の本人特定事項は「名称及び本店又は主たる事務所の所在地」で、定款に記載された目的ではありません。","w":"犯罪収益移転防止法第4条第1項第1号。","r":[["犯収法","4"]]},"3":{"t":false,"p":"本人特定事項は名称・所在地で、取締役会の決議が必要な多額の借財に当たるかどうかは「含まれません」。","w":"犯罪収益移転防止法第4条第1項第1号。","r":[["犯収法","4"]]},"4":{"t":true,"w":"犯罪収益移転防止法第8条第1項（疑わしい取引の届出）。","r":[["犯収法","8"]]}}},"04-37":{"s":"不動産の仮差押え（民事保全法）を問う問題です。適切なのはａｂです。","items":{"a":{"t":true,"w":"民事保全法第20条第1項。","r":[["民事保全法","20"]]},"b":{"t":true,"w":"民事保全法第4条第1項（担保の提供方法）。支払保証委託契約の方法は民事保全規則によります（公式正答による）。","r":[["民事保全法","4"]]},"c":{"t":false,"p":"保全異議の申立てには「2週間以内」という期間の制限は「ありません」。","w":"民事保全法第26条。","r":[["民事保全法","26"]]},"d":{"t":false,"p":"不動産の仮差押えの執行は、執行官が現地に赴くのではなく、「仮差押えの登記をする方法」又は強制管理の方法で行います。","w":"民事保全法第47条第1項。","r":[["民事保全法","47"]]}}},"04-38":{"s":"法的紛争解決手続を問う問題です。適切なのはｃｄの2個です。","items":{"a":{"t":false,"p":"支払督促には、年間の利用回数の上限は「ありません」（回数の制限があるのは少額訴訟です）。","w":"民事訴訟法第368条第1項ただし書（少額訴訟の回数制限）。支払督促にこのような定めはありません。","r":[["民事訴訟法","368"]]},"b":{"t":false,"p":"民事調停には、対象となる紛争の価額の上限は「ありません」。","w":"民事調停法第1条（民事に関する紛争が対象）。同法に価額の上限の定めはありません。","r":[["民事調停法","1"]]},"c":{"t":true,"w":"民事訴訟法第54条第1項ただし書。","r":[["民事訴訟法","54"]]},"d":{"t":true,"w":"民事訴訟法第377条。","r":[["民事訴訟法","377"]]}}},"04-39":{"s":"小切手を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"小切手法第1条第5号、第2条第1項。","r":[["小切手法","1"],["小切手法","2"]]},"2":{"t":false,"p":"小切手は「一覧払」のもので、支払期日の記載は要件では「ありません」（記載しても書かなかったものとみなされます）。","w":"小切手法第28条第1項。","r":[["小切手法","28"]]},"3":{"t":false,"p":"振出日より前に呈示しても、呈示の日に支払うべきものとされるので、呈示「できます」（先日付小切手）。","w":"小切手法第28条第2項。","r":[["小切手法","28"]]},"4":{"t":false,"p":"二条の線内に何の指定もないものは、「一般線引」の効力を「有します」。","w":"小切手法第37条第3項。","r":[["小切手法","37"]]}}},"04-40":{"s":"無権代理を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"民法第115条（相手方が契約の時に代理権がないことを知っていたときは取り消せません）。","r":[["民法","115"]]},"2":{"t":true,"w":"民法第114条（相手方の善意・悪意を問いません）。","r":[["民法","114"]]},"3":{"t":true,"w":"民法第114条後段。","r":[["民法","114"]]},"4":{"t":false,"p":"無権代理人の責任（履行又は損害賠償）を追及できるのは、相手方が代理権がないことを「知らなかった」場合（現行法では過失がない場合など）に限られます。知っていたときは請求「できません」。","w":"民法第117条第2項第1号。","r":[["民法","117"]]}}},"04-41":{"s":"弁済を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"民法第474条第1項・第2項。","r":[["民法","474"]]},"2":{"t":false,"p":"充当の順序は「費用、元本、利息」ではなく「費用、利息、元本」です。","w":"民法第489条第1項。","r":[["民法","489"]]},"3":{"t":true,"w":"民法第485条。","r":[["民法","485"]]},"4":{"t":true,"w":"民法第484条第1項。","r":[["民法","484"]]}}},"04-42":{"s":"差押禁止動産・差押禁止債権（民事執行法）を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"民事執行法第131条第7号。","r":[["民事執行法","131"]]},"2":{"t":false,"p":"給料債権は支払期に受けるべき給付の「4分の3」が差押禁止なので、差し押さえられるのは「4分の1」です。","w":"民事執行法第152条第1項第2号。","r":[["民事執行法","152"]]},"3":{"t":true,"w":"民事執行法第131条第12号。","r":[["民事執行法","131"]]},"4":{"t":true,"w":"民事執行法第131条第14号。","r":[["民事執行法","131"]]}}},"04-43":{"s":"破産法を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"破産法第2条第5項。","r":[["破産法","2"]]},"2":{"t":true,"w":"破産法第2条第7項。","r":[["破産法","2"]]},"3":{"t":true,"w":"破産法第65条第1項。","r":[["破産法","65"]]},"4":{"t":false,"p":"裁判所の許可を得て事業を継続できるのは「破産管財人」だけで、「破産者」はできません。","w":"破産法第36条。","r":[["破産法","36"]]}}},"04-44":{"s":"返済能力の調査と過剰貸付けの禁止を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"基準額は、年収などの合算額に「4分の1」ではなく「3分の1」を乗じて得た額です。","w":"貸金業法第13条の2第2項。","r":[["貸金業法","13の2"]]},"2":{"t":false,"p":"居宅を担保とする貸付けでも、返済能力を超えると認められるときは締結「できません」。","w":"貸金業法第13条の2第1項（顧客等の返済能力を超える貸付けの契約の禁止）。","r":[["貸金業法","13の2"]]},"3":{"t":true,"w":"施行規則第10条の21第1項第4号（除外契約）。第10条の23（例外契約）には当たりません。","r":[["貸金業法施行規則","10の21"]]},"4":{"t":false,"p":"信用情報の使用が義務づけられているのは「個人である顧客等」との契約で、法人との契約では「不要」です（返済能力を超える契約の禁止は法人にも適用されます）。","w":"貸金業法第13条第2項、第13条の2第1項。","r":[["貸金業法","13"],["貸金業法","13の2"]]}}},"04-45":{"s":"個人情報の定義（金融分野ガイドライン）の穴埋め問題です。正しいのは④です（ア個人情報データベース等・イ個人データ・ウ保有個人データ・エ6月）。","law":"エの「6月以内に消去するものを保有個人データから除く」定めは、2022年施行の改正で廃止されました。現行の個人情報保護法第16条第4項では、短期間で消去する個人データも保有個人データに含まれます。","items":{"1":{"t":false,"p":"アは「保有データベース等」ではなく「個人情報データベース等」、ウは「個人信用情報」ではなく「保有個人データ」です。"},"2":{"t":false,"p":"アは「個人情報データベース等」、イは「個人データ」、エは「6月」です（出題時）。"},"3":{"t":false,"p":"イは「保有個人情報」ではなく「個人データ」、ウは「個人信用情報」ではなく「保有個人データ」、エは「3月」ではなく「6月」です（出題時）。"},"4":{"t":true,"w":"個人情報保護法第16条第1項・第3項・第4項。エ（6月）は出題時の定めで、現在は廃止されています。","r":[["個人情報保護法","16"]]}}},"04-46":{"s":"誇大広告の禁止等（貸金業法第16条）を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"貸金業法第16条第2項第2号。","r":[["貸金業法","16"]]},"2":{"t":true,"w":"貸金業法第16条第4項。","r":[["貸金業法","16"]]},"3":{"t":false,"p":"過度な広告・勧誘の禁止（第16条第5項）に違反した場合も、行政処分の対象と「なります」。","w":"貸金業法第16条第5項、第24条の6の3（業務改善命令）・第24条の6の4第1項第2号。","r":[["貸金業法","16"],["貸金業法","24の6の4"]]},"4":{"t":true,"w":"貸金業法第16条第3項。","r":[["貸金業法","16"]]}}},"04-47":{"s":"生命保険契約の締結に係る制限（貸金業法第12条の7）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"「貸付けの契約」には保証契約も含まれ、その相手方である保証人についても、自殺による死亡を保険事故とすることは「できません」。","w":"貸金業法第12条の7、第2条第3項（貸付けの契約には保証契約を含む）。","r":[["貸金業法","12の7"],["貸金業法","2"]]},"2":{"t":true,"w":"貸金業法第12条の7の括弧書（住宅資金貸付契約その他の内閣府令で定める契約は除かれます）。","r":[["貸金業法","12の7"]]},"3":{"t":true,"w":"貸金業法第12条の7。","r":[["貸金業法","12の7"]]},"4":{"t":true,"w":"貸金業法第48条第1項第1号の3。","r":[["貸金業法","12の7"],["貸金業法","48"]]}}},"04-48":{"s":"企業会計原則の損益計算書の本質の穴埋め問題です。正しいのは④です（ア経営成績・イ収益・ウ費用・エ経常利益）。","items":{"1":{"t":false,"p":"アは「財政状態」ではなく「経営成績」、イは「資産」ではなく「収益」、ウは「負債」ではなく「費用」です。"},"2":{"t":false,"p":"エは「営業利益」ではなく「経常利益」です。"},"3":{"t":false,"p":"アは「経営成績」、イは「収益」、ウは「費用」、エは「経常利益」です。"},"4":{"t":true,"w":"企業会計原則 第二 損益計算書原則 一（損益計算書の本質）。"}}},"04-49":{"s":"キャッシュ・フロー計算書の区分の組合せ問題です。正しいのは②です（ア営業活動－ａ、イ投資活動－ｃ、ウ財務活動－ｂ）。キャッシュ・フロー計算書の基準は取り込んだ資料にないため、この問題は公式正答によります。","items":{"1":{"t":false,"p":"イ（投資活動）はｂではなく「ｃ」（有価証券・固定資産・貸付け）、ウ（財務活動）はｃではなく「ｂ」（借入れ・社債・株式）です。"},"2":{"t":true,"w":"公式正答によります。"},"3":{"t":false,"p":"アは「ａ」（仕入れ・人件費など営業利益の計算の対象となった取引）、イは「ｃ」、ウは「ｂ」です。"},"4":{"t":false,"p":"アは「ａ」、イは「ｃ」です。"}}},"04-50":{"s":"給与所得の源泉徴収票を問う問題です。適切なのは③です。源泉徴収票の様式は取り込んだ資料にないため、この問題は公式正答によります。","items":{"1":{"t":false,"p":"支払金額は、所得税額・住民税額を控除した「後」の金額ではありません（公式正答による）。","w":"源泉徴収票の様式は取り込んだ資料にないため、この肢は公式正答によります。","r":[]},"2":{"t":false,"p":"源泉徴収税額は、所得税額と住民税額の「合計額」ではありません（公式正答による）。","w":"源泉徴収票の様式は取り込んだ資料にないため、この肢は公式正答によります。","r":[]},"3":{"t":true,"w":"源泉徴収票の様式は取り込んだ資料にないため、この肢は公式正答によります。","r":[]},"4":{"t":false,"p":"中途で退職した場合の年月日を記載する欄も「あります」（公式正答による）。","w":"源泉徴収票の様式は取り込んだ資料にないため、この肢は公式正答によります。","r":[]}}},"05-01":{"s":"貸金業法の用語の定義を問う問題です。適切なのはａｂｄの3個です。","items":{"a":{"t":true,"w":"貸金業法第2条第4項〜第6項。","r":[["貸金業法","2"]]},"b":{"t":true,"w":"貸金業法第2条第9項。","r":[["貸金業法","2"]]},"c":{"t":false,"p":"記述は「信用情報」の定義です。「個人信用情報」とは、個人を相手方とする貸付けに係る契約に係る第41条の35第1項各号の事項（氏名・契約年月日・貸付けの金額など）をいいます。","w":"貸金業法第2条第13項・第14項。","r":[["貸金業法","2"]]},"d":{"t":true,"w":"貸金業法第2条第11項。","r":[["貸金業法","2"]]}}},"05-02":{"s":"変更の届出（貸金業法第8条）を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"役員の変更の届出期限は、「30日以内」ではなく変更の日から「2週間以内」です。","w":"貸金業法第8条第1項、第4条第1項第2号。","r":[["貸金業法","8"],["貸金業法","4"]]},"2":{"t":false,"p":"商号などの変更は、「あらかじめ」ではなく、変更の日から「2週間以内」に届け出ます。","w":"貸金業法第8条第1項、第4条第1項第1号。","r":[["貸金業法","8"],["貸金業法","4"]]},"3":{"t":true,"w":"貸金業法第8条第1項（第4条第1項第5号の変更はあらかじめ届出）・第3項（添付書類）。添付書類の細目は公式正答によります。","r":[["貸金業法","8"]]},"4":{"t":false,"p":"添付書類に虚偽の記載をして提出した場合も、刑事罰の対象に「なります」。","w":"貸金業法第50条第1項第1号（虚偽の届出）・第2号（第8条第3項の書類に虚偽の記載をして提出）。","r":[["貸金業法","50"]]}}},"05-03":{"s":"無登録営業と罰則を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"法人の従業者が法人の業務に関して違反行為をしたときは、行為者だけでなく法人も罰金刑を科され「ます」（両罰規定）。","w":"貸金業法第51条第1項。","r":[["貸金業法","51"]]},"2":{"t":false,"p":"無登録者による勧誘が禁止されるのは、「貸金業を営む目的をもって」勧誘する場合です。目的の有無を問わないわけではありません。","w":"貸金業法第11条第2項第2号、第47条の3第1項第2号。","r":[["貸金業法","11"],["貸金業法","47の3"]]},"3":{"t":true,"w":"貸金業法第11条第3項の違反は、刑事罰（第47条の3第1項第2号）と登録の取消し等（第24条の6の4第1項第2号）の対象です。","r":[["貸金業法","11"],["貸金業法","47の3"],["貸金業法","24の6の4"]]},"4":{"t":false,"p":"再開の届出をしなかった場合も、刑事罰の対象に「なります」。","w":"貸金業法第24条の6の2第1号、第50条第1項第3号（届出をせず、又は虚偽の届出をした者）。","r":[["貸金業法","24の6の2"],["貸金業法","50"]]}}},"05-04":{"s":"業務の適切な運営を確保するための措置（施行規則）を問う問題です。適切なのはａｃｄです。","items":{"a":{"t":true,"w":"施行規則第10条の2第1項。","r":[["貸金業法施行規則","10の2"]]},"b":{"t":false,"p":"特別の非公開情報は、社内で「一切」利用しないのではなく、「適切な業務の運営の確保その他必要と認められる目的以外の目的のために」利用しないことを確保する措置を講じます。","w":"施行規則第10条の4。","r":[["貸金業法施行規則","10の4"]]},"c":{"t":true,"w":"施行規則第10条の3。","r":[["貸金業法施行規則","10の3"]]},"d":{"t":true,"w":"施行規則第10条の6。","r":[["貸金業法施行規則","10の6"]]}}},"05-05":{"s":"監督指針（禁止行為等）の穴埋め問題です。正しいのは①です（ア不正・イ不当・ウ資金需要者等・エキャッシュカード）。","items":{"1":{"t":true,"w":"監督指針Ⅱ－２－１０（２）②（出題時の項番号はⅡ－２－９）：「偽りその他不正又は著しく不当な行為」、資金需要者等の利益を害する程度、「印鑑、預貯金通帳・証書、キャッシュカード、運転免許証…」。"},"2":{"t":false,"p":"アは「不当」ではなく「不正」、イは「不法」ではなく「不当」、ウは「顧客等」ではなく「資金需要者等」、エは「源泉徴収票」ではなく「キャッシュカード」です。"},"3":{"t":false,"p":"ウは「顧客等」ではなく「資金需要者等」です。"},"4":{"t":false,"p":"アは「不法」ではなく「不正」、イは「不正」ではなく「不当」、エは「源泉徴収票」ではなく「キャッシュカード」です。"}}},"05-06":{"s":"基準額超過極度方式基本契約に係る調査を問う問題です。正しい組合せは「ａ正・ｂ誤・ｃ誤・ｄ正」です。","items":{"a":{"t":true,"w":"貸金業法第13条の3第5項、第13条の2第2項（基準額）。","r":[["貸金業法","13の3"],["貸金業法","13の2"]]},"b":{"t":false,"p":"調査が不要になるのは、当該極度方式基本契約の残高だけでなく、他の極度方式基本契約の残高も「含めた」合計額が10万円以下の場合です。","w":"施行規則第10条の25第3項第1号。","r":[["貸金業法施行規則","10の25"]]},"c":{"t":false,"p":"資力を明らかにする書面等が必要なのは、極度方式個人顧客合算額が「50万円」ではなく「100万円」を超える場合です。","w":"貸金業法第13条の3第3項。","r":[["貸金業法","13の3"]]},"d":{"t":true,"w":"施行規則第10条の27第2項・第3項。","r":[["貸金業法施行規則","10の27"]]}}},"05-07":{"s":"広告・勧誘の規制のうち刑事罰の対象となるものを問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"貸金業法第16条第1項の違反は、第48条第1項第3号により刑事罰の対象です。","r":[["貸金業法","16"],["貸金業法","48"]]},"2":{"t":false,"p":"第16条第2項第1号の違反は、行政処分の対象ですが、刑事罰の対象では「ありません」。","w":"罰則（第48条）が挙げるのは第16条第1項の違反です。","r":[["貸金業法","16"]]},"3":{"t":false,"p":"第16条第3項（適合性原則）の違反は、刑事罰の対象では「ありません」。","w":"貸金業法第16条第3項。","r":[["貸金業法","16"]]},"4":{"t":false,"p":"第16条第4項（再勧誘の禁止）の違反は、刑事罰の対象では「ありません」。","w":"貸金業法第16条第4項。","r":[["貸金業法","16"]]}}},"05-08":{"s":"契約締結前の書面と契約締結時の書面を問う問題です。正しい組合せは「ａ誤・ｂ正・ｃ正・ｄ正」です。","items":{"a":{"t":false,"p":"契約締結前の書面を交付していても、契約を締結したときは契約締結時の書面を交付する必要が「あります」。","w":"貸金業法第17条第1項。","r":[["貸金業法","17"],["貸金業法","16の2"]]},"b":{"t":true,"w":"施行規則第12条の2第1項第1号イ・ロ・ホ・ト。","r":[["貸金業法施行規則","12の2"]]},"c":{"t":true,"w":"施行規則第12条の2第9項（現行の表記は「日本産業規格」）。","r":[["貸金業法施行規則","12の2"]]},"d":{"t":true,"w":"貸金業法第16条の2第4項。","r":[["貸金業法","16の2"]]}}},"05-09":{"s":"保証人に交付する書面を問う問題です。適切なのはｃｄです。","items":{"a":{"t":false,"p":"保証契約の弁済の方法及び弁済を受ける場所の変更は、保証人の利益となる変更でも再交付が「必要」です。","w":"施行規則第13条第7項第1号ロ（第12条の2第6項第7号）。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"b":{"t":false,"p":"保証期間の変更は、保証人の利益となる変更なら再交付は「不要」です。","w":"施行規則第13条第7項第1号イ（第16条の2第3項第2号）。","r":[["貸金業法施行規則","13"]]},"c":{"t":true,"w":"貸金業法第17条第3項、第16条の2第3項第5号。","r":[["貸金業法","17"],["貸金業法","16の2"]]},"d":{"t":true,"w":"貸金業法第17条第4項。","r":[["貸金業法","17"]]}}},"05-10":{"s":"マンスリーステートメントと簡素化書面を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"貸金業法第17条第6項、施行規則第13条第17項（マンスリーステートメントの記載事項）。記載事項の細目は公式正答によります。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"2":{"t":false,"p":"電磁的方法による承諾を受けた場合は、承諾を受けた旨を書面その他適切な方法で通知する必要が「あります」（公式正答による）。","w":"監督指針Ⅱ－２－１６（１）④。","r":[["貸金業法","17"]]},"3":{"t":false,"p":"簡素化書面は「3か月に1回」まとめて交付するのではなく、極度方式貸付けの契約を締結する「ごとに」交付します（マンスリーステートメントは1月以内の一定期間ごと）。","w":"貸金業法第17条第6項、施行規則第13条第17項。期間の細目は公式正答によります。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"4":{"t":false,"p":"弁済を受けたときの簡素化書面は、「1か月以内」ではなく、「直ちに」交付します（受取証書に代わる書面）。","w":"貸金業法第18条第1項・第3項。","r":[["貸金業法","18"]]}}},"05-11":{"s":"貸金業務取扱主任者の登録の拒否事由を問う問題です。公式正答はｂｃｄです。","law":"ｃについて、2019年の改正で、成年被後見人・被保佐人であることを一律に拒否事由とする規定は廃止され、現行の第24条の27第1項第1号は「心身の故障のため職務を適正に執行することができない者として内閣府令で定める者」としています。現行法ではｃは拒否事由に当たりません。","items":{"a":{"t":false,"p":"罰金の刑が拒否事由になるのは、貸金業法・出資法などの規定に違反した場合です。道路交通法違反の罰金は「該当しません」。","w":"貸金業法第24条の27第1項第5号。","r":[["貸金業法","24の27"]]},"b":{"t":true,"w":"貸金業法第24条の27第1項第4号（拘禁刑以上の刑。出題時は禁錮以上）。","r":[["貸金業法","24の27"]]},"c":{"t":true,"now":false,"p":"現行法では、成年被後見人・被保佐人であることは、それだけで拒否事由には当たりません（心身の故障により職務を適正に執行できない者として内閣府令で定める者が拒否事由です）。","w":"出題時の貸金業法による記述です（公式正答による）。現行の第24条の27第1項第1号。","r":[["貸金業法","24の27"]]},"d":{"t":true,"w":"貸金業法第24条の27第1項第7号、第24条の30第2号。","r":[["貸金業法","24の27"],["貸金業法","24の30"]]}}},"05-12":{"s":"金利の規制を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"営業的金銭消費貸借の賠償額の予定の上限は、「1.46倍」ではなく「年2割」です。","w":"利息制限法第7条第1項。","r":[["利息制限法","7"]]},"2":{"t":false,"p":"保証料の契約が無効になるのは「すべて」ではなく、上限を「超える部分」です。","w":"利息制限法第8条第1項。","r":[["利息制限法","8"]]},"3":{"t":false,"p":"出資法で刑事罰の対象となるのは、業として年20％を「超える」利息の契約です。年20％ちょうどは対象に「なりません」。","w":"出資法第5条第2項。","r":[["出資法","5"]]},"4":{"t":true,"w":"貸金業法第42条第1項。","r":[["貸金業法","42"]]}}},"05-13":{"s":"利息制限法の元本額の特則と貸金業法の行政処分を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"利息制限法第5条第1号：残高25万円＋5万円＝30万円で上限は年1割8分。上限を超える利息の契約は貸金業法第12条の8第1項に違反し、行政処分（第24条の6の3など）の対象です。","r":[["利息制限法","5"],["貸金業法","12の8"]]},"2":{"t":false,"p":"第二の貸付けの元本とみなされる額は5万円＋20万円＝25万円なので、上限は1割6分ではなく「年1割8分」です。年18％は無効に「なりません」。","w":"利息制限法第5条第1号、第1条第2号。","r":[["利息制限法","5"],["利息制限法","1"]]},"3":{"t":false,"p":"元本額の特則は「同一の債権者」からの重ねての貸付けの場合です。子会社Ｚ社の貸付け（元本85万円）の上限は年1割8分で、無効に「なりません」。","w":"利息制限法第5条第1号。","r":[["利息制限法","5"],["利息制限法","1"]]},"4":{"t":false,"p":"3番目の貸付けの元本とみなされる額は、残高5万円＋10万円＋5万円＝20万円なので、上限は1割5分ではなく「年1割8分」です。","w":"利息制限法第5条第1号、第1条第2号。","r":[["利息制限法","5"],["利息制限法","1"]]}}},"05-14":{"s":"業務を第三者に委託する場合の措置（施行規則第10条の5）を問う問題です。ａ〜ｄはすべて定められているので4個です。","items":{"a":{"t":true,"w":"施行規則第10条の5第1号。","r":[["貸金業法施行規則","10の5"]]},"b":{"t":true,"w":"施行規則第10条の5第2号。","r":[["貸金業法施行規則","10の5"]]},"c":{"t":true,"w":"施行規則第10条の5第3号。","r":[["貸金業法施行規則","10の5"]]},"d":{"t":true,"w":"施行規則第10条の5第4号。","r":[["貸金業法施行規則","10の5"]]}}},"05-15":{"s":"債権譲渡等の規制を問う問題です。正しい組合せは「ａ誤・ｂ誤・ｃ誤・ｄ正」です。","items":{"a":{"t":false,"p":"債権の譲受人は、貸金業者でなくても、準用される規定（取立て行為の規制など）に違反すれば刑事罰を科されることが「あります」。","w":"貸金業法第24条第2項（第21条などの準用）、第47条の3第1項第3号。","r":[["貸金業法","24"],["貸金業法","47の3"]]},"b":{"t":false,"p":"通知を電磁的方法で提供するには、債権を譲り受ける者の承諾を得る必要が「あります」。","w":"施行規則第21条第4項。","r":[["貸金業法施行規則","21"]]},"c":{"t":false,"p":"通知するのは、貸金業法の「すべての規定」ではなく、第24条第1項に列挙された「一部の規定」（第12条の7、第16条の2第3項など）の適用がある旨です。","w":"貸金業法第24条第1項。","r":[["貸金業法","24"]]},"d":{"t":true,"w":"施行規則第21条第1項第3号（第17条第3項の事項。保証期間・保証の範囲など第16条の2第3項の事項を含む）。","r":[["貸金業法施行規則","21"],["貸金業法","16の2"]]}}},"05-16":{"s":"返済能力の調査を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"貸金業法第13条第1項（媒介の契約も貸付けの契約に含まれ、法人顧客も調査の対象です）。","r":[["貸金業法","13"]]},"2":{"t":true,"w":"貸金業法第13条第2項。","r":[["貸金業法","13"]]},"3":{"t":false,"p":"勤務先の変更後の勤務先が確認され、かつ変更後の勤務先で「2月分以上の給与の支払を受けていない」場合は、変更前の書面等を用いることが「できます」。2か月分以上の給与を受けているか否かを問わず必要なわけではありません。","w":"施行規則第10条の17第3項。","r":[["貸金業法施行規則","10の17"]]},"4":{"t":true,"w":"貸金業法第13条第4項、施行規則第10条の18第1項。","r":[["貸金業法","13"],["貸金業法施行規則","10の18"]]}}},"05-17":{"s":"登録の拒否事由を問う問題です。該当しないのは②です。","items":{"1":{"t":true,"w":"貸金業法第6条第1項第3号（第24条の6の5第1項第4号による取消し）。","r":[["貸金業法","6"],["貸金業法","24の6の5"]]},"2":{"t":false,"p":"拒否事由は「破産手続開始の決定を受けて復権を得ない者」です。復権を得ていれば、5年を経過していなくても該当「しません」。","w":"貸金業法第6条第1項第2号。","r":[["貸金業法","6"]]},"3":{"t":true,"w":"貸金業法第6条第1項第6号。","r":[["貸金業法","6"]]},"4":{"t":true,"w":"貸金業法第6条第1項第13号。","r":[["貸金業法","6"]]}}},"05-18":{"s":"保証人となろうとする者の返済能力の調査を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"貸金業法第13条第1項の違反は、第24条の6の4第1項第2号により行政処分の対象です。","r":[["貸金業法","13"],["貸金業法","24の6の4"]]},"2":{"t":false,"p":"資力を明らかにする書面等の提出義務は「個人顧客」についてのもので、保証人となろうとする者は対象では「ありません」。","w":"貸金業法第13条第3項。","r":[["貸金業法","13"]]},"3":{"t":true,"w":"貸金業法第48条第1項第1号の4：第13条第2項の場合に信用情報を使用した調査をしなかった者は刑事罰の対象です。","r":[["貸金業法","13"],["貸金業法","48"]]},"4":{"t":true,"w":"施行規則第10条の18第2項第2号。","r":[["貸金業法施行規則","10の18"]]}}},"05-19":{"s":"極度額の増額と返済能力の調査を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"貸金業法第13条第5項（第2項の準用）。","r":[["貸金業法","13"]]},"2":{"t":true,"w":"施行規則第10条の19。","r":[["貸金業法施行規則","10の19"]]},"3":{"t":false,"p":"返済能力の低下を理由に減額した後の増額は、調査が不要な場合に当たらず、調査が「必要」です。","w":"施行規則第10条の19（不要なのは連絡できないことを理由とする一時的な減額の場合で、返済能力の低下による場合を除く）。","r":[["貸金業法施行規則","10の19"]]},"4":{"t":true,"w":"貸金業法第13条第5項で準用する第4項、施行規則第10条の18。","r":[["貸金業法","13"],["貸金業法施行規則","10の18"]]}}},"05-20":{"s":"個人過剰貸付契約から除かれる契約を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"施行規則第10条の22第1項。","r":[["貸金業法施行規則","10の22"]]},"2":{"t":true,"w":"施行規則第10条の21第1項第3号。","r":[["貸金業法施行規則","10の21"]]},"3":{"t":false,"p":"不動産担保貸付けの除外では、個人顧客や担保を提供する者の「居宅」などは担保の対象から除かれています。親族（担保提供者）の居宅を担保とする貸付けは該当「しません」。","w":"施行規則第10条の21第1項第6号。","r":[["貸金業法施行規則","10の21"]]},"4":{"t":true,"w":"施行規則第10条の21第1項第7号。","r":[["貸金業法施行規則","10の21"]]}}},"05-21":{"s":"契約締結時の書面・極度方式基本契約の書面の再交付を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"施行規則第13条第2項第1号イ。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"2":{"t":false,"p":"新たに物的担保を供させることとした場合は、担保の内容を記載した書面の再交付が「必要」です。","w":"施行規則第13条第2項第1号ロ（第1項第1号ル）。","r":[["貸金業法施行規則","13"]]},"3":{"t":true,"w":"施行規則第13条第2項柱書（変更の内容が第17条第2項後段の書面に記載されている場合は除かれます）。","r":[["貸金業法施行規則","13"]]},"4":{"t":true,"w":"施行規則第13条第5項第2号。","r":[["貸金業法施行規則","13"]]}}},"05-22":{"s":"極度方式保証契約の書面を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"貸金業法第16条の2第3項、施行規則第12条の2第7項。","r":[["貸金業法","16の2"],["貸金業法施行規則","12の2"]]},"2":{"t":true,"w":"施行規則第13条第11項。","r":[["貸金業法施行規則","13"]]},"3":{"t":false,"p":"極度方式保証契約における契約締結時の書面を交付する相手は、極度方式基本契約の相手方（主たる債務者）ではなく「保証人」です。","w":"貸金業法第17条第5項。","r":[["貸金業法","17"]]},"4":{"t":true,"w":"貸金業法第17条第5項後段。","r":[["貸金業法","17"]]}}},"05-23":{"s":"取立て行為の規制を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"貸金業法第21条第3項。","r":[["貸金業法","21"]]},"2":{"t":false,"p":"第43条により貸金業者とみなされる者（登録が効力を失った後に取引を結了する者など）も、取立てに当たり商号や従業者の氏名などを明らかにする必要が「あります」。","w":"貸金業法第43条（取引を結了する目的の範囲内で貸金業者とみなす）、第21条第3項。","r":[["貸金業法","43"],["貸金業法","21"]]},"3":{"t":true,"w":"施行規則第19条第5項（保証人に対し取立てをするときは第17条第3項の事項など）。","r":[["貸金業法施行規則","19"]]},"4":{"t":true,"w":"貸金業法第49条第7号（刑事罰）、第24条の6の4第1項第2号（行政処分）。","r":[["貸金業法","21"],["貸金業法","49"]]}}},"05-24":{"s":"債権の取立ての委託を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"個人である貸金業者の親族は、密接な関係を有する者に「該当します」。","w":"貸金業法施行令第3条の7第1号。","r":[["貸金業法施行令","3の7"],["貸金業法","24"]]},"2":{"t":true,"w":"貸金業法第24条第3項第2号。","r":[["貸金業法","24"]]},"3":{"t":true,"w":"貸金業法第24条第3項（取立て制限者）。","r":[["貸金業法","24"]]},"4":{"t":true,"w":"貸金業法第24条第4項。","r":[["貸金業法","24"]]}}},"05-25":{"s":"業務改善命令と監督上の処分を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"業務改善命令は、法令違反の事実を認定した上で「命じなければならない」ものではなく、資金需要者等の利益の保護を図るため必要があると認めるときに、必要の限度で「命ずることができる」ものです。","w":"貸金業法第24条の6の3第1項。","r":[["貸金業法","24の6の3"]]},"2":{"t":true,"w":"貸金業法第24条の6の8。","r":[["貸金業法","24の6の8"]]},"3":{"t":true,"w":"貸金業法第6条第1項第12号（暴力団員等を業務の補助者として使用するおそれのある者）、第24条の6の5第1項第1号（取り消さなければならない）。","r":[["貸金業法","6"],["貸金業法","24の6の5"]]},"4":{"t":true,"w":"貸金業法第12条の7の違反は、第24条の6の4第1項第2号により行政処分の対象です。","r":[["貸金業法","12の7"],["貸金業法","24の6の4"]]}}},"05-26":{"s":"指定信用情報機関への情報提供と同意を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"施行規則第30条の14第2項・第1条の2の3第1号：極度方式基本契約は、第41条の36第2項の同意を要しない契約です。","r":[["貸金業法","41の36"],["貸金業法施行規則","30の14"]]},"2":{"t":true,"w":"貸金業法第41条の35第3項。","r":[["貸金業法","41の35"]]},"3":{"t":true,"w":"貸金業法第41条の36第3項、施行規則第30条の16第1項。","r":[["貸金業法","41の36"],["貸金業法施行規則","30の16"]]},"4":{"t":false,"p":"加入前に締結した極度方式基本契約に基づく極度方式貸付け（加入前極度方式貸付契約）については、あらかじめ同意を得る必要は「ありません」。","w":"貸金業法第41条の36第2項ただし書。前半の同意不要の部分は施行規則第30条の14第1項第2号。","r":[["貸金業法","41の36"],["貸金業法施行規則","30の14"]]}}},"05-27":{"s":"出資法で利息とみなされないものを問う問題です。除かれるのはａｂｄです。","items":{"a":{"t":true,"w":"出資法第5条の4第4項第2号（貸付けの相手方の要請により行う事務の費用として政令で定めるもの）。政令の細目は取り込んだ資料にないため公式正答によります。","r":[["出資法","5の4"]]},"b":{"t":true,"w":"出資法第5条の4第4項第2号（カードの再発行に係る手数料）。","r":[["出資法","5の4"]]},"c":{"t":false,"p":"現金自動支払機などの利用料が利息とみなされないのは「政令で定める額の範囲内」のものに限られ、2万円の弁済で315円は範囲を超えるので、利息とみなされ「ます」（公式正答による）。","w":"出資法第5条の4第4項第1号ハ。政令で定める額は取り込んだ資料で確認できません。","r":[["出資法","5の4"]]},"d":{"t":true,"w":"出資法第5条の4第4項第1号ロ。","r":[["出資法","5の4"]]}}},"05-28":{"s":"意思表示を問う問題です。適切なのは③です。","law":"この回の基準日は2020年4月の民法改正の前で、錯誤は「無効」とされていました。現行の第95条では「取り消すことができる」とされ、動機の錯誤（法律行為の基礎とした事情についての錯誤）は、その事情が法律行為の基礎とされていることが表示されていたときに限り取り消すことができます（第95条第2項）。","items":{"1":{"t":false,"p":"動機（縁由）は、表示されていなければ法律行為の要素とは「なりません」（公式正答による）。","w":"現行の民法第95条第2項でも、基礎とした事情の錯誤は、それが表示されていたときに限り取消しの対象となります。","r":[["民法","95"]]},"2":{"t":false,"p":"無効な行為を追認しても、初めから有効にはならず、「新たな行為をしたもの」とみなされます（出題時の民法での錯誤無効の扱い）。","w":"民法第119条。現行法では錯誤は取消しの原因です。","r":[["民法","119"]]},"3":{"t":true,"w":"民法第122条、第124条第1項。","r":[["民法","122"],["民法","124"]]},"4":{"t":false,"p":"第三者保護の規定（第96条第3項）は「詐欺」による取消しについてのもので、強迫による取消しは善意の第三者にも対抗「できます」。","w":"民法第96条第3項。","r":[["民法","96"]]}}},"05-29":{"s":"代理を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"相手方Ｂが本人Ａのためにすることを知っていたときは、契約は本人Ａに対して直接に効力を「生じます」。","w":"民法第100条ただし書、第99条第1項。","r":[["民法","100"],["民法","99"]]},"2":{"t":true,"w":"民法第108条第1項（双方代理は代理権を有しない者がした行為とみなす）。","r":[["民法","108"]]},"3":{"t":false,"p":"任意代理人は、本人の許諾がなくても、「やむを得ない事由があるとき」は復代理人を選任「できます」。","w":"民法第104条。","r":[["民法","104"]]},"4":{"t":false,"p":"権限外の行為の表見代理は、相手方に代理権があると信ずべき正当な理由があるときに成立します。Ｂが代理権がないことを知っていたなら、当然には効力を「生じません」。","w":"民法第110条。","r":[["民法","110"]]}}},"05-30":{"s":"期間の計算・利息の発生・期限の利益を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"民法第142条：期間の末日が日曜日などで、その日に取引をしない慣習がある場合は、翌日に満了します。","r":[["民法","142"]]},"2":{"t":false,"p":"利息は、借主が金銭を「受け取った日」以後について生じるので、10月15日の分の利息も支払う義務が「あります」。","w":"民法第589条第2項（現行法で明文化。出題時の結論は公式正答による）。","r":[["民法","589"]]},"3":{"t":false,"p":"初日（9月1日）は算入しないので9月2日から起算し、返済期限は「11月30日」ではなく「12月1日」です。","w":"民法第140条、第143条第2項。","r":[["民法","140"],["民法","143"]]},"4":{"t":false,"p":"借主は、期限の利益を放棄して、返済期日の前でも返済「できます」。","w":"民法第136条第2項、第591条第2項。","r":[["民法","136"],["民法","591"]]}}},"05-31":{"s":"消滅時効と時効の中断を問う問題です。正しい組合せは「ａ正・ｂ誤・ｃ正・ｄ誤」です。","law":"この回の基準日は2020年4月の民法改正の前です。現行の第166条第1項では、債権の消滅時効は「権利を行使することができることを知った時から5年」又は「権利を行使することができる時から10年」です。また「時効の中断」は「完成猶予・更新」に改められ、裁判上の請求が取下げなどで終わったときも、終了の時から6箇月は時効の完成が猶予されます（第147条第1項）。","items":{"a":{"t":true,"w":"出題時の民法（旧第166条第1項）による記述です（公式正答による）。現行の第166条第1項第2号を参照。","r":[["民法","166"]]},"b":{"t":false,"p":"承認には、相手方の権利についての処分につき行為能力（の制限を受けていないこと）又は権限があることを「要しません」。","w":"民法第152条第2項。","r":[["民法","152"]]},"c":{"t":true,"w":"出題時の民法（旧第149条）による記述です（公式正答による）。現行の第147条第1項を参照。","r":[["民法","147"]]},"d":{"t":false,"p":"時効の利益は、あらかじめ放棄することが「できません」。","w":"民法第146条。","r":[["民法","146"]]}}},"05-32":{"s":"連帯債務を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"1人について無効の原因があっても、他の連帯債務者の債務は効力を「妨げられません」。","w":"民法第437条。","r":[["民法","437"]]},"2":{"t":false,"p":"1人による債務の承認は、他の連帯債務者に対して効力を「生じません」（相対的効力）。","w":"民法第441条。","r":[["民法","441"]]},"3":{"t":false,"p":"1人と債権者との間の更改は、債権が全ての連帯債務者の利益のために消滅する（他の連帯債務者の債務も消滅する）効力を「生じます」。","w":"民法第438条。","r":[["民法","438"]]},"4":{"t":true,"w":"民法第439条第1項。","r":[["民法","439"]]}}},"05-33":{"s":"連帯保証人の求償と時効を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"民法第461条第1項。","r":[["民法","461"]]},"2":{"t":false,"p":"連帯保証人Ｃが全額を弁済したときは、他の連帯保証人Ｄに対しても（負担部分について）求償「できます」。","w":"民法第465条第1項（第442条の準用）。","r":[["民法","465"]]},"3":{"t":false,"p":"保証人が死亡しても、連帯保証契約は当然には終了せず、保証債務は相続人に「承継されます」（公式正答による）。","w":"民法第896条（相続人は被相続人の財産に属した一切の権利義務を承継する）。","r":[["民法","896"]]},"4":{"t":false,"p":"主たる債務者の承認による時効の中断（現行法では更新）は、委託を受けたかどうかにかかわらず、保証人Ｄにも効力を「生じます」。","w":"民法第457条第1項。","r":[["民法","457"]]}}},"05-34":{"s":"金銭消費貸借を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"消費貸借は、原則として金銭を「受け取ることによって」効力を生じる要物契約です（現行法では書面でする消費貸借に限り諾成契約が認められています）。","w":"民法第587条、第587条の2第1項。","r":[["民法","587"],["民法","587の2"]]},"2":{"t":true,"w":"民法第588条（準消費貸借）。","r":[["民法","588"]]},"3":{"t":false,"p":"返還の時期を定めなかったときは、貸主は「直ちに」ではなく、「相当の期間を定めて」返還を催告できます。","w":"民法第591条第1項。","r":[["民法","591"]]},"4":{"t":false,"p":"利息の特約がなければ、貸主は利息を請求「できません」（年5分の利息が生じるわけではありません）。","w":"民法第589条第1項。","r":[["民法","589"]]}}},"05-35":{"s":"犯罪収益移転防止法を問う問題です。ａ〜ｄはすべて適切です。","law":"出題時の「本人確認」「本人確認記録」は、現行法では「取引時確認」「確認記録」と呼ばれ、確認事項も本人特定事項のほか取引を行う目的・職業などに広がっています（第4条第1項）。","items":{"a":{"t":true,"w":"犯罪収益移転防止法第4条第1項第1号。","r":[["犯収法","4"]]},"b":{"t":true,"w":"犯罪収益移転防止法第4条第1項（特定取引）。","r":[["犯収法","4"]]},"c":{"t":true,"w":"犯罪収益移転防止法第6条第2項（現行法では確認記録）。","r":[["犯収法","6"]]},"d":{"t":true,"w":"犯罪収益移転防止法第5条。","r":[["犯収法","5"]]}}},"05-36":{"s":"相続を問う問題です。公式正答はａｂｄの3個です。","law":"ａの「遺留分減殺請求」は、2019年施行の改正で「遺留分侵害額の請求」（金銭の支払を請求する権利。第1046条）に改められました。現行法では贈与の「減殺」を請求するのではないため、ａは条文どおりではありません。","items":{"a":{"t":true,"now":false,"p":"現行法では、贈与の「減殺」ではなく、受贈者に対して「遺留分侵害額に相当する金銭の支払」を請求します。","w":"出題時の民法（旧第1031条）による記述です（公式正答による）。現行の民法第1046条第1項、第1048条（期間の制限）。","r":[["民法","1046"],["民法","1048"]]},"b":{"t":true,"w":"民法第900条第1号・第4号。","r":[["民法","900"]]},"c":{"t":false,"p":"単純承認は単独でできますが、限定承認は共同相続人の「全員が共同して」のみすることができます。","w":"民法第923条。","r":[["民法","923"]]},"d":{"t":true,"w":"民法第938条。","r":[["民法","938"]]}}},"05-37":{"s":"弁済（場所・第三者弁済・代位・費用）を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"民法第484条第1項。","r":[["民法","484"]]},"2":{"t":false,"p":"物上保証人Ｃは弁済について正当な利益（法律上の利害関係）を有するので、債務者Ａの意思に反しても弁済「できます」。","w":"民法第474条第2項（制限されるのは正当な利益を有しない第三者）。","r":[["民法","474"]]},"3":{"t":true,"w":"出題時の民法（旧第499条）による記述です。現行の第499条では債権者の承諾がなくても代位でき、債務者・第三者への対抗には第467条の通知・承諾が必要です（第500条）。","r":[["民法","499"],["民法","500"]]},"4":{"t":true,"w":"民法第485条。","r":[["民法","485"]]}}},"05-38":{"s":"債務不履行に基づく損害賠償を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"民法第416条第2項（現行の条文は「当事者がその事情を予見すべきであったとき」。出題時は「予見し、又は予見することができたとき」）。","r":[["民法","416"]]},"2":{"t":true,"w":"民法第418条。","r":[["民法","418"]]},"3":{"t":false,"p":"出題時の民法では、賠償額の予定があるときは、裁判所はその額を増減することが「できない」とされていました（旧第420条第1項後段、公式正答による）。実際の損害額が上回っても増額されません。","w":"現行の民法第420条第1項は、損害賠償の額を予定できることだけを定めています。","r":[["民法","420"]]},"4":{"t":true,"w":"民法第422条。","r":[["民法","422"]]}}},"05-39":{"s":"約束手形と電子記録債権を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"手形法第10条（約束手形には第77条第2項で準用）。","r":[["手形法","10"],["手形法","77"]]},"2":{"t":true,"w":"手形法第38条第1項（約束手形には第77条第1項第3号で準用）。","r":[["手形法","38"]]},"3":{"t":true,"w":"電子記録債権法第17条。","r":[["電子記録債権法","17"]]},"4":{"t":false,"p":"支払が有効になるのは、支払をした者に悪意又は重大な過失が「ない」ときに限られます。","w":"電子記録債権法第21条ただし書。","r":[["電子記録債権法","21"]]}}},"05-40":{"s":"民事訴訟手続を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"民事訴訟法第5条第1号。","r":[["民事訴訟法","5"]]},"2":{"t":true,"w":"民事訴訟法第245条。","r":[["民事訴訟法","245"]]},"3":{"t":false,"p":"簡易裁判所は、訴訟が自らの管轄に属する場合でも、相当と認めるときは、地方裁判所に移送「できます」。","w":"民事訴訟法第18条（簡易裁判所の裁量移送）。","r":[["民事訴訟法","18"]]},"4":{"t":true,"w":"民事訴訟法第393条。","r":[["民事訴訟法","393"]]}}},"05-41":{"s":"債権に対する強制執行（民事執行法）を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"民事執行法第143条。","r":[["民事執行法","143"]]},"2":{"t":true,"w":"民事執行法第147条第1項。","r":[["民事執行法","147"]]},"3":{"t":false,"p":"差押債権者が取り立てられるのは、差押命令が債務者に送達された日から「2週間」ではなく「1週間」を経過したときです（現行法では、給料などの差押禁止債権の一部を差し押さえた場合は4週間）。","w":"民事執行法第155条第1項・第2項。","r":[["民事執行法","155"]]},"4":{"t":true,"w":"民事執行法第154条第1項。","r":[["民事執行法","154"]]}}},"05-42":{"s":"個人再生（民事再生法）を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"民事再生法第221条第1項。","r":[["民事再生法","221"]]},"2":{"t":false,"p":"再生計画案を決議に付す代わりに届出再生債権者の意見を聴くのは、「小規模個人再生」ではなく「給与所得者等再生」です。小規模個人再生では、再生計画案を決議に付します。","w":"民事再生法第230条（小規模個人再生の決議）、第240条（給与所得者等再生の意見聴取）。","r":[["民事再生法","230"],["民事再生法","240"]]},"3":{"t":true,"w":"民事再生法第239条第1項。","r":[["民事再生法","239"]]},"4":{"t":true,"w":"民事再生法第196条第3号。","r":[["民事再生法","196"]]}}},"05-43":{"s":"個人データの第三者提供を問う問題です。公式正答はｄの1個です。","law":"ｄのオプトアウト（本人の求めに応じて提供を停止する方法による第三者提供）は、2017年施行の改正以降、通知等の事項が増え、個人情報保護委員会への届出も必要になりました（現行の第27条第2項）。現行法では、記述の事項を通知等するだけでは第三者に提供できません。","items":{"a":{"t":false,"p":"親子会社であっても別の法人なので「第三者に該当します」。共同利用の要件を満たさなければ、本人の同意なく提供「できません」。","w":"個人情報保護法第27条第1項・第5項第3号。","r":[["個人情報保護法","27"]]},"b":{"t":false,"p":"利用目的の達成に必要な範囲内での委託に伴う提供は、委託先が第三者に当たらないので、本人の同意は「不要」です。","w":"個人情報保護法第27条第5項第1号。","r":[["個人情報保護法","27"]]},"c":{"t":false,"p":"合併による事業の承継に伴う提供は、承継先が第三者に当たらないので、本人の同意は「不要」です。","w":"個人情報保護法第27条第5項第2号。","r":[["個人情報保護法","27"]]},"d":{"t":true,"now":false,"p":"現行法では、記述の事項に加え、提供する事業者の氏名・住所、取得の方法、本人の求めを受け付ける方法などを通知等し、「個人情報保護委員会に届け出る」必要があります。","w":"出題時の個人情報保護法による記述です（公式正答による）。現行の第27条第2項。","r":[["個人情報保護法","27"]]}}},"05-44":{"s":"消費者契約法を問う問題です。公式正答は④です。","law":"④の取消権の行使期間は、出題時は追認できる時から6か月間でしたが、現行の第7条第1項では1年間（霊感等による告知の場合は3年間）に延びています。","items":{"1":{"t":false,"p":"消費者契約法は、政令で指定された商品等の契約に限られず、消費者と事業者との間で締結される「すべての契約」に適用されます。","w":"消費者契約法第2条第3項。","r":[["消費者契約法","2"]]},"2":{"t":false,"p":"消費者契約法には、クーリング・オフの権利を定める規定は「ありません」（公式正答による）。","w":"消費者契約法が定めるのは、誤認・困惑などによる取消し（第4条）と不当条項の無効（第8条〜第10条）などです。","r":[["消費者契約法","4"]]},"3":{"t":false,"p":"事業者の情報提供は、書面で説明する「義務」ではなく、「努めなければならない」（努力義務）とされています。","w":"消費者契約法第3条第1項。","r":[["消費者契約法","3"]]},"4":{"t":true,"now":false,"p":"現行法では、追認できる時からの期間は「6か月間」ではなく「1年間」です。","w":"出題時の消費者契約法による記述です（公式正答による）。現行の第7条第1項。","r":[["消費者契約法","7"]]}}},"05-45":{"s":"景品表示法の「表示」と不当表示の穴埋め問題です。正しいのは①です（ア内閣総理大臣・イ品質、規格その他の内容・ウ一般消費者・エ価格その他の取引条件）。","items":{"1":{"t":true,"w":"景品表示法第2条第4項（表示は内閣総理大臣が指定）、現行の第5条第1号（優良誤認表示：品質、規格その他の内容）・第2号（有利誤認表示：価格その他の取引条件）。いずれも「一般消費者」に誤認される表示です。","r":[["景品表示法","2"],["景品表示法","5"]]},"2":{"t":false,"p":"イとエが逆です（イは「品質、規格その他の内容」、エは「価格その他の取引条件」）。ウは「競業事業者」ではなく「一般消費者」です。"},"3":{"t":false,"p":"アは「公正取引委員会」ではなく「内閣総理大臣」、ウは「競業事業者」ではなく「一般消費者」です。"},"4":{"t":false,"p":"アは「公正取引委員会」ではなく「内閣総理大臣」です。また、イとエが逆です。"}}},"05-46":{"s":"総量規制の例外（施行規則第10条の23）を問う問題です。該当するのはｃｄです。","items":{"a":{"t":false,"p":"借換えの例外に当たるには、1か月の負担が既存債務の1か月の負担を「上回らない」ことが必要です。","w":"施行規則第10条の23第1項第1号イ。","r":[["貸金業法施行規則","10の23"]]},"b":{"t":false,"p":"つなぎ融資の例外は、返済期間が1か月を「超えない」ものに限られます。","w":"施行規則第10条の23第1項第6号ロ。","r":[["貸金業法施行規則","10の23"]]},"c":{"t":true,"w":"施行規則第10条の23第1項第4号。","r":[["貸金業法施行規則","10の23"]]},"d":{"t":true,"w":"施行規則第10条の23第1項第2号。","r":[["貸金業法施行規則","10の23"]]}}},"05-47":{"s":"帳簿の閲覧・謄写を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"公式正答では適切です。監督指針Ⅱ－２－１８（１）①：閲覧又は謄写の方法に関し、正当な理由なく過度な負担を課す場合は、拒否に該当するおそれがあるとされています。","r":[["貸金業法","19の2"]]},"2":{"t":false,"p":"債務者等に代わって弁済をした者も請求権者なので、債務者本人でないことを理由に拒否「できません」。","w":"施行規則第17条の2第1項第3号。","r":[["貸金業法","19の2"],["貸金業法施行規則","17の2"]]},"3":{"t":true,"w":"公式正答では適切です。監督指針Ⅱ－２－１８（１）①（正当な理由なく過度な負担を課す場合）。","r":[["貸金業法","19の2"]]},"4":{"t":true,"w":"監督指針Ⅱ－２－１８（１）③：複写などの実費を徴収する場合は、適正かつ適切な金額であることが求められます。","r":[["貸金業法","19の2"]]}}},"05-48":{"s":"企業会計原則の一般原則と注解を問う問題です。正しい組合せは「ａ正・ｂ誤・ｃ正・ｄ正」です。","items":{"a":{"t":true,"w":"企業会計原則注解〔注1－3〕。","r":[]},"b":{"t":false,"p":"重要性の乏しいものについて簡便な方法によることも、正規の簿記の原則に従った処理として「認められます」（重要性の原則）。","w":"企業会計原則注解〔注1〕。","r":[]},"c":{"t":true,"w":"企業会計原則注解〔注1－2〕。","r":[]},"d":{"t":true,"w":"企業会計原則注解〔注4〕（保守主義の原則）。","r":[]}}},"05-49":{"s":"会社法の計算書類の穴埋め問題です。正しいのは④です（ア財産及び損益・イ附属明細書・ウ定款・エ定時株主総会）。","items":{"1":{"t":false,"p":"アは「内部統制」ではなく「財産及び損益」、イは「営業報告」ではなく「附属明細書」、エは「会計参与」ではなく「定時株主総会」です。"},"2":{"t":false,"p":"アは「内部統制」ではなく「財産及び損益」、ウは「法令」ではなく「定款」、エは「会計参与」ではなく「定時株主総会」です。"},"3":{"t":false,"p":"イは「営業報告」ではなく「附属明細書」、ウは「法令」ではなく「定款」です。"},"4":{"t":true,"w":"会社法第435条第2項、第436条第1項、第438条第1項第1号。","r":[["会社法","435"],["会社法","436"],["会社法","438"]]}}},"05-50":{"s":"資力を明らかにする書面を問う問題です。ａ〜ｄはすべて該当し得るので4個です。","items":{"a":{"t":true,"w":"施行規則第10条の17第1項第7号の2・第2項。","r":[["貸金業法施行規則","10の17"]]},"b":{"t":true,"w":"施行規則第10条の17第1項第3号・第2項。","r":[["貸金業法施行規則","10の17"]]},"c":{"t":true,"w":"施行規則第10条の17第1項第5号・第2項。","r":[["貸金業法施行規則","10の17"]]},"d":{"t":true,"w":"施行規則第10条の17第1項第9号。","r":[["貸金業法施行規則","10の17"]]}}},"06-01":{"s":"貸金業法の用語を問う問題です。適切なのはａｄの2個です。","items":{"a":{"t":true,"w":"貸金業法第2条第3項。","r":[["貸金業法","2"]]},"b":{"t":false,"p":"事業者がその従業者に対して行う貸付けは、貸金業に「含まれません」。","w":"貸金業法第2条第1項第4号。","r":[["貸金業法","2"]]},"c":{"t":false,"p":"同一敷地内に設置しても営業所等に当たらないのは「現金自動設備」だけです。「自動契約受付機」は営業所又は事務所に「該当します」。","w":"施行規則第1条の5第3項。","r":[["貸金業法施行規則","1の5"]]},"d":{"t":true,"w":"施行規則第2条第1号。","r":[["貸金業法","4"],["貸金業法施行規則","2"]]}}},"06-02":{"s":"登録の更新を問う問題です。適切なのはｂｃｄです。","items":{"a":{"t":false,"p":"更新の申請期限は、有効期間満了の日「まで」ではなく、満了の日の「2月前まで」です。","w":"施行規則第5条。","r":[["貸金業法施行規則","5"]]},"b":{"t":true,"w":"監督指針Ⅲ－３－１（２）⑥イ。","r":[["貸金業法","6"]]},"c":{"t":true,"w":"貸金業法第3条第2項。","r":[["貸金業法","3"]]},"d":{"t":true,"w":"貸金業法第3条第3項、施行令第2条第1項（手数料15万円）。","r":[["貸金業法","3"],["貸金業法施行令","2"]]}}},"06-03":{"s":"変更の届出（貸金業法第8条）を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"貸金業法第8条第1項・第3項、施行規則第7条（別紙様式第5号の変更届出書と添付書類）。添付書類の細目は公式正答によります。","r":[["貸金業法","8"],["貸金業法施行規則","7"]]},"2":{"t":false,"p":"業務の種類の変更も、2週間以内に届け出る「必要があります」。","w":"貸金業法第8条第1項、第4条第1項第8号。","r":[["貸金業法","8"],["貸金業法","4"]]},"3":{"t":false,"p":"政令で定める使用人の変更は、「あらかじめ」ではなく、変更の日から「2週間以内」に届け出ます。","w":"貸金業法第8条第1項、第4条第1項第2号。","r":[["貸金業法","8"],["貸金業法","4"]]},"4":{"t":false,"p":"広告等で表示する電子メールアドレスの変更は、変更後2週間以内ではなく、「あらかじめ」届け出ます。","w":"貸金業法第8条第1項、第4条第1項第7号、施行規則第3条の2（連絡先等）。","r":[["貸金業法","8"],["貸金業法","4"]]}}},"06-04":{"s":"廃業等の届出（貸金業法第10条）を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"届け出るのは、消滅した法人の「役員であった者」なら誰でもよいのではなく、「法人を代表する役員であった者」です。","w":"貸金業法第10条第1項第2号。","r":[["貸金業法","10"]]},"2":{"t":false,"p":"相続人の届出期限は、死亡した日からではなく、死亡の事実を「知った日」から30日以内です。","w":"貸金業法第10条第1項第1号。","r":[["貸金業法","10"]]},"3":{"t":true,"w":"施行規則第10条第1項（別紙様式第6号の廃業等届出書）。記載事項の細目は公式正答によります。","r":[["貸金業法施行規則","10"]]},"4":{"t":false,"p":"届出が必要なのは、破産手続開始の「申立て」をしたときではなく、破産手続開始の「決定」があったときで、届け出るのは「破産管財人」です。","w":"貸金業法第10条第1項第3号。","r":[["貸金業法","10"]]}}},"06-05":{"s":"禁止行為（貸金業法第12条の6）と罰則を問う問題です。適切なのはｂｃの2個です。","items":{"a":{"t":false,"p":"虚偽のことを告げる行為は、行政処分だけでなく、刑事罰の対象にも「なります」。","w":"貸金業法第48条第1項第1号の2。","r":[["貸金業法","12の6"],["貸金業法","48"]]},"b":{"t":true,"w":"第12条の6第2号の違反は罰則の対象ではなく、行政処分の対象です（罰則は第1号の虚偽告知に限られます）。","r":[["貸金業法","12の6"],["貸金業法","48"]]},"c":{"t":true,"w":"第12条の6第3号の違反も罰則の対象ではなく、行政処分の対象です。","r":[["貸金業法","12の6"],["貸金業法","48"]]},"d":{"t":false,"p":"説明が逆です。「不正な」行為とは違法な行為、「不当な」行為とは客観的に見て実質的に妥当性を欠く又は適当でない行為で、不正（違法）な程度にまで達していない行為をいいます。","w":"監督指針Ⅱ－２－１０（２）②なお書き。","r":[["貸金業法","12の6"]]}}},"06-06":{"s":"保証料の制限を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"元本確定期日の定めがない根保証契約は、元本極度額が適切でも、保証業者との間で締結「できません」。","w":"貸金業法第12条の8第9項、施行規則第10条の14第2号。","r":[["貸金業法","12の8"],["貸金業法施行規則","10の14"]]},"2":{"t":false,"p":"特約上限利率の定めがないときの保証料の上限は、法定上限額ではなく、法定上限額の「2分の1」です。","w":"利息制限法第8条第4項第2号。","r":[["利息制限法","8"]]},"3":{"t":true,"w":"利息制限法第8条第1項。","r":[["利息制限法","8"]]},"4":{"t":false,"p":"刑事罰の対象に「なります」。出資法では特約上限利率（年15％）を利息の割合とみなし、保証料（年10％）と合算すると年20％を超えるからです。","w":"出資法第5条の2第1項・第3項第1号。","r":[["出資法","5の2"]]}}},"06-07":{"s":"金銭の貸借の媒介と媒介手数料を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"制限されるのは、貸借の金額の100分の5に相当する金額「以上」ではなく、それを「超える」手数料です。","w":"出資法第4条第1項。","r":[["出資法","4"]]},"2":{"t":false,"p":"保証の期間が1年未満の場合の割合は、「年3分」ではなく「年5分（5％）」です。","w":"出資法第4条第2項。","r":[["出資法","4"]]},"3":{"t":true,"w":"貸金業法第12条の8第10項。","r":[["貸金業法","12の8"]]},"4":{"t":false,"p":"貸金業者を債権者とする金銭の貸借の媒介に係る契約は、信用情報の使用義務の対象から「除かれています」。","w":"貸金業法第13条第2項、施行規則第10条の16第2号・第1条の2の3第5号。","r":[["貸金業法","13"],["貸金業法施行規則","10の16"]]}}},"06-08":{"s":"保証人となろうとする者の返済能力の調査を問う問題です。適切なのはｃｄです。","items":{"a":{"t":false,"p":"保証人の調査の記録の保存期限は、「いずれか遅い日」ではなく「いずれか早い日」までです。","w":"施行規則第10条の18第2項第2号。","r":[["貸金業法施行規則","10の18"]]},"b":{"t":false,"p":"資力を明らかにする書面等の提出義務は「個人顧客」についてのもので、保証人となろうとする者は対象では「ありません」。","w":"貸金業法第13条第3項。","r":[["貸金業法","13"]]},"c":{"t":true,"w":"貸金業法第13条第1項の違反は、登録の取消し・業務停止の対象です（第24条の6の4第1項第2号）。","r":[["貸金業法","13"],["貸金業法","24の6の4"]]},"d":{"t":true,"w":"貸金業法第13条第2項（個人である顧客等には保証人となろうとする者を含む）。","r":[["貸金業法","13"]]}}},"06-09":{"s":"基準額超過極度方式基本契約に係る調査を問う問題です。正しい組合せは「ａ正・ｂ誤・ｃ正・ｄ誤」です。","items":{"a":{"t":true,"w":"貸金業法第13条の4、施行規則第10条の29。","r":[["貸金業法","13の4"],["貸金業法施行規則","10の29"]]},"b":{"t":false,"p":"調査の記録の保存期間は、作成後「10年間」ではなく「3年間」です。","w":"施行規則第10条の27第2項。","r":[["貸金業法施行規則","10の27"]]},"c":{"t":true,"w":"貸金業法第13条の3第2項ただし書、施行規則第10条の25第3項第2号・第3号。","r":[["貸金業法","13の3"],["貸金業法施行規則","10の25"]]},"d":{"t":false,"p":"極度方式個人顧客合算額に算入するのは、当該極度方式基本契約の極度方式貸付けの「残高」ではなく「極度額」です。","w":"貸金業法第13条の3第5項第1号。","r":[["貸金業法","13の3"]]}}},"06-10":{"s":"契約締結前の書面（貸金業法第16条の2）を問う問題です。正しい組合せは「ａ正・ｂ正・ｃ誤・ｄ誤」です。","items":{"a":{"t":true,"w":"施行規則第12条の2第1項第2号ロ。","r":[["貸金業法","16の2"],["貸金業法施行規則","12の2"]]},"b":{"t":true,"w":"貸金業法第16条の2第1項第1号〜第5号。","r":[["貸金業法","16の2"]]},"c":{"t":false,"p":"貸付けの利率は「詳細を記載した書面」に記載する事項で、「概要を記載した書面」には記載しません。","w":"施行規則第12条の2第7項第1号（概要書面は第4項第1号イ〜ハ）・第2号（詳細書面は第4項第1号ヘ（貸付けの利率）を含む）。","r":[["貸金業法施行規則","12の2"]]},"d":{"t":false,"p":"契約締結前に記載事項の内容が変わったときは、変更後の内容の契約締結前の書面を「再度交付する必要があります」。","w":"監督指針Ⅱ－２－１６（２）②。","r":[["貸金業法","16の2"]]}}},"06-11":{"s":"書面に代えて電磁的方法で提供する場合を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"公式正答では適切です（電磁的方法での提供後に受取証書の交付を求められた場合の扱いは、取り込んだ資料で確認できません）。","r":[["貸金業法","18"]]},"2":{"t":false,"p":"承諾は「書面ではなく電磁的方法」に限られず、「書面又は電磁的方法」で得ます。","w":"施行令第3条の2の5第1項。","r":[["貸金業法施行令","3の2の5"]]},"3":{"t":false,"p":"電磁的方法による承諾を受けたときは、承諾を受けた旨を書面などで通知する必要が「あります」（公式正答による）。","w":"監督指針Ⅱ－２－１６（１）④でも、一定期間の取引状況を記載した書面の交付について電磁的方法で承諾を受けた場合は、承諾を受けた旨を書面などで通知しているかが着眼点とされています。","r":[["貸金業法","17"]]},"4":{"t":false,"p":"電磁的方法で提供するには、あらかじめ相手方の承諾を得る「必要があります」。","w":"貸金業法第16条の2第4項、施行令第3条の2の5第1項。","r":[["貸金業法","16の2"],["貸金業法施行令","3の2の5"]]}}},"06-12":{"s":"帳簿（貸金業法第19条）を問う問題です。適切なのはｂｃです。","items":{"a":{"t":false,"p":"極度方式基本契約の場合の起算点は、解除の日と最終の返済期日のうち「いずれか早い日」ではなく「いずれか遅い日」です。","w":"施行規則第17条第1項ただし書。","r":[["貸金業法施行規則","17"]]},"b":{"t":true,"w":"施行規則第16条第1項第5号〜第7号。","r":[["貸金業法施行規則","16"]]},"c":{"t":true,"w":"公式正答では適切です（帳簿を電磁的記録で作成できることの根拠は、取り込んだ資料で確認できません）。","r":[["貸金業法","19"]]},"d":{"t":false,"p":"保証契約の「弁済の方法及び弁済を受ける場所」は、帳簿の記載事項から「除かれています」。","w":"施行規則第16条第1項第3号（第12条の2第6項第7号の事項を除く）。","r":[["貸金業法施行規則","16"]]}}},"06-13":{"s":"債権譲渡等の規制を問う問題です。正しい組合せは「ａ誤・ｂ正・ｃ正・ｄ正」です。","items":{"a":{"t":false,"p":"「返済の方法及び返済を受ける場所」は、譲受人に通知する事項から「除かれています」。","w":"施行規則第21条第1項第1号・第2号（第13条第1項第1号ト・第3項第1号トを除く）。","r":[["貸金業法","24"],["貸金業法施行規則","21"]]},"b":{"t":true,"w":"自主規制基本規則第67条。","r":[]},"c":{"t":true,"w":"貸金業法第24条第2項（第17条の準用）。","r":[["貸金業法","24"]]},"d":{"t":true,"w":"貸金業法第24条第2項（第24条第1項の準用）。","r":[["貸金業法","24"]]}}},"06-14":{"s":"開始等の届出（貸金業法第24条の6の2）を問う問題です。適切なのはａｃです。","items":{"a":{"t":true,"w":"貸金業法第24条の6の2第1号。","r":[["貸金業法","24の6の2"]]},"b":{"t":false,"p":"届出の期限は、「30日以内」ではなく、その日から「2週間以内」です。","w":"施行規則第26条の25第1項第6号・第2項。","r":[["貸金業法施行規則","26の25"]]},"c":{"t":true,"w":"施行規則第26条の25第1項第3号。","r":[["貸金業法施行規則","26の25"]]},"d":{"t":false,"p":"役員又は使用人に法令違反行為などがあったことを知った場合も、届け出る必要が「あります」。","w":"施行規則第26条の25第1項第1号（第6条第1項第13号に該当）・第4号（法令違反行為など）。","r":[["貸金業法施行規則","26の25"]]}}},"06-15":{"s":"指定信用情報機関に関する加入貸金業者の義務を問う問題です。適切なのはａｂｄの3個です。","items":{"a":{"t":true,"w":"貸金業法第41条の37、監督指針Ⅱ－２－１４（１）①ｅ。","r":[["貸金業法","41の37"]]},"b":{"t":true,"w":"貸金業法第41条の36第1項。","r":[["貸金業法","41の36"]]},"c":{"t":false,"p":"他の指定信用情報機関の加入貸金業者に提供する旨の同意（第41条の24の依頼に応じた提供）も、得る必要が「あります」。","w":"貸金業法第41条の36第2項第3号。","r":[["貸金業法","41の36"]]},"d":{"t":true,"w":"施行規則第30条の16第1項。","r":[["貸金業法施行規則","30の16"]]}}},"06-16":{"s":"総量規制の例外（施行規則第10条の23）を問う問題です。適切なのはｂｄです。","items":{"a":{"t":false,"p":"借換えの例外に当たるには、1か月の負担が既存の債務の1か月の負担を「上回らない」ことも必要です。","w":"施行規則第10条の23第1項第1号イ。","r":[["貸金業法施行規則","10の23"]]},"b":{"t":true,"w":"施行規則第10条の23第3項。","r":[["貸金業法施行規則","10の23"]]},"c":{"t":false,"p":"この借換えの例外（第1号の2）は、弁済する債務の「すべて」が貸金業者と締結した契約に基づく債務である場合に限られます。「一部」では該当しません。","w":"施行規則第10条の23第1項第1号の2イ。","r":[["貸金業法施行規則","10の23"]]},"d":{"t":true,"w":"施行規則第10条の23第2項。","r":[["貸金業法施行規則","10の23"]]}}},"06-17":{"s":"監督指針の内部管理態勢の着眼点を問う問題です。ａ〜ｄはすべて適切なので4個です。","items":{"a":{"t":true,"w":"監督指針Ⅱ－２－２（法人関係情報を利用したインサイダー取引等の不公正な取引の防止に係る着眼点）。","r":[]},"b":{"t":true,"w":"監督指針Ⅱ－２－３（１）⑩。","r":[]},"c":{"t":true,"w":"監督指針Ⅱ－１（１）⑥ハｃ。","r":[]},"d":{"t":true,"w":"監督指針Ⅱ－２－１（１）①。","r":[]}}},"06-18":{"s":"貸金業務取扱主任者と従業者名簿を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"貸金業法第12条の3第3項。","r":[["貸金業法","12の3"]]},"2":{"t":true,"w":"貸金業法第12条の4第2項、施行規則第10条の9の2第1項。","r":[["貸金業法","12の4"],["貸金業法施行規則","10の9の2"]]},"3":{"t":true,"w":"施行規則第10条の9の2第3項。","r":[["貸金業法施行規則","10の9の2"]]},"4":{"t":false,"p":"主任者の数は、貸金業の業務に従事する者（40人）の50分の1以上なので、「2人以上」ではなく「1人」で足ります。業務に従事していない20人は数えません。","w":"施行規則第10条の8。","r":[["貸金業法","12の3"],["貸金業法施行規則","10の8"]]}}},"06-19":{"s":"過剰貸付けの禁止（総量規制）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"貸金業法第13条の2第2項、施行規則第10条の22第1項。","r":[["貸金業法","13の2"],["貸金業法施行規則","10の22"]]},"2":{"t":true,"w":"施行規則第10条の23第1項第2号。","r":[["貸金業法施行規則","10の23"]]},"3":{"t":true,"w":"売却予定の不動産の売却代金で弁済される貸付けは、例外（第10条の23）ではなく除外（第10条の21第1項第7号）です。","r":[["貸金業法施行規則","10の21"]]},"4":{"t":false,"p":"自動車担保の購入資金の貸付けは住宅資金貸付契約等（除外契約）に当たるので、その残高は個人顧客合算額に「含まれません」。","w":"貸金業法第13条の2第2項（住宅資金貸付契約等に係る貸付けの残高を除く）、施行規則第10条の21第1項第3号。","r":[["貸金業法","13の2"],["貸金業法施行規則","10の21"]]}}},"06-20":{"s":"誇大広告の禁止等（貸金業法第16条）と罰則を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"貸金業法第16条第3項は罰則の対象ではなく、行政処分の対象です。","r":[["貸金業法","16"]]},"2":{"t":true,"w":"貸金業法第16条第1項の違反は、第48条第1項第3号により刑事罰の対象です。","r":[["貸金業法","16"],["貸金業法","48"]]},"3":{"t":false,"p":"再勧誘の禁止（第16条第4項）の違反は、行政処分の対象ですが、刑事罰の対象では「ありません」。","w":"罰則（第48条）が挙げるのは第16条第1項の違反です。","r":[["貸金業法","16"],["貸金業法","48"]]},"4":{"t":true,"w":"貸金業法第16条第2項第3号は罰則の対象ではなく、行政処分の対象です。","r":[["貸金業法","16"]]}}},"06-21":{"s":"契約締結時の書面・保証契約の書面の再交付を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"施行規則第13条第10項・第2項第1号イ（利息の計算の方法）。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"2":{"t":false,"p":"返済を受ける場所の変更は、Ｂの利益となる変更でも、再交付が「必要」です。","w":"施行規則第13条第2項第1号ロ（第1項第1号ト）。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"3":{"t":true,"w":"施行規則第13条第7項第1号イ（保証期間は第16条の2第3項第2号）。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"4":{"t":true,"w":"契約の相手方の住所は、再交付が必要な事項（施行規則第13条第2項）に含まれていません。","r":[["貸金業法施行規則","13"]]}}},"06-22":{"s":"受取証書と債権証書の返還を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"貸金業法第18条第1項第4号。","r":[["貸金業法","18"]]},"2":{"t":true,"w":"施行規則第15条第2項。","r":[["貸金業法施行規則","15"]]},"3":{"t":true,"w":"貸金業法第18条第2項。","r":[["貸金業法","18"]]},"4":{"t":false,"p":"全部の弁済を受けたときは、請求があったときに限らず、「遅滞なく」債権証書を返還しなければなりません。","w":"貸金業法第22条。","r":[["貸金業法","22"]]}}},"06-23":{"s":"貸金業者に対する監督を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"貸金業法第24条の6の10（保証業者・業務の受託者への立入検査）。","r":[["貸金業法","24の6の10"]]},"2":{"t":true,"w":"監督指針Ⅲ－３－５（みなし貸金業者の取扱い）①。","r":[["貸金業法","24の6の10"]]},"3":{"t":false,"p":"所在不明による登録取消しは、公告の日から「2週間」ではなく「30日」を経過しても申出がないときです。","w":"貸金業法第24条の6の6第1項第1号。","r":[["貸金業法","24の6の6"]]},"4":{"t":true,"w":"貸金業法第24条の6の3第1項（業務改善命令）。","r":[["貸金業法","24の6の3"]]}}},"06-24":{"s":"利息制限法・出資法・貸金業法の金利規制を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"利息制限法第1条第3号：業として行うかどうかを問わず適用されます。","r":[["利息制限法","1"]]},"2":{"t":false,"p":"出資法で刑事罰の対象となるのは、業として年20％を「超える」利息の契約です。年20％ちょうどは刑事罰の対象に「なりません」。","w":"出資法第5条第2項。利息制限法では元本11万円の上限は年1割8分なので、超過部分は無効です（第1条第2号）。","r":[["出資法","5"],["利息制限法","1"]]},"3":{"t":true,"w":"出資法第5条第1項：業として行わない場合は年109.5％を超えると刑事罰の対象。年105％は超えていません。","r":[["出資法","5"],["利息制限法","1"]]},"4":{"t":true,"w":"貸金業法第42条第1項（契約の無効）、出資法第5条第3項（業として年109.5％超）。","r":[["貸金業法","42"],["出資法","5"]]}}},"06-25":{"s":"みなし利息（利息制限法第6条）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"債務者の要請による書面の再発行や電磁的方法による再提供の手数料は、利息とみなされ「ません」。","w":"利息制限法第6条第1項、施行令第1条第2号。","r":[["利息制限法","6"],["利息制限法施行令","1"]]},"2":{"t":true,"w":"施行令第1条第3号。","r":[["利息制限法施行令","1"]]},"3":{"t":true,"w":"利息制限法第6条第2項第3号、施行令第2条第1号（1万円以下の額は110円まで。出題時は105円）。","r":[["利息制限法","6"],["利息制限法施行令","2"]]},"4":{"t":true,"w":"利息制限法第6条第2項第2号。","r":[["利息制限法","6"]]}}},"06-26":{"s":"特定非営利金融法人を問う問題です。適切でないのは②です。","law":"問題文の施行規則の条番号は出題時のものです。現行の施行規則では、特定非営利金融法人の定義は第1条の2の4第2項、信用情報の使用義務の例外は第10条の16の2に置かれています。","items":{"1":{"t":true,"w":"公式正答では適切です。現行の施行規則第1条の2の4第2項・第3項を参照。","r":[["貸金業法施行規則","1の2の4"]]},"2":{"t":false,"p":"利率の上限は「年1割（10％）」ではありません。登録を受けた日以後行う全ての貸付けについて、「年7.5％」を超える利息の契約を締結せず、受領・要求もしないことが要件です。","w":"施行規則第5条の6第1項第1号（非営利特例対象法人の業務の要件）。","r":[["貸金業法施行規則","5の6"]]},"3":{"t":true,"w":"現行の施行規則第10条の16の2：特定非営利金融法人の特定貸付契約は、信用情報の使用義務の例外とされています。","r":[["貸金業法施行規則","10の16の2"]]},"4":{"t":true,"w":"公式正答では適切です（特定非営利活動貸付けの要件の細目）。","r":[]}}},"06-27":{"s":"日本貸金業協会の広告に関する規則・細則を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"自主規制基本規則第44条。","r":[]},"2":{"t":true,"w":"貸金業者の広告に関する細則Ⅱ．３．⑴・⑵（全一段相当以下の広告では一部の表示が任意）。","r":[]},"3":{"t":false,"p":"ラジオＣＭで電話番号を告知する際は、「申込み」という表現を「とらない」よう留意します。","w":"貸金業者の広告に関する細則（ラジオＣＭに関する遵守事項等）⑵。","r":[]},"4":{"t":true,"w":"貸金業者の広告に関する細則（啓発文言）。文言例の細目は公式正答によります。","r":[]}}},"06-28":{"s":"債務不履行の責任を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"不確定期限の場合は、「期限の到来を知った後、請求を受けた時」からではありません。現行法では、期限の到来後に請求を受けた時又は期限の到来を知った時の「いずれか早い時」からです（出題時は「知った時」から）。","w":"民法第412条第2項。","r":[["民法","412"]]},"2":{"t":false,"p":"出題時の民法では、裁判所は賠償額の予定の額を増減することが「できない」とされていました（旧第420条第1項後段、公式正答による）。現実の損害額の証明によって増減できるという定めはありません。","w":"現行の民法第420条第1項は、損害賠償の額を予定できることだけを定めています。","r":[["民法","420"]]},"3":{"t":true,"w":"民法第418条（過失相殺）。","r":[["民法","418"]]},"4":{"t":false,"p":"約定利率が法定利率を超えるときは、法定利率ではなく「約定利率」によります。","w":"民法第419条第1項ただし書。","r":[["民法","419"]]}}},"06-29":{"s":"連帯債務者の1人が死亡した場合の相続と連帯債務を問う問題です。公式正答は③です。","law":"この回の基準日は2020年4月の民法改正の前です。改正後の第441条では、連帯債務者の1人について時効が完成しても他の連帯債務者に効力を生じない（相対的効力）ため、③は現行法では適切でありません。","items":{"1":{"t":false,"p":"遺産分割協議で債務の承継者を決めても、債権者Ｃは、Ｄに法定相続分の弁済を請求「できます」（判例の考え方による）。","w":"相続分の指定がある場合について、民法第902条の2が同じ趣旨を定めています。","r":[["民法","902の2"]]},"2":{"t":false,"p":"債権者は、連帯債務者Ｂに対して全額の弁済を請求「できます」。","w":"民法第436条。","r":[["民法","436"]]},"3":{"t":true,"now":false,"p":"現行法では、時効の完成は他の連帯債務者に効力を生じないので、Ｂは返済義務を「免れません」。","w":"出題時の民法（旧第439条）による記述です（公式正答による）。現行の民法第441条。","r":[["民法","441"]]},"4":{"t":false,"p":"Ｆへの免除によって、他の相続人Ｄ・Ｅがその分の返済義務を免れることは「ありません」（公式正答による）。","w":"各相続人は相続分に応じて分割された債務を承継するという考え方です（判例の考え方による）。","r":[["民法","899"]]}}},"06-30":{"s":"連帯保証と保証人の要件を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"連帯保証人には、検索の抗弁権（先に主たる債務者の財産に執行せよと主張する権利）が「ありません」。","w":"民法第454条（第452条・第453条の権利を有しない）。","r":[["民法","454"]]},"2":{"t":true,"w":"民法第450条第1項・第3項。","r":[["民法","450"]]},"3":{"t":false,"p":"主たる債務者の承認による時効の中断（現行法では更新）は、保証人にも効力を「生じます」。","w":"民法第457条第1項。","r":[["民法","457"]]},"4":{"t":false,"p":"事前求償権を行使できるのは、債権者が破産財団の配当に「加入しない」ときです。加入した場合は行使「できません」。","w":"民法第460条第1号。","r":[["民法","460"]]}}},"06-31":{"s":"貸金等根保証契約（現行法では個人貸金等根保証契約）を問う問題です。適切なのは④です。","law":"出題時の「貸金等根保証契約」は、2020年の改正で「個人貸金等根保証契約」（第465条の3）に改められ、極度額の定めなどは個人根保証契約全般（第465条の2）に広げられました。","items":{"1":{"t":false,"p":"貸金等根保証契約は、保証人が「法人でない」（個人である）ものに限られます。法人が保証人となるものは含まれません。","w":"民法第465条の2第1項、第465条の3第1項。","r":[["民法","465の2"],["民法","465の3"]]},"2":{"t":false,"p":"元本確定期日の定めが効力を生じない場合の元本確定期日は、締結の日から「5年」ではなく「3年」を経過する日です。","w":"民法第465条の3第2項。","r":[["民法","465の3"]]},"3":{"t":false,"p":"元本確定期日より前の日に変更する場合は、書面又は電磁的記録で「しなくても」効力を生じます（書面の要件から除かれています）。","w":"民法第465条の3第4項括弧書。","r":[["民法","465の3"]]},"4":{"t":true,"w":"出題時の民法による記述です。現行の第465条の4第1項第1号は保証人の財産への強制執行等を元本確定事由とし、主たる債務者の財産への強制執行等は個人貸金等根保証契約の確定事由として同条第2項に定められています。","r":[["民法","465の4"]]}}},"06-32":{"s":"相殺を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"相殺できるのは「同種の目的」の債務の間だけです。金銭債務と自動車の引渡債務は相殺「できません」。","w":"民法第505条第1項。","r":[["民法","505"]]},"2":{"t":false,"p":"履行地が異なっても相殺「できます」。","w":"民法第507条。","r":[["民法","507"]]},"3":{"t":false,"p":"自働債権が弁済期にあれば、受働債権（自分の債務）の期限の利益を放棄して相殺「できます」。","w":"民法第505条第1項、第136条第2項。","r":[["民法","505"],["民法","136"]]},"4":{"t":true,"w":"民法第511条第1項（現行法では「差押えを受けた債権の第三債務者」）。","r":[["民法","511"]]}}},"06-33":{"s":"契約の成立時期（申込みと承諾）を問う問題です。公式正答は④です。","law":"この回の基準日は2020年4月の民法改正の前で、隔地者間の契約は承諾の通知を「発した時」に成立する（発信主義、旧第526条第1項）とされていました。改正でこの規定は削除され、承諾も通知が到達した時に効力を生じます（第97条第1項）。そのため③は現行法では適切になり、④の電子承諾通知の特例も不要になりました（法律名も「電子消費者契約に関する民法の特例に関する法律」に変わっています）。","items":{"1":{"t":false,"p":"申込者が通知の発送後に死亡し、相手方Ａ社がその事実を知っていたときは、申込みは効力を「有しません」。","w":"民法第526条（出題時の旧第525条も同じ趣旨）。","r":[["民法","526"]]},"2":{"t":false,"p":"申込者が承諾の通知を必要としない旨を表示していれば、承諾の意思表示と認めるべき事実（商品の発送）があった時に契約は「成立します」。","w":"民法第527条。","r":[["民法","527"]]},"3":{"t":false,"now":true,"p":"出題時の民法では、隔地者間の契約は承諾の通知を「発した時」に成立するため、通知が届かなくても契約は「成立する」とされていました（旧第526条第1項、公式正答による）。","w":"現行の民法第97条第1項では承諾も到達によって効力を生じるので、通知が到達しなければ契約は成立せず、記述は適切です。","r":[["民法","97"]]},"4":{"t":true,"w":"出題時は、電子承諾通知について発信主義の例外（到達主義）を定めた特例によります（公式正答による）。現行法でも、承諾は到達によって効力を生じるので（民法第97条第1項）、契約は成立しません。","r":[["民法","97"]]}}},"06-34":{"s":"相続（特別受益・寄与分・代襲・兄弟姉妹）を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"相続分の額が贈与の額を超えるときは、受贈者は、その相続分から贈与の額を控除した残額を相続分として受けることが「できます」。","w":"民法第903条第1項・第2項。","r":[["民法","903"]]},"2":{"t":true,"w":"民法第904条の2第1項。","r":[["民法","904の2"]]},"3":{"t":false,"p":"遺言書の偽造で相続欠格となった者の子は、代襲して相続人と「なります」。","w":"民法第891条第5号、第887条第2項。","r":[["民法","891"],["民法","887"]]},"4":{"t":false,"p":"兄弟姉妹は、直系卑属と直系尊属がいない場合に相続人となり、配偶者がいても配偶者とともに相続人に「なります」。","w":"民法第889条第1項、第890条。","r":[["民法","889"],["民法","890"]]}}},"06-35":{"s":"商行為の特則（商法）を問う問題です。正しい組合せは「ａ誤・ｂ正・ｃ正・ｄ誤」です。","law":"ｃの根拠である商法第507条（対話者間の契約の申込み）は2020年の改正で削除され、現行の民法第525条第3項（対話が継続している間に承諾の通知を受けなかったときは申込みは効力を失う）に一般的な規定が置かれています。現行法では「直ちに」承諾しなければ失効するとはされていません。","items":{"a":{"t":false,"p":"商行為の委任による代理権は、本人の死亡によっては消滅「しません」。","w":"商法第506条。","r":[["商法","506"]]},"b":{"t":true,"w":"商法第504条。","r":[["商法","504"]]},"c":{"t":true,"now":false,"p":"現行法では、対話者間の申込みは、「直ちに」承諾しなかったときではなく、「対話が継続している間に」承諾の通知を受けなかったときに効力を失います。","w":"出題時の商法（旧第507条）による記述です（公式正答による）。現行の民法第525条第3項。","r":[["民法","525"]]},"d":{"t":false,"p":"諾否の通知を怠ったときは、申込みを「拒絶した」ではなく「承諾した」ものとみなされます。","w":"商法第509条第2項。","r":[["商法","509"]]}}},"06-36":{"s":"法的整理の目的を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"破産法第1条。","r":[["破産法","1"]]},"2":{"t":false,"p":"再生計画は「裁判所が職権で策定」するのではなく、「債権者の多数の同意を得、かつ、裁判所の認可を受けた」ものです。","w":"民事再生法第1条。","r":[["民事再生法","1"]]},"3":{"t":false,"p":"会社更生法の対象は「株式会社」で、「持分会社」は含まれません。","w":"会社更生法第1条。","r":[["会社更生法","1"]]},"4":{"t":false,"p":"特別清算の開始は、裁判所の「職権」ではなく「申立てにより」命じられます。","w":"会社法第510条。","r":[["会社法","510"]]}}},"06-37":{"s":"意思表示と無効・取消しを問う問題です。公式正答は③です。","law":"この回の基準日は2020年4月の民法改正の前です。改正後の第95条では、錯誤による意思表示は「無効」ではなく「取り消すことができる」とされたため、②は現行法では条文どおりではありません。","items":{"1":{"t":true,"w":"民法第126条。","r":[["民法","126"]]},"2":{"t":true,"now":false,"p":"現行法では、錯誤による意思表示は「無効」ではなく「取り消すことができる」ものです。","w":"出題時の民法（旧第95条）による記述です（公式正答による）。現行の民法第95条第1項・第3項。","r":[["民法","95"]]},"3":{"t":false,"p":"心裡留保（真意でないと知りながらした意思表示）は、原則として「有効」で、相手方が真意を知り又は知ることができたときは「無効」です。記述は原則と例外が逆です。","w":"民法第93条第1項。","r":[["民法","93"]]},"4":{"t":true,"w":"民法第120条第2項。","r":[["民法","120"]]}}},"06-38":{"s":"消滅時効を問う問題です。適切でないのは④です。","law":"この回の基準日は2020年4月の民法改正の前です。④の工事に関する債権のような職業別の短期消滅時効（旧第170条など）は改正で廃止され、現行法では一般の債権の消滅時効（第166条第1項：知った時から5年、行使できる時から10年）によります。","items":{"1":{"t":true,"w":"民法第724条第1号（人の生命又は身体を害する不法行為の場合は5年。第724条の2）。","r":[["民法","724"]]},"2":{"t":true,"w":"民法第145条（保証人も時効を援用できる当事者に含まれます）。","r":[["民法","145"]]},"3":{"t":true,"w":"民法第144条。","r":[["民法","144"]]},"4":{"t":false,"p":"工事に関する債権の消滅時効は「2年」ではありません。出題時の民法では「3年」の短期消滅時効でした（公式正答による）。","w":"現行法では短期消滅時効は廃止され、民法第166条第1項によります。","r":[["民法","166"]]}}},"06-39":{"s":"質権を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"民法第364条（現行法では「債権を目的とする質権」）。","r":[["民法","364"]]},"2":{"t":true,"w":"民法第343条。","r":[["民法","343"]]},"3":{"t":true,"w":"民法第346条。","r":[["民法","346"]]},"4":{"t":false,"p":"質権者は、質権設定者に自己に代わって質物を占有させることは「できません」。","w":"民法第345条。","r":[["民法","345"]]}}},"06-40":{"s":"弁済を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"差押えを受けた第三債務者が自己の債権者に弁済したときは、差押債権者は、受けた損害の限度で更に弁済するよう請求「できます」。","w":"民法第481条第1項。","r":[["民法","481"]]},"2":{"t":true,"w":"民法第484条第1項。","r":[["民法","484"]]},"3":{"t":true,"w":"民法第492条。","r":[["民法","492"]]},"4":{"t":true,"w":"民法第474条第2項（現行法では「弁済をするについて正当な利益を有する者でない第三者」。債権者が債務者の意思に反することを知らなかったときは有効）。","r":[["民法","474"]]}}},"06-41":{"s":"督促手続（民事訴訟法）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"送達場所の申出をすべき不変期間は、通知を受けた日から「1か月」ではなく「2月」です。","w":"民事訴訟法第388条第3項。","r":[["民事訴訟法","388"]]},"2":{"t":true,"w":"民事訴訟法第391条第1項。","r":[["民事訴訟法","391"]]},"3":{"t":true,"w":"民事訴訟法第395条。","r":[["民事訴訟法","395"]]},"4":{"t":true,"w":"民事訴訟法第396条。","r":[["民事訴訟法","396"]]}}},"06-42":{"s":"金銭の支払を目的とする債権についての強制執行（民事執行法）を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"民事執行法第153条第1項。","r":[["民事執行法","153"]]},"2":{"t":false,"p":"動産執行では、執行官は、差押債権者のためにその債権及び執行費用の弁済を受領することが「できます」。","w":"民事執行法第122条第2項。","r":[["民事執行法","122"]]},"3":{"t":true,"w":"民事執行法第87条第1項第1号。","r":[["民事執行法","87"]]},"4":{"t":true,"w":"民事執行法第149条。","r":[["民事執行法","149"]]}}},"06-43":{"s":"金融分野ガイドラインの安全管理措置・従業者の監督を問う問題です。正しい組合せは「ａ正・ｂ誤・ｃ誤・ｄ正」です。","items":{"a":{"t":true,"w":"金融分野ガイドライン第8条（技術的安全管理措置）。","r":[["個人情報保護法","23"]]},"b":{"t":false,"p":"記述の各項目は「人的安全管理措置」ではなく「組織的安全管理措置」です。","w":"金融分野ガイドライン第8条（組織的安全管理措置）。","r":[["個人情報保護法","23"]]},"c":{"t":false,"p":"記述の各項目は「組織的安全管理措置」ではなく「人的安全管理措置」です。","w":"金融分野ガイドライン第8条（人的安全管理措置）。","r":[["個人情報保護法","23"]]},"d":{"t":true,"w":"金融分野ガイドライン第9条第1項（現行の個人情報保護法では第24条）。","r":[["個人情報保護法","24"]]}}},"06-44":{"s":"紛争解決等業務を問う問題です。適切なのはａｄの2個です。","items":{"a":{"t":true,"w":"貸金業法第2条第21項・第22項。","r":[["貸金業法","2"]]},"b":{"t":false,"p":"相手方が契約者等である場合、紛争解決手続に応じるか否かは「任意」です。正当な理由がある場合を除き応じなければならないのは、相手方が「協会員等」の場合です。","w":"紛争解決等業務に関する規則第62条第2項第3号、第63条。","r":[]},"c":{"t":false,"p":"苦情処理手続の申立てができるのは個人に限られず、「法人」や「権利能力なき社団等」もできます。","w":"紛争解決等業務に関する規則第37条。","r":[]},"d":{"t":true,"w":"紛争解決等業務に関する規則第93条第1項。","r":[]}}},"06-45":{"s":"個人過剰貸付契約から除かれる契約（施行規則第10条の21）を問う問題です。該当するのはａｂです。","items":{"a":{"t":true,"w":"施行規則第10条の21第1項第1号。","r":[["貸金業法施行規則","10の21"]]},"b":{"t":true,"w":"施行規則第10条の21第1項第8号・第1条の2の3第5号。","r":[["貸金業法施行規則","10の21"],["貸金業法施行規則","1の2の3"]]},"c":{"t":false,"p":"つなぎ融資は、除外（第10条の21）ではなく、例外（第10条の23第1項第6号）に当たります。","w":"施行規則第10条の23第1項第6号。","r":[["貸金業法施行規則","10の23"]]},"d":{"t":false,"p":"有価証券の時価（500万円）を超える貸付け（800万円）は、除外される契約に「該当しません」（公式正答による）。","w":"施行規則第10条の21第1項第8号・第1条の2の3第3号・第4号（金融商品取引業者の保護預り有価証券を担保とする貸付けの要件）。","r":[["貸金業法施行規則","1の2の3"]]}}},"06-46":{"s":"消費者契約法を問う問題です。公式正答は④（適切でない）です。","law":"②の取消権の行使期間は、出題時は追認できる時から6か月間でしたが、現行の第7条第1項では1年間（霊感等による告知の場合は3年間）に延びています。現行法では②は適切でありません。","items":{"1":{"t":true,"w":"消費者契約法第2条第2項・第3項。","r":[["消費者契約法","2"]]},"2":{"t":true,"now":false,"p":"現行法では、追認できる時からの期間は「6か月間」ではなく「1年間」です。","w":"出題時の消費者契約法による記述です（公式正答による）。現行の消費者契約法第7条第1項。","r":[["消費者契約法","7"]]},"3":{"t":true,"w":"消費者契約法第9条第1項第1号。","r":[["消費者契約法","9"]]},"4":{"t":false,"p":"不実告知による取消権を持つのは「適格消費者団体」ではなく「消費者」です。","w":"消費者契約法第4条第1項第1号。適格消費者団体が持つのは差止請求権です（第12条）。","r":[["消費者契約法","4"],["消費者契約法","12"]]}}},"06-47":{"s":"景品表示法と「消費者信用の融資費用に関する不当な表示」を問う問題です。適切でないのは③です。","law":"問題文の条番号は出題時のものです。現行法では、景品類の制限・禁止は第4条、不当な表示の禁止は第5条、措置命令は第7条、協定又は規約は第36条です。","items":{"1":{"t":true,"w":"現行の景品表示法第5条第2号（有利誤認表示）。","r":[["景品表示法","5"]]},"2":{"t":true,"w":"現行の景品表示法第36条第1項。","r":[["景品表示法","36"]]},"3":{"t":false,"p":"措置命令は、違反行為が既になくなっている場合でも「することができます」（公示などの命令も含む）。","w":"現行の景品表示法第7条第1項後段。","r":[["景品表示法","7"]]},"4":{"t":true,"w":"消費者信用の融資費用に関する不当な表示（公正取引委員会告示）第1号。","r":[]}}},"06-48":{"s":"企業会計原則の重要な後発事象の例を問う問題です。ａ〜ｄはすべて例として挙げられています。","items":{"a":{"t":true,"w":"企業会計原則注解〔注1－3〕ホ。","r":[]},"b":{"t":true,"w":"企業会計原則注解〔注1－3〕ハ。","r":[]},"c":{"t":true,"w":"企業会計原則注解〔注1－3〕イ。","r":[]},"d":{"t":true,"w":"企業会計原則注解〔注1－3〕ロ。","r":[]}}},"06-49":{"s":"資力を明らかにする書面を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"源泉徴収税額は、「給与所得控除後の金額」に税率を掛けて得られる額では「ありません」（公式正答による）。","w":"源泉徴収票・給与明細書の記載内容は取り込んだ資料にないため、この肢は公式正答によります。","r":[]},"2":{"t":true,"w":"施行規則第10条の17第1項第7号の2（納税証明書）・第2項。","r":[["貸金業法施行規則","10の17"]]},"3":{"t":false,"p":"特別徴収されている者の給与の支払明細書には、地方税（住民税）の額が記載「されます」（公式正答による）。","w":"源泉徴収票・給与明細書の記載内容は取り込んだ資料にないため、この肢は公式正答によります。","r":[]},"4":{"t":false,"p":"青色申告決算書の「売上金額」は、「事業所得」に該当「しません」（公式正答による）。","w":"施行規則第10条の22第1項第4号は「年間の事業所得の金額」としています。","r":[["貸金業法施行規則","10の22"]]}}},"06-50":{"s":"財務諸表等規則の損益計算書を問う問題です。適切でないのは③です。財務諸表等規則は資料にないため公式正答によりますが、企業会計原則で同じ内容を確認できる肢はその旨を書いています。","items":{"1":{"t":true,"w":"財務諸表等規則は取り込んだ資料にないため、この肢は公式正答によります。企業会計原則でも、売上総利益から販売費及び一般管理費を控除して営業利益を表示するとされています。","r":[]},"2":{"t":true,"w":"財務諸表等規則は取り込んだ資料にないため、この肢は公式正答によります。企業会計原則でも、営業損益計算の結果を受けて営業外損益を記載し、経常利益を計算するとされています。","r":[]},"3":{"t":false,"p":"税引前当期純損益は、経常損益から「売上原価」を控除するのではなく、「特別利益を加え特別損失を控除」して計算します。売上原価は売上総利益の計算で差し引くものです。","w":"企業会計原則 損益計算書原則：経常利益に特別損益に属する項目を加減して当期純利益を表示します。財務諸表等規則の表示は公式正答によります。","r":[]},"4":{"t":true,"w":"財務諸表等規則は取り込んだ資料にないため、この肢は公式正答によります。","r":[]}}},"07-01":{"s":"貸金業法の用語の定義を問う問題です。適切なのはａｂｄの3個です。","items":{"a":{"t":true,"w":"貸金業法第2条第1項第3号。","r":[["貸金業法","2"]]},"b":{"t":true,"w":"貸金業法第2条第22項。","r":[["貸金業法","2"]]},"c":{"t":false,"p":"記述は「個人信用情報」の定義です。「信用情報」とは、資金需要者である顧客又は債務者の借入金の返済能力に関する情報をいいます。","w":"貸金業法第2条第13項（信用情報）・第14項（個人信用情報）。","r":[["貸金業法","2"]]},"d":{"t":true,"w":"貸金業法施行令第3条、施行規則第3条。","r":[["貸金業法施行令","3"],["貸金業法施行規則","3"]]}}},"07-02":{"s":"登録の拒否事由を問う問題です。拒否されるのは④です。","items":{"1":{"t":false,"p":"取消しの日から「5年を経過した」者は、拒否事由に該当しません。","w":"貸金業法第6条第1項第3号。","r":[["貸金業法","6"]]},"2":{"t":false,"p":"罰金の刑が拒否事由になるのは、貸金業法・出資法などの規定に違反した場合です。道路交通法違反の罰金は「該当しません」。","w":"貸金業法第6条第1項第5号。","r":[["貸金業法","6"]]},"3":{"t":false,"p":"刑の執行を終わった日などから「5年を経過した」者は、拒否事由に該当しません。","w":"貸金業法第6条第1項第4号（現行法では「拘禁刑以上の刑」）。","r":[["貸金業法","6"]]},"4":{"t":true,"w":"貸金業法第6条第1項第15号、施行規則第5条の7第1項第2号：常務に従事する役員のうちに貸付けの業務に3年以上従事した経験を有する者がいないので、必要な体制が整備されていると認められません。","r":[["貸金業法","6"],["貸金業法施行規則","5の7"]]}}},"07-03":{"s":"禁止行為（貸金業法第12条の6）を問う問題です。適切なのはａｃです。","items":{"a":{"t":true,"w":"断定的判断の提供（第12条の6第2号）は罰則の対象ではなく、行政処分（第24条の6の3、第24条の6の4）の対象です。罰則（第48条第1項第1号の2）は第1号の「虚偽のことを告げた」行為に限られます。","r":[["貸金業法","12の6"],["貸金業法","48"]]},"b":{"t":false,"p":"虚偽のことを告げる行為は、行政処分だけでなく、刑事罰の対象にも「なります」。","w":"貸金業法第48条第1項第1号の2。","r":[["貸金業法","12の6"],["貸金業法","48"]]},"c":{"t":true,"w":"監督指針Ⅱ－２－１０（２）②トａ。","r":[["貸金業法","12の6"]]},"d":{"t":false,"p":"留意する事由として挙げられているのは、貸付けの利率の「引上げ」と賠償額の予定額の「引上げ」です。「引下げ」ではありません。","w":"自主規制基本規則第13条。","r":[]}}},"07-04":{"s":"保証業者との保証契約と保証料の規制を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"保証料の確認は、保証契約を「締結した場合に遅滞なく」ではなく、「あらかじめ、保証契約を締結するまでに」行います。","w":"貸金業法第12条の8第6項。","r":[["貸金業法","12の8"]]},"2":{"t":false,"p":"保証料の額などが確定していない保証料に係る契約を締結することを、貸付けに係る契約の締結の条件とすることは「できません」。","w":"貸金業法第12条の8第8項。","r":[["貸金業法","12の8"]]},"3":{"t":false,"p":"刑事罰の対象に「なります」。出資法では、特約上限利率（年14％）を利息の割合とみなし、保証料（年8％）と合算すると年20％を超えるからです。","w":"出資法第5条の2第1項・第2項第1号。利息制限法でも、保証料の上限は法定上限額（年1割5分）−特約上限利率（14％）＝年1％分なので違反です（第8条第2項第1号）。","r":[["出資法","5の2"],["利息制限法","8"]]},"4":{"t":true,"w":"利息制限法第8条第2項第1号：元本50万円の上限は年1割8分。特約上限利率年10％を引いた年8％分までの保証料は違反になりません。","r":[["利息制限法","8"],["利息制限法","1"]]}}},"07-05":{"s":"返済能力の調査と資力を明らかにする書面等を問う問題です。正しい組合せは「ａ正・ｂ誤・ｃ誤・ｄ誤」です。","items":{"a":{"t":true,"w":"貸金業法第13条第1項。","r":[["貸金業法","13"]]},"b":{"t":false,"p":"極度方式貸付けに係る契約は、信用情報の使用義務の対象から「除かれています」。","w":"貸金業法第13条第2項、施行規則第10条の16第1号。","r":[["貸金業法","13"],["貸金業法施行規則","10の16"]]},"c":{"t":false,"p":"当該貸金業者合算額は20万円＋30万円＝50万円で、50万円を「超えない」ので、資力を明らかにする書面等は「不要」です。","w":"貸金業法第13条第3項第1号。","r":[["貸金業法","13"]]},"d":{"t":false,"p":"個人顧客合算額は20万円＋60万円＝80万円で、100万円を「超えない」ので、資力を明らかにする書面等は「不要」です。","w":"貸金業法第13条第3項第2号。","r":[["貸金業法","13"]]}}},"07-06":{"s":"保証人となろうとする者の返済能力の調査を問う問題です。適切なのはａｃです。","items":{"a":{"t":true,"w":"監督指針Ⅱ－２－１３－１（１）①ロｂⅳ）。","r":[["貸金業法","13"]]},"b":{"t":false,"p":"資力を明らかにする書面等の提出義務は「個人顧客」についてのもので、保証人となろうとする者は対象では「ありません」。","w":"貸金業法第13条第3項。","r":[["貸金業法","13"]]},"c":{"t":true,"w":"貸金業法第13条の2第1項：顧客等（保証人となろうとする者を含む）の返済能力を超える貸付けの契約（保証契約を含む）は締結できません。","r":[["貸金業法","13の2"],["貸金業法","2"]]},"d":{"t":false,"p":"保証人の調査の記録の保存期限は、「保証契約の解除の日」などの「遅い日」ではなく、主たる債務の最終の返済期日（債権消滅の日）又は保証債務が消滅した日の「いずれか早い日」までです。","w":"施行規則第10条の18第2項第2号。","r":[["貸金業法施行規則","10の18"]]}}},"07-07":{"s":"貸付条件等の掲示（貸金業法第14条）を問う問題です。正しい組合せは「ａ正・ｂ正・ｃ誤・ｄ誤」です。","items":{"a":{"t":true,"w":"施行規則第11条第5項本文。","r":[["貸金業法","14"],["貸金業法施行規則","11"]]},"b":{"t":true,"w":"施行規則第11条第5項ただし書。","r":[["貸金業法施行規則","11"]]},"c":{"t":false,"p":"指定信用情報機関や指定紛争解決機関の商号・名称は、掲示事項に「含まれていません」。","w":"掲示事項は、貸付けの利率、返済の方式、返済期間及び返済回数、主任者の氏名（第14条第1項）と、賠償額の予定の割合・担保に関する事項・主な返済の例（施行規則第11条第3項第1号）です。","r":[["貸金業法","14"],["貸金業法施行規則","11"]]},"d":{"t":false,"p":"営業所等に置かれる貸金業務取扱主任者の氏名は、掲示事項に「含まれています」。","w":"貸金業法第14条第1項第4号。","r":[["貸金業法","14"]]}}},"07-08":{"s":"契約締結時の書面の再交付（貸金業法第17条第1項後段）を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"貸付けの利率の引下げは相手方の利益となる変更なので、再交付は「不要」です。","w":"施行規則第13条第2項第1号イ。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"2":{"t":false,"p":"各回の返済期日及び返済金額の変更は、相手方にとって不利なときに限らず、有利・不利を問わず再交付が「必要」です。","w":"施行規則第13条第2項第1号ロ（第1項第1号チ）。","r":[["貸金業法施行規則","13"]]},"3":{"t":false,"p":"賠償額の予定の変更は、相手方の利益となる変更なら再交付は「不要」です。","w":"施行規則第13条第2項第1号イ（第17条第1項第7号）。","r":[["貸金業法施行規則","13"]]},"4":{"t":true,"w":"施行規則第13条第2項第1号ロ（第1項第1号ヲ。新たに保証契約を締結する場合）。","r":[["貸金業法施行規則","13"]]}}},"07-09":{"s":"帳簿の閲覧・謄写（貸金業法第19条の2）を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"債務者等に代わって弁済をした者も閲覧等を請求でき、権利の行使に関する調査が目的なら拒むことは「できません」。","w":"施行規則第17条の2第1項第3号、貸金業法第19条の2。","r":[["貸金業法","19の2"],["貸金業法施行規則","17の2"]]},"2":{"t":false,"p":"閲覧・謄写に応じる義務は「営業時間内」のものなので、営業時間終了後の請求に翌営業日以降の再請求を求めても、拒否したことには「なりません」。","w":"施行規則第17条の3（営業時間内に請求に応じて閲覧又は謄写をさせなければならない）。","r":[["貸金業法施行規則","17の3"]]},"3":{"t":false,"p":"法定代理人も請求権者で、権利の行使に関する調査が目的であることが明らかなら、謄写の後の閲覧の請求も拒むことは「できません」。","w":"施行規則第17条の2第1項第1号、貸金業法第19条の2後段。","r":[["貸金業法","19の2"],["貸金業法施行規則","17の2"]]},"4":{"t":true,"w":"監督指針Ⅱ－２－１８（１）③。","r":[["貸金業法","19の2"]]}}},"07-10":{"s":"債権の取立ての委託を問う問題です。ａ〜ｄはすべて適切なので4個です。","items":{"a":{"t":true,"w":"貸金業法第24条第4項（債権譲渡等には取立ての委託を含む。第3項）、施行令第3条の7第1号（個人である貸金業者の親族）。","r":[["貸金業法","24"],["貸金業法施行令","3の7"]]},"b":{"t":true,"w":"貸金業法第24条第3項第1号：暴力団員等（暴力団員でなくなった日から5年を経過しない者を含む。第6条第1項第6号）は取立て制限者です。","r":[["貸金業法","24"],["貸金業法","6"]]},"c":{"t":true,"w":"貸金業法第21条第3項。","r":[["貸金業法","21"]]},"d":{"t":true,"w":"貸金業法第21条第2項、施行規則第19条第3項第1号・第2号。","r":[["貸金業法","21"],["貸金業法施行規則","19"]]}}},"07-11":{"s":"債権譲渡の規制を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"貸金業法第24条第2項：第16条の2第3項などが債権の譲受人に準用されます。","r":[["貸金業法","24"],["貸金業法","16の2"]]},"2":{"t":false,"p":"届出の期限は、「30日以内」ではなく、その日から「2週間以内」です。","w":"貸金業法第24条の6の2第4号、施行規則第26条の25第1項第3号・第2項。","r":[["貸金業法","24の6の2"],["貸金業法施行規則","26の25"]]},"3":{"t":false,"p":"第24条第2項に基づく通知を債務者等に送付するのは、「債権譲渡人」ではなく「債権譲受人」です。","w":"監督指針Ⅱ－２－２０（１）④。","r":[["貸金業法","24"]]},"4":{"t":false,"p":"廃業に伴う債権譲渡の場合は、「廃業の日から5年間」ではなく「譲渡の日から10年間」帳簿を保管し、閲覧等に応じる措置を講じるよう「努める」ものとされています。","w":"自主規制基本規則第67条。","r":[]}}},"07-12":{"s":"貸金業者に対する監督（行政処分・監督指針）を問う問題です。適切なのはｂｄです。","items":{"a":{"t":false,"p":"保証業者が取立て制限者であることを知らなかったことにつき相当の理由があることを貸金業者が「証明できたとき」は、この号による処分の対象に「なりません」。","w":"貸金業法第24条の6の4第1項第6号イ・ロ（イとロの両方に該当することが必要）。","r":[["貸金業法","24の6の4"]]},"b":{"t":true,"w":"貸金業法第24条の6の6第1項第2号。","r":[["貸金業法","24の6の6"]]},"c":{"t":false,"p":"純資産額が最低純資産額を下回っても、「直ちに」登録取消処分を行うのではありません。報告を求めて「純資産額を回復させる計画」を検証し、確実に回復できると認められれば処分を保留します。","w":"監督指針Ⅲ－３－４。","r":[["貸金業法","24の6の4"]]},"d":{"t":true,"w":"監督指針Ⅲ－３－３（１）。","r":[["貸金業法","24の6の10"]]}}},"07-13":{"s":"指定信用情報機関への情報提供を問う問題です。適切なのはａｄの2個です。","items":{"a":{"t":true,"w":"貸金業法第41条の35第1項、施行規則第30条の12。","r":[["貸金業法","41の35"],["貸金業法施行規則","30の12"]]},"b":{"t":false,"p":"極度方式基本契約は、個人信用情報の提供の対象から「除かれています」。","w":"施行規則第30条の12・第1条の2の3第1号。","r":[["貸金業法","41の35"],["貸金業法施行規則","30の12"]]},"c":{"t":false,"p":"同意に関する記録の保存期間は、提供した日から「10年間」ではなく、「当該同意に基づき指定信用情報機関が信用情報を保有している間」です。","w":"施行規則第30条の16第1項。","r":[["貸金業法施行規則","30の16"]]},"d":{"t":true,"w":"貸金業法第41条の35第3項、施行規則第30条の13第1項第5号（勤務先の商号又は名称）。","r":[["貸金業法","41の35"],["貸金業法施行規則","30の13"]]}}},"07-14":{"s":"監督指針Ⅱ－２－３（外部委託）を問う問題です。適切なのはａｂｄの3個です。","items":{"a":{"t":true,"w":"監督指針Ⅱ－２－３（１）②。","r":[]},"b":{"t":true,"w":"監督指針Ⅱ－２－３（１）⑨。","r":[]},"c":{"t":false,"p":"二段階以上の委託では、外部委託先が再委託先等に「十分な監督を行っているか確認」し、必要に応じて貸金業者自身も直接監督します。外部委託先に監督を「行わせない」のではありません。","w":"監督指針Ⅱ－２－３（１）⑩。","r":[]},"d":{"t":true,"w":"監督指針Ⅱ－２－３（１）⑪。","r":[]}}},"07-15":{"s":"日本貸金業協会の自主規制規則（勧誘）を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"勧誘リスト等には、個人信用情報を「記載等することがないよう留意」しなければなりません。正確に記載するのではありません。","w":"自主規制基本規則第54条第5項。","r":[]},"2":{"t":true,"w":"自主規制基本規則第55条第1号。","r":[]},"3":{"t":false,"p":"障害等により契約内容の理解が困難なことを認識した場合は、書面等で説明するのではなく、勧誘を「行ってはならない」とされています。","w":"自主規制基本規則第54条第4項。","r":[]},"4":{"t":false,"p":"承諾の取得方法は店頭窓口や書面に限られず、「協会員のホームページを用いて承諾を取得する方法」なども例示されています。","w":"自主規制基本規則第54条第1項。","r":[]}}},"07-16":{"s":"利息制限法（みなし利息・元本額の特則・賠償額の予定）を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"公租公課の支払に充てられるべきものは、利息とみなされ「ません」。","w":"利息制限法第6条第2項第1号（第3条ただし書）。","r":[["利息制限法","6"],["利息制限法","3"]]},"2":{"t":false,"p":"債務者の要請によるカードの再発行の手数料は、利息とみなされ「ません」。","w":"利息制限法第6条第1項、施行令第1条第1号。","r":[["利息制限法","6"],["利息制限法施行令","1"]]},"3":{"t":true,"w":"利息制限法第5条第1号：残高5万円＋8万円＝13万円を元本とみなし、上限は年1割8分。","r":[["利息制限法","5"],["利息制限法","1"]]},"4":{"t":false,"p":"営業的金銭消費貸借の賠償額の予定の上限は、「1割5分」ではなく「年2割」です。年20％の約定は無効になりません。","w":"利息制限法第7条第1項。","r":[["利息制限法","7"]]}}},"07-17":{"s":"変更の届出（貸金業法第8条）を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"貸金業法第8条第1項、第4条第1項第5号。","r":[["貸金業法","8"],["貸金業法","4"]]},"2":{"t":false,"p":"代理店も営業所又は事務所に含まれるので、新たに設ける場合は、2週間以内ではなく「あらかじめ」届け出ます。","w":"貸金業法第8条第1項、第4条第1項第5号、施行規則第1条の5第3項（営業所又は事務所には代理店を含む）。","r":[["貸金業法","8"],["貸金業法施行規則","1の5"]]},"3":{"t":true,"w":"貸金業法第8条第1項、第4条第1項第7号。","r":[["貸金業法","8"],["貸金業法","4"]]},"4":{"t":true,"w":"貸金業法第8条第1項、第4条第1項第2号。","r":[["貸金業法","8"],["貸金業法","4"]]}}},"07-18":{"s":"変更・開始等・廃業等の届出を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"業務の種類及び方法の変更は、「あらかじめ」ではなく、変更の日から「2週間以内」に届け出ます。","w":"貸金業法第8条第1項、第4条第1項第8号。","r":[["貸金業法","8"],["貸金業法","4"]]},"2":{"t":true,"w":"施行規則第26条の25第1項第7号・第2項。","r":[["貸金業法施行規則","26の25"]]},"3":{"t":true,"w":"貸金業法第10条第1項第1号。","r":[["貸金業法","10"]]},"4":{"t":true,"w":"貸金業法第24条の6の2第1号、施行規則第26条の25第2項。","r":[["貸金業法","24の6の2"],["貸金業法施行規則","26の25"]]}}},"07-19":{"s":"貸金業務取扱主任者を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"2週間以内の猶予があるのは「予見し難い事由」の場合です。定年退職は会社として予見できるので含まれず、2週間の猶予は「ありません」（主任者が欠けないよう事前に手当てする必要があります）。","w":"貸金業法第12条の3第3項、監督指針Ⅱ－２－９（２）③。","r":[["貸金業法","12の3"]]},"2":{"t":true,"w":"監督指針Ⅱ－２－９（２）①。","r":[["貸金業法","12の3"],["貸金業法施行規則","10の7"]]},"3":{"t":true,"w":"貸金業法第12条の4第2項、施行規則第10条の9の2第1項。","r":[["貸金業法","12の4"],["貸金業法施行規則","10の9の2"]]},"4":{"t":true,"w":"貸金業法第24条の27第1項第7号。","r":[["貸金業法","24の27"]]}}},"07-20":{"s":"返済能力の調査と総量規制を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"顧客が法人でも、個人である保証人となろうとする者の返済能力の調査では、信用情報を使用する必要が「あります」。","w":"貸金業法第13条第2項（個人である顧客等には保証人となろうとする者を含む）。","r":[["貸金業法","13"]]},"2":{"t":true,"w":"施行規則第10条の22第2項第2号・第3項。","r":[["貸金業法施行規則","10の22"]]},"3":{"t":true,"w":"施行規則第10条の23第1項第3号、第2項第3号ロ（配偶者の同意書）。","r":[["貸金業法施行規則","10の23"]]},"4":{"t":true,"w":"貸金業法第13条の2第1項の違反は、登録の取消し・業務停止の対象です（第24条の6の4第1項第2号）。","r":[["貸金業法","13の2"],["貸金業法","24の6の4"]]}}},"07-21":{"s":"極度方式基本契約の返済能力の調査と措置を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"施行規則第10条の19。","r":[["貸金業法","13"],["貸金業法施行規則","10の19"]]},"2":{"t":true,"w":"返済能力の低下による減額の後の増額は、施行規則第10条の19の例外に当たりません。","r":[["貸金業法","13"],["貸金業法施行規則","10の19"]]},"3":{"t":true,"w":"施行規則第10条の24第1項第1号：貸付けの合計額6万円が5万円を超え、かつ残高13万円が10万円を超えています。","r":[["貸金業法","13の3"],["貸金業法施行規則","10の24"]]},"4":{"t":false,"p":"求められる措置は、極度額の減額又は新たな極度方式貸付けの停止です。「指定信用情報機関に登録する措置」は「含まれません」。","w":"貸金業法第13条の4、施行規則第10条の29。","r":[["貸金業法","13の4"],["貸金業法施行規則","10の29"]]}}},"07-22":{"s":"総量規制の例外（施行規則第10条の23）と除外（第10条の21）の区別を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"不動産の建設・購入・改良の資金の貸付けは、例外（第10条の23）ではなく除外（第10条の21第1項第1号）に当たります。","r":[["貸金業法施行規則","10の21"],["貸金業法施行規則","10の23"]]},"2":{"t":true,"w":"売却予定の不動産の売却代金で弁済される貸付けは、除外（第10条の21第1項第7号）に当たります。","r":[["貸金業法施行規則","10の21"]]},"3":{"t":false,"p":"高額療養費の資金の貸付けは、例外（第10条の23）ではなく、除外（第10条の21第1項第4号）に当たります。","w":"施行規則第10条の21第1項第4号イ。","r":[["貸金業法施行規則","10の21"]]},"4":{"t":true,"w":"施行規則第10条の23第1項第2号の2（特定緊急貸付契約：合算額10万円以下、返済期間3月以内）。","r":[["貸金業法施行規則","10の23"]]}}},"07-23":{"s":"極度方式基本契約の調査を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"貸金業法第13条の3第2項、施行規則第10条の25第2項・第3項（残高10万円以下などの場合は不要）。","r":[["貸金業法","13の3"],["貸金業法施行規則","10の25"]]},"2":{"t":true,"w":"施行規則第10条の24第1項第2号。","r":[["貸金業法施行規則","10の24"]]},"3":{"t":false,"p":"調査の記録の保存期間は、最終の返済期日までではなく、「作成後3年間」です。","w":"施行規則第10条の27第2項。","r":[["貸金業法施行規則","10の27"]]},"4":{"t":true,"w":"貸金業法第13条の3第3項：極度方式個人顧客合算額が100万円を超えるときに必要です。80万円なら不要です。","r":[["貸金業法","13の3"]]}}},"07-24":{"s":"誇大広告の禁止等（貸金業法第16条）と罰則を問う問題です。適切でないのは④です。刑事罰があるのは第16条第1項の違反です。","items":{"1":{"t":true,"w":"貸金業法第16条第4項（再勧誘の禁止）は罰則の対象ではなく、行政処分の対象です。","r":[["貸金業法","16"]]},"2":{"t":true,"w":"貸金業法第16条第3項（適合性原則）は罰則の対象ではなく、行政処分の対象です。","r":[["貸金業法","16"]]},"3":{"t":true,"w":"貸金業法第16条第2項第1号は罰則の対象ではなく、行政処分の対象です。","r":[["貸金業法","16"]]},"4":{"t":false,"p":"貸付けの条件について著しく有利であると誤認させる表示（第16条第1項）は、行政処分だけでなく、刑事罰の対象にも「なります」。","w":"貸金業法第48条第1項第3号。","r":[["貸金業法","16"],["貸金業法","48"]]}}},"07-25":{"s":"保証人に交付する書面を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"施行規則第12条の2第7項第2号（詳細書面には第6項各号の事項。解除に関する事項は第6項第11号）。","r":[["貸金業法施行規則","12の2"]]},"2":{"t":false,"p":"極度額を引き下げた場合は、極度方式保証契約締結時の書面の再交付は「不要」です。","w":"貸金業法第17条第5項後段、施行規則第13条第13項・第5項第1号。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"3":{"t":true,"w":"貸金業法第17条第3項・第4項。","r":[["貸金業法","17"]]},"4":{"t":true,"w":"施行規則第13条第8項。","r":[["貸金業法施行規則","13"]]}}},"07-26":{"s":"高金利の規制と媒介手数料（貸金業法第42条・出資法）を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"貸金業法第42条第1項。","r":[["貸金業法","42"]]},"2":{"t":true,"w":"出資法第5条第1項・第2項：利息には債務の不履行について予定される賠償額を含み、業として貸付けを行う場合は年20％を超えると刑事罰の対象です。","r":[["出資法","5"]]},"3":{"t":false,"p":"受領できる媒介手数料は、貸借の金額100万円の100分の5にあたる5万円までです。6万円は受領「できません」。","w":"出資法第4条第1項。","r":[["出資法","4"]]},"4":{"t":true,"w":"出資法第5条の4第3項。","r":[["出資法","5の4"]]}}},"07-27":{"s":"監督指針の社内規則等・態勢整備を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"監督指針Ⅱ－２－２（顧客等に関する情報管理態勢）。","r":[]},"2":{"t":false,"p":"着眼点は、保証の履行や担保権実行を主な回収手段とする貸付けの契約を「締結する」措置ではなく、その締結を「防止する」措置が講じられているかです。","w":"監督指針Ⅱ－２－１３－２（１）①ロｂⅰ）。","r":[]},"3":{"t":true,"w":"監督指針Ⅱ－２－９（１）②ハ。","r":[]},"4":{"t":true,"w":"監督指針Ⅱ－２－１１－２（１）①。","r":[]}}},"07-28":{"s":"制限行為能力者を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"動産の賃貸借で保佐人の同意が必要なのは、6箇月を「超える」期間のものです。6か月を超えない賃貸には同意は「不要」です。","w":"民法第13条第1項第9号、第602条第4号。","r":[["民法","13"],["民法","602"]]},"2":{"t":false,"p":"成年被後見人の法律行為は、成年後見人の同意を得ていても取り消すことが「できます」。","w":"民法第9条。","r":[["民法","9"]]},"3":{"t":true,"w":"民法第21条。","r":[["民法","21"]]},"4":{"t":false,"p":"行為能力者となった本人が確答しないときは、「追認を拒絶した」ではなく「追認した」ものとみなされます。","w":"民法第20条第1項。","r":[["民法","20"]]}}},"07-29":{"s":"法律行為の取消しを問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"瑕疵ある意思表示をした者の承継人も、取り消すことが「できます」。","w":"民法第120条第2項。","r":[["民法","120"]]},"2":{"t":false,"p":"取り消された行為は、将来に向かってではなく「初めから」無効であったものとみなされます。","w":"民法第121条。","r":[["民法","121"]]},"3":{"t":true,"w":"民法第122条（第120条に規定する取消権者が追認したときは、以後取り消せない）。","r":[["民法","122"]]},"4":{"t":false,"p":"取消し又は追認は、「裁判所」ではなく「相手方」に対する意思表示によってします。","w":"民法第123条。","r":[["民法","123"]]}}},"07-30":{"s":"債権譲渡（出題時の「指名債権の譲渡」）を問う問題です。公式正答は④です。","law":"この回の基準日は2020年4月の民法改正の前です。②は改正前の第468条第1項（異議をとどめない承諾をした債務者は譲渡人に対抗できた事由を譲受人に対抗できない）による出題で、この規定は削除されました。現行の第468条第1項では、債務者は対抗要件具備時までに譲渡人に対して生じた事由を譲受人に対抗できるため、②は現行法では適切です。①の譲渡禁止特約も、現行の第466条では「譲渡制限の意思表示」として、譲渡自体は有効とされています。","items":{"1":{"t":false,"p":"譲渡禁止の特約は、善意の第三者に対抗「できません」（出題時の民法）。","w":"現行の民法第466条第2項・第3項：譲渡制限の意思表示があっても譲渡は有効で、債務者が履行を拒めるのは、そのことを知り又は重大な過失で知らなかった譲受人などに対してです。","r":[["民法","466"]]},"2":{"t":false,"now":true,"p":"出題時の民法では、異議をとどめないで承諾した債務者は、譲渡人に対抗できた事由を譲受人に対抗「できない」とされていました（旧第468条第1項、公式正答による）。","w":"現行の民法第468条第1項では、対抗要件具備時までに譲渡人に対して生じた事由を譲受人に対抗できるので、記述は適切です。","r":[["民法","468"]]},"3":{"t":false,"p":"譲渡通知の到達時に既に反対債権を有していれば、債務者は相殺をもって譲受人に対抗「できます」。","w":"現行の民法第469条第1項（対抗要件具備時より前に取得した債権による相殺）。出題時の結論は公式正答によります。","r":[["民法","469"]]},"4":{"t":true,"w":"公式正答では適切です。確定日付のある証書による通知が債務者に到達した日時の先後で優劣を決める考え方です（判例の考え方による）。民法第467条第2項。","r":[["民法","467"]]}}},"07-31":{"s":"弁済による代位を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"民法第501条第1項・第2項。","r":[["民法","501"]]},"2":{"t":false,"p":"一部の代位弁済があっても、債務不履行による契約の解除は「債権者のみ」がすることができます。","w":"民法第502条第4項。","r":[["民法","502"]]},"3":{"t":false,"p":"正当な利益を有しない者も、債権者に代位することが「できます」（出題時の民法では、弁済と同時に債権者の承諾を得れば代位できました）。","w":"現行の民法第499条（承諾は不要）、第500条（債務者・第三者への対抗には第467条の通知・承諾が必要）。","r":[["民法","499"],["民法","500"]]},"4":{"t":false,"p":"抵当不動産の第三取得者は弁済について正当な利益を有するので、債務者の意思に反しても弁済「できます」。","w":"民法第474条第2項（制限されるのは正当な利益を有しない第三者）。第三取得者の扱いは公式正答によります。","r":[["民法","474"]]}}},"07-32":{"s":"消費貸借を問う問題です。適切なのはａｄです。","items":{"a":{"t":true,"w":"民法第588条（準消費貸借）。","r":[["民法","588"]]},"b":{"t":false,"p":"借主が後見開始の審判を受けても、消費貸借契約が効力を失う定めは「ありません」。","w":"公式正答による。","r":[]},"c":{"t":false,"p":"商人間の金銭消費貸借では、利息の約定がなくても、貸主は法定利息を請求「できます」。","w":"商法第513条第1項。","r":[["商法","513"]]},"d":{"t":true,"w":"民法第589条第1項。","r":[["民法","589"]]}}},"07-33":{"s":"破産法を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"破産債権と財団債権の説明が逆です。破産手続によらないで随時弁済を受けられるのが「財団債権」、破産手続開始前の原因に基づく請求権で財団債権に当たらないものが「破産債権」です。","w":"破産法第2条第5項・第7項。","r":[["破産法","2"]]},"2":{"t":true,"w":"破産法第53条第1項。","r":[["破産法","53"]]},"3":{"t":false,"p":"破産手続開始後に破産財団に対して負担した債務との相殺は「できません」。","w":"破産法第71条第1項第1号。","r":[["破産法","71"]]},"4":{"t":false,"p":"費用を支弁するのに足りる金額の予納があったときは、同時廃止の決定は「しません」。","w":"破産法第216条第2項。","r":[["破産法","216"]]}}},"07-34":{"s":"手形法と電子記録債権法を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"手形法第38条第1項（支払をなすべき日又はこれに次ぐ2取引日内に呈示。約束手形には第77条第1項第3号で準用）。","r":[["手形法","38"],["手形法","77"]]},"2":{"t":false,"p":"強迫による取消しの抗弁は、善意・無重過失の手形の取得者Ｃに対抗「できません」（公式正答による）。","w":"手形法第17条（人的関係に基づく抗弁の制限）。強迫を人的抗弁として扱う点は公式正答によります。","r":[["手形法","17"]]},"3":{"t":false,"p":"支払約束は「単純な」約束でなければならないので、条件を付けた約束手形は、記載だけでなく手形「自体が無効」になります（公式正答による）。","w":"手形法第75条第2号。","r":[["手形法","75"]]},"4":{"t":false,"p":"電子記録債権の譲渡は、合意だけでは効力を生じず、譲渡記録は対抗要件ではなく「効力要件」です。","w":"電子記録債権法第17条。","r":[["電子記録債権法","17"]]}}},"07-35":{"s":"意思表示（虚偽表示・錯誤・詐欺・電子消費者契約）を問う問題です。適切でないのは③です。","law":"この回の基準日は2020年4月の民法改正の前で、錯誤は「無効」とされていました。現行の第95条では「取り消すことができる」に改められ、法律名も「電子消費者契約に関する民法の特例に関する法律」に変わっています。②④の結論（重大な過失があれば錯誤を主張できない・確認措置を講じていれば特例の適用がない）は現行法でも同じです。","items":{"1":{"t":true,"w":"民法第94条第2項：虚偽表示の無効を対抗できないのは善意の第三者です。悪意のＺには主張できます。","r":[["民法","94"]]},"2":{"t":true,"w":"民法第95条第3項（出題時は旧第95条ただし書）。","r":[["民法","95"]]},"3":{"t":false,"p":"詐欺による取消しを対抗できないのは、善意（現行法では善意かつ無過失）の第三者です。事情を知っているＺには取消しを主張「できます」。","w":"民法第96条第3項。","r":[["民法","96"]]},"4":{"t":true,"w":"電子消費者契約に関する民法の特例に関する法律第3条ただし書：事業者が意思表示を行う意思の有無について確認を求める措置を講じていたときは、民法第95条第3項（重大な過失がある場合の制限）が適用されます。","r":[["電子消費者契約に関する民法の特例に関する法律","3"]]}}},"07-36":{"s":"代理を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"民法第101条第3項（出題時の条文では「本人の指図に従って」が要件でした）。","r":[["民法","101"]]},"2":{"t":false,"p":"制限行為能力者も代理人と「することができます」。","w":"民法第102条：制限行為能力者が代理人としてした行為は、行為能力の制限によっては取り消すことができません。","r":[["民法","102"]]},"3":{"t":true,"w":"民法第104条。","r":[["民法","104"]]},"4":{"t":true,"w":"民法第106条第2項。","r":[["民法","106"]]}}},"07-37":{"s":"時効の中断を問う問題です。適切でないのは③です。","law":"この回の基準日は2020年4月の民法改正の前で、「時効の中断」の制度で出題されています。現行法では「時効の完成猶予」と「時効の更新」に改められました。現行法では、差押え（強制執行）は完成猶予・更新（第148条）、仮差押え・仮処分は完成猶予（第149条）、調停は完成猶予・更新（第147条）、催告は6箇月の完成猶予（第150条）の事由です。","items":{"1":{"t":true,"w":"出題時の民法（旧第147条）による記述です（公式正答による）。現行の第148条・第149条を参照。","r":[["民法","148"],["民法","149"]]},"2":{"t":true,"w":"出題時の民法（旧第157条）による記述です（公式正答による）。現行法では、権利が確定したときに事由の終了時から新たに進行します（第147条第2項。時効の更新）。","r":[["民法","147"]]},"3":{"t":false,"p":"出題時の民法では、調停が調わなかったときは「1か月以内」に訴えを提起しなければ中断の効力を生じないとされていました。2か月後では中断し「ません」（公式正答による）。","w":"現行法では、調停が権利の確定なく終了したときは、終了の時から6箇月を経過するまで時効の完成が猶予されます（第147条第1項第3号）。","r":[["民法","147"]]},"4":{"t":true,"w":"出題時の民法（旧第153条：催告の後6か月以内に調停の申立てなどをすれば中断）による記述です（公式正答による）。現行の第150条を参照。","r":[["民法","150"]]}}},"07-38":{"s":"連帯債務を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"民法第436条。","r":[["民法","436"]]},"2":{"t":true,"w":"民法第437条（現行法では錯誤は取消しの原因です）。","r":[["民法","437"]]},"3":{"t":true,"w":"民法第440条。","r":[["民法","440"]]},"4":{"t":false,"p":"1人の連帯債務者による債務の承認は、他の連帯債務者に対して効力を「生じません」（相対的効力）。","w":"民法第441条（出題時の民法でも、承認は相対的効力の事由でした）。","r":[["民法","441"]]}}},"07-39":{"s":"連帯保証を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"民法第457条第1項：主たる債務者に対する履行の請求その他の事由による時効の完成猶予・更新（出題時は中断）は、保証人にも効力を生じます。","r":[["民法","457"]]},"2":{"t":false,"p":"債権者が保証人を指名した場合は、保証人が行為能力者でなくなっても、他の保証人に代えることを請求「できません」。","w":"民法第450条第3項。","r":[["民法","450"]]},"3":{"t":true,"w":"民法第457条第1項（主たる債務者の承認）。","r":[["民法","457"]]},"4":{"t":true,"w":"民法第459条第2項・第442条第2項。","r":[["民法","459"],["民法","442"]]}}},"07-40":{"s":"債権の消滅（相殺・供託・代物弁済・更改）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"時効消滅前に相殺に適するようになっていたなら、時効消滅後でも、その債権を自働債権として相殺「できます」。","w":"民法第508条。","r":[["民法","508"]]},"2":{"t":true,"w":"民法第494条第2項。","r":[["民法","494"]]},"3":{"t":true,"w":"出題時の民法（旧第482条）による記述です。現行の第482条では、債権者との間で代物弁済の契約をして他の給付をしたときに、弁済と同一の効力を有します。","r":[["民法","482"]]},"4":{"t":true,"w":"出題時の民法（旧第513条）による記述です。現行の第513条では、従前の給付の内容について重要な変更をする新たな債務を発生させる契約などが更改とされています。","r":[["民法","513"]]}}},"07-41":{"s":"相続を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"民法第920条。","r":[["民法","920"]]},"2":{"t":true,"w":"民法第951条、第952条第1項（現行法では「相続財産の清算人」）。","r":[["民法","951"],["民法","952"]]},"3":{"t":true,"w":"民法第1004条第3項。","r":[["民法","1004"]]},"4":{"t":false,"p":"兄弟姉妹には遺留分が「ありません」。","w":"民法第1042条第1項（遺留分は「兄弟姉妹以外の相続人」に認められます）。","r":[["民法","1042"]]}}},"07-42":{"s":"民事訴訟法を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"民事訴訟法第263条。","r":[["民事訴訟法","263"]]},"2":{"t":true,"w":"民事訴訟法第251条第1項。","r":[["民事訴訟法","251"]]},"3":{"t":false,"p":"被告が原告の主張した事実を争わない場合などに請求を認容するときは、判決の言渡しは判決書の原本に「基づかないで」することができます（調書判決）。","w":"民事訴訟法第254条第1項第1号。","r":[["民事訴訟法","254"]]},"4":{"t":true,"w":"民事訴訟法第259条第1項。","r":[["民事訴訟法","259"]]}}},"07-43":{"s":"景品表示法を問う問題です。適切なのはａｄの2個です。","law":"問題文の条番号は出題時のものです。現行法では、景品類の制限・禁止は第4条、公聴会等は第6条、措置命令は第7条、報告徴収・立入検査は第25条です。","items":{"a":{"t":true,"w":"景品表示法第2条第4項。","r":[["景品表示法","2"]]},"b":{"t":false,"p":"景品類の制限・禁止をするときは、「意見公募手続」ではなく「公聴会」を開き、「公正取引委員会」ではなく「消費者委員会」の意見を聴きます。","w":"現行の景品表示法第6条第1項。","r":[["景品表示法","6"]]},"c":{"t":false,"p":"措置命令ができるのは違反する行為が「あるとき」です。「違反すると疑われる行為があるとき」は含まれません。","w":"現行の景品表示法第7条第1項。","r":[["景品表示法","7"]]},"d":{"t":true,"w":"現行の景品表示法第25条第1項。","r":[["景品表示法","25"]]}}},"07-44":{"s":"日本貸金業協会の貸付自粛対応に関する規則を問う問題です。適切なのはｂｃです。","items":{"a":{"t":false,"p":"貸付自粛は、協会が「帳簿を備えて協会員の閲覧に供する」ものではなく、協会が個人信用情報機関に情報の登録を依頼し、その機関が一定期間会員に情報を提供するものです。","w":"貸付自粛対応に関する規則第2条第2号。","r":[]},"b":{"t":true,"w":"貸付自粛対応に関する規則第2条第4号。","r":[]},"c":{"t":true,"w":"貸付自粛対応に関する規則第7条第1項。","r":[]},"d":{"t":false,"p":"申告を撤回できるのは、登録の依頼をした日から「1か月」ではなく「3か月」を超えた日以降です。","w":"貸付自粛対応に関する規則第10条第1項。","r":[]}}},"07-45":{"s":"消費者契約法を問う問題です。適切なのはａｂです。","items":{"a":{"t":true,"w":"消費者契約法第4条第2項（不利益事実の不告知）。","r":[["消費者契約法","4"]]},"b":{"t":true,"w":"消費者契約法第5条第1項（媒介の委託を受けた第三者による勧誘にも第4条を準用）、第4条第3項第2号（退去妨害）。","r":[["消費者契約法","5"],["消費者契約法","4"]]},"c":{"t":false,"p":"事業者が瑕疵のない物に代える責任又は修補する責任を負うこととされている場合は、損害賠償責任の全部を免除する条項でも無効に「なりません」。","w":"出題時の消費者契約法第8条第2項（公式正答による）。現行の第8条第2項でも、契約不適合について履行の追完などの責任を負うこととされている場合は同様の扱いです。","r":[["消費者契約法","8"]]},"d":{"t":false,"p":"無効になるのは条項全体ではなく、年14.6％の割合で計算した額を「超える部分」です。","w":"消費者契約法第9条第1項第2号。","r":[["消費者契約法","9"]]}}},"07-46":{"s":"日本貸金業協会の紛争解決等業務に関する規則を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"紛争解決等業務に関する規則第6条第5項。","r":[]},"2":{"t":true,"w":"紛争解決等業務に関する規則第83条第1項。","r":[]},"3":{"t":true,"w":"紛争解決等業務に関する規則第89条第1項。","r":[]},"4":{"t":false,"p":"貸金業務関連紛争は、当事者が和解をすることが「できないもの」ではなく「できるもの」です。","w":"紛争解決等業務に関する規則第2条第2号。","r":[]}}},"07-47":{"s":"金融分野ガイドラインの第三者提供の制限を問う問題です。適切でないのは③です。","law":"問題文の「ガイドライン第13条」「個人情報保護法第23条」は出題時のもので、現行ではガイドライン第12条、個人情報保護法第27条です。","items":{"1":{"t":true,"w":"金融分野ガイドライン第12条（第三者提供の制限）。","r":[["個人情報保護法","27"]]},"2":{"t":true,"w":"通則ガイドライン（第三者に該当しない場合）：「責任を有する者」とは、共同して利用するすべての事業者の中で、第一次的に苦情の受付・処理、開示・訂正等を行う権限を有する者をいいます。","r":[["個人情報保護法","27"]]},"3":{"t":false,"p":"利用目的の達成に必要な範囲内での委託に伴う提供は、委託先が第三者に当たらないため、本人の同意は「不要」です。","w":"個人情報保護法第27条第5項第1号。","r":[["個人情報保護法","27"]]},"4":{"t":true,"w":"金融分野ガイドライン第12条（個人信用情報機関に対する提供）。","r":[["個人情報保護法","27"]]}}},"07-48":{"s":"資力を明らかにする書面を問う問題です。正しい組合せは「ａ正・ｂ正・ｃ誤・ｄ正」です。","items":{"a":{"t":true,"w":"源泉徴収票・青色申告決算書の様式は取り込んだ資料にないため、この肢は公式正答によります。","r":[]},"b":{"t":true,"w":"源泉徴収票・青色申告決算書の様式は取り込んだ資料にないため、この肢は公式正答によります。","r":[]},"c":{"t":false,"p":"根拠法令なく行政サービスの一環として地方公共団体が交付する所得・課税証明書も、所得証明書として資力を明らかにする書面に「該当します」。","w":"監督指針Ⅱ－２－１３－１（１）②ロａ、施行規則第10条の17第1項第8号。","r":[["貸金業法施行規則","10の17"]]},"d":{"t":true,"w":"施行規則第10条の17第1項第2号（支払調書）・第2項（直近の期間に係るものなどの要件）。","r":[["貸金業法施行規則","10の17"]]}}},"07-49":{"s":"貸借対照表の区分を問う問題です。適切なのは④です。会社計算規則は資料にないため公式正答によりますが、企業会計原則で同じ内容を確認できる肢はその旨を書いています。","items":{"1":{"t":false,"p":"会社計算規則に規定する名称以外の名称を付すことが一切できないわけではありません（公式正答による）。","w":"会社計算規則は取り込んだ資料にないため、この肢は公式正答によります。","r":[]},"2":{"t":false,"p":"固定資産は、有形固定資産・無形固定資産・投資その他の資産に区分します。「繰延資産」は固定資産とは別の区分です。","w":"企業会計原則 貸借対照表原則二・四（一）Ｂ。","r":[]},"3":{"t":false,"p":"1年内に期限が到来するリース債務は、「固定負債」ではなく「流動負債」に属します（公式正答による）。","w":"企業会計原則 貸借対照表原則四（二）Ａ：期限が1年以内に到来する債務は流動負債に属する。","r":[]},"4":{"t":true,"w":"会社計算規則は取り込んだ資料にないため、この肢は公式正答によります。","r":[]}}},"07-50":{"s":"企業会計原則の損益計算書原則を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"企業会計原則 損益計算書原則一Ｂ。","r":[]},"2":{"t":true,"w":"企業会計原則 損益計算書原則三Ｂ（実現主義の原則）。","r":[]},"3":{"t":true,"w":"企業会計原則 損益計算書原則三（営業利益）。","r":[]},"4":{"t":false,"p":"記述は「経常損益計算」の区分の説明です。「純損益計算」の区分は、経常損益計算の結果を受けて、前期損益修正額・固定資産売却損益等の特別損益を記載し、当期純利益を計算します。","w":"企業会計原則 損益計算書原則二Ｂ・Ｃ。","r":[]}}},"08-01":{"s":"貸金業法の用語の定義と貸金業者登録簿を問う問題です。ａ〜ｄはすべて適切なので4個です。","items":{"a":{"t":true,"w":"貸金業法第2条第1項第5号、施行令第1条の2第1号ロ（労働組合。構成員以外の者への貸付けを業として行うものを除く）。","r":[["貸金業法","2"],["貸金業法施行令","1の2"]]},"b":{"t":true,"w":"貸金業法第2条第14項、施行規則第30条の13第1項第6号。","r":[["貸金業法","2"],["貸金業法施行規則","30の13"]]},"c":{"t":true,"w":"貸金業法第2条第4項〜第6項。","r":[["貸金業法","2"]]},"d":{"t":true,"w":"貸金業法第5条第1項第1号：登録申請書の記載事項（第4条第1項各号。業務の種類及び方法は第8号）が登録簿に登録されます。","r":[["貸金業法","5"],["貸金業法","4"]]}}},"08-02":{"s":"変更の届出（貸金業法第8条）を問う問題です。適切なのはｂｃです。","items":{"a":{"t":false,"p":"主任者の登録の更新は、届出が必要な変更に「当たりません」。","w":"届出の対象は第4条第1項各号の事項の変更で、主任者については氏名と登録番号（第6号）です。更新の届出を求める定めはありません（公式正答による）。","r":[["貸金業法","8"],["貸金業法","4"]]},"b":{"t":true,"w":"貸金業法第8条第1項、第4条第1項第2号（役員の氏名）。","r":[["貸金業法","8"],["貸金業法","4"]]},"c":{"t":true,"w":"貸金業法第8条第1項、第4条第1項第9号（他に行っている事業の種類）。","r":[["貸金業法","8"],["貸金業法","4"]]},"d":{"t":false,"p":"営業所又は事務所の名称の変更は、変更の日から2週間以内ではなく、「あらかじめ」届け出ます。","w":"貸金業法第8条第1項、第4条第1項第5号。","r":[["貸金業法","8"],["貸金業法","4"]]}}},"08-03":{"s":"廃業等の届出・開始等の届出を問う問題です。適切なのはａｂです。","items":{"a":{"t":true,"w":"貸金業法第10条第1項第5号。","r":[["貸金業法","10"]]},"b":{"t":true,"w":"貸金業法第24条の6の2第4号、施行規則第26条の25第1項第6号・第2項。","r":[["貸金業法","24の6の2"],["貸金業法施行規則","26の25"]]},"c":{"t":false,"p":"届け出るのは「存続会社又は新設会社を代表する役員」ではなく、「消滅した法人を代表する役員であった者」です。","w":"貸金業法第10条第1項第2号。","r":[["貸金業法","10"]]},"d":{"t":false,"p":"解散の場合に届け出るのは「法人を代表する役員」ではなく「清算人」で、期限は「2週間以内」ではなく「30日以内」です。","w":"貸金業法第10条第1項第4号。","r":[["貸金業法","10"]]}}},"08-04":{"s":"監督指針の経営管理・法令等遵守の着眼点を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"「営業部門から独立した検査部署、監査部署等」は「内部管理部門」ではなく「内部監査部門」の説明です。内部管理部門は、法令等を遵守した業務運営を確保するための内部事務管理部署、法務部署等をいいます。","w":"監督指針Ⅱ－１（１）①（注）。","r":[]},"2":{"t":false,"p":"着眼点は、業績評価や人事考課等で収益目標（ノルマ）を「重視しているか」ではなく、ノルマに「偏重することなく、コンプライアンスを重視しているか」です。","w":"監督指針Ⅱ－２－１（法令等遵守）（１）①。","r":[]},"3":{"t":true,"w":"監督指針Ⅱ－１（１）⑥イ。","r":[]},"4":{"t":false,"p":"モニタリング・検証及び改善策の策定等を行うのは、「内部監査部門」ではなく「内部管理部門」です。","w":"監督指針Ⅱ－１（１）②。","r":[]}}},"08-05":{"s":"監督指針Ⅱ－２－１０（禁止行為等）を問う問題です。適切なのはａｂです。","items":{"a":{"t":true,"w":"監督指針Ⅱ－２－１０（２）②イａ。","r":[["貸金業法","12の6"]]},"b":{"t":true,"w":"監督指針Ⅱ－２－１０（２）②ハ。","r":[["貸金業法","12の6"]]},"c":{"t":false,"p":"説明が逆です。「不正な」行為とは「違法な行為」、「不当な」行為とは客観的に見て実質的に妥当性を欠く又は適当でない行為で、不正（違法）な程度にまで達していない行為をいいます。","w":"監督指針Ⅱ－２－１０（２）②なお書き。","r":[["貸金業法","12の6"]]},"d":{"t":false,"p":"「告げる」「告げない」行為は、口頭によるものに「限られません」。","w":"監督指針Ⅱ－２－１０（２）①なお書き。","r":[["貸金業法","12の6"]]}}},"08-06":{"s":"基準額超過極度方式基本契約に係る調査と措置を問う問題です。適切なのはｄの1個です。","items":{"a":{"t":false,"p":"既に資力を明らかにする書面等の提出を受けており、それが使える期間内（発行後一定期間内）で資力に変更もないので、改めて提出を受ける必要は「ありません」。","w":"貸金業法第13条の3第3項ただし書、施行規則第10条の26第2項（源泉徴収票などは過去3年以内に発行されたもの）。","r":[["貸金業法","13の3"],["貸金業法施行規則","10の26"]]},"b":{"t":false,"p":"期間の末日の残高の合計額が10万円「以下」なら、調査を行う必要は「ありません」。","w":"施行規則第10条の25第3項第1号。","r":[["貸金業法","13の3"],["貸金業法施行規則","10の25"]]},"c":{"t":false,"p":"調査の記録の保存期間は、作成後「7年間」ではなく「3年間」です。","w":"施行規則第10条の27第2項。","r":[["貸金業法施行規則","10の27"]]},"d":{"t":true,"w":"貸金業法第13条の4、施行規則第10条の29（極度額の減額又は新たな極度方式貸付けの停止）。","r":[["貸金業法","13の4"],["貸金業法施行規則","10の29"]]}}},"08-07":{"s":"極度方式基本契約の書面を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"施行規則第12条の2第2項第1号ホ。","r":[["貸金業法","16の2"],["貸金業法施行規則","12の2"]]},"2":{"t":false,"p":"「極度方式基本契約に関し貸金業者が受け取る書面の内容」は、契約締結前の書面の記載事項に「含まれません」（契約締結時の書面の記載事項です）。","w":"施行規則第12条の2第2項第1号（記載事項）、第13条第3項第1号ハ（契約締結時の書面）。","r":[["貸金業法施行規則","12の2"],["貸金業法施行規則","13"]]},"3":{"t":false,"p":"利息の計算の方法の変更は、顧客の利益となる変更なら再交付は「不要」です。","w":"施行規則第13条第4項第1号イ（第3項第1号ヘ）。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"4":{"t":false,"p":"貸付限度額を引き下げた後、元の額を上回らない額まで引き上げたときは、再交付は「不要」です。","w":"施行規則第13条第5項第2号。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]}}},"08-08":{"s":"書面の交付に代えて電磁的方法で提供できる書面を問う問題です。ａ〜ｄはすべて提供できるので4個です。","items":{"a":{"t":true,"w":"貸金業法第16条の2第4項。","r":[["貸金業法","16の2"]]},"b":{"t":true,"w":"貸金業法第16条の3第2項。","r":[["貸金業法","16の3"]]},"c":{"t":true,"w":"貸金業法第17条第7項。","r":[["貸金業法","17"]]},"d":{"t":true,"w":"貸金業法第18条第4項。","r":[["貸金業法","18"]]}}},"08-09":{"s":"帳簿（貸金業法第19条）を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"契約締結時の書面の写しを保存すれば、その書面に記載した事項の帳簿への記載に「代えることができます」。両方をしなければならないわけではありません。","w":"施行規則第16条第3項。","r":[["貸金業法","19"],["貸金業法施行規則","16"]]},"2":{"t":true,"w":"施行規則第17条第1項ただし書。","r":[["貸金業法施行規則","17"]]},"3":{"t":false,"p":"営業所等が現金自動設備であるときは、帳簿の備付けを「要しません」。","w":"施行規則第17条第2項。","r":[["貸金業法施行規則","17"]]},"4":{"t":false,"p":"「交渉の経過の記録」は、契約締結前の書面の交付以降ではなく、「貸付けの契約の締結以降」の債権に関する交渉の経過の記録です。","w":"監督指針Ⅱ－２－１７（注）。","r":[["貸金業法施行規則","16"]]}}},"08-10":{"s":"監督指針Ⅱ－２－８（不祥事件）を問う問題です。適切なのはａｂｃの3個です。","items":{"a":{"t":true,"w":"監督指針Ⅱ－２－８（不祥事件の定義）。","r":[]},"b":{"t":true,"w":"監督指針Ⅱ－２－８（１）①。","r":[]},"c":{"t":true,"w":"監督指針Ⅱ－２－８（２）。","r":[]},"d":{"t":false,"p":"業務改善命令を発出するのは、重大な問題があると認められる「か否かにかかわらず」ではなく、「重大な問題があると認められるとき」です。","w":"監督指針Ⅱ－２－８（２）。","r":[["貸金業法","24の6の3"]]}}},"08-11":{"s":"貸金業務取扱主任者の登録を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"主任者登録の更新は、「5年ごと」ではなく「3年ごと」です。","w":"貸金業法第24条の25第3項。","r":[["貸金業法","24の25"]]},"2":{"t":false,"p":"罰金の刑が拒否事由になるのは、貸金業法・出資法・暴力団対策法などの規定に違反した場合です。道路交通法違反の罰金は「該当しません」。","w":"貸金業法第24条の27第1項第5号（拘禁刑以上の刑は第4号）。","r":[["貸金業法","24の27"]]},"3":{"t":false,"p":"主任者登録の取消し処分を受けた者が登録を受けられない期間は、処分の日から「3年」ではなく「5年」です。","w":"貸金業法第24条の27第1項第7号。","r":[["貸金業法","24の27"]]},"4":{"t":true,"w":"貸金業法第24条の25第4項、施行規則第26条の51第1項第3号。","r":[["貸金業法","24の25"],["貸金業法施行規則","26の51"]]}}},"08-12":{"s":"指定信用情報機関への信用情報の提供と同意を問う問題です。適切なのはａｄです。","items":{"a":{"t":true,"w":"貸金業法第41条の36第1項。","r":[["貸金業法","41の36"]]},"b":{"t":false,"p":"加入前に締結した極度方式基本契約に基づく極度方式貸付け（加入前極度方式貸付契約）については、あらかじめ同意を得る必要は「ありません」。","w":"貸金業法第41条の36第2項ただし書。","r":[["貸金業法","41の36"]]},"c":{"t":false,"p":"元本又は利息の支払の遅延の有無も、提供しなければならない事項に「含まれます」。","w":"貸金業法第41条の35第1項第4号、施行規則第30条の13第2項第2号。","r":[["貸金業法","41の35"],["貸金業法施行規則","30の13"]]},"d":{"t":true,"w":"施行規則第30条の16第1項。","r":[["貸金業法施行規則","30の16"]]}}},"08-13":{"s":"利息制限法の元本額の特則（第5条）を問う問題です。適切なのはａｂｃの3個です。","items":{"a":{"t":true,"w":"利息制限法第5条第1号：残高100万円＋5万円＝105万円を元本とみなし、上限は年1割5分。","r":[["利息制限法","5"],["利息制限法","1"]]},"b":{"t":true,"w":"利息制限法第5条第2号：同時に貸し付けた元本の合計105万円とみなし、上限は年1割5分。","r":[["利息制限法","5"],["利息制限法","1"]]},"c":{"t":true,"w":"利息制限法第5条第1号：残高2万円＋9万円＝11万円を元本とみなし、上限は年1割8分。","r":[["利息制限法","5"],["利息制限法","1"]]},"d":{"t":false,"p":"第二貸付契約の元本とみなされる額は、残高30万円＋同時に貸し付けた5万円と70万円＝105万円です。上限は年1割8分ではなく「年1割5分」です。","w":"利息制限法第5条第1号、第1条第3号。","r":[["利息制限法","5"],["利息制限法","1"]]}}},"08-14":{"s":"無登録営業の禁止・名義貸しの禁止などを問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"貸金業法第11条第2項。","r":[["貸金業法","11"]]},"2":{"t":false,"p":"相続人が引き続き貸金業を営めるのは、死亡後「90日間」ではなく「60日間」です。","w":"貸金業法第10条第3項。","r":[["貸金業法","10"]]},"3":{"t":true,"w":"名義貸しの禁止（第12条）の違反は、刑事罰（第47条第3号）と登録の取消し（第24条の6の5第1項第4号）の対象です。","r":[["貸金業法","12"],["貸金業法","47"],["貸金業法","24の6の5"]]},"4":{"t":true,"w":"監督指針Ⅲ－３－１（２）①。","r":[]}}},"08-15":{"s":"業務を第三者に委託する場合の措置（施行規則第10条の5）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"施行規則第10条の5第5号。","r":[["貸金業法施行規則","10の5"]]},"2":{"t":true,"w":"施行規則第10条の5第3号。","r":[["貸金業法施行規則","10の5"]]},"3":{"t":true,"w":"施行規則第10条の2第1項。","r":[["貸金業法施行規則","10の2"]]},"4":{"t":false,"p":"受託者が業務を適切に行えない事態が生じたときは、「他の適切な第三者に当該業務を速やかに委託する等」の措置を講じます。他の第三者への委託が「できない」わけではありません。","w":"施行規則第10条の5第4号。","r":[["貸金業法施行規則","10の5"]]}}},"08-16":{"s":"返済能力の調査を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"貸金業法第13条第1項（顧客等には法人も含まれます）。","r":[["貸金業法","13"]]},"2":{"t":true,"w":"自主規制基本規則第32条第1項。","r":[]},"3":{"t":true,"w":"自主規制基本規則第22条第1項。","r":[]},"4":{"t":false,"p":"他の貸金業者を債権者とする金銭の貸借の媒介に係る契約は、信用情報の使用義務の対象から「除かれています」。","w":"貸金業法第13条第2項、施行規則第10条の16第2号・第1条の2の3第5号。","r":[["貸金業法","13"],["貸金業法施行規則","10の16"]]}}},"08-17":{"s":"保証人となろうとする者の返済能力の調査を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"監督指針Ⅱ－２－１３－１（１）①ロｂⅳ）。","r":[["貸金業法","13"]]},"2":{"t":false,"p":"資力を明らかにする書面等の提出を求める義務（第13条第3項）は「個人顧客」についてのもので、保証人となろうとする者は対象では「ありません」。","w":"貸金業法第13条第3項。","r":[["貸金業法","13"]]},"3":{"t":true,"w":"貸金業法第13条第2項：個人である顧客等（保証人となろうとする者を含む）との貸付けの契約では、信用情報の使用が必要です。","r":[["貸金業法","13"]]},"4":{"t":true,"w":"施行規則第10条の18第2項第2号。","r":[["貸金業法施行規則","10の18"]]}}},"08-18":{"s":"総量規制の例外となる契約（施行規則第10条の23）を問う問題です。該当しないのは②です。","items":{"1":{"t":true,"w":"施行規則第10条の23第1項第5号。","r":[["貸金業法施行規則","10の23"]]},"2":{"t":false,"p":"売却予定の不動産の売却代金で弁済される貸付けは、第10条の23（例外）ではなく、第10条の21（総量規制の対象から「除外」される契約）に当たります。","w":"施行規則第10条の21第1項第7号。","r":[["貸金業法施行規則","10の21"]]},"3":{"t":true,"w":"施行規則第10条の23第1項第6号。","r":[["貸金業法施行規則","10の23"]]},"4":{"t":true,"w":"施行規則第10条の23第1項第2号。","r":[["貸金業法施行規則","10の23"]]}}},"08-19":{"s":"貸付条件の広告等（貸金業法第15条）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"施行規則第12条第1項第1号イ。","r":[["貸金業法","15"],["貸金業法施行規則","12"]]},"2":{"t":true,"w":"施行規則第12条第1項第3号。","r":[["貸金業法施行規則","12"]]},"3":{"t":true,"w":"貸金業法第15条第2項、施行規則第12条第4項（多数の者に対して同様の内容で行う勧誘）・第5項。","r":[["貸金業法","15"],["貸金業法施行規則","12"]]},"4":{"t":false,"p":"期限の利益の喪失の定めは、広告で表示しなければならない事項に「含まれません」。","w":"施行規則第12条第1項第1号、第11条第3項第1号。","r":[["貸金業法施行規則","12"],["貸金業法施行規則","11"]]}}},"08-20":{"s":"広告・勧誘の規制を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"勧誘に係る取引について引き続き勧誘を受けることを希望しない明確な意思表示の場合は、「最低1年間」ではなく「最低6ヶ月間」、当該取引と類似する取引の勧誘を見合わせます。最低1年間は、勧誘を一切拒否する強い意思表示の場合です。","w":"自主規制基本規則第55条第1号・第2号。","r":[]},"2":{"t":true,"w":"貸金業法第16条第4項の違反は、登録の取消し・業務停止の対象です（第24条の6の4第1項第2号）。","r":[["貸金業法","16"],["貸金業法","24の6の4"]]},"3":{"t":true,"w":"監督指針Ⅱ－２－１１－２（１）②イｂ。","r":[]},"4":{"t":true,"w":"監督指針Ⅱ－２－１１－２（１）①。","r":[]}}},"08-21":{"s":"契約締結前の書面の記載事項を問う問題です。該当しないのは③です。","items":{"1":{"t":true,"w":"貸金業法第16条の2第1項第5号。","r":[["貸金業法","16の2"]]},"2":{"t":true,"w":"施行規則第12条の2第1項第1号ホ。","r":[["貸金業法施行規則","12の2"]]},"3":{"t":false,"p":"「貸付けに関し貸金業者が受け取る書面の内容」は、契約締結時の書面の記載事項ですが、契約締結前の書面の記載事項には「含まれません」。","w":"施行規則第12条の2第1項第1号（契約締結前）、第13条第1項第1号ハ（契約締結時）。","r":[["貸金業法施行規則","12の2"],["貸金業法施行規則","13"]]},"4":{"t":true,"w":"施行規則第12条の2第1項第1号ロ。","r":[["貸金業法施行規則","12の2"]]}}},"08-22":{"s":"契約締結前・締結時の書面と保証契約の書面を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"貸金業法第16条の2第1項、施行規則第12条の2第1項第1号イ。","r":[["貸金業法","16の2"],["貸金業法施行規則","12の2"]]},"2":{"t":true,"w":"施行規則第13条第1項第1号タ。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"3":{"t":true,"w":"施行規則第13条第2項第1号イ：賠償額の予定（第17条第1項第7号）は、相手方の利益となる変更でなければ再交付が必要です。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"4":{"t":false,"p":"債務の残高の総額を記載するのは「概要を記載した書面」だけで、「詳細を記載した書面」には記載しません。","w":"施行規則第12条の2第7項第1号・第2号（詳細書面では第4項第1号イ・ロが除かれています）。","r":[["貸金業法施行規則","12の2"]]}}},"08-23":{"s":"受取証書と債権証書の返還を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"施行規則第15条第1項第2号・第3号、第2項。","r":[["貸金業法","18"],["貸金業法施行規則","15"]]},"2":{"t":true,"w":"貸金業法第18条第1項、施行規則第15条第1項第4号（債務者以外の者が弁済したときはその者の氏名等）。","r":[["貸金業法","18"],["貸金業法施行規則","15"]]},"3":{"t":false,"p":"債権証書は、債務者Ｂではなく、「全部の弁済をした者」である保証人Ｃに返還します。","w":"貸金業法第22条。","r":[["貸金業法","22"]]},"4":{"t":true,"w":"貸金業法第18条第2項。","r":[["貸金業法","18"]]}}},"08-24":{"s":"取立て行為の規制を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"監督指針Ⅱ－２－１９（２）⑦ロ。","r":[["貸金業法","21"]]},"2":{"t":true,"w":"監督指針Ⅱ－２－１９（２）⑧。","r":[["貸金業法","21"]]},"3":{"t":true,"w":"貸金業法第21条第1項第6号。","r":[["貸金業法","21"]]},"4":{"t":false,"p":"「債務者等の自発的な承諾がある場合」は、第1号・第3号の「正当な理由」に該当する可能性が高い例示に「含まれています」。","w":"監督指針Ⅱ－２－１９（２）②イａ・ロａ。","r":[["貸金業法","21"]]}}},"08-25":{"s":"貸金業者以外の者への債権譲渡を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"施行規則第21条第1項第3号：保証契約を締結したときは第17条第3項の事項（保証期間など第16条の2第3項の事項を含む）を通知します。","r":[["貸金業法","24"],["貸金業法施行規則","21"]]},"2":{"t":true,"w":"貸金業法第24条第2項（第17条の準用）。","r":[["貸金業法","24"]]},"3":{"t":true,"w":"貸金業法第24条第2項（第24条第1項の準用）。","r":[["貸金業法","24"]]},"4":{"t":false,"p":"債権を譲渡した後も貸金業者であるＡは、帳簿を保存する必要が「あります」。","w":"貸金業法第19条、施行規則第17条第1項。","r":[["貸金業法","19"],["貸金業法施行規則","17"]]}}},"08-26":{"s":"監督指針の事務処理上の留意点（Ⅲ－１・Ⅲ－３）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"残貸付債権の状況等の報告を求めるのは、有効期間満了の日の「30日前まで」ではなく「2月前まで」に更新の申請をしなかった場合です。","w":"監督指針Ⅲ－３－３（１）。","r":[["貸金業法","24の6の10"]]},"2":{"t":true,"w":"監督指針Ⅲ－１－２（２）。","r":[]},"3":{"t":true,"w":"監督指針Ⅲ－３－７。","r":[["貸金業法","24の6の10"]]},"4":{"t":true,"w":"監督指針Ⅲ－３－６（１）。","r":[["貸金業法","24の6の10"]]}}},"08-27":{"s":"利息の天引き・みなし利息・賠償額の予定（利息制限法）を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"利息制限法第2条：受領額72,000円を元本とみなすと上限は年2割で14,400円。天引額18,000円との差3,600円が元本の支払に充てたものとみなされます。","r":[["利息制限法","2"],["利息制限法","1"]]},"2":{"t":false,"p":"債務者の要請によるカードの再発行の手数料は、利息とみなされ「ません」。","w":"利息制限法第6条第1項、施行令第1条第1号。","r":[["利息制限法","6"],["利息制限法施行令","1"]]},"3":{"t":true,"w":"利息制限法第6条第2項第3号、施行令第2条：1万円以下の額の利用料は110円（消費税等相当額を含む）までなら利息とみなされません（出題時は105円）。","r":[["利息制限法","6"],["利息制限法施行令","2"]]},"4":{"t":true,"w":"利息制限法第7条第1項：営業的金銭消費貸借の賠償額の予定は年2割を超える部分が無効です。","r":[["利息制限法","7"]]}}},"08-28":{"s":"意思表示を問う問題です。公式正答は②です。","law":"この回の基準日は2020年4月の民法改正の前です。改正後の第95条では、錯誤による意思表示は「無効」ではなく「取り消すことができる」とされ、表意者に重大な過失があるときは、相手方が悪意・重過失のときなどを除き取り消せません。現行法では②は条文どおりではありません。","items":{"1":{"t":false,"p":"詐欺による取消しは、善意（現行法では善意かつ無過失）の第三者に対抗「できません」。","w":"民法第96条第3項。","r":[["民法","96"]]},"2":{"t":true,"now":false,"p":"現行法では、錯誤による意思表示は「無効」ではなく「取り消すことができる」ものです。","w":"出題時の民法（旧第95条）による記述です（公式正答による）。現行の民法第95条第1項・第3項。","r":[["民法","95"]]},"3":{"t":false,"p":"強迫による意思表示をした者の承継人も、取り消すことが「できます」。","w":"民法第120条第2項。","r":[["民法","120"]]},"4":{"t":false,"p":"相手方が表意者の真意を知っていたとき（現行法では知ることができたときも）は、心裡留保による意思表示は「無効」です。","w":"民法第93条第1項ただし書。","r":[["民法","93"]]}}},"08-29":{"s":"代理（表見代理・顕名・無権代理）を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"代理権の消滅を過失なく知らないＣに対しては、Ｂは代理権の消滅を対抗「できません」（表見代理）。","w":"民法第112条第1項。","r":[["民法","112"]]},"2":{"t":true,"w":"民法第100条ただし書・第99条第1項：相手方が本人のためにすることを知り、又は知ることができたときは、本人に対して直接に効力を生じます。","r":[["民法","100"],["民法","99"]]},"3":{"t":false,"p":"履行か損害賠償かを選ぶのは、無権代理人Ａではなく「相手方Ｃ」です。","w":"民法第117条第1項。","r":[["民法","117"]]},"4":{"t":false,"p":"権限外の行為でも、Ｃに権限があると信ずべき正当な理由があるときは、Ｂは責任を「負います」（権限外の行為の表見代理）。","w":"民法第110条。","r":[["民法","110"]]}}},"08-30":{"s":"期限の利益・解除・相殺・遅延損害金を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"債務者が担保を滅失させたときは期限の利益を失うので、Ａは期限前でも弁済を請求「できます」。","w":"民法第137条第2号。","r":[["民法","137"]]},"2":{"t":false,"p":"履行遅滞による解除には、原則として相当の期間を定めた「催告が必要」です。","w":"民法第541条。","r":[["民法","541"]]},"3":{"t":true,"w":"民法第505条第1項、第136条第2項：自働債権（貸金債権）が弁済期にあれば、受働債権（売買代金債務）の期限の利益を放棄して相殺できます。","r":[["民法","505"],["民法","136"]]},"4":{"t":false,"p":"約定がない場合の遅延損害金は、年14.6％ではなく「法定利率」によります（約定利率が法定利率を超えるときは約定利率）。","w":"民法第419条第1項。現行の法定利率は年3％を基準に3年ごとに見直されます（第404条）。","r":[["民法","419"],["民法","404"]]}}},"08-31":{"s":"時効の中断を問う問題です。適切なのは④です。","law":"この回の基準日は2020年4月の民法改正の前で、「時効の中断」の制度で出題されています。現行法では「時効の完成猶予」と「時効の更新」に改められました。承認は更新事由（第152条）、催告は6箇月の完成猶予（第150条）、支払督促・再生手続参加などは完成猶予・更新の事由（第147条）です。","items":{"1":{"t":false,"p":"承認をするには、相手方の権利についての処分につき行為能力（の制限を受けていないこと）又は権限があることを「要しません」。","w":"民法第152条第2項（出題時の旧第156条も同じ趣旨）。","r":[["民法","152"]]},"2":{"t":false,"p":"催告の後に裁判上の請求などをすべき期間は、「3か月以内」ではなく「6か月以内」です。","w":"現行の民法第150条第1項（催告の時から6箇月を経過するまで完成猶予）。","r":[["民法","150"]]},"3":{"t":false,"p":"再生手続参加は、届出を取り下げ、又は却下されたときは、時効の中断の効力を生じ「ません」（出題時の民法、公式正答による）。","w":"現行法では、権利が確定することなく事由が終了したときは、終了の時から6箇月を経過するまで完成猶予にとどまります（第147条第1項）。","r":[["民法","147"]]},"4":{"t":true,"w":"出題時の民法（旧第150条）による記述です（公式正答による）。現行法では、支払督促は完成猶予・更新の事由で、権利が確定することなく終了したときは6箇月の完成猶予にとどまります（第147条第1項第2号）。","r":[["民法","147"]]}}},"08-32":{"s":"抵当権を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"法定地上権が成立するのは、抵当権の「実行」（競売）により所有者を異にするに至ったときです。売買による譲渡では成立「しません」。","w":"民法第388条。","r":[["民法","388"]]},"2":{"t":false,"p":"被担保債権に不履行があったときは、その後に生じた果実に抵当権が「及びます」。","w":"民法第371条。","r":[["民法","371"]]},"3":{"t":false,"p":"抵当権を行使できる利息などは、最後の「3年分」ではなく「2年分」です。","w":"民法第375条第1項。","r":[["民法","375"]]},"4":{"t":true,"w":"民法第396条。","r":[["民法","396"]]}}},"08-33":{"s":"連帯債務を問う問題です。公式正答は③です。","law":"この回の基準日は2020年4月の民法改正の前です。改正後の第441条では、時効の完成も他の連帯債務者に効力を生じない（相対的効力）ため、③は現行法では適切でありません。","items":{"1":{"t":false,"p":"1人について無効・取消しの原因があっても、他の連帯債務者の債務は効力を妨げられません。他の連帯債務者が代わって主張して負担部分を免れることは「できません」。","w":"民法第437条。","r":[["民法","437"]]},"2":{"t":false,"p":"1人に対する免除で他の連帯債務者の債務が「すべて」消滅することはありません。出題時の民法では免除した者の負担部分に限って他の者も免れ、現行法では他の者には効力を生じません。","w":"現行の民法第441条。","r":[["民法","441"]]},"3":{"t":true,"now":false,"p":"現行法では、1人について時効が完成しても、他の連帯債務者は負担部分について義務を「免れません」（相対的効力）。","w":"出題時の民法（旧第439条）による記述です（公式正答による）。現行の民法第441条。","r":[["民法","441"]]},"4":{"t":false,"p":"求償できるのは、弁済した「全額」ではなく、他の連帯債務者の「負担部分」に応じた額です。","w":"民法第442条第1項。","r":[["民法","442"]]}}},"08-34":{"s":"契約の成立（申込みと承諾）を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"民法第527条：申込者の意思表示により承諾の通知を必要としない場合は、承諾の意思表示と認めるべき事実があった時に契約が成立します。","r":[["民法","527"]]},"2":{"t":false,"p":"申込者が通知の発送後に死亡しても、申込みが「当然に」効力を失うわけではありません。相手方がその事実を知った場合などに効力を有しないとされています。","w":"民法第526条（出題時の民法でも、相手方が死亡の事実を知っていた場合に適用しないとされていました。公式正答による）。","r":[["民法","526"]]},"3":{"t":false,"p":"申込みに条件を付して承諾したときは、契約は成立せず、申込みの拒絶とともに「新たな申込み」をしたものとみなされます。","w":"民法第528条。","r":[["民法","528"]]},"4":{"t":false,"p":"承諾の期間内に承諾の通知を受けなかったときは、申込みは効力を「失います」。","w":"民法第523条第2項。","r":[["民法","523"]]}}},"08-35":{"s":"相続を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"公式正答では適切です。連帯債務者の1人が死亡した場合、相続人は相続分に応じて分割された債務を承継し、その範囲で他の連帯債務者と連帯するという考え方です（判例の考え方による）。","r":[["民法","899"]]},"2":{"t":false,"p":"配偶者と子が相続を放棄すると、初めから相続人とならなかったものとみなされるので、直系尊属が相続人と「なります」。","w":"民法第939条、第889条第1項第1号。","r":[["民法","939"],["民法","889"]]},"3":{"t":false,"p":"配偶者と兄弟姉妹が相続人の場合、兄弟姉妹の法定相続分は「3分の1」ではなく「4分の1」です。","w":"民法第900条第3号。","r":[["民法","900"]]},"4":{"t":false,"p":"共同相続人がいるときは、限定承認は全員が共同してのみでき、単独では「できません」。","w":"民法第923条。","r":[["民法","923"]]}}},"08-36":{"s":"犯罪収益移転防止法の取引時確認・記録を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"株式会社の実質的支配者は、議決権の総数の「2分の1」ではなく「4分の1」を超える議決権を直接又は間接に有する者などです。","w":"犯罪収益移転防止法施行規則第11条第2項第1号。","r":[["犯収法","4"],["犯罪による収益の移転防止に関する法律施行規則","11"]]},"2":{"t":true,"w":"犯罪収益移転防止法第6条第1項・第2項。","r":[["犯収法","6"]]},"3":{"t":false,"p":"少額の取引などの政令で定める取引は、取引記録の作成義務から「除かれます」。","w":"犯罪収益移転防止法第7条第1項。","r":[["犯収法","7"]]},"4":{"t":false,"p":"本邦内に住居を有しない外国人で政令で定めるものの本人特定事項は、「氏名、性別及び生年月日」ではなく、氏名・生年月日と、住居に代えて「主務省令で定める事項」です。","w":"犯罪収益移転防止法第4条第1項第1号。","r":[["犯収法","4"]]}}},"08-37":{"s":"制限行為能力者を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"民法第5条第1項。","r":[["民法","5"]]},"2":{"t":true,"w":"民法第17条第4項。","r":[["民法","17"]]},"3":{"t":false,"p":"行為能力者となった本人が期間内に確答しないときは、「取り消した」ではなく「追認した」ものとみなされます。","w":"民法第20条第1項。","r":[["民法","20"]]},"4":{"t":true,"w":"民法第17条第1項ただし書。","r":[["民法","17"]]}}},"08-38":{"s":"弁済（第三者弁済・受領権者としての外観を有する者への弁済・供託・差押え）を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"民法第474条第2項（現行法では「弁済をするについて正当な利益を有する者でない第三者」。債務者の意思に反することを債権者が知らなかったときは有効）。","r":[["民法","474"]]},"2":{"t":false,"p":"受領権者としての外観を有する者への弁済が有効になるのは、弁済者が善意かつ「無過失」のときです。過失があれば効力は認められ「ません」。","w":"民法第478条。","r":[["民法","478"]]},"3":{"t":true,"w":"民法第494条第2項（弁済者が過失なく債権者を確知できないとき）。","r":[["民法","494"]]},"4":{"t":true,"w":"民法第481条第1項。","r":[["民法","481"]]}}},"08-39":{"s":"相殺を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"民法第508条。","r":[["民法","508"]]},"2":{"t":false,"p":"不法行為の被害者Ａが、損害賠償債権（甲債権）を「自働債権」として相殺することは「できます」。相殺が禁止されるのは、加害者の側から損害賠償債務を受働債権として相殺する場合です。","w":"民法第509条（現行法では、悪意による不法行為や人の生命・身体の侵害による損害賠償の債務に限られます）。","r":[["民法","509"]]},"3":{"t":true,"w":"民法第511条第1項：差押え後に取得した債権による相殺は差押債権者に対抗できません。","r":[["民法","511"]]},"4":{"t":true,"w":"民法第507条。","r":[["民法","507"]]}}},"08-40":{"s":"取締役会設置会社を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"会社法第331条第5項。","r":[["会社法","331"]]},"2":{"t":true,"w":"会社法第356条第1項第1号、第365条第1項（取締役会設置会社では株主総会に代えて取締役会の承認）。","r":[["会社法","356"],["会社法","365"]]},"3":{"t":true,"w":"会社法第362条第3項。","r":[["会社法","362"]]},"4":{"t":false,"p":"多額の借財その他の重要な業務執行の決定は、取締役に委任することが「できません」。","w":"会社法第362条第4項第2号。","r":[["会社法","362"]]}}},"08-41":{"s":"強制執行手続（民事執行法）を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"民事執行法第25条。","r":[["民事執行法","25"]]},"2":{"t":true,"w":"民事執行法第28条第1項。","r":[["民事執行法","28"]]},"3":{"t":false,"p":"目的物について所有権などを有する第三者が提起するのは、「請求異議の訴え」ではなく「第三者異議の訴え」です。","w":"民事執行法第38条第1項。請求異議の訴え（第35条）は、債務名義に係る請求権の存在・内容に異議のある債務者が提起するものです。","r":[["民事執行法","38"],["民事執行法","35"]]},"4":{"t":true,"w":"民事執行法第39条第1項第5号。","r":[["民事執行法","39"]]}}},"08-42":{"s":"倒産処理手続の申立てを問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"破産法第18条第2項。","r":[["破産法","18"]]},"2":{"t":true,"w":"会社更生法第17条第2項第2号。","r":[["会社更生法","17"]]},"3":{"t":false,"p":"「事業の継続に著しい支障を来すことなく弁済期にある債務を弁済できないとき」に申し立てられるのは「債務者」だけです。債権者が申し立てられるのは、破産手続開始の原因となる事実の生ずるおそれがあるときです。","w":"民事再生法第21条第1項・第2項。","r":[["民事再生法","21"]]},"4":{"t":true,"w":"会社法第511条第2項。","r":[["会社法","511"]]}}},"08-43":{"s":"個人情報取扱事業者の義務を問う問題です。正しい組合せは「ａ正・ｂ誤・ｃ誤・ｄ正」です。","law":"ａの「相当の関連性」は出題時の条文の表現で、現行の第17条第2項では「関連性を有すると合理的に認められる範囲」とされています。ｃの「5,000人」の基準は2017年施行の改正で廃止され、現行法では取り扱う個人の数にかかわらず個人情報取扱事業者に当たります。","items":{"a":{"t":true,"w":"個人情報保護法第17条第1項・第2項。","r":[["個人情報保護法","17"]]},"b":{"t":false,"p":"取得の状況からみて利用目的が明らかであると認められるときは、通知又は公表は「不要」です。","w":"個人情報保護法第21条第4項第4号。","r":[["個人情報保護法","21"]]},"c":{"t":false,"p":"出題時の法令では、過去6か月以内の「いずれかの日」に5,000を超えれば個人情報取扱事業者に当たり、義務を「負いました」（公式正答による）。","w":"現行法では5,000人の基準はなく、個人情報データベース等を事業の用に供していれば個人情報取扱事業者です（第16条第2項）。","r":[["個人情報保護法","16"]]},"d":{"t":true,"w":"個人情報保護法第18条第2項。","r":[["個人情報保護法","18"]]}}},"08-44":{"s":"景品表示法を問う問題です。適切なのは③です。","law":"問題文の条番号は出題時のものです。現行法では、景品類の制限・禁止は第4条、不当な表示の禁止は第5条、措置命令は第7条、協定又は規約は第36条です。","items":{"1":{"t":false,"p":"景品類は、くじの方法によるかどうかを「問いません」。","w":"景品表示法第2条第3項。","r":[["景品表示法","2"]]},"2":{"t":false,"p":"表示を指定するのは、「公正取引委員会」ではなく「内閣総理大臣」です。","w":"景品表示法第2条第4項。","r":[["景品表示法","2"]]},"3":{"t":true,"w":"現行の景品表示法第36条第1項。","r":[["景品表示法","36"]]},"4":{"t":false,"p":"措置命令をするのは、「公正取引委員会」ではなく「内閣総理大臣」です。","w":"現行の景品表示法第7条第1項。","r":[["景品表示法","7"]]}}},"08-45":{"s":"消費者契約法を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"消費者契約法第4条第5項第1号・第2号（現行法では第3号も加わっています）。","r":[["消費者契約法","4"]]},"2":{"t":false,"p":"契約締結の時からの期間は、「3年」ではなく「5年」です。また、追認をすることができる時からの期間は、現行法では「6か月間」ではなく「1年間」です。","w":"消費者契約法第7条第1項。","r":[["消費者契約法","7"]]},"3":{"t":true,"w":"消費者契約法第8条第1項第4号。","r":[["消費者契約法","8"]]},"4":{"t":true,"w":"消費者契約法第4条第1項第1号。","r":[["消費者契約法","4"]]}}},"08-46":{"s":"日本貸金業協会の紛争解決等業務に関する規則を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"紛争解決等業務に関する規則第2条第2号。","r":[]},"2":{"t":false,"p":"代理人になれるのは、法定代理人、弁護士、認定司法書士（一定の額以下の苦情に限る）などです。「行政書士」は挙げられておらず、司法書士も認定司法書士に限られます（それ以外の者は相談センターの許可が必要）。","w":"紛争解決等業務に関する規則第38条第1項・第2項。","r":[]},"3":{"t":true,"w":"紛争解決等業務に関する規則第76条第1項第4号。","r":[]},"4":{"t":true,"w":"紛争解決等業務に関する規則第33条第1項・第2項。","r":[]}}},"08-47":{"s":"個人過剰貸付契約から除かれる契約（施行規則第10条の21）を問う問題です。該当しないのは①です。","items":{"1":{"t":false,"p":"不動産担保貸付けの除外では、個人顧客や担保を提供する者の「居宅」などは担保の対象から「除かれています」。居宅を担保とする貸付けは該当しません。","w":"施行規則第10条の21第1項第6号。","r":[["貸金業法施行規則","10の21"]]},"2":{"t":true,"w":"施行規則第10条の21第1項第3号。","r":[["貸金業法施行規則","10の21"]]},"3":{"t":true,"w":"施行規則第10条の21第1項第4号イ。","r":[["貸金業法施行規則","10の21"]]},"4":{"t":true,"w":"施行規則第10条の21第1項第1号。","r":[["貸金業法施行規則","10の21"]]}}},"08-48":{"s":"損益計算書の区分を問う問題です。適切なのはａｂです。会社計算規則は資料にないため、この問題は公式正答によります。","items":{"a":{"t":true,"w":"会社計算規則は取り込んだ資料にないため、この肢は公式正答によります。","r":[]},"b":{"t":true,"w":"会社計算規則は取り込んだ資料にないため、この肢は公式正答によります。","r":[]},"c":{"t":false,"p":"会社計算規則に規定する名称以外の名称を付すことが一切できないわけではありません（公式正答による）。","w":"会社計算規則は取り込んだ資料にないため、この肢は公式正答によります。","r":[]},"d":{"t":false,"p":"営業損益金額に営業外収益を加え営業外費用を減じた額は、「税引前当期純利益金額」ではなく「経常利益金額」として表示します。","w":"企業会計原則 損益計算書原則でも、経常損益計算の区分で経常利益を計算し、これに特別損益を加減して当期純利益を表示するとされています。会社計算規則の表示は公式正答によります。","r":[]}}},"08-49":{"s":"給与所得の源泉徴収票を問う問題です。適切なのは①です。所得税法や様式は取り込んだ資料にないため、この問題は公式正答によります。","items":{"1":{"t":true,"w":"所得税法や源泉徴収票の様式は取り込んだ資料にないため、この肢は公式正答によります。","r":[]},"2":{"t":false,"p":"「社会保険料等の金額」には、事業主（会社）が負担した社会保険料は「含まれません」（公式正答による）。","w":"所得税法や源泉徴収票の様式は取り込んだ資料にないため、この肢は公式正答によります。","r":[]},"3":{"t":false,"p":"「生命保険料の控除額」には、介護医療保険料の控除額も「含まれます」（公式正答による）。","w":"所得税法や源泉徴収票の様式は取り込んだ資料にないため、この肢は公式正答によります。","r":[]},"4":{"t":false,"p":"「支払金額」は、源泉徴収税額などを「差し引いた後」の手取額ではありません（公式正答による）。","w":"所得税法や源泉徴収票の様式は取り込んだ資料にないため、この肢は公式正答によります。","r":[]}}},"08-50":{"s":"企業会計原則の貸借対照表原則を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"企業会計原則 貸借対照表原則 一Ｃ。","r":[]},"2":{"t":true,"w":"企業会計原則 貸借対照表原則 三（流動性配列法）。","r":[]},"3":{"t":false,"p":"無形固定資産に属するのは営業権、特許権、地上権、商標権等です。「有価証券（流動資産に属しないもの）・出資金」は無形固定資産ではなく「投資その他の資産」に属します。","w":"企業会計原則 貸借対照表原則 四（一）Ｂ。","r":[]},"4":{"t":true,"w":"企業会計原則 貸借対照表原則 四（二）Ａ。","r":[]}}},"09-01":{"s":"貸金業法の用語の定義を問う問題です。適切なのはｂｃの2個です。","items":{"a":{"t":false,"p":"既存の営業所の隣接地に設置しても営業所に当たらないのは「現金自動設備」だけです。「自動契約受付機」は営業所又は事務所に「該当します」。","w":"施行規則第1条の5第3項：営業所又は事務所には自動契約受付機・現金自動設備・代理店を含み、ただし書で同一敷地内（隣接地を含む）の現金自動設備だけを除いています。","r":[["貸金業法施行規則","1の5"]]},"b":{"t":true,"w":"貸金業法第2条第13項・第14項。","r":[["貸金業法","2"]]},"c":{"t":true,"w":"貸金業法第2条第9項。","r":[["貸金業法","2"]]},"d":{"t":false,"p":"公益社団法人の貸付けが貸金業から除かれるのは、収益を目的とする事業として行うものを「除いた」場合です。収益事業として行う貸付けは、貸金業から除かれ「ません」。","w":"貸金業法第2条第1項第5号、施行令第1条の2第2号イ。","r":[["貸金業法","2"],["貸金業法施行令","1の2"]]}}},"09-02":{"s":"登録の拒否事由（貸金業法第6条第1項）を問う問題です。拒否されるのは④です。","items":{"1":{"t":false,"p":"審査基準は、常務に従事する役員のうちに「貸付けの業務」に3年以上の経験者がいることで、「貸金業者での経験」に限られていません。銀行での貸付けの業務の経験でも拒否されません（公式正答による）。","w":"施行規則第5条の7第1項第2号。","r":[["貸金業法","6"],["貸金業法施行規則","5の7"]]},"2":{"t":false,"p":"拒否事由になるのは取消しの日前「30日以内」に役員であった者です。「60日前」に退任した者は該当しません。","w":"貸金業法第6条第1項第3号。","r":[["貸金業法","6"]]},"3":{"t":false,"p":"罰金の刑の執行を終わった日などから「5年を経過しない」者が拒否事由です。5年を経過した者は該当しません。","w":"貸金業法第6条第1項第5号。","r":[["貸金業法","6"]]},"4":{"t":true,"w":"貸金業法第6条第1項第14号、施行令第3条の2：最低純資産額は5,000万円です。3,000万円では満たしません。","r":[["貸金業法","6"],["貸金業法施行令","3の2"]]}}},"09-03":{"s":"監督指針Ⅱ－２－３（外部委託）を問う問題です。適切なのはｂｃです。","items":{"a":{"t":false,"p":"外部委託には、外部委託された業務等が海外で行われる場合も「含まれます」。","w":"監督指針Ⅱ－２－３（１）③（注）。","r":[["貸金業法施行規則","10の5"]]},"b":{"t":true,"w":"監督指針Ⅱ－２－３（１）⑤。","r":[]},"c":{"t":true,"w":"監督指針Ⅱ－２－３（１）⑩。","r":[]},"d":{"t":false,"p":"苦情等について設けるのは、資金需要者等から「外部委託先の責任者」ではなく、「委託元である貸金業者」への直接の連絡体制です。","w":"監督指針Ⅱ－２－３（１）⑪。","r":[]}}},"09-04":{"s":"監督指針Ⅱ－２－１０（禁止行為等）を問う問題です。ａ〜ｄはすべて適切なので4個です。","items":{"a":{"t":true,"w":"監督指針Ⅱ－２－１０（２）①ロ。","r":[["貸金業法","12の6"]]},"b":{"t":true,"w":"監督指針Ⅱ－２－１０（２）②なお書き。","r":[["貸金業法","12の6"]]},"c":{"t":true,"w":"監督指針Ⅱ－２－１０（２）②イｆ。","r":[["貸金業法","12の6"]]},"d":{"t":true,"w":"監督指針Ⅱ－２－１０（２）②ホ。","r":[["貸金業法","12の6"]]}}},"09-05":{"s":"返済能力の調査を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"返済能力の調査は、法人顧客Ｂについても「必要」です。","w":"貸金業法第13条第1項：貸付けの契約を締結しようとする場合には、顧客等（法人を含む）の返済能力を調査しなければなりません。","r":[["貸金業法","13"]]},"2":{"t":true,"w":"貸金業法第13条第2項、施行規則第10条の16第2号・第1条の2の3第5号：貸金業者を債権者とする金銭の貸借の媒介に係る契約は、信用情報の使用義務から除かれます。","r":[["貸金業法","13"],["貸金業法施行規則","10の16"],["貸金業法施行規則","1の2の3"]]},"3":{"t":false,"p":"資力を明らかにする書面等が必要なのは、当該貸金業者合算額が50万円を「超える」場合です。ちょうど50万円なら「不要」です。","w":"貸金業法第13条第3項第1号。","r":[["貸金業法","13"]]},"4":{"t":false,"p":"他社分を含めた個人顧客合算額が100万円を「超える」場合に必要です。40万円＋60万円＝ちょうど100万円なら「不要」です。","w":"貸金業法第13条第3項第2号。","r":[["貸金業法","13"]]}}},"09-06":{"s":"個人過剰貸付契約から除かれる契約（施行規則第10条の21）を問う問題です。該当するのはａｂです。","items":{"a":{"t":true,"w":"施行規則第10条の21第1項第8号・第1条の2の3第2号：手形（融通手形を除く）の割引を内容とする契約。","r":[["貸金業法施行規則","10の21"],["貸金業法施行規則","1の2の3"]]},"b":{"t":true,"w":"施行規則第10条の21第1項第4号イ。","r":[["貸金業法施行規則","10の21"]]},"c":{"t":false,"p":"有価証券担保の貸付けは、貸付けの金額が有価証券の「時価の範囲内」のものに限られます。時価を超えるものは該当しません（「1,000万円以下」という基準はありません）。","w":"施行規則第10条の21第1項第5号。","r":[["貸金業法施行規則","10の21"]]},"d":{"t":false,"p":"自動車購入資金の貸付けが該当するのは、自動車の所有権を貸金業者が取得し、又は自動車が譲渡により担保の目的となっている「もの」に限られます。","w":"施行規則第10条の21第1項第3号。","r":[["貸金業法施行規則","10の21"]]}}},"09-07":{"s":"極度方式基本契約の定期的な調査（貸金業法第13条の3第2項）を問う問題です。適切なのはａｃです。","items":{"a":{"t":true,"w":"貸金業法第13条の3第5項。","r":[["貸金業法","13の3"]]},"b":{"t":false,"p":"「残高10万円超かつ貸付額5万円超」は、1か月ごとの調査（第13条の3第1項、施行規則第10条の24）の要件です。3か月ごとの調査（第2項）が不要になるのは、期間の末日の残高が「10万円以下」である場合などです。","w":"施行規則第10条の25第3項第1号。","r":[["貸金業法","13の3"],["貸金業法施行規則","10の25"],["貸金業法施行規則","10の24"]]},"c":{"t":true,"w":"施行規則第10条の25第2項。","r":[["貸金業法施行規則","10の25"]]},"d":{"t":false,"p":"資力を明らかにする書面等が必要なのは、極度方式個人顧客合算額が100万円を「超える」場合です。ちょうど100万円なら不要で、また既に提出を受けている場合も改めて受ける必要は「ありません」（第13条の3第3項ただし書）。","w":"貸金業法第13条の3第3項。","r":[["貸金業法","13の3"]]}}},"09-08":{"s":"日本貸金業協会の自主規制規則（広告・勧誘）を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"審査機関の承認が必要な広告には、テレビＣＭ、新聞・雑誌広告のほか「電話帳広告」も含まれます。","w":"自主規制基本規則第45条第1項。","r":[]},"2":{"t":false,"p":"協会員は、比較広告を「行わない」こととされています（事実の裏付けがあっても同じ。借換えの例外に関する広告を除く）。","w":"貸金業者の広告に関する細則Ⅰ．４．⑶②。","r":[]},"3":{"t":true,"w":"貸金業者の広告に関する細則（ラジオＣＭに関する遵守事項等）⑵：電話番号を告知する際、「申込み」という表現をとらないよう留意する。","r":[]},"4":{"t":false,"p":"債務者等に勧誘を行うに際しては、当該債務者等から勧誘を行うことについての承諾を得る必要が「あります」。","w":"自主規制基本規則第54条第1項。","r":[]}}},"09-09":{"s":"保証人に交付する書面を問う問題です。適切なのはａｃです。","items":{"a":{"t":true,"w":"施行規則第12条の2第7項：概要書面には第4項第1号イ〜ハ（ロが債務の残高の総額）を記載し、詳細書面では第4項第1号のイ・ロが除かれています。","r":[["貸金業法","16の2"],["貸金業法施行規則","12の2"]]},"b":{"t":false,"p":"保証の対象となる貸付けに係る契約が2以上あるときは、当該契約「ごとに」記載しなければ「なりません」。","w":"施行規則第13条第8項。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"c":{"t":true,"w":"施行規則第13条第7項第1号イ：保証人が負担すべき保証債務以外の金銭に関する事項（第12条の2第6項第6号）は、保証人の利益となる変更なら再交付は不要です。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"d":{"t":false,"p":"利息の計算の方法の変更は、債務者の利益となる変更なら再交付は「不要」です。","w":"施行規則第13条第10項（第17条第4項後段は第2項に定める事項による）、第2項第1号イ。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]}}},"09-10":{"s":"極度方式基本契約・極度方式貸付けの書面を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"極度方式貸付けに係る契約は、契約締結前の書面（第16条の2第1項）の交付義務の対象から「除かれています」。","w":"貸金業法第16条の2第1項の括弧書。","r":[["貸金業法","16の2"]]},"2":{"t":true,"w":"施行規則第13条第3項第1号ニ。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"3":{"t":false,"p":"極度額を引き下げた後、元の額を上回らない額まで引き上げたときは、再交付は「不要」です。","w":"施行規則第13条第5項第2号。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"4":{"t":false,"p":"簡素化書面の記載事項は、受領年月日・受領金額などで、「その利息」や「弁済後の残存債務の額」の記載は求められていません（公式正答による）。","w":"貸金業法第18条第3項。残存債務の額は、通常の受取証書の記載事項です（施行規則第15条第1項第5号）。","r":[["貸金業法","18"],["貸金業法施行規則","15"]]}}},"09-11":{"s":"貸金業者が保存すべき記録・帳簿の保存期間を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"施行規則第10条の18第2項第1号。","r":[["貸金業法","13"],["貸金業法施行規則","10の18"]]},"2":{"t":false,"p":"基準額超過極度方式基本契約に係る調査の記録は、最終の返済期日などまでではなく、「作成後3年間」保存します。","w":"施行規則第10条の27第2項。","r":[["貸金業法施行規則","10の27"]]},"3":{"t":false,"p":"従業者名簿の保存期間は、最終の記載をした日から「5年間」ではなく「10年間」です。","w":"施行規則第10条の9の2第3項。","r":[["貸金業法","12の4"],["貸金業法施行規則","10の9の2"]]},"4":{"t":false,"p":"帳簿の保存期間の起算点は、「契約を締結した日」ではなく、「最終の返済期日（債権が消滅したときはその日）」です。","w":"施行規則第17条第1項。","r":[["貸金業法","19"],["貸金業法施行規則","17"]]}}},"09-12":{"s":"登録の取消し（所在不明者等）を問う問題です。取り消すことができるのは②です。","items":{"1":{"t":false,"p":"公告の日から「2週間」ではなく「30日」を経過しても申出がないときです。","w":"貸金業法第24条の6の6第1項第1号。","r":[["貸金業法","24の6の6"]]},"2":{"t":true,"w":"貸金業法第24条の6の6第1項第2号。","r":[["貸金業法","24の6の6"]]},"3":{"t":false,"p":"休止による取消しは、引き続き「3か月以上」ではなく「6月以上」休止したときです。","w":"貸金業法第24条の6の6第1項第2号。","r":[["貸金業法","24の6の6"]]},"4":{"t":false,"p":"被補助人となったことは、登録の取消し事由に「当たりません」。","w":"登録の取消し事由（第24条の6の5第1項第1号）は第6条第1項第1号・第4号〜第12号などで、被補助人は挙げられていません（公式正答による）。","r":[["貸金業法","24の6の5"],["貸金業法","6"]]}}},"09-13":{"s":"指定信用情報機関への個人信用情報の提供を問う問題です。適切なのはａｃの2個です。","items":{"a":{"t":true,"w":"貸金業法第41条の35第1項、施行規則第30条の12。","r":[["貸金業法","41の35"],["貸金業法施行規則","30の12"]]},"b":{"t":false,"p":"極度方式基本契約は、個人信用情報の提供の対象から「除かれています」。","w":"施行規則第30条の12・第1条の2の3第1号、貸金業法第2条第14項。","r":[["貸金業法","41の35"],["貸金業法施行規則","30の12"]]},"c":{"t":true,"w":"貸金業法第41条の35第3項：提供した個人信用情報に変更があったときは遅滞なく提供。勤務先の商号又は名称は個人信用情報に含まれます（施行規則第30条の13第1項第5号）。","r":[["貸金業法","41の35"],["貸金業法施行規則","30の13"]]},"d":{"t":false,"p":"同意に関する記録の保存期間は、提供した日から「10年間」ではなく、「当該同意に基づき指定信用情報機関が信用情報を保有している間」です。","w":"施行規則第30条の16第1項。","r":[["貸金業法","41の36"],["貸金業法施行規則","30の16"]]}}},"09-14":{"s":"利息制限法の元本額の特則（第5条）を問う問題です。適切なのはａｂです。","items":{"a":{"t":true,"w":"利息制限法第5条第1号：第二貸付契約の元本は残高5万円＋5万円＝10万円とみなされ、上限は年1割8分です。","r":[["利息制限法","5"],["利息制限法","1"]]},"b":{"t":true,"w":"利息制限法第5条第2号：同時に貸し付けた元本の合計120万円とみなされ、上限は年1割5分です。","r":[["利息制限法","5"],["利息制限法","1"]]},"c":{"t":false,"p":"第三貸付契約の元本とみなされる額は、残高70万円＋同時に貸し付けた25万円と5万円＝100万円です。上限は年1割8分ではなく「年1割5分」です。","w":"利息制限法第5条第1号、第1条第3号。","r":[["利息制限法","5"],["利息制限法","1"]]},"d":{"t":false,"p":"元本額の特則は「同一の債権者」から重ねて貸付けを受けた場合です。別の債権者Ｃ社の貸付け（元本50万円）の上限は年1割8分で、無効に「なりません」。","w":"利息制限法第5条第1号、第1条第2号。","r":[["利息制限法","5"],["利息制限法","1"]]}}},"09-15":{"s":"保証料の制限（利息制限法第8条・第9条）を問う問題です。適切なのは④です。保証料の上限は「法定上限額（第1条の上限金利で計算した利息）−約定の利息」が基本です。","items":{"1":{"t":false,"p":"受けられる保証料は24,000円ではなく、16,000円までです。","w":"利息制限法第8条第2項第1号：法定上限額（80万円×年1割8分＝144,000円）から特約上限利率で計算した利息（80万円×16％＝128,000円）を引いた額。","r":[["利息制限法","8"],["利息制限法","1"]]},"2":{"t":false,"p":"受けられる保証料は1年当たり100,000円ではなく、75,000円までです。","w":"利息制限法第8条第4項第2号：元本極度額を元本とみなした法定上限額（100万円×年1割5分＝150,000円）の2分の1。","r":[["利息制限法","8"],["利息制限法","1"]]},"3":{"t":false,"p":"Ｄが受けられる保証料は10,000円ではなく、5,000円までです。","w":"利息制限法第8条第1項・第6項：保証料の上限は法定上限額54,000円（30万円×年1割8分）−利息39,000円（30万円×13％）＝15,000円。他の保証人Ｃの保証料10,000円を引くと5,000円です。","r":[["利息制限法","8"],["利息制限法","1"]]},"4":{"t":true,"w":"利息制限法第9条第1項：増加後の利息は、法定上限額90,000円（50万円×年1割8分）−保証料15,000円＝75,000円（年1割5分）を超える部分が無効です。","r":[["利息制限法","9"],["利息制限法","1"]]}}},"09-16":{"s":"登録申請書の記載事項（役員・政令で定める使用人）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"施行規則第2条第1号：総株主等の議決権の100分の25を超える議決権に係る株式等を所有している個人は、取締役等と同等以上の支配力を有する者として役員に含まれ、申請書に記載します（第4条第1項第2号）。","r":[["貸金業法","4"],["貸金業法施行規則","2"]]},"2":{"t":true,"w":"施行規則第2条第2号：親会社の総株主等の議決権の100分の50を超える議決権に係る株式等を所有している個人。","r":[["貸金業法","4"],["貸金業法施行規則","2"]]},"3":{"t":true,"w":"施行令第3条、施行規則第3条第2号（主たる営業所等で一切の裁判外の行為をなす権限を有する者）。","r":[["貸金業法施行令","3"],["貸金業法施行規則","3"]]},"4":{"t":false,"p":"支店次長などが政令で定める使用人に当たるのは、貸付けに関する業務に従事する使用人の数が「20人」ではなく「50人以上」の従たる営業所等です。","w":"施行規則第3条第3号。","r":[["貸金業法施行令","3"],["貸金業法施行規則","3"]]}}},"09-17":{"s":"変更の届出（貸金業法第8条）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"商号の変更は、「あらかじめ」ではなく、変更があった日から「2週間以内」に届け出ます。","w":"貸金業法第8条第1項：あらかじめ届け出るのは第4条第1項第5号（営業所等の名称・所在地）と第7号（広告等で表示する連絡先等）です。","r":[["貸金業法","8"],["貸金業法","4"]]},"2":{"t":true,"w":"貸金業法第8条第1項、第4条第1項第7号。","r":[["貸金業法","8"],["貸金業法","4"]]},"3":{"t":true,"w":"貸金業法第8条第1項、第4条第1項第8号（業務の種類及び方法）。","r":[["貸金業法","8"],["貸金業法","4"]]},"4":{"t":true,"w":"貸金業法第8条第1項、第4条第1項第2号。","r":[["貸金業法","8"],["貸金業法","4"]]}}},"09-18":{"s":"廃業等の届出（貸金業法第10条）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"再生手続開始の決定は、第10条の届出事由に「含まれません」（届出事由は死亡、合併による消滅、破産手続開始の決定、解散、廃止など）。","w":"貸金業法第10条第1項各号。","r":[["貸金業法","10"]]},"2":{"t":true,"w":"貸金業法第10条第1項第2号。","r":[["貸金業法","10"]]},"3":{"t":true,"w":"貸金業法第10条第1項第5号。","r":[["貸金業法","10"]]},"4":{"t":true,"w":"貸金業法第10条第1項第3号。","r":[["貸金業法","10"]]}}},"09-19":{"s":"貸金業務取扱主任者の設置を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"施行規則第10条の8：貸金業の業務に従事する者の50分の1以上。60名のうち業務に従事するのは45名なので、1名で足ります。人事・経理などの業務に従事する者は原則として含まれません（監督指針Ⅱ－２－９（２）②）。","r":[["貸金業法","12の3"],["貸金業法施行規則","10の8"]]},"2":{"t":true,"w":"貸金業法第12条の3第3項：予見し難い事由で主任者が不足したときは、2週間以内に必要な措置をとります。","r":[["貸金業法","12の3"]]},"3":{"t":false,"p":"代理店（貸金業者である場合に限る）に主任者を置く場合は、常時勤務や他の営業所との重複の制限が適用されないため、Ｂは兼務「できます」。","w":"施行規則第10条の7第1項ただし書。","r":[["貸金業法施行規則","10の7"]]},"4":{"t":true,"w":"貸金業法第14条第1項第4号。","r":[["貸金業法","14"]]}}},"09-20":{"s":"極度額の増額と返済能力の調査を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"施行規則第10条の19。","r":[["貸金業法","13"],["貸金業法施行規則","10の19"]]},"2":{"t":false,"p":"極度額を下回る額を提示している場合に、その額を増額することも極度額の増額として扱われ、返済能力の調査が「必要」です。","w":"貸金業法第13条第5項の括弧書。","r":[["貸金業法","13"]]},"3":{"t":true,"w":"返済能力の低下による減額の後の増額は、施行規則第10条の19の例外に当たりません。","r":[["貸金業法","13"],["貸金業法施行規則","10の19"]]},"4":{"t":true,"w":"貸金業法第13条第5項で準用する第4項、施行規則第10条の18第2項第1号。","r":[["貸金業法","13"],["貸金業法施行規則","10の18"]]}}},"09-21":{"s":"3か月ごとの調査が不要な場合（施行規則第10条の25第3項）を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"施行規則第10条の25第3項第2号・第3号（新たな極度方式貸付けの停止の措置）。","r":[["貸金業法施行規則","10の25"]]},"2":{"t":false,"p":"「極度額の減額」の措置を講じていても、調査は不要に「なりません」。不要になるのは「新たな極度方式貸付けの停止」の措置などです。","w":"施行規則第10条の25第3項第2号（第10条の29第2号の停止の措置を指し、第1号の減額は含まれません）。","r":[["貸金業法施行規則","10の25"],["貸金業法施行規則","10の29"]]},"3":{"t":true,"w":"施行規則第10条の25第3項第4号（第1条の2の3第5号の貸借の媒介）。","r":[["貸金業法施行規則","10の25"]]},"4":{"t":true,"w":"施行規則第10条の25第3項第4号（第10条の21第1項第7号の契約）。","r":[["貸金業法施行規則","10の25"]]}}},"09-22":{"s":"契約締結前の書面（貸金業法第16条の2第1項）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"貸金業者の住所は法律で定める記載事項（第16条の2第1項第1号）で、登録番号などを記載しても省略「できません」。","w":"貸金業法第16条の2第1項第1号、施行規則第12条の2第1項第1号イ（登録番号は別の記載事項）。","r":[["貸金業法","16の2"],["貸金業法施行規則","12の2"]]},"2":{"t":true,"w":"施行規則第12条の2第1項第1号チ。","r":[["貸金業法施行規則","12の2"]]},"3":{"t":true,"w":"施行規則第12条の2第1項第1号リ。","r":[["貸金業法施行規則","12の2"]]},"4":{"t":true,"w":"施行規則第12条の2第9項（現行の表記は「日本産業規格」）。","r":[["貸金業法施行規則","12の2"]]}}},"09-23":{"s":"契約締結時の書面の再交付（貸金業法第17条第1項後段）を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"契約の相手方の住所（施行規則第13条第1項第1号ロ）は、再交付が必要な事項（同条第2項第1号）に含まれていません。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"2":{"t":true,"w":"施行規則第13条第2項第1号イ（第1項第1号リ）：相手方の利益となる変更なら再交付は不要です。","r":[["貸金業法施行規則","13"]]},"3":{"t":false,"p":"返済の方法及び返済を受ける場所の変更は、相手方の利益となる変更でも再交付が「必要」です。","w":"施行規則第13条第2項第1号ロ（第1項第1号ト）。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"4":{"t":true,"w":"施行規則第13条第2項第1号ロ：保証人の商号・氏名等（第1項第1号ヲ）は、新たに保証契約を締結する場合に再交付が必要です。","r":[["貸金業法施行規則","13"]]}}},"09-24":{"s":"帳簿の閲覧・謄写（貸金業法第19条の2）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"貸金業法第19条の2後段：請求が権利の行使に関する調査を目的とするものでないことが明らかであるときは、拒むことができます。","r":[["貸金業法","19の2"]]},"2":{"t":true,"w":"施行規則第17条の3：貸金業者は、営業時間内に請求に応じて閲覧又は謄写をさせなければなりません。営業時間外の請求に翌営業日以降の再請求を求めることは、拒否には当たりません。","r":[["貸金業法","19の2"],["貸金業法施行規則","17の3"]]},"3":{"t":true,"w":"監督指針Ⅱ－２－１８（１）③：帳簿の複写や複写物の郵送に係る実費を徴収する場合、その金額は適正かつ適切な金額となっているか。","r":[["貸金業法","19の2"]]},"4":{"t":false,"p":"閲覧・謄写の対象は取引履歴の部分に「限られず」、交渉の経過の記録も対象に「なります」（公式正答による）。","w":"帳簿の記載事項には交渉の経過の記録が含まれます（施行規則第16条第1項第7号）。閲覧・謄写の対象は、帳簿のうち請求者に利害関係がある部分です（第19条の2）。","r":[["貸金業法","19の2"],["貸金業法施行規則","16"]]}}},"09-25":{"s":"債権譲渡等の規制を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"譲受人への通知は、譲受人が貸金業者であっても、債権譲渡契約で不要と定めても、省略「できません」。","w":"貸金業法第24条第1項には、通知を省略できる定めがありません。","r":[["貸金業法","24"]]},"2":{"t":true,"w":"貸金業法第24条第2項：第17条などの規定が債権の譲受人に準用されます（貸金業者かどうかを問いません）。","r":[["貸金業法","24"],["貸金業法","17"]]},"3":{"t":true,"w":"監督指針Ⅱ－２－２０（債権譲渡等）（１）④。","r":[["貸金業法","24"]]},"4":{"t":true,"w":"貸金業法第19条、施行規則第17条第1項。","r":[["貸金業法","19"],["貸金業法施行規則","17"]]}}},"09-26":{"s":"開始等の届出（施行規則第26条の25）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"届出が必要なのは、債権を他人に「譲渡した」場合です。他人から「譲渡を受けた」場合は「含まれません」。","w":"施行規則第26条の25第1項第3号、第2項（2週間以内）。","r":[["貸金業法","24の6の2"],["貸金業法施行規則","26の25"]]},"2":{"t":true,"w":"施行規則第26条の25第1項第4号、第2項。","r":[["貸金業法施行規則","26の25"]]},"3":{"t":true,"w":"施行規則第26条の25第1項第5号、第2項。","r":[["貸金業法施行規則","26の25"]]},"4":{"t":true,"w":"施行規則第26条の25第1項第6号、第2項。","r":[["貸金業法施行規則","26の25"]]}}},"09-27":{"s":"利息・賠償額の予定・媒介手数料の規制を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"出資法第4条第1項。","r":[["出資法","4"]]},"2":{"t":true,"w":"出資法第5条の4第3項。","r":[["出資法","5の4"]]},"3":{"t":false,"p":"営業的金銭消費貸借の賠償額の予定の上限は、第1条の率の「1.46倍」ではなく「年2割」です（1.46倍は営業的でない場合の上限です）。","w":"利息制限法第7条第1項（第4条第1項の特則）。","r":[["利息制限法","7"],["利息制限法","4"]]},"4":{"t":true,"w":"貸金業法第12条の8第1項（契約の締結）・第4項（受領・支払の要求）。違反は業務改善命令などの行政処分の対象です（第24条の6の3など）。","r":[["貸金業法","12の8"],["貸金業法","24の6の3"]]}}},"09-28":{"s":"制限行為能力者を問う問題です。適切なのは④です。","law":"①について、現行の民法では成年年齢が18歳とされ（第4条）、婚姻による成年擬制（旧第753条）は削除されています。","items":{"1":{"t":false,"p":"出題時の民法では、婚姻により成年に達したものとみなされた者が20歳になる前に離婚しても、未成年者に「戻るとはされていませんでした」（公式正答による）。","w":"現行法では婚姻による成年擬制の規定自体がありません。","r":[["民法","4"]]},"2":{"t":false,"p":"成年被後見人の法律行為は、成年後見人の同意を得ていても取り消すことが「できます」（日用品の購入など日常生活に関する行為を除く）。","w":"民法第9条。","r":[["民法","9"]]},"3":{"t":false,"p":"遺贈の放棄にも、保佐人の同意が「必要」です。","w":"民法第13条第1項第6号（相続の放棄）・第7号（遺贈の放棄）。","r":[["民法","13"]]},"4":{"t":true,"w":"民法第20条第1項。","r":[["民法","20"]]}}},"09-29":{"s":"意思表示（虚偽表示・詐欺・強迫・錯誤）を問う問題です。適切なのは③です。","law":"この回の基準日は2020年4月の民法改正の前です。②の第三者による詐欺は、現行の第96条第2項では相手方が「知り、又は知ることができたとき」に取り消せます。④の錯誤は、現行の第95条では「無効」ではなく「取り消すことができる」とされています。どちらの記述も、現行法でも適切ではありません。","items":{"1":{"t":false,"p":"虚偽表示による無効は、善意の第三者Ｃに対抗「できません」。","w":"民法第94条第2項。","r":[["民法","94"]]},"2":{"t":false,"p":"第三者Ｄの詐欺の場合、相手方Ｂが詐欺の事実を知らなかったときは、取り消すことが「できません」（現行法では、知ることができたときは取り消せます）。","w":"民法第96条第2項。","r":[["民法","96"]]},"3":{"t":true,"w":"民法第96条第3項が第三者を保護しているのは「詐欺」による取消しだけです。強迫による取消しは、善意の第三者Ｅにも対抗できます。","r":[["民法","96"]]},"4":{"t":false,"p":"表意者Ａに重大な過失があるときは、錯誤を主張「できません」（現行法では、相手方が悪意・重過失のときなどの例外を除き、取り消すことができません）。","w":"民法第95条第3項。","r":[["民法","95"]]}}},"09-30":{"s":"条件と期限を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"民法第127条第1項・第2項。","r":[["民法","127"]]},"2":{"t":false,"p":"逆です。不能の停止条件を付した法律行為は「無効」、不能の解除条件を付した法律行為は「無条件」です。","w":"民法第133条。","r":[["民法","133"]]},"3":{"t":false,"p":"始期を付した法律行為の履行は、期限が到来する「まで」請求できません。「相当の期間が経過するまで」ではありません。","w":"民法第135条第1項。","r":[["民法","135"]]},"4":{"t":false,"p":"期限の利益は放棄することが「できます」（相手方の利益を害することはできません）。","w":"民法第136条第2項。","r":[["民法","136"]]}}},"09-31":{"s":"質権と抵当権を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"動産質権の設定は、契約だけでなく目的物を「引き渡すこと」によって効力を生じます。また、質権者は、質権設定者に質物を占有させることは「できません」。","w":"民法第344条、第345条。","r":[["民法","344"],["民法","345"]]},"2":{"t":false,"p":"転質による損失は、「不可抗力によるもの」であっても質権者が責任を負います。","w":"民法第348条。","r":[["民法","348"]]},"3":{"t":false,"p":"地上権及び永小作権も、抵当権の目的とすることが「できます」。","w":"民法第369条第2項。","r":[["民法","369"]]},"4":{"t":true,"w":"民法第378条（代価弁済）。","r":[["民法","378"]]}}},"09-32":{"s":"保証を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"保証契約は、口頭の合意ではなく「書面」（又は電磁的記録）でしなければ効力を生じません。","w":"民法第446条第2項・第3項。","r":[["民法","446"]]},"2":{"t":false,"p":"保証債務は、特約がなくても、主たる債務に関する違約金や損害賠償も「包含します」。","w":"民法第447条第1項。","r":[["民法","447"]]},"3":{"t":false,"p":"保証人の負担が主たる債務より重いときは減縮されますが、軽いときに主たる債務の限度まで「加重されることはありません」。","w":"民法第448条。","r":[["民法","448"]]},"4":{"t":true,"w":"民法第462条第1項（第459条の2第1項を準用）：委託を受けない保証人は、主たる債務者がその当時利益を受けた限度で求償できます。","r":[["民法","462"],["民法","459の2"]]}}},"09-33":{"s":"債権の消滅を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"民法第520条（混同）。","r":[["民法","520"]]},"2":{"t":false,"p":"代物弁済には、債権者の承諾（現行法では債権者との契約）が「必要」です。","w":"民法第482条。","r":[["民法","482"]]},"3":{"t":false,"p":"相殺の意思表示には、条件又は期限を付することが「できません」。","w":"民法第506条第1項。","r":[["民法","506"]]},"4":{"t":false,"p":"正当な利益を有しない者は、「当然に」代位するのではありません。出題時の民法では、弁済と同時に債権者の承諾を得て代位するとされていました（公式正答による）。","w":"現行の民法第499条・第500条では債権者の承諾は不要になりましたが、正当な利益を有しない者が代位を債務者や第三者に対抗するには、第467条の通知・承諾が必要です。","r":[["民法","499"],["民法","500"]]}}},"09-34":{"s":"売買契約の危険負担・同時履行・解除を問う問題です。公式正答は③です。","law":"①は、改正前の民法第534条（特定物に関する契約では、債務者の責めに帰することができない滅失の危険は債権者が負担する）による記述です。この条文は削除され、現行の第536条第1項では、債権者Ｂは代金の支払を拒むことができます。現行法では①は適切です。","items":{"1":{"t":false,"now":true,"p":"出題時の民法では、特定物の売買で売主Ａの責めに帰することができない事由で滅失したとき、Ａは代金を請求「できる」とされていました（旧第534条、公式正答による）。","w":"現行の民法第536条第1項では、買主Ｂは代金の支払を拒むことができるため、記述は適切です。","r":[["民法","536"]]},"2":{"t":false,"p":"Ａが甲商品を提供していないので、Ｂは同時履行の抗弁により代金の支払を拒むことが「できます」。","w":"民法第533条。","r":[["民法","533"]]},"3":{"t":true,"w":"民法第544条第1項：当事者の一方が数人あるときは、解除はその全員に対してしなければなりません。","r":[["民法","544"]]},"4":{"t":false,"p":"解除の意思表示は撤回「できません」。","w":"民法第540条第2項。","r":[["民法","540"]]}}},"09-35":{"s":"約束手形と電子記録債権を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"手形法第75条（約束手形の記載事項）。","r":[["手形法","75"]]},"2":{"t":false,"p":"支払呈示の期間は、支払をなすべき日又はこれに次ぐ「3取引日」ではなく「2取引日」内です。","w":"手形法第38条第1項（約束手形には第77条第1項第3号で準用）。","r":[["手形法","38"],["手形法","77"]]},"3":{"t":false,"p":"支払が有効になるのは、支払をした者に悪意又は重大な過失が「ない」ときに限られます。","w":"電子記録債権法第21条ただし書。","r":[["電子記録債権法","21"]]},"4":{"t":false,"p":"電子記録債権の譲渡は、合意だけでは効力を生じません。譲渡記録は対抗要件ではなく「効力要件」です。","w":"電子記録債権法第17条。","r":[["電子記録債権法","17"]]}}},"09-36":{"s":"復代理と双方代理を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"民法第104条。","r":[["民法","104"]]},"2":{"t":false,"p":"法定代理人は自己の責任で復代理人を選任でき、本人に対して全面的に責任を負います。選任及び監督についての責任「のみ」を負うのは、「やむを得ない事由があるとき」です。","w":"民法第105条。","r":[["民法","105"]]},"3":{"t":true,"w":"民法第106条第2項（現行法では「その権限の範囲内において」と明記）。","r":[["民法","106"]]},"4":{"t":true,"w":"民法第108条第1項。現行の条文では、双方代理などは「代理権を有しない者がした行為とみなす」と定められています。","r":[["民法","108"]]}}},"09-37":{"s":"時効の中断を問う問題です。適切でないのは①です。","law":"この回の基準日は2020年4月の民法改正の前で、「時効の中断」の制度で出題されています。現行法では「時効の完成猶予」と「時効の更新」に改められ、仮差押えはその事由が終了した時から6箇月を経過するまで時効の完成を猶予し（第149条）、催告は催告の時から6箇月を経過するまで時効の完成を猶予します（第150条）。","items":{"1":{"t":false,"p":"仮差押えについて「6か月以内に差押えをしなければ時効中断の効力を生じない」という定めはありません。出題時の民法では、仮差押えは権利者の請求により又は法律の規定に従わないことにより取り消されたときに中断の効力を生じないとされていました（公式正答による）。","w":"現行の民法第149条では、仮差押えは完成猶予の事由です。","r":[["民法","149"]]},"2":{"t":true,"w":"民法第146条。","r":[["民法","146"]]},"3":{"t":true,"w":"出題時の民法（旧第153条）による記述です（公式正答による）。現行の第150条では、催告から6箇月を経過するまで時効の完成が猶予され、その間に裁判上の請求などをすれば第147条の完成猶予・更新に進みます。","r":[["民法","150"],["民法","147"]]},"4":{"t":true,"w":"出題時の民法（旧第157条）による記述です（公式正答による）。現行法では、裁判上の請求などで権利が確定したときは、その事由が終了した時から時効が新たに進行を始めます（第147条第2項。時効の更新）。","r":[["民法","147"]]}}},"09-38":{"s":"債務不履行・受領遅滞・債権者代位権・詐害行為取消権を問う問題です。適切でないのは③です。","law":"①の「裁判所は賠償額の予定の額を増減することができない」との定め（旧第420条第1項後段）は、2020年の改正で削除されました。②の受領遅滞も、現行の第413条では、債務者の保存義務の軽減と増加費用の債権者負担という効果が定められています。","items":{"1":{"t":true,"w":"出題時の民法（旧第420条第1項後段）による記述です（公式正答による）。現行の第420条第1項は「当事者は、債務の不履行について損害賠償の額を予定することができる」とだけ定めています。","r":[["民法","420"]]},"2":{"t":true,"w":"出題時の民法（旧第413条）による記述です（公式正答による）。現行の第413条も、受領を拒んだ場合の効果を定めています。","r":[["民法","413"]]},"3":{"t":false,"p":"詐害行為取消権は、「裁判外」ではなく「裁判所に請求」して行使しなければなりません。","w":"民法第424条第1項。","r":[["民法","424"]]},"4":{"t":true,"w":"民法第423条第1項、第423条の3（金銭の支払を自己に求めることができる）。","r":[["民法","423"],["民法","423の3"]]}}},"09-39":{"s":"債権譲渡の対抗要件と債務者の抗弁を問う問題です。公式正答は④（適切でない）です。","law":"④は、改正前の民法第468条第1項（債務者が異議をとどめないで承諾したときは、譲渡人に対抗できた事由を譲受人に対抗できない）による記述です。現行法ではこの規定はなく、第469条第1項により、債務者は対抗要件具備時より前に取得した債権による相殺を譲受人に対抗できます。現行法では④は適切です。","items":{"1":{"t":true,"w":"民法第467条第1項。","r":[["民法","467"]]},"2":{"t":true,"w":"民法第467条第2項：債務者以外の第三者に対抗するには確定日付のある証書による通知又は承諾が必要です。","r":[["民法","467"]]},"3":{"t":true,"w":"民法第467条第2項：確定日付のある証書による通知を得たＤが、確定日付のない通知のＣに優先します。","r":[["民法","467"]]},"4":{"t":false,"now":true,"p":"出題時の民法では、異議をとどめない承諾をしたＢは、相殺をもってＣに対抗「できない」とされていました（旧第468条第1項、公式正答による）。","w":"現行の民法第469条第1項では、対抗要件具備時より前に取得した債権による相殺を譲受人に対抗できるため、記述は適切です。","r":[["民法","469"],["民法","468"]]}}},"09-40":{"s":"相続を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"民法第915条第1項、第921条第2号。","r":[["民法","915"],["民法","921"]]},"2":{"t":true,"w":"民法第919条第1項。","r":[["民法","919"]]},"3":{"t":false,"p":"Ｄが相続欠格で相続人になれなくても、Ｄの子Ｅは代襲して相続人と「なります」。","w":"民法第891条第5号（遺言書の偽造は欠格事由）、第887条第2項（欠格の場合も代襲相続が生じる）。","r":[["民法","891"],["民法","887"]]},"4":{"t":true,"w":"公式正答では適切です。遺産分割協議で債務を承継する人を決めても、債権者は各相続人に法定相続分に応じて請求できるとする考え方です（判例の考え方による）。相続分の指定がある場合については、民法第902条の2が同じ趣旨を定めています。","r":[["民法","902の2"]]}}},"09-41":{"s":"破産法を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"破産法第36条。","r":[["破産法","36"]]},"2":{"t":false,"p":"破産手続開始後に破産財団に対して負担した債務との相殺は、「できません」。","w":"破産法第71条第1項第1号。","r":[["破産法","71"]]},"3":{"t":true,"w":"破産法第2条第9項、第65条第1項。","r":[["破産法","2"],["破産法","65"]]},"4":{"t":true,"w":"破産法第53条第1項。","r":[["破産法","53"]]}}},"09-42":{"s":"犯罪収益移転防止法を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"犯罪収益移転防止法第4条第1項第1号。","r":[["犯収法","4"]]},"2":{"t":true,"w":"犯罪収益移転防止法施行規則第10条第2号イ。","r":[["犯罪による収益の移転防止に関する法律施行規則","10"]]},"3":{"t":false,"p":"確認記録は、取引を行った日から「3営業日以内」ではなく、取引時確認を行った場合に「直ちに」作成しなければなりません。","w":"犯罪収益移転防止法第6条第1項。","r":[["犯収法","6"]]},"4":{"t":true,"w":"犯罪収益移転防止法第5条。","r":[["犯収法","5"]]}}},"09-43":{"s":"消費者契約法を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"事業として又は事業のために契約の当事者となる個人は、事業者に「該当します」。","w":"消費者契約法第2条第2項。","r":[["消費者契約法","2"]]},"2":{"t":true,"w":"消費者契約法第2条第4項。","r":[["消費者契約法","2"]]},"3":{"t":false,"p":"取消権の行使期間は、追認できる時から「3か月間」ではありません。現行法では「1年間」（霊感等による告知の場合は3年間）です。","w":"消費者契約法第7条第1項。","r":[["消費者契約法","7"]]},"4":{"t":false,"p":"無効になるのは条項「そのもの」ではなく、平均的な損害の額を「超える部分」です。","w":"消費者契約法第9条第1項第1号。","r":[["消費者契約法","9"]]}}},"09-44":{"s":"総量規制の例外となる契約（施行規則第10条の23）を問う問題です。該当するのは④です。","items":{"1":{"t":false,"p":"借換えの例外に当たるには、1か月の負担が既存債務の1か月の負担を「上回らない」ことが必要です。","w":"施行規則第10条の23第1項第1号イ。","r":[["貸金業法施行規則","10の23"]]},"2":{"t":false,"p":"不動産の建設・購入・改良の資金の貸付けは、第10条の23（例外）ではなく、第10条の21（総量規制の対象から「除外」される契約）に当たります。","w":"施行規則第10条の21第1項第1号。","r":[["貸金業法施行規則","10の21"],["貸金業法施行規則","10の23"]]},"3":{"t":false,"p":"特定緊急貸付契約は、合算額が「30万円」ではなく「10万円」を超えず、返済期間が「6か月」ではなく「3月」を超えないものです。","w":"施行規則第10条の23第1項第2号の2ロ・ハ。","r":[["貸金業法施行規則","10の23"]]},"4":{"t":true,"w":"施行規則第10条の23第1項第6号。","r":[["貸金業法施行規則","10の23"]]}}},"09-45":{"s":"金融分野ガイドライン（第8条）の安全管理措置を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"金融分野ガイドライン第8条第2項・第8項（組織的安全管理措置）。","r":[["個人情報保護法","23"]]},"2":{"t":false,"p":"「個人データの安全管理に係る取扱規程に従った運用」は、技術的安全管理措置ではなく「組織的安全管理措置」に当たります。","w":"金融分野ガイドライン第8条第8項。利用者の識別及び認証、管理区分の設定及びアクセス制御は技術的安全管理措置です。","r":[["個人情報保護法","23"]]},"3":{"t":true,"w":"金融分野ガイドライン第8条第3項・第8項（人的安全管理措置）。","r":[["個人情報保護法","23"]]},"4":{"t":true,"w":"金融分野ガイドライン第8条第1項。","r":[["個人情報保護法","23"]]}}},"09-46":{"s":"景品表示法を問う問題です。適切でないのは④です。","law":"問題文の条番号は出題時のものです。現行法では、景品類の制限・禁止は第4条、不当な表示の禁止は第5条、措置命令は第7条、協定又は規約は第36条です。","items":{"1":{"t":true,"w":"景品表示法第2条第4項。","r":[["景品表示法","2"]]},"2":{"t":true,"w":"現行の景品表示法第7条第2項。","r":[["景品表示法","7"]]},"3":{"t":true,"w":"現行の景品表示法第36条第1項。","r":[["景品表示法","36"]]},"4":{"t":false,"p":"措置命令は、違反行為が既になくなっている場合でも「することができます」。","w":"現行の景品表示法第7条第1項後段。","r":[["景品表示法","7"]]}}},"09-47":{"s":"日本貸金業協会の紛争解決等業務に関する規則を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"紛争解決等業務に関する規則第2条第2号。","r":[]},"2":{"t":true,"w":"紛争解決等業務に関する規則第90条第1項。","r":[]},"3":{"t":false,"p":"法人でない社団又は財団で代表者又は管理者の定めがあるもの（権利能力なき社団等）も、紛争解決手続開始の申立てが「できます」。","w":"紛争解決等業務に関する規則第59条第1項。","r":[]},"4":{"t":true,"w":"紛争解決等業務に関する規則第82条第1項。","r":[]}}},"09-48":{"s":"企業会計原則の一般原則を問う問題です。適切なのは③（一般原則六）です。","items":{"1":{"t":false,"p":"一般原則四は、「財産目録及び出納帳簿」ではなく「財務諸表」によって、利害関係者に必要な会計事実を明瞭に表示し、判断を誤らせないようにするものです（「適切性の原則」ではなく明瞭性の原則）。","w":"企業会計原則 第一 一般原則 四。原則の呼び名は資料に書かれておらず、公式正答によります。","r":[]},"2":{"t":false,"p":"一般原則二は、「多額の取引」ではなく「すべての取引」につき、「正確な財務諸表」ではなく「正確な会計帳簿」を作成するものです（「正確性の原則」ではなく正規の簿記の原則）。","w":"企業会計原則 第一 一般原則 二。","r":[]},"3":{"t":true,"w":"企業会計原則 第一 一般原則 六（保守主義の原則）。","r":[]},"4":{"t":false,"p":"一般原則一は、「健全であると合理的に認められる内容」ではなく、財政状態及び経営成績に関して「真実な報告」を提供するものです（「健全性の原則」ではなく真実性の原則）。","w":"企業会計原則 第一 一般原則 一。","r":[]}}},"09-49":{"s":"源泉徴収票と青色申告決算書を問う問題です。適切なのは④です。所得税法や様式は取り込んだ資料にないため、この問題は公式正答によります。","items":{"1":{"t":false,"p":"「支払金額」は、所得税額と住民税額を「控除した金額」ではありません（公式正答による）。","w":"所得税法や青色申告決算書の様式は取り込んだ資料にないため、この肢は公式正答によります。","r":[]},"2":{"t":false,"p":"「控除対象扶養親族の数」は、「配偶者を含む」親族の数ではありません（公式正答による。源泉徴収票では配偶者は別の欄で扱われます）。","w":"所得税法や青色申告決算書の様式は取り込んだ資料にないため、この肢は公式正答によります。","r":[]},"3":{"t":false,"p":"「所得金額」は、売上原価及び諸経費を「差し引く前」の収入金額ではありません（公式正答による）。","w":"所得税法や青色申告決算書の様式は取り込んだ資料にないため、この肢は公式正答によります。","r":[]},"4":{"t":true,"w":"所得税法や青色申告決算書の様式は取り込んだ資料にないため、この肢は公式正答によります。","r":[]}}},"09-50":{"s":"貸借対照表の区分を問う問題です。適切でないのは①です。会社計算規則は資料にないため公式正答によりますが、企業会計原則で同じ内容を確認できる肢はその旨を書いています。","items":{"1":{"t":false,"p":"固定資産は、有形固定資産、無形固定資産及び「繰延資産」ではなく「投資その他の資産」に区分します。繰延資産は固定資産とは別の区分です。","w":"企業会計原則 貸借対照表原則二・四（一）Ｂ。","r":[]},"2":{"t":true,"w":"企業会計原則 注解（経過勘定項目）：未収収益は貸借対照表の資産の部に計上します。流動資産への区分は公式正答によります。","r":[]},"3":{"t":true,"w":"企業会計原則 注解〔注16〕：前受金など主目的たる営業取引により発生した債務は流動負債に属します。","r":[]},"4":{"t":true,"now":false,"p":"現行の規定では、純資産の部は株主資本、評価・換算差額等、「株式引受権」及び新株予約権に区分します（第19回問50④の公式正答による）。","w":"公式正答では適切とされています（第9回の時点）。","r":[]}},"law":"④について、第19回問50④の公式正答では、純資産の部は「株主資本、評価・換算差額等、株式引受権及び新株予約権」に区分するとされています。現行の会社計算規則では「株式引受権」の区分も加わっているので、④の記述（3区分）は現行の規定どおりではありません（会社計算規則は取り込んでいないため、第19回の公式正答に基づく判断です）。"},"10-01":{"s":"貸金業法の用語の定義を問う問題です。適切なのはｃの1個です。","items":{"a":{"t":false,"p":"事業者がその従業者に対して行う貸付けは、貸金業に「含まれる」のではなく「含まれません」。","w":"貸金業法第2条第1項第4号。","r":[["貸金業法","2"]]},"b":{"t":false,"p":"保証人となろうとする者と保証人も、資金需要者等に「含まれます」。","w":"貸金業法第2条第4項〜第6項：資金需要者等＝顧客等（資金需要者である顧客又は保証人となろうとする者）又は債務者等（債務者又は保証人）。","r":[["貸金業法","2"]]},"c":{"t":true,"w":"貸金業法第2条第11項。","r":[["貸金業法","2"]]},"d":{"t":false,"p":"住宅の改良に必要な資金の貸付けも、住宅資金貸付契約に「含まれます」。","w":"貸金業法第2条第17項。","r":[["貸金業法","2"]]}}},"10-02":{"s":"登録の拒否事由（貸金業法第6条第1項）を問う問題です。拒否されるのは③です。","items":{"1":{"t":false,"p":"拒否事由は「破産手続開始の決定を受けて復権を得ない者」です。復権を得ていれば、5年を経過していなくても該当しません。","w":"貸金業法第6条第1項第2号。","r":[["貸金業法","6"]]},"2":{"t":false,"p":"拒否事由になるのは取消しの日前「30日以内」に役員であった者です。「60日前」に退任した者は該当しません。","w":"貸金業法第6条第1項第3号。","r":[["貸金業法","6"]]},"3":{"t":true,"w":"出資法に違反して罰金の刑に処せられ、執行を終わった日などから5年を経過しない者は拒否事由（第6条第1項第5号）。法人の役員にその者がいれば、その法人も拒否されます（第9号ロ）。","r":[["貸金業法","6"]]},"4":{"t":false,"p":"常務に従事する役員のうちに貸付けの業務に3年以上の経験者が「1人」いれば基準を満たします。全員である必要はありません。","w":"貸金業法第6条第1項第15号（必要な体制の整備）の審査基準として、施行規則第5条の7第1項第2号は「常務に従事する役員のうちに貸付けの業務に三年以上従事した経験を有する者があること」としています。","r":[["貸金業法","6"],["貸金業法施行規則","5の7"]]}}},"10-03":{"s":"監督指針のシステムリスク管理態勢を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"外部委託先が複数の場合は、外部委託を「しない体制」ではなく、「より高度なリスク管理が求められることを十分認識した体制」となっているかが着眼点です。","w":"監督指針（システムリスク管理、⑧外部委託管理ハ）。","r":[]},"2":{"t":false,"p":"監査の対象は「全ての外部委託先」ではなく「重要な外部委託先」で、内部監査部門「又は」システム監査人等による監査です。","w":"監督指針（システムリスク管理、⑧外部委託管理ホ）。","r":[]},"3":{"t":true,"w":"監督指針（システムリスク管理、現金自動設備のセキュリティ対策のうち「資金需要者等への対応」）のとおりです。","r":[]},"4":{"t":false,"p":"コンティンジェンシープラン（緊急時対応計画）は、客観的な水準が判断できるものを根拠と「せず」ではなく、根拠と「して」策定します。","w":"監督指針（システムリスク管理、⑨コンティンジェンシープランハ）：例として金融情報システムセンターの手引書が挙げられています。","r":[]}}},"10-04":{"s":"禁止行為（貸金業法第12条の6）を問う問題です。適切なのはａｂです。","items":{"a":{"t":true,"w":"監督指針Ⅱ－２－１０（禁止行為等）（２）①イ。","r":[["貸金業法","12の6"]]},"b":{"t":true,"w":"監督指針Ⅱ－２－１０（禁止行為等）（２）②チ。","r":[["貸金業法","12の6"]]},"c":{"t":false,"p":"留意事由として挙げられているのは、貸付けの利率の「引上げ」（引下げは含まない）、返済の方式の変更、賠償額の予定額の引上げなどです。「配偶者の同意」や「取立て行為の第三者への委託」は挙げられていません。","w":"貸金業の業務運営に関する自主規制基本規則第13条。","r":[]},"d":{"t":false,"p":"断定的判断の提供（第12条の6第2号）は行政処分の対象ですが、刑事罰の対象では「ありません」。","w":"罰則（第48条第1項第1号の2）の対象は、第12条の6のうち第1号の「虚偽のことを告げた」行為に限られます。登録取消し・業務停止は第24条の6の4第1項。","r":[["貸金業法","12の6"],["貸金業法","48"],["貸金業法","24の6の4"]]}}},"10-05":{"s":"返済能力の調査を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"借回りが推察されるときは、貸付けを「一切行わず、返済を求める」のではなく、「より慎重な貸付審査を行うなど、過剰貸付けの防止に努めているか」が着眼点です。","w":"監督指針Ⅱ－２－１３－２（貸付審査）。","r":[]},"2":{"t":false,"p":"信用情報機関等による借入れ状況の確認は「事前又は事後」に「しなければならない」のではなく、「事前に」確認することに「努めなければならない」とされています。また、返済能力の確認で提出を受けるのは「代表者の資産の一覧表」ではなく、「決算書、資金繰り表又は事業計画書等」です。","w":"貸金業の業務運営に関する自主規制基本規則第32条第1項・第2項。","r":[]},"3":{"t":false,"p":"個人である保証人となろうとする者の返済能力の調査では、指定信用情報機関の信用情報を使用する必要が「あります」。","w":"貸金業法第13条第2項：「個人である顧客等」との貸付けの契約が対象で、顧客等には保証人となろうとする者が含まれます（第2条第4項）。","r":[["貸金業法","13"],["貸金業法","2"]]},"4":{"t":true,"w":"貸金業法第13条第2項：極度方式貸付けに係る契約は、信用情報の使用義務の対象から除かれています。","r":[["貸金業法","13"]]}}},"10-06":{"s":"基準額超過極度方式基本契約に係る調査（貸金業法第13条の3）を問う問題です。公式正答はｂｄです。","law":"ｄについて、現行の施行規則第10条の24第1項第1号では、特定緊急貸付契約である極度方式基本契約は「5万円」「10万円」の基準がいずれも零とされています。現行法では、所定の期間内に貸付けがあり、期末に残高があれば調査が必要になります（出題時の条文は取り込んだ資料にないため確認できません）。","items":{"a":{"t":false,"p":"3か月以内の期間の末日の残高が10万円「以下」なら、調査を行う必要は「ありません」。","w":"貸金業法第13条の3第2項ただし書、施行規則第10条の25第3項第1号。","r":[["貸金業法","13の3"],["貸金業法施行規則","10の25"]]},"b":{"t":true,"w":"施行規則第10条の24第1項第1号：所定の期間内の貸付けの合計額が5万円を「超え」、かつ期末の残高が10万円を超えるときに調査が必要です。5万円ちょうどは超えていないので不要です。","r":[["貸金業法","13の3"],["貸金業法施行規則","10の24"]]},"c":{"t":false,"p":"信用情報の提供の依頼の期限は、所定の期間の末日から「2週間」ではなく「3週間」を経過する日までです。","w":"施行規則第10条の24第2項。","r":[["貸金業法施行規則","10の24"]]},"d":{"t":true,"now":false,"p":"現行法では、特定緊急貸付契約でも調査が「不要」とは限りません。基準額が零とされているため、所定の期間内に貸付けがあり期末に残高があれば調査が必要です。","w":"公式正答では適切です。特定緊急貸付契約の要件は施行規則第10条の23第1項第2号の2。","r":[["貸金業法施行規則","10の24"],["貸金業法施行規則","10の23"]]}}},"10-07":{"s":"貸付条件の広告等（貸金業法第15条）を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"施行規則第12条第1項第3号。","r":[["貸金業法","15"],["貸金業法施行規則","12"]]},"2":{"t":false,"p":"「期限の利益の喪失の定め」は、広告で表示しなければならない事項に「含まれません」。","w":"広告の表示事項は、商号・登録番号、貸付けの利率（第15条第1項）のほか、返済の方式・返済期間・返済回数、賠償額の予定の割合、担保に関する事項などです（施行規則第12条第1項第1号、第11条第3項第1号）。","r":[["貸金業法","15"],["貸金業法施行規則","12"]]},"3":{"t":false,"p":"賠償額の予定の割合は、年率を百分率で少なくとも小数点以下「二位」ではなく「一位」まで表示します。","w":"施行規則第12条第1項第1号ロ、第11条第3項第1号イ。","r":[["貸金業法施行規則","12"],["貸金業法施行規則","11"]]},"4":{"t":false,"p":"貸付条件の広告には、貸金業法「のみ」ではなく、景品表示法などの法令も適用されます。","w":"施行規則第12条第6項：景品表示法、屋外広告物法に基づく条例その他の法令に違反する広告をしてはならない。","r":[["貸金業法施行規則","12"]]}}},"10-08":{"s":"契約締結時の書面の再交付（貸金業法第17条第1項後段）を問う問題です。相手方の利益となる変更でも再交付が必要なのは②です。","items":{"1":{"t":false,"p":"賠償額の予定（第17条第1項第7号）は、相手方の利益となる変更なら再交付は「不要」です。","w":"施行規則第13条第2項第1号イ。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"2":{"t":true,"w":"施行規則第13条第2項第1号ロ：返済の方法及び返済を受ける場所（第1項第1号ト）は、利益となる変更かどうかを問わず再交付が必要です。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"3":{"t":false,"p":"利息の計算の方法は、相手方の利益となる変更なら再交付は「不要」です。","w":"施行規則第13条第2項第1号イ（第1項第1号ヘ）。","r":[["貸金業法施行規則","13"]]},"4":{"t":false,"p":"債務者が負担すべき元本及び利息以外の金銭に関する事項は、相手方の利益となる変更なら再交付は「不要」です。","w":"施行規則第13条第2項第1号イ（第1項第1号ニ）。","r":[["貸金業法施行規則","13"]]}}},"10-09":{"s":"貸金業者が保存すべき帳簿・記録の保存期間を問う問題です。適切なのはａｂの2個です。","items":{"a":{"t":true,"w":"施行規則第17条第1項。","r":[["貸金業法","19"],["貸金業法施行規則","17"]]},"b":{"t":true,"w":"施行規則第10条の18第2項第1号。","r":[["貸金業法","13"],["貸金業法施行規則","10の18"]]},"c":{"t":false,"p":"基準額超過極度方式基本契約に係る調査の記録の保存期間は、作成後「5年間」ではなく「3年間」です。","w":"施行規則第10条の27第2項。","r":[["貸金業法","13の3"],["貸金業法施行規則","10の27"]]},"d":{"t":false,"p":"書面の保存期間は、契約締結日から「5年間」ではなく、契約に定められた最終の返済期日（債権が消滅したときは消滅した日）までです。","w":"施行規則第10条の21第2項。","r":[["貸金業法施行規則","10の21"]]}}},"10-10":{"s":"取立て行為の規制を問う問題です。適切なのはａｂです。","items":{"a":{"t":true,"w":"貸金業法第21条第3項、施行規則第19条第6項。","r":[["貸金業法","21"],["貸金業法施行規則","19"]]},"b":{"t":true,"w":"監督指針Ⅱ－２－１９（取立行為規制）（１）②。","r":[["貸金業法","21"]]},"c":{"t":false,"p":"「債務者等と連絡をとるための合理的方法が他にない場合」も、「正当な理由」に該当「しない」のではなく、該当する「可能性が高い」とされています。","w":"監督指針Ⅱ－２－１９（２）②イ。","r":[["貸金業法","21"]]},"d":{"t":false,"p":"証明書の提示で足りるのは、貸金業者の商号や「従業者の氏名」を明らかにするよう請求された場合です。「弁済受領権限」や「契約の内容」を求められたときは、書面の交付又は送付が必要です。","w":"施行規則第19条第5項・第6項ただし書。","r":[["貸金業法","21"],["貸金業法施行規則","19"],["貸金業法","12の4"]]}}},"10-11":{"s":"債権譲渡等の規制（貸金業法第24条）を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"譲受人Ｃは、譲渡人Ａとの約定にかかわらず、自ら契約の内容を明らかにする書面をＢに交付する必要が「あります」。","w":"貸金業法第24条第2項：第17条などの規定は、債権の譲受人について準用されます（公式正答による）。","r":[["貸金業法","24"],["貸金業法","17"]]},"2":{"t":true,"w":"貸金業法第24条第1項。","r":[["貸金業法","24"]]},"3":{"t":false,"p":"Ａは、債権を譲渡した後も貸金業を営むなら、帳簿を保存する必要が「あります」。","w":"貸金業法第19条、施行規則第17条第1項（契約ごとの保存義務）。帳簿の記載事項には、債権を他人に譲渡したときはその者の商号等が含まれます（施行規則第16条第1項第6号）。","r":[["貸金業法","19"],["貸金業法施行規則","17"],["貸金業法施行規則","16"]]},"4":{"t":false,"p":"届出の期限は、「30日以内」ではなく、その日から「2週間以内」です。","w":"貸金業法第24条の6の2第4号、施行規則第26条の25第1項第3号・第2項。","r":[["貸金業法","24の6の2"],["貸金業法施行規則","26の25"]]}}},"10-12":{"s":"監督指針Ⅱ－２－８（不祥事件に対する監督上の対応）を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"資金需要者等から告訴・告発された行為も、検挙されていなくても不祥事件に「該当します」。","w":"監督指針Ⅱ－２－８：「資金需要者等から告訴、告発され又は検挙された行為」。","r":[]},"2":{"t":false,"p":"第一報があったときに確認するのは、内部管理部門・経営陣への報告、警察等への通報、独立した部署での調査・解明の実施です。「直ちに立入検査を実施する」とはされていません。","w":"監督指針Ⅱ－２－８（１）①。","r":[]},"3":{"t":true,"w":"監督指針Ⅱ－２－８（１）②イ〜ヘ。","r":[]},"4":{"t":false,"p":"監督当局は、深度あるヒアリングや必要に応じた報告書の徴収により、「監督当局の主導」ではなく「貸金業者の自主的な業務改善状況」を把握するとされています。","w":"監督指針Ⅱ－２－８（２）：重大な問題があれば業務改善命令、重大・悪質な法令違反があれば業務停止命令等を検討します。","r":[]}}},"10-13":{"s":"指定信用情報機関への個人信用情報の提供と同意の取得を問う問題です。適切なのはａｄの2個です。","items":{"a":{"t":true,"w":"貸金業法第41条の36第1項。","r":[["貸金業法","41の36"]]},"b":{"t":false,"p":"加入前極度方式貸付契約を締結しようとする場合は、あらかじめ同意を得る必要は「ありません」。","w":"貸金業法第41条の36第2項ただし書。","r":[["貸金業法","41の36"]]},"c":{"t":false,"p":"個人信用情報の提供が必要なのは極度方式「基本契約」ではありません。個人信用情報の定義から極度方式基本契約は除かれており、提供するのは個々の貸付けに係る契約（極度方式貸付けなど）の情報です。","w":"貸金業法第2条第14項、第41条の35第2項。","r":[["貸金業法","2"],["貸金業法","41の35"]]},"d":{"t":true,"w":"施行規則第30条の16第1項。","r":[["貸金業法","41の36"],["貸金業法施行規則","30の16"]]}}},"10-14":{"s":"利息制限法の元本額の特則（第5条）を問う問題です。適切なのは④です。重ねて貸し付けるときは「既存の残高＋新しい元本」、同時に貸し付けるときは「元本の合計額」で上限金利を判断します。","items":{"1":{"t":false,"p":"年1割8分を超える部分が無効になるのは「第二契約だけ」です。第一契約は元本5万円（10万円未満）なので年2割まで有効で、無効にはなりません。","w":"利息制限法第5条第1号：第二契約は、残高5万円＋5万円＝10万円を元本とみなし、上限は年1割8分（第1条第2号）。第一契約の上限は変わりません。","r":[["利息制限法","5"],["利息制限法","1"]]},"2":{"t":false,"p":"第一契約を完済した後なので重ねての貸付けには当たらず、第二契約（元本5万円）の上限は年2割です。年2割の約定は無効に「なりません」。","w":"利息制限法第1条第1号、第5条第1号。","r":[["利息制限法","1"],["利息制限法","5"]]},"3":{"t":false,"p":"第二契約の元本とみなされる額は残高5万円＋3万円＝8万円（10万円未満）なので、上限は年1割8分ではなく年2割です。無効に「なりません」。","w":"利息制限法第5条第1号、第1条第1号。","r":[["利息制限法","5"],["利息制限法","1"]]},"4":{"t":true,"w":"利息制限法第5条第1号・第2号：残高45万円＋同時に貸し付けた5万円と50万円＝100万円を元本とみなすため、第二契約・第三契約とも上限は年1割5分です（第1条第3号）。","r":[["利息制限法","5"],["利息制限法","1"]]}}},"10-15":{"s":"みなし利息（利息制限法第3条・第6条）を問う問題です。ａ〜ｄはすべて利息とみなされるので4個です。","items":{"a":{"t":true,"w":"利息とみなされないのはカードの「再発行」の手数料です（第6条第1項、施行令第1条第1号）。最初の発行手数料は利息とみなされます。","r":[["利息制限法","3"],["利息制限法","6"],["利息制限法施行令","1"]]},"b":{"t":true,"w":"利息とみなされないのは、弁済期に弁済できなかった場合の「再度の」口座振替手続の費用です（施行令第1条第3号）。約定の弁済期の口座振替費用は利息とみなされます。","r":[["利息制限法","6"],["利息制限法施行令","1"]]},"c":{"t":true,"w":"利息とみなされないのは書面の「再発行」の手数料です（施行令第1条第2号）。最初の交付の手数料は利息とみなされます。","r":[["利息制限法","6"],["利息制限法施行令","1"]]},"d":{"t":true,"w":"営業的金銭消費貸借で利息とみなされないのは、公租公課、強制執行や担保権実行としての競売など「公の機関が行う手続」の費用、ATMの利用料（一定額まで）に限られます（第6条第2項）。私的な売却の手数料は利息とみなされます。","r":[["利息制限法","6"]]}}},"10-16":{"s":"変更の届出（貸金業法第8条）を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"業務の種類及び方法（第4条第1項第8号）の変更は、変更の日から2週間以内に届出。","r":[["貸金業法","8"],["貸金業法","4"]]},"2":{"t":false,"p":"広告・勧誘で表示するホームページアドレスなどの連絡先（第4条第1項第7号）は、変更の日から2週間以内ではなく、「あらかじめ」（変更しようとするとき）届け出ます。","w":"貸金業法第8条第1項。営業所の名称・所在地（第5号）も同じです。","r":[["貸金業法","8"],["貸金業法","4"]]},"3":{"t":true,"w":"役員の氏名（第4条第1項第2号）の変更は、2週間以内に届出。","r":[["貸金業法","8"],["貸金業法","4"]]},"4":{"t":true,"w":"政令で定める使用人（第4条第1項第2号）の変更は、2週間以内に届出。","r":[["貸金業法","8"],["貸金業法","4"]]}}},"10-17":{"s":"廃業等の届出（貸金業法第10条）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"合併で消滅したときに届け出るのは、「存続する法人を代表する役員」ではなく、「消滅した法人を代表する役員であった者」です。","w":"貸金業法第10条第1項第2号。","r":[["貸金業法","10"]]},"2":{"t":true,"w":"貸金業法第10条第1項第4号。","r":[["貸金業法","10"]]},"3":{"t":true,"w":"貸金業法第10条第1項第1号：死亡の場合は、相続人が死亡の事実を知った日から30日以内。","r":[["貸金業法","10"]]},"4":{"t":true,"w":"貸金業法第10条第3項。","r":[["貸金業法","10"]]}}},"10-18":{"s":"監督指針Ⅱ－２－２（顧客等に関する情報管理態勢）を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"監督指針Ⅱ－２－２の着眼点のとおりです。","r":[]},"2":{"t":false,"p":"漏えい等が発生したときの報告先は、「指定信用情報機関及び消費者委員会」ではなく「当局」です。","w":"監督指針Ⅱ－２－２：対象となった資金需要者等への説明、当局への報告及び必要に応じた公表が迅速かつ適切に行われる体制。","r":[]},"3":{"t":true,"w":"監督指針Ⅱ－２－２（個人情報保護に関する着眼点、クレジットカード情報等の措置）。","r":[]},"4":{"t":true,"w":"監督指針Ⅱ－２－２の着眼点のとおりです。","r":[]}}},"10-19":{"s":"貸金業務取扱主任者を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"被補助人であることは、主任者登録の拒否事由に「該当しません」。","w":"貸金業法第24条の27第1項の拒否事由に被補助人は挙げられていません（第1号は心身の故障のため職務を適正に執行できない者として内閣府令で定める者）。","r":[["貸金業法","24の27"]]},"2":{"t":true,"w":"貸金業法第24条の27第1項第3号：聴聞の期日・場所の公示の日前60日以内に役員であった者で、取消しの日から5年を経過しないもの。","r":[["貸金業法","24の27"]]},"3":{"t":true,"w":"監督指針Ⅱ－２－９（２）①。","r":[["貸金業法","12の3"]]},"4":{"t":true,"w":"監督指針Ⅱ－２－９（２）③。","r":[["貸金業法","12の3"]]}}},"10-20":{"s":"返済能力の調査と資力を明らかにする書面等を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"資力を明らかにする書面等の提出義務（第13条第3項）は、信用情報の使用義務がある場合（第2項）が前提です。第2項は極度方式貸付けに係る契約を除いています。","r":[["貸金業法","13"]]},"2":{"t":true,"w":"貸金業法第13条第3項：書面等の提出を受けるのは「個人顧客」（資金需要者である個人の顧客）からで、保証人となろうとする者は対象ではありません。","r":[["貸金業法","13"]]},"3":{"t":false,"p":"根拠法令なく行政サービスの一環として地方公共団体が交付する所得・課税証明書は、「所得証明書」に「含まれない」のではなく「含まれます」。","w":"監督指針Ⅱ－２－１３－１（１）②ロ ａ。","r":[["貸金業法施行規則","10の17"]]},"4":{"t":true,"w":"監督指針Ⅱ－２－１３－１（１）のとおりです。","r":[["貸金業法","13の2"]]}}},"10-21":{"s":"極度額を増額する場合の返済能力の調査（貸金業法第13条第5項）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"極度額を下回る額（貸付限度額）を提示している場合は、その額を引き上げることも極度額の増額として扱われ、返済能力の調査が「必要」です。","w":"貸金業法第13条第5項の括弧書：極度額を下回る額を提示しているときは、その下回る額を極度額として扱います。","r":[["貸金業法","13"]]},"2":{"t":true,"w":"返済能力の低下を理由に減額した後の増額は、調査が不要な場合（施行規則第10条の19）に当たりません。","r":[["貸金業法","13"],["貸金業法施行規則","10の19"]]},"3":{"t":true,"w":"施行規則第10条の19：連絡できないことにより一時的に減額していた（返済能力の低下による場合を除く）極度額を、連絡できたことにより減額前の額まで増額する場合は、調査が不要です。","r":[["貸金業法","13"],["貸金業法施行規則","10の19"]]},"4":{"t":true,"w":"貸金業法第13条第5項で準用する第4項：調査に関する記録の作成・保存。","r":[["貸金業法","13"]]}}},"10-22":{"s":"総量規制の例外となる契約（施行規則第10条の23）を問う問題です。該当しないのは③です。","items":{"1":{"t":true,"w":"施行規則第10条の23第1項第6号。","r":[["貸金業法施行規則","10の23"]]},"2":{"t":true,"w":"施行規則第10条の23第1項第4号。","r":[["貸金業法施行規則","10の23"]]},"3":{"t":false,"p":"借換えの例外に当たるには、1か月の負担が既存の債務の1か月の負担を「上回らない」ことが必要です。「上回る」ものは該当しません。","w":"施行規則第10条の23第1項第1号イ・ロ（イとロの両方を満たす必要があります）。","r":[["貸金業法施行規則","10の23"]]},"4":{"t":true,"w":"施行規則第10条の23第1項第5号。","r":[["貸金業法施行規則","10の23"]]}}},"10-23":{"s":"貸付けの契約に係る説明態勢と勧誘を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"監督指針Ⅱ－２－１１－２（契約に係る説明態勢）（１）①。","r":[]},"2":{"t":true,"w":"監督指針Ⅱ－２－１１－２（１）②イｂ。","r":[]},"3":{"t":true,"w":"自主規制基本規則第55条第2号。なお、勧誘を一切拒否する強い意思表示の場合は最低1年間です（第1号）。","r":[]},"4":{"t":false,"p":"障害等により契約の内容が理解困難なことを認識した場合は、「丁寧かつ十分な説明をする」のではなく、貸付けの契約の締結に係る「勧誘を行ってはならない」とされています。","w":"自主規制基本規則第54条第4項。","r":[]}}},"10-24":{"s":"極度方式貸付けの書面（個別貸付契約の書面）で記載を省略できる事項を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"「債務者が負担すべき元本及び利息以外の金銭に関する事項」は、基本契約の書面に記載されていても、個別貸付契約の書面で省略「できません」。","w":"施行規則第13条第1項第1号ニには、極度方式貸付けの場合の省略の定めがありません（ヘ・ト・リ・ヌなどには省略の定めがあります）。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"2":{"t":true,"w":"賠償額の予定（貸金業法第17条第1項第7号）は法律で定める記載事項で、施行規則に省略の定めはありません。","r":[["貸金業法","17"]]},"3":{"t":true,"w":"返済の方式（貸金業法第17条第1項第5号）も、省略の定めはありません。","r":[["貸金業法","17"]]},"4":{"t":true,"w":"施行規則第13条第1項第1号ロ。","r":[["貸金業法施行規則","13"]]}}},"10-25":{"s":"帳簿（貸金業法第19条）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"施行規則第17条第2項。","r":[["貸金業法","19"],["貸金業法施行規則","17"]]},"2":{"t":true,"w":"施行規則第16条第1項第6号。","r":[["貸金業法","19"],["貸金業法施行規則","16"]]},"3":{"t":true,"w":"施行規則第16条第1項第5号。","r":[["貸金業法","19"],["貸金業法施行規則","16"]]},"4":{"t":false,"p":"「交渉の経過の記録」は、勧誘を開始した時以降ではなく、「貸付けの契約の締結以降」の債権に関する交渉の経過の記録です。","w":"監督指針Ⅱ－２－１７（帳簿の備付け等）（注）、施行規則第16条第1項第7号。","r":[["貸金業法施行規則","16"]]}}},"10-26":{"s":"開始等の届出（貸金業法第24条の6の2）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"貸金業法第24条の6の2第3号。","r":[["貸金業法","24の6の2"]]},"2":{"t":true,"w":"施行規則第26条の25第1項第1号（第6条第1項第13号に該当することとなった場合）。","r":[["貸金業法","24の6の2"],["貸金業法施行規則","26の25"]]},"3":{"t":true,"w":"施行規則第26条の25第1項第7号。","r":[["貸金業法施行規則","26の25"]]},"4":{"t":false,"p":"役員について届出が必要なのは、第6条第1項第1号又は第4号〜第7号に該当した場合です。破産手続開始の決定（第2号）は「含まれません」。","w":"施行規則第26条の25第1項第2号。","r":[["貸金業法施行規則","26の25"],["貸金業法","6"]]}}},"10-27":{"s":"保証料と媒介手数料の規制を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"出資法第5条の3第1項。","r":[["出資法","5の3"]]},"2":{"t":true,"w":"出資法第4条第2項。","r":[["出資法","4"]]},"3":{"t":true,"w":"貸金業法第12条の8第9項、施行規則第10条の14第2号：3年を経過した日より後の日を元本確定期日とする根保証契約、又は元本確定期日の定めがない根保証契約は締結できません。","r":[["貸金業法","12の8"],["貸金業法施行規則","10の14"]]},"4":{"t":false,"p":"保証料の確認は、保証契約を「締結したときは遅滞なく」ではなく、「あらかじめ、保証契約を締結するまでに」行います。","w":"貸金業法第12条の8第6項。","r":[["貸金業法","12の8"]]}}},"10-28":{"s":"制限行為能力者を問う問題です。適切なのは①です。","items":{"1":{"t":true,"w":"民法第17条第1項ただし書：補助人の同意を要する旨の審判の対象は、第13条第1項に規定する行為の一部に限られます。","r":[["民法","17"],["民法","13"]]},"2":{"t":false,"p":"被保佐人は、元本の利用だけでなく「領収」にも保佐人の同意が「必要」です。","w":"民法第13条第1項第1号：元本を領収し、又は利用すること。","r":[["民法","13"]]},"3":{"t":false,"p":"単に権利を得る法律行為も、義務を免れる法律行為と同じく、法定代理人の同意は「不要」です。","w":"民法第5条第1項ただし書。","r":[["民法","5"]]},"4":{"t":false,"p":"行為能力者となった本人への催告は、期間が「2週間以上」ではなく「1箇月以上」で、確答がないときは「取り消した」ではなく「追認した」ものとみなされます。","w":"民法第20条第1項。","r":[["民法","20"]]}}},"10-29":{"s":"無効と取消しを問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"無効な行為を無効と知って追認したときは、初めから有効になるのではなく、「新たな行為をしたもの」とみなされます。","w":"民法第119条。","r":[["民法","119"]]},"2":{"t":false,"p":"追認は、取消しの原因となっていた状況が「消滅した後」（かつ取消権を有することを知った後）にしなければ、効力を生じ「ません」。","w":"民法第124条第1項。出題時の条文には「取消権を有することを知った後」の文言はありませんでしたが、結論は同じです。","r":[["民法","124"]]},"3":{"t":false,"p":"取り消された行為は、将来に向かってではなく、「初めから」無効であったものとみなされます。","w":"民法第121条。","r":[["民法","121"]]},"4":{"t":true,"w":"民法第120条第2項（現行法では錯誤も加わっています）。","r":[["民法","120"]]}}},"10-30":{"s":"質権と抵当権を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"質権は、動産だけでなく、不動産や債権などの財産権も目的とすることが「できます」。","w":"民法第362条第1項（権利質）。不動産質は第356条以下に定められています。","r":[["民法","362"],["民法","343"]]},"2":{"t":false,"p":"質権者は、質権設定者に自己に代わって質物を占有させることは「できません」。","w":"民法第345条。","r":[["民法","345"]]},"3":{"t":true,"w":"民法第376条第1項（抵当権の処分）。","r":[["民法","376"]]},"4":{"t":false,"p":"抵当権を行使できる利息などは、満期となった最後の「3年分」ではなく「2年分」です。","w":"民法第375条第1項。","r":[["民法","375"]]}}},"10-31":{"s":"債務不履行の責任を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"不確定期限の場合、遅滞の責任は「期限の到来後相当の期間が経過した時」からではありません。現行法では、期限の到来後に履行の請求を受けた時又は期限の到来を知った時のいずれか早い時からです。","w":"民法第412条第2項。出題時の民法では「期限の到来したことを知った時」からとされていました（公式正答による）。どちらでも記述は適切でありません。","r":[["民法","412"]]},"2":{"t":true,"w":"民法第416条。現行の第2項は「当事者がその事情を予見すべきであったとき」と改められています（出題時は「予見し、又は予見することができたとき」）。","r":[["民法","416"]]},"3":{"t":false,"p":"金銭債務の不履行では、債務者は不可抗力を抗弁と「することができません」。","w":"民法第419条第3項。","r":[["民法","419"]]},"4":{"t":false,"p":"債務者は、債権者の承諾を得たときに限らず、「当然に」債権者に代位します。","w":"民法第422条。","r":[["民法","422"]]}}},"10-32":{"s":"連帯債務を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"債権者は、すべての連帯債務者に「同時に」全部の履行を請求しなければならないわけではありません。1人に対し、又は同時に若しくは順次にすべての連帯債務者に対し、全部又は一部の履行を請求できます。","w":"民法第436条。","r":[["民法","436"]]},"2":{"t":false,"p":"1人について無効・取消しの原因があっても、他の連帯債務者の債務は効力を「妨げられません」。","w":"民法第437条。","r":[["民法","437"]]},"3":{"t":false,"p":"1人と債権者の間の混同は、他の連帯債務者に対しても効力を「生じます」（その連帯債務者は弁済をしたものとみなされます）。","w":"民法第440条。","r":[["民法","440"]]},"4":{"t":true,"w":"民法第439条第1項。","r":[["民法","439"]]}}},"10-33":{"s":"相殺を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"相殺できるのは「同種の目的」を有する債務の間だけです。金銭債権と特定物の引渡債務は同種ではないので、相殺「できません」。","w":"民法第505条第1項。","r":[["民法","505"]]},"2":{"t":true,"w":"民法第506条第1項。","r":[["民法","506"]]},"3":{"t":false,"p":"時効で消滅した債権でも、消滅前に相殺に適するようになっていたなら、それを自働債権として相殺「できます」。","w":"民法第508条。","r":[["民法","508"]]},"4":{"t":false,"p":"差押禁止債権について相殺を対抗できないのは、その債権の「債務者」の側です（差押禁止債権を受働債権とする相殺の禁止）。記述は債権者と債務者が逆です。","w":"民法第510条。","r":[["民法","510"]]}}},"10-34":{"s":"委任を問う問題です。適切なのは②です。","items":{"1":{"t":false,"p":"記述は「請負」の説明です。委任は、当事者の一方が「法律行為をすること」を相手方に委託し、相手方がこれを「承諾する」ことによって効力を生じます。","w":"民法第643条。","r":[["民法","643"]]},"2":{"t":true,"w":"民法第645条。","r":[["民法","645"]]},"3":{"t":false,"p":"受任者は、無償でも「自己のためにするのと同等の注意」ではなく「善良な管理者の注意」の義務を負います。","w":"民法第644条：有償・無償の区別はありません。","r":[["民法","644"]]},"4":{"t":false,"p":"受任者は、「特約がなければ」報酬を請求できません。","w":"民法第648条第1項。","r":[["民法","648"]]}}},"10-35":{"s":"不当利得と不法行為を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"受益者の返還義務は、他人に損失を及ぼした「か否かを問わず」ではなく、「そのために他人に損失を及ぼした」場合に生じます。また、悪意の受益者は、なお損害があるときは賠償の責任を「負います」。","w":"民法第703条、第704条。","r":[["民法","703"],["民法","704"]]},"2":{"t":false,"p":"返還を請求できないのは、債務の存在しないことを「知っていた」ときです。「知らなかった」ときは返還を請求「できます」。","w":"民法第705条。","r":[["民法","705"]]},"3":{"t":false,"p":"共同不法行為者は、加害の割合で按分した額を独立して負うのではなく、「各自が連帯して」損害の全部を賠償する責任を負います。","w":"民法第719条第1項。","r":[["民法","719"]]},"4":{"t":true,"w":"民法第715条第1項（使用者責任）。","r":[["民法","715"]]}}},"10-36":{"s":"手形法と電子記録債権法を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"所持人Ｃが合意と異なる補充を知って（悪意で）取得したときは、Ａはその違反をＣに対抗「できます」。","w":"手形法第10条ただし書（約束手形には第77条第2項で準用）。","r":[["手形法","10"],["手形法","77"]]},"2":{"t":false,"p":"詐欺による取消しは、善意かつ無過失の第三者Ｃに対抗「できません」。","w":"民法第96条第3項。手形法第17条（人的関係に基づく抗弁の制限。約束手形には第77条第1項で準用）も参照。詐欺の抗弁を人的抗弁として扱う点は公式正答によります。","r":[["民法","96"],["手形法","17"]]},"3":{"t":true,"w":"電子記録債権法第5条第1項：電子記録の請求は、電子記録権利者と電子記録義務者の双方がしなければなりません。","r":[["電子記録債権法","5"]]},"4":{"t":false,"p":"電子記録債権の内容の意思表示による変更は、変更記録をしなければ、第三者に対抗できないのではなく、「効力を生じません」。","w":"電子記録債権法第26条。","r":[["電子記録債権法","26"]]}}},"10-37":{"s":"代理（顕名・表見代理・無権代理）を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"民法第100条：相手方が本人のためにすることを知らず、知ることもできなかったときは、代理人自身のためにしたものとみなされます。","r":[["民法","100"]]},"2":{"t":true,"w":"民法第109条第1項ただし書：第三者が代理権を与えられていないことを知り、又は過失によって知らなかったときは、本人は責任を負いません。","r":[["民法","109"]]},"3":{"t":false,"p":"履行か損害賠償かを選ぶのは、無権代理人Ａではなく「相手方Ｃ」です。","w":"民法第117条第1項：相手方の選択に従い、履行又は損害賠償の責任を負います。","r":[["民法","117"]]},"4":{"t":true,"w":"民法第112条第1項：代理権の消滅を過失によって知らなかった第三者に対しては、本人は責任を負いません（代理権の消滅を対抗できます）。","r":[["民法","112"]]}}},"10-38":{"s":"時効を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"民法第144条。","r":[["民法","144"]]},"2":{"t":false,"p":"当事者が時効を「援用しなければ」、裁判所は時効によって裁判をすることが「できません」。","w":"民法第145条。","r":[["民法","145"]]},"3":{"t":true,"w":"民法第146条。","r":[["民法","146"]]},"4":{"t":true,"w":"民法第162条第2項（善意無過失の場合は10年）。","r":[["民法","162"]]}}},"10-39":{"s":"契約の解除を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"民法第540条第1項・第2項。","r":[["民法","540"]]},"2":{"t":true,"w":"民法第541条（催告による解除）。","r":[["民法","541"]]},"3":{"t":false,"p":"履行の一部が不能になったときも、契約の解除をすることが「できます」。","w":"出題時の民法（旧第543条）では、履行の全部又は一部が債務者の責めに帰すべき事由で不能となったときに解除できるとされていました（公式正答による）。現行の第542条では、一部不能のときは契約の一部の解除ができ（第2項第1号）、残りだけでは契約の目的を達せないときは全部の解除ができます（第1項第3号）。","r":[["民法","542"]]},"4":{"t":true,"w":"民法第545条第1項。","r":[["民法","545"]]}}},"10-40":{"s":"相続を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"民法第900条第3号。","r":[["民法","900"]]},"2":{"t":true,"w":"民法第920条。","r":[["民法","920"]]},"3":{"t":true,"w":"民法第923条。","r":[["民法","923"]]},"4":{"t":false,"p":"相続を放棄した者に求められる注意は、「善良な管理者の注意」ではなく「自己の財産におけるのと同一の注意」です。","w":"民法第940条第1項。現行の条文では、放棄の時に相続財産を現に占有している場合に、相続人などに引き渡すまでの間、保存しなければならないとされています。","r":[["民法","940"]]}}},"10-41":{"s":"倒産処理手続の申立てを問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"「事業の継続に著しい支障を来すことなく弁済期にある債務を弁済できないとき」に申立てができるのは「債務者」だけです。債権者が申し立てられるのは、破産手続開始の原因となる事実の生ずるおそれがあるときです。","w":"民事再生法第21条第1項・第2項。","r":[["民事再生法","21"]]},"2":{"t":true,"w":"破産法第18条第2項。","r":[["破産法","18"]]},"3":{"t":true,"w":"会社更生法第17条第1項。","r":[["会社更生法","17"]]},"4":{"t":true,"w":"会社法第511条第2項。","r":[["会社法","511"]]}}},"10-42":{"s":"犯罪収益移転防止法を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"犯罪収益移転防止法施行規則第10条第2号ハ：設立の登記に係る登記事項証明書は、確認する日前6月以内に作成されたものに限ります。","r":[["犯罪による収益の移転防止に関する法律施行規則","10"]]},"2":{"t":true,"w":"犯罪収益移転防止法第6条第1項・第2項。","r":[["犯収法","6"]]},"3":{"t":true,"w":"犯罪収益移転防止法第8条第4項。","r":[["犯収法","8"]]},"4":{"t":false,"p":"少額の取引などの政令で定める取引は、取引記録の作成義務から「除かれます」。また、保存期間は「3年間」ではなく「7年間」です。","w":"犯罪収益移転防止法第7条第1項・第3項。","r":[["犯収法","7"]]}}},"10-43":{"s":"個人情報の定義（個人情報データベース等・個人データ・個人情報取扱事業者・保有個人データ）を問う問題です。適切なのは①です。","law":"④について、出題時の個人情報保護法では「6か月以内に消去することとなるもの」が保有個人データから除かれていましたが、2022年施行の改正でこの除外はなくなりました。どちらでも「1年以内」ではないため、記述は適切でありません。","items":{"1":{"t":true,"w":"個人情報保護法第16条第1項。","r":[["個人情報保護法","16"]]},"2":{"t":false,"p":"個人情報データベース等から記録媒体に保存されたものや紙面に出力されたものも、個人データに「含まれます」。","w":"通則ガイドライン（個人データ）の「個人データに該当する事例」。個人情報保護法第16条第3項。","r":[["個人情報保護法","16"]]},"3":{"t":false,"p":"「事業」は営利を目的とするものに限られず、「営利・非営利の別は問いません」。","w":"通則ガイドライン（個人情報取扱事業者）。個人情報保護法第16条第2項。","r":[["個人情報保護法","16"]]},"4":{"t":false,"p":"「1年以内に消去することとなるもの」を除く定めはありません。","w":"現行の個人情報保護法第16条第4項：除かれるのは、存否が明らかになることにより公益その他の利益が害されるものとして政令で定めるものです。","r":[["個人情報保護法","16"]]}}},"10-44":{"s":"消費者契約法を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"消費者契約は、政令で指定された商品等に関する契約に限られず、「消費者と事業者との間で締結される契約」すべてです。","w":"消費者契約法第2条第3項。","r":[["消費者契約法","2"]]},"2":{"t":false,"p":"重要事項の不実告知で誤認して締結した契約は、「無効」ではなく「取り消すことができる」ものです。","w":"消費者契約法第4条第1項第1号。","r":[["消費者契約法","4"]]},"3":{"t":false,"p":"事業者の不法行為責任の全部を免除する条項は、消費者が契約を「取り消せる」のではなく、その条項が「無効」になります。","w":"消費者契約法第8条第1項第3号。","r":[["消費者契約法","8"]]},"4":{"t":true,"w":"消費者契約法第9条第1項第1号。","r":[["消費者契約法","9"]]}}},"10-45":{"s":"景品表示法を問う問題です。適切なのは②です。","law":"問題文の条番号は出題時のものです。現行法では、不当な表示の禁止は第5条、措置命令は第7条、報告徴収・立入検査は第25条、指定に関する公聴会は第3条・第6条です。","items":{"1":{"t":false,"p":"措置命令ができるのは違反する行為が「あるとき」です。「違反すると疑われる行為があるとき」は含まれません。","w":"現行の景品表示法第7条第1項。","r":[["景品表示法","7"]]},"2":{"t":true,"w":"現行の景品表示法第3条第1項（表示・景品類の指定）、第6条第1項（景品類の制限・禁止、不当表示の指定）：公聴会を開き、関係事業者及び一般の意見を求めるとともに、消費者委員会の意見を聴かなければなりません。","r":[["景品表示法","3"],["景品表示法","6"]]},"3":{"t":false,"p":"合理的な根拠を示す資料の提出を求められるのは、「有利誤認表示」ではなく「優良誤認表示」（商品・役務の内容についての表示）の判断のためです。","w":"現行の景品表示法第7条第2項（第5条第1号）。","r":[["景品表示法","7"],["景品表示法","5"]]},"4":{"t":false,"p":"内閣総理大臣は、報告をさせるだけでなく、事務所などに「立ち入り、帳簿書類等を検査することもできます」。","w":"現行の景品表示法第25条第1項。","r":[["景品表示法","25"]]}}},"10-46":{"s":"個人過剰貸付契約から除かれる契約（施行規則第10条の21）を問う問題です。該当しないのは③です。","items":{"1":{"t":true,"w":"施行規則第10条の21第1項第8号（第1条の2の3第5号の貸借の媒介）。","r":[["貸金業法施行規則","10の21"]]},"2":{"t":true,"w":"施行規則第10条の21第1項第7号。","r":[["貸金業法施行規則","10の21"]]},"3":{"t":false,"p":"不動産担保貸付けの例外では、個人顧客や担保を提供する者の「居宅」などは担保の対象から「除かれています」。居宅を担保とする貸付けは該当しません。","w":"施行規則第10条の21第1項第6号。","r":[["貸金業法施行規則","10の21"]]},"4":{"t":true,"w":"施行規則第10条の21第1項第4号イ。","r":[["貸金業法施行規則","10の21"]]}}},"10-47":{"s":"日本貸金業協会の紛争解決等業務に関する規則を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"紛争解決等業務に関する規則第2条第2号。","r":[]},"2":{"t":true,"w":"紛争解決等業務に関する規則第59条第1項。","r":[]},"3":{"t":false,"p":"特別調停案は、和解案の受諾の勧告によっては和解が成立する見込みが「ない」場合に作成できるものです。また、受諾しなければならないのは「当事者双方」ではなく「協会員等である当事者」で、それにも例外があります。","w":"紛争解決等業務に関する規則第90条第1項・第2項。","r":[]},"4":{"t":true,"w":"紛争解決等業務に関する規則第92条第2項。","r":[]}}},"10-48":{"s":"給与所得の源泉徴収票を問う問題です。適切なのは②です。所得税法などは取り込んだ資料にないため、この問題は公式正答によります。","items":{"1":{"t":false,"p":"「源泉徴収税額」の欄は、所得税額と住民税額の「合計額」ではありません（公式正答による）。","w":"所得税法は取り込んだ資料にないため、この肢は公式正答によります。","r":[]},"2":{"t":true,"w":"所得税法は取り込んだ資料にないため、この肢は公式正答によります。","r":[]},"3":{"t":false,"p":"控除対象配偶者の説明（範囲や所得の要件）が「適切でない」とされています（公式正答による）。","w":"所得税法は取り込んだ資料にないため、この肢は公式正答によります。具体的な所得の金額は資料で確認できないため示しません。","r":[]},"4":{"t":false,"p":"「社会保険料等の金額」の欄に記載されるのは、「事業主（会社）が負担した社会保険料」ではありません（公式正答による）。","w":"所得税法は取り込んだ資料にないため、この肢は公式正答によります。","r":[]}}},"10-49":{"s":"企業会計原則の一般原則を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"一般原則三は、「資本取引と負債取引」ではなく「資本取引と損益取引」を明瞭に区別し、特に「資本金と借入金」ではなく「資本剰余金と利益剰余金」を混同してはならないとするものです（資本取引・損益取引区分の原則）。","w":"企業会計原則 第一 一般原則 三。原則の呼び名は資料に書かれておらず、公式正答によります。","r":[]},"2":{"t":true,"w":"企業会計原則 第一 一般原則 五（継続性の原則）。","r":[]},"3":{"t":true,"w":"企業会計原則 第一 一般原則 二（正規の簿記の原則）。","r":[]},"4":{"t":true,"w":"企業会計原則 第一 一般原則 一（真実性の原則）。","r":[]}}},"10-50":{"s":"貸借対照表の区分を問う問題です。適切でないのは③です。会社計算規則は資料にないため公式正答によりますが、企業会計原則で同じ内容を確認できる肢はその旨を書いています。","items":{"1":{"t":true,"w":"会社計算規則は取り込んだ資料にないため、この肢は公式正答によります。","r":[]},"2":{"t":true,"w":"企業会計原則 貸借対照表原則：固定資産は、有形固定資産、無形固定資産及び投資その他の資産に区分しなければならない。","r":[]},"3":{"t":false,"p":"前受収益は「流動資産」ではなく「流動負債」に属します。","w":"企業会計原則 注解（経過勘定項目）：前受収益は、当期の損益計算から除去するとともに貸借対照表の負債の部に計上しなければならない。","r":[]},"4":{"t":true,"w":"企業会計原則 注解（経過勘定項目）：未払費用は、当期の損益計算に計上するとともに貸借対照表の負債の部に計上しなければならない。流動負債への区分は公式正答によります。","r":[]}}},"11-01":{"s":"貸金業法第2条の用語の定義です。適切なのはｂだけです（1個）。","items":{"a":{"t":false,"p":"物品の売買・運送・保管・売買の媒介を業とする者がその取引に付随して行う貸付けは、貸金業から「除かれます」。","w":"第2条第1項第3号。","r":[["貸金業法","2"]]},"b":{"t":true,"w":"第2条第12項。","r":[["貸金業法","2"]]},"c":{"t":false,"p":"記述は「信用情報」ではなく「個人信用情報」に近い定義です。信用情報は「顧客又は債務者の借入金の返済能力に関する情報」です。","w":"第2条第13項（信用情報）・第14項（個人信用情報）。","r":[["貸金業法","2"]]},"d":{"t":false,"p":"手続実施基本契約は、三者間ではなく「指定紛争解決機関と貸金業者との間」で締結される契約です。","w":"第2条第23項。","r":[["貸金業法","2"]]}}},"11-02":{"s":"変更の届出（第8条）の要否と期限です。正しいのは③です。","items":{"1":{"t":false,"p":"広告等に表示する電子メールアドレスの変更も、届出が「必要」です（変更しようとするとき「あらかじめ」）。","w":"第8条第1項・第4条第1項第7号・施行規則第3条の2第1項第3号。","r":[["貸金業法","8"],["貸金業法施行規則","3の2"]]},"2":{"t":false,"p":"他に行う事業の種類に変更があったときは、2週間以内の届出が「必要」です。","w":"第8条第1項・第4条第1項第9号。","r":[["貸金業法","8"],["貸金業法","4"]]},"3":{"t":true,"w":"主任者の登録の更新では、届出事項（氏名・登録番号）は変わらないので、届出は不要です。","r":[["貸金業法","8"],["貸金業法","4"]]},"4":{"t":false,"p":"従たる営業所（使用人50人以上）で業務を統括する者の権限を代行し得る地位にある者を変更したときは、届出が「必要」です。","w":"第4条第1項第2号・施行令第3条・施行規則第3条第1項第3号。","r":[["貸金業法","8"],["貸金業法施行規則","3"]]}}},"11-03":{"s":"監督指針Ⅱ－2－3（外部委託）の着眼点です。適切なのはａとｃです。","items":{"a":{"t":true,"w":"監督指針Ⅱ－2－3⑨のとおりです。"},"b":{"t":false,"p":"委託契約によっても、貸金業者と資金需要者等との権利義務関係に変更は「なく」、資金需要者等には貸金業者自身が業務を行ったものと「同様の権利」が確保されている必要があります。","w":"監督指針Ⅱ－2－3③。"},"c":{"t":true,"w":"監督指針Ⅱ－2－3⑧のとおりです。"},"d":{"t":false,"p":"求められているのは「直ちに委託先を変更する態勢」ではなく、顧客利便に支障が生じることを「未然に防止するための態勢」です。","w":"監督指針Ⅱ－2－3④。"}}},"11-04":{"s":"貸金業務取扱主任者の設置数・欠けたときの措置・登録拒否事由を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"50人に対して50分の1以上なので、主任者は1人（Ｂ）で「足ります」。","w":"施行規則第10条の8。","r":[["貸金業法施行規則","10の8"]]},"2":{"t":true,"w":"第12条の3第3項：急な失踪は「予見し難い事由」に当たり（監督指針Ⅱ－2－9（2）③）、2週間以内に必要な措置をとります。","r":[["貸金業法","12の3"]]},"3":{"t":false,"p":"拒否事由になるのは、聴聞の期日・場所の公示の日前「60日以内」に役員であった者です。90日前に退任したＣは「該当しません」。","w":"第24条の27第1項第3号かっこ書。","r":[["貸金業法","24の27"]]},"4":{"t":false,"p":"定年退職は予見できるので、2週間の猶予は「ありません」。","w":"監督指針Ⅱ－2－9（2）③。","r":[["貸金業法","12の3"]]}}},"11-05":{"s":"監督指針Ⅱ－2－10で、第12条の6第4号の「偽りその他不正又は著しく不当な行為」に当たるおそれが大きいとされる例です。4つとも該当します（4個）。","items":{"a":{"t":true,"w":"監督指針Ⅱ－2－10のイｆ。","r":[["貸金業法","12の6"]]},"b":{"t":true,"w":"監督指針Ⅱ－2－10のハ。","r":[["貸金業法","12の6"]]},"c":{"t":true,"w":"監督指針Ⅱ－2－10のトｃ。","r":[["貸金業法","12の6"]]},"d":{"t":true,"w":"監督指針Ⅱ－2－10のチ。","r":[["貸金業法","12の6"]]}}},"11-06":{"s":"返済能力の調査（第13条）の罰則と、監督指針の着眼点を問う問題です。適切なのはｃとｄです。","items":{"a":{"t":false,"p":"信用情報を使用した調査をせずに契約を締結する行為は、行政処分だけでなく刑事罰の対象にも「なります」。","w":"第48条第1項第1号の4。","r":[["貸金業法","13"],["貸金業法","48"]]},"b":{"t":false,"p":"保証人となろうとする個人についても、信用情報を使用した調査をしない行為は刑事罰の対象に「なります」。","w":"第13条第2項・第48条第1項第1号の4。","r":[["貸金業法","13"],["貸金業法","48"]]},"c":{"t":true,"w":"監督指針Ⅱ－2－13－1（1）ロｂⅱ）のとおりです。","r":[["貸金業法","13"]]},"d":{"t":true,"w":"監督指針Ⅱ－2－13－1（1）ロｂⅳ）のとおりです。","r":[["貸金業法","13"]]}}},"11-07":{"s":"総量規制の例外契約（施行規則第10条の23）に当たるものを選ぶ問題です。該当するのは③です。","items":{"1":{"t":false,"p":"高額療養費の貸付けは、例外契約ではなく「除外契約」（施行規則第10条の21第1項第4号）です。","w":"除外契約は総量規制の計算から除かれる契約です。","r":[["貸金業法施行規則","10の21"]]},"2":{"t":false,"p":"新たな事業のための貸付けは、確実に事業の用に供する資金であることと、返済能力を超えないことの「両方」が必要です。","w":"施行規則第10条の23第1項第5号。","r":[["貸金業法施行規則","10の23"]]},"3":{"t":true,"w":"施行規則第10条の23第1項第3号（配偶者と合わせた年収の3分の1以内の貸付け。配偶者の同意が必要）。","r":[["貸金業法施行規則","10の23"]]},"4":{"t":false,"p":"借換えの例外契約は、1か月の負担が既存債務を「上回らない」ことが必要です。","w":"施行規則第10条の23第1項第1号イ。","r":[["貸金業法施行規則","10の23"]]}}},"11-08":{"s":"貸付条件等の掲示（第14条）を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"掲示するのは主任者の「氏名」だけで、役職名や登録番号は「含まれません」。","w":"第14条第1項第4号。","r":[["貸金業法","14"]]},"2":{"t":true,"w":"施行規則第11条第3項第1号ハ。","r":[["貸金業法施行規則","11"]]},"3":{"t":false,"p":"年率は「小数点以下二位」ではなく、少なくとも「小数点以下一位」まで表示します。","w":"施行規則第11条第4項。","r":[["貸金業法施行規則","11"]]},"4":{"t":false,"p":"継続した貸付けの契約に基づく金銭の交付・回収のみを行う現金自動設備では、掲示は「不要」です。","w":"施行規則第11条（掲示の方法）ただし書。","r":[["貸金業法施行規則","11"]]}}},"11-09":{"s":"契約締結前の書面（第16条の2）の対象・方法・交付先を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"「貸金業者が受け取る書面の内容」は、極度方式基本契約の契約締結前の書面の記載事項に「含まれません」。","w":"施行規則第12条の2第2項第1号に挙げられていません。","r":[["貸金業法施行規則","12の2"]]},"2":{"t":false,"p":"相手方の承諾を得れば、電磁的方法で提供「できます」。","w":"第16条の2第4項。","r":[["貸金業法","16の2"]]},"3":{"t":true,"w":"第16条の2第1項かっこ書。","r":[["貸金業法","16の2"]]},"4":{"t":false,"p":"保証人となろうとする者に交付するのは、保証契約の契約締結前の書面（第16条の2第3項）で、極度方式基本契約の契約締結前の書面ではありません。","w":"第16条の2第2項（基本契約の相手方となろうとする者に交付）・第3項。","r":[["貸金業法","16の2"]]}}},"11-10":{"s":"契約締結時の書面の記載と、再交付が必要な変更を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"「返済の方式」は法律が定める記載事項（第17条第1項第5号）で、返済期間・回数を記載しても省略「できません」。","w":"第17条第1項第5号・第6号。","r":[["貸金業法","17"]]},"2":{"t":false,"p":"期限の利益の喪失の定めの変更は、相手方の利益となる変更なら再交付は「不要」です。","w":"施行規則第13条第2項第1号イかっこ書（同条第1項第1号ヌ）。","r":[["貸金業法施行規則","13"]]},"3":{"t":false,"p":"元本及び利息以外の金銭に関する事項の変更は、相手方の利益となる変更なら再交付は「不要」です。","w":"施行規則第13条第2項第1号イかっこ書（同条第1項第1号ニ）。","r":[["貸金業法施行規則","13"]]},"4":{"t":true,"w":"施行規則第13条第2項第1号ロ（同条第1項第1号チ）。","r":[["貸金業法施行規則","13"]]}}},"11-11":{"s":"貸金業者が保存すべきものの保存期間です。適切なのはｄだけです（1個）。","items":{"a":{"t":false,"p":"途中の調査の記録の保存期間は「7年間」ではなく、作成後「3年間」です。","w":"施行規則第10条の27第2項。","r":[["貸金業法施行規則","10の27"]]},"b":{"t":false,"p":"保存期間は「締結した日から5年間」ではなく、「最終の返済期日（債権が消滅したときはその日）まで」です。","w":"施行規則第10条の21第2項第1号。","r":[["貸金業法施行規則","10の21"]]},"c":{"t":false,"p":"極度方式基本契約の帳簿の保存期間は「7年間」ではなく、基本契約の解除の日又は最終の返済期日のうち最後のもの（債権がすべて消滅したときはその日）のいずれか遅い日から「少なくとも10年間」です。","w":"施行規則第17条第1項ただし書。","r":[["貸金業法施行規則","17"]]},"d":{"t":true,"w":"施行規則第10条の9の2第3項。","r":[["貸金業法施行規則","10の9の2"]]}}},"11-12":{"s":"監督指針Ⅱ－2－19（取立行為規制）の記述です。正しいのは③です。","items":{"1":{"t":false,"p":"「債務者等と連絡をとるための合理的方法が他にない場合」も、正当な理由に該当する可能性が高いとされています。","w":"監督指針Ⅱ－2－19（2）②イ。","r":[["貸金業法","21"]]},"2":{"t":false,"p":"家族に知られないよう要請を受けていない場合は、貸金業者と名乗っても「直ちに該当するものではない」とされています。","w":"監督指針Ⅱ－2－19（2）④。","r":[["貸金業法","21"]]},"3":{"t":true,"w":"監督指針Ⅱ－2－19（1）②のとおりです。"},"4":{"t":false,"p":"保証契約に基づく求償権の取立てにも、第21条が「適用され得る」とされています。","w":"監督指針Ⅱ－2－19（2）⑧。","r":[["貸金業法","21"]]}}},"11-13":{"s":"貸金業者の監督（登録の取消し・事業報告書・非協会員の広告）を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"役員の所在を確知できないときは、直ちに取り消すのではなく、その事実を公告し、公告から30日を経過しても申出がないときに、取り消すことが「できる」とされています。","w":"第24条の6の6第1項第1号。","r":[["貸金業法","24の6の6"]]},"2":{"t":false,"p":"純資産額の不足は、必ず取り消す事由ではなく、登録の取消し又は業務停止を命ずることが「できる」事由です。","w":"第24条の6の4第1項第1号。","r":[["貸金業法","24の6の4"]]},"3":{"t":false,"p":"事業報告書の提出期限は「30日以内」ではなく、毎事業年度経過後「3月以内」です。","w":"第24条の6の9。","r":[["貸金業法","24の6の9"]]},"4":{"t":true,"w":"監督指針Ⅲ－3－7のとおりです。","r":[["貸金業法","24の6の10"]]}}},"11-14":{"s":"みなし利息とその例外を問う問題です。適切なのはａとｂです。","items":{"a":{"t":true,"w":"返済方法等の変更で法律上必要となる書面の再交付の費用は、債務者の要請による再発行の手数料（施行令第1条第2号）に当たらないので、第3条により利息とみなされます（結論は公式正答によります）。","r":[["利息制限法","3"],["利息制限法施行令","1"]]},"b":{"t":true,"w":"例外はカードの「再発行」の手数料だけで、最初のカードの発行費用は利息とみなされます（第3条・施行令第1条第1号）。","r":[["利息制限法","3"],["利息制限法施行令","1"]]},"c":{"t":false,"p":"再度の口座振替手続の費用は、利息と「みなされません」。","w":"利息制限法第6条第1項・施行令第1条第3号。","r":[["利息制限法","6"],["利息制限法施行令","1"]]},"d":{"t":false,"p":"強制執行・競売など公の機関の手続の費用は、利息と「みなされません」。","w":"利息制限法第6条第2項第2号。","r":[["利息制限法","6"]]}}},"11-15":{"s":"保証料の制限（利息制限法第8条）を問う問題です。適切なのはａとｂです（2個）。","items":{"a":{"t":true,"w":"利息制限法第8条第2項第1号。","r":[["利息制限法","8"]]},"b":{"t":true,"w":"利息制限法第8条第2項第2号。","r":[["利息制限法","8"]]},"c":{"t":false,"p":"根保証で保証料が元本に対する割合で定められている場合は、「保証契約の時に現に存する元本」に係る法定上限額を使うルールの「対象外」です（このルールは、割合で定められている場合を除いて適用されます）。","w":"利息制限法第8条第3項。","r":[["利息制限法","8"]]},"d":{"t":false,"p":"公租公課の支払に充てられるべきものは、保証料と「みなされません」。","w":"利息制限法第8条第7項第1号イ。","r":[["利息制限法","8"]]}}},"11-16":{"s":"登録の拒否事由（第6条第1項）に該当しないものを選ぶ問題です。該当しないのは①です。","items":{"1":{"t":false,"p":"取消しの日前「30日以内」に役員であった者が対象なので、50日前に退任した者は「該当しません」。","w":"第6条第1項第3号かっこ書。","r":[["貸金業法","6"]]},"2":{"t":true,"w":"第6条第1項第5号・第9号ロ。","r":[["貸金業法","6"]]},"3":{"t":true,"w":"第6条第1項第4号・第9号ロ（どの法律の違反でも拘禁刑（旧懲役）以上）。","r":[["貸金業法","6"]]},"4":{"t":true,"w":"第6条第1項第2号・第9号ロ。","r":[["貸金業法","6"]]}}},"11-17":{"s":"監督指針のシステムリスク管理態勢の着眼点と監督手法です。適切でないのは④です。","items":{"1":{"t":true,"w":"監督指針Ⅱ－2－4（注）のとおりです。"},"2":{"t":true,"w":"公式正答では適切とされています（現行の監督指針（令和8年10月版）には、入口・内部・出口対策の例示は見当たらず、「金融分野におけるサイバーセキュリティに関するガイドライン」を参照するよう定めています）。"},"3":{"t":true,"w":"監督指針Ⅱ－2－4－1⑩イのとおりです。"},"4":{"t":false,"p":"システム障害が発生したことだけを理由に、監督当局が「直ちに業務停止命令を発出する」という記載はありません。","w":"結論は公式正答によります（取り込んだ監督指針に、記述のような対応の記載はありません）。","r":[["貸金業法","24の6の10"]]}}},"11-18":{"s":"年収証明書の種類・要件を問う問題です（元本200万円で年収証明書が必要な場面）。適切でないのは②です。","items":{"1":{"t":true,"w":"施行規則第10条の17第2項第2号かっこ書・第10条の22第2項第3号：地方税額を基に合理的に算出する方法による場合は、直近の（1か月分の）給与の支払明細書で足ります。","r":[["貸金業法施行規則","10の17"],["貸金業法施行規則","10の22"]]},"2":{"t":false,"p":"2年前の源泉徴収票の提出を受けていても、改めて年収証明書の提出を受ける必要が「あります」（結論は公式正答による）。","w":"第13条第3項ただし書・施行規則第10条の17第2項第1号（源泉徴収票は一般的に発行される直近の期間に係るもの）。","r":[["貸金業法","13"],["貸金業法施行規則","10の17"]]},"3":{"t":true,"w":"施行規則第10条の17第3項。","r":[["貸金業法施行規則","10の17"]]},"4":{"t":true,"w":"監督指針Ⅱ－2－13－1（2）②ロ。","r":[["貸金業法施行規則","10の17"]]}}},"11-19":{"s":"総量規制の除外契約（施行規則第10条の21）に当たらないものを選ぶ問題です。該当しないのは③です。","items":{"1":{"t":true,"w":"施行規則第10条の21第1項第8号・第1条の2の3第2号。","r":[["貸金業法施行規則","10の21"],["貸金業法施行規則","1の2の3"]]},"2":{"t":true,"w":"施行規則第10条の21第1項第7号。","r":[["貸金業法施行規則","10の21"]]},"3":{"t":false,"p":"有価証券担保貸付けの除外契約は、貸付金額が有価証券の「時価の範囲内」のものに限られます。時価を超えるものは、金額にかかわらず「該当しません」（1,000万円という基準はありません）。","w":"施行規則第10条の21第1項第5号。","r":[["貸金業法施行規則","10の21"]]},"4":{"t":true,"w":"施行規則第10条の21第1項第3号。","r":[["貸金業法施行規則","10の21"]]}}},"11-20":{"s":"極度方式基本契約の途中の調査（第13条の3）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"極度額の「減額」の措置では、定期調査は免除「されません」（免除は新たな貸付けの「停止」の措置の場合など）。","w":"施行規則第10条の25第3項第2号・第10条の29。","r":[["貸金業法施行規則","10の25"],["貸金業法施行規則","10の29"]]},"2":{"t":true,"w":"施行規則第10条の25第3項第2号・第10条の29第2号。","r":[["貸金業法施行規則","10の25"]]},"3":{"t":true,"w":"施行規則第10条の25第3項第4号（第10条の21第1項第5号〜第7号の契約に当たる極度方式基本契約）。","r":[["貸金業法施行規則","10の25"]]},"4":{"t":true,"w":"第13条の3第3項：極度方式個人顧客合算額50万円は100万円を超えないので不要です。","r":[["貸金業法","13の3"]]}}},"11-21":{"s":"協会の自主規制基本規則（勧誘に関する規則）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"自主規制基本規則第55条第1項第1号。"},"2":{"t":true,"w":"自主規制基本規則第55条第1項第2号。"},"3":{"t":true,"w":"自主規制基本規則第54条第4項。"},"4":{"t":false,"p":"債務者等に勧誘を行うには、その債務者等から勧誘を行うことについての承諾を得「なければなりません」。","w":"自主規制基本規則第54条第1項。"}}},"11-22":{"s":"極度方式基本契約・個別契約・極度方式保証契約の書面を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"第17条第6項。","r":[["貸金業法","17"]]},"2":{"t":true,"w":"施行規則第13条第5項第2号。","r":[["貸金業法施行規則","13"]]},"3":{"t":false,"p":"「基本契約に関し貸金業者が受け取る書面の内容」は、再交付が必要な重要な事項に挙げられていないので、再交付は「不要」です。","w":"施行規則第13条第4項（同条第3項第1号ハは挙げられていません）。","r":[["貸金業法施行規則","13"]]},"4":{"t":true,"w":"第17条第3項・第5項。","r":[["貸金業法","17"]]}}},"11-23":{"s":"受取証書（第18条）と債権証書の返還（第22条）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"受取証書は、「遅滞なく」ではなく「直ちに」、弁済をした者（保証人Ｃ）に交付します。主たる債務者Ｂにも交付する義務はありません。","w":"第18条第1項。","r":[["貸金業法","18"]]},"2":{"t":true,"w":"第18条第2項。","r":[["貸金業法","18"]]},"3":{"t":true,"w":"施行規則第15条第2項。","r":[["貸金業法施行規則","15"]]},"4":{"t":true,"w":"第22条。","r":[["貸金業法","22"]]}}},"11-24":{"s":"開始等の届出（第24条の6の2・施行規則第26条の25）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"施行規則第26条の25第1項第5号。","r":[["貸金業法施行規則","26の25"]]},"2":{"t":true,"w":"施行規則第26条の25第1項第6号。","r":[["貸金業法施行規則","26の25"]]},"3":{"t":true,"w":"施行規則第26条の25第1項第4号。","r":[["貸金業法施行規則","26の25"]]},"4":{"t":false,"p":"届出が必要なのは債権を「譲渡した」場合だけで、「譲り受けた」場合は届出事由では「ありません」。","w":"施行規則第26条の25第1項第3号。","r":[["貸金業法施行規則","26の25"]]}}},"11-25":{"s":"個人信用情報の提供と同意の記録を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"第41条の35第1項・施行規則第30条の12。","r":[["貸金業法","41の35"],["貸金業法施行規則","30の12"]]},"2":{"t":false,"p":"同意の記録の保存期間は「作成日から10年間」ではなく、「同意に基づき指定信用情報機関が信用情報を保有している間」です。","w":"施行規則第30条の16第1項。","r":[["貸金業法施行規則","30の16"]]},"3":{"t":true,"w":"第41条の35第2項。","r":[["貸金業法","41の35"]]},"4":{"t":true,"w":"施行規則第30条の13第2項第2号。","r":[["貸金業法施行規則","30の13"]]}}},"11-26":{"s":"利息・媒介手数料の規制（出資法・貸金業法）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"出資法は刑事罰を定める法律で、契約を「無効」にする定めは「ありません」。年20%を超える部分は利息制限法の上限も超えるので、その超過部分が利息制限法で無効になります（年109.5%を超える契約は貸金業法第42条で契約自体が無効）。","w":"出資法第5条第2項・利息制限法第1条・貸金業法第42条第1項。","r":[["出資法","5"],["利息制限法","1"],["貸金業法","42"]]},"2":{"t":true,"w":"出資法第5条の4第3項。","r":[["出資法","5の4"]]},"3":{"t":true,"w":"貸金業法第12条の8第10項。","r":[["貸金業法","12の8"]]},"4":{"t":true,"w":"貸金業法第12条の8第1項・第4項（違反は行政処分の対象）。","r":[["貸金業法","12の8"]]}}},"11-27":{"s":"利息制限法の元本額の特則（第5条）の計算問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"第5条第1号：残元本5万円＋5万円＝10万円で上限は年18%。","r":[["利息制限法","5"]]},"2":{"t":true,"w":"第5条第2号：同時に50万円＋50万円＝100万円で上限は年15%。","r":[["利息制限法","5"]]},"3":{"t":false,"p":"第一・第二契約は、同時に借りた合計20万円で判断するので上限は18%のままで無効部分はありません。15%に下がるのは第三契約（残元本15万円＋85万円＝100万円）だけです。","w":"第5条第1号・第2号・第1条。","r":[["利息制限法","5"],["利息制限法","1"]]},"4":{"t":true,"w":"第5条：残元本45万円＋5万円＋50万円＝100万円で、第二・第三契約の上限は年15%。","r":[["利息制限法","5"]]}}},"11-28":{"s":"意思表示（心裡留保・虚偽表示・詐欺・強迫）と第三者の保護を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"相手方Ｂが真意でないことを知り又は知ることができたときは、心裡留保の意思表示は「無効」で、Ａは無効を主張「できます」。","w":"民法第93条第1項ただし書。","r":[["民法","93"]]},"2":{"t":true,"w":"民法第94条第2項。","r":[["民法","94"]]},"3":{"t":false,"p":"詐欺の事情を「知っている」第三者Ｃには、取消しを対抗「できます」（対抗できないのは善意（現行法では善意かつ無過失）の第三者です）。","w":"民法第96条第3項。","r":[["民法","96"]]},"4":{"t":false,"p":"強迫による取消しは、事情を知らない第三者にも対抗「できます」。","w":"民法第96条第3項（第三者保護は詐欺の場合だけ）。","r":[["民法","96"]]}}},"11-29":{"s":"時効（第11回の時点の「時効の中断」）を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"訴えが却下された場合も、取り下げた場合と同様に、権利が確定しないので時効の中断（現行法では更新）の効力は「生じません」（現行法では、終了から6箇月の完成猶予にとどまります）。","w":"民法第147条第1項（現行）。結論は公式正答によります。","r":[["民法","147"]]},"2":{"t":false,"p":"仮差押えは、その後に差押えがされなかったことを理由に効力を失うものではありません（現行法では、仮差押えは事由の終了から6箇月の完成猶予事由です）。","w":"民法第149条第1号（現行）。結論は公式正答によります。","r":[["民法","149"]]},"3":{"t":false,"p":"天災等による猶予の期間は「1年」ではありません（現行法では障害の消滅から「3箇月」）。","w":"民法第161条（現行）。","r":[["民法","161"]]},"4":{"t":true,"w":"民法第145条。","r":[["民法","145"]]}}},"11-30":{"s":"抵当権（処分・消滅請求・順位）を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"抵当権を他の債権の担保とすること（転抵当）も「できます」。","w":"民法第376条第1項。","r":[["民法","376"]]},"2":{"t":false,"p":"保証人も、抵当権消滅請求を「できません」。","w":"民法第380条：主たる債務者、保証人及びこれらの者の承継人は、抵当権消滅請求をすることができません。","r":[["民法","380"]]},"3":{"t":false,"p":"抵当権の順位は、契約の締結日ではなく「登記の前後」によります。","w":"民法第373条。","r":[["民法","373"]]},"4":{"t":true,"w":"民法第374条。","r":[["民法","374"]]}}},"11-31":{"s":"債権の効力（履行遅滞・賠償額の予定・債権者代位・詐害行為取消し）を問う問題です。公式正答（基準日2016年4月1日）では①が適切とされています。①は、2020年4月施行の民法改正で内容が変わっています。","law":"①について、公式正答では「期限の到来したことを知った時から」遅滞になるとされています。現行の民法第412条第2項では、期限の到来した後に履行の請求を受けた時又は期限の到来したことを知った時の「いずれか早い時」から遅滞の責任を負うとされています。","items":{"1":{"t":true,"now":false,"w":"公式正答（基準日当時の民法）では適切とされています。現行の民法第412条第2項では、知った時より前に履行の請求を受けていれば、その時から遅滞になります。","r":[["民法","412"]]},"2":{"t":false,"p":"賠償額を予定しても、解除権の行使は「妨げられません」。","w":"民法第420条第2項。","r":[["民法","420"]]},"3":{"t":false,"p":"債務者の一身に専属する権利は、債権者代位の対象に「なりません」。","w":"民法第423条第1項ただし書。","r":[["民法","423"]]},"4":{"t":false,"p":"詐害行為取消権は、裁判外ではなく「裁判所に請求」して行使します。","w":"民法第424条第1項。","r":[["民法","424"]]}}},"11-32":{"s":"債権譲渡の対抗要件と二重譲渡を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"「債務者Ｂ」に対抗するには、確定日付のない通知・承諾で「足ります」。","w":"民法第467条第1項・第2項。","r":[["民法","467"]]},"2":{"t":false,"p":"Ｃへの通知に確定日付がないので、確定日付のある通知を受けたＤが優先し、Ｃは対抗「できません」。","w":"民法第467条第2項。","r":[["民法","467"]]},"3":{"t":true,"w":"いずれも確定日付のある通知の場合、確定日付の先後ではなく、通知が債務者に到達した先後で優劣が決まる、というのが判例の考え方です（条文には直接書かれていません）。","r":[["民法","467"]]},"4":{"t":false,"p":"Ｃへの譲渡について確定日付のある承諾が先にされているので、Ｃが優先し、Ｄは対抗「できません」。","w":"民法第467条第2項。","r":[["民法","467"]]}}},"11-33":{"s":"危険負担・解除権の消滅・第三者のためにする契約・解除権の不可分性を問う問題です。公式正答（基準日2016年4月1日）では①が適切とされています。①は、2020年4月施行の民法改正で結論が変わっています。","law":"①は、改正前の民法第534条（特定物の物権の設定・移転を目的とする双務契約の危険は債権者が負担する）による記述です。この条文は改正で削除され、現行の民法第536条第1項では、当事者双方の責めに帰することができない事由で履行できなくなったときは、債権者は反対給付の履行を拒むことができます。","items":{"1":{"t":true,"now":false,"w":"公式正答（基準日当時の民法）では適切とされています。現行の民法には、この債権者主義の規定（旧第534条）はなく、第536条第1項により債権者は反対給付の履行を拒めます（現行法では記述は適切ではありません）。","r":[["民法","536"]]},"2":{"t":false,"p":"解除権者の行為や過失によらずに目的物が滅失・損傷した場合は、解除権は消滅「しません」。","w":"民法第548条（解除権者が故意又は過失によって目的物を著しく損傷した場合などに消滅）。","r":[["民法","548"]]},"3":{"t":false,"p":"第三者の権利は、契約締結の時ではなく、第三者が債務者に対して「契約の利益を享受する意思を表示した時」に発生します。","w":"民法第537条第3項。","r":[["民法","537"]]},"4":{"t":false,"p":"当事者の一方が数人ある場合、解除はその「全員から又は全員に対して」のみすることができ、1人について解除権が消滅すれば他の者についても「消滅します」。","w":"民法第544条。","r":[["民法","544"]]}}},"11-34":{"s":"相続（熟慮期間・相続債務・半血の兄弟姉妹の相続分・代襲相続）を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"熟慮期間は「6か月」ではなく「3か月」です。","w":"民法第915条第1項。","r":[["民法","915"]]},"2":{"t":false,"p":"遺産分割で債務をＣが負担すると決めても、債権者Ｄはそれに拘束されず、Ｂに対しても法定相続分に応じて請求「できます」。","w":"民法第899条。債権者が遺産分割協議に拘束されないというのは判例の考え方です（条文には直接書かれていません）。","r":[["民法","899"]]},"3":{"t":true,"w":"民法第900条第3号・第4号ただし書：配偶者Ｂが4分の3、兄弟姉妹が残り4分の1。父母の一方だけを同じくする弟Ｄは、父母の双方を同じくする兄Ｃの2分の1なので、Ｃが12分の2、Ｄが12分の1です。","r":[["民法","900"]]},"4":{"t":false,"p":"欠格事由に該当した子の子Ｄは、代襲相続人に「なれます」。","w":"民法第887条第2項。","r":[["民法","887"]]}}},"11-35":{"s":"約束手形と電子記録債権（譲渡・質入れ）を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"「商品の受領と引換えに支払う」という条件付きの記載があると、単純な支払約束ではないので、約束手形は「無効」です。","w":"手形法第75条第2号。","r":[["手形法","75"]]},"2":{"t":true,"w":"手形法第38条第1項（第77条第1項第3号で準用）。","r":[["手形法","38"],["手形法","77"]]},"3":{"t":false,"p":"電子記録債権の譲渡は、合意だけでは効力を生じず、「譲渡記録をしなければ効力を生じません」。","w":"電子記録債権法第17条。","r":[["電子記録債権法","17"]]},"4":{"t":false,"p":"電子記録債権の質権の設定は、発生記録の「引渡し」ではなく、「質権設定記録」をしなければ効力を生じません。","w":"電子記録債権法第36条第1項。","r":[["電子記録債権法","36"]]}}},"11-36":{"s":"行為能力を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"民法第6条第1項。","r":[["民法","6"]]},"2":{"t":true,"w":"民法第13条第1項第6号。","r":[["民法","13"]]},"3":{"t":false,"p":"法定代理人・保佐人・補助人が期間内に確答しないときは、「取り消した」ではなく「追認した」ものとみなされます。","w":"民法第20条第2項。","r":[["民法","20"]]},"4":{"t":true,"w":"民法第21条。","r":[["民法","21"]]}}},"11-37":{"s":"代理を問う問題です。適切でないのは①です。代理人は行為能力者（制限を受けていない人）でなくてもかまいません。","items":{"1":{"t":false,"p":"被保佐人に代理権を付与することは「できない」のではなく、「できます」。","w":"民法第102条：制限行為能力者（被保佐人など）が代理人としてした行為は、行為能力の制限を理由に取り消すことができません。つまり制限行為能力者も代理人になれます。","r":[["民法","102"]]},"2":{"t":true,"w":"民法第104条：委任による代理人（任意代理人）は、本人の許諾を得たとき、又はやむを得ない事由があるときでなければ、復代理人（代理人がさらに選ぶ代理人）を選任できません。","r":[["民法","104"]]},"3":{"t":true,"w":"民法第108条第1項：当事者双方の代理人としてした行為（双方代理）は、債務の履行や本人があらかじめ許諾した行為を除き、代理権を有しない者がした行為とみなされます。","r":[["民法","108"]]},"4":{"t":true,"w":"民法第111条第1項第2号：代理人が後見開始の審判を受けたことは代理権の消滅事由です。","r":[["民法","111"]]}}},"11-38":{"s":"条件と期限を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"民法第129条：条件の成否が未定の間の権利義務も、一般の規定に従い処分・相続・保存し、そのために担保を供することができます。","r":[["民法","129"]]},"2":{"t":false,"p":"停止条件と解除条件の説明が逆です。停止条件付法律行為は成就した時から効力を「失う」のではなく「生ずる」、解除条件付法律行為は成就した時から効力を「生じる」のではなく「失う」です。","w":"民法第127条第1項・第2項。","r":[["民法","127"]]},"3":{"t":true,"w":"民法第135条第1項（始期）・第2項（終期）。","r":[["民法","135"]]},"4":{"t":true,"w":"民法第137条第2号：債務者が担保を滅失・損傷・減少させたときは、期限の利益（期限まで払わなくてよい利益）を主張できません。","r":[["民法","137"]]}}},"11-39":{"s":"連帯債務を問う問題です。公式正答は①（適切でない）です。","law":"この回の基準日は2020年4月の民法改正の前です。改正後の第441条では、連帯債務者の1人について生じた事由は、更改・相殺・混同のほかは原則として他の連帯債務者に効力を生じません（相対的効力）。免除と時効の完成も相対的効力になったため、現行法では①は適切、④は適切でないことになります。","items":{"1":{"t":false,"now":true,"p":"出題時の民法では、連帯債務者の1人に対する免除は、その者の負担部分について他の連帯債務者にも効力を「生じない」のではなく「生じる」とされていました（公式正答による）。","w":"現行の民法第441条では、免除は第438条（更改）・第439条第1項（相殺）・第440条（混同）に当たらないため、他の連帯債務者に効力を生じません。現行法ではこの記述は適切です。","r":[["民法","441"]]},"2":{"t":true,"w":"民法第437条：1人について法律行為の無効・取消しの原因があっても、他の連帯債務者の債務は効力を妨げられません。","r":[["民法","437"]]},"3":{"t":true,"w":"民法第439条第1項。","r":[["民法","439"]]},"4":{"t":true,"now":false,"p":"現行法では、1人について時効が完成しても、他の連帯債務者が負担部分について義務を「免れる」のではなく、他の連帯債務者には効力を「生じません」。","w":"出題時の民法では適切とされていました（公式正答による）。現行の民法第441条では、時効の完成は相対的効力です。","r":[["民法","441"]]}}},"11-40":{"s":"債権の消滅（弁済・相殺・混同・更改）を問う問題です。公式正答は④（適切でない）です。","law":"この回の基準日は2020年4月の民法改正の前です。改正後の第509条では、相殺が禁止されるのは悪意による不法行為や人の生命・身体の侵害による損害賠償の債務の場合に限られるため、②は現行法では適切でないことになります。","items":{"1":{"t":true,"w":"公式正答では適切です。民法第478条：受領権者としての外観を有する者に対する弁済は、弁済した者が善意（知らなかった）かつ無過失のときに限り効力を有します。","r":[["民法","478"]]},"2":{"t":true,"now":false,"p":"現行法では、不法行為に基づく損害賠償の債務であっても、悪意による不法行為や人の生命・身体の侵害によるものでなければ、相殺「できない」のではなく「できます」。","w":"出題時の民法では、不法行為によって生じた債務の債務者（ここではＡ）は相殺できないとされていました（公式正答による）。現行の第509条は、第1号（悪意による不法行為）・第2号（人の生命・身体の侵害）の場合に限って相殺を禁止しています。問題文にはこれらに当たる事情がありません。","r":[["民法","509"]]},"3":{"t":true,"w":"民法第520条：債権と債務が同一人に帰属したとき（混同）は、債権が第三者の権利の目的であるときを除き、その債権は消滅します。","r":[["民法","520"]]},"4":{"t":false,"p":"確定日付のある証書は、更改の「効力を生じる要件」ではなく「第三者に対抗する要件」です。","w":"民法第515条：債権者の交替による更改は、更改前の債権者・更改後の債権者・債務者の契約でできます（第1項）。確定日付のある証書によらなければ、第三者に対抗できません（第2項）。","r":[["民法","515"]]}}},"11-41":{"s":"破産法を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"破産法第18条第2項。疎明とは、一応確からしいと思わせる程度の証明のことです。","r":[["破産法","18"]]},"2":{"t":true,"w":"破産法第97条第1号。","r":[["破産法","97"]]},"3":{"t":false,"p":"配当表に不服がある破産債権者は、公告の後は異議を申し立てられない「のではなく」、最後配当に関する除斥期間が経過した後1週間以内に限り、異議を申し立てることができます。","w":"破産法第200条第1項。","r":[["破産法","200"]]},"4":{"t":true,"w":"破産法第248条第1項：免責許可の申立ては、破産手続開始の申立てがあった日から破産手続開始の決定が確定した日以後1月を経過する日までの間にできます。","r":[["破産法","248"]]}}},"11-42":{"s":"犯罪収益移転防止法を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"犯罪収益移転防止法第4条第1項第1号。","r":[["犯収法","4"]]},"2":{"t":false,"p":"なりすましの疑いがある取引「であって、かつ」偽りの疑いがある顧客との取引ではなく、どちらか一方に当たる取引です（第1号と第2号は別々の類型）。","w":"犯罪収益移転防止法施行令第12条第1項：第1号はなりすましの疑いがある取引、第2号は確認事項を偽っていた疑いがある顧客等との取引です。","r":[["犯罪による収益の移転防止に関する法律施行令","12"]]},"3":{"t":true,"w":"犯罪収益移転防止法第6条第1項・第2項（確認記録は7年間保存）。","r":[["犯収法","6"]]},"4":{"t":true,"w":"犯罪収益移転防止法第7条第1項・第3項（取引記録は7年間保存）。","r":[["犯収法","7"]]}}},"11-43":{"s":"個人データの第三者提供の制限を問う問題です。適切なのは②です。","law":"問題文の「個人情報保護法第23条」は、現行法では第27条です。また、金融分野ガイドラインで第三者提供の制限を定めるのは、現行版では第12条です。","items":{"1":{"t":false,"p":"第三者から「本人の親族」を除く定めはありません。本人の親族も第三者に当たります。","w":"個人情報保護法第27条第5項が第三者に当たらないとするのは、委託・事業の承継・共同利用の3つの場合で、本人の親族は挙げられていません（公式正答による）。","r":[["個人情報保護法","27"]]},"2":{"t":true,"w":"通則ガイドライン（第三者に該当しない場合）：「責任を有する者」とは、共同して利用するすべての事業者の中で、第一次的に苦情の受付・処理、開示・訂正等を行う権限を有する者をいいます。個人情報保護法第27条第5項第3号。","r":[["個人情報保護法","27"]]},"3":{"t":false,"p":"利用目的の達成に必要な範囲内での委託に伴う提供は、本人の同意が「必要」ではなく「不要」です（委託先は第三者に当たらない）。","w":"個人情報保護法第27条第5項第1号。","r":[["個人情報保護法","27"]]},"4":{"t":false,"p":"合併などによる事業の承継に伴う提供は、本人の同意が「必要」ではなく「不要」です（承継先は第三者に当たらない）。","w":"個人情報保護法第27条第5項第2号。","r":[["個人情報保護法","27"]]}}},"11-44":{"s":"消費者契約法を問う問題です。適切なのは④です。","items":{"1":{"t":false,"p":"事業として又は事業のために契約の当事者となる個人は、事業者に「含まれない」のではなく「含まれます」。","w":"消費者契約法第2条第2項。","r":[["消費者契約法","2"]]},"2":{"t":false,"p":"無効になるのは消費者契約「全体」ではなく、平均的な損害の額を「超える部分」です。","w":"消費者契約法第9条第1項第1号。","r":[["消費者契約法","9"]]},"3":{"t":false,"p":"困惑による契約の取消権を持つのは「適格消費者団体」ではなく「消費者」です。","w":"消費者契約法第4条第3項：取り消すことができるのは消費者です。適格消費者団体が持つのは差止請求権です（第12条）。","r":[["消費者契約法","4"],["消費者契約法","12"]]},"4":{"t":true,"w":"消費者契約法第8条第1項第2号：事業者の故意又は重大な過失による債務不履行の責任の一部を免除する条項は無効です。","r":[["消費者契約法","8"]]}}},"11-45":{"s":"誇大広告の禁止等（貸金業法第16条）と罰則を問う問題です。適切なのは④です。刑事罰があるのは第16条第1項の違反です。","items":{"1":{"t":false,"p":"不適当と認められる勧誘の禁止（第16条第3項）の違反は、行政処分の対象ですが、刑事罰の対象では「ありません」。","w":"罰則を定める第48条が挙げるのは第16条第1項の違反で、第3項は挙げられていません。","r":[["貸金業法","16"],["貸金業法","48"]]},"2":{"t":false,"p":"過度な広告・勧誘の禁止（第16条第5項）の違反は、行政処分の対象ですが、刑事罰の対象では「ありません」。","w":"第48条が挙げるのは第16条第1項の違反です。","r":[["貸金業法","16"],["貸金業法","48"]]},"3":{"t":false,"p":"他の貸金業者の利用者などを対象として勧誘する旨の表示の禁止（第16条第2項第2号）の違反は、行政処分の対象ですが、刑事罰の対象では「ありません」。","w":"第48条が挙げるのは第16条第1項の違反です。","r":[["貸金業法","16"],["貸金業法","48"]]},"4":{"t":true,"w":"貸金業法第16条第1項の違反は、第48条第1項第3号により刑事罰の対象です。","r":[["貸金業法","16"],["貸金業法","48"]]}}},"11-46":{"s":"日本貸金業協会の紛争解決等業務に関する規則を問う問題です。適切なのは③です。","items":{"1":{"t":false,"p":"貸金業務関連紛争は、当事者が和解をすることが「できないもの」ではなく「できるもの」です。","w":"紛争解決等業務に関する規則第2条第2号。","r":[]},"2":{"t":false,"p":"苦情処理手続の代理人は、法定代理人又は弁護士「に限られる」のではなく、認定司法書士（一定の額以下の苦情）もなれます。必要な事情があるときは、相談センターの許可でそれ以外の者もなれます。","w":"紛争解決等業務に関する規則第38条第1項・第2項。","r":[]},"3":{"t":true,"w":"紛争解決等業務に関する規則第93条第1項（標準処理期間）。苦情処理手続は3か月以内です（第52条第1項）。","r":[]},"4":{"t":false,"p":"当事者双方が和解案を受諾したときは、「裁判所に届け出ることにより」ではなく、「受諾した時点で」和解が成立します。","w":"紛争解決等業務に関する規則第89条第1項・第2項。","r":[]}}},"11-47":{"s":"景品表示法を問う問題です。適切でないのは②です。","law":"問題文の条番号は出題時のものです。現行法では、事業者が講ずべき管理上の措置は第22条、勧告・公表は第24条、協定又は規約は第36条です。","items":{"1":{"t":true,"w":"景品表示法第2条第4項。","r":[["景品表示法","2"]]},"2":{"t":false,"p":"協定又は規約は、届出ではなく「内閣総理大臣及び公正取引委員会の認定」を受けて締結します。また、事業者団体が違反事業者に課徴金を「課すことはできません」（課徴金納付命令は内閣総理大臣が行います）。","w":"景品表示法第36条第1項（協定又は規約）、第8条（課徴金納付命令）。","r":[["景品表示法","36"],["景品表示法","8"]]},"3":{"t":true,"w":"景品表示法第7条第2項（不実証広告規制）：資料を提出しないときは、不当な表示（第5条第1号）とみなされます。","r":[["景品表示法","7"]]},"4":{"t":true,"w":"現行の景品表示法第24条第1項・第2項（措置は第22条第1項）。","r":[["景品表示法","24"],["景品表示法","22"]]}}},"11-48":{"s":"企業会計原則の一般原則を問う問題です。適切なのは③（一般原則七）です。","items":{"1":{"t":false,"p":"「堅実性の原則」という一般原則はありません。一般原則六は、企業の財政に不利な影響を及ぼす可能性がある場合に備えて適当に健全な会計処理をすることを求めるもの（保守主義の原則）です。","w":"企業会計原則 第一 一般原則 一〜七に、このような注記の原則はありません。原則の呼び名は資料に書かれておらず、公式正答によります。","r":[]},"2":{"t":false,"p":"一般原則三は、「自己資本と他人資本」「純資産と負債」ではなく、「資本取引と損益取引」を明瞭に区別し、特に「資本剰余金と利益剰余金」を混同してはならないとするもの（資本取引・損益取引区分の原則）です。","w":"企業会計原則 第一 一般原則 三。","r":[]},"3":{"t":true,"w":"企業会計原則 第一 一般原則 七の内容どおりです（単一性の原則）。","r":[]},"4":{"t":false,"p":"一般原則二は、「明確に表示する」ではなく「正確な」会計帳簿を作成することを求めるもので、「明確性の原則」ではなく「正規の簿記の原則」と呼ばれます。","w":"企業会計原則 第一 一般原則 二：すべての取引につき、正規の簿記の原則に従って、正確な会計帳簿を作成しなければならない。","r":[]}}},"11-49":{"s":"貸借対照表の区分を問う問題です。適切なのは①です。会社計算規則は資料にないため公式正答によりますが、企業会計原則の貸借対照表原則で同じ内容を確認できる肢はその旨を書いています。","items":{"1":{"t":true,"w":"企業会計原則 貸借対照表原則：固定資産は、有形固定資産、無形固定資産及び投資その他の資産に区分しなければならない。","r":[]},"2":{"t":false,"p":"前受金は「流動資産」ではなく「流動負債」に属します。","w":"企業会計原則 注解〔注16〕：受取手形、売掛金、前払金、支払手形、買掛金、前受金等の主目的たる営業取引により発生した債権及び債務は、流動資産又は流動負債に属する。","r":[]},"3":{"t":false,"p":"1年内に費用となる前払費用は「流動負債」ではなく「流動資産」に属します。","w":"企業会計原則 貸借対照表原則：前払費用で1年以内に費用となるものは、流動資産に属する。","r":[]},"4":{"t":false,"p":"社債は「純資産の部」ではなく「負債（固定負債）」です。","w":"企業会計原則 貸借対照表原則：社債、長期借入金等の長期債務は、固定負債に属する。株式会社の純資産の部の区分は、会社計算規則が資料にないため公式正答によります。","r":[]}}},"11-50":{"s":"損益計算書の区分を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"会社計算規則は取り込んだ資料にないため、この肢は公式正答によります。","r":[]},"2":{"t":true,"w":"会社計算規則は取り込んだ資料にないため、この肢は公式正答によります。企業会計原則でも、営業損益計算の区分で営業利益を計算するとされています。","r":[]},"3":{"t":true,"w":"会社計算規則は取り込んだ資料にないため、この肢は公式正答によります。企業会計原則でも、経常損益計算の区分は営業損益計算の結果を受けて、営業活動以外の原因から生ずる損益を記載し、経常利益を計算するとされています。","r":[]},"4":{"t":false,"p":"当期純損益は、経常損益に「貸倒引当金を加え減価償却費を減じて」ではなく、「特別利益を加え特別損失を減じて」計算します。","w":"企業会計原則 損益計算書原則：経常利益に特別損益に属する項目を加減して当期純利益を表示します。会社計算規則の表示は資料にないため、公式正答によります。","r":[]}}},"12-01":{"s":"貸金業法第2条の用語の定義です。4つとも適切です（4個）。","items":{"a":{"t":true,"w":"第2条第4項〜第6項（資金需要者等＝顧客等又は債務者等）。","r":[["貸金業法","2"]]},"b":{"t":true,"w":"第2条第11項。","r":[["貸金業法","2"]]},"c":{"t":true,"w":"第2条第17項。","r":[["貸金業法","2"]]},"d":{"t":true,"w":"第2条第23項。","r":[["貸金業法","2"]]}}},"12-02":{"s":"登録の拒否事由（第6条第1項）に当たるものを選ぶ問題です。当たるのは③です。","items":{"1":{"t":false,"p":"被補助人であること自体は、拒否事由に「当たりません」。役員について拒否事由となるのは、心身の故障のため職務を適正に執行できない者として内閣府令で定める者などです。","w":"第6条第1項第9号イ・施行規則第5条の4。","r":[["貸金業法","6"],["貸金業法施行規則","5の4"]]},"2":{"t":false,"p":"罰金刑で拒否事由になるのは、貸金業法・出資法など法律が列挙したものの違反に限られます。道路交通法違反の罰金刑は「該当しません」。","w":"第6条第1項第5号・第9号ロ。","r":[["貸金業法","6"]]},"3":{"t":true,"w":"第6条第1項第3号かっこ書（取消しの日前30日以内に役員であった者）・第9号ロ。","r":[["貸金業法","6"]]},"4":{"t":false,"p":"常務に従事する役員のうち1人でも貸付けの業務に3年以上従事した経験があれば、基準を満たすので、拒否事由に「当たりません」。","w":"施行規則第5条の7第1項第2号（「役員のうちに…有する者があること」）。","r":[["貸金業法施行規則","5の7"]]}}},"12-03":{"s":"変更の届出（第8条）の期限です。「あらかじめ」届け出るのは、営業所の名称・所在地と広告等に表示する連絡先です。正しいのは②です。","items":{"1":{"t":false,"p":"取締役の変更は、「あらかじめ」ではなく、変更があった日から「2週間以内」に届け出ます。","w":"第8条第1項・第4条第1項第2号。","r":[["貸金業法","8"],["貸金業法","4"]]},"2":{"t":true,"w":"第4条第1項第2号の「政令で定める使用人」（施行令第3条・施行規則第3条第1項第3号）の変更で、2週間以内に届け出ます。","r":[["貸金業法","8"],["貸金業法施行規則","3"]]},"3":{"t":false,"p":"広告等に表示するホームページアドレスの変更は、変更後2週間以内ではなく、変更しようとするとき「あらかじめ」届け出ます。","w":"第8条第1項・第4条第1項第7号・施行規則第3条の2。","r":[["貸金業法","8"],["貸金業法施行規則","3の2"]]},"4":{"t":false,"p":"業務の種類及び方法の変更は、「あらかじめ」ではなく、変更があった日から「2週間以内」に届け出ます。","w":"第8条第1項・第4条第1項第8号。","r":[["貸金業法","8"],["貸金業法","4"]]}}},"12-04":{"s":"監督指針の顧客等に関する情報管理態勢（Ⅱ－2－2）と外部委託（Ⅱ－2－3）の着眼点です。適切なのはａとｃです。","items":{"a":{"t":true,"w":"監督指針Ⅱ－2－2のとおりです。"},"b":{"t":false,"p":"クレジットカード情報等は、保存期間経過後は「適切かつ速やかに廃棄」します。廃棄せずに保管し続けるのではありません。","w":"監督指針Ⅱ－2－2（クレジットカード情報等）。"},"c":{"t":true,"w":"監督指針Ⅱ－2－3のとおりです。"},"d":{"t":false,"p":"二段階以上の委託では、外部委託先が再委託先等に十分な監督を行っているかを確認し、必要に応じて貸金業者自身も直接監督します。外部委託先に監督を行わせないのではありません。","w":"監督指針Ⅱ－2－3⑩。"}}},"12-05":{"s":"利息・保証料等の制限（第12条の8）を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"利息制限法の上限を超える利息の契約は行政処分の対象ですが、刑事罰は出資法の上限（年20%）を超えた場合なので、「必ず」刑事罰の対象になるわけではありません。","w":"第12条の8第1項・出資法第5条第2項。","r":[["貸金業法","12の8"],["出資法","5"]]},"2":{"t":false,"p":"保証料の確認は、保証契約を締結した後に「遅滞なく」ではなく、締結する「まで」に行います。","w":"第12条の8の保証料の確認義務。","r":[["貸金業法","12の8"]]},"3":{"t":true,"w":"第12条の8第9項・施行規則第10条の14第2号。","r":[["貸金業法","12の8"],["貸金業法施行規則","10の14"]]},"4":{"t":false,"p":"契約の更新があっても、新たな媒介手数料を受領・要求することは「できません」。","w":"第12条の8第10項。","r":[["貸金業法","12の8"]]}}},"12-06":{"s":"年収証明書（資力を明らかにする書面等）の提出が必要な場面です。適切なのはｃとｄです。","items":{"a":{"t":false,"p":"貸付金額50万円は50万円を「超えない」ので、他社借入れがなければ年収証明書は「不要」です。","w":"第13条第3項第1号・第2号。","r":[["貸金業法","13"]]},"b":{"t":false,"p":"年収証明書の提出義務は「個人顧客」についてのもので、保証人となろうとする者は対象外です。","w":"第13条第3項。","r":[["貸金業法","13"]]},"c":{"t":true,"w":"第13条第3項第2号：自社10万円＋他社残高100万円超で100万円を超えます。","r":[["貸金業法","13"]]},"d":{"t":true,"w":"80万円は50万円を超えるので必要です（第13条第3項第1号）。2年前の源泉徴収票ではただし書の「既に提出を受けている場合」に当たらないことの結論は公式正答によります（施行規則第10条の17第2項第1号：一般的に発行される直近の期間に係るもの）。","r":[["貸金業法","13"],["貸金業法施行規則","10の17"]]}}},"12-07":{"s":"総量規制の除外契約（施行規則第10条の21）です。適切なのはｃとｄです（2個）。","items":{"a":{"t":false,"p":"不動産の「改良」に必要な資金の貸付けも、除外契約に「該当します」。","w":"施行規則第10条の21第1項第1号。","r":[["貸金業法施行規則","10の21"]]},"b":{"t":false,"p":"不動産の建設資金の貸付けまでのつなぎ融資は、除外契約に「該当します」。","w":"施行規則第10条の21第1項第2号。","r":[["貸金業法施行規則","10の21"]]},"c":{"t":true,"w":"施行規則第10条の21第1項第8号・第1条の2の3第5号。","r":[["貸金業法施行規則","10の21"],["貸金業法施行規則","1の2の3"]]},"d":{"t":true,"w":"施行規則第10条の21第1項第3号。","r":[["貸金業法施行規則","10の21"]]}}},"12-08":{"s":"極度方式基本契約の途中の調査（第13条の3）を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"5万円を「超え」、かつ残高10万円を「超える」ことが要件です。5万円・10万円ちょうどなら調査は「不要」です。","w":"施行規則第10条の24第1項第1号。","r":[["貸金業法施行規則","10の24"]]},"2":{"t":false,"p":"極度額の「減額」の措置では、定期調査は免除「されません」（免除は新たな貸付けの停止の措置の場合など）。","w":"施行規則第10条の25第3項第2号・第10条の29。","r":[["貸金業法施行規則","10の25"],["貸金業法施行規則","10の29"]]},"3":{"t":false,"p":"極度方式個人顧客合算額60万円は100万円を「超えない」ので、年収証明書は「不要」です。","w":"第13条の3第3項。","r":[["貸金業法","13の3"]]},"4":{"t":true,"w":"施行規則第10条の24第2項。","r":[["貸金業法施行規則","10の24"]]}}},"12-09":{"s":"貸付条件の広告（第15条）で表示しなければならない事項です。該当するのは①です。","items":{"1":{"t":true,"w":"施行規則第12条第1項第1号イ。","r":[["貸金業法","15"],["貸金業法施行規則","12"]]},"2":{"t":false,"p":"利息の計算の方法は、広告の表示事項に「含まれません」（契約締結前・締結時の書面の記載事項です）。","w":"第15条第1項・施行規則第12条第1項第1号。","r":[["貸金業法","15"],["貸金業法施行規則","12"]]},"3":{"t":false,"p":"期限の利益の喪失の定めは、広告の表示事項に「含まれません」。","w":"第15条第1項・施行規則第12条第1項第1号。","r":[["貸金業法","15"],["貸金業法施行規則","12"]]},"4":{"t":false,"p":"債務者が負担すべき元本及び利息以外の金銭は、広告の表示事項に「含まれません」。","w":"第15条第1項・施行規則第12条第1項第1号。","r":[["貸金業法","15"],["貸金業法施行規則","12"]]}}},"12-10":{"s":"契約締結前の書面（第16条の2）の対象・方法・記載事項を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"極度方式貸付けには、契約締結前の書面の交付義務は「ありません」。","w":"第16条の2第1項かっこ書。","r":[["貸金業法","16の2"]]},"2":{"t":false,"p":"相手方となろうとする者の承諾を得れば、電磁的方法で提供「できます」。","w":"第16条の2第4項。","r":[["貸金業法","16の2"]]},"3":{"t":true,"w":"施行規則第12条の2第2項第1号ヘ。","r":[["貸金業法施行規則","12の2"]]},"4":{"t":false,"p":"省略できるのは登録番号の「括弧書」だけで、登録番号そのものを契約番号で省略することは「できません」。","w":"施行規則第12条の2第1項第1号イ。","r":[["貸金業法施行規則","12の2"]]}}},"12-11":{"s":"契約締結時の書面の再交付が必要な変更（施行規則第13条第2項）です。正しいのは④です。","items":{"1":{"t":false,"p":"契約の相手方の氏名・住所（施行規則第13条第1項第1号ロ）は、再交付が必要な重要な事項に「挙げられていません」。","w":"施行規則第13条第2項第1号。","r":[["貸金業法施行規則","13"]]},"2":{"t":false,"p":"期限の利益の喪失の定めの変更は、相手方に有利な変更なら再交付は「不要」です。","w":"施行規則第13条第2項第1号イかっこ書（同条第1項第1号ヌ）。","r":[["貸金業法施行規則","13"]]},"3":{"t":false,"p":"期限前返済の可否・内容の変更は、相手方に有利な変更なら再交付は「不要」です。","w":"施行規則第13条第2項第1号イかっこ書（同条第1項第1号リ）。","r":[["貸金業法施行規則","13"]]},"4":{"t":true,"w":"施行規則第13条第2項第1号ロ（同条第1項第1号ト）。","r":[["貸金業法施行規則","13"]]}}},"12-12":{"s":"受取証書（第18条第1項）の記載事項です。該当するのはａとｂです（2個）。","items":{"a":{"t":true,"w":"第18条第1項第4号。","r":[["貸金業法","18"]]},"b":{"t":true,"w":"第18条第1項第3号。","r":[["貸金業法","18"]]},"c":{"t":false,"p":"貸付けの利率は、受取証書の記載事項に「含まれません」。","w":"第18条第1項各号・施行規則第15条第1項に挙げられていません。","r":[["貸金業法","18"],["貸金業法施行規則","15"]]},"d":{"t":false,"p":"利息の計算の方法は、受取証書の記載事項に「含まれません」。","w":"第18条第1項各号・施行規則第15条第1項に挙げられていません。","r":[["貸金業法","18"],["貸金業法施行規則","15"]]}}},"12-13":{"s":"貸金業者が保存すべきものの保存期間です。適切なのはｃとｄです。","items":{"a":{"t":false,"p":"従業者名簿の保存期間は「5年間」ではなく、最終の記載から「10年間」です。","w":"施行規則第10条の9の2第3項。","r":[["貸金業法施行規則","10の9の2"]]},"b":{"t":false,"p":"同意の記録の保存期間は「提供した日から5年間」ではなく、「同意に基づき指定信用情報機関が信用情報を保有している間」です。","w":"施行規則第30条の16第1項。","r":[["貸金業法施行規則","30の16"]]},"c":{"t":true,"w":"施行規則第10条の18第2項第1号。","r":[["貸金業法施行規則","10の18"]]},"d":{"t":true,"w":"施行規則第10条の23第2項第2号（医療費の請求書又は見積書）。","r":[["貸金業法施行規則","10の23"]]}}},"12-14":{"s":"債権譲渡等の規制（第24条）を問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"第24条第1項。","r":[["貸金業法","24"]]},"2":{"t":false,"p":"譲受人は、債権の内容を明らかにする書面（第17条の準用）を債務者に交付「しなければなりません」。","w":"第24条第2項。","r":[["貸金業法","24"],["貸金業法","17"]]},"3":{"t":false,"p":"譲受人の受取証書には、当該債権の譲受年月日も記載が「必要」です（結論は公式正答によります）。","w":"第24条第2項で第18条が譲受人に準用されます（必要な読替えは政令で定めます）。","r":[["貸金業法","24"],["貸金業法","18"]]},"4":{"t":false,"p":"譲受人も、帳簿を作成・保存「しなければなりません」。","w":"第24条第2項で第19条が譲受人に準用されます。","r":[["貸金業法","24"],["貸金業法","19"]]}}},"12-15":{"s":"開始等の届出（第24条の6の2）の事由と期限（2週間以内）です。正しいのは③です。","items":{"1":{"t":false,"p":"届出期限は「30日以内」ではなく「2週間以内」です。","w":"施行規則第26条の25第1項第1号（第6条第1項第13号＝営業所等の主任者の要件を欠く者に該当することとなった場合）・第2項。","r":[["貸金業法施行規則","26の25"],["貸金業法","6"]]},"2":{"t":false,"p":"債権を「譲り受けた」場合は、届出事由では「ありません」（届出が必要なのは譲渡した場合）。","w":"施行規則第26条の25第1項第3号。","r":[["貸金業法施行規則","26の25"]]},"3":{"t":true,"w":"施行規則第26条の25第1項第7号・第2項。","r":[["貸金業法施行規則","26の25"]]},"4":{"t":false,"p":"届出期限は「30日以内」ではなく「2週間以内」です。","w":"施行規則第26条の25第1項第4号・第2項。","r":[["貸金業法施行規則","26の25"]]}}},"12-16":{"s":"利息制限法（天引き・賠償額の予定・元本額の特則）を問う問題です。適切なのはｃとｄです。","items":{"a":{"t":false,"p":"天引額が上限を超えても契約全体が無効になるのではなく、超過部分が「元本の支払に充てたもの」とみなされます。","w":"利息制限法第2条。","r":[["利息制限法","2"]]},"b":{"t":false,"p":"営業的金銭消費貸借の賠償額の予定の上限は、1.46倍ではなく「年2割」です。","w":"利息制限法第7条第1項（1.46倍は営業的でない場合。第4条第1項）。","r":[["利息制限法","7"],["利息制限法","4"]]},"c":{"t":true,"w":"利息制限法第5条第1号。","r":[["利息制限法","5"]]},"d":{"t":true,"w":"利息制限法第5条第2号。","r":[["利息制限法","5"]]}}},"12-17":{"s":"廃業等の届出（第10条）です。適切でないのは①です。","items":{"1":{"t":false,"p":"破産手続開始の決定があった場合に届け出るのは、貸金業者本人ではなく「破産管財人」です。","w":"第10条第1項第3号。","r":[["貸金業法","10"]]},"2":{"t":true,"w":"第10条第1項第1号。","r":[["貸金業法","10"]]},"3":{"t":true,"w":"第10条第1項第2号。","r":[["貸金業法","10"]]},"4":{"t":true,"w":"第10条第1項第4号。","r":[["貸金業法","10"]]}}},"12-18":{"s":"監督指針Ⅱ－2－6（反社会的勢力による被害の防止）の着眼点です。適切でないのは④です。","items":{"1":{"t":true,"w":"監督指針Ⅱ－2－6②のとおりです。"},"2":{"t":true,"w":"監督指針Ⅱ－2－6③のとおりです。"},"3":{"t":true,"w":"監督指針Ⅱ－2－6⑤ロのとおりです。"},"4":{"t":false,"p":"刑事事件化は「極力回避」するのではなく、積極的に被害届を提出するなど「刑事事件化も躊躇しない」対応とされています。","w":"監督指針Ⅱ－2－6⑥ハ。"}}},"12-19":{"s":"貸金業務取扱主任者（設置・常時勤務・登録拒否事由・氏名の明示）を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"第12条の3第2項。","r":[["貸金業法","12の3"]]},"2":{"t":false,"p":"営業時間内に営業所等に常時駐在している必要は「ありません」。","w":"監督指針Ⅱ－2－9（2）①。","r":[["貸金業法施行規則","10の7"]]},"3":{"t":true,"w":"第24条の27第1項第3号かっこ書：取消しに係る聴聞の期日及び場所の公示の日前60日以内にその法人の役員であった者で、取消しの日から5年を経過しないもの（貸金業の登録拒否の「取消しの日前30日以内」とは期間が違います）。","r":[["貸金業法","24の27"]]},"4":{"t":true,"w":"第12条の3第4項。","r":[["貸金業法","12の3"]]}}},"12-20":{"s":"禁止行為（第12条の6）と監督指針の解釈です。適切でないのは④です。","items":{"1":{"t":true,"w":"第12条の6第3号（刑事罰は第1号の虚偽告知だけ。第48条第1項第1号の2）。","r":[["貸金業法","12の6"],["貸金業法","48"]]},"2":{"t":true,"w":"監督指針Ⅱ－2－10のイの例示のとおりです。","r":[["貸金業法","12の6"]]},"3":{"t":true,"w":"監督指針Ⅱ－2－10のロの例示のとおりです。","r":[["貸金業法","12の6"]]},"4":{"t":false,"p":"「不正な」行為が「違法な行為」、「不当な」行為が「実質的に妥当性を欠く又は適当でない行為で、違法な程度にまで達していない行為」です。記述は定義が入れ替わっています。","w":"監督指針Ⅱ－2－10。","r":[["貸金業法","12の6"]]}}},"12-21":{"s":"返済能力の調査（第13条）の範囲です。適切でないのは②です。","items":{"1":{"t":true,"w":"第13条第1項。","r":[["貸金業法","13"]]},"2":{"t":false,"p":"法人の保証人となろうとする者についても、返済能力の調査は「必要」です（信用情報の使用義務がないだけです）。","w":"第13条第1項（顧客等には保証人となろうとする者を含み、貸付けの契約には保証契約を含みます。第2条第3項・第4項）。","r":[["貸金業法","13"],["貸金業法","2"]]},"3":{"t":true,"w":"施行規則第10条の16第1号。","r":[["貸金業法施行規則","10の16"]]},"4":{"t":true,"w":"第13条第2項。","r":[["貸金業法","13"]]}}},"12-22":{"s":"総量規制の例外契約（施行規則第10条の23）に当たらないものを選ぶ問題です。該当しないのは④です。","items":{"1":{"t":true,"w":"施行規則第10条の23第1項第4号イ・ロ。","r":[["貸金業法施行規則","10の23"]]},"2":{"t":true,"w":"施行規則第10条の23第1項第5号。","r":[["貸金業法施行規則","10の23"]]},"3":{"t":true,"w":"施行規則第10条の23第1項第6号。","r":[["貸金業法施行規則","10の23"]]},"4":{"t":false,"p":"特定緊急貸付契約は、返済期間「3か月」以内、合算額「10万円」以下が要件です。返済期間1年では「該当しません」。","w":"施行規則第10条の23第1項第2号の2ロ・ハ。","r":[["貸金業法施行規則","10の23"]]}}},"12-23":{"s":"極度方式基本契約の書面と個別契約の書面の記載事項を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"「返済の方式」は法律が直接定める記載事項（第17条第1項第5号）で、基本契約の書面に記載されていても、個別契約の書面で省略「できません」。","w":"第17条第1項第5号。省略・代替が認められているのは、施行規則第13条第1項第1号で個別に定めた事項（利息の計算の方法など）です。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"2":{"t":true,"w":"施行規則第13条第1項第1号ロかっこ書。","r":[["貸金業法施行規則","13"]]},"3":{"t":true,"w":"第17条第1項第7号。","r":[["貸金業法","17"]]},"4":{"t":true,"w":"施行規則第13条第3項第1号リ。","r":[["貸金業法施行規則","13"]]}}},"12-24":{"s":"極度方式基本契約の書面を再交付しなければならない変更（施行規則第13条第4項・第5項）です。適切でないのは③です。","items":{"1":{"t":true,"w":"施行規則第13条第4項第1号ロ（同条第3項第1号チ）。","r":[["貸金業法施行規則","13"]]},"2":{"t":true,"w":"施行規則第13条第5項第2号。","r":[["貸金業法施行規則","13"]]},"3":{"t":false,"p":"元本及び利息以外の金銭に関する事項の変更は、相手方の利益となる変更なら再交付は「不要」です。","w":"施行規則第13条第4項第1号イかっこ書（同条第3項第1号ニ）。","r":[["貸金業法施行規則","13"]]},"4":{"t":true,"w":"基本契約に関し受け取る書面の内容（施行規則第13条第3項第1号ハ）は、同条第4項の重要な事項に挙げられていません。","r":[["貸金業法施行規則","13"]]}}},"12-25":{"s":"登録行政庁による登録の取消しを問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"第24条の6の5第1項第2号・第7条第3号：知事登録の者が2以上の都道府県に営業所を設置したのに、内閣総理大臣の登録を受けずに営業を続けている場合は、登録を取り消さなければなりません。","r":[["貸金業法","24の6の5"],["貸金業法","7"]]},"2":{"t":true,"w":"第24条の6の5第1項第2号・第7条第2号。","r":[["貸金業法","24の6の5"],["貸金業法","7"]]},"3":{"t":false,"p":"登録を取り消すことができるのは、引き続き「3か月」ではなく「6月以上」休止したときです。","w":"第24条の6の6第1項第2号。","r":[["貸金業法","24の6の6"]]},"4":{"t":true,"w":"第24条の6の6第1項第1号。","r":[["貸金業法","24の6の6"]]}}},"12-26":{"s":"出資法の規制（媒介手数料・保証料がある場合の高金利・天引き・高金利）を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"出資法第4条第1項。","r":[["出資法","4"]]},"2":{"t":false,"p":"保証料の契約の後に利息を増加し、保証料と合算して年20%を超えることとなる場合は、増加後の利息が20%以下でも、貸付けを行う者は刑事罰の対象と「なります」。","w":"出資法第5条の3第1項。","r":[["出資法","5の3"]]},"3":{"t":true,"w":"出資法第5条の4第2項。","r":[["出資法","5の4"]]},"4":{"t":true,"w":"出資法第5条第2項（業として年20%を超える利息の契約）。","r":[["出資法","5"]]}}},"12-27":{"s":"みなし利息とその例外を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"利息制限法第6条第2項第3号・施行令第2条第2号：1万円を超える額のATM利用料は220円（消費税等を含む）まで利息とみなされません（記述の108円は範囲内です）。","r":[["利息制限法","6"],["利息制限法施行令","2"]]},"2":{"t":true,"w":"例外は弁済期に弁済できなかったときの「再度の」口座振替の費用だけです（施行令第1条第3号）。通常の口座振替の費用は、第3条により利息とみなされます。","r":[["利息制限法","3"],["利息制限法施行令","1"]]},"3":{"t":false,"p":"重要な事項の変更で法律上必要となった書面の再交付の費用は、債務者の要請による再発行の手数料ではないので、利息と「みなされます」（結論は公式正答によります）。","w":"利息制限法第3条・第6条第1項・施行令第1条第2号（例外は債務者の要請により行う書面の再発行）。","r":[["利息制限法","3"],["利息制限法","6"],["利息制限法施行令","1"]]},"4":{"t":true,"w":"例外はカードの「再発行」の手数料だけで、最初のカードの発行費用は利息とみなされます（第3条・施行令第1条第1号）。","r":[["利息制限法","3"],["利息制限法施行令","1"]]}}},"12-28":{"s":"行為能力を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"単に権利を得る法律行為には、法定代理人の同意は「不要」です。","w":"民法第5条第1項ただし書。","r":[["民法","5"]]},"2":{"t":false,"p":"日用品の購入その他日常生活に関する行為は、成年被後見人がしても取り消すことが「できません」。","w":"民法第9条ただし書。","r":[["民法","9"]]},"3":{"t":true,"w":"民法第13条第1項第1号。","r":[["民法","13"]]},"4":{"t":false,"p":"行為能力者となった本人が期間内に確答しないときは、「取り消した」ではなく「追認した」ものとみなされます。","w":"民法第20条第1項。","r":[["民法","20"]]}}},"12-29":{"s":"無権代理（相手方が代理権のないことを知っていた場合）を問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"民法第114条：催告は相手方が悪意（代理権がないことを知っていた）でもでき、本人が期間内に確答しないときは追認を拒絶したものとみなされます。","r":[["民法","114"]]},"2":{"t":false,"p":"無権代理の契約は、本人が「追認しなければ」本人に対して効力を生じません。追認拒絶までは有効、ではありません。","w":"民法第113条第1項。","r":[["民法","113"]]},"3":{"t":false,"p":"契約の時に代理権がないことを知っていた相手方Ｃは、取り消すことが「できません」。","w":"民法第115条ただし書。","r":[["民法","115"]]},"4":{"t":false,"p":"本人の追認を得たときは、無権代理人は履行又は損害賠償の責任を「負いません」（相手方が悪意の場合も責任を負いません）。","w":"民法第117条第1項・第2項第1号。","r":[["民法","117"]]}}},"12-30":{"s":"消滅時効（時効の利益の放棄・援用・催告・効力）を問う問題です。公式正答（基準日2017年4月1日）では③が適切とされています。③は、2020年4月施行の民法改正で制度が改められています。","law":"③は、改正前の「時効の中断」を前提にした記述です。現行の民法第150条では、催告があったときは、その時から6箇月を経過するまでの間は時効は完成しない（完成猶予）とされ、「時効の中断」という制度はなくなっています。","items":{"1":{"t":false,"p":"時効の利益は、あらかじめ放棄することが「できません」。","w":"民法第146条。","r":[["民法","146"]]},"2":{"t":false,"p":"時効は、当事者が「援用」しなければ、裁判所はこれによって裁判をすることが「できません」。","w":"民法第145条。","r":[["民法","145"]]},"3":{"t":true,"now":false,"w":"公式正答（基準日当時の民法）では適切とされています。現行の民法第150条第1項では、催告の時から6箇月を経過するまでの間は時効が完成しない（完成猶予）とされ、記述のような「時効の中断」の仕組みではなくなっています。","r":[["民法","150"]]},"4":{"t":false,"p":"時効の効力は、判決確定の時ではなく、その「起算日にさかのぼって」生じます。","w":"民法第144条。","r":[["民法","144"]]}}},"12-31":{"s":"質権と抵当権を問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"民法第346条。","r":[["民法","346"]]},"2":{"t":false,"p":"質権の設定は、債権者に目的物を「引き渡す」ことによって効力を生じます（要物契約）。","w":"民法第344条。","r":[["民法","344"]]},"3":{"t":false,"p":"抵当権の順位は、契約の締結日ではなく「登記の前後」によります。","w":"民法第373条。","r":[["民法","373"]]},"4":{"t":false,"p":"利息などの定期金について抵当権を行使できるのは、「最後の3年分」ではなく「最後の2年分」です。","w":"民法第375条第1項。","r":[["民法","375"]]}}},"12-32":{"s":"債務不履行の損害賠償（範囲・過失相殺・賠償額の予定・金銭債務）を問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"民法第416条。公式正答（基準日当時の民法）では適切とされています。現行の第416条第2項は、特別の事情によって生じた損害について「当事者がその事情を予見すべきであったとき」は賠償を請求できる、と定めています。","r":[["民法","416"]]},"2":{"t":false,"p":"債権者に過失があったときは、裁判所はこれを考慮して損害賠償の責任と額を「定めます」（過失相殺）。","w":"民法第418条。","r":[["民法","418"]]},"3":{"t":false,"p":"賠償額を予定した場合に、実際の損害額の証明によって裁判所が予定額を増減することはできない、とされています（公式正答による）。","w":"民法第420条（賠償額の予定）。現行の条文には増減の可否についての文言はなく、結論は公式正答によります。","r":[["民法","420"]]},"4":{"t":false,"p":"約定利率と法定利率の「低い方」ではありません。法定利率によるのが原則で、約定利率が法定利率を超えるときは「約定利率」によります。","w":"民法第419条第1項。","r":[["民法","419"]]}}},"12-33":{"s":"保証（成立・範囲・付従性・根保証）を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"保証契約は、口頭の合意では効力を生じず、「書面」（又は電磁的記録）でしなければなりません。","w":"民法第446条第2項・第3項。","r":[["民法","446"]]},"2":{"t":true,"w":"民法第447条第1項。","r":[["民法","447"]]},"3":{"t":false,"p":"保証人の負担が主たる債務より重いときは、主たる債務の限度に「減縮されます」。","w":"民法第448条第1項。","r":[["民法","448"]]},"4":{"t":false,"p":"保証人が「法人」のものではなく、保証人が「法人でない」（個人の）ものです。","w":"民法第465条の2第1項（個人根保証契約）・第465条の3（個人貸金等根保証契約）。","r":[["民法","465の2"],["民法","465の3"]]}}},"12-34":{"s":"相殺の方法・要件・差押えとの関係を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"相殺の意思表示には、条件又は期限を付けることが「できません」。","w":"民法第506条第1項。","r":[["民法","506"]]},"2":{"t":false,"p":"履行地が異なっていても相殺「できます」。","w":"民法第507条。","r":[["民法","507"]]},"3":{"t":false,"p":"時効消滅前に相殺適状になっていれば、時効消滅後も相殺「できます」。","w":"民法第508条。","r":[["民法","508"]]},"4":{"t":true,"w":"民法第511条第1項。","r":[["民法","511"]]}}},"12-35":{"s":"不当利得と不法行為を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"利息を付して返還する義務があるのは「悪意」の受益者です。事実を知らなかった（善意の）受益者は、利益の存する限度で返還すれば足ります。","w":"民法第703条・第704条。","r":[["民法","703"],["民法","704"]]},"2":{"t":true,"w":"民法第706条。","r":[["民法","706"]]},"3":{"t":false,"p":"注文者は、請負人が第三者に加えた損害について、注文又は指図に過失がなければ責任を「負いません」。","w":"民法第716条。","r":[["民法","716"]]},"4":{"t":false,"p":"不法行為の損害賠償請求権の消滅時効は、損害及び加害者を知った時から「1年」ではなく「3年」（人の生命・身体の侵害は5年）です。","w":"民法第724条第1号・第724条の2。","r":[["民法","724"],["民法","724の2"]]}}},"12-36":{"s":"犯罪収益移転防止法（事業内容の確認・実質的支配者・厳格な顧客管理・確認記録）を問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"犯罪収益移転防止法施行規則第10条第1項第2号ロ。","r":[["犯罪収益移転防止法施行規則","10"]]},"2":{"t":false,"p":"株式会社の実質的支配者は、議決権の「5分の1」ではなく「4分の1」を超える議決権を直接又は間接に有する自然人です。","w":"犯罪収益移転防止法施行規則第11条第2項第1号。","r":[["犯罪収益移転防止法施行規則","11"]]},"3":{"t":false,"p":"取引時確認の事項を偽っていた疑いがある顧客等との取引も、厳格な顧客管理が必要な取引に「該当します」。","w":"犯罪収益移転防止法施行令第12条第1項第1号（なりすましの疑い）・第2号（偽りの疑い）。","r":[["犯罪収益移転防止法施行令","12"]]},"4":{"t":false,"p":"確認記録は「遅滞なく」ではなく「直ちに」作成し、保存期間は「確認を行った日から10年間」ではなく「契約が終了した日などから7年間」です。","w":"犯罪収益移転防止法第6条第1項・第2項。","r":[["犯罪収益移転防止法","6"]]}}},"12-37":{"s":"無効と取消しを問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"無効と知って追認すると、初めから有効になるのではなく、「新たな行為をしたもの」とみなされます。","w":"民法第119条。","r":[["民法","119"]]},"2":{"t":true,"w":"民法第120条第1項。","r":[["民法","120"]]},"3":{"t":true,"w":"民法第121条。","r":[["民法","121"]]},"4":{"t":true,"w":"公式正答では適切とされています。現行の民法第124条第1項では、追認は、取消しの原因となっていた状況が消滅し、かつ、取消権を有することを知った後にしなければ効力を生じないと定めています。","r":[["民法","124"]]}}},"12-38":{"s":"債権譲渡の対抗要件と二重譲渡を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"民法第467条第1項：債務者の承諾があれば、債務者に対抗できます。","r":[["民法","467"]]},"2":{"t":true,"w":"民法第467条第2項：確定日付のある通知を受けたＤが優先します。","r":[["民法","467"]]},"3":{"t":true,"w":"民法第467条第2項：Ｃへの承諾に確定日付がないので、確定日付のある通知を受けたＤが優先します。","r":[["民法","467"]]},"4":{"t":false,"p":"どちらも確定日付のある通知の場合、優劣は確定日付の先後ではなく、通知が債務者に「到達した先後」で決まります。先に到達したＣが優先します。","w":"到達の先後で決まることは判例の考え方です（条文には直接書かれていません）。","r":[["民法","467"]]}}},"12-39":{"s":"弁済（第三者弁済・弁済による代位・債権証書の交付・受取証書の持参人）を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"公式正答では適切とされています。現行の民法第474条では「正当な利益を有する者でない第三者」は債務者の意思に反して弁済できないと定め（第2項）、債務の性質や当事者の禁止・制限の意思表示があるときの例外は第4項に定められています。","r":[["民法","474"]]},"2":{"t":false,"p":"弁済をするについて正当な利益を有する者は、債権者の承諾がなくても「当然に」債権者に代位します（法定代位）。","w":"民法第499条・第500条かっこ書（正当な利益を有する者の代位には、債権譲渡の対抗要件の規定も準用されません）。","r":[["民法","499"],["民法","500"]]},"3":{"t":true,"w":"民法第503条第1項。","r":[["民法","503"]]},"4":{"t":true,"w":"公式正答では適切とされています。現行の民法には、受取証書の持参人についての独立した規定はなく、受領権者としての外観を有する者に対する弁済（第478条：弁済者が善意かつ無過失なら有効）として扱われます。","r":[["民法","478"]]}}},"12-40":{"s":"典型契約の成立要件を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"民法第587条。","r":[["民法","587"]]},"2":{"t":true,"w":"民法第601条。","r":[["民法","601"]]},"3":{"t":false,"p":"受任者は、特約がなければ委任者に報酬を請求「できません」（委任は無償が原則です）。","w":"民法第648条第1項。","r":[["民法","648"]]},"4":{"t":true,"w":"民法第632条。","r":[["民法","632"]]}}},"12-41":{"s":"相続を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"民法第898条。","r":[["民法","898"]]},"2":{"t":true,"w":"民法第920条。","r":[["民法","920"]]},"3":{"t":true,"w":"民法第900条第2号。","r":[["民法","900"]]},"4":{"t":false,"p":"欠格で相続人になれなくなった子の子は、代襲相続人に「なれます」。","w":"民法第887条第2項（代襲原因は死亡・欠格・廃除）。","r":[["民法","887"]]}}},"12-42":{"s":"約束手形（白地手形の不当補充・記載事項）と電子記録債権を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"合意と異なる補充がされたことを知って取得した所持人には、不当補充を対抗「できます」（悪意又は重大な過失による取得の場合）。","w":"手形法第10条ただし書（第77条第2項で約束手形に準用）：所持人が悪意又は重大な過失によって手形を取得したときは、不当補充を対抗できます。","r":[["手形法","10"],["手形法","77"]]},"2":{"t":true,"w":"手形法第75条。","r":[["手形法","75"]]},"3":{"t":true,"w":"電子記録債権法第17条。","r":[["電子記録債権法","17"]]},"4":{"t":true,"w":"電子記録債権法第21条。","r":[["電子記録債権法","21"]]}}},"12-43":{"s":"金融分野ガイドライン第8条の安全管理措置（組織的・人的・物理的・技術的）の分類を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"書店で購入できる名簿で全く加工していないものは、個人の権利利益を侵害するおそれが低いので、細断せずに廃棄しても、直ちに安全管理措置の義務違反とは「なりません」。","w":"金融分野ガイドライン第8条第1項（リスクに応じた措置の例）。"},"2":{"t":false,"p":"従業者による個人データ管理手続の遵守状況の確認は、組織的ではなく「人的」安全管理措置です。","w":"金融分野ガイドライン第8条（人的安全管理措置④）。"},"3":{"t":true,"w":"金融分野ガイドライン第8条（技術的安全管理措置⑥）。"},"4":{"t":false,"p":"個人データの取扱状況を確認できる手段の整備は、人的ではなく「組織的」安全管理措置です。","w":"金融分野ガイドライン第8条（組織的安全管理措置④）。"}}},"12-44":{"s":"景品表示法（事業者の定義・協定・不実証広告・指定の手続）を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"事業者の利益のためにする行為を行う役員・従業員などは、事業者団体の定義（第2条第2項）と協定・規約（第36条）の規定の適用については、事業者と「みなされます」。","w":"景品表示法第2条第1項後段。","r":[["景品表示法","2"]]},"2":{"t":false,"p":"協定・規約は、内閣総理大臣と消費者委員会に「届け出る」のではなく、内閣総理大臣及び「公正取引委員会」の「認定」を受けて締結・設定します。","w":"景品表示法第36条第1項。","r":[["景品表示法","36"]]},"3":{"t":false,"p":"資料を提出しないと不当表示とみなされるのは、有利誤認表示（第5条第2号）ではなく「優良誤認表示」（第5条第1号）です。","w":"景品表示法第7条第2項。","r":[["景品表示法","7"],["景品表示法","5"]]},"4":{"t":true,"w":"景品表示法第3条第1項。","r":[["景品表示法","3"]]}}},"12-45":{"s":"日本貸金業協会の紛争解決等業務に関する規則を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"記述は「貸金業務等関連苦情」ではなく「貸金業務関連紛争」の定義です。貸金業務等関連苦情は、貸金業務等に関する契約者等の「不満足の表明」です。","w":"紛争解決等業務に関する規則（定義）第1号・第2号。"},"2":{"t":false,"p":"法人でない社団・財団でも、代表者又は管理者の定めがあるもの（権利能力なき社団等）は、申立てが「できます」。","w":"紛争解決等業務に関する規則第37条。"},"3":{"t":true,"w":"紛争解決等業務に関する規則第50条第2項。"},"4":{"t":false,"p":"苦情処理手続・紛争解決手続は、公開ではなく「非公開」です。","w":"紛争解決等業務に関する規則第53条（苦情処理手続はすべて非公開）・第94条（紛争解決手続は公開しない）。"}}},"12-46":{"s":"消費者契約法の定義・取消し・不当条項・他の法律との関係を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"消費者契約法第2条第2項・第3項。","r":[["消費者契約法","2"]]},"2":{"t":false,"p":"不実告知で誤認して締結した契約は、当然に無効になるのではなく、消費者が「取り消す」ことができます。","w":"消費者契約法第4条第1項第1号。","r":[["消費者契約法","4"]]},"3":{"t":true,"w":"消費者契約法第8条第1項第1号。","r":[["消費者契約法","8"]]},"4":{"t":true,"w":"消費者契約法第11条第1項・第2項。","r":[["消費者契約法","11"]]}}},"12-47":{"s":"協会の自主規制基本規則（勧誘に関する規則）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"勧誘リストに信用情報を記載することは、信用情報の目的外使用として「禁止」されています。","w":"自主規制基本規則第39条の3第2項第1号。","r":[["貸金業法","41の38"]]},"2":{"t":true,"w":"自主規制基本規則第55条第1項第2号。"},"3":{"t":true,"w":"自主規制基本規則第54条第1項第1号。"},"4":{"t":true,"w":"自主規制基本規則第54条第1項第2号・第2項。"}}},"12-48":{"s":"損益計算書の段階利益を問う問題です。会社計算規則は取り込んでいないため、同じ考え方を定めた企業会計原則の損益計算書原則で確認します。正しいのは②です。","items":{"1":{"t":false,"p":"売上高−売上原価は「当期販売利益」ではなく「売上総利益」です。","w":"企業会計原則・損益計算書原則（売上総利益）。"},"2":{"t":true,"w":"企業会計原則・損益計算書原則三：売上総利益から販売費及び一般管理費を控除して営業利益を表示します。"},"3":{"t":false,"p":"経常利益は、営業損益に「特別利益・特別損失」ではなく「営業外収益・営業外費用」を加減したものです。","w":"企業会計原則・損益計算書原則五。"},"4":{"t":false,"p":"税引前当期純利益は、経常損益に「営業外収益・費用」ではなく「特別利益・特別損失」を加減したものです。","w":"企業会計原則・損益計算書原則七。"}}},"12-49":{"s":"企業会計原則の一般原則を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"真実性の原則は、企業の財政状態及び経営成績に関して「真実な報告を提供する」ことを求める原則です。重要性の乏しいものまで厳密な処理を求めるものではありません。","w":"企業会計原則・一般原則一。"},"2":{"t":true,"w":"企業会計原則・一般原則六。"},"3":{"t":true,"w":"企業会計原則・一般原則五。"},"4":{"t":true,"w":"企業会計原則・一般原則七。"}}},"12-50":{"s":"貸借対照表の区分と科目の分類です。会社計算規則は取り込んでいないため、企業会計原則の貸借対照表原則で確認できる範囲で説明します。適切でないのは④です。","items":{"1":{"t":true,"w":"企業会計原則・貸借対照表原則二。"},"2":{"t":true,"w":"結論は公式正答によります（未収収益が流動資産に属すること）。"},"3":{"t":true,"w":"企業会計原則・貸借対照表原則四㈡Ｂ。"},"4":{"t":false,"p":"「社債」は純資産ではなく「負債」（固定負債）の項目です。純資産の部は、株主資本・評価・換算差額等・株式引受権・新株予約権に区分します（第19回問50④の公式正答による）。","w":"企業会計原則・貸借対照表原則四㈡Ｂ（社債は固定負債）。"}}},"13-01":{"s":"貸金業法第2条の用語の定義です。適切なのはｂとｃです（2個）。","items":{"a":{"t":false,"p":"信用情報は「顧客又は債務者の借入金の返済能力に関する情報」で、保証人の保証能力に関する情報は「含まれません」。","w":"第2条第13項。","r":[["貸金業法","2"]]},"b":{"t":true,"w":"第2条第14項。","r":[["貸金業法","2"]]},"c":{"t":true,"w":"第2条第9項。","r":[["貸金業法","2"]]},"d":{"t":false,"p":"手続実施基本契約は、三者間ではなく、「指定紛争解決機関と貸金業者との間」で締結される契約です。","w":"第2条第23項。","r":[["貸金業法","2"]]}}},"13-02":{"s":"登録の拒否事由（第6条第1項）に当たるものを数える問題です。当たるのはｃだけです（1個）。","items":{"a":{"t":false,"p":"拒否事由は「復権を得ない者」で、復権を得ていれば5年以内でも「該当しません」。","w":"第6条第1項第2号・第9号ロ。","r":[["貸金業法","6"]]},"b":{"t":false,"p":"刑の全部の執行猶予の期間を取り消されることなく経過すると、刑の言渡しは効力を失うので、拒否事由に「該当しません」。","w":"刑法第27条第1項。","r":[["刑法","27"],["貸金業法","6"]]},"c":{"t":true,"w":"第6条第1項第4号・第9号ロ（どの法律の違反でも、拘禁刑（旧懲役）以上の刑で執行を終わった日から5年を経過しない者）。","r":[["貸金業法","6"]]},"d":{"t":false,"p":"取消しの日前「30日以内」に役員であった者が対象です。50日前に退任した者は「該当しません」。","w":"第6条第1項第3号かっこ書。","r":[["貸金業法","6"]]}}},"13-03":{"s":"廃業等の届出（第10条）を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"届け出るのは存続法人の役員ではなく、「消滅した法人を代表する役員であった者」です。","w":"第10条第1項第2号。","r":[["貸金業法","10"]]},"2":{"t":false,"p":"破産手続開始の決定があった場合に届け出るのは、本人ではなく「破産管財人」です。","w":"第10条第1項第3号。","r":[["貸金業法","10"]]},"3":{"t":false,"p":"登録は、届出の有無にかかわらず、廃止した時点で効力を「失います」。","w":"第10条第2項。","r":[["貸金業法","10"]]},"4":{"t":true,"w":"第10条第3項。","r":[["貸金業法","10"]]}}},"13-04":{"s":"監督指針Ⅱ－2－4（システムリスク管理態勢）の着眼点です。合致するのはｂとｄです。","items":{"a":{"t":false,"p":"「サイバーセキュリティ事案」は、サイバー空間を経由して行われるサイバー攻撃により、サイバーセキュリティが脅かされる事案です。データセンター建屋への不正侵入など、サイバー空間を経由しない行為は「含まれていません」。","w":"監督指針Ⅱ－2－4（注）。"},"b":{"t":true,"w":"結論は公式正答によります（現行の監督指針（令和8年10月版）には、記述のとおりの文言は見当たらず、「金融分野におけるサイバーセキュリティに関するガイドライン」を参照するよう定めています）。"},"c":{"t":false,"p":"コンティンジェンシープラン（緊急時対応計画）は、他の貸金業者におけるシステム障害等の事例も「踏まえて」想定シナリオを見直します。","w":"監督指針Ⅱ－2－4－1：他の貸金業者におけるシステム障害等の事例や中央防災会議等の検討結果を踏まえるなど、想定シナリオの見直しを適宜行っているか。"},"d":{"t":true,"w":"監督指針Ⅱ－2－4－1（外部委託管理）ロのとおりです。"}}},"13-05":{"s":"貸金業務取扱主任者の設置数・登録簿・欠けたとき・登録拒否の期間を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"数えるのは貸金業の業務に従事する50人なので、必要な主任者は「2人以上」ではなく「1人以上」です。","w":"施行規則第10条の8（50分の1以上）。","r":[["貸金業法施行規則","10の8"]]},"2":{"t":true,"w":"第24条の25第4項・施行規則第26条の51第1項。","r":[["貸金業法","24の25"],["貸金業法施行規則","26の51"]]},"3":{"t":false,"p":"定年退職は予見できるので、2週間の猶予は「ありません」。","w":"第12条の3第3項（予見し難い事由の場合のみ）・監督指針Ⅱ－2－9（2）③。","r":[["貸金業法","12の3"]]},"4":{"t":false,"p":"登録を受けられない期間は「3年」ではなく、処分の日から「5年」です。","w":"第24条の27第1項第7号・第24条の30第2号。","r":[["貸金業法","24の27"],["貸金業法","24の30"]]}}},"13-06":{"s":"監督指針Ⅱ－2－10で、第12条の6第4号の「偽りその他不正又は著しく不当な行為」に当たるおそれが大きいとされる、契約の締結・変更時の行為です。4つとも該当します（4個）。","items":{"a":{"t":true,"w":"監督指針Ⅱ－2－10のイｄ。","r":[["貸金業法","12の6"]]},"b":{"t":true,"w":"監督指針Ⅱ－2－10のイｆ。","r":[["貸金業法","12の6"]]},"c":{"t":true,"w":"監督指針Ⅱ－2－10のイａ。","r":[["貸金業法","12の6"]]},"d":{"t":true,"w":"監督指針Ⅱ－2－10のイｅ。","r":[["貸金業法","12の6"]]}}},"13-07":{"s":"極度方式基本契約の極度額を増額するときの返済能力の調査（第13条第5項）を問う問題です。適切なのはａとｂです。","items":{"a":{"t":true,"w":"第13条第5項で第2項（信用情報の使用）が準用されます。","r":[["貸金業法","13"]]},"b":{"t":true,"w":"施行規則第10条の19。","r":[["貸金業法施行規則","10の19"]]},"c":{"t":false,"p":"返済能力の低下を理由に減額した極度額を戻す場合は、調査が「必要」です。","w":"第13条第5項・施行規則第10条の19（例外は、連絡が取れないため一時的に減額した場合に限られます）。","r":[["貸金業法","13"],["貸金業法施行規則","10の19"]]},"d":{"t":false,"p":"極度額を下回る提示額を増額する場合も、極度額の増額として調査が「必要」です。","w":"第13条第5項かっこ書。","r":[["貸金業法","13"]]}}},"13-08":{"s":"総量規制の例外契約（施行規則第10条の23）に当たるものを選ぶ問題です。該当するのは③です。","items":{"1":{"t":false,"p":"特定緊急貸付契約は、合算額「10万円」以下・返済期間「3か月」以内が要件です。","w":"施行規則第10条の23第1項第2号の2。","r":[["貸金業法施行規則","10の23"]]},"2":{"t":false,"p":"事業実態の確認と、返済能力を超えないことの「両方」が必要です。「いずれか」ではありません。","w":"施行規則第10条の23第1項第4号。","r":[["貸金業法施行規則","10の23"]]},"3":{"t":true,"w":"施行規則第10条の23第1項第6号。","r":[["貸金業法施行規則","10の23"]]},"4":{"t":false,"p":"借換えの例外契約は、1か月の負担が既存債務を「上回らない」ことが必要です。上回るものは該当しません。","w":"施行規則第10条の23第1項第1号イ。","r":[["貸金業法施行規則","10の23"]]}}},"13-09":{"s":"極度方式基本契約の3か月ごとの定期調査（第13条の3第2項）が不要になる場合です。正しいのは③です。","items":{"1":{"t":false,"p":"他の契約の残高にかかわらず調査が必要になるのではありません。他の極度方式基本契約の残高も合算した合計額が10万円以下であれば、調査は「不要」です。","w":"施行規則第10条の25第3項第1号。","r":[["貸金業法施行規則","10の25"]]},"2":{"t":false,"p":"極度額の「減額」の措置では、定期調査は免除「されません」。","w":"施行規則第10条の25第3項第2号（第10条の29第2号の停止の措置の場合だけ）。","r":[["貸金業法施行規則","10の25"],["貸金業法施行規則","10の29"]]},"3":{"t":true,"w":"施行規則第10条の25第3項第2号・第10条の29第2号。","r":[["貸金業法施行規則","10の25"],["貸金業法施行規則","10の29"]]},"4":{"t":false,"p":"信用情報の提供依頼の期限は「1か月」ではなく、期間の末日から「3週間」を経過する日までです。","w":"施行規則第10条の25第2項。","r":[["貸金業法施行規則","10の25"]]}}},"13-10":{"s":"極度方式基本契約の書面と個別契約の書面の記載事項を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"各回の返済期日及び返済金額は、省略ではなく、「次回の返済期日及び返済金額」で代えることができるだけです（利率や返済方法の記載とは関係ありません）。","w":"施行規則第13条第1項第1号チかっこ書。","r":[["貸金業法施行規則","13"]]},"2":{"t":false,"p":"返済回数の記載を省略できるという定めは「ありません」。","w":"第17条第1項第6号（返済期間及び返済回数）。","r":[["貸金業法","17"]]},"3":{"t":true,"w":"施行規則第13条第3項第1号ヲ。","r":[["貸金業法施行規則","13"]]},"4":{"t":false,"p":"基本契約の書面に記載するのは「極度方式基本契約に関し貸金業者が受け取る書面の内容」で、個別契約に関し受け取る書面の内容は「含まれません」（それは個別契約の書面の記載事項です）。","w":"施行規則第13条第3項第1号ハ・同条第1項第1号ハ。","r":[["貸金業法施行規則","13"]]}}},"13-11":{"s":"保証人・保証人となろうとする者への書面の交付方法を問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"第16条の2第3項・施行規則第12条の2（現行では第7項）。","r":[["貸金業法","16の2"],["貸金業法施行規則","12の2"]]},"2":{"t":false,"p":"文字の大きさは「10ポイント以上」ではなく「8ポイント以上」です。","w":"施行規則第13条第15項。","r":[["貸金業法施行規則","13"]]},"3":{"t":false,"p":"保証の対象となる貸付けの契約が2以上あるときは、契約「ごとに」記載しなければなりません。","w":"施行規則第13条第8項。","r":[["貸金業法施行規則","13"]]},"4":{"t":false,"p":"極度方式保証契約の保証人にも、マンスリーステートメントによる方法を使うことが「できます」。","w":"第17条第6項：相手方「又は」極度方式保証契約の保証人に対し、承諾を得てマンスリーステートメントを交付するときは、簡素な書面に代えることができます。","r":[["貸金業法","17"]]}}},"13-12":{"s":"貸金業者が保存すべきものの保存期間です。適切なのはｂとｄです。","items":{"a":{"t":false,"p":"帳簿の保存期間の起算点は「契約を締結した日」ではなく、「最終の返済期日（債権が消滅したときはその日）」です。","w":"施行規則第17条第1項。","r":[["貸金業法施行規則","17"]]},"b":{"t":true,"w":"施行規則第10条の21第2項。","r":[["貸金業法施行規則","10の21"]]},"c":{"t":false,"p":"途中の調査の記録の保存期間は「10年間」ではなく、作成後「3年間」です。","w":"施行規則第10条の27第2項。","r":[["貸金業法施行規則","10の27"]]},"d":{"t":true,"w":"施行規則第10条の9の2第3項。","r":[["貸金業法施行規則","10の9の2"]]}}},"13-13":{"s":"監督指針Ⅱ－2－19（取立行為規制）の記述です。合致するのはｃだけです（1個）。","items":{"a":{"t":false,"p":"「債務者等と連絡をとるための合理的方法が他にない場合」も、正当な理由に該当する可能性が高いとされています。","w":"監督指針Ⅱ－2－19（2）②イ：自発的な承諾がある場合と、連絡をとるための合理的方法が他にない場合の両方が例示されています。","r":[["貸金業法","21"]]},"b":{"t":false,"p":"「具体的な期日の申出がない場合」も、正当な理由に該当する可能性が高いとされています。","w":"監督指針Ⅱ－2－19（2）③イ・ロ。","r":[["貸金業法","21"]]},"c":{"t":true,"w":"監督指針Ⅱ－2－19（2）④のとおりです。","r":[["貸金業法","21"]]},"d":{"t":false,"p":"保証契約に基づく求償権の取立てにも、第21条が「適用され得る」とされています。","w":"監督指針Ⅱ－2－19（2）⑧。","r":[["貸金業法","21"]]}}},"13-14":{"s":"開始等の届出（第24条の6の2）の事由です。届出事由は、開始と終了（加入と脱退など）の両方を含みます。正しいのは①です。","items":{"1":{"t":true,"w":"施行規則第26条の25第1項第3号・第2項。","r":[["貸金業法施行規則","26の25"]]},"2":{"t":false,"p":"信用情報提供契約を「終了した」場合も届出が「必要」です。","w":"第24条の6の2第2号。","r":[["貸金業法","24の6の2"]]},"3":{"t":false,"p":"業務の委託を「行わなくなった」場合も届出が「必要」です。","w":"施行規則第26条の25第1項第6号。","r":[["貸金業法施行規則","26の25"]]},"4":{"t":false,"p":"貸金業協会を「脱退した」場合も届出が「必要」です。","w":"施行規則第26条の25第1項第7号。","r":[["貸金業法施行規則","26の25"]]}}},"13-15":{"s":"個人信用情報の提供（第41条の35）と同意（第41条の36）を問う問題です。適切なのはａとｃです。","items":{"a":{"t":true,"w":"第41条の35第2項。","r":[["貸金業法","41の35"]]},"b":{"t":false,"p":"「元本又は利息の支払の遅延の有無」も、個人信用情報に「含まれます」。","w":"第41条の35第1項第4号・施行規則第30条の13第2項第2号。","r":[["貸金業法","41の35"],["貸金業法施行規則","30の13"]]},"c":{"t":true,"w":"第41条の36第1項。","r":[["貸金業法","41の36"]]},"d":{"t":false,"p":"同意の記録の保存期間は「提供した日から10年間」ではなく、「その同意に基づき指定信用情報機関が信用情報を保有している間」です。","w":"施行規則第30条の16第1項。","r":[["貸金業法施行規則","30の16"]]}}},"13-16":{"s":"みなし利息とその例外（利息制限法第3条・第6条）です。4つとも適切です（4個）。","items":{"a":{"t":true,"w":"例外はカードの「再発行」手数料だけで、最初の発行手数料は利息とみなされます（第3条・第6条第1項・施行令第1条第1号）。","r":[["利息制限法","3"],["利息制限法","6"],["利息制限法施行令","1"]]},"b":{"t":true,"w":"例外は弁済期に弁済できなかったときの「再度の」口座振替の費用だけで、通常の口座振替手続の費用は利息とみなされます（第3条・施行令第1条第3号）。","r":[["利息制限法","3"],["利息制限法施行令","1"]]},"c":{"t":true,"w":"第6条第1項・施行令第1条第2号。","r":[["利息制限法","6"],["利息制限法施行令","1"]]},"d":{"t":true,"w":"第6条第2項第2号。","r":[["利息制限法","6"]]}}},"13-17":{"s":"変更の届出（第8条）の対象と期限を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"主任者の登録の更新では、届出事項（第4条第1項第6号の氏名・登録番号）は変わらないので、届出は不要です。","r":[["貸金業法","8"],["貸金業法","4"]]},"2":{"t":true,"w":"第4条第1項第2号の「政令で定める使用人」（施行令第3条・施行規則第3条第1項第3号）の変更で、2週間以内に届け出ます。","r":[["貸金業法","8"],["貸金業法施行令","3"],["貸金業法施行規則","3"]]},"3":{"t":true,"w":"施行規則第3条第1項第2号の使用人の変更で、2週間以内に届け出ます。","r":[["貸金業法","8"],["貸金業法施行規則","3"]]},"4":{"t":false,"p":"他に行う事業の種類の変更は、「あらかじめ」ではなく、変更があった日から「2週間以内」に届け出ます。","w":"第8条第1項・第4条第1項第9号。","r":[["貸金業法","8"],["貸金業法","4"]]}}},"13-18":{"s":"監督指針の経営管理等・業務の適切性の記述です。合致しないのは②です。","items":{"1":{"t":true,"w":"監督指針（経営管理等の着眼点）⑤のとおりです。"},"2":{"t":false,"p":"自己検証の頻度は「年1回以上」ではなく、「少なくとも月1回以上」です。","w":"監督指針（経営管理等・内部監査に代わる措置）ハｃ。"},"3":{"t":true,"w":"監督指針Ⅱ－2（業務の適切性）の冒頭のとおりです。"},"4":{"t":true,"w":"監督指針Ⅱ－2－1の着眼点①のとおりです。"}}},"13-19":{"s":"利息・保証料等の制限（第12条の8）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"第12条の8第10項。","r":[["貸金業法","12の8"]]},"2":{"t":true,"w":"元本100万円の利息制限法の上限は年15%なので、20%の契約は第12条の8第1項違反として行政処分の対象です。出資法の刑事罰は年20%を超える場合なので、20%ちょうどは対象外です。","r":[["貸金業法","12の8"],["利息制限法","1"],["出資法","5"]]},"3":{"t":true,"w":"第12条の8第9項・施行規則第10条の14第2号。","r":[["貸金業法","12の8"],["貸金業法施行規則","10の14"]]},"4":{"t":false,"p":"保証料の確認は、保証契約を締結した後に「遅滞なく」ではなく、締結する「まで」に行います。","w":"第12条の8の保証料の確認義務。","r":[["貸金業法","12の8"]]}}},"13-20":{"s":"返済能力の調査と信用情報の使用義務の範囲です。適切でないのは③です。","items":{"1":{"t":true,"w":"第13条第1項（法人でも調査は必要）。","r":[["貸金業法","13"]]},"2":{"t":true,"w":"施行規則第10条の16第2号・第1条の2の3第5号。","r":[["貸金業法施行規則","10の16"]]},"3":{"t":false,"p":"極度方式貸付けに係る契約は、信用情報の使用義務の対象から「除かれて」います。","w":"施行規則第10条の16第1号。","r":[["貸金業法施行規則","10の16"]]},"4":{"t":true,"w":"第13条第2項（個人である保証人となろうとする者）。","r":[["貸金業法","13"]]}}},"13-21":{"s":"総量規制の除外契約（施行規則第10条の21）に当たらないものを選ぶ問題です。該当しないのは①です。","items":{"1":{"t":false,"p":"金融商品取引業者による保護預り有価証券を担保とする貸付けが除外されるのは、貸付金額が有価証券の「時価の範囲内」のものに限られます。時価500万円に対して800万円の貸付けは「該当しません」。","w":"施行規則第10条の21第1項第8号・第1条の2の3第3号。","r":[["貸金業法施行規則","10の21"],["貸金業法施行規則","1の2の3"]]},"2":{"t":true,"w":"施行規則第10条の21第1項第3号。","r":[["貸金業法施行規則","10の21"]]},"3":{"t":true,"w":"施行規則第10条の21第1項第8号・第1条の2の3第2号。","r":[["貸金業法施行規則","10の21"],["貸金業法施行規則","1の2の3"]]},"4":{"t":true,"w":"施行規則第10条の21第1項第7号。","r":[["貸金業法施行規則","10の21"]]}}},"13-22":{"s":"契約締結前の書面（第16条の2）の対象と記載事項です。適切でないのは③です。","items":{"1":{"t":true,"w":"第16条の2第1項かっこ書。","r":[["貸金業法","16の2"]]},"2":{"t":true,"w":"第16条の2第3項。保証人となろうとする者に交付するのは保証契約の書面です。","r":[["貸金業法","16の2"]]},"3":{"t":false,"p":"「貸金業者が受け取る書面の内容」は、契約締結前の書面の記載事項に「含まれません」（契約締結時の書面の記載事項です）。","w":"施行規則第12条の2第1項第1号に挙げられていません。","r":[["貸金業法施行規則","12の2"]]},"4":{"t":true,"w":"施行規則第12条の2第1項第1号ハ。","r":[["貸金業法施行規則","12の2"]]}}},"13-23":{"s":"契約締結時の書面の再交付が必要な変更（施行規則第13条第2項）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"施行規則第13条第1項第1号ニは、同条第2項第1号イ（利益となる変更は除く）の事項です。","r":[["貸金業法施行規則","13"]]},"2":{"t":true,"w":"施行規則第13条第1項第1号リは、同条第2項第1号イの事項です。","r":[["貸金業法施行規則","13"]]},"3":{"t":true,"w":"施行規則第13条第1項第1号ヘは、同条第2項第1号イの事項です。","r":[["貸金業法施行規則","13"]]},"4":{"t":false,"p":"「返済の方法及び返済を受ける場所」の変更は、利益となる変更でも再交付が「必要」です。","w":"施行規則第13条第2項第1号ロ（同条第1項第1号ト）。","r":[["貸金業法施行規則","13"]]}}},"13-24":{"s":"帳簿（第19条）の記載事項と監督指針の「交渉の経過の記録」を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"施行規則第16条第3項第1号。","r":[["貸金業法施行規則","16"]]},"2":{"t":true,"w":"施行規則第16条第1項第5号。","r":[["貸金業法施行規則","16"]]},"3":{"t":false,"p":"「交渉の経過の記録」は、契約締結前の書面の交付以降ではなく、「貸付けの契約の締結以降」における債権に関する交渉の経過の記録です。","w":"監督指針（帳簿の備付け等の着眼点の注）。","r":[["貸金業法施行規則","16"]]},"4":{"t":true,"w":"施行規則第16条第1項第6号。","r":[["貸金業法施行規則","16"]]}}},"13-25":{"s":"監督指針Ⅱ－2－8（不祥事件）の監督上の対応です。合致しないのは④です。","items":{"1":{"t":true,"w":"監督指針Ⅱ－2－8のとおりです。","r":[["貸金業法施行規則","26の25"]]},"2":{"t":true,"w":"監督指針Ⅱ－2－8（1）①のとおりです。"},"3":{"t":true,"w":"監督指針Ⅱ－2－8（1）②のとおりです。"},"4":{"t":false,"p":"報告書は「必要に応じて」徴収し、業務改善命令は資金需要者等の利益の保護の観点から「重大な問題があると認められるとき」に発出します。届出があれば直ちに発出するのではありません。","w":"監督指針Ⅱ－2－8（2）。","r":[["貸金業法","24の6の10"],["貸金業法","24の6の3"]]}}},"13-26":{"s":"利息制限法（天引き・元本額の特則）の計算問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"利息制限法第2条：受領額8万2,000円を元本とみなすと上限は年2割（10万円未満）で1万6,400円。天引額1万8,000円のうち超過分1,600円は元本の支払に充てたものとみなされます。","r":[["利息制限法","2"],["利息制限法","1"]]},"2":{"t":false,"p":"元本の合算（第5条）は「同一の債権者」から借りた場合のルールです。別の貸主Ｃの貸付けは、Ａからの借入れと合算せず、元本8万円で判断するので、年20%は「全部有効」です。","w":"利息制限法第5条第1号・第1条第1号。","r":[["利息制限法","5"],["利息制限法","1"]]},"3":{"t":true,"w":"利息制限法第5条第1号：残元本5万円＋5万円＝10万円で上限は年18%。","r":[["利息制限法","5"],["利息制限法","1"]]},"4":{"t":true,"w":"利息制限法第5条：残元本55万円＋5万円＋40万円＝100万円で上限は年15%。","r":[["利息制限法","5"],["利息制限法","1"]]}}},"13-27":{"s":"保証料の制限（利息制限法第8条・第9条）を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"利息制限法第8条第1項。","r":[["利息制限法","8"]]},"2":{"t":false,"p":"特約上限利率を定めても主たる債務者Ｂに「通知」していない場合は、通知した場合の計算ではなく、法定上限額の「2分の1」（元本50万円・年18%で9万円の半分の4万5,000円）が保証料の上限です。","w":"利息制限法第8条第2項第1号（定めをし、かつ通知した場合）・第2号（それ以外の場合は法定上限額の2分の1）。","r":[["利息制限法","8"]]},"3":{"t":true,"w":"利息制限法第8条第7項第1号イ。","r":[["利息制限法","8"]]},"4":{"t":true,"w":"利息制限法第9条第1項：元本30万円の法定上限額は年18%で5万4,000円。保証料1万2,000円を引いた4万2,000円（年14%）が上限です。","r":[["利息制限法","9"]]}}},"13-28":{"s":"意思表示（心裡留保・錯誤・強迫・虚偽表示）を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"心裡留保は原則として「有効」で、無効を主張できるのは、相手方Ｂが真意でないことを知り又は知ることができた場合に限られます。","w":"民法第93条第1項。","r":[["民法","93"]]},"2":{"t":false,"p":"動機（法律行為の基礎とした事情）の錯誤は、その事情が法律行為の基礎とされていることが「表示されていた」ときに限り主張できます（現行法では、錯誤の効果は無効ではなく「取消し」です）。","w":"民法第95条第1項第2号・第2項。","r":[["民法","95"]]},"3":{"t":true,"w":"民法第96条第3項（第三者保護は詐欺の場合だけ）。","r":[["民法","96"]]},"4":{"t":false,"p":"虚偽表示の無効は、「善意」の第三者には対抗できません。Ｃが通謀を知らなかった場合は対抗「できない」ので、知っていたか否かに「かかわらず」対抗できるわけではありません。","w":"民法第94条第2項。","r":[["民法","94"]]}}},"13-29":{"s":"無効と取消しを問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"民法第120条第2項。","r":[["民法","120"]]},"2":{"t":false,"p":"追認した後は、取り消すことが「できません」。","w":"民法第122条。","r":[["民法","122"]]},"3":{"t":false,"p":"取消権の期間は「3年・10年」ではなく、追認できる時から「5年」、行為の時から「20年」です。","w":"民法第126条。","r":[["民法","126"]]},"4":{"t":false,"p":"無効な行為は、追認によっても効力を「生じません」（無効と知って追認すれば、新たな行為をしたものとみなされます）。","w":"民法第119条。","r":[["民法","119"]]}}},"13-30":{"s":"取得時効と時効の完成猶予（第13回の時点では「時効の中断」）を問う問題です。公式正答（基準日2018年4月1日）では④が適切とされています。④は、2020年4月施行の民法改正で結論が変わっています。","law":"④について、公式正答では「障害が消滅した時から2週間」が適切とされていますが、現行の民法第161条は「3箇月」を経過するまで時効は完成しないと定めています。また、現行法では「時効の中断」は「完成猶予」と「更新」に改められています。","items":{"1":{"t":false,"p":"10年で所有権を取得するには、占有開始時に善意であることに加えて「過失がなかった」ことが必要です。","w":"民法第162条第2項（善意でも過失があれば20年。同条第1項）。","r":[["民法","162"]]},"2":{"t":false,"p":"催告の後に裁判上の請求などをすべき期間は「3か月」ではなく「6か月」です（現行法では、催告の時から6箇月を経過するまで時効が完成しない「完成猶予」です）。","w":"民法第150条第1項。","r":[["民法","150"]]},"3":{"t":false,"p":"仮差押えは、3か月以内に差押えをしなければ効力を生じない、という制度ではありません（現行法では、仮差押えは事由の終了から6箇月を経過するまでの完成猶予事由です）。","w":"民法第149条第1号。結論は公式正答によります。","r":[["民法","149"]]},"4":{"t":true,"now":false,"w":"公式正答では適切とされています。現行の民法第161条では、障害が消滅した時から「3箇月」を経過するまでの間は時効は完成しません（現行法では記述は適切ではありません）。","r":[["民法","161"]]}}},"13-31":{"s":"債権の効力（履行遅滞・賠償額の予定・詐害行為取消し・債権者代位）を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"不確定期限の場合は、期限が到来しただけでは遅滞にならず、期限到来後に履行の請求を受けた時又は期限の到来を知った時のいずれか早い時から遅滞になります。","w":"民法第412条第2項。","r":[["民法","412"]]},"2":{"t":false,"p":"賠償額を予定しても、解除権の行使は「妨げられません」。","w":"民法第420条第2項。","r":[["民法","420"]]},"3":{"t":true,"w":"詐害行為取消し：民法第424条第1項ただし書（受益者が害することを知らなかったとき）・第424条の5（転得者に対する請求は、転得者が知っていたときに限る）。公式正答では適切とされています。","r":[["民法","424"],["民法","424の5"]]},"4":{"t":false,"p":"債務者の一身に専属する権利は、債権者代位の対象に「なりません」。","w":"民法第423条第1項ただし書。","r":[["民法","423"]]}}},"13-32":{"s":"連帯債務者の1人に生じた事由が他の連帯債務者に影響するかを問う問題です。公式正答（基準日2018年4月1日）では①が適切とされています。④は、2020年4月施行の民法改正で結論が変わっています。","law":"④について、公式正答では「免除は他の連帯債務者に効力を生じない」は適切でないとされています。現行の民法第441条では、更改（第438条）・相殺（第439条第1項）・混同（第440条）以外の事由は他の連帯債務者に効力を生じない（相対的効力）とされ、免除も含まれるので、現行法では④は適切になります。","items":{"1":{"t":true,"w":"民法第440条（現行）。","r":[["民法","440"]]},"2":{"t":false,"p":"更改があったときは、他の連帯債務者の同意がなくても、債権は全ての連帯債務者の利益のために「消滅します」。","w":"民法第438条（現行）。","r":[["民法","438"]]},"3":{"t":false,"p":"1人のために時効が完成しても、他の連帯債務者の債務が「すべて」消滅するわけではありません（現行法では、時効の完成は他の連帯債務者に効力を生じません）。","w":"民法第441条（現行）。結論は公式正答によります。","r":[["民法","441"]]},"4":{"t":false,"now":true,"p":"公式正答（基準日当時の民法）では、免除は他の連帯債務者にも一定の効力を生じるとされています。","w":"現行の民法第441条では、免除は他の連帯債務者に効力を生じません（現行法では記述は適切）。","r":[["民法","441"]]}}},"13-33":{"s":"相殺の禁止と時効消滅後の相殺を問う問題です。Ａから見ると甲債権が自働債権です。公式正答（基準日2018年4月1日）では④が適切とされています。④は、2020年4月施行の民法改正で結論が変わっています。","law":"④は、公式正答では適切とされています。現行の民法第509条で相殺が禁止されるのは、悪意による不法行為に基づく損害賠償の債務と、人の生命又は身体の侵害による損害賠償の債務だけなので、乙債権がこれらに当たらなければＡは相殺でき、現行法では④は適切ではありません。","items":{"1":{"t":false,"p":"差押命令の送達後に取得した債権による相殺は、差押債権者Ｃに対抗「できません」。","w":"民法第511条第1項。","r":[["民法","511"]]},"2":{"t":false,"p":"差押えが禁じられた債権を受働債権として相殺することは「できません」。","w":"民法第510条。","r":[["民法","510"]]},"3":{"t":false,"p":"時効消滅前に相殺適状になっていれば、時効消滅後も相殺「できます」。","w":"民法第508条。","r":[["民法","508"]]},"4":{"t":true,"now":false,"w":"公式正答（基準日当時の民法）では、不法行為に基づく損害賠償債務を負うＡは相殺できないとされています。現行の民法第509条では、乙債権が悪意による不法行為又は人の生命・身体の侵害による損害賠償債権でなければ、Ａは相殺できます。","r":[["民法","509"]]}}},"13-34":{"s":"不当利得（他人の債務の弁済・期限前の弁済・非債弁済・不法原因給付）を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"債権者が善意で証書を滅失させたときは、弁済をした者は返還を請求「できません」（債務者への求償はできます）。","w":"民法第707条。","r":[["民法","707"]]},"2":{"t":false,"p":"弁済期にない債務の弁済として給付したものは、返還を請求「できません」（錯誤によるときは、債権者が得た利益の返還を求められます）。","w":"民法第706条。","r":[["民法","706"]]},"3":{"t":true,"w":"民法第705条（非債弁済）。","r":[["民法","705"]]},"4":{"t":false,"p":"不法な原因が受益者についてのみ存したときは、給付したものの返還を請求「できます」。","w":"民法第708条ただし書。","r":[["民法","708"]]}}},"13-35":{"s":"相続人・相続分・相続放棄・遺留分を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"配偶者と兄弟姉妹が相続人のとき、兄弟姉妹の相続分は6分の1ではなく「4分の1」です。","w":"民法第900条第3号。","r":[["民法","900"]]},"2":{"t":true,"w":"兄弟姉妹の代襲相続は兄弟姉妹の子までで、その子（Ｄ）による再代襲はありません（民法第889条第2項は第887条第2項を準用し、第3項は準用していません）。","r":[["民法","889"],["民法","887"]]},"3":{"t":false,"p":"相続の放棄は、熟慮期間内であっても撤回「できません」。","w":"民法第919条第1項。","r":[["民法","919"]]},"4":{"t":false,"p":"兄弟姉妹には遺留分が「ありません」。","w":"民法第1042条第1項（兄弟姉妹以外の相続人は、遺留分として…）。","r":[["民法","1042"]]}}},"13-36":{"s":"行為能力を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"成年者と同一の行為能力を有するのは「許された営業に関して」だけで、それ以外の法律行為を単独でできるわけではありません。","w":"民法第6条第1項。","r":[["民法","6"]]},"2":{"t":true,"w":"民法第13条第1項第6号。","r":[["民法","13"]]},"3":{"t":true,"w":"民法第17条第1項ただし書。","r":[["民法","17"]]},"4":{"t":true,"w":"民法第20条第1項。","r":[["民法","20"]]}}},"13-37":{"s":"代理（代理行為の瑕疵・復代理・代理人の行為能力・代理権の消滅）を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"民法第101条第1項。","r":[["民法","101"]]},"2":{"t":true,"w":"民法第104条。","r":[["民法","104"]]},"3":{"t":false,"p":"制限行為能力者にも代理権を付与「できます」。制限行為能力者が代理人としてした行為は、行為能力の制限を理由に取り消すことができません。","w":"民法第102条。","r":[["民法","102"]]},"4":{"t":true,"w":"民法第111条第1項第2号（代理人が破産手続開始の決定を受けたこと）。","r":[["民法","111"]]}}},"13-38":{"s":"抵当権の内容・順位の変更・処分・消滅を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"民法第369条第1項。","r":[["民法","369"]]},"2":{"t":false,"p":"抵当権の順位の変更は、登記をしなければ、第三者への対抗だけでなく、効力そのものが「生じません」。","w":"民法第374条第2項。","r":[["民法","374"]]},"3":{"t":true,"w":"民法第376条第1項。","r":[["民法","376"]]},"4":{"t":true,"w":"民法第396条・第397条。","r":[["民法","396"],["民法","397"]]}}},"13-39":{"s":"債権の消滅（受領権者の外観・代物弁済・更改・混同）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"民法第478条：受領権者としての外観を有する者への弁済は、弁済者が善意かつ無過失なら有効です。","r":[["民法","478"]]},"2":{"t":true,"w":"民法第482条（代物弁済）。","r":[["民法","482"]]},"3":{"t":true,"w":"民法第513条・第514条第1項（債務者の交替による更改）。","r":[["民法","513"],["民法","514"]]},"4":{"t":false,"p":"債権が第三者（Ｃ）の質権の目的となっているときは、混同によっても債権は消滅「しません」。","w":"民法第520条ただし書。","r":[["民法","520"]]}}},"13-40":{"s":"委任と請負を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"受任者は、有償・無償を問わず、「善良な管理者の注意」をもって委任事務を処理する義務を負います。無償なら自己のためにするのと同等の注意でよい、という定めはありません。","w":"民法第644条。","r":[["民法","644"]]},"2":{"t":true,"w":"民法第649条。","r":[["民法","649"]]},"3":{"t":true,"w":"民法第633条。","r":[["民法","633"]]},"4":{"t":true,"w":"民法第641条。","r":[["民法","641"]]}}},"13-41":{"s":"手形の抗弁・呈示期間と、電子記録債権の請求・変更を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"手形法第17条（第77条第1項第1号で準用）：人的抗弁は、債務者を害することを知らずに手形を取得した所持人には対抗できません。強迫による取消しが人的抗弁に当たることは判例の考え方です（条文には直接書かれていません）。","r":[["手形法","17"],["手形法","77"]]},"2":{"t":true,"w":"手形法第38条第1項（第77条第1項第3号で準用）。","r":[["手形法","38"],["手形法","77"]]},"3":{"t":true,"w":"電子記録債権法第5条第1項。","r":[["電子記録債権法","5"]]},"4":{"t":false,"p":"電子記録債権の内容の変更は、意思表示の合致だけでは効力を生じず、「変更記録をしなければ効力を生じません」（対抗要件ではなく効力要件）。","w":"電子記録債権法第26条第1項。","r":[["電子記録債権法","26"]]}}},"13-42":{"s":"犯罪収益移転防止法の取引時確認と記録の保存を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"犯罪収益移転防止法第4条第1項第1号。","r":[["犯罪収益移転防止法","4"]]},"2":{"t":true,"w":"犯罪収益移転防止法施行規則第10条第1項第2号ハ（確認する日前6月以内に作成されたもの）。","r":[["犯罪収益移転防止法施行規則","10"]]},"3":{"t":false,"p":"取引記録は「少額の取引など政令で定める取引」を「除いて」作成し、保存期間7年の起算点は「契約が終了した日」ではなく「取引の行われた日」です。","w":"犯罪収益移転防止法第7条第1項・第3項。","r":[["犯罪収益移転防止法","7"]]},"4":{"t":true,"w":"犯罪収益移転防止法第6条第1項・第2項。","r":[["犯罪収益移転防止法","6"]]}}},"13-43":{"s":"個人情報保護法の定義と義務を問う問題です。公式正答（基準日2018年4月1日）では②が適切とされています。②は、2022年4月施行の改正で結論が変わっています。","law":"②について、公式正答の時点では、6か月以内に消去することとなる個人データは「保有個人データ」から除かれていました。現行の個人情報保護法第16条第4項には、この期間による除外はありません（公益その他の利益が害されるものとして政令で定めるもの以外の個人データは、保有個人データです）。","items":{"1":{"t":false,"p":"取り扱う個人の数が5,000人未満でも、個人情報データベース等を事業の用に供していれば個人情報取扱事業者に「該当します」。","w":"個人情報保護法第16条第2項（人数による除外はありません）。","r":[["個人情報保護法","16"]]},"2":{"t":true,"now":false,"w":"公式正答では適切とされています。現行の個人情報保護法第16条第4項では、6か月以内に消去することとなるものを除外する定めがないので、現行法では記述は適切ではありません。","r":[["個人情報保護法","16"]]},"3":{"t":false,"p":"要配慮個人情報も、あらかじめ本人の同意を得れば取得「できます」（法令に基づく場合などの例外もあります）。","w":"個人情報保護法第20条第2項。","r":[["個人情報保護法","20"]]},"4":{"t":false,"p":"利用する必要がなくなった個人データは、「直ちに消去しなければならない」のではなく、「遅滞なく消去するよう努めなければならない」（努力義務）とされています。","w":"個人情報保護法第22条。","r":[["個人情報保護法","22"]]}}},"13-44":{"s":"消費者契約法の適用範囲・取消権の期間・不当条項を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"消費者契約は、政令で指定された商品等に限られず、消費者と事業者との間で締結される契約「すべて」です。","w":"消費者契約法第2条第3項。","r":[["消費者契約法","2"]]},"2":{"t":false,"p":"取消権の期間は「6か月」ではなく、追認できる時から「1年間」（締結の時から5年）です。","w":"消費者契約法第7条第1項。","r":[["消費者契約法","7"]]},"3":{"t":false,"p":"無効になるのは消費者契約全体ではなく、責任の一部を免除する「その条項」です。","w":"消費者契約法第8条第1項第2号。","r":[["消費者契約法","8"]]},"4":{"t":true,"w":"消費者契約法第9条第1項第1号。","r":[["消費者契約法","9"]]}}},"13-45":{"s":"協会の自主規制基本規則（広告・勧誘）を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"テレビCMの承認を受けるのは、協会が設ける「審査機関」からで、登録行政庁の承認は求められていません。","w":"自主規制基本規則第45条第1項。"},"2":{"t":true,"w":"自主規制基本規則第55条第1項第1号。"},"3":{"t":false,"p":"勧誘を引き続き受けることを希望しない旨の明確な意思表示があったときは、「3か月」ではなく「最低6か月」見合わせます。","w":"自主規制基本規則第55条第1項第2号。"},"4":{"t":false,"p":"契約内容が理解困難なことを認識した場合は、丁寧に説明して理解させるよう努めるのではなく、貸付けの契約の締結に係る勧誘を「行ってはならない」とされています。","w":"自主規制基本規則第54条第4項。なお、理解困難なことを認識しながら契約を締結することは、不正又は著しく不当な行為に当たるおそれがある行為とされています（同規則第15条第7号・監督指針Ⅱ－2－10）。"}}},"13-46":{"s":"景品表示法（指定の手続・不実証広告・課徴金・協定）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"景品類・表示の指定の際に意見を聴くのは「公正取引委員会」ではなく「消費者委員会」です（公聴会で関係事業者及び一般の意見も求めます）。","w":"景品表示法第3条第1項。","r":[["景品表示法","3"]]},"2":{"t":true,"w":"景品表示法第7条第2項。","r":[["景品表示法","7"]]},"3":{"t":true,"w":"景品表示法第13条。","r":[["景品表示法","13"]]},"4":{"t":true,"w":"景品表示法第36条第1項。","r":[["景品表示法","36"]]}}},"13-47":{"s":"日本貸金業協会の紛争解決等業務に関する規則を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"代理人になれるのは、法定代理人・弁護士・認定司法書士（請求の価額に上限あり）と、許可を受けた者です。「行政書士」は挙げられていません。","w":"紛争解決等業務に関する規則第38条第1項・第2項。"},"2":{"t":true,"w":"紛争解決等業務に関する規則第52条第1項。"},"3":{"t":true,"w":"紛争解決等業務に関する規則（紛争解決手続の申立ての取下げ）のとおりです（結論は公式正答によります）。"},"4":{"t":true,"w":"紛争解決等業務に関する規則第89条。"}}},"13-48":{"s":"貸借対照表の区分を問う問題です。会社計算規則は取り込んでいないため、同じ考え方を定めた企業会計原則の貸借対照表原則で確認できる範囲で説明します。公式正答では④が適切とされています。","law":"④について、第19回問50④の公式正答では、純資産の部は「株主資本、評価・換算差額等、株式引受権及び新株予約権」に区分するとされています。現行の会社計算規則では「株式引受権」の区分も加わっているので、④の記述（3区分）は現行の規定どおりではありません（会社計算規則は取り込んでいないため、第19回の公式正答に基づく判断です）。","items":{"1":{"t":false,"p":"連結会社が2以上の異なる種類の事業を営んでいる場合は、連結貸借対照表の資産の部・負債の部を事業の種類ごとに区分「できます」（公式正答による）。","w":"結論は公式正答によります。"},"2":{"t":false,"p":"資産の部の区分は「流動資産、固定資産及び金融資産」ではなく、「流動資産、固定資産及び繰延資産」です。","w":"企業会計原則・貸借対照表原則二。"},"3":{"t":false,"p":"固定資産の区分は「有形固定資産、無形固定資産及び繰延資産」ではなく、「有形固定資産、無形固定資産及び投資その他の資産」です（繰延資産は固定資産とは別の区分です）。","w":"企業会計原則・貸借対照表原則二・四㈠Ｂ。"},"4":{"t":true,"now":false,"w":"公式正答では適切とされています（第13回の時点）。現行の規定では株式引受権の区分も加わっています（第19回問50④の公式正答による）。"}}},"13-49":{"s":"企業会計原則の一般原則を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"企業会計原則・一般原則一。"},"2":{"t":false,"p":"正規の簿記の原則は「少額の取引」ではなく「すべての取引」について「正確な会計帳簿」を作成することを求めるもので、「厳格性の原則」という名称の原則はありません。","w":"企業会計原則・一般原則二。"},"3":{"t":true,"w":"企業会計原則・一般原則七。"},"4":{"t":true,"w":"企業会計原則・一般原則四。"}}},"13-50":{"s":"損益計算書の段階利益を問う問題です。会社計算規則は取り込んでいないため、同じ考え方を定めた企業会計原則の損益計算書原則で確認します。適切でないのは④です。","items":{"1":{"t":true,"w":"結論は公式正答によります。"},"2":{"t":true,"w":"企業会計原則・損益計算書原則：売上総利益は、売上高から売上原価を控除して表示します。"},"3":{"t":true,"w":"企業会計原則・損益計算書原則三。"},"4":{"t":false,"p":"経常利益は、営業損益に「特別利益・特別損失」ではなく「営業外収益・営業外費用」を加減したものです（特別損益を加減するのは税引前当期純利益の計算です）。","w":"企業会計原則・損益計算書原則五・七。"}}},"14-01":{"s":"貸金業法第2条の用語の定義です。適切なのはｂとｃです（2個）。","items":{"a":{"t":false,"p":"手形の割引・売渡担保などの方法による金銭の交付も、貸金業に「含まれます」。","w":"第2条第1項かっこ書。","r":[["貸金業法","2"]]},"b":{"t":true,"w":"第2条第3項。","r":[["貸金業法","2"]]},"c":{"t":true,"w":"第2条第4項。","r":[["貸金業法","2"]]},"d":{"t":false,"p":"信用情報は「顧客又は債務者の借入金の返済能力に関する情報」で、保証人の保証能力に関する情報は「含まれません」。","w":"第2条第13項。","r":[["貸金業法","2"]]}}},"14-02":{"s":"変更の届出（第8条）です。「あらかじめ」届け出るのは、営業所の名称・所在地と広告等に表示する連絡先です。正しいのは②です。","items":{"1":{"t":false,"p":"商号の変更は、「あらかじめ」ではなく、変更があった日から「2週間以内」に届け出ます。","w":"第8条第1項・第4条第1項第1号。","r":[["貸金業法","8"],["貸金業法","4"]]},"2":{"t":true,"w":"第8条第1項・第4条第1項第8号（業務の種類及び方法）。","r":[["貸金業法","8"],["貸金業法","4"]]},"3":{"t":false,"p":"営業所の所在地の変更は、変更後2週間以内ではなく、変更しようとするとき「あらかじめ」届け出ます。","w":"第8条第1項・第4条第1項第5号。","r":[["貸金業法","8"],["貸金業法","4"]]},"4":{"t":false,"p":"広告等に表示する電話番号の変更は、変更後2週間以内ではなく、変更しようとするとき「あらかじめ」届け出ます。","w":"第8条第1項・第4条第1項第7号。","r":[["貸金業法","8"],["貸金業法","4"]]}}},"14-03":{"s":"貸金業務取扱主任者の常時勤務・従業者名簿・欠けたときの措置を問う問題です。適切なのはａとｃです。","items":{"a":{"t":true,"w":"監督指針Ⅱ－2－9（2）①のとおりです。","r":[["貸金業法施行規則","10の7"]]},"b":{"t":false,"p":"主任者である従業者については、その登録番号も従業者名簿に記載「しなければなりません」。","w":"施行規則第10条の9の2第1項第4号。","r":[["貸金業法施行規則","10の9の2"]]},"c":{"t":true,"w":"第12条の3第3項・監督指針Ⅱ－2－9（2）③のとおりです。","r":[["貸金業法","12の3"]]},"d":{"t":false,"p":"「必要な措置」は、主任者の「求人募集」や新たな貸付けの停止ではなく、営業所等への主任者の「設置」又は営業所等の「廃止」などです。","w":"監督指針Ⅱ－2－9（2）④。","r":[["貸金業法","12の3"]]}}},"14-04":{"s":"禁止行為（第12条の6）と監督指針の解釈・罰則を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"監督指針が該当するおそれが大きいとしているのは、問合せに「回答せず」不利益を与えることです。口頭で回答して書面で回答しなかっただけでは、この例に当たりません。","w":"監督指針Ⅱ－2－10（第12条の6第1号の例示）。","r":[["貸金業法","12の6"]]},"2":{"t":false,"p":"「不正な」行為は「違法な行為」、「不当な」行為は「実質的に妥当性を欠く又は適当でない行為で、違法な程度にまで達していない行為」です。記述は定義が入れ替わっています。","w":"監督指針Ⅱ－2－10。","r":[["貸金業法","12の6"]]},"3":{"t":true,"w":"第12条の6第1号の虚偽告知は、行政処分（第24条の6の4）に加え、第48条第1項第1号の2の刑事罰の対象です。","r":[["貸金業法","12の6"],["貸金業法","48"]]},"4":{"t":false,"p":"断定的判断の提供（第12条の6第2号）は、刑事罰の対象では「ありません」。","w":"第48条第1項第1号の2（刑事罰は第1号の虚偽告知だけ）。","r":[["貸金業法","12の6"],["貸金業法","48"]]}}},"14-05":{"s":"利息・保証料等の制限（第12条の8）と罰則を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"年20%の利息の契約は、出資法の上限（年20%を「超える」と処罰）を超えないので、刑事罰の対象では「ありません」（利息制限法の上限18%を超える部分は無効で、貸金業法第12条の8第1項違反として行政処分の対象です）。","w":"出資法第5条第2項・利息制限法第1条第2号・貸金業法第12条の8第1項。","r":[["出資法","5"],["利息制限法","1"],["貸金業法","12の8"]]},"2":{"t":false,"p":"利息制限法の上限を超える利息の受領は、第12条の8第4項に違反し、行政処分の対象と「なります」。","w":"第12条の8第4項・第24条の6の4第1項第2号。","r":[["貸金業法","12の8"],["貸金業法","24の6の4"]]},"3":{"t":false,"p":"保証料の確認は、保証契約の締結後に「遅滞なく」ではなく、保証契約を締結する「まで」に行います。","w":"第12条の8の保証料の確認義務。","r":[["貸金業法","12の8"]]},"4":{"t":true,"w":"第12条の8第9項・施行規則第10条の14第2号：根保証契約で、3年を経過した日より後の日を元本確定期日とするもの（又は元本確定期日の定めがないもの）は締結できません。5年を経過した日はこれに当たります。","r":[["貸金業法","12の8"],["貸金業法施行規則","10の14"]]}}},"14-06":{"s":"返済能力の調査で指定信用情報機関の信用情報を使う義務（第13条第2項）がある場合です。義務があるのはｂだけです（1個）。","items":{"a":{"t":false,"p":"極度方式貸付けに係る契約は、使用義務の対象から「除かれて」います。","w":"施行規則第10条の16第1号。","r":[["貸金業法施行規則","10の16"]]},"b":{"t":true,"w":"第13条第2項：個人である顧客等（保証人となろうとする者を含む）と貸付けの契約（保証契約を含む）を締結しようとする場合。","r":[["貸金業法","13"],["貸金業法","2"]]},"c":{"t":false,"p":"手形（融通手形を除く）の割引を内容とする契約は、使用義務の対象から「除かれて」います。","w":"施行規則第10条の16第2号・第1条の2の3第2号。","r":[["貸金業法施行規則","10の16"],["貸金業法施行規則","1の2の3"]]},"d":{"t":false,"p":"他の貸金業者を債権者とする金銭の貸借の媒介に係る契約は、使用義務の対象から「除かれて」います。","w":"施行規則第10条の16第2号・第1条の2の3第5号。","r":[["貸金業法施行規則","10の16"],["貸金業法施行規則","1の2の3"]]}}},"14-07":{"s":"年収証明書（資力を明らかにする書面等）の提出が必要な場面を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"80万円の貸付けは50万円を超えるので、1年前に源泉徴収票の提出を受けていても、改めて提出を受ける必要が「あります」（公式正答による）。","w":"第13条第3項第1号・ただし書。ただし書の「既に提出を受けている場合」に1年前の源泉徴収票が当たらないことの結論は公式正答によります（源泉徴収票は一般的に発行される直近の期間に係るものであることが必要です。施行規則第10条の17第2項第1号）。","r":[["貸金業法","13"],["貸金業法施行規則","10の17"]]},"2":{"t":false,"p":"自社の合算額に加えるのは「貸付けの残高」で、顧客が「保証」している残高は含みません。貸付金額50万円は50万円を「超えない」ので、年収証明書は「不要」です。","w":"第13条第3項第1号イ・ロ。","r":[["貸金業法","13"]]},"3":{"t":false,"p":"途上の調査では、過去3年以内に発行された書面等で、資力に変更がないと認められるものの提出を既に受けていれば、改めて提出を受ける必要は「ありません」。","w":"第13条の3第3項ただし書・施行規則第10条の26第2項。","r":[["貸金業法","13の3"],["貸金業法施行規則","10の26"]]},"4":{"t":true,"w":"第13条の3第5項：極度方式個人顧客合算額＝極度額50万円＋他の貸付けの残高30万円＝80万円（住宅資金貸付契約の残高は除く）で、100万円を超えないので不要です。","r":[["貸金業法","13の3"]]}}},"14-08":{"s":"返済能力の調査に関する義務違反が、刑事罰と行政処分の両方の対象になるかを問う問題です。両方の対象になるのはｂ・ｃ・ｄです（3個）。","items":{"a":{"t":false,"p":"過剰貸付けの禁止（第13条の2第1項）違反は、行政処分の対象ですが、刑事罰の規定は「ありません」。","w":"第48条・第49条に第13条の2第1項違反の罰則はありません。法令違反として第24条の6の4第1項第2号の処分の対象です。","r":[["貸金業法","13の2"],["貸金業法","24の6の4"]]},"b":{"t":true,"w":"第13条第2項違反（信用情報を使用した調査をしない）は、第48条第1項第1号の4の刑事罰と、行政処分の対象です。","r":[["貸金業法","13"],["貸金業法","48"]]},"c":{"t":true,"w":"第13条第3項違反（年収証明書の提出を受けない）は、第49条第3号の2の刑事罰と、行政処分の対象です。","r":[["貸金業法","13"],["貸金業法","49"]]},"d":{"t":true,"w":"第13条第4項違反（調査の記録を作成しない）は、第49条第3号の3の刑事罰と、行政処分の対象です。","r":[["貸金業法","13"],["貸金業法","49"]]}}},"14-09":{"s":"総量規制の除外契約（施行規則第10条の21）に当たるものを選ぶ問題です。該当するのはｂとｄです。","items":{"a":{"t":false,"p":"売却予定の不動産の売却代金で返済する貸付けの除外契約は、「個人顧客の」不動産が対象です。配偶者が所有する土地は「該当しません」。","w":"施行規則第10条の21第1項第7号。","r":[["貸金業法施行規則","10の21"]]},"b":{"t":true,"w":"施行規則第10条の21第1項第1号：不動産の改良に必要な資金の貸付け（担保の要件はありません）。","r":[["貸金業法施行規則","10の21"]]},"c":{"t":false,"p":"不動産担保貸付けの除外契約から、個人顧客の「居宅」は除かれています。","w":"施行規則第10条の21第1項第6号かっこ書。","r":[["貸金業法施行規則","10の21"]]},"d":{"t":true,"w":"施行規則第10条の21第1項第6号：担保を提供する者（直系尊属）の居宅などではない別荘を担保とし、返済能力を超えず、価格の範囲内の貸付け。","r":[["貸金業法施行規則","10の21"]]}}},"14-10":{"s":"契約締結前の書面（第16条の2）の対象・交付先・記載事項を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"極度方式貸付けには、契約締結前の書面の交付義務は「ありません」。","w":"第16条の2第1項かっこ書。","r":[["貸金業法","16の2"]]},"2":{"t":false,"p":"保証人となろうとする者に交付するのは、保証契約の契約締結前の書面（概要と詳細の2種類を同時に）で、貸付けの契約の契約締結前の書面ではありません。","w":"第16条の2第3項・施行規則第12条の2第7項。第1項の書面の交付先は貸付けの契約の相手方となろうとする者です。","r":[["貸金業法","16の2"],["貸金業法施行規則","12の2"]]},"3":{"t":true,"w":"第16条の2第1項各号・施行規則第12条の2第1項第1号に、「貸付けに関し貸金業者が受け取る書面の内容」は挙げられていません。","r":[["貸金業法","16の2"],["貸金業法施行規則","12の2"]]},"4":{"t":false,"p":"保証人となろうとする者の氏名・住所は、記載事項に「含まれません」。","w":"第16条の2第1項各号・施行規則第12条の2第1項第1号。","r":[["貸金業法","16の2"],["貸金業法施行規則","12の2"]]}}},"14-11":{"s":"契約締結時の書面を再交付しなければならない変更（施行規則第13条第2項）を問う問題です。適切なのはａだけです（1個）。","items":{"a":{"t":true,"w":"貸金業者の商号・住所（第17条第1項第1号）は、施行規則第13条第2項の重要な事項に挙げられていないので、再交付は不要です。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"b":{"t":false,"p":"各回の返済期日及び返済金額の変更は、不利な変更に限らず、有利な変更でも再交付が「必要」です。","w":"施行規則第13条第2項第1号ロ（同条第1項第1号チ）。","r":[["貸金業法施行規則","13"]]},"c":{"t":false,"p":"新たに保証契約を締結して保証人を追加した場合は、再交付が「必要」です。","w":"施行規則第13条第2項第1号ロ：同条第1項第1号ヲ（保証人の氏名・住所）は、新たに保証契約を締結する場合に再交付が必要な事項です。","r":[["貸金業法施行規則","13"]]},"d":{"t":false,"p":"期限の利益の喪失の定めの変更は、相手方の利益となる変更であれば、再交付は「不要」です。","w":"施行規則第13条第2項第1号イかっこ書（同条第1項第1号ヌ）。","r":[["貸金業法施行規則","13"]]}}},"14-12":{"s":"貸金業者が保存すべきものの保存期間です。適切なのはａとｂです。","items":{"a":{"t":true,"w":"施行規則第10条の18第2項第2号。","r":[["貸金業法施行規則","10の18"]]},"b":{"t":true,"w":"施行規則第30条の16第1項。","r":[["貸金業法施行規則","30の16"]]},"c":{"t":false,"p":"帳簿の保存期間は「締結した日から7年間」ではなく、「最終の返済期日（債権が消滅したときはその日）から少なくとも10年間」です。","w":"施行規則第17条第1項。","r":[["貸金業法施行規則","17"]]},"d":{"t":false,"p":"途中の調査（第13条の3）の記録の保存期間は「7年間」ではなく、作成後「3年間」です。","w":"施行規則第10条の27第2項。","r":[["貸金業法施行規則","10の27"]]}}},"14-13":{"s":"生命保険契約の制限・公的給付の預金通帳等の保管の制限・特定公正証書の制限を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"住宅資金貸付契約は、自殺を保険事故とすることの禁止の対象から「除かれて」います。","w":"第12条の7。","r":[["貸金業法","12の7"]]},"2":{"t":true,"w":"第20条の2第2号。","r":[["貸金業法","20の2"]]},"3":{"t":false,"p":"説明をしても、債務者等から特定公正証書の作成を代理人に委任する委任状を取得することは「できません」。","w":"第20条第1項（例外なく禁止）。","r":[["貸金業法","20"]]},"4":{"t":false,"p":"代理人の選任に関し、推薦その他これに類する関与をしては「なりません」。","w":"第20条第2項。","r":[["貸金業法","20"]]}}},"14-14":{"s":"開始等の届出（第24条の6の2・施行規則第26条の25）の事由です。該当するのはｂとｃです（2個）。","items":{"a":{"t":false,"p":"外国法人との合弁事業は、届出事由に「挙げられていません」。","w":"施行規則第26条の25第1項第1号〜第7号。","r":[["貸金業法施行規則","26の25"]]},"b":{"t":true,"w":"施行規則第26条の25第1項第4号。","r":[["貸金業法施行規則","26の25"]]},"c":{"t":true,"w":"施行規則第26条の25第1項第5号。","r":[["貸金業法施行規則","26の25"]]},"d":{"t":false,"p":"届出事由は債権を「譲渡した」場合で、「譲り受けた」場合は届出事由では「ありません」。","w":"施行規則第26条の25第1項第3号。","r":[["貸金業法施行規則","26の25"]]}}},"14-15":{"s":"登録を必ず取り消さなければならない場合（第24条の6の5）を問う問題です。該当するのは①です。","items":{"1":{"t":true,"w":"第24条の6の5第1項第4号：第12条（名義貸しの禁止）に違反したとき。","r":[["貸金業法","24の6の5"],["貸金業法","12"]]},"2":{"t":false,"p":"純資産額の不足は、必ず取り消す事由ではなく、登録の取消し又は業務停止を命ずることが「できる」事由です。","w":"第24条の6の4第1項第1号（第6条第1項第14号に該当することとなったとき）。","r":[["貸金業法","24の6の4"]]},"3":{"t":false,"p":"取立て制限者への債権譲渡は、必ず取り消す事由ではなく、取消し又は業務停止を命ずることが「できる」事由です。","w":"第24条の6の4第1項第3号。","r":[["貸金業法","24の6の4"]]},"4":{"t":false,"p":"破産手続開始の決定は、取消しの事由ではなく、登録が当然に「効力を失う」事由です（破産管財人が30日以内に届け出ます）。","w":"第10条第1項第3号・第2項。第24条の6の5第1項第1号が引用する第6条第1項の号に、第2号（破産）は含まれていません。","r":[["貸金業法","10"],["貸金業法","24の6の5"]]}}},"14-16":{"s":"個人信用情報の提供（第41条の35）と監督指針の留意事項を問う問題です。適切なのはｃとｄです。","items":{"a":{"t":false,"p":"極度方式基本契約そのものは、個人信用情報の提供の対象から「除かれて」います。","w":"第41条の35第2項・施行規則第1条の2の3第1号。","r":[["貸金業法","41の35"],["貸金業法施行規則","1の2の3"]]},"b":{"t":false,"p":"提供した個人信用情報（勤務先の商号又は名称を含む）に変更があったときは、遅滞なく変更内容を提供「しなければなりません」。","w":"第41条の35第3項・施行規則第30条の13第1項第5号。","r":[["貸金業法","41の35"],["貸金業法施行規則","30の13"]]},"c":{"t":true,"w":"施行規則第30条の13第1項第6号。","r":[["貸金業法施行規則","30の13"]]},"d":{"t":true,"w":"監督指針Ⅱ－2－14（2）①イ：取得した個人信用情報は、取得当日中に指定信用情報機関に提供することを原則とします。","r":[["貸金業法","41の35"]]}}},"14-17":{"s":"利息制限法の元本額の特則（第5条）と保証料の制限（第8条・第9条）の計算問題です（期間1年・元利一括返済）。正しいのは④です。","items":{"1":{"t":false,"p":"第一契約（元本8万円・20%）は、締結時の元本で判断するので有効です。18%に下がるのは第二契約だけです（残元本5万円＋5万円＝10万円とみなす）。","w":"利息制限法第5条第1号・第1条第1号・第2号。","r":[["利息制限法","5"],["利息制限法","1"]]},"2":{"t":false,"p":"同時に借りた元本の合計は9万円＋100万円＝109万円で、上限は年18%ではなく「15%」です。","w":"利息制限法第5条第2号・第1条第3号。","r":[["利息制限法","5"],["利息制限法","1"]]},"3":{"t":false,"p":"保証料の上限は45,000円ではなく「25,000円」です。","w":"利息制限法第8条第1項：元本50万円の法定上限額は年18%で9万円。利息（13%で6万5,000円）を引いた2万5,000円が上限で、超える部分が無効です。","r":[["利息制限法","8"],["利息制限法","1"]]},"4":{"t":true,"w":"利息制限法第9条第1項：元本20万円の法定上限額は年18%で3万6,000円。保証料8,000円を引いた2万8,000円（年14%）が増加後の利息の上限です。","r":[["利息制限法","9"],["利息制限法","1"]]}}},"14-18":{"s":"みなし利息とその例外（利息制限法第3条・第6条）を問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"例外は「債務者の要請により」行う書面の再発行の手数料です（第6条第1項・施行令第1条第2号）。返済の方式を変更したために法律上必要となる書面の再交付の費用はこれに当たらず、第3条により利息とみなされます（結論は公式正答によります）。","r":[["利息制限法","3"],["利息制限法","6"],["利息制限法施行令","1"]]},"2":{"t":false,"p":"顧客の要請によるカードの再発行手数料は、利息と「みなされません」。","w":"利息制限法第6条第1項・施行令第1条第1号。","r":[["利息制限法","6"],["利息制限法施行令","1"]]},"3":{"t":false,"p":"公租公課に充てられるべき費用は、利息と「みなされません」。","w":"利息制限法第6条第2項第1号。","r":[["利息制限法","6"]]},"4":{"t":false,"p":"再度の口座振替手続の費用は、利息と「みなされません」。","w":"利息制限法第6条第1項・施行令第1条第3号。","r":[["利息制限法","6"],["利息制限法施行令","1"]]}}},"14-19":{"s":"登録の拒否事由（第6条第1項）に該当しないものを選ぶ問題です。該当しないのは①です。","items":{"1":{"t":false,"p":"罰金刑で拒否事由になるのは、貸金業法・出資法・暴力団対策法など法律が列挙したものの違反に限られます。不正競争防止法違反の罰金刑は「該当しません」。","w":"第6条第1項第5号。","r":[["貸金業法","6"]]},"2":{"t":true,"w":"第6条第1項第3号かっこ書（取消しの日前30日以内に役員であった者）・第9号ロ。2週間前の退任はこれに当たります。","r":[["貸金業法","6"]]},"3":{"t":true,"w":"第6条第1項第4号・第9号ロ：どの法律の違反でも、拘禁刑（旧懲役）以上の刑は拒否事由です。","r":[["貸金業法","6"]]},"4":{"t":true,"w":"第6条第1項第15号・施行規則第5条の7第1項第2号。","r":[["貸金業法","6"],["貸金業法施行規則","5の7"]]}}},"14-20":{"s":"廃業等の届出（第10条）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"相続人の届出期限は、死亡の日からではなく、「死亡の事実を知った日」から30日以内です。","w":"第10条第1項柱書かっこ書・第1号。","r":[["貸金業法","10"]]},"2":{"t":true,"w":"第10条第1項第2号。","r":[["貸金業法","10"]]},"3":{"t":true,"w":"第10条第1項第3号。","r":[["貸金業法","10"]]},"4":{"t":true,"w":"第10条第1項第4号。","r":[["貸金業法","10"]]}}},"14-21":{"s":"監督指針のシステムリスク管理態勢で、多段階のサイバーセキュリティ対策（入口対策・内部対策・出口対策）として挙げられていた例を問う問題です。合致しないのは③です。現行の監督指針（令和8年10月版）には、この例示は見当たらず、「金融分野におけるサイバーセキュリティに関するガイドライン」を参照するよう定めています。結論は公式正答によります。","items":{"1":{"t":true,"w":"入口対策の例です（結論は公式正答によります）。"},"2":{"t":true,"w":"内部対策の例です（結論は公式正答によります）。"},"3":{"t":false,"p":"内部監査部門による監査や外部監査人による評価は、入口・内部・出口の多段階のサイバーセキュリティ対策の例では「ありません」（システム監査に関する事項です）。","w":"結論は公式正答によります。"},"4":{"t":true,"w":"出口対策の例です（結論は公式正答によります）。"}}},"14-22":{"s":"総量規制の例外契約（施行規則第10条の23）に該当しないものを選ぶ問題です。該当しないのは④です。","items":{"1":{"t":true,"w":"施行規則第10条の23第1項第2号。","r":[["貸金業法施行規則","10の23"]]},"2":{"t":true,"w":"施行規則第10条の23第1項第5号。","r":[["貸金業法施行規則","10の23"]]},"3":{"t":true,"w":"施行規則第10条の23第1項第6号。","r":[["貸金業法施行規則","10の23"]]},"4":{"t":false,"p":"特定緊急貸付契約は、合算額「10万円」以下・返済期間「3か月」以内が要件です。30万円・1年では「該当しません」。","w":"施行規則第10条の23第1項第2号の2ロ・ハ。","r":[["貸金業法施行規則","10の23"]]}}},"14-23":{"s":"極度方式基本契約の3か月ごとの定期調査（第13条の3第2項）を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"施行規則第10条の25第3項第3号ロ：合理的な理由による停止の措置で、その旨・年月日・理由が帳簿に交渉の経過の記録として記載されている場合は、調査不要です。","r":[["貸金業法施行規則","10の25"]]},"2":{"t":false,"p":"残高10万円以下かどうかは、同じ顧客との「他の極度方式基本契約」の残高も合わせて判断します。他の契約の残高に「かかわらず」不要になるわけではありません。","w":"施行規則第10条の25第3項第1号かっこ書。","r":[["貸金業法施行規則","10の25"]]},"3":{"t":true,"w":"施行規則第10条の25第2項。","r":[["貸金業法施行規則","10の25"]]},"4":{"t":true,"w":"第13条の4・施行規則第10条の29。","r":[["貸金業法","13の4"],["貸金業法施行規則","10の29"]]}}},"14-24":{"s":"貸付条件の広告（第15条）の表示事項と連絡先の制限を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"監督指針Ⅱ－2－15（2）①のとおりです。","r":[["貸金業法","15"]]},"2":{"t":true,"w":"施行規則第12条第1項第3号。","r":[["貸金業法施行規則","12"]]},"3":{"t":false,"p":"「期限の利益の喪失の定め」は、広告の表示事項に「含まれません」。","w":"広告の表示事項は第15条第1項・施行規則第12条第1項第1号（返済の方式・返済期間及び返済回数、賠償額の予定の割合、担保に関する事項など）です。","r":[["貸金業法","15"],["貸金業法施行規則","12"]]},"4":{"t":true,"w":"第15条第2項・施行規則第12条第4項（多数の者に対して同様の内容で行う勧誘）・第5項。","r":[["貸金業法","15"],["貸金業法施行規則","12"]]}}},"14-25":{"s":"契約締結時の書面（第17条第1項）の記載事項です。含まれないのは④です。","items":{"1":{"t":true,"w":"施行規則第13条第1項第1号ニ。","r":[["貸金業法施行規則","13"]]},"2":{"t":true,"w":"施行規則第13条第1項第1号ハ。","r":[["貸金業法施行規則","13"]]},"3":{"t":true,"w":"施行規則第13条第1項第1号リ。","r":[["貸金業法施行規則","13"]]},"4":{"t":false,"p":"記載するのは将来支払う返済金額の「合計額」で、元本・利息の「内訳」は記載事項に「含まれません」。","w":"施行規則第13条第1項第1号タ。","r":[["貸金業法施行規則","13"]]}}},"14-26":{"s":"債権譲渡等の規制（第24条）を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"第24条第1項。","r":[["貸金業法","24"]]},"2":{"t":true,"w":"第24条第2項で第17条が譲受人に準用されます。","r":[["貸金業法","24"]]},"3":{"t":false,"p":"譲渡人である貸金業者も、譲渡までに作成していた帳簿を引き続き保存「しなければなりません」。保存義務を免れる定めはありません。","w":"施行規則第17条第1項：帳簿は契約ごとに最終の返済期日（債権が消滅したときはその日）から少なくとも10年間保存します。","r":[["貸金業法","19"],["貸金業法施行規則","17"]]},"4":{"t":true,"w":"第24条第2項で第18条（受取証書）が譲受人に準用されます。","r":[["貸金業法","24"],["貸金業法","18"]]}}},"14-27":{"s":"出資法と利息制限法の規制を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"出資法第4条第1項。","r":[["出資法","4"]]},"2":{"t":true,"w":"出資法第5条の4第3項。","r":[["出資法","5の4"]]},"3":{"t":true,"w":"利息制限法第8条第8項：主たる債務について既に他の保証契約があるときなどは、あらかじめ保証人となるべき者に通知しなければなりません。","r":[["利息制限法","8"]]},"4":{"t":false,"p":"「営業的」金銭消費貸借の賠償額の予定の上限は、利息の上限の1.46倍ではなく「年2割（20%）」です。1.46倍は営業的でない場合の上限です。","w":"利息制限法第7条第1項・第4条第1項。","r":[["利息制限法","7"],["利息制限法","4"]]}}},"14-28":{"s":"行為能力を問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"民法第20条第1項。","r":[["民法","20"]]},"2":{"t":false,"p":"被保佐人は、事理を弁識する能力を「欠く常況にある者」ではなく、能力が「著しく不十分である者」です（欠く常況にある者は成年被後見人）。","w":"民法第11条・第7条。借財又は保証に保佐人の同意が必要なのは正しい（第13条第1項第2号）。","r":[["民法","11"],["民法","7"],["民法","13"]]},"3":{"t":false,"p":"「義務を免れる」法律行為も、単に権利を得る行為と同じく、法定代理人の同意は「不要」です。","w":"民法第5条第1項ただし書。","r":[["民法","5"]]},"4":{"t":false,"p":"成年被後見人の行為は、成年後見人の同意を得ていても取り消すことが「できます」。","w":"民法第9条。","r":[["民法","9"]]}}},"14-29":{"s":"代理（復代理・無権代理）を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"委任による代理人は、本人の許諾を得たとき「又は」やむを得ない事由があるときに、復代理人を選任「できます」。","w":"民法第104条。","r":[["民法","104"]]},"2":{"t":false,"p":"やむを得ない事由があるときは、法定代理人は復代理人の選任及び監督についての責任「のみ」を負います。","w":"民法第105条。","r":[["民法","105"]]},"3":{"t":true,"w":"民法第115条。","r":[["民法","115"]]},"4":{"t":false,"p":"代理権がないことを相手方が知っていたときは、無権代理人は履行又は損害賠償の責任を「負いません」。","w":"民法第117条第2項第1号。","r":[["民法","117"]]}}},"14-30":{"s":"期間の計算と金銭消費貸借（利息の発生・返還時期）を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"初日（10月1日）は算入しないので、10月2日から1か月で、返済期限は10月31日ではなく「11月1日」です。","w":"民法第140条（初日不算入）・第143条第2項。","r":[["民法","140"],["民法","143"]]},"2":{"t":true,"w":"民法第589条第2項：利息の特約があるときは、借主が金銭を受け取った日以後の利息を請求できます。","r":[["民法","589"]]},"3":{"t":false,"p":"返還時期の定めがないときは、貸主は「相当の期間を定めて」返還の催告をすることができます。直ちに返還を請求できるわけではありません。","w":"民法第591条第1項。","r":[["民法","591"]]},"4":{"t":false,"p":"末日が日曜日で取引をしない慣習があるときは、「前日」ではなく「翌日」に満了します。","w":"民法第142条。","r":[["民法","142"]]}}},"14-31":{"s":"債権の効力（履行遅滞・損害賠償による代位・金銭債務の特則・賠償額の予定）を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"不確定期限の場合、期限の到来を知っているか否かを「問わず」遅滞になるのではなく、期限到来後に履行の請求を受けた時又は期限の到来を知った時のいずれか早い時から遅滞になります。","w":"民法第412条第2項。","r":[["民法","412"]]},"2":{"t":false,"p":"価額の全部の支払を受けたときは、債権者の承諾がなくても、債務者は「当然に」債権者に代位します。","w":"民法第422条。","r":[["民法","422"]]},"3":{"t":false,"p":"金銭債務の不履行では、債権者は損害の証明を「要せず」、債務者は不可抗力を抗弁に「できません」。","w":"民法第419条第2項・第3項。","r":[["民法","419"]]},"4":{"t":true,"w":"民法第420条第1項・第2項。","r":[["民法","420"]]}}},"14-32":{"s":"保証債務の範囲・検索の抗弁・保証人の要件・委託のない保証を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"保証債務は、元本・利息だけでなく、違約金・損害賠償その他の従たるものも「包含します」。","w":"民法第447条第1項。","r":[["民法","447"]]},"2":{"t":false,"p":"検索の抗弁では、債権者が調査するのではなく、「保証人が」主たる債務者に弁済をする資力があり、かつ執行が容易であることを証明します。","w":"民法第453条。","r":[["民法","453"]]},"3":{"t":true,"w":"民法第450条第2項：保証人の代わりを請求できるのは、保証人が弁済の資力（同条第1項第2号）を欠くに至ったときです。行為能力を失った場合は代わりを請求できません。","r":[["民法","450"]]},"4":{"t":false,"p":"主たる債務者の意思に反して保証をすることも「できます」（求償の範囲が制限されるだけです）。","w":"民法第462条第2項。","r":[["民法","462"]]}}},"14-33":{"s":"弁済（費用・充当・提供・代位）を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"弁済の費用は、別段の意思表示がなければ、等しい割合ではなく「債務者」が負担します。","w":"民法第485条。","r":[["民法","485"]]},"2":{"t":false,"p":"弁済をする者の指定に対して、受領者が異議を述べることはできません。「直ちに異議を述べたときはこの限りでない」というのは、受領者が充当を指定した場合に、弁済をする者が異議を述べたときのルールです。","w":"民法第488条第1項・第2項ただし書。","r":[["民法","488"]]},"3":{"t":false,"p":"債権者があらかじめ受領を拒んでいるときは、弁済の準備をしたことを通知して受領の催告をすれば「足ります」。","w":"民法第493条ただし書。","r":[["民法","493"]]},"4":{"t":true,"w":"民法第501条第1項・第2項。","r":[["民法","501"]]}}},"14-34":{"s":"相殺の方法・要件・禁止を問う問題です。Ａから見ると甲債権が自働債権です。公式正答（基準日2019年4月1日）では③が適切とされています。④は、2020年4月施行の民法改正で結論が変わっています。","law":"④は、公式正答（基準日2019年4月1日）では適切でないとされています。現行（基準日2026年4月1日）の民法第509条で相殺が禁止されるのは、悪意による不法行為に基づく損害賠償の債務と、人の生命又は身体の侵害による損害賠償の債務だけなので、現行法では④は適切になります（2020年4月施行の民法改正による変更です）。","items":{"1":{"t":false,"p":"相殺の意思表示には、条件又は期限を付けることが「できません」。","w":"民法第506条第1項。","r":[["民法","506"]]},"2":{"t":false,"p":"双方の債務の履行地が異なっていても、相殺「できます」（相手方に生じた損害は賠償します）。","w":"民法第507条。","r":[["民法","507"]]},"3":{"t":true,"w":"Ａが相殺に使う甲債権の弁済期が来ていれば、乙債権については期限の利益を放棄して相殺できます（民法第505条第1項・第136条第2項）。これは判例の考え方です。","r":[["民法","505"],["民法","136"]]},"4":{"t":false,"now":true,"p":"公式正答（基準日当時の民法）では、不法行為に基づく損害賠償債務を負うＡは相殺できないとされています。","w":"現行の民法第509条では、乙債権が悪意による不法行為又は人の生命・身体の侵害による損害賠償債権でなければ、Ａは相殺できます（現行法では記述は適切）。","r":[["民法","509"]]}}},"14-35":{"s":"約束手形の要件・抗弁と、電子記録債権の譲渡・抗弁の切断を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"「商品の受領と引換えに支払う」という条件を付けると単純な支払約束ではなくなり、付加した記載だけでなく約束手形そのものが「無効」になります。","w":"手形法第75条第2号。","r":[["手形法","75"]]},"2":{"t":true,"w":"電子記録債権法第17条。","r":[["電子記録債権法","17"]]},"3":{"t":false,"p":"原因契約の解除はＡに対する人的抗弁なので、抗弁の切断により、譲受人Ｃには対抗「できません」（Ｃが害することを知って取得した場合などを除く）。","w":"電子記録債権法第20条第1項。","r":[["電子記録債権法","20"]]},"4":{"t":false,"p":"詐欺による取消しは人的抗弁なので、善意無過失で裏書譲渡を受けたＣには対抗「できません」。","w":"手形法第17条（第77条第1項第1号で準用）。詐欺取消しが人的抗弁に当たることは判例の考え方です（条文には直接書かれていません）。","r":[["手形法","17"],["手形法","77"]]}}},"14-36":{"s":"無効・取消し・追認を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"民法第119条。","r":[["民法","119"]]},"2":{"t":false,"p":"行為能力者となった後（取消しの原因となっていた状況が消滅した後）であれば、成年後見人であった者の同意がなくても、本人が単独で追認「できます」。","w":"民法第124条第1項。","r":[["民法","124"]]},"3":{"t":true,"w":"民法第121条。","r":[["民法","121"]]},"4":{"t":true,"w":"民法第125条第2号（法定追認）。","r":[["民法","125"]]}}},"14-37":{"s":"条件と期限を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"債務者が担保を減少させたときは、期限の利益を主張「できません」。","w":"民法第137条第2号。","r":[["民法","137"]]},"2":{"t":true,"w":"民法第129条。","r":[["民法","129"]]},"3":{"t":true,"w":"民法第135条。","r":[["民法","135"]]},"4":{"t":true,"w":"民法第127条第2項。","r":[["民法","127"]]}}},"14-38":{"s":"根抵当権（被担保債権の範囲・極度額の変更・元本確定期日・確定事由）を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"民法第398条の2第2項。","r":[["民法","398の2"]]},"2":{"t":true,"w":"民法第398条の5。","r":[["民法","398の5"]]},"3":{"t":false,"p":"元本確定期日は、定め又は変更した日から「3年以内」ではなく「5年以内」でなければなりません。","w":"民法第398条の6第3項。","r":[["民法","398の6"]]},"4":{"t":true,"w":"民法第398条の20第1項第4号。","r":[["民法","398の20"]]}}},"14-39":{"s":"債権の二重譲渡の対抗関係を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"Ｄへの確定日付のある通知が届く前に、Ｃに弁済して債権は消滅しているので、ＢはＤへの弁済を拒絶「できます」。","w":"民法第467条第1項：確定日付のない承諾でも債務者Ｂとの関係では対抗要件になり、Ｃへの弁済は有効です。その後のＤへの譲渡通知によって、消滅した債権の弁済を求められることはないというのは、判例の考え方です（条文には直接書かれていません）。","r":[["民法","467"]]},"2":{"t":true,"w":"民法第467条第2項：第三者（Ｃ）に対抗するには確定日付のある証書が必要です。確定日付のある通知を受けたＤが優先します。","r":[["民法","467"]]},"3":{"t":true,"w":"どちらも確定日付のない通知の場合、債務者がそのうちの一方（Ｄ）に弁済すれば、他方（Ｃ）への弁済を拒めるというのは、判例の考え方です（条文には直接書かれていません）。","r":[["民法","467"]]},"4":{"t":true,"w":"民法第467条第2項：どちらも確定日付のある通知の場合、先に到達したＣが優先するというのは、判例の考え方です（条文には直接書かれていません）。","r":[["民法","467"]]}}},"14-40":{"s":"契約の成立と解除を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"民法第528条。","r":[["民法","528"]]},"2":{"t":true,"w":"民法第540条。","r":[["民法","540"]]},"3":{"t":true,"w":"民法第542条第1項第4号（定期行為の履行遅滞）。","r":[["民法","542"]]},"4":{"t":false,"p":"解除による返還の範囲は「現に利益を受けている限度」ではなく、相手方を「原状に復させる」（元の状態に戻す）義務です。","w":"民法第545条第1項（金銭を返還するときは受領の時からの利息も付けます。同条第2項）。","r":[["民法","545"]]}}},"14-41":{"s":"相続人と相続分・相続債務・限定承認を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"兄弟姉妹の代襲相続は、兄弟姉妹の子までです。民法第889条第2項は第887条第2項（代襲）を準用しますが、第3項（再代襲）は準用していないので、弟の孫Ｄは相続人になりません。","r":[["民法","889"],["民法","887"]]},"2":{"t":true,"w":"民法第899条：相続分に応じて承継します。遺産分割で債務の負担者を決めても債権者に対抗できず、債権者は法定相続分に応じて請求できるというのは判例の考え方です（条文には直接書かれていません）。","r":[["民法","899"]]},"3":{"t":false,"p":"相続人が数人あるときは、限定承認は全員が共同してのみできるので、Ｂが単独ですることは「できません」。","w":"民法第923条。","r":[["民法","923"]]},"4":{"t":true,"w":"配偶者Ｂが2分の1、子Ｅの代襲相続人ＣとＤが残り2分の1を等分して各4分の1です（民法第887条第2項・第900条第1号・第901条）。","r":[["民法","887"],["民法","900"],["民法","901"]]}}},"14-42":{"s":"倒産手続で財産の管理処分権を持つのは誰かを問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"破産法第78条第1項。","r":[["破産法","78"]]},"2":{"t":false,"p":"民事再生手続では、手続開始後も「再生債務者自身」が業務の遂行と財産の管理処分を続けます。監督委員に権限が専属するのではありません。","w":"民事再生法第38条第1項。","r":[["民事再生法","38"]]},"3":{"t":true,"w":"会社更生法第72条第1項。","r":[["会社更生法","72"]]},"4":{"t":true,"w":"会社法第523条。","r":[["会社法","523"]]}}},"14-43":{"s":"個人情報保護法ガイドライン（通則編）の定義（個人に関する情報・個人データ・公表・提供）を問う問題です（第14回の時点の第23条は、現行法では第27条です）。正しいのは④です。","items":{"1":{"t":false,"p":"暗号化などで秘匿化されていても、「個人に関する情報」に「該当します」（秘匿化されているかどうかを問いません）。","w":"通則編ガイドライン（個人情報の定義）。","r":[["個人情報保護法","2"]]},"2":{"t":false,"p":"個人情報データベース等を構成する「前」の入力用の帳票等に記載された個人情報は、個人データに「該当しません」。","w":"通則編ガイドライン（個人データ）：外部記録媒体に保存されたものや紙面に出力された帳票に印字されたものは該当し、入力用の帳票等に記載されたものは該当しない事例です。","r":[["個人情報保護法","16"]]},"3":{"t":false,"p":"店舗や事務所など顧客が訪れる場所でのポスター掲示も「公表」に「該当します」（ホームページはトップページから1回程度の操作で到達できる場所への掲載が例示されています）。","w":"通則編ガイドライン（公表）。","r":[["個人情報保護法","21"]]},"4":{"t":true,"w":"通則編ガイドライン（提供）：個人データ等を自己以外の者が利用可能な状態に置くことをいい、ネットワーク等で利用できる状態にあれば提供に当たります。","r":[["個人情報保護法","27"]]}}},"14-44":{"s":"消費者契約法の適格消費者団体と不当条項を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"適格消費者団体が行使できるのは「差止請求権」で、取消権は「ありません」（取消権は消費者本人の権利です）。","w":"消費者契約法第2条第4項・第12条。","r":[["消費者契約法","2"],["消費者契約法","12"]]},"2":{"t":false,"p":"事業者の損害賠償責任の全部を免除する条項は、契約を取り消せるのではなく、その条項が「無効」になります。","w":"消費者契約法第8条第1項第1号。","r":[["消費者契約法","8"]]},"3":{"t":false,"p":"無効になるのは条項そのものではなく、平均的な損害の額を「超える部分」だけです。","w":"消費者契約法第9条第1項第1号。","r":[["消費者契約法","9"]]},"4":{"t":true,"w":"消費者契約法第10条。","r":[["消費者契約法","10"]]}}},"14-45":{"s":"景品表示法（景品類・表示の定義・管理上の措置・課徴金）を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"景品類は、くじの方法によるかどうかを問わず、自己の供給する商品又は役務の取引に「付随して」提供するものに限られます。","w":"景品表示法第2条第3項。","r":[["景品表示法","2"]]},"2":{"t":false,"p":"「表示」を指定するのは公正取引委員会ではなく「内閣総理大臣」です。","w":"景品表示法第2条第4項。","r":[["景品表示法","2"]]},"3":{"t":true,"w":"景品表示法第22条第1項。","r":[["景品表示法","22"]]},"4":{"t":false,"p":"課徴金の対象は、第5条（不当な表示の禁止）の違反（第3号の表示を除く）で、第4条（景品類の制限）違反は対象では「ありません」。","w":"景品表示法第8条第1項。","r":[["景品表示法","8"]]}}},"14-46":{"s":"個人データの第三者提供（記録・確認・第三者該当性・同意の方法）を問う問題です（第14回の時点の第23条は、現行法では第27条です）。適切でないのは③です。","items":{"1":{"t":true,"w":"個人情報保護法第29条第1項・第2項。","r":[["個人情報保護法","29"]]},"2":{"t":true,"w":"個人情報保護法第30条第1項。","r":[["個人情報保護法","30"]]},"3":{"t":false,"p":"フランチャイズ組織の本部と加盟店の間で個人データを交換する場合は、第三者提供に「該当します」。","w":"通則編ガイドライン：第三者提供とされる事例として、親子兄弟会社・グループ会社間、フランチャイズ組織の本部と加盟店の間、同業者間の交換が挙げられています。","r":[["個人情報保護法","27"]]},"4":{"t":true,"w":"金融分野ガイドライン第12条第1項。","r":[["個人情報保護法","27"]]}}},"14-47":{"s":"日本貸金業協会の貸付自粛対応に関する規則を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"貸付自粛対応に関する規則第2条第2号の定義のとおりです。"},"2":{"t":false,"p":"「いつでも」申告できるのは本人と法定代理人等です。配偶者や二親等内の親族は、本人が所在不明であるなど一定の要件をすべて満たす場合に限り申告できます。","w":"貸付自粛対応に関する規則第7条第1項・第2項。"},"3":{"t":true,"w":"貸付自粛対応に関する規則第10条第2項。"},"4":{"t":true,"w":"貸付自粛対応に関する規則第17条第1項。"}}},"14-48":{"s":"企業会計原則の一般原則を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"単一性の原則は、異なる形式の財務諸表の作成を禁じるものではなく、形式は異なってもよいが内容は信頼しうる会計記録に基づき、事実の真実な表示をゆがめてはならないという原則です。","w":"企業会計原則・一般原則七。"},"2":{"t":false,"p":"一般原則にあるのは「資本取引と損益取引」を区別し「資本剰余金と利益剰余金」を混同しないという原則で、「明確性の原則」という名称の原則はありません。","w":"企業会計原則・一般原則三。"},"3":{"t":false,"p":"正規の簿記の原則は、「高額の取引」ではなく「すべての取引」について「正確な会計帳簿」を作成することを求めるもので、「公正性の原則」という名称の原則はありません。","w":"企業会計原則・一般原則二。"},"4":{"t":true,"w":"企業会計原則・一般原則五。"}}},"14-49":{"s":"企業会計原則の貸借対照表原則を問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"企業会計原則・貸借対照表原則四㈠。"},"2":{"t":false,"p":"社債、退職給与引当金、特別修繕引当金は、流動負債ではなく「固定負債」に属します。","w":"企業会計原則・貸借対照表原則四㈡Ａ・Ｂ。"},"3":{"t":false,"p":"剰余金は欄外に注記するのではなく、資本準備金・利益準備金・その他の剰余金に区分して「記載」します（注記するのは発行済株式の数です）。","w":"企業会計原則・貸借対照表原則四㈢Ａ・Ｂ。"},"4":{"t":false,"p":"資産の価額は、原則として「期末時点の評価額」ではなく「取得原価」を基礎として計上します。","w":"企業会計原則・貸借対照表原則五。"}}},"14-50":{"s":"企業会計原則の損益計算書原則を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"企業会計原則・損益計算書原則一。"},"2":{"t":false,"p":"未実現収益は、原則として当期の損益計算に計上しては「なりません」。","w":"企業会計原則・損益計算書原則一Ａただし書。"},"3":{"t":true,"w":"企業会計原則・損益計算書原則一Ａ。"},"4":{"t":true,"w":"企業会計原則・損益計算書原則一Ｂ（総額主義の原則）。"}}},"15-01":{"s":"貸金業法第2条の用語の定義です。適切なのはａだけです（1個）。","items":{"a":{"t":true,"w":"第2条第1項第4号。","r":[["貸金業法","2"]]},"b":{"t":false,"p":"「資金需要者等」は「顧客又は債務者」ではなく「顧客等又は債務者等」で、保証人となろうとする者や保証人も「含まれます」。","w":"第2条第4項〜第6項。","r":[["貸金業法","2"]]},"c":{"t":false,"p":"記述は「個人信用情報」ではなく「信用情報」の定義です。","w":"第2条第13項（信用情報）・第14項（個人信用情報）。","r":[["貸金業法","2"]]},"d":{"t":false,"p":"住宅の改良に必要な資金の貸付けも、住宅資金貸付契約に「含まれます」。","w":"第2条第17項。","r":[["貸金業法","2"]]}}},"15-02":{"s":"登録の申請・更新・登録簿・営業所の定義を問う問題です。適切なのはａとｃです（2個）。","items":{"a":{"t":true,"w":"貸金業法施行令第3条のとおりです。","r":[["貸金業法施行令","3"]]},"b":{"t":false,"p":"更新の申請期限は「有効期間満了の日まで」ではなく、満了の日の「2月前まで」です。","w":"施行規則第5条。","r":[["貸金業法施行規則","5"]]},"c":{"t":true,"w":"第5条第1項第1号：貸金業者登録簿には、第4条第1項各号の事項（業務の種類及び方法（第8号）を含む）を登録します。","r":[["貸金業法","5"],["貸金業法","4"]]},"d":{"t":false,"p":"現金自動設備や自動契約受付機も、営業所又は事務所に「該当します」。","w":"施行規則第1条の5第3項：営業所又は事務所とは、貸付けに関する業務を継続して営む施設又は設備（自動契約受付機、現金自動設備及び代理店を含む）をいいます。","r":[["貸金業法施行規則","1の5"]]}}},"15-03":{"s":"廃業等の届出（第10条）を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"登録が効力を失うのは、清算人が届け出た時ではなく、解散した（届出事由に該当するに至った）時です。","w":"第10条第2項。","r":[["貸金業法","10"]]},"2":{"t":false,"p":"届け出るのは、存続会社などの役員ではなく、「消滅した会社を代表する役員であった者」です。","w":"第10条第1項第2号。","r":[["貸金業法","10"]]},"3":{"t":false,"p":"破産手続開始の決定があった場合に届け出るのは、本人ではなく「破産管財人」です。","w":"第10条第1項第3号。","r":[["貸金業法","10"]]},"4":{"t":true,"w":"第10条第3項。","r":[["貸金業法","10"]]}}},"15-04":{"s":"監督指針Ⅱ－2－3（外部委託）の着眼点を問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"監督指針Ⅱ－2－3の（注）のとおりです。"},"2":{"t":false,"p":"求められているのは「直ちに委託先を変更する態勢」ではなく、顧客利便に支障が生じることを「未然に防止するための態勢」です。","w":"監督指針Ⅱ－2－3④。"},"3":{"t":false,"p":"外部委託先から速やかに報告を受けるのは、監督当局ではなく「委託元」（貸金業者）です。","w":"監督指針Ⅱ－2－3⑧。"},"4":{"t":false,"p":"二段階以上の委託では、外部委託先が再委託先等に十分な監督を行っているかを確認し、必要に応じて貸金業者自身も直接監督します。外部委託先に監督を行わせないのではありません。","w":"監督指針Ⅱ－2－3⑩。"}}},"15-05":{"s":"貸金業務取扱主任者の設置（第12条の3）を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"数に含める「貸金業の業務に従事する者」には、人事・労務・経理・システム管理など、通常資金需要者等に影響が及ばない業務の従事者は原則として「含まれません」。","w":"監督指針Ⅱ－2－9：主任者の数は従業者名簿に記載されるべき従業者数で判断し、人事、総務、経理、システム管理等の業務の従事者は原則として名簿の対象になりません。","r":[["貸金業法","12の3"],["貸金業法施行規則","10の8"]]},"2":{"t":false,"p":"同じ建物内であっても、2つの営業所等を兼務する主任者を置くことは「できません」。","w":"施行規則第10条の7第2号：他の営業所等の主任者として登録されている者は、主任者として置けません。監督指針に、同じ建物なら兼務できるとする記述はありません（結論は公式正答によります）。","r":[["貸金業法施行規則","10の7"]]},"3":{"t":true,"w":"第12条の3第2項。","r":[["貸金業法","12の3"]]},"4":{"t":false,"p":"定年退職は予見できるので、2週間の猶予はありません。退職の時点で後任を置いていなければなりません。","w":"第12条の3第3項（予見し難い事由の場合のみ2週間）・監督指針Ⅱ－2－9（2）③。","r":[["貸金業法","12の3"]]}}},"15-06":{"s":"禁止行為（第12条の6）と処分・罰則・監督指針の解釈を問う問題です。適切なのはａとｃです。","items":{"a":{"t":true,"w":"第12条の6第3号違反は法令違反として、第24条の6の4第1項第2号により登録の取消し又は1年以内の業務停止の対象です。","r":[["貸金業法","12の6"],["貸金業法","24の6の4"]]},"b":{"t":false,"p":"断定的判断の提供（第12条の6第2号）は、刑事罰の対象では「ありません」（刑事罰は第1号の虚偽告知だけ）。","w":"第48条第1項第1号の2。","r":[["貸金業法","12の6"],["貸金業法","48"]]},"c":{"t":true,"w":"監督指針Ⅱ－2－10の第12条の6第1号に関する例示のとおりです。","r":[["貸金業法","12の6"]]},"d":{"t":false,"p":"「不正な」行為が「違法な行為」、「不当な」行為が「客観的に見て実質的に妥当性を欠く又は適当でない行為で、不正（違法）な程度にまで達していない行為」です。記述は定義が入れ替わっています。","w":"監督指針Ⅱ－2－10。","r":[["貸金業法","12の6"]]}}},"15-07":{"s":"利息・保証料等に係る制限（第12条の8）を問う問題です。適切なのはａとｃです。","items":{"a":{"t":true,"w":"第12条の8第1項・第4項。","r":[["貸金業法","12の8"]]},"b":{"t":false,"p":"契約の更新があっても、新たな媒介手数料を受領することは「できません」。","w":"第12条の8第10項。","r":[["貸金業法","12の8"]]},"c":{"t":true,"w":"第12条の8の保証料の確認義務のとおりです。","r":[["貸金業法","12の8"]]},"d":{"t":false,"p":"締結が禁止されるのは、「1年」ではなく「3年」を経過した日より後の日を元本確定期日とする根保証契約（又は元本確定期日の定めがないもの）です。","w":"第12条の8第9項・施行規則第10条の14第2号。","r":[["貸金業法","12の8"],["貸金業法施行規則","10の14"]]}}},"15-08":{"s":"返済能力の調査（第13条）の範囲・年収証明書・記録の保存を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"他の貸金業者を債権者とする金銭の貸借の媒介に係る契約は、信用情報の使用義務の対象から「除かれて」います。","w":"第13条第2項・施行規則第10条の16第2号・第1条の2の3第5号。","r":[["貸金業法","13"],["貸金業法施行規則","10の16"]]},"2":{"t":false,"p":"手形割引でも、法人が相手でも、返済能力の調査（第13条第1項）は「必要」です。","w":"第13条第1項は、貸付けの契約を締結しようとするすべての場合に調査を求めています（手形割引の除外は、第2項の信用情報の使用義務についてだけです）。","r":[["貸金業法","13"]]},"3":{"t":false,"p":"30万円＋他社残高70万円＝100万円は、100万円を「超えない」ので、年収証明書は「不要」です（自社の合算額も50万円以下）。","w":"第13条第3項第1号（50万円超）・第2号（100万円超）。","r":[["貸金業法","13"]]},"4":{"t":true,"w":"施行規則第10条の18第2項第1号。","r":[["貸金業法","13"],["貸金業法施行規則","10の18"]]}}},"15-09":{"s":"極度方式基本契約の極度額を増額するときの返済能力の調査（第13条第5項）を問う問題です。適切なのはｂだけです（1個）。","items":{"a":{"t":false,"p":"返済能力の低下を理由に減額した極度額を元に戻す場合は、調査が「必要」です。","w":"第13条第5項・施行規則第10条の19（例外は、連絡が取れないため一時的に減額していた場合だけ）。","r":[["貸金業法","13"],["貸金業法施行規則","10の19"]]},"b":{"t":true,"w":"第13条第5項かっこ書：極度額を下回る額を提示している場合は、その下回る額を増額する場合も、極度額の増額として調査（信用情報の使用を含む）が必要です。","r":[["貸金業法","13"]]},"c":{"t":false,"p":"増額後の極度額50万円は50万円を「超えない」ので、他社残高0円なら年収証明書は「不要」です。","w":"第13条第5項で準用する第3項第1号・第2号。","r":[["貸金業法","13"]]},"d":{"t":false,"p":"保存期限は、解除の日と最終の返済期日のうち「早い日」ではなく「遅い日」までです。","w":"施行規則第10条の18第2項。","r":[["貸金業法施行規則","10の18"]]}}},"15-10":{"s":"極度方式基本契約の途中の調査（第13条の3）を問う問題です。適切なのはｃとｄです。","items":{"a":{"t":false,"p":"要件は、1か月の貸付けの合計額が5万円を「超え」、かつ残高が10万円を「超える」ことです。5万円・10万円ちょうどなら調査は「不要」です。","w":"施行規則第10条の24第1項第1号。","r":[["貸金業法施行規則","10の24"]]},"b":{"t":false,"p":"停止の措置を解除した日から2週間以内ではなく、解除「しようとする」ときに（解除する前に）調査します。","w":"施行規則第10条の24第1項第2号。","r":[["貸金業法施行規則","10の24"]]},"c":{"t":true,"w":"施行規則第10条の24第2項（3週間を経過する日まで）。","r":[["貸金業法施行規則","10の24"]]},"d":{"t":true,"w":"第13条の3第3項：極度方式個人顧客合算額が100万円を超えるときは、年収証明書の提出を受けます（既に受けている場合を除く）。","r":[["貸金業法","13の3"]]}}},"15-11":{"s":"貸付条件等の掲示（第14条）を問う問題です。適切なのはｂとｃです。","items":{"a":{"t":false,"p":"掲示するのは主任者の「氏名」だけで、役職名や登録番号は「含まれません」。","w":"第14条第1項第4号。","r":[["貸金業法","14"]]},"b":{"t":true,"w":"第14条第1項第5号・施行規則第11条第3項第1号ロ。","r":[["貸金業法","14"],["貸金業法施行規則","11"]]},"c":{"t":true,"w":"施行規則第11条第4項。","r":[["貸金業法施行規則","11"]]},"d":{"t":false,"p":"あらかじめ定める条件により継続して貸付けを行う契約に基づく金銭の交付・回収のみを行う現金自動設備は、掲示が「不要」です。","w":"施行規則第11条（掲示の方法）ただし書。","r":[["貸金業法施行規則","11"]]}}},"15-12":{"s":"契約締結前の書面（第16条の2第1項）の記載事項です。該当するのはｂだけです（1個）。","items":{"a":{"t":false,"p":"契約申込年月日は、記載事項に「含まれません」。","w":"第16条の2第1項各号・施行規則第12条の2第1項第1号に挙げられていません。","r":[["貸金業法","16の2"],["貸金業法施行規則","12の2"]]},"b":{"t":true,"w":"第16条の2第1項第1号。","r":[["貸金業法","16の2"]]},"c":{"t":false,"p":"契約の相手方となろうとする者の氏名・住所は、記載事項に「含まれません」。","w":"第16条の2第1項各号・施行規則第12条の2第1項第1号に挙げられていません（契約締結時の書面では記載します）。","r":[["貸金業法","16の2"],["貸金業法施行規則","12の2"]]},"d":{"t":false,"p":"保証人となろうとする者の氏名・住所は、記載事項に「含まれません」。","w":"第16条の2第1項各号・施行規則第12条の2第1項第1号に挙げられていません。","r":[["貸金業法","16の2"],["貸金業法施行規則","12の2"]]}}},"15-13":{"s":"受取証書（第18条）と債権証書の返還（第22条）を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"受取証書は「遅滞なく」ではなく「直ちに」交付します。","w":"第18条第1項。","r":[["貸金業法","18"]]},"2":{"t":true,"w":"第18条第2項。","r":[["貸金業法","18"]]},"3":{"t":false,"p":"マンスリーステートメントを交付するときは、受取証書に代えて受領年月日・受領金額などを記載した書面を交付「できる」という仕組みで、「弁済から1か月以内に受取証書を交付しなければならない」という定めは「ありません」。","w":"第18条第3項。","r":[["貸金業法","18"]]},"4":{"t":false,"p":"債権証書は、債務者の請求の有無にかかわらず、遅滞なく「弁済をした者」（第三者が弁済したなら、その第三者）に返還します。","w":"第22条。","r":[["貸金業法","22"]]}}},"15-14":{"s":"自主規制基本規則第57条（取立て行為の社内態勢整備）で、「威迫」や「私生活若しくは業務の平穏を害するような言動」に該当するおそれがあるとされる例です。4つとも該当します（4個）。","items":{"a":{"t":true,"w":"自主規制基本規則第57条第2号。"},"b":{"t":true,"w":"自主規制基本規則第57条第3号（親族の冠婚葬祭時、年末年始、入院時、罹災時）。"},"c":{"t":true,"w":"自主規制基本規則第57条第5号（電話は1日に4回以上、電子メールや文書は前回から3日以内など）。"},"d":{"t":true,"w":"自主規制基本規則第57条第6号（あたかも返済義務があるような旨を伝えること、支払申出の際に支払義務がないことを伝えないことなど）。"}}},"15-15":{"s":"貸金業者に対する監督（届出・登録の取消し・社内規則の作成命令・業務改善命令）を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"貸金業を「休止」した場合も、届出が「必要」です。","w":"第24条の6の2第1号：貸金業を開始し、休止し、又は再開したとき。廃止は第10条第1項第5号の届出です。","r":[["貸金業法","24の6の2"],["貸金業法","10"]]},"2":{"t":false,"p":"公告から「2週間」ではなく「30日」を経過しても申出がないときに、登録を取り消すことができます。","w":"第24条の6の6第1項第1号。","r":[["貸金業法","24の6の6"]]},"3":{"t":true,"w":"第24条の6の12第2項（作成・変更を命ぜられた貸金業者は、30日以内に作成・変更して承認を受けます。同条第3項）。","r":[["貸金業法","24の6の12"]]},"4":{"t":false,"p":"業務改善命令は、法令違反の認定を前提とせず、利益の保護を図るため必要があると認めるときに命ずることが「できる」ものです（「命じなければならない」のではありません）。","w":"第24条の6の3第1項。","r":[["貸金業法","24の6の3"]]}}},"15-16":{"s":"保証料の上限（利息制限法第8条・第9条）と出資法の刑事罰の計算問題です（期間1年・元利一括返済）。正しいのは②です。","items":{"1":{"t":false,"p":"保証料が上限を超えても、無効になるのは「超過部分だけ」で、契約の全部が無効になるのではありません。","w":"利息制限法第8条第1項：元本100万円の法定上限額は年15%で15万円。利息13万円を引いた2万円が保証料の上限で、これを超える部分が無効です。","r":[["利息制限法","8"],["利息制限法","1"]]},"2":{"t":true,"w":"利息制限法第9条第1項：元本50万円の法定上限額は年18%で9万円。保証料1万5,000円を引くと7万5,000円（年15%）が利息の上限なので、16%のうち15%を超える部分が無効です。","r":[["利息制限法","9"],["利息制限法","1"]]},"3":{"t":false,"p":"保証料の上限は「24,000円」ではなく「16,000円」です。","w":"利息制限法第8条第2項第1号：特約上限利率を定めて通知した場合、保証料の上限は、法定上限額（元本80万円・年18%で14万4,000円）から特約上限利率（16%）で計算した利息（12万8,000円）を引いた1万6,000円です。","r":[["利息制限法","8"]]},"4":{"t":false,"p":"刑事罰の対象となるのはＣだけで、Ａは対象に「なりません」。","w":"出資法第5条の2第1項：保証料2万円は、利息（20万円×12%＝2万4,000円）と合算すると4万4,000円で年22%となり、20%を超えるので保証業者Ｃが処罰の対象です。貸主Ａの利息12%は出資法の上限（年20%）を超えておらず、保証料の契約後に利息を増加したわけでもない（第5条の3）ので、Ａは対象外です。","r":[["出資法","5の2"],["出資法","5の3"],["出資法","5"]]}}},"15-17":{"s":"登録の拒否事由（第6条第1項）に該当しないものを選ぶ問題です。該当しないのは①です。","items":{"1":{"t":false,"p":"役員だった者が拒否事由に当たるのは、取消しの日前「30日以内」に役員であった場合です。60日前に退任した者は「該当しません」。","w":"第6条第1項第3号かっこ書。","r":[["貸金業法","6"]]},"2":{"t":true,"w":"第6条第1項第2号。","r":[["貸金業法","6"]]},"3":{"t":true,"w":"第6条第1項第4号（現行法の表記は「拘禁刑以上の刑」です）。","r":[["貸金業法","6"]]},"4":{"t":true,"w":"第6条第1項第14号・施行令第3条の2（5,000万円未満）。","r":[["貸金業法","6"],["貸金業法施行令","3の2"]]}}},"15-18":{"s":"変更の届出（第8条）の対象となる事項です。適切でないのは③です。","items":{"1":{"t":true,"w":"第8条第1項・第4条第1項第1号。","r":[["貸金業法","8"],["貸金業法","4"]]},"2":{"t":true,"w":"第8条第1項・第4条第1項第2号。","r":[["貸金業法","8"],["貸金業法","4"]]},"3":{"t":false,"p":"主任者が登録の「更新」を受けても、氏名や登録番号は変わらないので、変更の届出は「不要」です。","w":"届出の対象は、第4条第1項第6号の主任者の氏名及び登録番号の変更です。","r":[["貸金業法","8"],["貸金業法","4"]]},"4":{"t":true,"w":"第8条第1項・第4条第1項第7号・施行規則第3条の2。","r":[["貸金業法","8"],["貸金業法","4"],["貸金業法施行規則","3の2"]]}}},"15-19":{"s":"監督指針Ⅱ－2－6（反社会的勢力による被害の防止）の着眼点です。適切でないのは②です。","items":{"1":{"t":true,"w":"監督指針Ⅱ－2－6⑥イ・ロのとおりです。"},"2":{"t":false,"p":"グループ内での情報共有は「行わない」のではなく、共有に「努める」こととされています。","w":"監督指針Ⅱ－2－6②イ：情報の収集・分析等に際しては、グループ内で情報の共有に努め、業界団体等から提供された情報を積極的に活用しているか。"},"3":{"t":true,"w":"監督指針Ⅱ－2－6③のとおりです。"},"4":{"t":true,"w":"監督指針Ⅱ－2－6⑤ニのとおりです。"}}},"15-20":{"s":"個人の保証人となろうとする者についての返済能力の調査を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"第13条第1項（顧客等には保証人となろうとする者を含む。第2条第4項）。","r":[["貸金業法","13"],["貸金業法","2"]]},"2":{"t":true,"w":"第13条第2項（個人である顧客等）。","r":[["貸金業法","13"]]},"3":{"t":true,"w":"第13条第3項の年収証明書の提出義務は、資金需要者である「個人顧客」についてのもので、保証人となろうとする者は対象外です。","r":[["貸金業法","13"]]},"4":{"t":false,"p":"保証契約の調査記録の保存期限は、解除の日と債務が消滅した日のうち「遅い日」ではなく「早い日」です。","w":"施行規則第10条の18第2項第2号：主たる貸付けの最終の返済期日などの日又は保証契約に基づく債務が消滅した日のうちいずれか早い日。","r":[["貸金業法施行規則","10の18"]]}}},"15-21":{"s":"総量規制の除外契約（施行規則第10条の21）に該当しないものを選ぶ問題です。該当しないのは③です。","items":{"1":{"t":true,"w":"施行規則第10条の21第1項第4号。","r":[["貸金業法施行規則","10の21"]]},"2":{"t":true,"w":"施行規則第10条の21第1項第3号。","r":[["貸金業法施行規則","10の21"]]},"3":{"t":false,"p":"不動産担保貸付けの除外契約からは、個人顧客や担保を提供する者の「居宅」は除かれているので、居宅を担保とする貸付けは「該当しません」。","w":"施行規則第10条の21第1項第6号かっこ書。","r":[["貸金業法施行規則","10の21"]]},"4":{"t":true,"w":"施行規則第10条の21第1項第8号・第1条の2の3第2号。","r":[["貸金業法施行規則","10の21"],["貸金業法施行規則","1の2の3"]]}}},"15-22":{"s":"保証契約を締結する前後に保証人へ交付する書面（第16条の2第3項・第17条第3項・第4項）を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"第16条の2第3項・施行規則第12条の2：保証契約の概要を記載した書面と詳細を記載した書面を同時に交付します（現行の施行規則では第7項に定められています）。","r":[["貸金業法","16の2"],["貸金業法施行規則","12の2"]]},"2":{"t":true,"w":"第17条第3項・第4項。","r":[["貸金業法","17"]]},"3":{"t":false,"p":"保証契約の契約締結時の書面（第17条第3項）の交付先は、貸付けの相手方（主たる債務者）ではなく「保証人」です。","w":"第17条第3項。","r":[["貸金業法","17"]]},"4":{"t":true,"w":"第17条第3項後段・施行規則第13条第7項第1号イ：保証期間（第16条の2第3項第2号）の変更は、保証人の利益となる変更を除き、再交付が必要です。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]}}},"15-23":{"s":"契約締結時の書面を再交付しなければならない変更（施行規則第13条第2項）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"貸付けの利率（第17条第1項第4号）は施行規則第13条第2項第1号イの事項で、引上げは相手方の利益となる変更ではないので再交付が必要です。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"2":{"t":true,"w":"返済の方式（第17条第1項第5号）は施行規則第13条第2項第1号ロの事項で、変更すれば再交付が必要です。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"3":{"t":true,"w":"返済の方法及び返済を受ける場所（施行規則第13条第1項第1号ト）は同条第2項第1号ロの事項で、利益となる変更でも再交付が必要です。","r":[["貸金業法施行規則","13"]]},"4":{"t":false,"p":"返済期日前の返済の可否・内容（施行規則第13条第1項第1号リ）は、相手方の利益となる変更であれば、再交付は「不要」です。","w":"施行規則第13条第2項第1号イかっこ書。","r":[["貸金業法施行規則","13"]]}}},"15-24":{"s":"貸金業者が保存すべきものの保存期間です。適切でないのは③です。","items":{"1":{"t":true,"w":"施行規則第10条の9の2第3項。","r":[["貸金業法施行規則","10の9の2"]]},"2":{"t":true,"w":"施行規則第10条の21第2項第1号。","r":[["貸金業法施行規則","10の21"]]},"3":{"t":false,"p":"基準額超過極度方式基本契約の調査記録の保存期間は、最終の返済期日などまでではなく、作成後「3年間」です。","w":"施行規則第10条の27第2項。","r":[["貸金業法施行規則","10の27"]]},"4":{"t":true,"w":"施行規則第17条第1項ただし書（極度方式基本契約の場合）。","r":[["貸金業法施行規則","17"]]}}},"15-25":{"s":"監督指針Ⅱ－2－8（不祥事件）の監督上の対応です。合致しないのは①です。","items":{"1":{"t":false,"p":"第一報があった場合に監督当局が確認するのは、内部管理部門・経営陣への報告、警察等への「通報」、独立した部署での調査・解明です。直ちに立入検査をして証拠保全を確認する、という記載は「ありません」。","w":"監督指針Ⅱ－2－8（1）①イ〜ハ。"},"2":{"t":true,"w":"監督指針Ⅱ－2－8（1）②のとおりです。"},"3":{"t":true,"w":"監督指針Ⅱ－2－8（2）のとおりです。","r":[["貸金業法","24の6の10"]]},"4":{"t":true,"w":"監督指針Ⅱ－2－8（2）のとおりです。","r":[["貸金業法","24の6の3"],["貸金業法","24の6の4"]]}}},"15-26":{"s":"個人信用情報の提供（第41条の35）と同意（第41条の36）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"極度方式基本契約そのものは、個人信用情報の提供の対象から「除かれて」います。","w":"第41条の35第2項・第2条第14項・施行規則第1条の2の3第1号。","r":[["貸金業法","41の35"],["貸金業法施行規則","1の2の3"]]},"2":{"t":true,"w":"第41条の36第1項。","r":[["貸金業法","41の36"]]},"3":{"t":true,"w":"第41条の35第3項。","r":[["貸金業法","41の35"]]},"4":{"t":true,"w":"施行規則第30条の16第1項。","r":[["貸金業法施行規則","30の16"]]}}},"15-27":{"s":"みなし利息の例外（利息制限法第6条・施行令）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"利息制限法第6条第2項第3号・施行令第2条第1号（1万円以下は110円まで）。","r":[["利息制限法","6"],["利息制限法施行令","2"]]},"2":{"t":true,"w":"利息制限法第6条第1項・施行令第1条第1号。","r":[["利息制限法","6"],["利息制限法施行令","1"]]},"3":{"t":true,"w":"例外は「債務者の要請により」行う書面の再発行の手数料です（利息制限法第6条第1項・施行令第1条第2号）。契約内容の変更で法律上再交付が必要になった書面の費用はこれに当たらないので、第3条により利息とみなされます（結論は公式正答によります）。","r":[["利息制限法","6"],["利息制限法","3"],["利息制限法施行令","1"]]},"4":{"t":false,"p":"再度の口座振替手続の費用は、利息と「みなされません」。","w":"利息制限法第6条第1項・施行令第1条第3号。","r":[["利息制限法","6"],["利息制限法施行令","1"]]}}},"15-28":{"s":"意思能力と行為能力を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"成年被後見人の行為は、成年後見人の同意を得ていても取り消すことが「できます」。","w":"民法第9条。","r":[["民法","9"]]},"2":{"t":false,"p":"詐術を用いた場合は、制限行為能力者本人だけでなく、法定代理人も取り消すことが「できません」。","w":"民法第21条。","r":[["民法","21"]]},"3":{"t":false,"p":"営業を許されても成年に達したとみなされるのではなく、「その営業に関して」成年者と同一の行為能力を有するだけです。","w":"民法第6条第1項。","r":[["民法","6"]]},"4":{"t":true,"w":"民法第3条の2。","r":[["民法","3の2"]]}}},"15-29":{"s":"意思表示（錯誤・第三者の詐欺・強迫・虚偽表示）を問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"民法第95条第3項第1号：表意者に重大な過失があっても、相手方が錯誤を知り又は重大な過失によって知らなかったときは、取り消すことができます。","r":[["民法","95"]]},"2":{"t":false,"p":"第三者が詐欺をした場合、取り消せるのは相手方Ｂがその事実を知り又は知ることができたときに限られます。Ｂが善意無過失なら取り消せ「ません」。","w":"民法第96条第2項。","r":[["民法","96"]]},"3":{"t":false,"p":"強迫による取消しは、善意無過失の第三者にも対抗「できます」。","w":"民法第96条第3項（第三者保護は詐欺だけ）。","r":[["民法","96"]]},"4":{"t":false,"p":"虚偽表示の無効を対抗できないのは「善意」の第三者です。事情を知っているＣには、無効を主張「できます」。","w":"民法第94条第2項。","r":[["民法","94"]]}}},"15-30":{"s":"無効と取消しを問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"無効と知って追認すると、初めから有効になるのではなく、「新たな行為をしたもの」とみなされます。","w":"民法第119条。","r":[["民法","119"]]},"2":{"t":true,"w":"民法第120条第1項。","r":[["民法","120"]]},"3":{"t":false,"p":"取り消された行為は、将来に向かってではなく「初めから無効」であったものとみなされます。","w":"民法第121条。","r":[["民法","121"]]},"4":{"t":false,"p":"取消権の期間は「3年・5年」ではなく、追認できる時から「5年」、行為の時から「20年」です。","w":"民法第126条。","r":[["民法","126"]]}}},"15-31":{"s":"抵当権の効力の範囲・順位・処分・消滅時効を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"土地の抵当権の効力は、土地の上に存する「建物には及びません」（付加して一体となっている物には及びます）。","w":"民法第370条。","r":[["民法","370"]]},"2":{"t":false,"p":"抵当権の順位は、契約の締結日ではなく「登記の前後」によります。","w":"民法第373条。","r":[["民法","373"]]},"3":{"t":true,"w":"民法第376条第1項（転抵当、抵当権の譲渡・放棄、順位の譲渡・放棄）。","r":[["民法","376"]]},"4":{"t":false,"p":"抵当権は、債務者と抵当権設定者に対しては、担保する債権と「同時でなければ」時効によって消滅しません。","w":"民法第396条。","r":[["民法","396"]]}}},"15-32":{"s":"債務不履行（損害賠償の範囲・履行遅滞・過失相殺・法定利率）を問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"民法第416条第1項・第2項。","r":[["民法","416"]]},"2":{"t":false,"p":"不確定期限の場合は、「期限の到来を知り、かつ請求を受けた時」ではなく、期限到来後に請求を受けた時「又は」期限の到来を知った時の「いずれか早い時」から遅滞になります。","w":"民法第412条第2項。","r":[["民法","412"]]},"3":{"t":false,"p":"債権者に過失があったときは、裁判所はこれを考慮して、損害賠償の責任と額を「定めます」（過失相殺）。減免できないわけではありません。","w":"民法第418条。","r":[["民法","418"]]},"4":{"t":false,"p":"法定利率は「年5分」ではなく「年3パーセント」です（3年ごとに見直される変動制）。","w":"民法第404条第2項・第3項。","r":[["民法","404"]]}}},"15-33":{"s":"相殺（弁済期・時効消滅した債権・差押え・破産）を問う問題です。Ａから見ると甲債権が自働債権です。正しいのは④です。","items":{"1":{"t":false,"p":"相殺に使う甲債権の弁済期が来ていれば、乙債権（受働債権）の弁済期が未到来でも、Ａは期限の利益を放棄して相殺「できます」。","w":"民法第505条第1項・第136条第2項（期限の利益は放棄できる）。受働債権の期限の利益を放棄して相殺できるというのは判例の考え方です。","r":[["民法","505"],["民法","136"]]},"2":{"t":false,"p":"時効消滅前に相殺適状になっていれば、時効消滅後も相殺「できます」。","w":"民法第508条。","r":[["民法","508"]]},"3":{"t":false,"p":"差押命令の送達後に取得した債権による相殺は、差押債権者Ｃに対抗「できません」。","w":"民法第511条第1項。","r":[["民法","511"]]},"4":{"t":true,"w":"破産法第67条第1項：破産債権者は、破産手続開始の時に破産者に対して債務を負担するときは、破産手続によらないで相殺できます。","r":[["破産法","67"]]}}},"15-34":{"s":"相続（代襲相続・法定相続分・遺留分・熟慮期間）を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"欠格事由で相続人になれなくなった者の子は、代襲相続人に「なれます」。","w":"民法第887条第2項（代襲原因は死亡・欠格・廃除）。","r":[["民法","887"]]},"2":{"t":false,"p":"配偶者と兄弟姉妹が相続人のとき、兄弟姉妹の相続分は3分の1ではなく「4分の1」です。","w":"民法第900条第3号。","r":[["民法","900"]]},"3":{"t":true,"w":"民法第1042条第1項第2号：直系尊属のみが相続人である場合以外は、遺留分は2分の1です（兄弟姉妹には遺留分はありません）。","r":[["民法","1042"]]},"4":{"t":false,"p":"熟慮期間は「6か月」ではなく「3か月」です。","w":"民法第915条第1項。","r":[["民法","915"]]}}},"15-35":{"s":"手形の抗弁・遡求と、電子記録債権を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"所持人が債務者を害することを知って手形を取得したときは、人的抗弁をもって対抗「できます」。","w":"手形法第17条ただし書（第77条第1項第1号で準用）。強迫による取消しが人的抗弁に当たることは、判例の考え方です（条文には直接書かれていません）。","r":[["手形法","17"],["手形法","77"]]},"2":{"t":false,"p":"満期前でも、法律の定める場合（引受拒絶や破産手続開始など）には遡求権を行使「できます」。","w":"手形法第43条（約束手形には第77条第1項第4号で準用）。約束手形で満期前の支払拒絶などにより遡求できるかの結論は公式正答によります。","r":[["手形法","43"],["手形法","77"]]},"3":{"t":false,"p":"電子記録債権の譲渡は、合意だけでは効力を生じず、「譲渡記録をしなければ効力を生じません」（対抗要件ではなく効力要件）。","w":"電子記録債権法第17条。","r":[["電子記録債権法","17"]]},"4":{"t":true,"w":"電子記録債権法第21条。","r":[["電子記録債権法","21"]]}}},"15-36":{"s":"犯罪収益移転防止法（事業内容の確認・確認記録・取引記録・疑わしい取引の届出）を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"登記事項証明書は「1年以内」ではなく、確認する日前「6月以内」に作成されたものに限られます。","w":"犯罪収益移転防止法施行規則第10条第1項第2号ハ・柱書。","r":[["犯罪収益移転防止法施行規則","10"]]},"2":{"t":false,"p":"確認記録の保存期間は「3年間」ではなく「7年間」です。","w":"犯罪収益移転防止法第6条第2項。","r":[["犯罪収益移転防止法","6"]]},"3":{"t":true,"w":"犯罪収益移転防止法第7条第1項・第3項。","r":[["犯罪収益移転防止法","7"]]},"4":{"t":false,"p":"疑わしい取引の届出を行おうとすること又は行ったことを、顧客等やその関係者に漏らしては「なりません」。","w":"犯罪収益移転防止法第8条第4項。","r":[["犯罪収益移転防止法","8"]]}}},"15-37":{"s":"代理（顕名・復代理・代理権の消滅・表見代理）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"権限内で本人のためにすることを示した意思表示は、本人の承認や追認がなくても、本人に対して直接に効力を「生じます」。","w":"民法第99条第1項。","r":[["民法","99"]]},"2":{"t":true,"w":"民法第105条。","r":[["民法","105"]]},"3":{"t":true,"w":"民法第111条第1項第1号。","r":[["民法","111"]]},"4":{"t":true,"w":"民法第112条第1項。","r":[["民法","112"]]}}},"15-38":{"s":"時効の完成猶予と更新を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"民法第147条第2項。","r":[["民法","147"]]},"2":{"t":true,"w":"民法第148条第1項。","r":[["民法","148"]]},"3":{"t":false,"p":"仮差押えは時効の「更新」事由ではなく、「完成猶予」事由です（終了の時から6か月を経過するまで時効は完成しません）。","w":"民法第149条第1号。","r":[["民法","149"]]},"4":{"t":true,"w":"民法第166条第1項。","r":[["民法","166"]]}}},"15-39":{"s":"事業資金の借入れの個人保証（保証意思宣明公正証書・情報提供義務）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"保証意思宣明公正証書は、保証人が自分で文書を作って公証人が認証する方式ではなく、保証人が公証人に「口授」し、公証人が筆記して読み聞かせ等を行い、保証人が署名押印する方式で作成します。","w":"民法第465条の6第2項第1号〜第4号。","r":[["民法","465の6"]]},"2":{"t":true,"w":"民法第458条の3第2項。","r":[["民法","458の3"]]},"3":{"t":true,"w":"民法第465条の6第1項：締結の日前1箇月以内に作成された公正証書で保証債務を履行する意思を表示していなければ、効力を生じません。","r":[["民法","465の6"]]},"4":{"t":true,"w":"民法第465条の10第1項第1号〜第3号。","r":[["民法","465の10"]]}}},"15-40":{"s":"弁済（効果・第三者弁済・場所・提供の効果）を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"民法第473条。","r":[["民法","473"]]},"2":{"t":false,"p":"正当な利益を有しない第三者でも、債務者・債権者の意思に反しなければ弁済「できます」。","w":"民法第474条第1項〜第3項：正当な利益を有しない第三者は、債務者の意思に反して（第2項）、又は債権者の意思に反して（第3項）弁済することができない、という制限です。","r":[["民法","474"]]},"3":{"t":true,"w":"民法第484条第1項。","r":[["民法","484"]]},"4":{"t":true,"w":"民法第492条。","r":[["民法","492"]]}}},"15-41":{"s":"消費貸借契約（期限前返還・書面による消費貸借・準消費貸借・利息）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"民法第591条第2項。","r":[["民法","591"]]},"2":{"t":true,"w":"民法第587条の2第2項。","r":[["民法","587の2"]]},"3":{"t":true,"w":"民法第588条（準消費貸借）。","r":[["民法","588"]]},"4":{"t":false,"p":"利息の特約がなければ、貸主は利息を請求「できません」。","w":"民法第589条第1項。","r":[["民法","589"]]}}},"15-42":{"s":"2020年4月1日施行の民法改正の経過措置（どちらの民法が適用されるか）を問う問題です。経過措置は改正法の附則に定められていますが、取り込んだ法令データには附則が含まれていないため、結論は公式正答によります。適切でないのは②です。","items":{"1":{"t":true,"w":"結論は公式正答によります（施行日前に生じた債権の消滅時効の期間には改正前民法が適用される、とされています）。"},"2":{"t":false,"p":"施行日（2020年4月1日）より後に債権譲渡の契約をした場合は、改正前民法ではなく「改正民法」が適用され、譲渡制限の特約があっても債権譲渡は有効です（改正民法第466条第2項）。","w":"結論は公式正答によります（附則を確認できません）。","r":[["民法","466"]]},"3":{"t":true,"w":"結論は公式正答によります（定型約款の規定は、施行日前に締結された定型取引に係る契約にも、反対の意思表示がない限り適用される、とされています）。"},"4":{"t":true,"w":"天災等による時効の完成猶予（民法第161条：障害が消滅した時から3箇月）。施行日以後に事由が生じた場合に改正民法が適用されることの結論は公式正答によります。","r":[["民法","161"]]}}},"15-43":{"s":"個人情報保護法ガイドライン（通則編）の利用目的に関する記述です（第15回の時点の第15条は、現行法では第17条です）。正しいのは④です。","items":{"1":{"t":false,"p":"「マーケティング活動に用いるため」は、具体的に利用目的を特定して「いない」事例とされています。","w":"通則編ガイドライン（利用目的の特定）：「事業活動に用いるため」「マーケティング活動に用いるため」は、具体的に利用目的を特定していない事例です。","r":[["個人情報保護法","17"]]},"2":{"t":false,"p":"本人の同意を得るために個人情報を利用すること（メールの送信や電話など）は、当初の利用目的に記載がなくても、目的外利用に「該当しません」。","w":"通則編ガイドライン（利用目的による制限）。","r":[["個人情報保護法","18"]]},"3":{"t":false,"p":"インターネット上で本人が自発的に公にしている個人情報を取得した場合も、利用目的を公表していなければ、本人への通知又は公表が「必要」です（単に閲覧しただけの場合を除く）。","w":"通則編ガイドライン（取得に際しての利用目的の通知等）：本人への通知又は公表が必要な事例として挙げられています。","r":[["個人情報保護法","21"]]},"4":{"t":true,"w":"個人情報保護法第21条第2項（本人から直接書面で取得する場合は、あらかじめ利用目的を明示。人の生命、身体又は財産の保護のために緊急に必要がある場合は除く）。","r":[["個人情報保護法","21"]]}}},"15-44":{"s":"消費者契約法の取消し・取消権の期間・不当条項を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"消費者契約法には、無条件で撤回・解除できるクーリング・オフの定めは「ありません」。","w":"消費者契約法が定めるのは、不当な勧誘による取消し（第4条）や不当条項の無効（第8条〜第10条）などです。","r":[["消費者契約法","4"]]},"2":{"t":false,"p":"不退去などによる困惑で締結された契約を取り消せるのは「消費者」です。適格消費者団体には取消権は「ありません」（団体ができるのは差止請求です）。","w":"消費者契約法第4条第3項（取消し）・第12条（適格消費者団体の差止請求）。","r":[["消費者契約法","4"],["消費者契約法","12"]]},"3":{"t":true,"w":"消費者契約法第7条第1項。","r":[["消費者契約法","7"]]},"4":{"t":false,"p":"無効になるのは条項そのものではなく、平均的な損害の額を「超える部分」だけです。","w":"消費者契約法第9条第1項第1号。","r":[["消費者契約法","9"]]}}},"15-45":{"s":"協会の自主規制基本規則と広告に関する細則を問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"自主規制基本規則第54条第1項第1号。"},"2":{"t":false,"p":"勧誘リストに信用情報を記載することは、信用情報の目的外使用として「禁止」されています。","w":"自主規制基本規則第39条の3第2項第1号：勧誘又は勧誘リストの作成を目的として信用情報を使用すること、勧誘リスト等に信用情報について記載等をすることは禁止されます。","r":[["貸金業法","41の38"]]},"3":{"t":false,"p":"ギャンブル専門紙・誌は、表現に留意すれば出稿してよい媒体として定められているのではなく、「掲出に留意する」出稿先とされています。","w":"貸金業者の広告に関する細則Ⅰ．4．⑷。"},"4":{"t":false,"p":"比較広告は、根拠を説明できる態勢を整えれば行えるのではなく、原則として「行わない」とされています。","w":"貸金業者の広告に関する細則Ⅰ．4．⑶②。"}}},"15-46":{"s":"景品表示法（表示の定義・措置命令・不実証広告・管理上の措置）を問う問題です（第15回の時点の第26条は、現行法では第22条・第24条です）。適切でないのは②です。","items":{"1":{"t":true,"w":"景品表示法第2条第4項。","r":[["景品表示法","2"]]},"2":{"t":false,"p":"措置命令は、違反行為が既になくなっている場合でも「することができます」。","w":"景品表示法第7条第1項後段。","r":[["景品表示法","7"]]},"3":{"t":true,"w":"景品表示法第7条第2項。","r":[["景品表示法","7"]]},"4":{"t":true,"w":"景品表示法第22条第1項（事業者が講ずべき管理上の措置）・第24条（勧告及び公表）。","r":[["景品表示法","22"],["景品表示法","24"]]}}},"15-47":{"s":"日本貸金業協会の紛争解決等業務に関する規則を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"紛争解決等業務に関する規則（協会員等の応諾義務）のとおりです。第41条の44第2項第2号でも、加入貸金業者は正当な理由なく手続に応じることを拒めません。","r":[["貸金業法","41の44"]]},"2":{"t":true,"w":"紛争解決等業務に関する規則（紛争解決委員による意見聴取・資料提出の求め）のとおりです。協会員等は正当な理由なくこれを拒めません（第85条）。"},"3":{"t":false,"p":"当事者双方が和解案を受諾した時点で和解が成立します。「裁判所に届け出ることにより」成立するのではありません。","w":"紛争解決等業務に関する規則第89条第2項。"},"4":{"t":true,"w":"紛争解決等業務に関する規則第90条第1項。"}}},"15-48":{"s":"損益計算書の段階利益の名前を問う穴埋め問題です。正しいのは①です（ａ売上総利益・ｂ営業利益・ｃ経常利益）。","items":{"1":{"t":true,"w":"企業会計原則・損益計算書原則：売上高3,850−売上原価2,950＝（ａ）売上総利益900、900−販売費及び一般管理費730＝（ｂ）営業利益170、170−営業外費用20＋営業外収益3＝（ｃ）経常利益153、153＋特別利益0−特別損失1＝税引前当期純利益152です（損益計算書原則三・五・七）。"},"2":{"t":false,"p":"ａは「経常利益」ではなく「売上総利益」、ｃは「売上総利益」ではなく「経常利益」です。"},"3":{"t":false,"p":"ｂは「粗利益」ではなく「営業利益」です。"},"4":{"t":false,"p":"ａは「粗利益」、ｂは「売上総利益」、ｃは「営業利益」ではありません。正しくはａ売上総利益・ｂ営業利益・ｃ経常利益です。"}}},"15-49":{"s":"企業会計原則の一般原則（7つ）を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"企業会計原則・一般原則一（真実性の原則）。"},"2":{"t":true,"w":"企業会計原則・一般原則四（明瞭性の原則）。"},"3":{"t":false,"p":"「堅実性の原則」という一般原則は「ありません」。一般原則は、真実性・正規の簿記・資本取引と損益取引の区分・明瞭性・継続性・保守主義・単一性の7つです。","w":"企業会計原則・一般原則一〜七。"},"4":{"t":true,"w":"企業会計原則・一般原則七（単一性の原則）。"}}},"15-50":{"s":"貸借対照表の区分と科目の分類を問う問題です。会社計算規則は取り込んでいないため、同じ考え方を定めた企業会計原則の貸借対照表原則で確認できる範囲で説明します。適切でないのは②です。","items":{"1":{"t":true,"w":"企業会計原則・貸借対照表原則四㈠Ｂ：固定資産は、有形固定資産、無形固定資産及び投資その他の資産に区分します（会社計算規則についての結論は公式正答によります）。"},"2":{"t":false,"p":"資産の部の区分は「流動資産、固定資産及び金融資産」ではなく、「流動資産、固定資産及び繰延資産」です。","w":"企業会計原則・貸借対照表原則二。"},"3":{"t":true,"w":"企業会計原則・貸借対照表原則四㈡Ｂ：社債、長期借入金等の長期債務は固定負債に属します。"},"4":{"t":true,"w":"結論は公式正答によります（未払費用が流動負債に属すること）。"}}},"16-01":{"s":"貸金業法第2条の用語の定義です。適切なのはａだけです（1個）。","items":{"a":{"t":true,"w":"第2条第1項第3号。","r":[["貸金業法","2"]]},"b":{"t":false,"p":"「債務者等」は「債務者又は債務者であった者」ではなく、「債務者又は保証人」です。保証人は含まれます。","w":"第2条第5項。","r":[["貸金業法","2"]]},"c":{"t":false,"p":"「貸付けの契約」は、貸付けに係る契約又は当該契約に係る保証契約をいい、「資金需要者等の利益を損なうおそれがないと認められるもの」という限定は「ありません」。","w":"第2条第3項。","r":[["貸金業法","2"]]},"d":{"t":false,"p":"手続実施基本契約は、三者間ではなく、「指定紛争解決機関と貸金業者との間」で締結される契約です。","w":"第2条第23項。","r":[["貸金業法","2"]]}}},"16-02":{"s":"登録の申請先・更新・記載事項を問う問題です。適切なのはｂとｄです。","items":{"a":{"t":false,"p":"2以上の都道府県に営業所を設置する場合は、都道府県知事を「経由」せず、内閣総理大臣に登録申請書を提出します。","w":"第4条第1項。","r":[["貸金業法","4"]]},"b":{"t":true,"w":"施行規則第5条：有効期間満了の日の2月前までに申請します。","r":[["貸金業法施行規則","5"]]},"c":{"t":false,"p":"記載するのは、主任者の「氏名及び住所」ではなく「氏名及び登録番号」です。","w":"第4条第1項第6号。","r":[["貸金業法","4"]]},"d":{"t":true,"w":"第3条第2項。","r":[["貸金業法","3"]]}}},"16-03":{"s":"変更の届出（第8条）です。「あらかじめ」届け出るのは、営業所の名称・所在地（第4条第1項第5号）と広告等に表示する連絡先（第7号）だけです。正しいのは②です。","items":{"1":{"t":false,"p":"商号・名称・氏名の変更は、「あらかじめ」ではなく、変更があった日から「2週間以内」に届け出ます。","w":"第8条第1項・第4条第1項第1号。","r":[["貸金業法","8"],["貸金業法","4"]]},"2":{"t":true,"w":"第8条第1項・第4条第1項第7号・施行規則第3条の2第1項第1号。","r":[["貸金業法","8"],["貸金業法","4"],["貸金業法施行規則","3の2"]]},"3":{"t":false,"p":"業務の種類及び方法の変更は、「あらかじめ」ではなく、変更があった日から「2週間以内」に届け出ます。","w":"第8条第1項・第4条第1項第8号。","r":[["貸金業法","8"],["貸金業法","4"]]},"4":{"t":false,"p":"他に行う事業の種類の変更は、「あらかじめ」ではなく、変更があった日から「2週間以内」に届け出ます。","w":"第8条第1項・第4条第1項第9号。","r":[["貸金業法","8"],["貸金業法","4"]]}}},"16-04":{"s":"監督指針の経営管理等・法令等遵守の着眼点を問う問題です。適切なのはｂとｄです。","items":{"a":{"t":false,"p":"協会の自主規制規則に則った内容が求められるのは、協会員に限られません。非協会員の社内規則等も同じです。","w":"監督指針Ⅱ－2（業務の適切性）：社内規則等の内容については、協会の策定する自主規制規則に則った内容が求められます（協会員かどうかで区別していません）。"},"b":{"t":true,"w":"監督指針（経営管理等の着眼点）⑤と、「内部管理部門」の定義（注）のとおりです。"},"c":{"t":false,"p":"自己検証の頻度は「年3回以上」ではなく、「少なくとも月1回以上」です。","w":"監督指針（経営管理等の着眼点・内部監査に代わる措置）。"},"d":{"t":true,"w":"監督指針（経営管理等の着眼点）②のとおりです。"}}},"16-05":{"s":"従業者に証明書を携帯させる義務（第12条の4第1項）の対象となる者を問う問題です。適切なのはａとｄです。","items":{"a":{"t":true,"w":"第12条の4第1項は「貸金業の業務に従事する」使用人その他の従業者に証明書を携帯させる義務です。監督指針Ⅱ－2－9（2）②は、従業者名簿について、システム管理等その業務遂行の影響が通常資金需要者等に及ばない業務に従事する者は原則として該当しないとしています（証明書についての結論は公式正答によります）。","r":[["貸金業法","12の4"]]},"b":{"t":false,"p":"勧誘を伴わない広告のみを行う業務の従事者には、証明書を携帯させる必要は「ありません」（公式正答による）。","w":"結論は公式正答によります。取り込んだ資料に、広告のみの従事者を直接扱った記述はありません。","r":[["貸金業法","12の4"]]},"c":{"t":false,"p":"派遣労働者でも、貸金業の業務に従事させる以上、証明書の携帯は「必要」です。","w":"第12条の4第1項は「使用人その他の従業者」と定め、雇用関係に限っていません。監督指針Ⅱ－2－9（2）②も、営業・審査・回収などに従事する者は雇用関係・雇用形態を問わず従業者名簿の対象になるとしています。","r":[["貸金業法","12の4"]]},"d":{"t":true,"w":"施行規則第10条の9第1項第2号：貸金業者の委託により貸金業の業務に従事する場合の証明書の記載事項（委託した貸金業者の商号等、委託された者の商号等、委託した旨）が定められています。","r":[["貸金業法","12の4"],["貸金業法施行規則","10の9"]]}}},"16-06":{"s":"監督指針Ⅱ－2－10（禁止行為）で、第12条の6第4号の「偽りその他不正又は著しく不当な行為」に当たるおそれが大きいとされる例です。4つとも該当します（4個）。","items":{"a":{"t":true,"w":"監督指針Ⅱ－2－10のイｄのとおりです。","r":[["貸金業法","12の6"]]},"b":{"t":true,"w":"監督指針Ⅱ－2－10のホのとおりです。","r":[["貸金業法","12の6"]]},"c":{"t":true,"w":"監督指針Ⅱ－2－10のヘのとおりです。","r":[["貸金業法","12の6"]]},"d":{"t":true,"w":"監督指針Ⅱ－2－10のチのとおりです。","r":[["貸金業法","12の6"]]}}},"16-07":{"s":"総量規制で年収に含められる「年間の給与に類する定期的な収入」（施行規則第10条の22第1項）です。該当するのはａ・ｃ・ｄです（3個）。","items":{"a":{"t":true,"w":"施行規則第10条の22第1項第1号。","r":[["貸金業法施行規則","10の22"]]},"b":{"t":false,"p":"投資信託の分配金は、年間の給与に類する定期的な収入に「含まれません」。","w":"施行規則第10条の22第1項に挙げられているのは、年金、恩給、定期的に受領する不動産の賃貸収入（事業として行う場合を除く）、事業所得（安定的と認められるもの）です。","r":[["貸金業法施行規則","10の22"]]},"c":{"t":true,"w":"施行規則第10条の22第1項第3号。","r":[["貸金業法施行規則","10の22"]]},"d":{"t":true,"w":"施行規則第10条の22第1項第4号。","r":[["貸金業法施行規則","10の22"]]}}},"16-08":{"s":"総量規制の除外契約（施行規則第10条の21）の要件です。適切なのはａとｂです。","items":{"a":{"t":true,"w":"施行規則第10条の21第1項第1号：不動産の改良に必要な資金の貸付けは、担保の有無を問わず除外契約です。","r":[["貸金業法施行規則","10の21"]]},"b":{"t":true,"w":"施行規則第10条の21第1項第2号：「自ら又は他の者により」不動産購入資金などの貸付けが行われるまでのつなぎ融資。他の者が金融機関に限られる定めはありません（金融機関に限るのは、例外契約のつなぎ融資（第10条の23第1項第6号）の方です）。","r":[["貸金業法施行規則","10の21"],["貸金業法施行規則","10の23"]]},"c":{"t":false,"p":"貸付けの金額は、契約締結時の不動産の価格の範囲内であるものに「限られます」。超える場合は除外契約に「該当しません」。","w":"施行規則第10条の21第1項第7号。","r":[["貸金業法施行規則","10の21"]]},"d":{"t":false,"p":"自動車購入資金の貸付けは、自動車の所有権を貸金業者が取得するか、譲渡担保の目的となっているものに「限られます」。","w":"施行規則第10条の21第1項第3号。","r":[["貸金業法施行規則","10の21"]]}}},"16-09":{"s":"極度方式基本契約の途中の調査（第13条の3）の要件です。正しいのは④です。","items":{"1":{"t":false,"p":"1か月の貸付けの合計額が5万円を「超え」、かつ残高が10万円を超えることが要件です。5万円ちょうどなら調査は「不要」です。","w":"施行規則第10条の24第1項第1号。","r":[["貸金業法施行規則","10の24"]]},"2":{"t":false,"p":"年収証明書が必要なのは、極度方式個人顧客合算額が100万円を「超える」ときです。70万円なら「不要」です。","w":"第13条の3第3項。","r":[["貸金業法","13の3"]]},"3":{"t":false,"p":"極度額の「減額」の措置では、定期調査は免除されません。免除されるのは新たな貸付けの「停止」の措置などです。","w":"施行規則第10条の25第3項第2号・第10条の29第2号。","r":[["貸金業法施行規則","10の25"],["貸金業法施行規則","10の29"]]},"4":{"t":true,"w":"施行規則第10条の24第1項第2号：新たな貸付けの停止の措置を解除しようとする場合は、調査の要件に該当します。","r":[["貸金業法施行規則","10の24"]]}}},"16-10":{"s":"貸付条件の広告（第15条）と、協会の広告規制（自主規制基本規則・貸金業者の広告に関する細則）を問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"施行規則第12条第1項第3号：登録されたホームページアドレス又は電子メールアドレスを表示するときは、登録された電話番号も表示します。","r":[["貸金業法","15"],["貸金業法施行規則","12"]]},"2":{"t":false,"p":"「主な返済の例」は、広告の表示事項ではなく、営業所ごとの「貸付条件等の掲示」（第14条）の事項です。","w":"広告の表示事項は施行規則第12条第1項第1号（返済の方式・返済期間・返済回数、賠償額の予定の割合、担保に関する事項）。主な返済の例は施行規則第11条第3項第1号ハ（掲示事項）です。","r":[["貸金業法施行規則","12"],["貸金業法施行規則","11"]]},"3":{"t":false,"p":"比較広告は「合理的根拠に基づけば行える」のではなく、原則として「行わない」とされています。","w":"貸金業者の広告に関する細則Ⅰ．4．⑶：①安易な借入れを助長する表現の排除、②比較広告を行わないこと（施行規則第10条の23第1項第1号又は第1号の2に関する広告を除く）、③ホームページアドレスを表示する場合はホームページ内に啓発文言と返済シミュレーションを備えること。"},"4":{"t":false,"p":"ギャンブル専門紙・誌は、啓発文言を入れれば出稿できる媒体として定められているのではなく、「掲出に留意する」出稿先とされています。","w":"貸金業者の広告に関する細則Ⅰ．4．⑷：出稿先については、ギャンブル専門・風俗専門に係る媒体への掲出に留意します。"}}},"16-11":{"s":"極度方式基本契約の契約締結前の書面（第16条の2第2項）の記載事項と交付方法を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"「債務者が負担すべき元本及び利息以外の金銭に関する事項」は記載事項に「含まれます」。一方、「貸金業者が受け取る書面の内容」は、極度方式基本契約の契約締結前の書面には挙げられていません。","w":"施行規則第12条の2第2項第1号ロ。","r":[["貸金業法施行規則","12の2"]]},"2":{"t":true,"w":"第16条の2第2項第1号（商号等・住所）・施行規則第12条の2第2項第1号イ（登録番号。括弧書は省略可）。相手方の氏名・住所は挙げられていません。","r":[["貸金業法","16の2"],["貸金業法施行規則","12の2"]]},"3":{"t":false,"p":"相手方となろうとする者の承諾を得れば、電磁的方法で提供「できます」。","w":"第16条の2第4項。","r":[["貸金業法","16の2"]]},"4":{"t":false,"p":"極度方式貸付け（枠の中での個々の借入れ）には、契約締結前の書面の交付義務は「ありません」。","w":"第16条の2第1項かっこ書。","r":[["貸金業法","16の2"]]}}},"16-12":{"s":"貸金業者が保存すべきものの保存期間です。適切なのはｃとｄです。","items":{"a":{"t":false,"p":"従業者名簿の保存期間は「営業所等を廃止するまで」ではなく、「最終の記載をした日から10年間」です。","w":"施行規則第10条の9の2第3項。","r":[["貸金業法施行規則","10の9の2"]]},"b":{"t":false,"p":"返済能力の調査の記録は「作成後3年間」ではなく、「契約に定められた最終の返済期日（債権が消滅したときはその日）など」までの間保存します。","w":"施行規則第10条の18第2項。作成後3年間は、極度方式基本契約の途中の調査の記録です（施行規則第10条の27第2項）。","r":[["貸金業法施行規則","10の18"],["貸金業法施行規則","10の27"]]},"c":{"t":true,"w":"施行規則第17条第1項。","r":[["貸金業法施行規則","17"]]},"d":{"t":true,"w":"施行規則第30条の16第1項。","r":[["貸金業法","41の36"],["貸金業法施行規則","30の16"]]}}},"16-13":{"s":"指定信用情報機関への信用情報の提供と、その使い方を問う問題です。適切なのはａとｃです（2個）。","items":{"a":{"t":true,"w":"第41条の36第1項。","r":[["貸金業法","41の36"]]},"b":{"t":false,"p":"極度方式基本契約そのものは、個人信用情報の提供の対象から「除かれて」います（枠の中で実際に借りた極度方式貸付けは対象です）。","w":"第41条の35第2項・第2条第14項・施行規則第1条の2の3第1号。","r":[["貸金業法","41の35"],["貸金業法施行規則","1の2の3"]]},"c":{"t":true,"w":"第41条の37：加入貸金業者は、加入指定信用情報機関の商号又は名称を公表しなければなりません。","r":[["貸金業法","41の37"]]},"d":{"t":false,"p":"債権の保全を目的とした利用も、返済能力の調査以外の目的による使用に「該当します」。","w":"監督指針Ⅱ－2－14（注）：途上与信で取得した信用情報の勧誘への二次利用や、内部データベースに取り込んでの勧誘への利用等（債権の保全を目的とした利用を含む）は、目的外使用に該当します。","r":[["貸金業法","41の38"]]}}},"16-14":{"s":"利息とみなされない費用（利息制限法第6条・施行令）を問う問題です。適切なのはｃとｄです。","items":{"a":{"t":false,"p":"カードの再発行手数料は、利息と「みなされません」。","w":"利息制限法第6条第1項・施行令第1条第1号。","r":[["利息制限法","6"],["利息制限法施行令","1"]]},"b":{"t":false,"p":"再度の口座振替手続の費用は、利息と「みなされません」。","w":"利息制限法第6条第1項・施行令第1条第3号。","r":[["利息制限法","6"],["利息制限法施行令","1"]]},"c":{"t":true,"w":"利息制限法第6条第2項第3号・施行令第2条第2号：1万円を超える額（20,000円）のATM利用料は、220円（消費税等を含む）まで利息とみなされません。","r":[["利息制限法","6"],["利息制限法施行令","2"]]},"d":{"t":true,"w":"利息制限法第6条第1項・施行令第1条第2号。","r":[["利息制限法","6"],["利息制限法施行令","1"]]}}},"16-15":{"s":"登録の拒否事由（第6条第1項）に該当しないものを選ぶ問題です。該当しないのは②です。","items":{"1":{"t":true,"w":"第6条第1項第9号イ・施行規則第5条の4：役員に、精神の機能の障害のため職務を適正に執行するに当たって必要な認知、判断及び意思疎通を適切に行うことができない者がいる場合は拒否事由です。","r":[["貸金業法","6"],["貸金業法施行規則","5の4"]]},"2":{"t":false,"p":"拒否事由は「破産手続開始の決定を受けて復権を得ない者」です。復権していれば、5年を経過していなくても「該当しません」。","w":"第6条第1項第2号・第9号ロ。","r":[["貸金業法","6"]]},"3":{"t":true,"w":"第6条第1項第5号・第9号ロ（政令で定める使用人に該当者がいる場合）。","r":[["貸金業法","6"]]},"4":{"t":true,"w":"第6条第1項第3号（取消しの日前30日以内に役員であった者で、取消しの日から5年を経過しないもの）・第9号ロ。","r":[["貸金業法","6"]]}}},"16-16":{"s":"監督指針Ⅱ－2－2（顧客等に関する情報管理態勢）の着眼点です。適切でないのは④です。","items":{"1":{"t":true,"w":"監督指針Ⅱ－2－2のクレジットカード情報等についての着眼点のとおりです。"},"2":{"t":true,"w":"監督指針Ⅱ－2－2の法人関係情報についての着眼点のとおりです。"},"3":{"t":true,"w":"監督指針Ⅱ－2－2の個人データの第三者提供についての着眼点のとおりです。"},"4":{"t":false,"p":"権限を特定の役職員に「集中させる」のではなく、特定役職員に集中する権限等を「分散」させ、幅広い権限を持つ役職員への管理・けん制を強化します。","w":"監督指針Ⅱ－2－2：特定役職員に集中する権限等の分散や、幅広い権限等を有する役職員への管理・けん制の強化を図る等、顧客等に関する情報を利用した不正行為を防止するための適切な措置を図っているか。"}}},"16-17":{"s":"貸金業務取扱主任者の設置・常時勤務・登録取消し・氏名の明示を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"第12条の3第1項・施行規則第10条の8。","r":[["貸金業法","12の3"],["貸金業法施行規則","10の8"]]},"2":{"t":false,"p":"営業時間内に営業所等に常時駐在している必要は「ありません」。","w":"監督指針Ⅱ－2－9（2）①。","r":[["貸金業法施行規則","10の7"]]},"3":{"t":true,"w":"第24条の30第4号。","r":[["貸金業法","24の30"]]},"4":{"t":true,"w":"第12条の3第4項。","r":[["貸金業法","12の3"]]}}},"16-18":{"s":"返済能力の調査で指定信用情報機関の信用情報を使う義務（第13条第2項）の範囲です。適切でないのは④です。","items":{"1":{"t":true,"w":"第13条第2項の使用義務は個人である顧客等が相手の場合だけです。","r":[["貸金業法","13"]]},"2":{"t":true,"w":"主たる債務者が法人でも、保証人となろうとする者が個人なら、その保証契約について使用義務があります（第13条第2項・第2条第3項・第4項）。","r":[["貸金業法","13"],["貸金業法","2"]]},"3":{"t":true,"w":"施行規則第10条の16第2号・第1条の2の3第5号：貸金業者を債権者とする金銭の貸借の媒介に係る契約は対象外です。","r":[["貸金業法施行規則","10の16"],["貸金業法施行規則","1の2の3"]]},"4":{"t":false,"p":"極度方式貸付けに係る契約は、信用情報の使用義務の対象から「除かれて」います。","w":"第13条第2項かっこ書・施行規則第10条の16第1号。","r":[["貸金業法","13"],["貸金業法施行規則","10の16"]]}}},"16-19":{"s":"極度方式基本契約の極度額を増額するときの返済能力の調査（第13条第5項）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"2年前の源泉徴収票では足りず、年収証明書の提出を受ける必要が「あります」。","w":"第13条第5項で同条第3項が準用され、極度額100万円は50万円を超えるので年収証明書が必要です。源泉徴収票は「一般的に発行される直近の期間に係るもの」でなければなりません（施行規則第10条の17第2項第1号）。","r":[["貸金業法","13"],["貸金業法施行規則","10の17"]]},"2":{"t":true,"w":"第13条第5項：増額する場合は返済能力の調査が必要です。返済能力の低下による減額を戻す場合は、例外（施行規則第10条の19）に当たりません。","r":[["貸金業法","13"],["貸金業法施行規則","10の19"]]},"3":{"t":true,"w":"施行規則第10条の19：連絡が取れないため（返済能力の低下によらず）一時的に減額し、連絡が取れて元の額に戻す場合は、調査は不要です。","r":[["貸金業法施行規則","10の19"]]},"4":{"t":true,"w":"第13条第4項（第5項で準用）・施行規則第10条の18：調査に関する記録を作成し、保存します。","r":[["貸金業法","13"],["貸金業法施行規則","10の18"]]}}},"16-20":{"s":"総量規制の例外契約（施行規則第10条の23）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"第13条の2第2項：個人顧客合算額から除かれるのは住宅資金貸付契約等（除外契約）の残高だけで、例外契約の残高は算入されます。","r":[["貸金業法","13の2"]]},"2":{"t":true,"w":"施行規則第10条の23第1項第6号。","r":[["貸金業法施行規則","10の23"]]},"3":{"t":true,"w":"施行規則第10条の23第1項第1号イ〜ヘ：1か月の負担と返済金額の合計額が既存債務を上回らず、物的担保・保証の条件も不利にならないもの。担保も保証も付けないなら要件を満たします。","r":[["貸金業法施行規則","10の23"]]},"4":{"t":false,"p":"特定緊急貸付契約の返済期間は「1年」ではなく「3か月」を超えないことが要件です（合算額10万円以下も必要）。","w":"施行規則第10条の23第1項第2号の2ロ・ハ。","r":[["貸金業法施行規則","10の23"]]}}},"16-21":{"s":"極度方式基本契約の書面を再交付しなければならない変更を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"施行規則第13条第5項第1号。","r":[["貸金業法施行規則","13"]]},"2":{"t":false,"p":"引き下げた後に元の額を上回らない額まで引き上げた場合も、再交付は「不要」です。","w":"施行規則第13条第5項第2号。","r":[["貸金業法施行規則","13"]]},"3":{"t":true,"w":"施行規則第13条第4項第1号イかっこ書（利率の引下げなど相手方の利益となる変更は除く）。","r":[["貸金業法施行規則","13"]]},"4":{"t":true,"w":"施行規則第13条第4項第1号ロ・同条第3項第1号ト：返済の方法及び返済を受ける場所は、利益となる変更でも再交付が必要な事項です。","r":[["貸金業法施行規則","13"]]}}},"16-22":{"s":"取立て行為の規制（第21条）と監督指針の解釈を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"家族に知られないよう要請を受けている場合「以外」は、貸金業者と名乗ったり差出人を貸金業者としたりしても、直ちに第5号に該当するものではないとされています。要請の有無を「問わず」該当するおそれが大きいわけではありません。","w":"監督指針Ⅱ－2－19。","r":[["貸金業法","21"]]},"2":{"t":true,"w":"施行規則第19条第2項。","r":[["貸金業法施行規則","19"]]},"3":{"t":true,"w":"第21条第2項第3号〜第5号・第7号。","r":[["貸金業法","21"]]},"4":{"t":true,"w":"監督指針Ⅱ－2－19に、記述のとおりの記載があります。","r":[["貸金業法","21"]]}}},"16-23":{"s":"債権譲渡等の規制（第24条）と、協会の自主規制基本規則を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"譲受人が貸金業者である場合も通知は「必要」です。","w":"第24条第1項。","r":[["貸金業法","24"]]},"2":{"t":true,"w":"第24条第2項：第24条の6の10（報告徴収・立入検査）が債権の譲受人に準用され、営業所等の所在する都道府県の知事が行います。","r":[["貸金業法","24"],["貸金業法","24の6の10"]]},"3":{"t":true,"w":"第24条第2項で第17条（第6項を除く）が譲受人に準用されています。","r":[["貸金業法","24"],["貸金業法","17"]]},"4":{"t":true,"w":"自主規制基本規則第67条（譲渡債権に係る帳簿の開示及び保管）のとおりです。"}}},"16-24":{"s":"開始等の届出（第24条の6の2・施行規則第26条の25）の事由です。適切でないのは④です。","items":{"1":{"t":true,"w":"施行規則第26条の25第1項第7号・第2項。","r":[["貸金業法施行規則","26の25"]]},"2":{"t":true,"w":"施行規則第26条の25第1項第5号。","r":[["貸金業法施行規則","26の25"]]},"3":{"t":true,"w":"施行規則第26条の25第1項第6号。","r":[["貸金業法施行規則","26の25"]]},"4":{"t":false,"p":"届出事由は債権を他人に「譲渡した」場合で、他人から「譲り受けた」場合は届出事由では「ありません」。","w":"施行規則第26条の25第1項第3号。","r":[["貸金業法施行規則","26の25"]]}}},"16-25":{"s":"監督上の処分・事業報告書・非協会員の広告の徴収を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"第24条の6の4第1項第1号（第6条第1項第14号に該当することとなったとき）。","r":[["貸金業法","24の6の4"],["貸金業法","6"]]},"2":{"t":true,"w":"第24条の6の6第1項第1号：役員の所在を確知できない場合、その事実を公告し、公告の日から30日を経過しても申出がないときは、登録を取り消すことができます。","r":[["貸金業法","24の6の6"]]},"3":{"t":false,"p":"事業報告書の提出期限は「30日以内」ではなく、毎事業年度経過後「3月以内」です。","w":"第24条の6の9。","r":[["貸金業法","24の6の9"]]},"4":{"t":true,"w":"監督指針Ⅲ－3－7（非協会員に対する広告の写し等の徴収）のとおりです。","r":[["貸金業法","24の6の10"]]}}},"16-26":{"s":"利息制限法の上限（利息・賠償額の予定・天引き）を問う問題です。媒介手数料は利息制限法ではなく出資法で規制されています。適切でないのは①です。","items":{"1":{"t":false,"p":"媒介手数料を制限しているのは利息制限法ではなく「出資法第4条」（貸借の金額の100分の5まで）です。利息制限法には、媒介手数料を無効とする定めはありません。","w":"出資法第4条第1項。","r":[["出資法","4"]]},"2":{"t":true,"w":"利息制限法第1条第2号：元本10万円以上100万円未満は年1割8分。","r":[["利息制限法","1"]]},"3":{"t":true,"w":"利息制限法第7条第1項：営業的金銭消費貸借の賠償額の予定は、元本に対する割合が年2割を超えると、超過部分が無効です。","r":[["利息制限法","7"]]},"4":{"t":true,"w":"利息制限法第2条。","r":[["利息制限法","2"]]}}},"16-27":{"s":"保証料の制限（利息制限法第8条・第9条）を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"利息制限法第8条第1項。","r":[["利息制限法","8"]]},"2":{"t":true,"w":"利息制限法第8条第2項第2号：変動利率で特約上限利率の定めがない場合、保証料の上限は法定上限額の2分の1です。元本80万円の法定上限額は年18%で14万4,000円なので、保証料の上限はその2分の1の7万2,000円になります。","r":[["利息制限法","8"],["利息制限法","1"]]},"3":{"t":false,"p":"保証料とみなされないのは「契約の締結又は債務の弁済の費用」一般ではなく、公租公課・公の機関の手続費用・ATM利用料（政令の範囲内）、カードの再発行手数料など、法律が列挙したものに「限られます」。","w":"利息制限法第8条第7項。","r":[["利息制限法","8"]]},"4":{"t":true,"w":"利息制限法第9条第1項：保証料の契約後に利息を増加したときは、増加後の利息が法定上限額から保証料の額を減じた金額を超える部分が無効です。元本10万円の法定上限額は年18%で1万8,000円、保証料5,000円を引くと1万3,000円（年13%）が上限です。","r":[["利息制限法","9"]]}}},"16-28":{"s":"意思表示（心裡留保・虚偽表示・錯誤・強迫）を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"相手方Ｂが真意でないことを知っていたときは、心裡留保の意思表示は「無効」なので、Ａは無効を主張「できます」。","w":"民法第93条第1項ただし書。","r":[["民法","93"]]},"2":{"t":true,"w":"民法第94条第2項。","r":[["民法","94"]]},"3":{"t":false,"p":"法律行為の基礎とした事情についての錯誤（動機の錯誤）で取り消せるのは、その事情が基礎とされていることが「表示されていた」ときに限られます。","w":"民法第95条第1項第2号・第2項。","r":[["民法","95"]]},"4":{"t":false,"p":"強迫による取消しは、事情を知らない第三者Ｃにも対抗「できます」（第三者保護は詐欺の場合だけ）。","w":"民法第96条第3項。","r":[["民法","96"]]}}},"16-29":{"s":"無効・取消し・追認を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"無効と知って追認すると、行為の時に遡って有効になるのではなく、「新たな行為をしたもの」とみなされます。","w":"民法第119条。","r":[["民法","119"]]},"2":{"t":false,"p":"制限行為能力者本人も、同意を得ずに取り消すことが「できます」。","w":"民法第120条第1項。","r":[["民法","120"]]},"3":{"t":false,"p":"追認した後は、相手方の履行の着手の有無にかかわらず、以後取り消すことが「できません」。","w":"民法第122条。","r":[["民法","122"]]},"4":{"t":true,"w":"民法第124条第1項。","r":[["民法","124"]]}}},"16-30":{"s":"時効の完成猶予と更新を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"確定判決などで権利が確定したときは、事由が終了した時から6か月を経過した時ではなく、事由が終了した「時」から新たに進行を始めます。","w":"民法第147条第2項。","r":[["民法","147"]]},"2":{"t":true,"w":"民法第149条第1号。","r":[["民法","149"]]},"3":{"t":false,"p":"権利の承認をするには、行為能力の制限を受けていないこと又は権限があることを「要しません」。","w":"民法第152条第2項。","r":[["民法","152"]]},"4":{"t":false,"p":"時効の利益は、あらかじめ放棄することが「できません」。","w":"民法第146条。","r":[["民法","146"]]}}},"16-31":{"s":"連帯保証の性質と効力を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"主たる債務者の意思に反して（連帯）保証をすることも「できます」。その場合は求償の範囲が制限されるだけです。","w":"民法第462条第2項：主たる債務者の意思に反して保証をした者は、主たる債務者が現に利益を受けている限度においてのみ求償権を有します（意思に反する保証ができることが前提です）。","r":[["民法","462"]]},"2":{"t":false,"p":"保証契約の締結後に主たる債務が加重されても、連帯保証人の負担は加重「されません」。","w":"民法第448条第2項。","r":[["民法","448"]]},"3":{"t":false,"p":"連帯保証人には、催告の抗弁権が「ありません」。","w":"民法第454条。","r":[["民法","454"]]},"4":{"t":true,"w":"民法第458条・第441条：連帯保証人について生じた事由は、第438条（更改）・第439条第1項（相殺）・第440条（混同）を除き、主たる債務者に効力を生じません（相対的効力）。ただし、債権者と主たる債務者が別段の意思を表示したときは、その意思に従います。","r":[["民法","458"],["民法","441"]]}}},"16-32":{"s":"相殺の要件と、差押えとの関係を問う問題です。Ａから見ると甲債権が自働債権（相殺に使う債権）です。正しいのは③です。","items":{"1":{"t":false,"p":"Ａが相殺に使う甲債権の弁済期（11月1日）が来ていないので、10月15日の時点ではＡから相殺「できません」。","w":"民法第505条第1項：双方の債務が弁済期にあることが必要です。","r":[["民法","505"]]},"2":{"t":false,"p":"相殺の意思表示には、条件又は期限を付けることが「できません」。","w":"民法第506条第1項。","r":[["民法","506"]]},"3":{"t":true,"w":"民法第508条。","r":[["民法","508"]]},"4":{"t":false,"p":"差押え後に「他人から譲り受けた」債権は、差押え前の原因に基づくものでも、相殺を差押債権者に対抗「できません」。","w":"民法第511条第2項ただし書：第三債務者が差押え後に他人の債権を取得したときは、同項本文（差押え前の原因に基づく債権による相殺の対抗）は適用されません。","r":[["民法","511"]]}}},"16-33":{"s":"相続（限定承認・代襲相続・撤回・法定相続分）を問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"民法第922条（限定承認）。","r":[["民法","922"]]},"2":{"t":false,"p":"相続放棄をした者の子は、代襲相続人に「なりません」。","w":"民法第887条第2項（代襲原因は死亡・欠格・廃除）・第939条。","r":[["民法","887"],["民法","939"]]},"3":{"t":false,"p":"相続の承認・放棄は、熟慮期間内であっても撤回「できません」。","w":"民法第919条第1項。","r":[["民法","919"]]},"4":{"t":false,"p":"配偶者と兄弟姉妹が相続人のとき、配偶者は3分の2ではなく「4分の3」、兄弟姉妹は「4分の1」です。","w":"民法第900条第3号。","r":[["民法","900"]]}}},"16-34":{"s":"約束手形と電子記録債権を問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"手形法第38条第1項（第77条第1項第3号で約束手形に準用）。","r":[["手形法","38"],["手形法","77"]]},"2":{"t":false,"p":"約束手形には「単純な」支払約束が必要なので、分割払いの条件を付けると、条件だけでなく約束手形そのものが「無効」になります。","w":"手形法第75条第2号。（条件を記載しなかったものとみなすのは裏書の場合です。第12条第1項）","r":[["手形法","75"],["手形法","12"]]},"3":{"t":false,"p":"電子記録債権の譲渡は、当事者の合意だけでは効力を生じず、「譲渡記録」をしなければ効力を生じません。譲渡記録は対抗要件ではなく効力要件です。","w":"電子記録債権法第17条。","r":[["電子記録債権法","17"]]},"4":{"t":false,"p":"電子記録債権は、分割記録をすることで分割「できます」。","w":"電子記録債権法第43条。","r":[["電子記録債権法","43"]]}}},"16-35":{"s":"強制執行（債務名義・不動産執行・動産執行・差押禁止債権）を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"執行証書による強制執行にも「執行文」が必要です。執行文なしで正本に基づいて実施できるのは、少額訴訟の確定判決・仮執行宣言付少額訴訟判決・支払督促だけです。","w":"民事執行法第25条。","r":[["民事執行法","25"]]},"2":{"t":false,"p":"強制競売と強制管理は、併用することが「できます」。","w":"民事執行法第43条第1項。","r":[["民事執行法","43"]]},"3":{"t":false,"p":"動産執行は、執行裁判所の差押命令ではなく、「執行官」の目的物に対する差押えにより開始します（差押命令で始まるのは債権執行です）。","w":"民事執行法第122条第1項・第143条。","r":[["民事執行法","122"],["民事執行法","143"]]},"4":{"t":true,"w":"民事執行法第152条第1項第2号：給料債権は、支払期に受けるべき給付の4分の3（政令で定める額を超えるときはその額）は差し押さえてはなりません。","r":[["民事執行法","152"]]}}},"16-36":{"s":"行為能力（未成年者の営業許可・成年被後見人・被補助人・相手方の催告権）を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"民法第6条第1項。","r":[["民法","6"]]},"2":{"t":false,"p":"成年被後見人の行為は、成年後見人の同意を得ていても取り消すことが「できます」（日常生活に関する行為を除く）。同意を得れば有効にできるのは被保佐人の場合です。","w":"民法第9条。","r":[["民法","9"],["民法","13"]]},"3":{"t":true,"w":"民法第17条第1項ただし書：補助人の同意を要する旨の審判ができる行為は、第13条第1項に規定する行為の一部に限られます。","r":[["民法","17"],["民法","13"]]},"4":{"t":true,"w":"民法第20条第2項。","r":[["民法","20"]]}}},"16-37":{"s":"代理（顕名・復代理・代理権の消滅・代理権消滅後の表見代理）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"民法第100条ただし書・第99条第1項。","r":[["民法","100"],["民法","99"]]},"2":{"t":true,"w":"民法第104条。","r":[["民法","104"]]},"3":{"t":true,"w":"民法第111条第1項第2号：代理人が後見開始の審判を受けたことは、代理権の消滅事由です。","r":[["民法","111"]]},"4":{"t":false,"p":"代理権消滅後の表見代理で本人が責任を負うのは、相手方が代理権の消滅を知らず、かつ知らないことに「過失がない」ときに限られます。過失があれば責任を負いません。","w":"民法第112条第1項ただし書。","r":[["民法","112"]]}}},"16-38":{"s":"債権の効力（受領遅滞・損害賠償の範囲・賠償額の予定・代位）を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"民法第413条第1項。","r":[["民法","413"]]},"2":{"t":false,"p":"特別の事情による損害は、特約がなくても、当事者がその事情を予見すべきであったときは請求「できます」。","w":"民法第416条第2項。","r":[["民法","416"]]},"3":{"t":true,"w":"民法第420条第1項・第2項。","r":[["民法","420"]]},"4":{"t":true,"w":"民法第422条。","r":[["民法","422"]]}}},"16-39":{"s":"債権譲渡（供託・将来債権・対抗要件・相殺）を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"民法第466条の2第1項。","r":[["民法","466の2"]]},"2":{"t":true,"w":"民法第466条の6第1項。","r":[["民法","466の6"]]},"3":{"t":false,"p":"「債務者」に対抗するには、確定日付のない通知・承諾で「足ります」。確定日付が必要なのは、債務者以外の第三者に対抗する場合です。","w":"民法第467条第1項・第2項。","r":[["民法","467"]]},"4":{"t":true,"w":"民法第469条第2項第1号・ただし書。","r":[["民法","469"]]}}},"16-40":{"s":"定型約款を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"定型約款の内容は、事前に必ず示す義務があるのではなく、相手方から「請求があった場合」に遅滞なく示せば足ります。","w":"民法第548条の3第1項。","r":[["民法","548の3"]]},"2":{"t":true,"w":"民法第548条の2第2項。","r":[["民法","548の2"]]},"3":{"t":true,"w":"民法第548条の4第2項。","r":[["民法","548の4"]]},"4":{"t":true,"w":"民法第548条の4第1項第1号。","r":[["民法","548の4"]]}}},"16-41":{"s":"破産法（破産債権・財団債権・別除権・相殺権）を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"破産法第2条第5項・第100条第1項。","r":[["破産法","2"],["破産法","100"]]},"2":{"t":true,"w":"破産法第148条第1項第1号・第2条第7項（財団債権は、破産手続によらないで破産財団から随時弁済を受けることができる債権）。","r":[["破産法","148"],["破産法","2"]]},"3":{"t":false,"p":"別除権は、破産手続によらなければ行使できないのではなく、破産手続によら「ないで」行使できます（抵当権の実行などを手続の外で行えます）。","w":"破産法第2条第9項（定義）・第65条第1項。","r":[["破産法","2"],["破産法","65"]]},"4":{"t":true,"w":"破産法第67条第1項・第71条第2項第3号：破産手続開始の申立てがあった時より1年以上前に生じた原因に基づく債務負担であれば、相殺禁止の規定は適用されません。","r":[["破産法","67"],["破産法","71"]]}}},"16-42":{"s":"犯罪収益移転防止法の本人特定事項の確認方法を問う問題です。公式正答（基準日2021年4月1日）では④が確認方法に該当しないとされています。現行法では、①②の書類が本人確認書類から外れています。","law":"現行（基準日2026年4月1日）の犯罪収益移転防止法施行規則第7条第1号ハには、国民健康保険の「被保険者証」と国民年金手帳は挙げられていません（健康保険は「資格確認書」が挙げられています）。そのため①②の方法は、現行の条文では確認方法に当たりません。経過措置は附則にありますが、取り込んだ法令データには附則が含まれていないため確認できません。","items":{"1":{"t":true,"now":false,"w":"公式正答では確認方法に該当するとされています（写真のない本人確認書類2種類の提示。施行規則第6条第1項第1号ハ）。現行の第7条第1号ハには、国民健康保険の被保険者証・国民年金手帳は挙げられていません。","r":[["犯罪収益移転防止法施行規則","6"],["犯罪収益移転防止法施行規則","7"]]},"2":{"t":true,"now":false,"w":"公式正答では確認方法に該当するとされています（写真のない本人確認書類の提示＋補完書類の写しの送付。施行規則第6条第1項第1号ニ、補完書類は同条第2項第3号の公共料金の領収証書）。現行法では、国民健康保険の被保険者証が第7条第1号ハに挙げられていません。","r":[["犯罪収益移転防止法施行規則","6"],["犯罪収益移転防止法施行規則","7"]]},"3":{"t":true,"w":"施行規則第6条第1項第1号ホ：特定事業者が提供するソフトウェアで撮影させた本人の容貌と写真付き本人確認書類の画像情報の送信を受ける方法。","r":[["犯罪収益移転防止法施行規則","6"]]},"4":{"t":false,"p":"本人確認書類の写し「1種類」の送付と転送不要郵便では足りません。写しの送付による方法では、写し2種類、又は写しと補完書類の送付を受けたうえで、転送不要郵便などを送付する必要があります。","w":"施行規則第6条第1項第1号リ。","r":[["犯罪収益移転防止法施行規則","6"]]}}},"16-43":{"s":"個人情報保護法の定義（個人識別符号・個人情報取扱事業者・保有個人データ・要配慮個人情報）を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"携帯電話番号やクレジットカード番号は、個人識別符号に「該当しません」。","w":"個人情報保護法第2条第2項：個人識別符号は、身体の一部の特徴を変換した符号（第1号）や、個人に割り当てられ、カードその他の書類に記載されるなどした符号（第2号）のうち、政令で定めるものです。携帯電話番号やクレジットカード番号が該当しないことの結論は公式正答によります。","r":[["個人情報保護法","2"]]},"2":{"t":true,"w":"個人情報保護法第16条第2項：個人情報データベース等を事業の用に供している者（国の機関・地方公共団体・独立行政法人等・地方独立行政法人を除く）。取り扱う人数による除外はありません。","r":[["個人情報保護法","16"]]},"3":{"t":false,"p":"保有個人データは、請求に「いずれか」応じる権限がある個人データではなく、開示・訂正等・利用停止等・第三者提供の停止を行うことのできる権限を有する個人データです。","w":"個人情報保護法第16条第4項。","r":[["個人情報保護法","16"]]},"4":{"t":false,"p":"「犯罪により害を被った事実」も、要配慮個人情報に「含まれます」。","w":"個人情報保護法第2条第3項。","r":[["個人情報保護法","2"]]}}},"16-44":{"s":"消費者契約法の定義・取消し・不当条項を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"事業として又は事業のために契約の当事者となる個人も、消費者契約法上の「事業者」に「当たります」。","w":"消費者契約法第2条第2項。","r":[["消費者契約法","2"]]},"2":{"t":false,"p":"不利益事実の不告知で誤認して契約した場合、契約は「無効」ではなく、消費者が「取り消す」ことができます。","w":"消費者契約法第4条第2項。","r":[["消費者契約法","4"]]},"3":{"t":false,"p":"無効になるのは条項全体ではなく、平均的な損害の額を「超える部分」だけです。","w":"消費者契約法第9条第1項第1号。","r":[["消費者契約法","9"]]},"4":{"t":true,"w":"消費者契約法第8条第1項第2号：事業者の故意又は重大な過失による債務不履行の損害賠償責任の一部を免除する条項は無効です。","r":[["消費者契約法","8"]]}}},"16-45":{"s":"日本貸金業協会の紛争解決等業務に関する規則（定義・代理人・申立人）を問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"紛争解決等業務に関する規則（定義）第1号のとおりです。"},"2":{"t":false,"p":"貸金業務関連紛争は、当事者が和解を「することができない」ものではなく、「することができる」ものです。","w":"紛争解決等業務に関する規則（定義）第2号。"},"3":{"t":false,"p":"代理人は「法定代理人、弁護士、司法書士、行政書士」ではなく、法定代理人・弁護士・認定司法書士（請求の価額に上限あり）です。行政書士は挙げられていません（それ以外の者も、許可を受ければ代理人になれます）。","w":"紛争解決等業務に関する規則第38条第1項・第2項。"},"4":{"t":false,"p":"法人でない社団又は財団で代表者等の定めがあるもの（権利能力なき社団等）も、申立てが「できます」。","w":"紛争解決等業務に関する規則第59条第1項。"}}},"16-46":{"s":"個人データの第三者提供（通則編ガイドライン）と、金融分野ガイドラインを問う問題です。第16回の時点の条番号（第23条）は、現行法では第27条になっています。適切でないのは③です。","items":{"1":{"t":true,"w":"通則編ガイドライン：親子兄弟会社、グループ会社の間で個人データを交換する場合は、第三者提供とされる事例です（現行の第27条第5項各号の場合を除く）。","r":[["個人情報保護法","27"]]},"2":{"t":true,"w":"公式正答では適切とされています。現行の個人情報保護法第27条第6項では、共同利用する者の利用目的や責任者を「変更しようとするとき」はあらかじめ、責任者の氏名・名称・住所などに「変更があったとき」は遅滞なく、本人に通知し又は容易に知り得る状態に置く、と区別されています。","r":[["個人情報保護法","27"]]},"3":{"t":false,"p":"利用目的の達成に必要な範囲内で取扱いを委託することに伴う提供の場合、提供先（委託先）は第三者に「該当しません」。","w":"個人情報保護法第27条第5項第1号。","r":[["個人情報保護法","27"]]},"4":{"t":true,"w":"金融分野ガイドライン（与信事業における法第27条第2項（オプトアウト）の規定の適用）：個人の返済能力に関する情報を個人信用情報機関へ提供するに当たっては、オプトアウトの規定を適用しないこととし、本人の同意を得ることとされています。","r":[["個人情報保護法","27"]]}}},"16-47":{"s":"日本貸金業協会の自主規制基本規則の勧誘に関する規定を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"自主規制基本規則第55条第1項第1号。"},"2":{"t":true,"w":"自主規制基本規則第55条第1項第2号。"},"3":{"t":false,"p":"契約内容が理解困難なことを認識した場合は、丁寧に説明して理解させるよう努めるのではなく、貸付けの契約の締結に係る勧誘を「行ってはならない」とされています。","w":"自主規制基本規則第54条第4項。なお、理解困難なことを認識しながら契約を締結することは、不正又は著しく不当な行為に当たるおそれがある行為とされています（同規則第15条第7号・監督指針Ⅱ－2－10）。"},"4":{"t":true,"w":"自主規制基本規則第54条第1項第1号。"}}},"16-48":{"s":"貸借対照表の区分と科目の分類を問う問題です。会社計算規則は取り込んでいないため、同じ考え方を定めた企業会計原則の貸借対照表原則で確認できる範囲で説明します。適切なのはａだけです（1個）。","items":{"a":{"t":true,"w":"企業会計原則・貸借対照表原則二は資産の部・負債の部・資本の部の3区分としています。会社計算規則で「純資産」の部とすることの結論は公式正答によります。"},"b":{"t":false,"p":"負債の部は「流動負債、固定負債及び繰延負債」ではなく、「流動負債及び固定負債」に区分します。繰延負債という区分はありません。","w":"企業会計原則・貸借対照表原則二。"},"c":{"t":false,"p":"前受金（受注工事・受注品等に対する前受金）は、流動「資産」ではなく流動「負債」に属します。","w":"企業会計原則注解〔注16〕：受取手形・売掛金・前払金・支払手形・買掛金・前受金など、主目的たる営業取引により発生した債権及び債務は、流動資産又は流動負債に属します。前受金は代金を先に受け取ったことによる債務（後で品物や工事を引き渡す義務）なので、流動負債に入ります。"},"d":{"t":false,"p":"1年内に費用となる前払費用は、流動「負債」ではなく流動「資産」に属します。","w":"企業会計原則・貸借対照表原則四㈠Ａ：前払費用で1年以内に費用となるものは、流動資産に属します。"}}},"16-49":{"s":"キャッシュ・フロー計算書の区分を問う問題です。財務諸表等規則とキャッシュ・フロー計算書の基準は取り込んだ資料にないため、結論は公式正答によります。正しいのは③です。","items":{"1":{"t":false,"p":"短期借入れ・返済は、営業活動ではなく「財務活動」の区分です。","w":"結論は公式正答によります。"},"2":{"t":false,"p":"棚卸資産の増減額は、投資活動ではなく「営業活動」の区分です。","w":"結論は公式正答によります。"},"3":{"t":true,"w":"結論は公式正答によります。"},"4":{"t":false,"p":"貸付けによる支出・貸付金の回収による収入は、財務活動ではなく「投資活動」の区分です。","w":"結論は公式正答によります。"}}},"16-50":{"s":"企業会計原則の一般原則を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"企業会計原則・一般原則二（正規の簿記の原則）。"},"2":{"t":false,"p":"一般原則にあるのは「資本取引と損益取引」を区別し「資本剰余金と利益剰余金」を混同しないという「資本取引・損益取引区分の原則」です。「資本取引と負債取引」の区別ではなく、明瞭性の原則という名称でもありません。","w":"企業会計原則・一般原則三。明瞭性の原則は一般原則四（財務諸表で会計事実を明瞭に表示すること）です。"},"3":{"t":true,"w":"企業会計原則・一般原則五（継続性の原則）。"},"4":{"t":true,"w":"企業会計原則・一般原則六（保守主義の原則）。"}}},"17-01":{"s":"貸金業法第2条の用語の定義と、個人信用情報の中身です。適切なのはｂだけです（1個）。","items":{"a":{"t":false,"p":"貸金業は「営利の目的をもって」ではなく、「業として」行う金銭の貸付け又は貸借の媒介です。","w":"第2条第1項。","r":[["貸金業法","2"]]},"b":{"t":true,"w":"第2条第14項・第41条の35第1項第1号・施行規則第30条の13：個人信用情報には、氏名・住所・生年月日・電話番号・勤務先の商号又は名称・運転免許証等の番号（交付を受けている場合）などが含まれます。","r":[["貸金業法","2"],["貸金業法","41の35"],["貸金業法施行規則","30の13"]]},"c":{"t":false,"p":"住宅の改良に必要な資金の貸付けも、住宅資金貸付契約に「含まれます」。","w":"第2条第17項。","r":[["貸金業法","2"]]},"d":{"t":false,"p":"紛争解決手続は、「裁判上の和解」ではなく、「訴訟手続によらずに」解決を図る手続です。","w":"第2条第21項。","r":[["貸金業法","2"]]}}},"17-02":{"s":"登録申請書の記載事項（第4条第1項）を問う問題です。適切なのはｂとｃです。","items":{"a":{"t":false,"p":"記載するのは、主任者の「氏名及び住所」ではなく「氏名及び登録番号」です。","w":"第4条第1項第6号。","r":[["貸金業法","4"]]},"b":{"t":true,"w":"第4条第1項第2号の「政令で定める使用人」（施行令第3条）として、施行規則第3条第1項第3号で、貸付けに関する業務に従事する使用人が50人以上の従たる営業所等の支店次長・副支店長・副所長など（業務を統括する者の権限を代行し得る地位にある者）が定められています。","r":[["貸金業法","4"],["貸金業法施行令","3"],["貸金業法施行規則","3"]]},"c":{"t":true,"w":"第4条第1項第7号・施行規則第3条の2第1項第1号。","r":[["貸金業法","4"],["貸金業法施行規則","3の2"]]},"d":{"t":false,"p":"代理店から、銀行などの金融機関が設置する現金自動設備は「除かれています」。","w":"施行規則第1条の5第4項：代理店の定義のかっこ書で、銀行・長期信用銀行・協同組織金融機関などの現金自動設備を除いています。","r":[["貸金業法施行規則","1の5"]]}}},"17-03":{"s":"登録行政庁への届出（変更の届出・廃業等の届出・開始等の届出）の期限です。正しいのは④です。","items":{"1":{"t":false,"p":"営業所の所在地の変更は、変更から2週間以内ではなく、変更しようとするとき「あらかじめ」届け出ます。","w":"第8条第1項・第4条第1項第5号。","r":[["貸金業法","8"],["貸金業法","4"]]},"2":{"t":false,"p":"業務の種類の変更は、「あらかじめ」ではなく、変更があった日から「2週間以内」に届け出ます。","w":"第8条第1項・第4条第1項第8号。","r":[["貸金業法","8"],["貸金業法","4"]]},"3":{"t":false,"p":"貸金業を廃止した場合の届出期限は、「2週間以内」ではなく「30日以内」です。","w":"第10条第1項第5号。","r":[["貸金業法","10"]]},"4":{"t":true,"w":"第24条の6の2第4号・施行規則第26条の25第1項第4号・第2項：役員又は使用人に貸金業の業務に関し法令に違反する行為等があったことを知った場合は、2週間以内に届け出ます。","r":[["貸金業法","24の6の2"],["貸金業法施行規則","26の25"]]}}},"17-04":{"s":"業務を第三者に委託するときの措置（施行規則第10条の5）です。4つとも同条第1項の措置です（4個）。","items":{"a":{"t":true,"w":"施行規則第10条の5第1項第1号。","r":[["貸金業法施行規則","10の5"]]},"b":{"t":true,"w":"施行規則第10条の5第1項第2号。","r":[["貸金業法施行規則","10の5"]]},"c":{"t":true,"w":"施行規則第10条の5第1項第4号。","r":[["貸金業法施行規則","10の5"]]},"d":{"t":true,"w":"施行規則第10条の5第1項第5号。","r":[["貸金業法施行規則","10の5"]]}}},"17-05":{"s":"金融ADR制度（指定紛争解決機関との手続実施基本契約）を問う問題です。適切なのはｂとｄです。","items":{"a":{"t":false,"p":"指定紛争解決機関が存在する以上、協会に加入していなくても、苦情処理措置等で代えることはできず、手続実施基本契約を締結する措置が「必要」です。","w":"第12条の2の2第1項：指定紛争解決機関が存在する場合は第1号（手続実施基本契約の締結）、存在しない場合に第2号（苦情処理措置及び紛争解決措置）となります。","r":[["貸金業法","12の2の2"]]},"b":{"t":true,"w":"第12条の2の2第2項。","r":[["貸金業法","12の2の2"]]},"c":{"t":false,"p":"「和解案」は受諾を拒否「できます」。加入貸金業者が原則として受諾しなければならないのは「特別調停案」です。","w":"第41条の44第2項第4号（和解案の受諾の勧告）・第5号（特別調停案）。","r":[["貸金業法","41の44"]]},"d":{"t":true,"w":"第41条の44第2項第11号・施行規則第30条の22第1項：資金需要者等の申出があるときは、和解などで定められた義務の履行状況を調査し、履行を勧告することができることを、手続実施基本契約の内容とします。","r":[["貸金業法","41の44"],["貸金業法施行規則","30の22"]]}}},"17-06":{"s":"貸金業務取扱主任者の設置数と、欠けたときの対応です。適切なのはｂだけです（1個）。","items":{"a":{"t":false,"p":"定年退職は予見できるので、「2週間以内」の猶予はありません。定年退職の時点で後任を置いていなければ、設置義務違反になります。","w":"第12条の3第3項の2週間の猶予は「予見し難い事由」の場合だけです。監督指針Ⅱ－2－9（2）③：会社の都合や定年による退職などは含まれません。","r":[["貸金業法","12の3"]]},"b":{"t":true,"w":"施行規則第10条の8：貸金業の業務に従事する者の50分の1以上。110人÷50＝2.2なので、3人以上が必要です。","r":[["貸金業法","12の3"],["貸金業法施行規則","10の8"]]},"c":{"t":false,"p":"他の営業所等の主任者として登録されている者を兼務させることは「できません」。急な失踪の場合は、2週間以内に新たな主任者を置くなどの措置をとります。","w":"施行規則第10条の7第2号：他の営業所等の主任者として登録されている者（変更の届出がないもの）は、主任者として置けません。第12条の3第3項：予見し難い事由のときは2週間以内に必要な措置をとります。","r":[["貸金業法施行規則","10の7"],["貸金業法","12の3"]]},"d":{"t":false,"p":"現金自動設備を設置しても、乙営業所で貸金業の業務に従事する者は40人のままなので、必要な主任者は「2人以上」ではなく「1人以上」です（40人の50分の1以上）。","w":"施行規則第10条の8（業務に従事する者の50分の1以上）。なお、現金自動設備のみで貸付けの業務を行う営業所等に主任者を置く場合は、常時勤務の要件は適用されません（施行規則第10条の7ただし書）。","r":[["貸金業法施行規則","10の7"],["貸金業法施行規則","10の8"]]}}},"17-07":{"s":"禁止行為など（第12条の5〜第12条の8）と罰則です。適切なのはａとｄです。","items":{"a":{"t":true,"w":"第12条の5。","r":[["貸金業法","12の5"]]},"b":{"t":false,"p":"保証料の確認は、保証契約を締結した後に「遅滞なく」ではなく、保証契約を締結する「まで」に行います。","w":"第12条の8：保証業者と保証契約を締結しようとするときは、当該保証契約を締結するまでに、照会その他の方法により保証料に係る契約の締結の有無などを確認しなければなりません。","r":[["貸金業法","12の8"]]},"c":{"t":false,"p":"住宅資金貸付契約は、自殺を保険事故とすることの禁止の対象から「除かれて」います。","w":"第12条の7：貸付けの契約（住宅資金貸付契約その他の内閣府令で定める契約を除く）について、保険契約で自殺による死亡を保険事故としてはなりません。","r":[["貸金業法","12の7"]]},"d":{"t":true,"w":"第12条の6第1号の虚偽告知は、第48条第1項第1号の2で刑事罰の対象です。","r":[["貸金業法","12の6"],["貸金業法","48"]]}}},"17-08":{"s":"返済能力の調査（第13条）で、信用情報の使用・年収証明書・記録の保存を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"他の貸金業者を債権者とする金銭の貸借の媒介に係る契約は、信用情報の使用義務の対象から「除かれて」います。","w":"第13条第2項・施行規則第10条の16第2号・第1条の2の3第5号。","r":[["貸金業法","13"],["貸金業法施行規則","10の16"],["貸金業法施行規則","1の2の3"]]},"2":{"t":false,"p":"年収証明書が必要なのは、自社の合算額が50万円を「超える」場合です。ちょうど50万円で他社借入れもなければ「不要」です。","w":"第13条第3項第1号（50万円超）・第2号（他社を含め100万円超）。","r":[["貸金業法","13"]]},"3":{"t":false,"p":"変更後の勤務先で2か月分以上の給与を受けていない場合は、変更後の1か月分の明細だけで足りるのではなく、変更前の資力を明らかにする書面等（源泉徴収票など）を用いることができる、とされています。","w":"施行規則第10条の17第1項ただし書：勤務先の変更などで資力に変更があったときは、変更後の資力を明らかにするものに限ります。同条第3項：変更後の勤務先が確認され、変更後の勤務先で2月分以上の給与の支払を受けていないときは、同条第1項本文の書面等を用いることができます。給与の支払明細書は直近2月分以上が必要です（同条第2項第2号）。","r":[["貸金業法施行規則","10の17"]]},"4":{"t":true,"w":"施行規則第10条の18第2項第1号。","r":[["貸金業法","13"],["貸金業法施行規則","10の18"]]}}},"17-09":{"s":"保証人となろうとする者についての返済能力の調査と、保証人への書面の交付を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"年収証明書の提出を受ける義務（第13条第3項）は、資金需要者である「個人顧客」についてのもので、保証人となろうとする者は「対象外」です。","w":"第13条第3項：「資金需要者である個人の顧客（個人顧客）」から提出を受けます。","r":[["貸金業法","13"]]},"2":{"t":false,"p":"保証人となろうとする者に交付するのは、保証契約の内容を説明する書面（概要と詳細の2種類）です。貸付けの契約の内容を説明する書面ではありません。","w":"第16条の2第3項・施行規則第12条の2第7項：保証契約の概要を記載した書面と詳細を記載した書面を同時に交付します。","r":[["貸金業法","16の2"],["貸金業法施行規則","12の2"]]},"3":{"t":false,"p":"法人の保証人となろうとする者についても、返済能力の調査（第13条第1項）は「必要」です（信用情報の使用義務がないだけです）。","w":"第13条第1項：貸付けの契約（保証契約を含む。第2条第3項）を締結しようとする場合には、顧客等（保証人となろうとする者を含む）の返済能力を調査しなければなりません。","r":[["貸金業法","13"],["貸金業法","2"]]},"4":{"t":true,"w":"第13条第1項・第2項：個人である顧客等（保証人となろうとする個人を含む）と貸付けの契約（保証契約を含む）を締結しようとする場合は、信用情報を使用して調査します。","r":[["貸金業法","13"],["貸金業法","2"]]}}},"17-10":{"s":"総量規制の「例外契約」（施行規則第10条の23）と「除外契約」（第10条の21）の区別を問う問題です。例外契約に当たるのは③です。","items":{"1":{"t":false,"p":"担保付の自動車購入資金の貸付けは、例外契約ではなく「除外契約」（施行規則第10条の21第1項第3号）です。","w":"除外契約は総量規制の計算から除かれる契約、例外契約は総量規制の対象だが例外的に貸し付けられる契約です。","r":[["貸金業法施行規則","10の21"]]},"2":{"t":false,"p":"金融機関からの貸付けまでのつなぎ融資は、返済期間が1か月を「超えない」ものに限り例外契約です。","w":"施行規則第10条の23第1項第6号ロ。","r":[["貸金業法施行規則","10の23"]]},"3":{"t":true,"w":"施行規則第10条の23第1項第2号：緊急に必要と認められる医療費を支払うための貸付け（高額療養費の除外契約を除く）で、返済能力を超えないと認められるもの。","r":[["貸金業法施行規則","10の23"]]},"4":{"t":false,"p":"借換えの例外契約は、1か月の負担だけでなく、返済金額の合計額も既存債務を「上回らない」ことが必要です。上回るものは該当しません。","w":"施行規則第10条の23第1項第1号イ・ロ。","r":[["貸金業法施行規則","10の23"]]}}},"17-11":{"s":"貸付条件等の掲示（第14条）と標識の掲示（第23条）を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"貸付条件等の掲示事項に、商号や登録番号は「含まれません」（これらは標識などで示します）。","w":"第14条第1項：掲示事項は、貸付けの利率、返済の方式、返済期間及び返済回数、主任者の氏名、内閣府令で定める事項（施行規則第11条第3項）です。","r":[["貸金業法","14"],["貸金業法施行規則","11"]]},"2":{"t":true,"w":"第14条第1項第5号・施行規則第11条第3項第1号ハ：金銭の貸付けでは「主な返済の例」を掲示します。","r":[["貸金業法","14"],["貸金業法施行規則","11"]]},"3":{"t":false,"p":"標識は「顧客」ではなく「公衆」の見やすい場所に掲示します。また、現行法では、商号・登録番号などをインターネットで公衆の閲覧に供することも求められています。","w":"第23条第1項・第2項。","r":[["貸金業法","23"]]},"4":{"t":false,"p":"現金自動設備も営業所等に含まれるので、標識の掲示は「必要」です。","w":"第23条第1項は営業所又は事務所ごとに掲示を求めています。施行規則第1条の5第3項で、営業所又は事務所には現金自動設備も含まれます。現金自動設備を除外する定めはありません（結論は公式正答によります）。","r":[["貸金業法","23"],["貸金業法施行規則","1の5"]]}}},"17-12":{"s":"マンスリーステートメント（一定期間の取引状況をまとめた書面）の交付を問う問題です。適切なのはａ・ｂ・ｄです（3個）。","items":{"a":{"t":true,"w":"監督指針Ⅱ－2－16（1）④のとおりです。","r":[["貸金業法","17"]]},"b":{"t":true,"w":"監督指針Ⅱ－2－16（1）④のとおりです。","r":[["貸金業法","17"]]},"c":{"t":false,"p":"マンスリーステートメントは契約締結時の書面に代わるものではありません。マンスリーステートメントを交付するときは、契約締結時の書面に代えて、契約年月日・貸付けの金額などを記載した簡素な書面を交付することが「できる」、という仕組みです。","w":"第17条第6項。","r":[["貸金業法","17"]]},"d":{"t":true,"w":"第18条第3項：極度方式保証契約に基づく債権の弁済を受けた場合も、保証人の承諾を得てマンスリーステートメントを交付するときは、受取証書に代えて、受領年月日・受領金額などを記載した書面を交付できます。","r":[["貸金業法","18"]]}}},"17-13":{"s":"帳簿（第19条）の備付け・保存と、監督指針の「交渉の経過の記録」です。適切なのはｃとｄです。","items":{"a":{"t":false,"p":"帳簿は主たる営業所だけでなく、「営業所又は事務所ごと」に備えます。","w":"第19条（現金自動設備は施行規則第17条第2項で不要）。","r":[["貸金業法","19"],["貸金業法施行規則","17"]]},"b":{"t":false,"p":"保存期間の起算点は「全ての取引が終了した日」ではなく、「貸付けの契約ごとに、最終の返済期日（債権が消滅したときはその日）」です。","w":"施行規則第17条第1項：少なくとも10年間保存します。","r":[["貸金業法施行規則","17"]]},"c":{"t":true,"w":"監督指針（帳簿の備付け等の着眼点の注）のとおりです。","r":[["貸金業法施行規則","16"]]},"d":{"t":true,"w":"監督指針：交渉の経過の記録の記載事項として、交渉の相手方、日時・場所・手法、担当者、「交渉内容（催告書等の書面の内容を含む）」などが挙げられています。","r":[["貸金業法施行規則","16"]]}}},"17-14":{"s":"債権譲渡等の規制（第24条）と、取立て制限者への委託の責任を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"通知は、譲受人が貸金業者ではない場合に「限られません」。貸金業者に譲渡する場合も必要です。","w":"第24条第1項。","r":[["貸金業法","24"]]},"2":{"t":false,"p":"債権の内容を明らかにする書面（第17条の準用）を交付するのは、譲渡人ではなく「譲受人」です。","w":"第24条第2項。","r":[["貸金業法","24"],["貸金業法","17"]]},"3":{"t":true,"w":"第24条第2項で第16条の2第3項が譲受人に準用されています。","r":[["貸金業法","24"],["貸金業法","16の2"]]},"4":{"t":false,"p":"知らなかっただけでは足りず、「知らなかったことにつき相当の理由があることを証明」できなければ、行政処分の対象に「なります」。","w":"第24条の6の4第1項第4号イ・ロ：取立て制限者であることを知らなかったことにつき相当の理由があることを証明できず、かつ、その者が第21条第1項に違反するなどしたときは、処分の対象です。","r":[["貸金業法","24の6の4"]]}}},"17-15":{"s":"指定信用情報機関に提供する個人信用情報の対象と項目を問う問題です。適切なのはａとｃです。","items":{"a":{"t":true,"w":"第41条の35第2項：個人の顧客と貸付けに係る契約を締結したときは、遅滞なく個人信用情報を提供します。対象外とされる契約（施行規則第1条の2の3）は極度方式基本契約などで、枠の中で実際に借りる極度方式貸付けは対象です。","r":[["貸金業法","41の35"],["貸金業法施行規則","1の2の3"]]},"b":{"t":false,"p":"住宅資金貸付契約も、個人信用情報の提供の対象から除かれて「いません」。","w":"個人信用情報の対象外は、施行規則第1条の2の3に掲げる極度方式基本契約・手形割引・一定の有価証券担保貸付け・貸金業者を債権者とする媒介などで、住宅資金貸付契約は挙げられていません。","r":[["貸金業法","41の35"],["貸金業法施行規則","1の2の3"]]},"c":{"t":true,"w":"施行規則第30条の13第1項第5号：勤務先の商号又は名称。","r":[["貸金業法施行規則","30の13"]]},"d":{"t":false,"p":"本人確認書類の記号番号が個人信用情報に含まれるのは、旅券等・在留カード・特別永住者証明書で本人確認をした場合です。国民健康保険証は「対象外」です。","w":"施行規則第30条の13第1項第7号。","r":[["貸金業法施行規則","30の13"]]}}},"17-16":{"s":"利息制限法の元本額の特則（第5条）の計算問題です。適切なのはｂとｄです（2個）。","items":{"a":{"t":false,"p":"15%に下がるのは第二契約だけです。第一契約は締結時の元本95万円で判断するので、18%のままで無効部分はありません。","w":"第5条第1号：第二契約の元本は、残元本95万円＋9万円＝104万円とみなされ、上限は年15%。","r":[["利息制限法","5"],["利息制限法","1"]]},"b":{"t":true,"w":"第5条第1号：残元本9万円＋5万円＝14万円とみなされ、上限は年18%（第1条第2号）。","r":[["利息制限法","5"],["利息制限法","1"]]},"c":{"t":false,"p":"残元本5万円＋3万円＝8万円は10万円未満なので、上限は年20%です。第二契約の20%は「全部有効」です。","w":"第5条第1号・第1条第1号。","r":[["利息制限法","5"],["利息制限法","1"]]},"d":{"t":true,"w":"第5条：残元本45万円＋5万円＋50万円＝100万円とみなされ、第二・第三契約の上限は年15%（第1条第3号）。","r":[["利息制限法","5"],["利息制限法","1"]]}}},"17-17":{"s":"みなし利息とその例外（利息制限法第3条・第6条）を問う問題です。適切なのはａとｂです。","items":{"a":{"t":true,"w":"利息とみなされない例外は、カードの「再発行」手数料です（第6条第1項・施行令第1条第1号）。最初のカード発行手数料は、第3条により利息とみなされます。","r":[["利息制限法","3"],["利息制限法","6"],["利息制限法施行令","1"]]},"b":{"t":true,"w":"営業的金銭消費貸借では、利息とみなされない契約の締結・弁済の費用は、第6条第2項の公租公課・公の手続の費用・ATM利用料に限られます。振込手数料はこれに当たらないので、第3条により利息とみなされます。","r":[["利息制限法","3"],["利息制限法","6"]]},"c":{"t":false,"p":"再度の口座振替手続の費用は、利息と「みなされません」。","w":"第6条第1項・施行令第1条第3号。","r":[["利息制限法","6"],["利息制限法施行令","1"]]},"d":{"t":false,"p":"貸金業法の書面の再発行手数料は、利息と「みなされません」。","w":"第6条第1項・施行令第1条第2号。","r":[["利息制限法","6"],["利息制限法施行令","1"]]}}},"17-18":{"s":"登録の拒否事由（第6条第1項）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"執行猶予の期間を取り消されることなく経過すると、刑の言渡しは効力を失うので、拒否事由に「該当しません」。","w":"刑法第27条第1項。第6条第1項第4号の「刑に処せられ…5年を経過しない者」に当たらなくなります（現行法では「懲役」は「拘禁刑」になっています）。","r":[["刑法","27"],["貸金業法","6"]]},"2":{"t":true,"w":"施行規則第5条の7第1項第2号：常務に従事する役員のうちに貸付けの業務に3年以上従事した経験を有する者が必要です。満たさなければ第6条第1項第15号に該当します。","r":[["貸金業法","6"],["貸金業法施行規則","5の7"]]},"3":{"t":true,"w":"第6条第1項第4号・第9号ロ：どの法律の違反でも、拘禁刑（旧懲役）以上の刑に処せられ、執行を終わるなどした日から5年を経過しない者が役員にいれば拒否事由です。","r":[["貸金業法","6"]]},"4":{"t":true,"w":"第6条第1項第14号・施行令第3条の2：純資産額が5,000万円に満たない者。","r":[["貸金業法","6"],["貸金業法施行令","3の2"]]}}},"17-19":{"s":"監督指針のシステムリスク管理態勢の着眼点です。適切でないのは③です。","items":{"1":{"t":true,"w":"監督指針（システムリスク管理）のサイバーセキュリティ事案の定義のとおりです。"},"2":{"t":true,"w":"監督指針（システムリスク管理）の着眼点のとおりです。"},"3":{"t":false,"p":"「通常の業務では使用しないシステム領域に格納されたデータ」も、洗い出しの対象範囲に「含まれます」。","w":"監督指針（情報セキュリティ管理）ニ：洗い出しの対象範囲として、通常の業務では使用しないシステム領域に格納されたデータ、障害解析用データ、現金自動設備等に保存されている取引ログ等が例示されています。"},"4":{"t":true,"w":"監督指針（システム監査）の着眼点のとおりです。"}}},"17-20":{"s":"極度方式基本契約の途中の調査（第13条の3）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"施行規則第10条の24第1項第1号：1か月の貸付けの合計額が5万円を超え、「かつ」期間の末日の残高が10万円を超えるときに調査が必要です。残高5万円なら不要です。","r":[["貸金業法施行規則","10の24"]]},"2":{"t":true,"w":"施行規則第10条の25第3項第1号：3か月ごとの調査が免除されるのは残高10万円以下の場合などです。30万円なら必要です。","r":[["貸金業法","13の3"],["貸金業法施行規則","10の25"]]},"3":{"t":true,"w":"第13条の3第3項・第5項：極度方式個人顧客合算額は、極度額50万円＋他社残高60万円＝110万円で100万円を超えるので、年収証明書が必要です（残高30万円ではなく極度額で計算します）。","r":[["貸金業法","13の3"]]},"4":{"t":false,"p":"極度額を「減額」する措置では、3か月ごとの調査は免除「されません」。免除されるのは、新たな貸付けを「停止」する措置を講じている場合などです。","w":"施行規則第10条の25第3項第2号・第10条の29。","r":[["貸金業法施行規則","10の25"],["貸金業法施行規則","10の29"]]}}},"17-21":{"s":"極度方式基本契約の契約締結前の書面（第16条の2第2項）の記載事項です。該当しないのは①です。","items":{"1":{"t":false,"p":"契約の相手方となろうとする者の氏名・住所は、契約締結前の書面の記載事項では「ありません」。","w":"第16条の2第2項・施行規則第12条の2第2項第1号に挙げられていません（契約締結時の書面では記載します）。","r":[["貸金業法","16の2"],["貸金業法施行規則","12の2"]]},"2":{"t":true,"w":"施行規則第12条の2第2項第1号ヘ。","r":[["貸金業法施行規則","12の2"]]},"3":{"t":true,"w":"施行規則第12条の2第2項第1号ホ。","r":[["貸金業法施行規則","12の2"]]},"4":{"t":true,"w":"第16条の2第2項第4号。","r":[["貸金業法","16の2"]]}}},"17-22":{"s":"極度方式基本契約の書面と、その枠内の個々の借入れ（個別契約）の書面で、省略・代替できる記載を問う問題です（利息制限法の上限以下の契約）。適切でないのは③です。","items":{"1":{"t":true,"w":"施行規則第13条第1項第1号イかっこ書：極度方式貸付けに係る契約で、利息が旧利息制限法の制限額を超えないものは、登録番号の記載を省略できます。","r":[["貸金業法施行規則","13"]]},"2":{"t":true,"w":"施行規則第13条第1項第1号ヘかっこ書：基本契約の書面に記載されているときは、利息の計算の方法の記載を省略できます。","r":[["貸金業法施行規則","13"]]},"3":{"t":false,"p":"貸付けの利率は、基本契約の書面に記載していても、個別契約の書面で省略「できません」。","w":"貸付けの利率は第17条第1項第4号で法律が直接定める記載事項で、省略を認める定めはありません。","r":[["貸金業法","17"]]},"4":{"t":true,"w":"施行規則第13条第1項第1号チかっこ書：次回の返済期日及び返済金額をもって代えることができます。","r":[["貸金業法施行規則","13"]]}}},"17-23":{"s":"契約締結時の書面を再交付しなければならない変更（施行規則第13条第2項）を問う問題です。相手方に有利な変更なら不要になる事項（同項第1号イ）と、有利でも必要な事項（同号ロ）の区別がポイントです。適切でないのは②です。","items":{"1":{"t":true,"w":"利息の計算の方法（施行規則第13条第1項第1号ヘ）は、同条第2項第1号イの事項で、相手方の利益となる変更なら再交付は不要です。","r":[["貸金業法施行規則","13"]]},"2":{"t":false,"p":"「返済の方法及び返済を受ける場所」の変更は、相手方の利益となる変更でも再交付が「必要」です。","w":"施行規則第13条第1項第1号トの事項は、同条第2項第1号ロに挙げられていて、利益となる変更を除く定めがありません。","r":[["貸金業法施行規則","13"]]},"3":{"t":true,"w":"債務者が負担すべき元本及び利息以外の金銭に関する事項（施行規則第13条第1項第1号ニ）は、同条第2項第1号イの事項です。","r":[["貸金業法施行規則","13"]]},"4":{"t":true,"w":"期限の利益の喪失の定め（施行規則第13条第1項第1号ヌ）は、同条第2項第1号イの事項です。","r":[["貸金業法施行規則","13"]]}}},"17-24":{"s":"受取証書（第18条）の交付時期・記載事項を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"受取証書は「遅滞なく」ではなく、弁済を受けたその都度「直ちに」交付します。","w":"第18条第1項。","r":[["貸金業法","18"]]},"2":{"t":true,"w":"第18条第2項。","r":[["貸金業法","18"]]},"3":{"t":true,"w":"施行規則第15条第2項：登録番号（同条第1項第2号）と債務者の商号等（第3号）は、契約番号その他により明示して代えることができます。","r":[["貸金業法施行規則","15"]]},"4":{"t":true,"w":"第18条第1項第3号・第4号。","r":[["貸金業法","18"]]}}},"17-25":{"s":"取立て行為の規制（第21条）と監督指針を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"第21条第2項第2号：書面を送付する者の氏名。","r":[["貸金業法","21"]]},"2":{"t":true,"w":"第21条第1項第9号。","r":[["貸金業法","21"]]},"3":{"t":true,"w":"施行規則第19条第2項。","r":[["貸金業法施行規則","19"]]},"4":{"t":false,"p":"保証契約に基づく求償権の取立てにも、第21条が「適用され得る」とされています。適用されないのではありません。","w":"監督指針Ⅱ－2－19（2）⑧：貸金業者以外の者が貸し付けた債権について、貸金業者が保証契約に基づき求償権を有する場合（保証履行により取得した場合を含む）、その取立てには第21条が適用され得ることに留意します。","r":[["貸金業法","21"]]}}},"17-26":{"s":"登録行政庁による監督（立入検査・登録の取消し・業務改善命令）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"立入検査は「3年毎に必ず」行うものではなく、資金需要者等の利益の保護を図るため「必要があると認めるとき」に行えます。","w":"第24条の6の10第3項。","r":[["貸金業法","24の6の10"]]},"2":{"t":true,"w":"第12条（名義貸しの禁止）違反は、第24条の6の5第1項第4号で、登録を取り消さなければなりません。","r":[["貸金業法","12"],["貸金業法","24の6の5"]]},"3":{"t":true,"w":"第24条の6の6第1項第2号。","r":[["貸金業法","24の6の6"]]},"4":{"t":true,"w":"第24条の6の3第1項（業務改善命令）。","r":[["貸金業法","24の6の3"]]}}},"17-27":{"s":"媒介手数料・利息の上限と、その違反の扱い（行政処分・刑事罰）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"貸金業法第12条の8第10項。","r":[["貸金業法","12の8"]]},"2":{"t":true,"w":"出資法第4条第1項：貸借の金額の100分の5を超える媒介手数料の契約・受領は禁止され、罰則の対象です。","r":[["出資法","4"]]},"3":{"t":true,"w":"貸金業法第12条の8第1項：利息制限法第1条の金額を超える利息の契約を締結してはなりません。違反は法令違反として行政処分（第24条の6の4）の対象です。","r":[["貸金業法","12の8"],["貸金業法","24の6の4"]]},"4":{"t":false,"p":"出資法で刑事罰の対象となるのは年20%を「超える」利息の契約です。年20%ちょうどは対象外です（元本100万円の利息制限法の上限15%は超えるので、超える部分は民事上無効です）。","w":"出資法第5条第2項・利息制限法第1条第3号。","r":[["出資法","5"],["利息制限法","1"]]}}},"17-28":{"s":"未成年者・成年被後見人の行為能力を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"目的を定めないで処分を許した財産も、未成年者は自由に処分「できます」。","w":"民法第5条第3項。","r":[["民法","5"]]},"2":{"t":false,"p":"許された営業「以外」の法律行為は、成年者と同一の行為能力が認められないので、取り消すことが「できます」。","w":"民法第6条第1項（許された営業に関してだけ成年者と同一の行為能力）・第5条第2項。","r":[["民法","6"],["民法","5"]]},"3":{"t":true,"w":"民法第8条・第843条第4項（成年後見人となる者が法人であるときは、その事業の種類などを考慮する、と定めており、法人も成年後見人になれます）。","r":[["民法","8"],["民法","843"]]},"4":{"t":false,"p":"成年被後見人の行為は、成年後見人の同意を得ていても取り消すことが「できます」（日常生活に関する行為を除く）。","w":"民法第9条。","r":[["民法","9"]]}}},"17-29":{"s":"時効の完成猶予（時効がしばらく完成しないこと）と更新を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"時効の利益は、あらかじめ放棄することが「できません」。","w":"民法第146条。","r":[["民法","146"]]},"2":{"t":true,"w":"民法第147条第1項第3号：民事調停は完成猶予の事由で、権利が確定することなく終了した場合は、終了の時から6箇月を経過するまで時効は完成しません。","r":[["民法","147"]]},"3":{"t":false,"p":"催告による完成猶予の間にした再度の催告には、完成猶予の効力が「ありません」。","w":"民法第150条第2項。","r":[["民法","150"]]},"4":{"t":false,"p":"協議を行う旨の書面による合意は、時効の「更新」（新たに進行し直すこと）ではなく「完成猶予」の事由です（原則として合意から1年を経過するまでなど）。","w":"民法第151条第1項。","r":[["民法","151"]]}}},"17-30":{"s":"質権と抵当権の効力を問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"民法第344条：質権の設定は、債権者に目的物を引き渡すことによって効力を生じます。","r":[["民法","344"]]},"2":{"t":false,"p":"質権者は、質権設定者の承諾がなくても、自己の責任で転質を「できます」。","w":"民法第348条。","r":[["民法","348"]]},"3":{"t":false,"p":"被担保債権に不履行があったときは、その後に生じた抵当不動産の果実（賃料など）に抵当権が「及びます」。","w":"民法第371条。","r":[["民法","371"]]},"4":{"t":false,"p":"利息などの定期金は、「全額」ではなく、満期となった「最後の2年分」についてのみ抵当権を行使できます。","w":"民法第375条第1項。","r":[["民法","375"]]}}},"17-31":{"s":"保証債務の範囲・付従性・時効・情報提供義務を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"保証人は、その保証債務についてのみ、違約金又は損害賠償の額を約定することが「できます」。","w":"民法第447条第2項。","r":[["民法","447"]]},"2":{"t":false,"p":"主たる債務が「加重」されても、保証人の負担は加重されません（軽減されれば、保証人の負担も主たる債務の限度に減縮されます）。","w":"民法第448条第2項・第1項。","r":[["民法","448"]]},"3":{"t":false,"p":"主たる債務者への履行の請求などによる時効の完成猶予・更新は、保証人に対しても効力を「生じます」。","w":"民法第457条第1項。","r":[["民法","457"]]},"4":{"t":true,"w":"民法第458条の3第1項・第3項。","r":[["民法","458の3"]]}}},"17-32":{"s":"弁済（受領権者の外観・第三者弁済・充当・弁済の提供）を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"受領権者としての外観を有する者への弁済が有効になるのは、弁済者が善意で、かつ「過失がない」ときに限られます。","w":"民法第478条。","r":[["民法","478"]]},"2":{"t":true,"w":"民法第474条第4項：当事者が第三者の弁済を禁止し、又は制限する旨の意思表示をしたときは、第三者は弁済できません（正当な利益を有する第三者でも同じです）。","r":[["民法","474"]]},"3":{"t":false,"p":"充当の順序について合意があるときは、その「合意の順序」に従います。費用→利息→元本の順は、合意がない場合のルールです。","w":"民法第490条・第489条第1項。","r":[["民法","490"],["民法","489"]]},"4":{"t":false,"p":"債権者があらかじめ受領を拒んでいるときは、弁済の準備をしたことを通知して受領の催告をすれば「足ります」（口頭の提供）。","w":"民法第493条ただし書。","r":[["民法","493"]]}}},"17-33":{"s":"相続（胎児・法定相続分・限定承認・相続債務）を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"胎児は、相続については既に生まれたものとみなされるので、生きて生まれれば相続人に「なります」。","w":"民法第886条。","r":[["民法","886"]]},"2":{"t":false,"p":"配偶者と直系尊属（親）が相続人のとき、親の相続分は3分の2ではなく「3分の1」です（配偶者が3分の2）。","w":"民法第900条第2号。","r":[["民法","900"]]},"3":{"t":false,"p":"共同相続人の限定承認は全員が共同してのみできるので、Ｂが単純承認すると、ＣとＤだけで限定承認は「できません」。","w":"民法第923条。","r":[["民法","923"]]},"4":{"t":true,"w":"民法第899条：各共同相続人は、相続分に応じて被相続人の権利義務を承継します。遺産分割協議で借入金債務の負担者を決めても、債権者Ｄはそれに拘束されず、法定相続分に応じて請求できる、というのは判例の考え方です（条文には直接書かれていません。相続分の指定については第902条の2）。","r":[["民法","899"],["民法","902の2"]]}}},"17-34":{"s":"破産法（同時廃止・免責・復権）を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"破産財団で手続の費用が足りないときは、申立ての「却下」ではなく、破産手続開始の決定と「同時に破産手続廃止」の決定をします（同時廃止）。","w":"破産法第216条第1項。却下されるのは、費用の予納がないときなどです（第30条第1項第1号）。","r":[["破産法","216"],["破産法","30"]]},"2":{"t":false,"p":"免責許可の申立ての期間は、破産手続開始の申立てがあった日から「破産手続開始の決定が確定した日以後1月を経過する日まで」です。","w":"破産法第248条第1項。","r":[["破産法","248"]]},"3":{"t":false,"p":"浪費や賭博などの免責不許可事由があっても、裁判所は一切の事情を考慮して免責を許可することが「できます」（裁量免責）。","w":"破産法第252条第1項・第2項。","r":[["破産法","252"]]},"4":{"t":true,"w":"破産法第255条第1項第1号。","r":[["破産法","255"]]}}},"17-35":{"s":"犯罪収益移転防止法の取引時確認・疑わしい取引の届出・記録の保存を問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"犯罪収益移転防止法第4条第4項・第5項：会社のために現に取引の任に当たっている自然人（担当者）が顧客等と異なるときは、顧客等の確認に加えて、その担当者の本人特定事項の確認も必要です。","r":[["犯罪収益移転防止法","4"]]},"2":{"t":false,"p":"公共料金の領収証書は本人確認書類では「ありません」。本人確認書類に現在の住居が書かれていない場合などに、補完的に使う書類です。","w":"本人確認書類は犯罪収益移転防止法施行規則第7条。公共料金の領収証書は同規則第6条第2項第3号（補完書類）に挙げられています。","r":[["犯罪収益移転防止法施行規則","7"],["犯罪収益移転防止法施行規則","6"]]},"3":{"t":false,"p":"疑わしい取引の届出先は「行政庁」だけで、指定信用情報機関に届け出る定めは「ありません」。","w":"犯罪収益移転防止法第8条第1項。","r":[["犯罪収益移転防止法","8"]]},"4":{"t":false,"p":"確認記録の保存期間7年は、「取引時確認を行った日」ではなく「特定取引等に係る契約が終了した日など」から数えます。","w":"犯罪収益移転防止法第6条第2項。","r":[["犯罪収益移転防止法","6"]]}}},"17-36":{"s":"代理（代理行為の瑕疵・双方代理・無権代理）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"民法第101条第1項：代理人がした意思表示の効力が詐欺などによって影響を受けるべき場合、その事実の有無は代理人について決します。","r":[["民法","101"]]},"2":{"t":true,"w":"民法第108条第1項：当事者双方の代理人としてした行為（双方代理）は、本人があらかじめ許諾した場合などを除き、代理権を有しない者がした行為とみなします。","r":[["民法","108"]]},"3":{"t":true,"w":"民法第114条（無権代理の相手方の催告権）。","r":[["民法","114"]]},"4":{"t":false,"p":"契約の時に代理権がないことを知っていた相手方は、取り消すことが「できません」。","w":"民法第115条ただし書。","r":[["民法","115"]]}}},"17-37":{"s":"取消し・無効・法定追認を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"民法第120条第1項。","r":[["民法","120"]]},"2":{"t":true,"w":"民法第121条。","r":[["民法","121"]]},"3":{"t":true,"w":"民法第119条。","r":[["民法","119"]]},"4":{"t":false,"p":"権利の譲渡などで追認したとみなされる（法定追認）のは、追認をすることができる時より「前」ではなく「以後」にした場合です。","w":"民法第125条。","r":[["民法","125"]]}}},"17-38":{"s":"債務引受（他人の債務を引き受けること）を問う問題です。併存的債務引受は元の債務者と並んで負担し、免責的債務引受は元の債務者が債務を免れます。適切でないのは②です。","items":{"1":{"t":true,"w":"民法第470条第1項。","r":[["民法","470"]]},"2":{"t":false,"p":"併存的債務引受は、三者間の契約でなくても、債権者と引受人となる者との契約（又は債務者と引受人となる者との契約）で「できます」。","w":"民法第470条第2項・第3項。","r":[["民法","470"]]},"3":{"t":true,"w":"民法第472条第1項。","r":[["民法","472"]]},"4":{"t":true,"w":"民法第472条の3。","r":[["民法","472の3"]]}}},"17-39":{"s":"相殺の禁止と効力を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"相殺が禁止されるのは、悪意の不法行為の「加害者（損害賠償債務を負う側）」からの相殺です。被害者Ａが損害賠償債権を使って相殺することは「できます」。","w":"民法第509条第1号：悪意による不法行為に基づく損害賠償の「債務の債務者」は、相殺をもって債権者に対抗することができません。","r":[["民法","509"]]},"2":{"t":true,"w":"相手方Ｂが同時履行の抗弁（納品と引換えでなければ払わないと言える権利）を持つ債権を、自働債権として相殺することはできません。これは判例の考え方です（条文には直接書かれていません）。","r":[["民法","505"]]},"3":{"t":true,"w":"民法第511条第1項：差押え後に取得した債権による相殺は、差押債権者に対抗できません。","r":[["民法","511"]]},"4":{"t":true,"w":"民法第506条第2項。","r":[["民法","506"]]}}},"17-40":{"s":"契約の成立・危険負担・契約上の地位の移転・解除を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"民法第526条。","r":[["民法","526"]]},"2":{"t":true,"w":"民法第536条第1項。","r":[["民法","536"]]},"3":{"t":false,"p":"契約上の地位の移転には、相手方への「通知」ではなく、相手方の「承諾」が必要です。","w":"民法第539条の2。","r":[["民法","539の2"]]},"4":{"t":true,"w":"民法第545条第1項。","r":[["民法","545"]]}}},"17-41":{"s":"請負契約（仕事の完成に対して報酬を払う契約）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"民法第632条。","r":[["民法","632"]]},"2":{"t":true,"w":"民法第633条。","r":[["民法","633"]]},"3":{"t":true,"w":"民法第636条に、記述のとおりの定めがあります。","r":[["民法","636"]]},"4":{"t":false,"p":"仕事の完成前にいつでも解除できるのは「注文者」だけで、しかも損害を賠償する必要があります。請負人にはこの解除権は「ありません」。","w":"民法第641条。","r":[["民法","641"]]}}},"17-42":{"s":"不当利得（法律上の理由なく得た利益）と不法行為を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"民法第719条第1項。","r":[["民法","719"]]},"2":{"t":true,"w":"民法第724条（人の生命・身体を害する場合は第724条の2で「5年間」に延長）。","r":[["民法","724"],["民法","724の2"]]},"3":{"t":false,"p":"利息を付して返還する義務があるのは「悪意」の受益者だけです。善意の受益者は、その利益の存する限度（現存利益）で返還すれば足ります。","w":"民法第703条・第704条。","r":[["民法","703"],["民法","704"]]},"4":{"t":true,"w":"民法第706条。","r":[["民法","706"]]}}},"17-43":{"s":"個人情報保護法の利用目的（特定・変更・通知）を問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"個人情報保護法第17条第1項・第2項。","r":[["個人情報保護法","17"]]},"2":{"t":false,"p":"承継前の利用目的の範囲を超えて取り扱うには、通知・公表では足りず、あらかじめ本人の「同意」が必要です。","w":"個人情報保護法第18条第2項。","r":[["個人情報保護法","18"]]},"3":{"t":false,"p":"取得の状況からみて利用目的が明らかな場合は、変更後の利用目的の通知・公表も「不要」です。","w":"個人情報保護法第21条第3項・第4項第4号（第4項は前三項すべてに適用されます）。","r":[["個人情報保護法","21"]]},"4":{"t":false,"p":"契約書などで本人から直接取得する場合は、あらかじめ利用目的を「明示」すれば足り、本人の「同意」までは必要ありません。","w":"個人情報保護法第21条第2項。","r":[["個人情報保護法","21"]]}}},"17-44":{"s":"消費者契約法の取消し・期間・不当条項を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"取り消せるのは、不実告知によって消費者が「誤認」し、それによって契約した場合です。誤認したか否かに「かかわらず」取り消せるわけではありません。","w":"消費者契約法第4条第1項第1号。","r":[["消費者契約法","4"]]},"2":{"t":false,"p":"取消権の期間は「6か月」ではなく、追認できる時から「1年間」（締結の時から5年）です。","w":"消費者契約法第7条第1項。","r":[["消費者契約法","7"]]},"3":{"t":false,"p":"退去させないことによる困惑で締結した契約は、「無効」ではなく、消費者が「取り消す」ことができます。","w":"消費者契約法第4条第3項。","r":[["消費者契約法","4"]]},"4":{"t":true,"w":"消費者契約法第9条第1項第2号。","r":[["消費者契約法","9"]]}}},"17-45":{"s":"協会の自主規制基本規則で、審査機関の承認が必要な広告の媒体です。正しいのは②です。","items":{"1":{"t":false,"p":"インターネット広告は、審査機関の承認が必要な媒体に「含まれません」。","w":"自主規制基本規則第45条第1項：承認が必要なのは、テレビCM、新聞及び雑誌広告、電話帳広告です。"},"2":{"t":true,"w":"自主規制基本規則第45条第1項第2号。"},"3":{"t":false,"p":"チラシ広告は、審査機関の承認が必要な媒体に「含まれません」。","w":"自主規制基本規則第45条第1項。"},"4":{"t":false,"p":"看板広告は、審査機関の承認が必要な媒体に「含まれません」。","w":"自主規制基本規則第45条第1項。"}}},"17-46":{"s":"個人情報保護法ガイドライン（通則編）の安全管理措置（組織的・人的・物理的・技術的）の分類を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"通則編ガイドライン（物理的安全管理措置）のとおりです。"},"2":{"t":true,"w":"通則編ガイドライン（人的安全管理措置）のとおりです。"},"3":{"t":false,"p":"担当者や取り扱う個人情報データベース等の範囲を限定する「アクセス制御」は、組織的安全管理措置ではなく「技術的安全管理措置」です。","w":"通則編ガイドライン：技術的安全管理措置として（1）アクセス制御、（2）アクセス者の識別と認証、（3）外部からの不正アクセス等の防止、（4）情報システムの使用に伴う漏えい等の防止を挙げています。"},"4":{"t":true,"w":"通則編ガイドライン（技術的安全管理措置（2）アクセス者の識別と認証）のとおりです。"}}},"17-47":{"s":"景品表示法（景品類の定義・景品の制限・不実証広告・罰則）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"景品類は、事業者が自己の供給する商品又は役務の「取引に付随して」提供するものに限られます。付随するかどうかを「問わない」わけではありません。","w":"景品表示法第2条第3項。","r":[["景品表示法","2"]]},"2":{"t":true,"w":"景品表示法第4条。","r":[["景品表示法","4"]]},"3":{"t":true,"w":"景品表示法第7条第2項。","r":[["景品表示法","7"]]},"4":{"t":true,"w":"景品表示法第46条：措置命令に違反したときは、2年以下の拘禁刑又は300万円以下の罰金に処します。","r":[["景品表示法","46"]]}}},"17-48":{"s":"給与所得者の収入の確認と源泉徴収票の見方を問う問題です。所得税法と源泉徴収票の様式は取り込んだ資料にないため、②〜④の結論は公式正答によります。正しいのは③です。","items":{"1":{"t":false,"p":"収入を把握できる書類は、源泉徴収票と給与明細書に「限られません」。","w":"貸金業法施行規則第10条の17第1項：収入又は収益その他の資力を明らかにする書面として、源泉徴収票・給与の支払明細書のほか、支払調書、確定申告書、納税通知書、納税証明書、所得証明書などが挙げられています。","r":[["貸金業法施行規則","10の17"]]},"2":{"t":false,"p":"公式正答では適切でないとされています。確定申告が必要となる給与収入の金額の基準は、取り込んだ資料では確認できません。","w":"結論は公式正答によります。"},"3":{"t":true,"w":"結論は公式正答によります（源泉徴収票の様式は取り込んだ資料にありません）。"},"4":{"t":false,"p":"公式正答では適切でないとされています。控除対象配偶者の要件（判定の基準日や所得の金額）は、取り込んだ資料では確認できません。","w":"結論は公式正答によります。"}}},"17-49":{"s":"損益計算書の意味と段階利益を問う問題です。会社計算規則は取り込んでいないため、同じ考え方を定めた企業会計原則の損益計算書原則で確認します。正しいのは②です。","items":{"1":{"t":false,"p":"損益計算書は、ある時点の「財政状態」ではなく、一会計期間の「経営成績」を明らかにするものです（ある時点の財政状態を表すのは貸借対照表です）。","w":"企業会計原則・損益計算書原則一：損益計算書は、企業の経営成績を明らかにするため、一会計期間に属するすべての収益とこれに対応するすべての費用とを記載します。"},"2":{"t":true,"w":"企業会計原則・損益計算書原則三：売上総利益から販売費及び一般管理費を控除して営業利益を表示します。"},"3":{"t":false,"p":"営業利益に特別損益を加減したものではありません。経常利益は、営業利益に「営業外収益」を加え「営業外費用」を控除したものです。","w":"企業会計原則・損益計算書原則五。特別損益は経常利益の後に加減します（同原則七）。"},"4":{"t":false,"p":"経常利益から税金を差し引くのではなく、経常利益に特別損益を加減した「税引前当期純利益」から税金を差し引いたものが当期純利益です。","w":"企業会計原則・損益計算書原則七・八。"}}},"17-50":{"s":"企業会計原則の一般原則を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"企業会計原則・一般原則一（真実性の原則）。"},"2":{"t":true,"w":"企業会計原則・一般原則三（資本取引・損益取引区分の原則）。"},"3":{"t":false,"p":"明瞭に表示する手段は「財産目録及び出納帳簿」ではなく「財務諸表」で、名称も「適切性の原則」ではなく「明瞭性の原則」です。","w":"企業会計原則・一般原則四：財務諸表によって、利害関係者に対し必要な会計事実を明瞭に表示し、企業の状況に関する判断を誤らせないようにしなければなりません。"},"4":{"t":true,"w":"企業会計原則・一般原則七（単一性の原則）。"}}},"18-01":{"s":"貸金業法第2条の用語の定義です。適切なのはｃとｄです（2個）。","items":{"a":{"t":false,"p":"「貸金業者」は、第3条第1項の登録を受けた者です。貸付けに係る契約について業として保証を行う者（保証業者）は「含まれません」。","w":"第2条第2項：「貸金業者」とは、次条第1項の登録を受けた者をいいます。保証業者は、第24条の2などで貸金業者とは別に扱われています。","r":[["貸金業法","2"],["貸金業法","24の2"]]},"b":{"t":false,"p":"「資金需要者等」は「顧客、債務者又は債務者であった者」ではなく、「顧客等又は債務者等」です。","w":"第2条第4項〜第6項：顧客等＝資金需要者である顧客又は保証人となろうとする者、債務者等＝債務者又は保証人、資金需要者等＝顧客等又は債務者等。","r":[["貸金業法","2"]]},"c":{"t":true,"w":"第2条第17項の定義どおりです。","r":[["貸金業法","2"]]},"d":{"t":true,"w":"第2条第23項の定義どおりです。","r":[["貸金業法","2"]]}}},"18-02":{"s":"登録の拒否事由（第6条第1項）です。拒否されるのはｂとｃです。","items":{"a":{"t":false,"p":"拒否事由は「破産手続開始の決定を受けて復権を得ない者」です。復権を得ていれば、5年を経過していなくても拒否事由に当たりません。","w":"第6条第1項第2号。","r":[["貸金業法","6"]]},"b":{"t":true,"w":"第6条第1項第5号：貸金業法・出資法などの規定に違反し、罰金の刑に処せられ、その刑の執行を終わり、又は刑の執行を受けることがなくなった日から5年を経過しない者。","r":[["貸金業法","6"]]},"c":{"t":true,"w":"第6条第1項第3号かっこ書：登録を取り消された法人の、取消しの日前30日以内に役員であった者で、取消しの日から5年を経過しないもの。","r":[["貸金業法","6"]]},"d":{"t":false,"p":"求められるのは「貸付けの業務に3年以上従事した経験」で、貸金業者での経験に限られていません。金融機関での経験でも基準を満たすので、拒否されません。","w":"施行規則第5条の7第1項第2号：常務に従事する役員のうちに貸付けの業務に3年以上従事した経験を有する者があること。貸金業者以外での経験が含まれることの結論は公式正答によります。","r":[["貸金業法施行規則","5の7"]]}}},"18-03":{"s":"監督指針Ⅱ－2－6（反社会的勢力による被害の防止）の着眼点です。適切でないのはｃだけです（3個）。","items":{"a":{"t":true,"w":"監督指針Ⅱ－2－6②（反社会的勢力対応部署による一元的な管理態勢の構築）とイに、記述のとおりの着眼点があります。"},"b":{"t":true,"w":"監督指針Ⅱ－2－6③（適切な事前審査の実施）のとおりです。"},"c":{"t":false,"p":"弁済が滞るまで契約解消を行わないのではなく、反社会的勢力と判明した時点で可能な限り速やかに関係を解消し、可能な限り回収を図るなど、利益供与にならないよう配意します。","w":"監督指針Ⅱ－2－6：相手方が反社会的勢力であると判明した時点で可能な限り速やかに関係を解消するための態勢整備を求め、⑤ハで、可能な限り回収を図るなど反社会的勢力への利益供与にならないよう配意しているか、としています。"},"d":{"t":true,"w":"監督指針Ⅱ－2－6⑥ハのとおりです。"}}},"18-04":{"s":"貸金業務取扱主任者の登録と設置を問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"第24条の27第1項第7号：第24条の30各号のいずれかに該当することにより主任者登録の取消しの処分を受け、その処分の日から5年を経過しない者は、主任者登録を拒否されます。","r":[["貸金業法","24の27"],["貸金業法","24の30"]]},"2":{"t":false,"p":"講習を受けるだけでは更新されず、更新の「申請」が必要です。","w":"第24条の32第1項：主任者登録は、申請により更新します。講習の受講は、更新を受けようとする者の要件です（同条第2項）。","r":[["貸金業法","24の32"],["貸金業法","24の25"]]},"3":{"t":false,"p":"営業時間内にその営業所等に常時駐在している必要は「ありません」。","w":"監督指針Ⅱ－2－9（2）①：「常時勤務する者」とは、営業時間内に常時駐在する必要はないが、所属する営業所等が1つに決まっているだけでは足りず、社会通念に照らし常時勤務していると認められるだけの実態を必要とします。","r":[["貸金業法施行規則","10の7"]]},"4":{"t":false,"p":"定年退職は会社として予見できるので、「2週間以内」の猶予は認められません。2週間の猶予があるのは、急な死亡や失踪など「予見し難い事由」の場合です。","w":"第12条の3第3項：予見し難い事由により主任者の数が不足したときは、2週間以内に必要な措置をとらなければなりません。監督指針Ⅱ－2－9（2）③：「予見し難い事由」は急な死亡や失踪など限定的に解釈され、会社の都合や定年による退職などは含まれません。","r":[["貸金業法","12の3"]]}}},"18-05":{"s":"年収証明書（源泉徴収票など）の提出が必要な場面と、監督指針の解釈を問う問題です。適切なのはｃとｄです。","items":{"a":{"t":false,"p":"自社の貸付けが60万円で50万円を超えるので、他社残高との合計が100万円未満でも、年収証明書は「必要」です。","w":"第13条第3項第1号：当該貸金業者合算額が50万円を超える場合。","r":[["貸金業法","13"]]},"b":{"t":false,"p":"給与の支払明細書は「直近1年以内の任意の2か月分」ではなく、「直近2月分以上」のものが必要です。","w":"施行規則第10条の17第2項第2号。","r":[["貸金業法施行規則","10の17"]]},"c":{"t":true,"w":"監督指針Ⅱ－2－13－1（2）②ロ：施行規則第10条の17第1項第8号の「所得証明書」には、根拠法令なく、行政サービスの一環として地方公共団体が交付する所得・課税証明書などが含まれます。","r":[["貸金業法施行規則","10の17"]]},"d":{"t":true,"w":"監督指針Ⅱ－2－13－1（1）ハのなお書のとおりです。","r":[["貸金業法","13の2"]]}}},"18-06":{"s":"総量規制の除外契約（施行規則第10条の21）の要件です。適切なのはｂ・ｃ・ｄです（3個）。","items":{"a":{"t":false,"p":"住宅（不動産）の改良に必要な資金の貸付けは、担保の有無に「かかわらず」除外契約です。","w":"施行規則第10条の21第1項第1号：不動産の建設若しくは購入に必要な資金又は不動産の改良に必要な資金の貸付けに係る契約。担保の要件はありません。","r":[["貸金業法施行規則","10の21"]]},"b":{"t":true,"w":"施行規則第10条の21第1項第3号：自動車購入資金の貸付けのうち、自動車の所有権を貸金業者が取得し、又は自動車が譲渡により担保の目的となっているものに限られます。","r":[["貸金業法施行規則","10の21"]]},"c":{"t":true,"w":"施行規則第10条の21第1項第4号：個人顧客又は個人顧客の親族で「生計を一にする者」の高額療養費を支払うための貸付けに限られます。","r":[["貸金業法施行規則","10の21"]]},"d":{"t":true,"w":"施行規則第10条の21第1項第6号：不動産担保貸付けの対象から、個人顧客若しくは担保を提供する者の居宅などは除かれています。","r":[["貸金業法施行規則","10の21"]]}}},"18-07":{"s":"極度方式基本契約の3か月ごとの定期調査（第13条の3第2項）が不要になる場合と、調査後の措置を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"年収証明書が必要なのは、極度方式個人顧客合算額が100万円を「超える」ときです。80万円なら「不要」です。","w":"第13条の3第3項。","r":[["貸金業法","13の3"]]},"2":{"t":true,"w":"施行規則第10条の25第3項第1号：所定の期間の末日における極度方式貸付けの残高の合計額が10万円以下である場合は、定期調査は不要です。","r":[["貸金業法","13の3"],["貸金業法施行規則","10の25"]]},"3":{"t":false,"p":"利息の支払の遅延を理由に新たな貸付けを停止している場合は、残高にかかわらず定期調査は「不要」です。","w":"施行規則第10条の25第3項第3号イ：期間の末日に、元本又は利息の支払の遅延を理由として新たな極度方式貸付けの停止の措置が講じられている場合。","r":[["貸金業法施行規則","10の25"]]},"4":{"t":false,"p":"講じる措置は「新たな貸付けの停止又は解除」ではなく、「極度額の減額又は新たな貸付けの停止」です。","w":"第13条の4・施行規則第10条の29：基準額超過極度方式基本契約に該当しないようにするため必要な極度額の減額、又は新たな極度方式貸付けの停止。","r":[["貸金業法","13の4"],["貸金業法施行規則","10の29"]]}}},"18-08":{"s":"広告・勧誘の規制（貸金業法第16条）と協会の自主規制基本規則を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"貸付けの条件について著しく事実に相違する説明は、行政処分だけでなく刑事罰の対象にも「なります」。","w":"第16条第1項で禁止され、第48条第1項第3号で刑事罰（1年以下の拘禁刑若しくは300万円以下の罰金又は併科）の対象です。","r":[["貸金業法","16"],["貸金業法","48"]]},"2":{"t":true,"w":"自主規制基本規則第45条第1項：個人向け貸付けの契約に係る広告を、テレビCM、新聞及び雑誌広告、電話帳広告に出稿するにあたり、協会が設ける審査機関から承認を得なければなりません。"},"3":{"t":false,"p":"勧誘を引き続き受けることを希望しない旨の明確な意思表示があったときは、「3か月」ではなく「最低6か月」見合わせます。3か月は、単に契約を締結しない旨の意思表示があった場合です。","w":"自主規制基本規則第55条（再勧誘に関する留意事項）第1項第2号・第3号。"},"4":{"t":false,"p":"第16条違反は法令違反なので、業務改善命令だけでなく、登録の取消し（や業務停止）も「できます」。","w":"借入れが容易であることを過度に強調する表示は第16条第2項第3号で禁止されています。法令違反は第24条の6の4第1項第2号の処分事由で、登録の取消し又は1年以内の業務の停止を命ずることができます。業務改善命令は第24条の6の3です。","r":[["貸金業法","16"],["貸金業法","24の6の4"],["貸金業法","24の6の3"]]}}},"18-09":{"s":"契約締結前の書面（第16条の2）の対象と記載事項、保証人への交付方法を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"契約締結前の書面には、契約年月日や相手方の氏名・住所は「含まれません」。契約はまだ成立していないからです。","w":"第16条の2第2項各号（極度方式基本契約）は、貸金業者の商号等・極度額・貸付けの利率・返済の方式などです。","r":[["貸金業法","16の2"]]},"2":{"t":false,"p":"極度方式貸付け（枠の中での個々の借入れ）には、契約締結前の書面の交付義務は「ありません」。","w":"第16条の2第1項かっこ書：極度方式基本契約及び極度方式貸付けに係る契約を除きます（基本契約は同条第2項で交付）。","r":[["貸金業法","16の2"]]},"3":{"t":false,"p":"記載事項の内容に変更が生じた場合は、再交付が「必要」です。","w":"監督指針Ⅱ－2－16（2）②。","r":[["貸金業法","16の2"]]},"4":{"t":true,"w":"施行規則第12条の2第7項：保証契約の概要を記載した書面と詳細を記載した書面を、同時に交付しなければなりません。","r":[["貸金業法","16の2"],["貸金業法施行規則","12の2"]]}}},"18-10":{"s":"保証契約を締結したときに保証人に交付する書面（第17条第3項・第4項）を問う問題です。適切なのはｂとｄです。","items":{"a":{"t":false,"p":"保証契約の内容を明らかにする書面（第17条第3項）の交付先は、主たる債務者Ｂではなく「保証人Ｃ」です。","w":"第17条第3項：当該保証契約の保証人に交付しなければなりません。","r":[["貸金業法","17"]]},"b":{"t":true,"w":"第17条第3項・施行規則第13条第6項第1号：保証契約の書面には第16条の2第3項各号の事項を記載します。その第5号が、連帯保証の場合の民法第454条の趣旨（催告・検索の抗弁がないこと）です。","r":[["貸金業法","17"],["貸金業法","16の2"],["貸金業法施行規則","13"],["民法","454"]]},"c":{"t":false,"p":"保証債務の弁済の方式の変更は、保証人の利益となる変更でも、再交付が「必要」です。","w":"施行規則第13条第7項第1号ロ：第12条の2第6項第1号（保証契約に基づく債務の弁済の方式）は重要な事項で、利益となる変更を除く旨の定めがありません。","r":[["貸金業法","17"],["貸金業法施行規則","13"],["貸金業法施行規則","12の2"]]},"d":{"t":true,"w":"第17条第4項：保証契約を締結したときは、遅滞なく、第17条第1項各号の事項について貸付けに係る契約の内容を明らかにする書面を保証人にも交付します。","r":[["貸金業法","17"]]}}},"18-11":{"s":"極度方式基本契約の書面（第17条第2項）を再交付しなければならない変更かどうかを問う問題です。適切なのはａとｄです。","items":{"a":{"t":true,"w":"施行規則第13条第5項第2号：極度額を引き下げた後、元の額を上回らない額まで引き上げたときは、再交付は不要です（15万円→20万円は元の30万円を上回りません）。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"b":{"t":false,"p":"返済期日・返済金額の設定の方式の変更は、相手方に有利な変更（返済金額の引下げ）でも、再交付が「必要」です。","w":"施行規則第13条第4項第1号ロ：同条第3項第1号チ（各回の返済期日及び返済金額の設定の方式）などは、利益となる変更を除く定めがない重要な事項です。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"c":{"t":false,"p":"利率の「引下げ」は相手方の利益となる変更なので、再交付は「不要」です。","w":"施行規則第13条第4項第1号イかっこ書。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"d":{"t":true,"w":"登録番号（施行規則第13条第3項第1号イ）は、再交付が必要な重要な事項（同条第4項）に挙げられていません。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]}}},"18-12":{"s":"貸金業者が保存すべきものの保存期間です。正しいのは①です。","items":{"1":{"t":true,"w":"施行規則第10条の9の2第3項：従業者名簿は、最終の記載をした日から10年間保存します。","r":[["貸金業法","12の4"],["貸金業法施行規則","10の9の2"]]},"2":{"t":false,"p":"返済能力の調査の記録は「作成の日から10年間」ではなく、「その契約に定められた最終の返済期日（債権が消滅したときはその消滅した日）など」までの間保存します。","w":"施行規則第10条の18第2項。","r":[["貸金業法","13"],["貸金業法施行規則","10の18"]]},"3":{"t":false,"p":"基準額超過極度方式基本契約の調査記録の保存期間は「10年間」ではなく、作成後「3年間」です。","w":"施行規則第10条の27第2項。","r":[["貸金業法","13の3"],["貸金業法施行規則","10の27"]]},"4":{"t":false,"p":"帳簿の保存期間の起算点は「契約を締結した日」ではなく、「契約に定められた最終の返済期日（債権が消滅したときはその消滅した日）」です。","w":"施行規則第17条第1項：少なくとも10年間保存します。","r":[["貸金業法","19"],["貸金業法施行規則","17"]]}}},"18-13":{"s":"債権譲渡の規制（第24条）と届出（第24条の6の2）を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"譲受人が貸金業者である場合も通知は「必要」です。「譲受人が貸金業者である場合を除き」という例外はありません。","w":"第24条第1項。","r":[["貸金業法","24"]]},"2":{"t":false,"p":"債権譲渡後に、債権の内容を明らかにする書面（第17条の書面）を債務者に交付するのは、譲渡人ではなく「譲受人」です。","w":"第24条第2項：第17条（第6項を除く）などの規定は、債権を譲り受けた者に準用されます。","r":[["貸金業法","24"],["貸金業法","17"]]},"3":{"t":false,"p":"帳簿を譲受人に引き渡して保存義務を免れるという定めは「ありません」。譲受人は、自ら帳簿を備えて保存する義務を負います。","w":"第24条第2項で第19条（帳簿の備付け）が譲受人に準用されています。譲渡人の帳簿の保存期間は施行規則第17条第1項によります。","r":[["貸金業法","24"],["貸金業法","19"],["貸金業法施行規則","17"]]},"4":{"t":true,"w":"第24条の6の2第4号・施行規則第26条の25第1項第3号・第2項：債権を他人に譲渡した場合（法令の規定により第24条を適用しないこととされる場合を除く）は、2週間以内に届け出ます。","r":[["貸金業法","24の6の2"],["貸金業法施行規則","26の25"]]}}},"18-14":{"s":"監督指針Ⅱ－2－8（不祥事件）の記述です。4つとも適切です（4個）。","items":{"a":{"t":true,"w":"監督指針Ⅱ－2－8：不祥事件とは、法令に違反する行為のほか、資金需要者等の利益を損なうおそれのある詐欺・横領・背任等、資金需要者等から告訴・告発され又は検挙された行為などが該当します。","r":[["貸金業法施行規則","26の25"]]},"b":{"t":true,"w":"監督指針Ⅱ－2－8（1）①イ〜ハのとおりです。"},"c":{"t":true,"w":"監督指針Ⅱ－2－8（1）②イ〜ヘのとおりです。"},"d":{"t":true,"w":"監督指針Ⅱ－2－8（2）のとおりです。","r":[["貸金業法","24の6の10"]]}}},"18-15":{"s":"利息と保証料の上限を、出資法（刑事罰の上限 年20%）と利息制限法（民事上の上限）で判定する問題です。元本100万円の上限は利息制限法で年15%です。適切なのはａだけです（1個）。","items":{"a":{"t":true,"w":"出資法第5条第2項：業として貸し付ける場合に刑事罰の対象となるのは年20%を超える利息の契約です。年18%は超えないので対象外です。","r":[["出資法","5"]]},"b":{"t":false,"p":"保証料3%は、利息18%と合算すると年21%になり、20%を「超える」ので、Ｃは刑事罰の対象に「なります」。","w":"出資法第5条の2第1項：保証料が、保証に係る貸付けの利息と合算して年20パーセントを超える割合となる保証料の契約をしたときは処罰されます。","r":[["出資法","5の2"]]},"c":{"t":false,"p":"元本100万円の利息の上限は年15%なので、18%のうち15%を超える部分は「無効」です。全部が有効ではありません。","w":"利息制限法第1条第3号：元本の額が100万円以上の場合は年1割5分。","r":[["利息制限法","1"]]},"d":{"t":false,"p":"利息がすでに法定上限額（年15%分）を超えているので、保証料が入る余地はなく、保証料の契約は「全部」無効になります。","w":"利息制限法第8条第1項：保証料が、主たる債務の元本に係る法定上限額から主たる債務について支払うべき利息の額を減じて得た金額を超えるときは、その超過部分は無効です。15%−18%はマイナスなので、保証料3%は全額が超過部分です。","r":[["利息制限法","8"]]}}},"18-16":{"s":"利息とみなされない費用（利息制限法第6条・施行令）を問う問題です。適切なのはａとｂです。","items":{"a":{"t":true,"w":"利息制限法第6条第2項第3号・施行令第2条第2号：1万円を超える額のATM利用料は220円（消費税等を含む）まで、利息とみなされません。","r":[["利息制限法","6"],["利息制限法施行令","2"]]},"b":{"t":true,"w":"利息制限法第6条第2項第1号：公租公課の支払に充てられるべきもの。","r":[["利息制限法","6"]]},"c":{"t":false,"p":"再度の口座振替手続の費用は、利息と「みなされません」。","w":"利息制限法第6条第1項・施行令第1条第3号：口座振替の方法による弁済で、弁済期に弁済できなかった場合に行う再度の口座振替手続に要する費用。","r":[["利息制限法","6"],["利息制限法施行令","1"]]},"d":{"t":false,"p":"例外になるのはカードの「再発行」の手数料だけです。契約締結時に最初に交付するカードの発行手数料は、利息と「みなされます」。","w":"利息制限法第3条・第6条第1項・施行令第1条第1号。","r":[["利息制限法","3"],["利息制限法","6"],["利息制限法施行令","1"]]}}},"18-17":{"s":"変更の届出（第8条）で、「あらかじめ」届け出る事項（営業所の名称・所在地、広告等に表示する連絡先）と「2週間以内」に届け出る事項の区別です。適切でないのは④です。","items":{"1":{"t":true,"w":"主任者の氏名・登録番号は第4条第1項第6号の事項で、変更があった日から2週間以内に届け出ます（第8条第1項）。","r":[["貸金業法","8"],["貸金業法","4"]]},"2":{"t":true,"w":"役員の氏名は第4条第1項第2号の事項で、2週間以内に届け出ます。","r":[["貸金業法","8"],["貸金業法","4"]]},"3":{"t":true,"w":"広告等に表示する連絡先（ホームページアドレスを含む。施行規則第3条の2）は第4条第1項第7号の事項で、「あらかじめ」届け出ます。","r":[["貸金業法","8"],["貸金業法","4"],["貸金業法施行規則","3の2"]]},"4":{"t":false,"p":"業務の種類及び方法の変更は、「あらかじめ」ではなく、変更があった日から「2週間以内」に届け出ます。","w":"第4条第1項第8号の事項は、第8条第1項で事後の届出です。","r":[["貸金業法","8"],["貸金業法","4"]]}}},"18-18":{"s":"廃業等の届出（第10条）の届出義務者と期限（30日以内）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"届出が必要なのは破産手続開始の「申立て」ではなく「決定」があった場合で、届け出るのは会社ではなく「破産管財人」です。","w":"第10条第1項第3号。","r":[["貸金業法","10"]]},"2":{"t":true,"w":"第10条第1項第1号：貸金業者が死亡した場合は相続人が、その事実を知った日から30日以内に届け出ます。","r":[["貸金業法","10"]]},"3":{"t":true,"w":"第10条第1項第2号：合併により消滅した場合は、その法人を代表する役員であった者が届け出ます。","r":[["貸金業法","10"]]},"4":{"t":true,"w":"第10条第1項第6号：貸金業貸付媒介業務の種別に係る登録を受けた場合も届出事由です（法律名は現在「金融サービスの提供及び利用環境の整備等に関する法律」です）。","r":[["貸金業法","10"]]}}},"18-19":{"s":"監督指針の経営管理等・業務の適切性に関する記述です。適切でないのは②です。","items":{"1":{"t":true,"w":"監督指針Ⅱ－2（業務の適切性）の冒頭に、記述のとおりの記載があります。"},"2":{"t":false,"p":"自己検証の頻度は「少なくとも年1回以上」ではなく、「少なくとも月1回以上」です。","w":"監督指針（経営管理等の着眼点・内部監査）：他に貸金業の業務に従事する者がいない個人の貸金業者などが、内部監査に代わる措置として自己検証を行う場合、十分な時間の確保、別添自己検証リストに基づく項目設定、少なくとも月1回以上の実施、記録の3年間保存などを求めています。"},"3":{"t":true,"w":"監督指針Ⅱ－2－1（法令等遵守（コンプライアンス）態勢等）の冒頭のとおりです。"},"4":{"t":true,"w":"監督指針Ⅱ－2－13－3（「経営者保証に関するガイドライン」の融資慣行としての浸透・定着等）のとおりです。"}}},"18-20":{"s":"貸金業者の禁止行為（第12条の6〜第12条の8・第16条）を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"第12条の6第3号。","r":[["貸金業法","12の6"]]},"2":{"t":false,"p":"借り手の死亡で保険金が支払われる保険契約を結ぶこと自体は禁止されていません。禁止されているのは、その保険契約で「自殺による死亡を保険事故とすること」です。","w":"第12条の7。","r":[["貸金業法","12の7"]]},"3":{"t":true,"w":"第16条第2項第2号。","r":[["貸金業法","16"]]},"4":{"t":true,"w":"第12条の8第10項に、記述のとおりの規定があります（契約の更新時に新たな媒介手数料を受け取ることの禁止）。","r":[["貸金業法","12の8"]]}}},"18-21":{"s":"返済能力の調査で指定信用情報機関の信用情報を使う義務（第13条第2項）があるかどうかを問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"第13条第2項の使用義務は、「個人である顧客等」と契約する場合だけです。法人が相手なら不要です（返済能力の調査そのもの（第1項）は必要です）。","r":[["貸金業法","13"]]},"2":{"t":true,"w":"第13条第5項かっこ書・施行規則第10条の19：連絡が取れないため一時的に減額していた極度額を（返済能力の低下によるものではなく）元に戻す場合は、増額時の調査の対象外です。","r":[["貸金業法","13"],["貸金業法施行規則","10の19"]]},"3":{"t":false,"p":"極度方式貸付けは、金額にかかわらず信用情報の使用義務の対象外です。「5万円超かつ残高10万円超」は、第13条の3第1項（基本契約の途中の調査）の要件で、第13条第2項とは関係ありません。","w":"第13条第2項かっこ書・施行規則第10条の16第1号。","r":[["貸金業法","13"],["貸金業法施行規則","10の16"],["貸金業法施行規則","10の24"]]},"4":{"t":true,"w":"施行規則第10条の16第2号・第1条の2の3第2号：手形（融通手形を除く）の割引を内容とする契約は、信用情報の使用義務の対象外です。","r":[["貸金業法施行規則","10の16"],["貸金業法施行規則","1の2の3"]]}}},"18-22":{"s":"過剰貸付けの禁止（第13条の2）と、年収に含める収入・除外契約・例外契約を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"第13条の2第1項：個人過剰貸付契約（総量規制）だけでなく、「その他顧客等の返済能力を超える貸付けの契約」も禁止されます。法人が相手でも対象です。","r":[["貸金業法","13の2"]]},"2":{"t":true,"w":"施行規則第10条の23第1項第5号：現に事業を営んでいない個人顧客の新たな事業のための貸付けで、事業計画等で確実に事業の用に供する資金と認められ、返済能力を超えないもの。","r":[["貸金業法施行規則","10の23"]]},"3":{"t":false,"p":"年収に含められるのは「総収入金額」ではなく、「事業所得の金額」（過去の状況に照らして安定的と認められるもの）です。","w":"施行規則第10条の22第1項第4号。","r":[["貸金業法施行規則","10の22"]]},"4":{"t":true,"w":"施行規則第10条の21第2項第1号に、記述のとおりの保存義務があります。","r":[["貸金業法施行規則","10の21"]]}}},"18-23":{"s":"総量規制の例外契約（施行規則第10条の23）の要件を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"事業を営む個人顧客への貸付けは、事業実態の確認と、事業計画等に照らし返済能力を超えないことの「両方」（すべて）を満たす必要があります。「いずれか」ではありません。","w":"施行規則第10条の23第1項第4号：次に掲げるすべての要件に該当するもの（イ 事業の実態の確認、ロ 返済能力を超えないこと）。","r":[["貸金業法施行規則","10の23"]]},"2":{"t":true,"w":"施行規則第10条の23第1項第6号：金融機関からの正規貸付けまでのつなぎ融資で、正規貸付けが確実と認められ、返済期間が1か月を超えないもの。","r":[["貸金業法施行規則","10の23"]]},"3":{"t":true,"w":"施行規則第10条の23第1項第2号の2（特定緊急貸付契約）：合算額10万円以下に加えて、返済期間が3か月を超えないことが要件です。返済期間1年では該当しません。","r":[["貸金業法施行規則","10の23"]]},"4":{"t":true,"w":"施行規則第10条の23第1項第1号イ：1か月の負担が既存債務の1か月の負担を上回らないことが要件です。上回るものは該当しません。","r":[["貸金業法施行規則","10の23"]]}}},"18-24":{"s":"貸付条件の広告（第15条）と誇大広告の禁止等（第16条）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"「貸付けに関し貸金業者が受け取る書面の内容」は、広告の表示事項に「含まれません」。","w":"第15条第1項・施行規則第12条第1項第1号：広告の表示事項は、商号等・登録番号・貸付けの利率、返済の方式・返済期間及び返済回数、賠償額の予定の割合、担保に関する事項などです。受け取る書面の内容は、契約締結前の書面などの記載事項です。","r":[["貸金業法","15"],["貸金業法施行規則","12"],["貸金業法施行規則","11"]]},"2":{"t":true,"w":"監督指針Ⅱ－2－15（2）②に、記述のとおりの説明があります。","r":[["貸金業法","15"]]},"3":{"t":true,"w":"第16条第5項。","r":[["貸金業法","16"]]},"4":{"t":true,"w":"第15条第2項・施行規則第12条第4項・第5項。","r":[["貸金業法","15"],["貸金業法施行規則","12"]]}}},"18-25":{"s":"特定公正証書（借り手が「返さなければすぐ強制執行されてよい」と認める公正証書）と、公的給付の預金通帳等の保管の制限（第20条・第20条の2）を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"第20条第1項：債務者等から、特定公正証書の作成を代理人に委任することを証する書面（委任状）を取得してはなりません。","r":[["貸金業法","20"]]},"2":{"t":true,"w":"第20条第2項：代理人の選任に関し推薦その他これに類する関与をしてはなりません。","r":[["貸金業法","20"]]},"3":{"t":false,"p":"書面の交付・説明は、嘱託した後に「遅滞なく」ではなく、嘱託する前に「あらかじめ」行います。","w":"第20条第3項：特定公正証書の作成を公証人に嘱託する場合には、あらかじめ、強制執行に服することとなる旨などについて書面を交付して説明しなければなりません。","r":[["貸金業法","20"]]},"4":{"t":true,"w":"第20条の2第1号。","r":[["貸金業法","20の2"]]}}},"18-26":{"s":"貸金業者に対する監督（事業報告書・報告徴収・登録の取消し）を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"第24条の6の9：毎事業年度経過後3月以内に事業報告書を提出します。","r":[["貸金業法","24の6の9"]]},"2":{"t":true,"w":"第24条の6の10第1項。","r":[["貸金業法","24の6の10"]]},"3":{"t":false,"p":"暴力団員等を業務に従事させた場合は、登録を取り消すことが「できる」のではなく、取り消さ「なければならない」（業務停止を選ぶ余地はない）とされています。","w":"第24条の6の5第1項第5号：第12条の5の規定に違反したときは、登録を取り消さなければなりません。第24条の6の4第1項第2号（業務停止等）からは、第12条の5違反が除かれています。","r":[["貸金業法","24の6の5"],["貸金業法","24の6の4"],["貸金業法","12の5"]]},"4":{"t":true,"w":"第24条の6の6第1項第2号：正当な理由がないのに登録を受けた日から6月以内に貸金業を開始しないときは、登録を取り消すことができます。","r":[["貸金業法","24の6の6"]]}}},"18-27":{"s":"利息制限法の元本額の特則（第5条）の計算問題です。重ねて借りるときは「残元本＋新元本」、同時に借りるときは「元本の合計」で上限利率を判定します。適切でないのは④です。","items":{"1":{"t":true,"w":"第一契約は完済済みなので、第二契約は元本5万円だけで判断します（10万円未満は年2割。第1条第1号）。20%は有効です。","r":[["利息制限法","1"],["利息制限法","5"]]},"2":{"t":true,"w":"第5条第2号：同時に借りた20万円＋80万円＝100万円とみなすので、上限は年15%です。第一契約の18%は15%を超える部分が無効です。","r":[["利息制限法","5"],["利息制限法","1"]]},"3":{"t":true,"w":"第5条第1号：残元本30万円＋80万円＝110万円とみなすので、第二契約の上限は年15%です。","r":[["利息制限法","5"],["利息制限法","1"]]},"4":{"t":false,"p":"第二契約だけでなく、第三契約も無効部分があります。残元本50万円＋5万円＋50万円＝105万円とみなされ、上限は第二・第三契約とも年15%です。","w":"第5条：第二契約（20%）も第三契約（18%）も、15%を超える部分が無効になります。","r":[["利息制限法","5"],["利息制限法","1"]]}}},"18-28":{"s":"意思能力（自分の行為の結果がわかる能力）と行為能力を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"意思能力がない状態でした法律行為は、「取り消すことができる」のではなく「無効」です。","w":"民法第3条の2。","r":[["民法","3の2"]]},"2":{"t":false,"p":"「単に権利を得る」法律行為も、義務を免れる行為と同じく、法定代理人の同意は「不要」です。","w":"民法第5条第1項ただし書：単に権利を得、又は義務を免れる法律行為については、同意を要しません。","r":[["民法","5"]]},"3":{"t":true,"w":"民法第9条：成年被後見人の法律行為は、日常生活に関する行為を除き取り消すことができ、同意を得た場合の例外はありません。","r":[["民法","9"]]},"4":{"t":false,"p":"金銭の借入れ（借財）や元本の領収には、保佐人の同意が「必要」です。","w":"民法第13条第1項第1号・第2号。","r":[["民法","13"]]}}},"18-29":{"s":"無効・取消し・追認を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"無効と知って追認すると、初めから有効になるのではなく、「新たな行為をしたもの」とみなされます。","w":"民法第119条。","r":[["民法","119"]]},"2":{"t":false,"p":"制限行為能力者本人も、同意を得ずに単独で取り消すことが「できます」。","w":"民法第120条第1項：制限行為能力者又はその代理人、承継人若しくは同意をすることができる者が取り消すことができます。","r":[["民法","120"]]},"3":{"t":false,"p":"取り消された行為は、将来に向かってではなく、「初めから無効」であったものとみなされます。","w":"民法第121条。","r":[["民法","121"]]},"4":{"t":true,"w":"民法第124条第1項。","r":[["民法","124"]]}}},"18-30":{"s":"時効の期間・放棄・効力が及ぶ範囲を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"債権の消滅時効は「知った時から10年・行使できる時から20年」ではなく、「知った時から5年・行使できる時から10年」です。20年は債権・所有権以外の財産権です。","w":"民法第166条第1項・第2項。","r":[["民法","166"]]},"2":{"t":false,"p":"時効の利益は、あらかじめ（時効完成前に）放棄することが「できません」。放棄しても無効なので、援用できます。","w":"民法第146条。","r":[["民法","146"]]},"3":{"t":false,"p":"完成猶予・更新の効力が及ぶのは、「当事者及びその承継人の間」だけです。利害関係が生じるすべての者には及びません。","w":"民法第153条。","r":[["民法","153"]]},"4":{"t":true,"w":"民法第169条第1項・第2項。","r":[["民法","169"]]}}},"18-31":{"s":"債権の目的と効力（善管注意義務・損害賠償の範囲・金銭債務の特則）を問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"民法第400条。","r":[["民法","400"]]},"2":{"t":false,"p":"特別の事情による損害も、当事者がその事情を予見すべきであったときは、賠償の対象に「なります」。","w":"民法第416条第2項。","r":[["民法","416"]]},"3":{"t":false,"p":"金銭債務の不履行は、不可抗力によるものでも、損害賠償を請求「できます」（不可抗力を抗弁にできません）。","w":"民法第419条第3項。","r":[["民法","419"]]},"4":{"t":false,"p":"金銭債務の不履行による損害賠償は、損害を証明しなくても請求「できます」。","w":"民法第419条第2項。","r":[["民法","419"]]}}},"18-32":{"s":"債権譲渡（譲渡制限特約・対抗要件・二重譲渡）を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"譲渡を禁止する特約があっても、債権の譲渡は「有効」で、Ｃは債権を取得します（特約を知っていた又は重大な過失で知らなかった譲受人には、債務者は履行を拒めます）。","w":"民法第466条第2項・第3項。","r":[["民法","466"]]},"2":{"t":false,"p":"債務者Ｂに対抗するには、確定日付のない通知で「足ります」。確定日付が必要なのは、債務者以外の第三者に対抗する場合です。","w":"民法第467条第1項・第2項。","r":[["民法","467"]]},"3":{"t":true,"w":"民法第467条第2項：債務者以外の第三者（二重譲受人Ｄ）に対抗するには、確定日付のある証書による通知又は承諾が必要です。Ｃへの承諾には確定日付がなく、Ｄへの通知には確定日付があるので、Ｄが優先し、ＢはＣの請求を拒めます。","r":[["民法","467"]]},"4":{"t":false,"p":"二重譲渡の優劣は、確定日付の日付の先後ではなく、確定日付のある通知が債務者に「到達した日時の先後」で決まります。先に到達したＤが優先するので、ＢはＣの請求を拒めます。","w":"到達の先後で決まることは判例の考え方です（条文には直接書かれていません）。","r":[["民法","467"]]}}},"18-33":{"s":"相殺（互いの債権を対当額で消し合うこと）の要件と、差押えとの関係を問う問題です。Ａから見ると、甲債権が自働債権（相殺に使う債権）、乙債権が受働債権（相殺される債権）です。正しいのは②です。","items":{"1":{"t":false,"p":"甲債権が差し押さえられると、Ａは甲債権の取立てその他の処分を禁止されるので、甲債権を使って相殺することは「できません」。","w":"民事執行法第145条第1項：差押命令において、債務者（Ａ）に対し債権の取立てその他の処分を禁止します。","r":[["民事執行法","145"]]},"2":{"t":true,"w":"民法第505条第1項：相殺するには双方の債務が弁済期にあることが必要です。Ａが相殺に使う甲債権の弁済期が来ていないので、Ａからは相殺できません（受働債権の乙債権は、Ａが期限の利益を放棄すれば足ります）。","r":[["民法","505"]]},"3":{"t":false,"p":"差押え前に取得した債権による相殺は、差押債権者Ｄに対抗「できます」。","w":"民法第511条第1項。","r":[["民法","511"]]},"4":{"t":false,"p":"時効で消滅する前に相殺適状（相殺できる状態）になっていれば、時効消滅後も相殺「できます」。","w":"民法第508条。","r":[["民法","508"]]}}},"18-34":{"s":"金銭消費貸借契約の解除・利息・期限の利益・重利（利息の元本組入れ）を問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"民法第587条の2第2項：書面でする消費貸借の借主は、貸主から金銭を受け取るまで、契約の解除をすることができます。","r":[["民法","587の2"]]},"2":{"t":false,"p":"利息の特約がなければ、貸主は利息を請求「できません」。","w":"民法第589条第1項。","r":[["民法","589"]]},"3":{"t":false,"p":"1回の遅滞で残債務全部を一括請求できるのは、そのような約定（期限の利益喪失特約）がある場合です。本問にはなく、民法上も1回の遅滞は期限の利益の喪失事由ではありません。","w":"民法第137条の期限の利益の喪失事由は、破産手続開始・担保の滅失等・担保を供しないことです。","r":[["民法","137"]]},"4":{"t":false,"p":"利息を1年分以上延滞し、催告しても支払わないときは、元本に組み入れることが「できます」。","w":"民法第405条。","r":[["民法","405"]]}}},"18-35":{"s":"犯罪収益移転防止法の取引時確認（確認事項・本人確認書類）を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"確認事項は、本人特定事項（氏名・住居・生年月日）、取引を行う目的、職業です。「収入」は通常の取引時確認の確認事項に「含まれません」。","w":"犯罪収益移転防止法第4条第1項第1号〜第3号。","r":[["犯罪収益移転防止法","4"]]},"2":{"t":true,"w":"犯罪収益移転防止法施行規則第7条：運転免許証（第1号イ）は提示を受ける日において有効なもの、住民票の写し（第1号ニ）は提示を受ける日前6月以内に作成されたものに限られます。","r":[["犯罪収益移転防止法施行規則","7"]]},"3":{"t":false,"p":"本人確認書類の「提示」を受ける方法では、写しではなく原本の提示を受けます。","w":"犯罪収益移転防止法施行規則第6条第1項第1号イ（本人確認書類の提示を受ける方法）。写しの提示が認められないことの結論は公式正答によります。","r":[["犯罪収益移転防止法施行規則","6"]]},"4":{"t":false,"p":"過去の取引で取引時確認を行い、確認記録を保存している顧客であれば、契約の都度確認する必要は「ありません」。","w":"犯罪収益移転防止法第4条第3項：他の取引の際に既に確認を行っている顧客等については、第1項の規定は適用しません。","r":[["犯罪収益移転防止法","4"]]}}},"18-36":{"s":"意思表示（虚偽表示・錯誤・詐欺・強迫）と第三者の保護を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"民法第94条第2項：虚偽表示の無効は、善意の第三者に対抗することができません。","r":[["民法","94"]]},"2":{"t":true,"w":"民法第95条第1項第2号・第2項：法律行為の基礎とした事情についての錯誤（動機の錯誤）は、その事情が基礎とされていることが表示されていたときに限り、取り消すことができます。","r":[["民法","95"]]},"3":{"t":true,"w":"民法第96条第3項：詐欺による取消しは、善意でかつ過失がない第三者に対抗することができません。","r":[["民法","96"]]},"4":{"t":false,"p":"強迫による取消しは、善意無過失の第三者にも対抗「できます」。第三者保護の規定（第96条第3項）は詐欺だけが対象です。","w":"民法第96条第3項は「詐欺による意思表示の取消し」に限っています。","r":[["民法","96"]]}}},"18-37":{"s":"期間の計算（民法第139条〜第143条）を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"民法第139条：時間で定めた期間は即時から起算します。10時30分から6時間で16時30分に満了します。","r":[["民法","139"]]},"2":{"t":true,"w":"民法第140条：日・週・月・年で定めた期間は、初日を算入しません（初日不算入）。10月2日から起算して2週間で、10月15日に満了します。","r":[["民法","140"],["民法","143"]]},"3":{"t":false,"p":"末日が休日に当たり、その日に取引をしない慣習がある場合は、「前日」ではなく「翌日」に満了します。","w":"民法第142条。","r":[["民法","142"]]},"4":{"t":true,"w":"民法第140条ただし書：午前0時から始まるときは初日を算入します。民法第143条第2項ただし書：最後の月に応当する日がないときは、その月の末日に満了します。","r":[["民法","140"],["民法","143"]]}}},"18-38":{"s":"債権質と根抵当権を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"民法第364条：債権質の設定は、第467条に従い、第三債務者への通知又は第三債務者の承諾がなければ、第三債務者に対抗できません。","r":[["民法","364"],["民法","467"]]},"2":{"t":false,"p":"質権の目的が金銭債権のときは、「全部」ではなく、自己の債権額（貸金債権の額）に対応する部分に限り取り立てることができます。","w":"民法第366条第1項・第2項。","r":[["民法","366"]]},"3":{"t":true,"w":"民法第398条の3第1項。根抵当権には、普通抵当権のような「最後の2年分」の制限（第375条）はなく、極度額が上限です。","r":[["民法","398の3"],["民法","375"]]},"4":{"t":true,"w":"民法第398条の4第1項・第2項（変更は元本確定前に登記が必要。同条第3項）。","r":[["民法","398の4"]]}}},"18-39":{"s":"保証債務の範囲と性質を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"保証人は、その保証債務についてだけ違約金や損害賠償の額を約定することが「できます」。","w":"民法第447条第2項。保証人の負担が主たる債務より重いときに減縮する定め（第448条第1項）は、これとは別のルールです。","r":[["民法","447"],["民法","448"]]},"2":{"t":true,"w":"民法第454条。","r":[["民法","454"]]},"3":{"t":true,"w":"民法第449条。","r":[["民法","449"]]},"4":{"t":true,"w":"民法第450条第1項・第3項（債権者が保証人を指名した場合は、同条第1項・第2項は適用されません）。","r":[["民法","450"]]}}},"18-40":{"s":"相続人と相続分、単純承認、相続放棄を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"民法第900条第1号・第4号：配偶者と子が相続人のときは各2分の1。子が2人なので、ＣとＤは2分の1を等分して各4分の1です。","r":[["民法","900"]]},"2":{"t":true,"w":"民法第902条の2：相続分の指定がされた場合でも、被相続人の債権者は、各共同相続人に法定相続分に応じて権利を行使できます。","r":[["民法","902の2"]]},"3":{"t":true,"w":"民法第921条第1号：相続人が相続財産の全部又は一部を処分したときは、単純承認をしたものとみなします。","r":[["民法","921"]]},"4":{"t":false,"p":"相続放棄をしたＤの子Ｅは、代襲相続人に「なりません」。共同相続人はＢとＣだけです。","w":"民法第939条：放棄をした者は初めから相続人とならなかったものとみなされます。民法第887条第2項：代襲相続の原因は死亡・欠格・廃除で、放棄は含まれません。","r":[["民法","939"],["民法","887"]]}}},"18-41":{"s":"手形の抗弁・裏書の連続と、電子記録債権の発生・支払免責を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"詐欺による取消しは「人的抗弁」で、事情を知らずに手形を取得した所持人には対抗「できません」。","w":"手形法第17条（約束手形には第77条第1項第1号で準用）：振出人その他所持人の前者に対する人的関係に基づく抗弁をもって所持人に対抗できません。ただし、所持人が債務者を害することを知って取得したときは別です。詐欺取消しが人的抗弁に当たることは、判例の考え方です（条文には直接書かれていません）。","r":[["手形法","17"],["手形法","77"]]},"2":{"t":true,"w":"手形法第16条第1項（第77条第1項第1号で準用）：裏書の連続によって権利を証明するときは、適法の所持人とみなします。","r":[["手形法","16"],["手形法","77"]]},"3":{"t":true,"w":"電子記録債権法第15条。","r":[["電子記録債権法","15"]]},"4":{"t":true,"w":"電子記録債権法第21条：支払をした者に悪意又は重大な過失があるときを除き、効力を有します。","r":[["電子記録債権法","21"]]}}},"18-42":{"s":"民事訴訟法（管轄の合意・訴えの提起・訴訟代理人・陳述の擬制）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"民事訴訟法第11条第1項・第13条第1項（専属管轄の定めがある場合は適用しない）。合意は書面でする必要があります（第11条第2項）。","r":[["民事訴訟法","11"],["民事訴訟法","13"]]},"2":{"t":true,"w":"民事訴訟法第134条第1項（訴状の提出）・第271条（簡易裁判所では口頭で提起できる）。","r":[["民事訴訟法","134"],["民事訴訟法","271"]]},"3":{"t":true,"w":"民事訴訟法第54条第1項：「法令により裁判上の行為をすることができる代理人」は、弁護士でなくても訴訟代理人になれます。会社法第11条第1項で、支配人は会社に代わってその事業に関する一切の裁判上又は裁判外の行為をする権限を有します。","r":[["民事訴訟法","54"],["会社法","11"]]},"4":{"t":false,"p":"準備書面の陳述の擬制が認められるのは、地方裁判所では「最初の口頭弁論の期日」だけです。「続行の期日」にも認められるのは簡易裁判所です。","w":"民事訴訟法第158条（最初の期日）・第277条（簡易裁判所の特則で続行期日に準用）。","r":[["民事訴訟法","158"],["民事訴訟法","277"]]}}},"18-43":{"s":"個人情報保護法の定義（個人情報・個人識別符号・個人データ・個人関連情報）を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"取得後に他の情報と照合するなどして特定の個人を識別できるようになれば、その時点で個人情報に「該当します」。","w":"個人情報保護法第2条第1項第1号：特定の個人を識別することができるもの（他の情報と容易に照合でき、それにより識別できるものを含む）が個人情報です。取得時点で判断が固定されるとは定められていません（結論は公式正答によります）。","r":[["個人情報保護法","2"]]},"2":{"t":false,"p":"個人データは、個人情報データベース等を構成する個人情報に「限られます」。","w":"個人情報保護法第16条第3項：「個人データ」とは、個人情報データベース等を構成する個人情報をいいます。","r":[["個人情報保護法","16"]]},"3":{"t":true,"w":"個人情報保護法第2条第2項第1号（個人識別符号）・同条第1項第2号（個人識別符号が含まれるものは個人情報）。","r":[["個人情報保護法","2"]]},"4":{"t":false,"p":"個人関連情報は、個人情報・仮名加工情報・匿名加工情報の「いずれにも該当しない」ものです。","w":"個人情報保護法第2条第7項。","r":[["個人情報保護法","2"]]}}},"18-44":{"s":"消費者契約法の差止請求・取消し・不当条項・取消権の期間を問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"消費者契約法第12条第1項・第2項：適格消費者団体は、不特定かつ多数の消費者に対して不実告知などの不当な勧誘を現に行い又は行うおそれがある事業者に、その停止・予防などを請求できます。","r":[["消費者契約法","12"]]},"2":{"t":false,"p":"退去しない（不退去）ことで困惑して契約した場合、契約は「無効」ではなく、消費者が「取り消す」ことができます。","w":"消費者契約法第4条第3項。","r":[["消費者契約法","4"]]},"3":{"t":false,"p":"消費者の利益を一方的に害する条項は、契約を「取り消せる」のではなく、その条項が「無効」になります。","w":"消費者契約法第10条。","r":[["消費者契約法","10"]]},"4":{"t":false,"p":"取消権の期間は「追認できる時から6か月」ではなく「1年間」です（契約締結の時から5年）。","w":"消費者契約法第7条第1項。","r":[["消費者契約法","7"]]}}},"18-45":{"s":"本人の開示・訂正・利用停止等の請求（個人情報保護法第33条〜第35条）を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"個人情報保護法第33条第1項：本人は、電磁的記録の提供による方法その他の方法による開示を請求できます。","r":[["個人情報保護法","33"]]},"2":{"t":true,"w":"個人情報保護法第34条第1項。","r":[["個人情報保護法","34"]]},"3":{"t":false,"p":"利用停止等を請求できるのは、違法な取扱い・取得の場合に「限られません」。利用する必要がなくなった場合や、漏えい等の報告対象事態が生じた場合なども請求できます。","w":"個人情報保護法第35条第1項（第18条・第19条違反の取扱い、第20条違反の取得）に加え、同条第5項（利用する必要がなくなった場合、報告対象事態が生じた場合、本人の権利又は正当な利益が害されるおそれがある場合）。","r":[["個人情報保護法","35"]]},"4":{"t":true,"w":"個人情報保護法第35条第7項。","r":[["個人情報保護法","35"]]}}},"18-46":{"s":"景品表示法（不当な景品や表示を規制する法律）の定義と手続を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"資料を提出しないと不当表示とみなされる仕組み（不実証広告規制）は、有利誤認表示（第5条第2号）ではなく、「優良誤認表示」（第5条第1号。品質などを実際より著しく優良と誤認させる表示）が対象です。","w":"景品表示法第7条第2項：第5条第1号に該当するか否かを判断するため必要があるときに、表示の裏付けとなる合理的な根拠を示す資料の提出を求めることができます。","r":[["景品表示法","7"],["景品表示法","5"]]},"2":{"t":true,"w":"景品表示法第6条第1項。","r":[["景品表示法","6"]]},"3":{"t":true,"w":"景品表示法第2条第4項。","r":[["景品表示法","2"]]},"4":{"t":true,"w":"景品表示法第2条第3項。","r":[["景品表示法","2"]]}}},"18-47":{"s":"日本貸金業協会の紛争解決等業務に関する規則を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"紛争解決等業務に関する規則（定義）第2号のとおりです。"},"2":{"t":false,"p":"紛争解決手続の申立ては、契約者等だけでなく、加入貸金業者からも「できます」。","w":"紛争解決等業務に関する規則第59条第1項：契約者等若しくは加入貸金業者である個人、法人又は権利能力なき社団等であって貸金業務関連紛争の当事者である者が申立てをすることができます。"},"3":{"t":true,"w":"紛争解決等業務に関する規則第89条第2項。"},"4":{"t":true,"w":"紛争解決等業務に関する規則第90条第3項。"}}},"18-48":{"s":"企業会計原則の一般原則（7つ）を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"単一性の原則は、目的に応じて異なる形式の財務諸表を作ることを禁じるのではなく、形式は異なってもよいが、内容は信頼しうる会計記録に基づき、事実の真実な表示をゆがめてはならない、という原則です。","w":"企業会計原則・一般原則七。"},"2":{"t":false,"p":"一般原則にあるのは「資本取引・損益取引区分の原則」で、資本取引と損益取引を区別し、資本剰余金と利益剰余金を混同してはならないというものです。「総資本区分の原則」はありません。","w":"企業会計原則・一般原則三。"},"3":{"t":true,"w":"企業会計原則・一般原則五（継続性の原則）。"},"4":{"t":false,"p":"「正確性の原則」という一般原則は「ありません」。会計事実を明瞭に表示するよう求めるのは「明瞭性の原則」です。","w":"企業会計原則・一般原則四：財務諸表によって、利害関係者に対し必要な会計事実を明瞭に表示し、企業の状況に関する判断を誤らせないようにしなければなりません。"}}},"18-49":{"s":"損益計算書の段階利益の名前と計算順を問う問題です。財務諸表等規則は取り込んでいないため、同じ考え方を定めた企業会計原則の損益計算書原則で確認します。正しいのは④です。","items":{"1":{"t":false,"p":"売上高−売上原価は、「営業利益」ではなく「売上総利益」です。","w":"企業会計原則・損益計算書原則：売上総利益は、売上高から売上原価を控除して表示します。"},"2":{"t":false,"p":"売上総利益−販売費及び一般管理費は、「経常利益」ではなく「営業利益」です。","w":"企業会計原則・損益計算書原則三：売上総利益から販売費及び一般管理費を控除して、営業利益を表示します。"},"3":{"t":false,"p":"営業利益に営業外収益を加え営業外費用を引いたものは、「営業外利益」ではなく「経常利益」です。","w":"企業会計原則・損益計算書原則五。"},"4":{"t":true,"w":"企業会計原則・損益計算書原則七：税引前当期純利益は、経常利益に特別利益を加え、これから特別損失を控除して表示します。"}}},"18-50":{"s":"キャッシュ・フロー計算書の区分を問う問題です。財務諸表等規則とキャッシュ・フロー計算書の基準は取り込んだ資料にないため、結論は公式正答によります。適切でないのは②です。","items":{"1":{"t":true,"w":"結論は公式正答によります。"},"2":{"t":false,"p":"社債の発行・償還や株式の発行は、投資活動ではなく「財務活動」の区分です。","w":"結論は公式正答によります（取り込んだ資料では確認できません）。"},"3":{"t":true,"w":"結論は公式正答によります。"},"4":{"t":true,"w":"結論は公式正答によります。"}}},"19-01":{"s":"貸金業法第2条の用語の定義を問う問題です。適切なのはｂだけです（1個）。","items":{"a":{"t":false,"p":"事業者がその従業者に対して行う貸付けは、貸金業に「含まれる」のではなく、貸金業から「除かれます」。","w":"第2条第1項第4号。会社が社員に貸す（従業員貸付け）のは、業として行っても貸金業には当たりません。","r":[["貸金業法","2"]]},"b":{"t":true,"w":"第2条第3項：「貸付けの契約」とは、貸付けに係る契約又は当該契約に係る保証契約をいいます。","r":[["貸金業法","2"]]},"c":{"t":false,"p":"「債務者等」は「顧客、債務者又は債務者であった者」ではなく、「債務者又は保証人」です。","w":"第2条第5項。似た用語の「顧客等」は「資金需要者である顧客又は保証人となろうとする者」（同条第4項）、両方を合わせたものが「資金需要者等」（同条第6項）です。","r":[["貸金業法","2"]]},"d":{"t":false,"p":"記述は「個人信用情報」ではなく「信用情報」の定義です。","w":"第2条第13項：「信用情報」＝顧客又は債務者の借入金の返済能力に関する情報。第2条第14項：「個人信用情報」＝個人を相手方とする貸付けに係る契約（極度方式基本契約などを除く）に係る第41条の35第1項各号の事項（氏名・住所、契約年月日、貸付けの金額など）です。","r":[["貸金業法","2"],["貸金業法","41の35"]]}}},"19-02":{"s":"登録を拒否される場合（第6条第1項）のうち、「体制が整っていない」（第15号）の具体的な基準（施行規則第5条の7）と、純資産額（第14号）を問う問題です。拒否されるのはａとｃです。","items":{"a":{"t":true,"w":"施行規則第5条の7第1項第2号：個人の申請者は、本人が貸付けの業務に3年以上従事した経験を有することが必要です。これを満たさないと、第6条第1項第15号（貸金業を的確に遂行するための必要な体制が整備されていると認められない者）として拒否されます。","r":[["貸金業法","6"],["貸金業法施行規則","5の7"]]},"b":{"t":false,"p":"求められるのは「1人以上」の在籍です。1人在籍していれば基準を満たすので、拒否の理由になりません。","w":"施行規則第5条の7第1項第3号：営業所等ごとに、貸付けの業務に1年以上従事した者が常勤の役員又は使用人として1人以上在籍していること。","r":[["貸金業法施行規則","5の7"]]},"c":{"t":true,"w":"施行規則第5条の7第1項第4号：資金需要者等の利益の保護を図り、貸金業の適正な運営に資するため十分な社内規則（会社の中のルール）を定めていることが基準です。定めていなければ第6条第1項第15号により拒否されます。","r":[["貸金業法","6"],["貸金業法施行規則","5の7"]]},"d":{"t":false,"p":"最低純資産額は1億円ではなく5,000万円です。1億円あれば基準を満たすので、拒否の理由になりません。","w":"第6条第1項第14号・施行令第3条の2：純資産額が5,000万円に満たない者は登録を拒否されます。","r":[["貸金業法","6"],["貸金業法施行令","3の2"]]}}},"19-03":{"s":"変更の届出（第8条）は、「あらかじめ」届け出る事項と「変更から2週間以内」に届け出る事項の区別が問われます。営業所の名称・所在地（第4条第1項第5号）と広告等に表示する連絡先（第7号）は「あらかじめ」、それ以外は「2週間以内」です。適切なのはａとｄです。","items":{"a":{"t":true,"w":"第8条第1項：営業所又は事務所の所在地（第4条第1項第5号）を変更しようとするときは、あらかじめ届け出ます。","r":[["貸金業法","8"],["貸金業法","4"]]},"b":{"t":false,"p":"広告・勧誘で表示するホームページアドレスは、変更から「2週間以内」ではなく、変更しようとするとき「あらかじめ」届け出ます。","w":"第4条第1項第7号の「連絡先等」に、施行規則第3条の2でホームページアドレスが含まれています。第7号の事項は第8条第1項で「あらかじめ」届け出る事項です。","r":[["貸金業法","8"],["貸金業法","4"],["貸金業法施行規則","3の2"]]},"c":{"t":false,"p":"業務の種類及び方法の変更は、「あらかじめ」ではなく、変更があった日から「2週間以内」に届け出ます。","w":"業務の種類及び方法は第4条第1項第8号の事項で、第5号・第7号以外なので、第8条第1項により事後（2週間以内）の届出です。","r":[["貸金業法","8"],["貸金業法","4"]]},"d":{"t":true,"w":"他に行っている事業の種類（第4条第1項第9号）は、変更があった日から2週間以内に届け出ます（第8条第1項）。","r":[["貸金業法","8"],["貸金業法","4"]]}}},"19-04":{"s":"業務の適切な運営のための措置（施行規則）と監督指針の着眼点を問う問題です。4つとも適切です（4個）。","items":{"a":{"t":true,"w":"施行規則第10条の3：信用情報に関する機関から提供を受けた個人の返済能力に関する情報を、返済能力の調査以外の目的に使わないことを確保するための措置を講じなければなりません。","r":[["貸金業法施行規則","10の3"]]},"b":{"t":true,"w":"施行規則第10条の5第1項第2号：業務を第三者に委託する場合、受託者（委託先）の業務の実施状況を定期的に又は必要に応じて確認するなどして、必要かつ適切な監督等を行うための措置を講じなければなりません。","r":[["貸金業法施行規則","10の5"]]},"c":{"t":true,"w":"監督指針Ⅱ－2－1（法令等遵守（コンプライアンス）態勢等）の着眼点に、記述のとおり「業績評価や人事考課等において収益目標（ノルマ）に偏重することなく、コンプライアンスを重視しているか」があります。"},"d":{"t":true,"w":"監督指針Ⅱ－2－2（顧客等に関する情報管理態勢）の着眼点に、内部管理部門における定期的な点検や内部監査を通じて実施状況を把握・検証し、態勢の見直しを行うなど、情報管理の実効性が確保されているか、があります。"}}},"19-05":{"s":"監督指針Ⅱ－2－7（苦情等への対処）の着眼点を問う問題です。適切でないのはｃだけです（3個）。","items":{"a":{"t":true,"w":"監督指針Ⅱ－2－7－1：資金需要者等の利便に配慮したアクセス時間・アクセス手段（電話、手紙、FAX、eメール等）を設定する等、広く苦情等を受け付ける態勢を整備しているか。"},"b":{"t":true,"w":"監督指針Ⅱ－2－7－1：苦情等への対処を単に処理の手続の問題と捉えるにとどまらず、事後的な説明態勢の問題として位置付け、可能な限り資金需要者等の理解と納得を得て解決することを目指しているか。"},"c":{"t":false,"p":"軽微な案件まで「すべて、直ちに」報告するのではなく、「重要案件と認められた場合」に「速やかに」内部監査部門や経営陣に報告します。","w":"監督指針Ⅱ－2－7－1：類型化した苦情等及びその対処結果等が内部管理部門や営業所等に報告されると共に、重要案件と認められた場合、速やかに内部監査部門や経営陣に報告されるなど、事案に応じ必要な関係者間で情報共有が図られる態勢を整備しているか。"},"d":{"t":true,"w":"監督指針Ⅱ－2－7－1：外部機関が介在して対処したものを含めて記録・保存し、指定ADR機関（裁判以外で紛争を解決する機関）から提供された情報等も活用して分析し、再発防止策・未然防止策に活用する態勢を整備しているか。"}}},"19-06":{"s":"貸金業務取扱主任者（以下「主任者」）の設置と従業者名簿のルールです。正しいのは④（名簿は最終の記載から10年間保存）です。","items":{"1":{"t":false,"p":"営業時間内に営業所等に常時駐在する必要は「ある」のではなく「ない」とされています。","w":"監督指針Ⅱ－2－9（2）①：施行規則第10条の7第1号の「常時勤務する者」とは、営業時間内に常時駐在する必要はないが、所属する営業所等が1つに決まっているだけでは足りず、社会通念に照らし常時勤務していると認められるだけの実態を必要とします。","r":[["貸金業法施行規則","10の7"]]},"2":{"t":false,"p":"必要な主任者は「2人以上」ではなく「1人以上」です。貸金業の業務に従事する50人に対して50分の1以上なので、1人で足ります。","w":"施行規則第10条の8：主任者の数は、営業所等において貸金業の業務に従事する者の数の50分の1以上。数えるのは従業者全体（80人）ではなく、貸金業の業務に従事する者（50人）です。","r":[["貸金業法","12の3"],["貸金業法施行規則","10の8"]]},"3":{"t":false,"p":"監督指針が原則として記載対象外とするのは、「広告のみ・非対面の業務」ではなく、「人事、総務、経理、システム管理等、通常、資金需要者等に影響が及ばない業務」に従事する者です。","w":"監督指針Ⅱ－2－9（2）②：勧誘や契約の締結を含む営業、審査、債権の管理・回収及びこれらに付随する事務に従事する者は、雇用関係・雇用形態を問わず記載対象に該当すると考えられます。"},"4":{"t":true,"w":"第12条の4第2項：営業所等ごとに従業者名簿を備え、氏名・住所・証明書の番号などを記載して保存します。施行規則第10条の9の2第3項：最終の記載をした日から10年間保存します。","r":[["貸金業法","12の4"],["貸金業法施行規則","10の9の2"]]}}},"19-07":{"s":"違反したとき刑事罰（拘禁刑・罰金）まであるかどうかを問う問題です。禁止行為（第12条の6）のうち刑事罰があるのは第1号の「虚偽のことを告げる」だけです。適切なのはａとｂです。","items":{"a":{"t":true,"w":"保証人に「主たる債務者が確実に弁済する」と誤解させるおそれのあることを告げる行為は、第12条の6第3号の禁止行為です。罰則（第48条第1項第1号の2）は第12条の6第1号の虚偽告知に限られるので刑事罰はありませんが、法令違反として業務停止などの行政処分（第24条の6の4第1項第2号）の対象になります。","r":[["貸金業法","12の6"],["貸金業法","48"],["貸金業法","24の6の4"]]},"b":{"t":true,"w":"暴力団員等（暴力団員でなくなった日から5年を経過しない者を含む。第6条第1項第6号）を業務に従事させることは第12条の5で禁止されています。違反すると登録の取消し（第24条の6の5第1項第5号）の対象となり、刑事罰（第48条第1項第1号：1年以下の拘禁刑若しくは300万円以下の罰金又は併科）もあります。","r":[["貸金業法","12の5"],["貸金業法","24の6の5"],["貸金業法","48"]]},"c":{"t":false,"p":"断定的判断の提供（第12条の6第2号）は、行政処分の対象ですが、刑事罰の対象では「ありません」。","w":"第48条第1項第1号の2で刑事罰があるのは、第12条の6のうち第1号（虚偽のことを告げた者）だけです。","r":[["貸金業法","12の6"],["貸金業法","48"]]},"d":{"t":false,"p":"証明書を携帯させずに業務に従事させると、行政処分だけでなく刑事罰（100万円以下の罰金）の対象にも「なります」。","w":"第12条の4第1項違反は第49条第3号で100万円以下の罰金です。","r":[["貸金業法","12の4"],["貸金業法","49"]]}}},"19-08":{"s":"返済能力の調査（第13条）で、指定信用情報機関の信用情報を使う義務がある場面を問う問題です。義務は「個人である顧客等」（保証人になろうとする個人を含む）が相手のときで、極度方式貸付け（カードの枠内での個々の借入れ）は除かれます。正しいのは④です。","items":{"1":{"t":false,"p":"個人事業者も「個人」なので、信用情報を使用して調査する必要が「あります」。","w":"第13条第2項：個人である顧客等と貸付けの契約を締結しようとする場合には、指定信用情報機関が保有する信用情報を使用しなければなりません。事業者かどうかは関係ありません。","r":[["貸金業法","13"]]},"2":{"t":false,"p":"法人の代表者Ｃは個人の保証人となろうとする者なので、Ｃについて信用情報を使用して調査する必要が「あります」。","w":"「顧客等」には保証人となろうとする者が含まれ（第2条第4項）、「貸付けの契約」には保証契約が含まれます（同条第3項）。第13条第2項の対象になります。","r":[["貸金業法","13"],["貸金業法","2"]]},"3":{"t":false,"p":"返済能力の低下を理由に減額した極度額を元に戻すのは、例外に当たらないので、信用情報を使用して調査する必要が「あります」。","w":"第13条第5項：極度額を増額する場合も第13条第1項〜第4項を準用します。例外（施行規則第10条の19）は、相手方と連絡が取れないため一時的に減額していた場合（返済能力の低下による場合を除く）に、連絡が取れて元の額まで戻すときだけです。","r":[["貸金業法","13"],["貸金業法施行規則","10の19"]]},"4":{"t":true,"w":"第13条第2項かっこ書・施行規則第10条の16第1号：極度方式貸付けに係る契約は、信用情報の使用義務の対象から除かれています（基本契約を結ぶとき・極度額を増やすときに調査します）。","r":[["貸金業法","13"],["貸金業法施行規則","10の16"]]}}},"19-09":{"s":"総量規制（年収の3分の1を超える貸付けの禁止）の対象から外れる「除外契約」（施行規則第10条の21）を問う問題です。適切なのはｂとｄです。","items":{"a":{"t":false,"p":"つなぎ融資は、自らの貸付けまでのつなぎだけでなく、「他の者」による住宅改良資金などの貸付けまでのつなぎも除外契約に「該当します」。","w":"施行規則第10条の21第1項第2号：「自ら又は他の者により」第1号の契約（不動産の建設・購入・改良に必要な資金の貸付け）に係る貸付けが行われるまでのつなぎとして行う貸付け。","r":[["貸金業法施行規則","10の21"]]},"b":{"t":true,"w":"施行規則第10条の21第1項第5号：一定の有価証券を担保とする貸付けで、貸付けの金額が契約締結時の有価証券の時価の範囲内であるものは除外契約です。対象となる有価証券の範囲は金融商品取引法などで定められており、取り込んだ資料では個別に確認できないため、記述の有価証券が該当することは公式正答によります。","r":[["貸金業法施行規則","10の21"]]},"c":{"t":false,"p":"担保の不動産を提供するのが個人顧客本人でなくても（第三者の不動産でも）、除外契約に「該当します」。","w":"施行規則第10条の21第1項第6号は、「個人顧客若しくは担保を提供する者」の居宅などを除いた不動産を担保とし、個人顧客の返済能力を超えないと認められ、貸付金額が不動産の価格の範囲内の貸付けを除外契約としています。担保提供者が本人に限られていません。","r":[["貸金業法施行規則","10の21"]]},"d":{"t":true,"w":"施行規則第10条の21第1項第7号のとおりです。","r":[["貸金業法施行規則","10の21"]]}}},"19-10":{"s":"極度方式基本契約（カードローンなど、枠の中で何度も借りられる契約）について、総量規制を超えていないかを途中で確かめる調査（第13条の3）の要件を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"1か月の貸付けの合計額が5万円を超えるだけでなく、「かつ」期間の末日の残高の合計額が10万円を超えることも必要です。残高の多寡に「かかわらず」ではありません。","w":"施行規則第10条の24第1項第1号：所定の期間内の極度方式貸付けの合計額が5万円を超え、かつ、その期間の末日の残高の合計額が10万円を超えるとき、調査が必要です。","r":[["貸金業法","13の3"],["貸金業法施行規則","10の24"]]},"2":{"t":true,"w":"施行規則第10条の24第2項：同条第1項第1号の基準を満たした場合は、その期間の末日から3週間を経過する日までに、指定信用情報機関に個人信用情報の提供を依頼しなければなりません。","r":[["貸金業法施行規則","10の24"]]},"3":{"t":false,"p":"極度額を「減額」する措置を講じただけでは、3か月ごとの調査は免除されません。免除されるのは、新たな極度方式貸付けを「停止」する措置を講じている場合などです。","w":"第13条の3第2項・施行規則第10条の25第1項：3か月以内の期間ごとに調査が必要です。免除（同条第3項）は、残高10万円以下の場合、第10条の29第2号（新たな貸付けの停止）の措置が講じられている場合などで、第10条の29第1号（極度額の減額）は挙げられていません。","r":[["貸金業法","13の3"],["貸金業法施行規則","10の25"],["貸金業法施行規則","10の29"]]},"4":{"t":false,"p":"停止の措置を「解除したときから1か月以内」ではなく、措置を「解除しようとする」ときに（解除する前に）調査します。","w":"施行規則第10条の24第1項第2号：第10条の29第2号の措置（新たな極度方式貸付けの停止）などを解除しようとする場合は、第13条の3第1項の調査の要件に該当します。","r":[["貸金業法","13の3"],["貸金業法施行規則","10の24"]]}}},"19-11":{"s":"極度方式基本契約（カードローンなどの枠の契約）と、その枠内での個々の借入れ（個別契約）について交付する、契約締結時の書面（第17条）のルールです。正しいのは①です。","items":{"1":{"t":true,"w":"施行規則第13条第3項第1号ヨ：基本契約の書面には、極度額（下回る額を提示する場合はその額）を1回貸し付けることなどの必要な仮定を置き、その仮定に基づく将来支払う返済金額の合計額、返済期間及び返済回数並びに当該仮定を記載します。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"2":{"t":false,"p":"契約番号で代えられるのは、貸付けの利率ではなく、「契約の相手方の商号・名称又は氏名及び住所」です。","w":"施行規則第13条第1項第1号ロ：極度方式貸付けに係る契約では、契約の相手方の商号、名称又は氏名及び住所を契約番号その他をもって代えることができます。貸付けの利率は第17条第1項第4号の記載事項で、代替の定めはありません。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"3":{"t":false,"p":"一定期間の取引状況をまとめた書面（マンスリーステートメント）を交付する場合でも、個別契約のたびに「契約年月日・貸付けの金額などを記載した簡素な書面」の交付は必要です。交付が不要になるのではなく、書面が簡素になるだけです。","w":"第17条第6項：相手方の承諾を得てマンスリーステートメントを交付するときは、第17条第1項の書面に代えて、契約年月日、貸付けの金額などを記載した書面を交付することができます。","r":[["貸金業法","17"]]},"4":{"t":false,"p":"極度額を引き下げた後、元の額まで引き上げる場合も、書面の再交付は「不要」です。","w":"第17条第2項後段かっこ書・施行規則第13条第5項：極度額を引き下げたとき（第1号）と、引き下げた後に元の額を上回らない額まで引き上げたとき（第2号）は、相手方の利益の保護に支障を生ずることがないときとして、変更後の書面を交付しなくてよいとされています。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]}}},"19-12":{"s":"契約内容を変更したとき、改めて契約締結時の書面を交付しなければならない「重要な事項」（施行規則第13条第2項）を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"貸金業者の商号・名称・住所（第17条第1項第1号）は、再交付が必要な「重要なもの」に含まれていません。","w":"施行規則第13条第2項第1号に挙げられているのは、第17条第1項第4号（利率）・第5号（返済の方式）・第7号（賠償額の予定）や、各回の返済期日及び返済金額などです。第1号の事項は挙げられていません。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"2":{"t":false,"p":"利率の「引下げ」のように相手方の利益となる変更は、再交付が「不要」です。","w":"施行規則第13条第2項第1号イかっこ書：貸付けの利率を引き下げる場合その他の契約の相手方の利益となる変更を加える場合は、除かれます。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"3":{"t":true,"w":"各回の返済期日及び返済金額（施行規則第13条第1項第1号チ）は、同条第2項第1号ロで重要な事項とされています（相手方に有利な変更でも除かれません）。保証人にも、第17条第4項後段・施行規則第13条第10項により変更後の書面を交付します。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"4":{"t":false,"p":"変更が生じた事項「だけ」を記載すれば足りるのではなく、変更後の内容で第17条第1項各号の事項を記載した書面を交付します。","w":"第17条第1項後段は、重要な事項を変更したときも「同様とする」と定めています。前段と同じく、各号に掲げる事項について契約の内容を明らかにする書面を交付するという意味です。変更した事項だけを記載すればよいという定めは、取り込んだ資料にはありません（結論は公式正答によります）。","r":[["貸金業法","17"]]}}},"19-13":{"s":"帳簿（第19条）の備付けと閲覧（第19条の2）を問う問題です。適切なのはｂとｄです。","items":{"a":{"t":false,"p":"代理店も「営業所又は事務所」に含まれるので、帳簿の備付けは「必要」です。備付けが不要とされているのは、現金自動設備（ATM）だけです。","w":"施行規則第1条の5で、営業所又は事務所には代理店も含まれます。第19条は営業所又は事務所ごとに帳簿を備えるよう定め、施行規則第17条第2項で免除されるのは営業所等が現金自動設備である場合だけです。","r":[["貸金業法","19"],["貸金業法施行規則","1の5"],["貸金業法施行規則","17"]]},"b":{"t":true,"w":"施行規則第16条第3項第1号：帳簿を保存すべき営業所等ごとに、第17条第1項の書面（契約締結時の書面）の写しを保存すれば、同条第1項第1号の事項の記載に代えることができます。","r":[["貸金業法施行規則","16"]]},"c":{"t":false,"p":"保証人は「債務者等」に含まれ、弁済者も施行規則で請求できる者とされているので、債務者の承諾は「不要」です。","w":"第19条の2：債務者等（債務者又は保証人）、債務者等であった者、その他内閣府令で定める者が請求できます。施行規則第17条の2第1項第3号：債務者等のために又は債務者等に代わって弁済をした者も含まれます。","r":[["貸金業法","19の2"],["貸金業法施行規則","17の2"],["貸金業法","2"]]},"d":{"t":true,"w":"第19条の2後段：請求が請求者の権利の行使に関する調査を目的とするものでないことが明らかであるときを除き、拒むことができません。","r":[["貸金業法","19の2"]]}}},"19-14":{"s":"取立て行為の規制（第21条）と監督指針の解釈を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"不適当な時間帯は「午後8時から午前9時」ではなく、「午後9時から午前8時」です。","w":"第21条第1項第1号・施行規則第19条第1項。","r":[["貸金業法","21"],["貸金業法施行規則","19"]]},"2":{"t":false,"p":"禁止されているのは、債務者等以外の者に弁済を「要求すること」です。債務者等以外の者から弁済を「受けること」自体は禁止されていません。","w":"第21条第1項第7号：債務者等以外の者に対し、債務者等に代わって債務を弁済することを要求すること、が禁止されています。","r":[["貸金業法","21"]]},"3":{"t":false,"p":"家族に知られないよう要請を受けている場合「以外」は、自宅への電話で貸金業者と名乗ったり、郵送物の差出人を貸金業者としたりしても、直ちに第5号には該当しないとされています。要請の有無に「かかわらず」該当するおそれが大きいわけではありません。","w":"監督指針Ⅱ－2－19：第21条第1項第5号は、心理的圧迫を加えて弁済を強要することを禁止する趣旨であると説明されています。","r":[["貸金業法","21"]]},"4":{"t":true,"w":"監督指針Ⅱ－2－19：第21条第1項各号は「人の私生活若しくは業務の平穏を害するような言動」の例示で、ほかに、反復継続して電話・電報・電子メール・ファクシミリ等で送信したり、居宅を訪問したりすることは、該当するおそれが大きいとされています。","r":[["貸金業法","21"]]}}},"19-15":{"s":"開始等の届出（第24条の6の2・施行規則第26条の25）を問う問題です。届出の期限は2週間以内です。適切なのはｂとｃです。","items":{"a":{"t":false,"p":"届出が必要なのは債権を「譲渡した」場合だけで、「譲り受けた」場合は届出事由になっていません。","w":"施行規則第26条の25第1項第3号：貸付けに係る契約に基づく債権を他人に譲渡した場合。","r":[["貸金業法","24の6の2"],["貸金業法施行規則","26の25"]]},"b":{"t":true,"w":"施行規則第26条の25第1項第6号：第三者に貸金業の業務の委託を行った場合又は委託を行わなくなった場合。","r":[["貸金業法","24の6の2"],["貸金業法施行規則","26の25"]]},"c":{"t":true,"w":"施行規則第26条の25第1項第7号：貸金業協会に加入又は脱退した場合。","r":[["貸金業法","24の6の2"],["貸金業法施行規則","26の25"]]},"d":{"t":false,"p":"届出の期限は「30日以内」ではなく「2週間以内」です。","w":"施行規則第26条の25第2項。","r":[["貸金業法施行規則","26の25"]]}}},"19-16":{"s":"登録行政庁による監督（立入検査・役員の解任命令・登録取消し・行政処分の考え方）を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"立入検査は、法令違反が認められる場合に限られず、「資金需要者等の利益の保護を図るため必要があると認めるとき」に行えます。","w":"第24条の6の10第3項。","r":[["貸金業法","24の6の10"]]},"2":{"t":true,"w":"取立て制限者（暴力団員等など）と知りながら債権譲渡をすることは、第24条の6の4第1項第3号の処分事由です。同条第2項：役員が同条第1項第2号から第12号までのいずれかに該当することとなったときは、その役員の解任を命ずることができます。","r":[["貸金業法","24の6の4"],["貸金業法","24"]]},"3":{"t":false,"p":"業務停止だけでなく、登録の取消しも「できます」。","w":"暴力団員等は保証業者についての取立て制限者に当たります（第24条の2第3項第1号）。取立て制限者と知りながら保証契約を締結したときは、第24条の6の4第1項第5号により、登録の取消し又は1年以内の業務の全部若しくは一部の停止を命ずることができます。","r":[["貸金業法","24の6の4"],["貸金業法","24の2"]]},"4":{"t":false,"p":"重大性・悪質性「だけ」ではなく、経営管理態勢の適切性や、貸金業者が自主的に利益の保護に取り組んでいるといった「軽減事由」も勘案して決定します。","w":"監督指針Ⅲ－5：①当該行為の重大性・悪質性、②背景となった経営管理態勢及び業務運営態勢の適切性、③軽減事由（行政による対応に先行して自主的に資金需要者等の利益の保護のために取り組んでいる等）を勘案します。","r":[["貸金業法","24の6の3"]]}}},"19-17":{"s":"指定信用情報機関（借入れの情報を集めて貸金業者に提供する機関）への個人信用情報の提供と、信用情報の使い方を問う問題です。適切なのはｃとｄです。","items":{"a":{"t":false,"p":"極度方式基本契約（枠の契約）そのものは、個人信用情報の提供の対象から「除かれて」います。","w":"第41条の35第2項で提供するのは「個人信用情報」です。第2条第14項・施行規則第1条の2の3第1号により、極度方式基本契約に係るものは個人信用情報から除かれます（枠の中で実際に借りた個々の極度方式貸付けは対象です）。","r":[["貸金業法","41の35"],["貸金業法","2"],["貸金業法施行規則","1の2の3"]]},"b":{"t":false,"p":"同意の記録の保存期間は「提供した日から10年間」ではなく、「その同意に基づき指定信用情報機関が信用情報を保有している間」です。","w":"第41条の36第3項・施行規則第30条の16第1項。","r":[["貸金業法","41の36"],["貸金業法施行規則","30の16"]]},"c":{"t":true,"w":"第41条の38第1項で、返済能力等調査以外の目的での使用が禁止されています。監督指針Ⅱ－2－14（注）に、記述のとおりの例（途上与信で得た信用情報の勧誘への二次利用、内部データベースに取り込んでの勧誘への利用。債権の保全を目的とした利用を含む）が挙げられています。","r":[["貸金業法","41の38"]]},"d":{"t":true,"w":"第41条の36第1項：信用情報の提供を依頼する場合は、あらかじめ、資金需要者等から「書面又は電磁的方法による」同意を得なければなりません。口頭の同意では足りません。","r":[["貸金業法","41の36"]]}}},"19-18":{"s":"出資法（刑事罰の上限）と利息制限法（民事上の無効）の金利規制を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"刑事罰の対象は年20%を「超える」利息の契約です。年20%ちょうどは対象になりません。","w":"出資法第5条第2項：業として金銭の貸付けを行う者が、年20パーセントを超える割合による利息の契約をしたときは、5年以下の拘禁刑若しくは1,000万円以下の罰金又は併科。（なお、元本50万円に年20%は利息制限法の上限（年18%）を超えるので、超える部分は民事上は無効です。）","r":[["出資法","5"],["利息制限法","1"]]},"2":{"t":false,"p":"変動利率で特約上限利率を定めなかった場合、貸付けの利息は年10%とみなされます。保証料年10%と合算しても年20%ちょうどで、20%を「超えない」ので、刑事罰の対象になりません。","w":"出資法第5条の2第1項：保証料は、貸付けの利息と合算して年20パーセントを超えると処罰されます。同条第2項第2号：変動利率で特約上限利率の定めがない場合は、年10パーセントを貸付けの利息の割合とみなします。","r":[["出資法","5の2"]]},"3":{"t":false,"p":"媒介手数料（借入れを仲介した手数料）を制限しているのは利息制限法ではなく、出資法第4条です。","w":"出資法第4条第1項：金銭の貸借の媒介を行う者は、媒介に係る貸借の金額の100分の5に相当する金額（貸借の期間が1年未満のものは期間に応じて計算した額）を超える手数料の契約などをしてはなりません。利息制限法には、媒介手数料を無効とする定めはありません。","r":[["出資法","4"]]},"4":{"t":true,"w":"利息制限法第7条第1項：営業的金銭消費貸借（業として行う貸付け）の債務不履行による賠償額の予定（遅延損害金）は、元本に対する割合が年2割（20%）を超えると、その超過部分が無効です。（業としない貸付けでは、第4条第1項で第1条の率の1.46倍が上限です。）","r":[["利息制限法","7"],["利息制限法","4"]]}}},"19-19":{"s":"金融ADR制度（裁判をせずに苦情・紛争を解決する仕組み。貸金業では日本貸金業協会が指定紛争解決機関）を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"第12条の2の2第1項第1号：指定紛争解決機関が存在する場合、貸金業者は協会員かどうかにかかわらず、一の指定紛争解決機関と手続実施基本契約を締結する措置を講じなければなりません。同条第2項：その指定紛争解決機関の商号又は名称を公表しなければなりません。","r":[["貸金業法","12の2の2"]]},"2":{"t":false,"p":"指定紛争解決機関の商号又は名称は、契約締結時の書面だけでなく、契約締結前の書面にも記載が「必要」です。","w":"契約締結前の書面：施行規則第12条の2第1項第1号ヌ（1）。契約締結時の書面：施行規則第13条第1項第1号の同様の事項。どちらも、手続実施基本契約の相手方である指定紛争解決機関の商号又は名称を記載します。","r":[["貸金業法","16の2"],["貸金業法施行規則","12の2"],["貸金業法施行規則","13"]]},"3":{"t":true,"w":"第41条の44第2項第6号：手続実施基本契約には、記述のとおり、訴訟が係属している旨、請求の理由及び訴訟の程度を報告する義務を定めます。","r":[["貸金業法","41の44"]]},"4":{"t":true,"w":"第41条の44第2項第2号：加入貸金業者は、手続に応じるよう求められたときは、正当な理由なくこれを拒んではなりません。","r":[["貸金業法","41の44"]]}}},"19-20":{"s":"年収証明書（源泉徴収票など、収入を明らかにする書面）の提出を受けなければならない場面です。自社の合算額が50万円超、又は他社残高を含めた合算額が100万円超のときに必要です。公式正答では③が適切でないとされています。④は、現行法では期限が変わっています。","law":"④の期限について、公式正答（基準日2024年4月1日）では「2か月以内」が適切とされていますが、現行（基準日2026年4月1日）の施行規則第10条の26第1項は「1月以内」と定めています。","items":{"1":{"t":true,"w":"自社の貸付け40万円＋他社残高70万円＝110万円が100万円を超えるので、第13条第3項第2号により年収証明書が必要です。","r":[["貸金業法","13"]]},"2":{"t":true,"w":"100万円の貸付けは自社の合算額が50万円を超えるので、第13条第3項第1号で年収証明書が必要です。源泉徴収票は「一般的に発行される直近の期間に係るもの」でなければならないので（施行規則第10条の17第2項第1号）、2年前に発行されたものでは足りません（結論は公式正答によります）。","r":[["貸金業法","13"],["貸金業法施行規則","10の17"]]},"3":{"t":false,"p":"除外契約（住宅資金貸付契約等）の残高は合算額に含めないので、合算額は30万円で100万円を「超えません」。年収証明書は「不要」です。","w":"第13条の3第3項・第5項第3号：極度方式個人顧客合算額の他社残高からは、住宅資金貸付契約等（第13条の2第2項。除外契約）に係る残高が除かれます。","r":[["貸金業法","13の3"],["貸金業法","13の2"]]},"4":{"t":true,"now":false,"w":"公式正答では適切とされています。現行の施行規則第10条の26第1項では、極度方式個人顧客合算額が100万円を超えると知った日から「1月以内」に提出又は提供を受けなければならないとされています。","r":[["貸金業法","13の3"],["貸金業法施行規則","10の26"]]}}},"19-21":{"s":"総量規制の例外のうち「借入残高を段階的に減少させるための借換え」（施行規則第10条の23第1項第1号の2）の要件を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"「返済金額の合計額が既存債務を上回らないこと」は、第1号（顧客に一方的に有利な借換え）の要件で、第1号の2では要件に「なっていません」。","w":"施行規則第10条の23第1項第1号の2ニ：第1号の要件のうちイとハからヘまでを満たすことが必要で、ロ（返済金額の合計額）は除かれています。かわりに、同号ハで、定期の返済により残高が段階的に減少することが見込まれることが要件です。","r":[["貸金業法施行規則","10の23"]]},"2":{"t":true,"w":"施行規則第10条の23第1項第1号イ（第1号の2ニで準用）：1か月の負担が既存債務の1か月の負担を上回らないこと。","r":[["貸金業法施行規則","10の23"]]},"3":{"t":true,"w":"施行規則第10条の23第1項第1号の2ロ：貸付けの利率が既存債務の利率（2以上あるときは残高による加重平均）を上回らないこと。","r":[["貸金業法施行規則","10の23"]]},"4":{"t":true,"w":"施行規則第10条の23第1項第1号ハ・ホ（第1号の2ニで準用）：既存債務の物的担保以外の物的担保を供させないこと、既存債務の保証人以外の者を保証人としないこと。","r":[["貸金業法施行規則","10の23"]]}}},"19-22":{"s":"貸付条件の広告（第15条）で表示すべき事項と、表示できる連絡先を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"第15条第2項：広告に表示できる電話番号は、貸金業者登録簿に登録されたもの（第4条第1項第7号）に限られます。登録できる電話番号は「場所を特定するもの」など（施行規則第3条の2第1項第1号）なので、携帯電話の番号は表示できません（結論は公式正答によります）。","r":[["貸金業法","15"],["貸金業法施行規則","3の2"]]},"2":{"t":false,"p":"広告では、登録番号の括弧書を省略「できません」。括弧書の省略が認められているのは、契約締結時の書面などです。","w":"第15条第1項第1号：広告には商号等と登録番号を表示します。施行規則第12条（広告の表示事項）には括弧書の省略の定めがありません。契約締結時の書面では、施行規則第13条で省略が認められています。","r":[["貸金業法","15"],["貸金業法施行規則","12"]]},"3":{"t":true,"w":"施行規則第12条第1項第1号ロ→第11条第3項第1号ロ：担保を供することが必要な場合における当該担保に関する事項を表示します。","r":[["貸金業法施行規則","12"],["貸金業法施行規則","11"]]},"4":{"t":true,"w":"施行規則第12条第6項：景品表示法、屋外広告物法第3条第1項に基づく都道府県の条例その他の法令に違反する広告をしてはなりません。","r":[["貸金業法施行規則","12"]]}}},"19-23":{"s":"契約締結前の書面（第16条の2）の交付時期・記載事項・文字の大きさを問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"交付の期限は「契約締結の前日まで」ではなく、「契約を締結するまで」です。","w":"第16条の2第1項：貸付けに係る契約を締結しようとする場合には、当該契約を締結するまでに書面を交付します。監督指針に「前日まで」とする記述はありません。","r":[["貸金業法","16の2"]]},"2":{"t":true,"w":"第16条の2第1項各号の記載事項は、貸金業者の商号等・貸付けの金額・利率・返済の方式・返済期間及び返済回数・賠償額の予定などです。契約年月日や相手方の氏名・住所は、契約がまだ成立していないので含まれていません（契約締結時の書面（第17条）では記載事項です）。","r":[["貸金業法","16の2"],["貸金業法","17"]]},"3":{"t":true,"w":"施行規則第12条の2第9項：日本産業規格Z8305に規定する8ポイント以上の大きさの文字及び数字を用いて、明瞭かつ正確に記載します。","r":[["貸金業法施行規則","12の2"]]},"4":{"t":true,"w":"監督指針Ⅱ－2－16（2）②：契約締結前の書面の交付後、契約締結前に法令で定められた記載事項の内容に変更が生じた場合には、再度交付する必要があります。","r":[["貸金業法","16の2"]]}}},"19-24":{"s":"弁済を受けたときの受取証書（第18条）と、全額弁済後の債権証書の返還（第22条）を問う問題です。適切でないのは④です。","items":{"1":{"t":true,"w":"第18条第1項：弁済を受けたときは、その都度、直ちに、受取証書を弁済をした者に交付します。","r":[["貸金業法","18"]]},"2":{"t":true,"w":"第18条第2項：預金又は貯金の口座への払込みなどで弁済を受けた場合は、弁済をした者の請求があった場合に限り交付します。","r":[["貸金業法","18"]]},"3":{"t":true,"w":"施行規則第15条第1項第3号・第4号：受取証書には、債務者の氏名と、債務者以外の者が弁済した場合はその者の氏名を記載します（債務者の氏名は、同条第2項により契約番号などで明示して代えることもできます）。","r":[["貸金業法","18"],["貸金業法施行規則","15"]]},"4":{"t":false,"p":"受取証書とは別の「完済証明書」を交付する義務は、貸金業法に「ありません」。全部の弁済を受けたときに義務があるのは、債権の証書を持っていればそれを「返還」することです。","w":"第22条：全部の弁済を受けた場合において債権の証書を有するときは、遅滞なく、これを弁済をした者に返還しなければなりません。","r":[["貸金業法","22"]]}}},"19-25":{"s":"債権譲渡の規制（第24条）と監督指針の着眼点を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"譲受人が貸金業者である場合も通知は「必要」です。「譲受人が貸金業者である場合を除き」という例外はありません。","w":"第24条第1項：債権を他人に譲渡するに当たっては、譲受人に対し、債権が貸金業者の貸付けに係る契約に基づいて発生したことなどと、譲受人の行為に貸金業法の一定の規定の適用がある旨を通知しなければなりません。","r":[["貸金業法","24"]]},"2":{"t":true,"w":"第24条第2項で、帳簿の備付け（第19条）などの規定が債権の譲受人に準用されています。","r":[["貸金業法","24"],["貸金業法","19"]]},"3":{"t":true,"w":"監督指針Ⅱ－2－20④に、記述のとおりの着眼点があります。"},"4":{"t":true,"w":"監督指針Ⅱ－2－20③に、記述のとおりの着眼点があります（弁護士法は、弁護士でない者が報酬目的で他人の法律事件を扱うことなどを禁止している法律です）。"}}},"19-26":{"s":"利息制限法の元本額の特則（第5条）を問う計算問題です。同じ貸主から重ねて借りるときは「既にある残元本＋新しい元本」、同時に2つ以上借りるときは「元本の合計」で上限利率を決めます（10万円未満20%、10万円以上100万円未満18%、100万円以上15%）。適切でないのは①です。","items":{"1":{"t":false,"p":"15%の上限になるのは「第二契約だけ」です。第一契約の利息は、締結時の元本30万円で判断するので18%のままで、無効になりません。","w":"第5条第1号：第二契約の元本額は、残元本15万円＋90万円＝105万円とみなされ、上限は年15%（第1条第3号）。第一契約は、重ねて借りたものではないので影響を受けません。","r":[["利息制限法","5"],["利息制限法","1"]]},"2":{"t":true,"w":"第5条第1号：20万円＋8万円＝28万円とみなされるので、上限は年18%（第1条第2号）。20%のうち18%を超える部分が無効です。","r":[["利息制限法","5"],["利息制限法","1"]]},"3":{"t":true,"w":"第5条：残元本5万円＋同時に借りた60万円＋40万円で100万円以上となるので、上限は年15%（第1条第3号）。第二・第三契約とも18%のうち15%を超える部分が無効です。","r":[["利息制限法","5"],["利息制限法","1"]]},"4":{"t":true,"w":"第5条：残元本10万円＋80万円＋9万円＝99万円で100万円未満なので、上限は年18%（第1条第2号）。第二契約（18%）は有効、第三契約（20%）は18%を超える部分が無効です。","r":[["利息制限法","5"],["利息制限法","1"]]}}},"19-27":{"s":"みなし利息（利息以外の名目で受け取るお金も利息として扱うこと。利息制限法第3条）の例外を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"第6条第2項第3号・施行令第2条第1号：ATMの利用料は、1万円以下の額なら110円（消費税等を含む）までは利息とみなされません。","r":[["利息制限法","6"],["利息制限法施行令","2"]]},"2":{"t":false,"p":"貸金業法の書面の再発行手数料は、利息と「みなされません」。","w":"第6条第1項・施行令第1条第2号：債務者の要請により行う、貸金業法の規定により交付した書面の再発行の手数料は、みなし利息の規定（第3条本文）が適用されません。","r":[["利息制限法","6"],["利息制限法施行令","1"]]},"3":{"t":true,"w":"第6条第2項第1号：公租公課（税金など）の支払に充てられるもの（収入印紙代）は、契約の締結の費用として利息とみなされません。","r":[["利息制限法","6"],["利息制限法","3"]]},"4":{"t":true,"w":"例外になるのはカードの「再発行」の手数料だけです（第6条第1項・施行令第1条第1号）。契約時に最初に交付するカードの発行手数料は、第3条により利息とみなされます。","r":[["利息制限法","6"],["利息制限法","3"],["利息制限法施行令","1"]]}}},"19-28":{"s":"制限行為能力者（未成年者・成年被後見人・被保佐人・被補助人。ひとりで完全に有効な契約ができない人）の行為能力を問う問題です。正しいのは③です。","items":{"1":{"t":false,"p":"成年被後見人の法律行為は、成年後見人の同意を得ていても取り消すことが「できます」（日用品の購入など日常生活に関する行為を除く）。","w":"民法第9条：成年被後見人の法律行為は、取り消すことができます。例外は日用品の購入その他日常生活に関する行為だけで、成年後見人の同意を得た場合を例外とする定めはありません。","r":[["民法","9"]]},"2":{"t":false,"p":"相続の承認又は放棄には、保佐人の同意が「必要」です。","w":"民法第13条第1項第6号：相続の承認若しくは放棄又は遺産の分割をするには、保佐人の同意を得なければなりません。","r":[["民法","13"]]},"3":{"t":true,"w":"民法第17条第1項・第4項：被補助人が補助人の同意を要するのは、家庭裁判所の審判で定めた特定の法律行為だけです。それ以外は単独で有効に行えます。","r":[["民法","17"]]},"4":{"t":false,"p":"成年者と同一の行為能力を有するのは「すべての法律行為」ではなく、「許された営業に関して」だけです。成年に達したとみなされるわけでもありません。","w":"民法第6条第1項：一種又は数種の営業を許された未成年者は、その営業に関しては、成年者と同一の行為能力を有します。","r":[["民法","6"]]}}},"19-29":{"s":"無効と取消しの効果を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"無効と知って追認すると、行為の時にさかのぼって有効になるのではなく、追認の時に「新たな行為をしたもの」とみなされます。","w":"民法第119条：無効な行為は、追認によっても効力を生じません。ただし、無効であることを知って追認をしたときは、新たな行為をしたものとみなします。","r":[["民法","119"]]},"2":{"t":false,"p":"成年被後見人は、法定代理人の同意を得ても、取り消すことができる行為を追認「できません」。","w":"民法第124条第2項第2号：法定代理人等の同意を得て追認できる制限行為能力者から、成年被後見人は除かれています。成年被後見人は、行為能力者となった後（取消しの原因となっていた状況が消滅した後）でなければ追認できません（同条第1項）。","r":[["民法","124"]]},"3":{"t":false,"p":"取り消された行為は、将来に向かってではなく、「初めから無効であった」ものとみなされます。","w":"民法第121条。","r":[["民法","121"]]},"4":{"t":true,"w":"民法第121条の2第3項：行為の時に制限行為能力者であった者は、その行為によって現に利益を受けている限度（現存利益）において、返還の義務を負います。原則（同条第1項）の原状回復義務より軽くなっています。","r":[["民法","121の2"]]}}},"19-30":{"s":"消滅時効（一定期間権利を行使しないと権利が消える制度）を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"5年で消滅するのは、権利を行使できることを「知った時から」5年です。知っているか否かにかかわらず進むのは、権利を行使できる時から「10年」の方です。","w":"民法第166条第1項：①債権者が権利を行使することができることを知った時から5年間、②権利を行使することができる時から10年間、のいずれかで時効によって消滅します。","r":[["民法","166"]]},"2":{"t":false,"p":"時効は、当事者が「援用」（時効の利益を受けると主張すること）しなければ、裁判所はこれによって裁判をすることが「できません」。","w":"民法第145条。","r":[["民法","145"]]},"3":{"t":false,"p":"申立ての取下げで終了した場合も、終了の時から6か月を経過するまでは時効の完成猶予の効力が「生じます」（時効の更新はしません）。","w":"民法第148条第1項：強制執行などの事由が終了するまで時効は完成せず、申立ての取下げ等で終了した場合は、その終了の時から6箇月を経過するまで完成しません。同条第2項ただし書：取下げ等で終了した場合は、更新（時効がゼロから進み直すこと）は生じません。","r":[["民法","148"]]},"4":{"t":true,"w":"民法第152条第1項：時効は、権利の承認があったときは、その時から新たにその進行を始めます（時効の更新）。記述は公式正答どおり適切です。なお、時効完成後に完成を知らずに承認した債務者がその後に時効を援用できるかは、判例の考え方によります（条文には直接書かれていません）。","r":[["民法","152"]]}}},"19-31":{"s":"金銭債務の遅延損害金（返済が遅れたときの賠償金）の利率を問う問題です。約定利率が法定利率（年3%）を超えるときは、約定利率によります。正しいのは①です。","items":{"1":{"t":true,"w":"民法第419条第1項：金銭債務の不履行の損害賠償額は法定利率によりますが、ただし書で、約定利率が法定利率を超えるときは約定利率によります。約定利率15%は法定利率3%（第404条第2項）を超えるので、15%で請求できます。","r":[["民法","419"],["民法","404"]]},"2":{"t":false,"p":"約定利率と法定利率を「合計」するのではなく、約定利率（15%）だけで計算します。","w":"民法第419条第1項ただし書。","r":[["民法","419"]]},"3":{"t":false,"p":"法定利率（3%）「しか」請求できないのではなく、約定利率（15%）で請求できます。","w":"民法第419条第1項ただし書：約定利率が法定利率を超えるときは、約定利率によります。","r":[["民法","419"]]},"4":{"t":false,"p":"金銭債務の遅延損害金は、損害を証明しなくても請求「できます」。","w":"民法第419条第2項：債権者は、損害の証明をすることを要しません。","r":[["民法","419"]]}}},"19-32":{"s":"保証と連帯保証の違いを問う問題です。連帯保証人には、催告の抗弁・検索の抗弁・分別の利益がありません。正しいのは③です。","items":{"1":{"t":false,"p":"書面（又は電磁的記録）が必要なのは連帯保証に限らず、通常の保証契約も同じです。口頭の合意だけでは効力を「生じません」。","w":"民法第446条第2項・第3項：保証契約は、書面でしなければ、その効力を生じません。電磁的記録でされたときは書面によってされたものとみなします。","r":[["民法","446"]]},"2":{"t":false,"p":"保証契約の締結後に主たる債務が加重されても、保証人（連帯保証人を含む）の負担は加重「されません」。","w":"民法第448条第2項。","r":[["民法","448"]]},"3":{"t":true,"w":"民法第456条・第427条：数人の保証人は、原則として平等の割合で分割された額だけを負担します（分別の利益）。連帯保証人にはこの分別の利益がなく、各自が全額を負担するというのが判例の考え方です（条文には直接書かれていません）。","r":[["民法","456"],["民法","427"]]},"4":{"t":false,"p":"連帯保証人には、「まず主たる債務者に催告せよ」と請求する権利（催告の抗弁）が「ありません」。","w":"民法第454条：保証人は、主たる債務者と連帯して債務を負担したときは、前二条（第452条の催告の抗弁、第453条の検索の抗弁）の権利を有しません。記述の「破産手続開始の決定を受けたとき又は行方が知れないとき」は、通常の保証人の催告の抗弁の例外（第452条ただし書）です。","r":[["民法","454"],["民法","452"]]}}},"19-33":{"s":"定型約款（ネット取引の利用規約のように、多くの人と同じ内容で契約するための条項）を問う問題です。正しいのは①です。","items":{"1":{"t":true,"w":"民法第548条の2第1項かっこ書の定義どおりです。","r":[["民法","548の2"]]},"2":{"t":false,"p":"内容を示す義務は、合意をするまでに必ず示すものではなく、「相手方から請求があった場合」に遅滞なく示すものです。","w":"民法第548条の3第1項：定型取引合意の前又は合意の後相当の期間内に相手方から請求があった場合には、遅滞なく、相当な方法でその内容を示さなければなりません。","r":[["民法","548の3"]]},"3":{"t":false,"p":"相手方が個別の条項を認識していなくても、その条項について合意をしたものと「みなされます」。","w":"民法第548条の2第1項：定型取引合意をした者は、①定型約款を契約の内容とする旨の合意をしたとき、又は②準備者があらかじめ契約の内容とする旨を相手方に表示していたときは、定型約款の個別の条項についても合意をしたものとみなされます（ただし、相手方の利益を一方的に害する条項は、同条第2項により合意しなかったものとみなされます）。","r":[["民法","548の2"]]},"4":{"t":false,"p":"相手方の一般の利益に適合する場合だけでなく、契約の目的に反せず、変更の必要性・内容の相当性などに照らして「合理的な」変更であれば、個別の合意なしに変更できます。","w":"民法第548条の4第1項第1号・第2号。","r":[["民法","548の4"]]}}},"19-34":{"s":"相続（代襲相続・法定相続分・限定承認・相続人不存在）を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"代襲相続の原因は、相続開始以前の死亡・欠格・廃除の3つです。「相続の放棄」をした者の子は代襲「しません」。","w":"民法第887条第2項：子が相続の開始以前に死亡したとき、又は第891条（欠格）に該当し若しくは廃除によって相続権を失ったときに、その者の子が代襲して相続人となります。放棄は挙げられていません。","r":[["民法","887"]]},"2":{"t":false,"p":"配偶者と直系尊属（父母など）が相続人のとき、配偶者の相続分は4分の3ではなく「3分の2」です。4分の3は兄弟姉妹と相続する場合です。","w":"民法第900条第2号・第3号。","r":[["民法","900"]]},"3":{"t":false,"p":"相続人が数人あるときの限定承認は、各自が個別にではなく「共同相続人の全員が共同して」のみすることができます。","w":"民法第923条。限定承認とは、相続で得た財産の範囲でだけ借金などを引き継ぐ方法です。","r":[["民法","923"]]},"4":{"t":true,"w":"民法第951条：相続人のあることが明らかでないときは、相続財産は、法人とします。","r":[["民法","951"]]}}},"19-35":{"s":"株式会社の取締役と取締役会（会社法）を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"任期は、定款又は株主総会の決議によって「短縮」することができます（公開会社でない会社は、定款で10年まで「伸長」もできます）。","w":"会社法第332条第1項ただし書・第2項。","r":[["会社法","332"]]},"2":{"t":true,"w":"会社法第363条第2項：代表取締役と、業務を執行する取締役として選定された取締役は、3箇月に1回以上、自己の職務の執行の状況を取締役会に報告しなければなりません。","r":[["会社法","363"]]},"3":{"t":false,"p":"多額の借財の決定は、取締役に委任「できません」。取締役会自身で決める必要があります。","w":"会社法第362条第4項第2号。","r":[["会社法","362"]]},"4":{"t":false,"p":"悪意又は重大な過失がある取締役自身も、第三者に対して損害賠償責任を「負います」。","w":"会社法第429条第1項：役員等がその職務を行うについて悪意又は重大な過失があったときは、当該役員等は、これによって第三者に生じた損害を賠償する責任を負います。（会社が代表者の行為について責任を負う定めは第350条です。）","r":[["会社法","429"],["会社法","350"]]}}},"19-36":{"s":"犯罪収益移転防止法（マネー・ローンダリング対策の法律）の取引時確認と記録を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"貸金業者の特定取引として挙げられているのは、金銭の貸付け又は金銭の貸借の媒介を内容とする契約の締結で、保証契約は「含まれていません」。","w":"犯罪収益移転防止法施行令第7条第1項第1号カ。保証契約が挙げられていないことの結論は公式正答によります。","r":[["犯罪収益移転防止法施行令","7"]]},"2":{"t":false,"p":"会社の代表者が会社のために取引をするときは、会社の確認に加えて、取引の任に当たっている代表者の本人特定事項の確認も「必要」です。","w":"犯罪収益移転防止法第4条第4項。","r":[["犯罪収益移転防止法","4"]]},"3":{"t":false,"p":"確認記録の保存期間7年の起算点は「記録を作成した日」ではなく、「特定取引等に係る契約が終了した日」などです。","w":"犯罪収益移転防止法第6条第2項：確認記録を、特定取引等に係る契約が終了した日その他の主務省令で定める日から、7年間保存しなければなりません。","r":[["犯罪収益移転防止法","6"]]},"4":{"t":true,"w":"犯罪収益移転防止法第11条第4号・同法施行規則第32条第1項第1号：特定事業者作成書面等を作成し、必要に応じて見直しを行い、必要な変更を加えることが、努力義務とされる措置です。","r":[["犯罪収益移転防止法","11"],["犯罪収益移転防止法施行規則","32"]]}}},"19-37":{"s":"意思表示（心裡留保・虚偽表示・到達・公示）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"心裡留保（冗談などで本心でない意思表示）は、原則として「有効」です。相手方が真意でないことを知り又は知ることができたときに、例外として「無効」になります。記述は原則と例外が逆です。","w":"民法第93条第1項。","r":[["民法","93"]]},"2":{"t":true,"w":"民法第94条：相手方と通じてした虚偽の意思表示は無効ですが、その無効は善意の第三者に対抗することができません。","r":[["民法","94"]]},"3":{"t":true,"w":"民法第97条第3項。","r":[["民法","97"]]},"4":{"t":true,"w":"民法第98条第1項。","r":[["民法","98"]]}}},"19-38":{"s":"代理（顕名・復代理・表見代理）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"相手方が、代理人が本人のためにすることを知り又は知ることができたときは、本人の追認がなくても、本人に対して効力を「生じます」。","w":"民法第100条：本人のためにすることを示さない意思表示は、自己のためにしたものとみなします。ただし、相手方がそれを知り又は知ることができたときは、第99条第1項（本人に直接効力が生じる）を準用します。","r":[["民法","100"],["民法","99"]]},"2":{"t":true,"w":"民法第104条。","r":[["民法","104"]]},"3":{"t":true,"w":"民法第105条。","r":[["民法","105"]]},"4":{"t":true,"w":"民法第109条第1項（代理権授与の表示による表見代理）。","r":[["民法","109"]]}}},"19-39":{"s":"期限の利益（返済期限まで返さなくてよいという借主の利益）を失う場合と、その放棄を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"民法第137条第2号：債務者が担保を滅失させ、損傷させ、又は減少させたときは、期限の利益を主張することができません。","r":[["民法","137"]]},"2":{"t":true,"w":"民法第137条第1号：債務者が破産手続開始の決定を受けたとき。","r":[["民法","137"]]},"3":{"t":false,"p":"利息の支払を1回遅滞しただけでは、民法上、期限の利益を失い「ません」。民法第137条が定める喪失事由は、破産手続開始・担保の滅失等・担保を供しないことの3つです。","w":"民法第137条。本問の契約には、利息の遅滞で期限の利益を失うという約定（特約）もありません。","r":[["民法","137"]]},"4":{"t":true,"w":"民法第136条：期限は債務者の利益のために定めたものと推定され、期限の利益は放棄することができます（ただし、相手方の利益を害することはできません）。","r":[["民法","136"]]}}},"19-40":{"s":"抵当権（物上代位・随伴性・抵当権消滅請求・被担保債権の範囲）を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"民法第372条・第304条：抵当権者は、目的物の賃貸によって債務者が受けるべき金銭（賃料）に対しても、払渡しの前に差し押さえれば、抵当権を行使できます（物上代位）。","r":[["民法","372"],["民法","304"]]},"2":{"t":false,"p":"特約がなくても、被担保債権が譲渡されれば、抵当権も一緒にＤに「移転します」。","w":"抵当権は被担保債権に従って移転します（随伴性）。この性質は条文に直接書かれておらず、結論は公式正答によります。","r":[]},"3":{"t":true,"w":"民法第380条：主たる債務者、保証人及びこれらの者の承継人は、抵当権消滅請求をすることができません。保証人Ｅが第三取得者になっても同じです。","r":[["民法","380"]]},"4":{"t":true,"w":"民法第375条：後順位抵当権者などがいる場合、利息その他の定期金は満期となった最後の2年分についてのみ抵当権を行使でき、遅延損害金も利息と通算して2年分が限度です。","r":[["民法","375"]]}}},"19-41":{"s":"金銭消費貸借契約（お金の貸し借りの契約）の成立・利息・返還時期・遅滞を問う問題です。適切でないのは②です。","items":{"1":{"t":true,"w":"民法第587条：消費貸借は、物を受け取ることによって効力を生じます（要物契約）。民法第587条の2第1項：書面でする消費貸借は、引き渡すことと返還することの合意だけで成立します（諾成契約）。","r":[["民法","587"],["民法","587の2"]]},"2":{"t":false,"p":"利息の特約がなければ、貸主は利息を請求「できません」。","w":"民法第589条第1項：貸主は、特約がなければ、借主に対して利息を請求することができません。","r":[["民法","589"]]},"3":{"t":true,"w":"民法第591条第1項。","r":[["民法","591"]]},"4":{"t":true,"w":"民法第412条第1項：確定期限があるときは、期限の到来した時から遅滞の責任を負います。民法第419条第3項：金銭債務の不履行については、不可抗力をもって抗弁とすることができません。","r":[["民法","412"],["民法","419"]]}}},"19-42":{"s":"民事執行法（裁判所を通じて強制的に回収する手続）の債務名義・債権執行・差押禁止を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"民事執行法第25条：強制執行は執行文の付された債務名義（判決など、強制執行できる根拠となる文書）の正本に基づいて実施します。ただし書で、少額訴訟の確定判決・仮執行宣言付少額訴訟判決・支払督促は、執行文がなくても正本で実施できます。","r":[["民事執行法","25"]]},"2":{"t":true,"w":"民事執行法第143条：債権執行は、執行裁判所の差押命令により開始します。","r":[["民事執行法","143"]]},"3":{"t":false,"p":"差押えの効力が生じるのは、債務者ではなく「第三債務者」（勤務先など、債務者にお金を払う立場の人）に送達された時です。","w":"民事執行法第145条第3項：差押命令は債務者及び第三債務者に送達します。同条第5項：差押えの効力は、差押命令が第三債務者に送達された時に生じます。","r":[["民事執行法","145"]]},"4":{"t":true,"w":"民事執行法第152条第1項第2号。","r":[["民事執行法","152"]]}}},"19-43":{"s":"個人情報保護法の利用目的（特定・制限・通知）と罰則を問う問題です。正しいのは④です。","items":{"1":{"t":false,"p":"取得の状況からみて利用目的が明らかであると認められる場合は、通知・公表は「不要」です。","w":"個人情報保護法第21条第4項第4号。","r":[["個人情報保護法","21"]]},"2":{"t":false,"p":"事業の承継で取得した個人情報は、あらかじめ本人の同意を得なければ、「承継前」の利用目的の達成に必要な範囲を超えて取り扱えません。承継した側が公表している利用目的の範囲で使えるわけではありません。","w":"個人情報保護法第18条第2項。","r":[["個人情報保護法","18"]]},"3":{"t":false,"p":"変更前の利用目的と関連性を有すると合理的に認められる範囲を超える変更は、通知・公表すれば足りるのではなく、そもそも「行ってはなりません」（本人の同意なく超える範囲で取り扱うことは第18条第1項で禁止）。","w":"個人情報保護法第17条第2項：利用目的の変更は、関連性を有すると合理的に認められる範囲を超えて行ってはなりません。範囲内の変更をした場合に、第21条第3項で通知又は公表します。","r":[["個人情報保護法","17"],["個人情報保護法","21"],["個人情報保護法","18"]]},"4":{"t":true,"w":"個人情報保護法第179条：個人情報データベース等を自己若しくは第三者の不正な利益を図る目的で提供し、又は盗用したときは、刑事罰（データベース等不正提供罪）の対象です。","r":[["個人情報保護法","179"]]}}},"19-44":{"s":"消費者契約法（消費者と事業者の契約で消費者を守る法律）の取消し・無効を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"消費者契約法には、無条件で申込みの撤回や解除ができる権利（クーリング・オフ）の定めは「ありません」。","w":"消費者契約法が定めるのは、不当な勧誘による意思表示の取消し（第4条）や、不当な契約条項の無効（第8条〜第10条）などです。","r":[["消費者契約法","4"]]},"2":{"t":true,"w":"消費者契約法第8条の3。","r":[["消費者契約法","8の3"]]},"3":{"t":false,"p":"重要事項について事実と異なることを告げられて誤認した場合、契約は「無効」ではなく、消費者が「取り消す」ことができます。","w":"消費者契約法第4条第1項第1号（不実告知）。","r":[["消費者契約法","4"]]},"4":{"t":false,"p":"無効になるのは条項全体ではなく、平均的な損害の額を「超える部分」だけです。","w":"消費者契約法第9条第1項第1号：当該消費者契約の解除に伴い事業者に生ずべき平均的な損害の額を超える部分について、無効とします。","r":[["消費者契約法","9"]]}}},"19-45":{"s":"日本貸金業協会の紛争解決等業務に関する規則（苦情処理手続と紛争解決手続）を問う問題です。正しいのは②です。","items":{"1":{"t":false,"p":"申立てができるのは個人に「限られません」。法人や権利能力なき社団等も申立てができます。","w":"紛争解決等業務に関する規則第37条：協会員等との間で貸金業務等関連苦情を有する契約者等である個人、法人又は法人でない社団若しくは財団で代表者若しくは管理者の定めがある者（権利能力なき社団等）が申立てをすることができます。"},"2":{"t":true,"w":"紛争解決等業務に関する規則第48条：当事者である協会員等は、苦情処理手続が開始された事案について直接交渉を行った場合、交渉の日時・場所・手法、交渉担当者及び同席者、交渉の内容などを報告しなければなりません。現行の規則では報告先を「相談センター」と定めています。"},"3":{"t":false,"p":"紛争解決手続は、「公開」ではなく「非公開」が原則です。当事者双方の同意を得た場合に、相当と認める者の傍聴を許すことができます。","w":"紛争解決等業務に関する規則第94条第1項。（苦情処理手続はすべて非公開です。第53条）"},"4":{"t":false,"p":"協会員等が受諾しなくてよいのは、契約者等が受諾しないときだけではありません。所定の期間内に訴訟が提起され取り下げられないときなども、受諾義務の例外です。","w":"紛争解決等業務に関する規則第90条第2項：協会員等は特別調停案を受諾しなければなりませんが、(1)契約者等が受諾しないとき、(2)(3)一定の期間内に訴訟が提起されて取り下げられないときなどは、この限りではありません。"}}},"19-46":{"s":"個人データの漏えい等が起きたときの個人情報保護委員会への報告と本人への通知（個人情報保護法第26条）を問う問題です。適切でないのは①です。","items":{"1":{"t":false,"p":"財産的被害が生じるおそれがある個人データ（クレジットカード番号など）の漏えい等は、本人の数が1,000人以下でも報告が「必要」です。1,000人超は別の報告事由です。","w":"個人情報保護委員会規則第7条（通則編ガイドライン3-5-3-1に掲載）：(1)要配慮個人情報、(2)不正利用により財産的被害が生じるおそれがある個人データ、(3)不正の目的をもって行われたおそれがある行為による漏えい等、(4)本人の数が1,000人を超える漏えい等、のいずれかに当たれば報告対象です。","r":[["個人情報保護法","26"]]},"2":{"t":true,"w":"通則編ガイドライン：高度な暗号化等の秘匿化がされている場合など、「高度な暗号化その他の個人の権利利益を保護するために必要な措置」が講じられている場合は、報告を要しません。","r":[["個人情報保護法","26"]]},"3":{"t":true,"w":"個人情報保護法第26条第2項：報告対象事態が生じた場合、本人に通知しなければなりません。ただし、本人への通知が困難な場合で、本人の権利利益を保護するため必要なこれに代わるべき措置をとるときは、この限りではありません。","r":[["個人情報保護法","26"]]},"4":{"t":true,"w":"個人情報保護委員会規則第8条第1項（通則編ガイドライン3-5-3-3「速報」）：事態を知った後、速やかに、報告をしようとする時点で把握している事項を報告します。","r":[["個人情報保護法","26"]]}}},"19-47":{"s":"日本貸金業協会の貸付自粛対応に関する規則（本人や家族の申告で、本人への新たな貸付けを控えてもらう制度）を問う問題です。適切でないのは③です。","items":{"1":{"t":true,"w":"貸付自粛対応に関する規則第7条第2項・第4項：配偶者又は二親等内の親族は、所在不明・金銭債務が原因の可能性・生命身体財産の保護に必要・本人の同意を得ることが困難、のすべてに該当する場合に申告でき、本人の意思に反することが明らかな場合は申告できません。"},"2":{"t":true,"w":"貸付自粛対応に関する規則第10条第2項：第7条第2項又は第3項の者（家族など）が申告をした場合には、自粛対象者は、いつでも当該申告を取り消すことができます。"},"3":{"t":false,"p":"撤回・取消しがなくても、登録から「5年」を経過すれば当然に抹消されます。","w":"貸付自粛対応に関する規則：個人信用情報機関との合意事項として、貸付自粛情報の登録期間は登録から5年以内とされ、別紙1（運用に関する事項）の4に、撤回又は取消がなされない場合でも登録から5年を経過したときは当然に抹消されることが定められています。"},"4":{"t":true,"w":"貸付自粛対応に関する規則第17条第3項に、記述のとおりの努力義務が定められています。"}}},"19-48":{"s":"損益計算書の段階利益（売上総利益→営業利益→経常利益）を計算する問題です。会社計算規則は取り込んでいないため、同じ考え方を定めた企業会計原則の損益計算書原則で確認します。正しいのは③（580百万円）です。","items":{"1":{"t":false,"p":"1,000百万円は、売上高−売上原価の「売上総利益」です。経常利益ではありません。","w":"売上総利益＝2,000−1,000＝1,000百万円。"},"2":{"t":false,"p":"600百万円は、売上総利益から販売費及び一般管理費を引いた「営業利益」です。経常利益は、ここに営業外収益を加え営業外費用を引いたものです。","w":"営業利益＝1,000−400＝600百万円。"},"3":{"t":true,"w":"企業会計原則・損益計算書原則五：経常利益は、営業利益に営業外収益を加え、これから営業外費用を控除して表示します。600＋80−100＝580百万円。特別利益・特別損失は、経常利益の後（税引前当期純利益の計算、同原則七）で加減するので含めません。"},"4":{"t":false,"p":"500百万円は、営業利益600から営業外費用100だけを引き、営業外収益80を加えていない額です。経常利益は、営業外収益も加えて計算します。","w":"経常利益580＋特別利益40−特別損失60＝560百万円が税引前当期純利益です（損益計算書原則七）。"}}},"19-49":{"s":"キャッシュ・フロー計算書の3つの区分（営業活動・投資活動・財務活動）を問う問題です。財務諸表等規則とキャッシュ・フロー計算書の基準は取り込んだ資料にないため、結論は公式正答によります。正しいのは②です。","items":{"1":{"t":false,"p":"長期借入れによる収入・返済による支出は、営業活動ではなく「財務活動」の区分です。","w":"結論は公式正答によります（取り込んだ資料では確認できません）。"},"2":{"t":true,"w":"資金の増加・減少を伴わない項目は、営業活動によるキャッシュ・フローの区分に掲記されます（結論は公式正答によります）。"},"3":{"t":false,"p":"社債の償還・株式の発行は、投資活動ではなく「財務活動」の区分です。","w":"結論は公式正答によります（取り込んだ資料では確認できません）。"},"4":{"t":false,"p":"貸付けによる支出・貸付金の回収による収入は、財務活動ではなく「投資活動」の区分です。","w":"結論は公式正答によります（取り込んだ資料では確認できません）。"}}},"19-50":{"s":"貸借対照表の区分を問う問題です。会社計算規則は取り込んでいないため、同じ考え方を定めた企業会計原則の貸借対照表原則で確認できる範囲で説明します。適切でないのは①です。","items":{"1":{"t":false,"p":"資産の部の区分は「流動資産、固定資産、投資その他の資産」ではなく、「流動資産、固定資産、繰延資産」です。投資その他の資産は、固定資産の中の区分です。","w":"企業会計原則・貸借対照表原則二：資産の部を流動資産、固定資産及び繰延資産に区分しなければなりません。（投資その他の資産が固定資産の中の区分であることは、結論として公式正答によります。）"},"2":{"t":true,"w":"企業会計原則・貸借対照表原則四㈠Ａ：現金預金は流動資産に属します。1年以内に期限の到来しない預金を除くことは、結論として公式正答によります。"},"3":{"t":true,"w":"企業会計原則・貸借対照表原則四㈡Ｂ：社債、長期借入金等の長期債務は、固定負債に属します。"},"4":{"t":true,"w":"株式会社の純資産の部を株主資本・評価・換算差額等・株式引受権・新株予約権に区分することは会社計算規則の定めで、取り込んだ資料にないため、結論は公式正答によります（企業会計原則では「資本の部」として定めています）。"}}},"20-01":{"s":"貸金業法第2条の用語の定義をそのまま問う問題です。適切なのはａだけです（1個）。","items":{"a":{"t":true,"w":"物品の売買・運送・保管・売買の媒介を業とする者が、その取引に付随して行う貸付けは「貸金業」から除かれます（第2条第1項第3号）。","r":[["貸金業法","2"]]},"b":{"t":false,"p":"「債務者等」は「債務者又は保証人」です。保証人は含まれ、「債務者であった者」という定義ではありません。","w":"第2条第5項。似た用語の「顧客等」は「資金需要者である顧客又は保証人となろうとする者」（同条第4項）です。","r":[["貸金業法","2"]]},"c":{"t":false,"p":"「貸付けの契約」には、貸付けに係る契約に係る保証契約も含まれます。","w":"第2条第3項：「貸付けの契約」とは、貸付けに係る契約又は当該契約に係る保証契約をいいます。","r":[["貸金業法","2"]]},"d":{"t":false,"p":"住宅の改良に必要な資金の貸付けも「住宅資金貸付契約」に含まれます。","w":"第2条第17項：住宅の建設・購入（土地・借地権の取得を含む）又は住宅の改良に必要な資金の貸付けに係る契約です。","r":[["貸金業法","2"]]}}},"20-02":{"s":"登録の有効期間（3年）と更新・登録換えの手続です。","items":{"a":{"t":false,"p":"登録の有効期間は2年ではなく3年です。","w":"第3条第2項：登録は3年ごとに更新を受けなければ効力を失います。","r":[["貸金業法","3"]]},"b":{"t":true,"w":"施行規則第5条：更新の申請は、有効期間満了の日の2か月前までにしなければなりません。","r":[["貸金業法施行規則","5"]]},"c":{"t":false,"p":"申請しただけでは営業できません。新たな登録（登録換え）を受けてはじめて、その営業所で貸金業を営めます。","w":"貸金業を営むには第3条第1項の登録が必要です。登録換えで新しい登録を受けると、従前の登録が効力を失います（第7条）。","r":[["貸金業法","3"],["貸金業法","7"]]},"d":{"t":true,"w":"施行規則第6条第1項：登録換えの申請は、現に受けている登録をした財務局長等又は都道府県知事を経由して行います。","r":[["貸金業法施行規則","6"]]}}},"20-03":{"s":"登録拒否事由（第6条第1項）のうち、役員・政令で定める使用人に関するものです。","items":{"a":{"t":true,"w":"法人の役員に、精神の機能の障害のため職務を適正に執行するのに必要な認知・判断・意思疎通を適切に行うことができない者がいると、登録拒否事由です（第6条第1項第9号イ、施行規則第5条の4）。","r":[["貸金業法","6"],["貸金業法施行規則","5の4"]]},"b":{"t":false,"p":"道路交通法違反の罰金刑は登録拒否事由ではありません。","w":"罰金刑で拒否事由になるのは、貸金業法・出資法・暴力団対策法などの違反や、取立て等に当たって刑法の罪を犯した場合などに限られます（第6条第1項第5号）。刑罰の種類を問わず拒否事由になるのは拘禁刑以上の刑です（同項第4号）。","r":[["貸金業法","6"]]},"c":{"t":false,"p":"拒否事由は「破産手続開始の決定を受けて復権を得ない者」です。復権を得た後に5年待つ必要はありません。","w":"第6条第1項第2号。復権を得れば、その日からこの拒否事由には当たりません。","r":[["貸金業法","6"]]},"d":{"t":true,"w":"登録を取り消された法人の、取消しの日前30日以内に役員だった者で、取消しの日から5年を経過しないものは拒否事由に該当する者です（第6条第1項第3号）。これが政令で定める使用人の中にいれば、法人Ａの登録拒否事由になります（同項第9号ロ）。","r":[["貸金業法","6"]]}}},"20-04":{"s":"変更の届出は「事後2週間以内」が原則で、営業所等の名称・所在地（第4条第1項第5号）と広告等に表示する連絡先（同第7号）だけは「あらかじめ」届け出ます。","items":{"a":{"t":true,"w":"「他に行っている事業の種類」（第4条第1項第9号）の変更は、変更の日から2週間以内に届け出ます（第8条第1項）。","r":[["貸金業法","8"],["貸金業法","4"]]},"b":{"t":false,"p":"広告・勧誘で表示する連絡先（電子メールアドレス等）の変更は、事後ではなく「あらかじめ」届け出ます。","w":"第4条第1項第7号の事項は、第8条第1項で事前の届出とされています。","r":[["貸金業法","8"],["貸金業法","4"]]},"c":{"t":true,"w":"「業務の種類及び方法」（第4条第1項第8号）の変更は、変更の日から2週間以内に届け出ます。","r":[["貸金業法","8"]]},"d":{"t":false,"p":"営業所又は事務所の名称・所在地の変更は、事後ではなく「あらかじめ」届け出ます。","w":"第4条第1項第5号の事項は、第8条第1項で事前の届出とされています。","r":[["貸金業法","8"],["貸金業法","4"]]}}},"20-05":{"s":"監督指針「Ⅱ－1 経営管理等」の着眼点です。内部監査部門は営業部門から独立していることがポイントです。","items":{"a":{"t":false,"p":"内部監査部門は営業部門の指揮命令系統の下ではなく、営業部門から独立して設置します。","w":"監督指針Ⅱ－1は、内部監査部門を「営業部門から独立した検査部署、監査部署等」とし、被監査部門から独立した実効性のある内部監査ができる態勢かを着眼点にしています。"},"b":{"t":false,"p":"業務運営全般のモニタリング・検証を行うのは内部監査部門ではなく内部管理部門で、重大な問題は経営陣に報告します。内部監査部門が事業計画の作成を主導するという記載もありません。","w":"監督指針Ⅱ－1：内部管理部門において適切なモニタリング・検証が行われ、重大な問題等を確認した場合に経営陣へ適切に報告が行われているか、が着眼点です。"},"c":{"t":true,"w":"規模等を踏まえ外部監査で代える場合は、監査目的を明確に指示し、結果を業務改善に活用する態勢が求められます。"},"d":{"t":true,"w":"従業者のいない個人業者などは、内部監査に代えて自己検証を行えます。自己検証の時間の確保、別添の自己検証リストに基づく項目設定、月1回以上の実施、記録の3年間保存などが着眼点です（監督指針Ⅱ－1）。"}}},"20-06":{"s":"貸金業務取扱主任者の設置基準（50分の1以上・常時勤務）と、欠けたときの措置期限（2週間）です。","items":{"a":{"t":true,"w":"営業所等ごとに、業務に従事する者の数に対する主任者の割合が50分の1以上となる数の主任者を置きます（第12条の3第1項、施行規則第10条の8）。","r":[["貸金業法","12の3"],["貸金業法施行規則","10の8"]]},"b":{"t":true,"w":"置く主任者は、その営業所等に常時勤務する者で、かつ他の営業所等の主任者として登録されていて変更の届出がない者であってはなりません（施行規則第10条の7）。","r":[["貸金業法施行規則","10の7"]]},"c":{"t":false,"p":"契約締結時の書面（第17条第1項）の記載事項に、貸金業務取扱主任者の氏名・登録番号はありません。","w":"主任者の氏名は、営業所等での掲示事項（第14条第1項第4号）や、資金需要者等から請求があったときに明らかにする事項（第12条の3第4項）です。","r":[["貸金業法","14"],["貸金業法","12の3"]]},"d":{"t":false,"p":"措置の期限は30日以内ではなく2週間以内です。","w":"第12条の3第3項：予見し難い事由で主任者の数が足りなくなったときは、2週間以内に必要な措置をとります。","r":[["貸金業法","12の3"]]}}},"20-07":{"s":"返済能力の調査（第13条第1項）は全ての貸付けの契約で必要です。指定信用情報機関の信用情報を使う義務（第2項）は、個人が相手で、例外契約でない場合です。","items":{"1":{"t":false,"p":"金銭の貸借の媒介の契約も「貸付けの契約」に当たるため、返済能力の調査が必要です。","w":"第13条第1項は「貸付けの契約を締結しようとする場合」に調査を義務づけています。「貸付け」には金銭の貸借の媒介が含まれます（第2条第1項）。","r":[["貸金業法","13"],["貸金業法","2"]]},"2":{"t":false,"p":"相手が法人でも、極度方式貸付けでも、返済能力の調査（第13条第1項）は必要です。","w":"極度方式貸付けが例外になるのは、指定信用情報機関の信用情報を使う義務（同条第2項、施行規則第10条の16第1号）の方です。","r":[["貸金業法","13"],["貸金業法施行規則","10の16"]]},"3":{"t":false,"p":"個人事業者も「個人である顧客等」なので、指定信用情報機関の信用情報を使わなければなりません。","w":"第13条第2項の対象は個人である顧客等です。事業者かどうかで区別はありません。","r":[["貸金業法","13"]]},"4":{"t":true,"w":"手形（融通手形を除く）の割引を内容とする契約は、信用情報の使用義務の例外です（施行規則第10条の16第2号、第1条の2の3第2号）。","r":[["貸金業法施行規則","10の16"],["貸金業法施行規則","1の2の3"]]}}},"20-08":{"s":"年収証明書（資力を明らかにする書面）の提出を受ける相手・種類・期間の問題です。","items":{"1":{"t":false,"p":"年収証明書の提出を受ける義務があるのは「個人顧客」（資金需要者である個人の顧客）からで、保証人となろうとする者からではありません。","w":"第13条第3項は、個人顧客から提出又は提供を受けると定めています。","r":[["貸金業法","13"]]},"2":{"t":false,"p":"既に受け取っている書面で足りるとは限りません。源泉徴収票は「一般的に発行される直近の期間に係るもの」でなければならず、1年前に受けたものがこれに当たらない場合があります。","w":"第13条第3項ただし書は既に提出を受けている場合を除外しますが、その書面は施行規則第10条の17第2項の要件（直近の期間に係るもの等）を満たす必要があります。","r":[["貸金業法","13"],["貸金業法施行規則","10の17"]]},"3":{"t":true,"w":"給与の支払明細書は直近2か月分以上が必要です。ただし、地方税額を基に合理的に算出する方法で年間の給与を算出する場合は直近のもので足ります（施行規則第10条の17第2項第2号）。","r":[["貸金業法施行規則","10の17"]]},"4":{"t":false,"p":"根拠法令なく行政サービスとして地方公共団体が交付する所得・課税証明書も「所得証明書」に含まれます。","w":"監督指針は、施行規則第10条の17第1項第8号の「所得証明書」の例として、これを挙げています。","r":[["貸金業法施行規則","10の17"]]}}},"20-09":{"s":"極度方式基本契約の定期的な調査（第13条の3第2項）と、基準額超過のときの措置（第13条の4）です。","items":{"a":{"t":true,"w":"所定の期間の末日の極度方式貸付けの残高の合計額が10万円以下なら、定期的な調査は不要です（第13条の3第2項ただし書、施行規則第10条の25）。","r":[["貸金業法","13の3"],["貸金業法施行規則","10の25"]]},"b":{"t":false,"p":"年収証明書が必要になる基準は「極度額が50万円超」ではなく、「極度方式個人顧客合算額が100万円超」です。","w":"第13条の3第3項。極度方式個人顧客合算額は、その極度額に自社の他の貸付けの残高と他社の貸付けの残高を合算した額です（同条第5項）。","r":[["貸金業法","13の3"]]},"c":{"t":true,"w":"基準額超過極度方式基本契約に当たると認められるときは、極度額の減額や新たな極度方式貸付けの停止の措置を講じます（第13条の4）。","r":[["貸金業法","13の4"]]},"d":{"t":false,"p":"極度額を減額しても、その後の定期的な調査は免除されません。","w":"調査が不要になる場合（施行規則第10条の25）に挙がっているのは、残高10万円以下の場合や新たな極度方式貸付けを停止している場合などで、極度額の減額は含まれません。","r":[["貸金業法施行規則","10の25"]]}}},"20-10":{"s":"営業所等での掲示（第14条）と標識（第23条）です。掲示は「顧客の見やすい場所」、標識は「公衆の見やすい場所」です。","items":{"1":{"t":false,"p":"貸付条件等の掲示場所は「公衆の見やすい場所」ではなく「顧客の見やすい場所」です。","w":"第14条第1項。これに対し、標識は「公衆の見やすい場所」に掲示します（第23条第1項）。","r":[["貸金業法","14"],["貸金業法","23"]]},"2":{"t":true,"w":"金銭の貸付けの掲示事項には「主な返済の例」が含まれます（第14条第1項第5号、施行規則第11条第3項第1号ハ）。","r":[["貸金業法","14"],["貸金業法施行規則","11"]]},"3":{"t":false,"p":"事業の規模が著しく小さい場合など、内閣府令で定める場合はウェブサイトでの公表は不要です。","w":"第23条第2項ただし書、施行規則第20条第3項。","r":[["貸金業法","23"],["貸金業法施行規則","20"]]},"4":{"t":false,"p":"第23条第1項の標識の掲示義務に、現金自動設備を除く定めはありません。","w":"標識は営業所又は事務所ごとに掲示します。","r":[["貸金業法","23"]]}}},"20-11":{"s":"広告・勧誘で表示する事項（第15条第1項、施行規則第12条）です。4つとも該当します。","items":{"a":{"t":true,"w":"金銭の貸付けでは、返済の方式並びに返済期間及び返済回数を表示します（施行規則第12条第1項第1号イ）。","r":[["貸金業法","15"],["貸金業法施行規則","12"]]},"b":{"t":true,"w":"貸付けの利率は法律で直接定められた表示事項です（第15条第1項第2号）。","r":[["貸金業法","15"]]},"c":{"t":true,"w":"賠償額の予定に関する定めをする場合の、その元本に対する割合も表示します（施行規則第12条第1項第1号ロ、第11条第3項第1号イ）。","r":[["貸金業法施行規則","12"],["貸金業法施行規則","11"]]},"d":{"t":true,"w":"担保が必要な場合の担保に関する事項も表示します（施行規則第12条第1項第1号ロ、第11条第3項第1号ロ）。","r":[["貸金業法施行規則","12"],["貸金業法施行規則","11"]]}}},"20-12":{"s":"契約締結前の書面（第16条の2）は、第1項が通常の貸付け、第2項が極度方式基本契約、第3項が保証契約です。適切なのはａだけです（1個）。","items":{"a":{"t":true,"w":"極度方式基本契約を締結しようとするときは、第16条の2第2項の書面を交付します。","r":[["貸金業法","16の2"]]},"b":{"t":false,"p":"極度方式貸付けに係る契約は、第16条の2第1項の対象から除かれています。","w":"第1項は「極度方式基本契約及び極度方式貸付けに係る契約を除く」と定めています。","r":[["貸金業法","16の2"]]},"c":{"t":false,"p":"保証契約の契約締結前の書面を交付する相手は、保証人となろうとする者だけです。貸付けに係る契約の相手方には交付しません。","w":"第16条の2第3項。","r":[["貸金業法","16の2"]]},"d":{"t":false,"p":"監督指針は、記載事項に変更が生じた場合は「再度交付する必要がある」としています。","w":"契約締結前の書面を交付した後、契約締結前に記載事項の内容に変更が生じたら、改めて交付します。"}}},"20-13":{"s":"債権譲渡の通知（第24条第1項）、譲受人への規制の準用（同条第2項）、取立て制限者への譲渡禁止（同条第3項）です。","items":{"1":{"t":false,"p":"譲受人が貸金業者でも、通知は省略できません。","w":"第24条第1項は、債権を「他人に」譲渡するときに通知するとしており、相手が貸金業者の場合を除外していません。","r":[["貸金業法","24"]]},"2":{"t":false,"p":"譲渡後に契約締結時の書面（第17条）の交付義務を負うのは、譲渡したＡではなく譲り受けたＢです。","w":"第24条第2項で、第17条などの規定が債権の譲受人に準用されます。","r":[["貸金業法","24"]]},"3":{"t":true,"w":"譲渡後に取立て制限者が債権を譲り受けることを「知り、若しくは知ることができるとき」は譲渡してはならず（第24条第3項）、行政処分の対象になります（第24条の6の4第1項第4号）。","r":[["貸金業法","24"],["貸金業法","24の6の4"]]},"4":{"t":false,"p":"Ａが相当の注意を払ったことを証明できれば、行政処分の対象になりません。","w":"密接な関係を有する者への譲渡で取立て規制違反があった場合の処分は、Ａが相当の注意を払ったことを証明できなかったときに限られます（第24条第4項、第24条の6の4第1項第9号）。","r":[["貸金業法","24"],["貸金業法","24の6の4"]]}}},"20-14":{"s":"業務改善命令・登録取消し・事業報告書・協会非加入業者の社内規則の問題です。","items":{"a":{"t":false,"p":"業務改善命令は法令違反がある場合に限られません。「資金需要者等の利益の保護を図るため必要があると認めるとき」に命じることができます。","w":"第24条の6の3第1項。","r":[["貸金業法","24の6の3"]]},"b":{"t":true,"w":"暴力団員等を業務に従事させること等を禁じた第12条の5に違反したときは、登録を取り消さなければなりません（第24条の6の5第1項第5号）。「取り消すことができる」ではなく義務的な取消しです。","r":[["貸金業法","24の6の5"],["貸金業法","12の5"]]},"c":{"t":true,"w":"事業報告書は事業年度ごとに作成し、毎事業年度経過後3か月以内に提出します（第24条の6の9）。","r":[["貸金業法","24の6の9"]]},"d":{"t":false,"p":"その都度承認が必要なのは、登録行政庁から作成・変更を命じられて承認を受けた社内規則を変更・廃止する場合です。","w":"協会に加入していない業者に対し、登録行政庁は社内規則の作成・変更を命じることができ、命じられた業者は30日以内に作成・変更して承認を受けます。その社内規則の変更・廃止にも承認が必要です（第24条の6の12）。","r":[["貸金業法","24の6の12"]]}}},"20-15":{"s":"指定信用情報機関どうしの情報交流と、信用情報の提供依頼に必要な同意です。","items":{"1":{"t":false,"p":"全国銀行個人信用情報センターは、貸金業法の指定信用情報機関ではありません。","w":"指定信用情報機関は第41条の13第1項の指定を受けた者です（第2条第16項）。取り込んだ資料には指定を受けた機関の一覧がないため、この肢は公式の正答に基づいて誤りとしています。","r":[["貸金業法","2"],["貸金業法","41の13"]]},"2":{"t":true,"w":"第41条の24第1項のとおりです。他の機関の加入貸金業者の依頼に基づく提供依頼には、正当な理由がない限り応じなければなりません。","r":[["貸金業法","41の24"]]},"3":{"t":false,"p":"極度方式基本契約は「個人信用情報」の対象から除かれています。","w":"第2条第14項は個人信用情報から「極度方式基本契約その他の内閣府令で定めるもの」を除いています（施行規則第1条の2の3第1号）。","r":[["貸金業法","2"],["貸金業法施行規則","1の2の3"]]},"4":{"t":false,"p":"返済能力の調査が目的でも、あらかじめ資金需要者等の同意を得なければなりません。","w":"第41条の36第1項。同意が不要になるのは内閣府令で定める場合だけです。","r":[["貸金業法","41の36"]]}}},"20-16":{"s":"廃業等の届出（第10条）は、届出をする人と期限（30日以内）がポイントです。","items":{"1":{"t":true,"w":"死亡の場合は相続人が、その事実を知った日から30日以内に届け出ます（第10条第1項第1号）。","r":[["貸金業法","10"]]},"2":{"t":false,"p":"合併で消滅した場合に届け出るのは、存続会社Ｂの代表取締役ではなく、消滅した法人Ａを代表する役員であった者です。","w":"第10条第1項第2号。","r":[["貸金業法","10"]]},"3":{"t":true,"w":"破産手続開始の決定があると、登録はその効力を失います（第10条第2項、同条第1項第3号）。届出は破産管財人が行います。","r":[["貸金業法","10"]]},"4":{"t":true,"w":"登録が効力を失った後も、締結した貸付けの契約に基づく取引を結了する目的の範囲内では、なお貸金業者とみなされます（第43条）。","r":[["貸金業法","43"]]}}},"20-17":{"s":"監督指針の取引時確認・疑わしい取引の届出の着眼点です。","items":{"1":{"t":true,"w":"犯罪収益移転危険度調査書を勘案してリスクを調査・分析し、特定事業者作成書面等を作成して定期的に見直すことが着眼点です。","r":[["犯罪による収益の移転防止に関する法律","3"]]},"2":{"t":true,"w":"実質的支配者の確認、外国PEPs該当性の確認、本人確認書類の適切な取扱いなど、取引時確認を適正に実施する態勢が着眼点です。"},"3":{"t":false,"p":"参考事例に機械的に当てはめるのではありません。取引時確認情報や取引時の状況など、保有する具体的な情報を総合的に勘案して届出の要否を判断します。","w":"監督指針は、取得した取引時確認情報、取引時の状況その他の具体的な情報を総合的に勘案したうえで、犯収法第8条第2項等に基づき判断することを求めています。","r":[["犯罪による収益の移転防止に関する法律","8"]]},"4":{"t":true,"w":"取引時確認と疑わしい取引の届出の判断を一体的・一元的に行う社内体制が求められています。"}}},"20-18":{"s":"証明書の携帯、禁止行為、生命保険契約の制限、誇大広告の禁止です。","items":{"1":{"t":false,"p":"営業所等で資金需要者等と対面せずに行う業務は、証明書の携帯義務の対象外です。","w":"施行規則第10条の9第2項：第12条の4第1項の業務には、勧誘を伴わない広告のみの業務と、営業所等で資金需要者等と対面せずに行う業務を含みません。","r":[["貸金業法","12の4"],["貸金業法施行規則","10の9"]]},"2":{"t":true,"w":"第12条の6第2号の禁止行為です。","r":[["貸金業法","12の6"]]},"3":{"t":true,"w":"第12条の7のとおり、相手方の死亡で保険金を受け取る保険契約では、自殺による死亡を保険事故としてはなりません。","r":[["貸金業法","12の7"]]},"4":{"t":true,"w":"公的な年金・手当等の受給者の借入意欲をそそるような表示・説明は禁止されています（第16条第2項第4号）。","r":[["貸金業法","16"]]}}},"20-19":{"s":"総量規制の対象外になる「除外契約」（施行規則第10条の21）と、総量規制の例外になる「例外契約」（同第10条の23）を区別する問題です。","items":{"1":{"t":true,"w":"売却予定の不動産の売却代金で弁済される貸付けは、除外契約です（施行規則第10条の21第1項第7号）。","r":[["貸金業法施行規則","10の21"]]},"2":{"t":false,"p":"不動産担保の除外契約からは、個人顧客の居宅が除かれています。居宅を担保とする貸付けは第10条の21の除外契約に当たりません。","w":"施行規則第10条の21第1項第6号は、居宅や生計維持に不可欠な不動産を除いた不動産を担保とする貸付けを定めています。","r":[["貸金業法施行規則","10の21"]]},"3":{"t":true,"w":"住宅資金貸付けまでのつなぎ融資は除外契約です（施行規則第10条の21第1項第2号）。","r":[["貸金業法施行規則","10の21"]]},"4":{"t":true,"w":"本人又は生計を一にする親族の高額療養費の支払に必要な資金の貸付けは除外契約です（同第4号）。","r":[["貸金業法施行規則","10の21"]]}}},"20-20":{"s":"例外契約（施行規則第10条の23）の要件です。つなぎ融資の返済期間は1か月です。","items":{"1":{"t":true,"w":"事業を営む個人顧客への貸付けは、実地調査や直近の確定申告書の確認などで事業の実態が確認されていることが要件の1つです（第10条の23第1項第4号イ）。","r":[["貸金業法施行規則","10の23"]]},"2":{"t":true,"w":"貸付金額が100万円以下なら、事業計画等に代えて、事業の状況・収支の状況・資金繰りの状況に照らして返済能力を超えないと認められればよいとされています（同号ロ）。","r":[["貸金業法施行規則","10の23"]]},"3":{"t":false,"p":"返済期間は3か月ではなく1か月を超えないことが要件です。","w":"金融機関からの正規貸付けまでのつなぎ融資（極度方式基本契約を除く）は、正規貸付けが確実で、返済期間が1か月を超えないものが例外契約です（第10条の23第1項第6号）。","r":[["貸金業法施行規則","10の23"]]},"4":{"t":true,"w":"例外契約は総量規制の「例外」で、その残高は個人顧客合算額に算入されます。算入されないのは住宅資金貸付契約等（除外契約）の残高です。","r":[["貸金業法","13"],["貸金業法","13の2"]]}}},"20-21":{"s":"契約締結時の書面（第17条）の記載事項・交付方法です。電磁的方法には相手方の承諾が必要です。","items":{"1":{"t":true,"w":"極度方式基本契約の書面には「極度方式基本契約に関し貸金業者が受け取る書面の内容」を記載します（施行規則第13条）。","r":[["貸金業法施行規則","13"]]},"2":{"t":true,"w":"登録番号の括弧書は記載を省略できます（施行規則第13条）。","r":[["貸金業法施行規則","13"]]},"3":{"t":true,"w":"マンスリーステートメントを交付する場合は、契約年月日・貸付けの金額などを記載した簡素な書面で代えられます（第17条第6項）。","r":[["貸金業法","17"]]},"4":{"t":false,"p":"電磁的方法で提供できるのは、相手方の「承諾を得た」場合です。書面を希望する申出がなければよい、という仕組みではありません。","w":"第17条第7項。","r":[["貸金業法","17"]]}}},"20-22":{"s":"契約締結時の書面を交付した後の変更で、書面を再交付する必要があるかどうかです（施行規則第13条第2項）。","items":{"1":{"t":true,"w":"貸付けの利率は、引き下げるなど相手方の利益となる変更なら再交付は不要です（施行規則第13条第2項第1号イ）。","r":[["貸金業法","17"],["貸金業法施行規則","13"]]},"2":{"t":false,"p":"各回の返済金額は、相手方の利益となる変更（減額）でも再交付が必要な事項です。","w":"「各回の返済期日及び返済金額」は施行規則第13条第2項第1号ロに入っており、イのような「利益となる変更なら除く」という扱いがありません。","r":[["貸金業法施行規則","13"]]},"3":{"t":true,"w":"期限の利益の喪失の定めは、相手方の利益となる変更なら再交付は不要です（施行規則第13条第2項第1号イ）。","r":[["貸金業法施行規則","13"]]},"4":{"t":true,"w":"保証人に関する事項で再交付が必要なのは、新たに保証契約を締結する場合に限られます（施行規則第13条第2項第1号ロ）。保証契約の解除なら不要です。","r":[["貸金業法施行規則","13"]]}}},"20-23":{"s":"取立て行為の規制（第21条）と、監督指針が示す「正当な理由」の例です。","items":{"1":{"t":true,"w":"午後9時〜午前8時の連絡・訪問の禁止（第21条第1項第1号）について、監督指針は「債務者等と連絡をとるための合理的方法が他にない場合」を正当な理由に当たる可能性が高い例に挙げています。","r":[["貸金業法","21"]]},"2":{"t":true,"w":"債務者等が申し出た時期以外の連絡等の禁止（第21条第1項第2号）について、監督指針は「直近において申し出が履行されていない場合」を正当な理由に当たる可能性が高い例に挙げています。","r":[["貸金業法","21"]]},"3":{"t":false,"p":"正当な理由なく勤務先を訪問すると告げることは、それ自体が禁止行為です。","w":"第21条第1項第10号は、同項の各号（第6号を除く）の言動をすることを債務者等に告げることを禁止しています。勤務先訪問（第3号）を告げることもこれに当たります。","r":[["貸金業法","21"]]},"4":{"t":true,"w":"監督指針は、家族に知られないよう要請を受けている場合以外は、自宅への電話で家族に貸金業者と名乗ることや、郵送物の差出人として貸金業者と示すことは、直ちに第21条第1項第5号違反ではないとしています。","r":[["貸金業法","21"]]}}},"20-24":{"s":"開始等の届出（第24条の6の2、施行規則第26条の25）に当たる事由です。","items":{"1":{"t":false,"p":"政令で定める使用人の破産手続開始の決定は、開始等の届出の事由に入っていません。","w":"届出が必要なのは、役員・重要な使用人が第6条第1項第1号又は第4号〜第7号に該当することとなった事実を知った場合です（施行規則第26条の25第1項第2号）。破産（第6条第1項第2号）は含まれません。","r":[["貸金業法","24の6の2"],["貸金業法施行規則","26の25"]]},"2":{"t":true,"w":"主任者の設置要件（第6条第1項第13号）を欠くことになった場合は届出事由です（施行規則第26条の25第1項第1号）。","r":[["貸金業法施行規則","26の25"]]},"3":{"t":true,"w":"役員又は使用人に業務に関する法令違反行為等があったことを知った場合は届出事由です（施行規則第26条の25第1項第4号）。","r":[["貸金業法施行規則","26の25"]]},"4":{"t":true,"w":"純資産額の要件（第6条第1項第14号）に該当するに至ったことを知ったときは届出が必要です（第24条の6の2第3号）。最低純資産額は政令で5,000万円と定められています。","r":[["貸金業法","24の6の2"],["貸金業法施行令","3の2"]]}}},"20-25":{"s":"出資法・利息制限法・貸金業法の上限金利と、違反したときの効果（無効・刑事罰・行政処分）の区別です。","items":{"1":{"t":true,"w":"出資法第4条第1項のとおり、媒介手数料の上限は貸借の金額の100分の5（期間1年未満は年5％で日割り）です。","r":[["出資法","4"]]},"2":{"t":true,"w":"営業的金銭消費貸借の賠償額の予定は、年2割を超える部分が無効です（利息制限法第7条第1項）。","r":[["利息制限法","7"]]},"3":{"t":true,"w":"業として行う保証の保証料は、法定上限額から利息の額を差し引いた額を超える部分が無効です（利息制限法第8条第1項）。","r":[["利息制限法","8"]]},"4":{"t":false,"p":"利息制限法の上限を超える利息の契約の締結は、貸金業法上、刑事罰ではなく行政処分の対象です。","w":"第12条の8第1項に違反すると、業務改善命令や登録取消し・業務停止の対象になります（第24条の6の3、第24条の6の4）。刑事罰があるのは年20％を超える利息の契約です（出資法第5条第2項）。","r":[["貸金業法","12の8"],["貸金業法","24の6の4"],["出資法","5"]]}}},"20-26":{"s":"利息制限法第5条の元本額の特則は、「同一の債権者」からの貸付けを合算します。","items":{"1":{"t":true,"w":"同時に2口借りたときは元本を合計します（第5条第2号）。50万円＋100万円＝150万円なので上限は年15％です。","r":[["利息制限法","5"],["利息制限法","1"]]},"2":{"t":true,"w":"既に負担している債務の残元本と新たな元本を合計します（第5条第1号）。30万円＋70万円＝100万円なので上限は年15％です。","r":[["利息制限法","5"],["利息制限法","1"]]},"3":{"t":true,"w":"第一契約は完済済みなので合算しません。同時に借りた第二・第三契約は合計します。8万円＋30万円＝38万円なので上限は年18％です。","r":[["利息制限法","5"],["利息制限法","1"]]},"4":{"t":false,"p":"債権者が異なる（ＡとＣ）ので、元本は合算しません。第二契約の元本30万円の上限は年18％で、年18％の約定は無効になりません。","w":"第5条は「同一の債権者」から重ねて又は同時に貸付けを受けた場合の特則です。","r":[["利息制限法","5"],["利息制限法","1"]]}}},"20-27":{"s":"営業的金銭消費貸借のみなし利息です。利息とみなされないのは、法令で列挙された費用（公租公課・公的手続の費用・ATM手数料の一定額・再発行手数料など）だけです。","items":{"1":{"t":false,"p":"約定の弁済期の口座振替手続の費用は、利息とみなされます。利息とみなされないのは、弁済期に弁済できなかったときの「再度の」口座振替の費用です。","w":"利息制限法第6条第2項は利息とみなさない費用を限定しています。施行令第1条第3号は再度の口座振替手続の費用だけを除いています。","r":[["利息制限法","6"],["利息制限法施行令","1"]]},"2":{"t":true,"w":"書面の「交付」費用は利息とみなされます。利息とみなされないのは書面の「再発行」の手数料です（施行令第1条第2号）。","r":[["利息制限法","6"],["利息制限法施行令","1"]]},"3":{"t":true,"w":"カードの「発行」費用は利息とみなされます。利息とみなされないのはカードの「再発行」の手数料です（施行令第1条第1号）。","r":[["利息制限法","6"],["利息制限法施行令","1"]]},"4":{"t":true,"w":"ATM等の利用料は、1万円以下の取引なら110円、1万円超なら220円までが利息とみなされません（利息制限法第6条第2項第3号、施行令第2条）。","r":[["利息制限法","6"],["利息制限法施行令","2"]]}}},"20-28":{"s":"意思表示の到達主義、公示による意思表示、錯誤、第三者の強迫です。","items":{"1":{"t":false,"p":"意思表示は、通知を発した時ではなく、相手方に到達した時から効力を生じます。","w":"民法第97条第1項（到達主義）。","r":[["民法","97"]]},"2":{"t":false,"p":"相手方を知ることができないときも、公示の方法で意思表示ができます。","w":"民法第98条第1項：相手方を知ることができず、又はその所在を知ることができないときです。","r":[["民法","98"]]},"3":{"t":true,"w":"重要な錯誤で、表意者に重大な過失がなければ取り消すことができます（民法第95条第1項・第3項）。","r":[["民法","95"]]},"4":{"t":false,"p":"第三者の強迫の場合は、相手方が知っていたかどうかに関係なく取り消せます。相手方の知・不知が問題になるのは第三者の「詐欺」です。","w":"民法第96条第1項・第2項。","r":[["民法","96"]]}}},"20-29":{"s":"代理（顕名・表見代理・無権代理・双方代理）の問題です。","items":{"1":{"t":false,"p":"相手方Ｃが本人Ｂのためにすることを知っていたときは、契約はＢとＣの間に効力を生じます。","w":"民法第100条ただし書。顕名がなくても、相手方が知り又は知ることができたときは本人に効力が及びます。","r":[["民法","100"]]},"2":{"t":false,"p":"相手方Ｄが過失によって代理権の消滅を知らなかったときは、表見代理は成立しません。","w":"民法第112条第1項ただし書。保護されるのは善意かつ無過失の第三者です。","r":[["民法","112"]]},"3":{"t":true,"w":"無権代理の契約は、本人が追認しない間、代理権がないことを知らなかった相手方が取り消せます（民法第115条）。","r":[["民法","115"]]},"4":{"t":false,"p":"双方代理は、本人があらかじめ許諾した場合などを除き、代理権を有しない者の行為とみなされます。当然にＢＦ間に効力を生じるわけではありません。","w":"民法第108条第1項。","r":[["民法","108"]]}}},"20-30":{"s":"無効と取消しの基本です。","items":{"1":{"t":false,"p":"未成年者（制限行為能力者）は、法定代理人の同意がなくても自分で取り消せます。","w":"民法第120条第1項は、制限行為能力者本人を取消権者に挙げています。","r":[["民法","120"]]},"2":{"t":true,"w":"民法第121条：取り消された行為は、初めから無効であったものとみなされます。","r":[["民法","121"]]},"3":{"t":false,"p":"無効な行為に基づいて給付を受けた者は、原則として原状回復義務を負います。現に利益を受けている限度でよいのは、善意で無償行為の給付を受けた場合などに限られます。","w":"民法第121条の2第1項・第2項。","r":[["民法","121の2"]]},"4":{"t":false,"p":"取消権の時効は「追認をすることができる時から5年」です。「行為の時から」なら20年です。","w":"民法第126条。","r":[["民法","126"]]}}},"20-31":{"s":"根抵当権の基本です。被担保債権の範囲の限定、極度額、元本確定前の譲渡、元本確定請求がポイントです。","items":{"1":{"t":false,"p":"根抵当権の担保すべき債権の範囲は、債務者との特定の継続的取引契約から生ずるものなど、限定して定めなければなりません。","w":"民法第398条の2第2項。範囲を限定しない「包括根抵当」は認められていません。","r":[["民法","398の2"]]},"2":{"t":false,"p":"「最後の2年分」に限られるのは普通抵当権です。根抵当権は、利息・損害金も含めて極度額を限度に全部行使できます。","w":"民法第398条の3第1項。","r":[["民法","398の3"]]},"3":{"t":false,"p":"元本の確定前に債権を取得した者は、その債権について根抵当権を行使できません。","w":"民法第398条の7第1項。元本確定前の根抵当権には随伴性がありません。","r":[["民法","398の7"]]},"4":{"t":true,"w":"確定期日の定めがなければ、設定者は設定から3年を経過したときに元本の確定を請求できます（民法第398条の19第1項・第3項）。根抵当権者はいつでも請求できます（同条第2項）。","r":[["民法","398の19"]]}}},"20-32":{"s":"過失相殺、損害賠償による代位、債権者代位権、詐害行為取消権です。","items":{"1":{"t":true,"w":"民法第418条（過失相殺）のとおりです。","r":[["民法","418"]]},"2":{"t":false,"p":"価額の全部の支払を受けたときは、債権者の承諾がなくても、債務者は当然に代位します。","w":"民法第422条。","r":[["民法","422"]]},"3":{"t":false,"p":"債務者の一身に専属する権利は、債権者代位権の対象から除かれます。","w":"民法第423条第1項ただし書。","r":[["民法","423"]]},"4":{"t":false,"p":"詐害行為取消権は、裁判外では行使できません。取消しを裁判所に請求する必要があります。","w":"民法第424条第1項。","r":[["民法","424"]]}}},"20-33":{"s":"債権譲渡の対抗要件です。債務者には通知・承諾、債務者以外の第三者には確定日付のある証書による通知・承諾が必要です。","items":{"1":{"t":true,"w":"譲渡人から債務者への通知があれば、債務者に対抗できます（民法第467条第1項）。","r":[["民法","467"]]},"2":{"t":false,"p":"Ｃへの譲渡の承諾は確定日付のない証書によるもので、確定日付のある通知を備えたＤには対抗できません。","w":"債務者以外の第三者への対抗には、確定日付のある証書による通知・承諾が必要です（民法第467条第2項）。","r":[["民法","467"]]},"3":{"t":false,"p":"確定日付のある通知どうしの優劣は、確定日付の先後ではなく、通知が債務者に到達した先後で決まります。先に到達したのはＤへの譲渡の通知です。","w":"民法第467条第2項の解釈として判例が採る考え方です（条文には直接書かれていません）。","r":[["民法","467"]]},"4":{"t":false,"p":"Ｃへの譲渡の確定日付ある通知が、差押命令の送達より先に到達しているので、Ｅは差押えをＣに対抗できません。","w":"差押債権者も債務者以外の第三者に当たり、対抗要件の先後で優劣が決まります（民法第467条第2項）。","r":[["民法","467"]]}}},"20-34":{"s":"相殺の方法・効力、時効消滅した債権による相殺、相殺禁止特約です。","items":{"1":{"t":false,"p":"相殺の意思表示には、条件や期限を付けることはできません。","w":"民法第506条第1項後段。","r":[["民法","506"]]},"2":{"t":false,"p":"時効で消滅した債権でも、消滅前に相殺に適するようになっていたなら、自働債権として相殺できます。","w":"民法第508条。","r":[["民法","508"]]},"3":{"t":false,"p":"相殺の効力は将来に向かってではなく、相殺に適するようになった時にさかのぼって生じます。","w":"民法第506条第2項。","r":[["民法","506"]]},"4":{"t":true,"w":"相殺禁止・制限の特約は、第三者が知り又は重大な過失で知らなかったときに限り対抗できます（民法第505条第2項）。","r":[["民法","505"]]}}},"20-35":{"s":"相続の一般的効力、遺産分割、相続債務、相続放棄です。","items":{"1":{"t":false,"p":"被相続人の一身に専属したものは承継しません。","w":"民法第896条ただし書。","r":[["民法","896"]]},"2":{"t":true,"w":"民法第907条第1項のとおりです。遺言で禁じられた場合や分割しない旨の契約がある場合を除き、いつでも協議で分割できます。","r":[["民法","907"]]},"3":{"t":false,"p":"相続人の1人が金銭債務の全てを承継すると協議で決めても、債権者は他の相続人にも法定相続分に応じて請求できます。","w":"相続人は相続分に応じて被相続人の義務を承継し（民法第899条）、相続債権者は法定相続分に応じて各相続人に権利を行使できます（第902条の2）。","r":[["民法","899"],["民法","902の2"]]},"4":{"t":false,"p":"相続の放棄は、他の相続人への意思表示ではなく、家庭裁判所への申述によってします。","w":"民法第938条。放棄をした者は初めから相続人とならなかったものとみなされる点（第939条）は正しい内容です。","r":[["民法","938"],["民法","939"]]}}},"20-36":{"s":"破産債権、別除権、開始後の法律行為、相殺の禁止です。","items":{"1":{"t":false,"p":"破産債権は、破産手続開始「後」ではなく「前」の原因に基づいて生じた財産上の請求権です。","w":"破産法第2条第5項。","r":[["破産法","2"]]},"2":{"t":false,"p":"別除権は、破産手続によらないで行使できます。","w":"破産法第65条第1項。担保権者は破産手続の外で担保権を実行できます。","r":[["破産法","65"],["破産法","2"]]},"3":{"t":true,"w":"破産法第47条第1項のとおりです。","r":[["破産法","47"]]},"4":{"t":false,"p":"破産手続開始後に破産財団に対して負担した債務とは、相殺できません。","w":"破産法第71条第1項第1号（相殺の禁止）。","r":[["破産法","71"]]}}},"20-37":{"s":"意思能力と制限行為能力者の制度です。","items":{"1":{"t":true,"w":"民法第3条の2のとおり、意思能力を有しなかったときの法律行為は無効です。","r":[["民法","3の2"]]},"2":{"t":true,"w":"事理を弁識する能力を欠く常況にあり、後見開始の審判を受けた者が成年被後見人です（民法第7条・第8条）。","r":[["民法","7"],["民法","8"]]},"3":{"t":false,"p":"未成年者が成年者だと信じさせるために詐術を用いたときは、その行為は取り消せません。法定代理人も取り消せません。","w":"民法第21条。","r":[["民法","21"]]},"4":{"t":true,"w":"法定代理人に1か月以上の期間を定めて催告し、期間内に確答がなければ追認したものとみなされます（民法第20条第2項）。","r":[["民法","20"]]}}},"20-38":{"s":"期限と期間の計算です。","items":{"1":{"t":true,"w":"民法第135条第1項のとおりです。","r":[["民法","135"]]},"2":{"t":true,"w":"担保を滅失・損傷・減少させたときは、期限の利益を主張できません（民法第137条第2号）。","r":[["民法","137"]]},"3":{"t":true,"w":"初日不算入の原則です（民法第140条）。","r":[["民法","140"]]},"4":{"t":false,"p":"期間は、起算日に応当する日ではなく、その「前日」に満了します。","w":"民法第143条第2項。","r":[["民法","143"]]}}},"20-39":{"s":"消滅時効の期間、援用権者、時効の効力、時効利益の事前放棄です。","items":{"1":{"t":true,"w":"知った時から5年、行使できる時から10年です（民法第166条第1項）。","r":[["民法","166"]]},"2":{"t":true,"w":"保証人は消滅時効の援用権者に含まれます（民法第145条）。","r":[["民法","145"]]},"3":{"t":false,"p":"時効の効力は将来に向かってではなく、起算日にさかのぼります。","w":"民法第144条。","r":[["民法","144"]]},"4":{"t":true,"w":"時効の利益は、あらかじめ放棄できません（民法第146条）。完成前の「援用しない合意」は無効です。","r":[["民法","146"]]}}},"20-40":{"s":"保証・連帯保証で生じた事由の効力です。主たる債務者に生じた事由は保証人に及びますが、連帯保証人に生じた事由は原則として主たる債務者に及びません。","items":{"1":{"t":true,"w":"主たる債務者に対する履行の請求等による時効の完成猶予・更新は、保証人にも効力を生じます（民法第457条第1項）。","r":[["民法","457"]]},"2":{"t":true,"w":"保証人は主たる債務者の抗弁を債権者に対抗できます（民法第457条第2項）。","r":[["民法","457"]]},"3":{"t":true,"w":"主たる債務者が相殺権を有するときは、その限度で保証人は履行を拒めます（民法第457条第3項）。","r":[["民法","457"]]},"4":{"t":false,"p":"連帯保証人に対する履行の請求は、主たる債務者には効力を生じません（相対的効力）。","w":"連帯保証人に生じた事由については、更改・相殺・混同などの規定だけが準用され（民法第458条）、それ以外は相対的効力の原則（第441条）によります。","r":[["民法","458"],["民法","441"]]}}},"20-41":{"s":"弁済の充当、受領権者としての外観を有する者への弁済、第三者弁済、差押えを受けた債権の弁済です。","items":{"1":{"t":true,"w":"費用→利息→元本の順に充当します（民法第489条第1項）。","r":[["民法","489"]]},"2":{"t":false,"p":"弁済が有効になるのは、弁済者が善意で、かつ「過失がなかった」ときに限られます。","w":"民法第478条。","r":[["民法","478"]]},"3":{"t":true,"w":"抵当不動産の第三取得者は弁済について正当な利益を有するので、債務者の意思に反しても弁済できます（民法第474条第2項の反対解釈）。第三者弁済の禁止・制限の特約があれば別です（同条第4項）。","r":[["民法","474"]]},"4":{"t":true,"w":"民法第481条第1項のとおりです。","r":[["民法","481"]]}}},"20-42":{"s":"犯罪収益移転防止法の取引時確認です。確認事項は、本人特定事項・取引を行う目的・職業（法人は事業の内容）などです。","items":{"1":{"t":true,"w":"犯収法第4条第1項第1号のとおりです。","r":[["犯罪による収益の移転防止に関する法律","4"]]},"2":{"t":true,"w":"本人確認書類の住居が現在と違う場合は、現在の住居の記載がある補完書類等の送付を受けて確認する方法が定められています（犯収法施行規則第6条）。","r":[["犯罪による収益の移転防止に関する法律施行規則","6"]]},"3":{"t":true,"w":"自然人は、本人特定事項のほか、取引を行う目的と職業を確認します（犯収法第4条第1項第2号・第3号）。","r":[["犯罪による収益の移転防止に関する法律","4"]]},"4":{"t":false,"p":"法人の事業の内容は、代表者の申告ではなく、定款や登記事項証明書などの書類で確認します。","w":"犯収法施行規則第10条第2号。申告で足りるのは自然人の職業などです（同条第1号）。","r":[["犯罪による収益の移転防止に関する法律施行規則","10"]]}}},"20-43":{"s":"個人情報保護法の定義（個人情報・個人識別符号・要配慮個人情報・個人データ）です。","items":{"1":{"t":false,"p":"個人情報は「生存する」個人に関する情報に限られます。","w":"個人情報保護法第2条第1項。","r":[["個人情報の保護に関する法律","2"]]},"2":{"t":false,"p":"個人識別符号は政令で定めるものに限られ、クレジットカード番号や電話番号は含まれません。","w":"第2条第2項。通則ガイドラインが挙げる例は、旅券番号、基礎年金番号、運転免許証番号、住民票コード、個人番号などです。","r":[["個人情報の保護に関する法律","2"]]},"3":{"t":true,"w":"第2条第3項のとおりです。","r":[["個人情報の保護に関する法律","2"]]},"4":{"t":false,"p":"個人データは「個人情報データベース等を構成する」個人情報です。容易に検索できるよう体系的に構成されていない映像は、個人情報には当たっても個人データには当たりません。","w":"第16条第1項・第3項。通則ガイドラインは、防犯カメラの映像で本人が判別できるものを「個人情報」の例に挙げています。","r":[["個人情報の保護に関する法律","16"]]}}},"20-44":{"s":"金融分野ガイドラインの第三者提供（個人信用情報機関への提供・共同利用・同意の形式）です。","items":{"1":{"t":false,"p":"個人信用情報機関への返済能力情報の提供には、オプトアウトは使えません。本人の同意を得ます。","w":"金融分野ガイドライン第12条：与信事業に係る返済能力の情報を個人信用情報機関に提供するときは、法第27条第2項（オプトアウト）を適用しないこととしています。","r":[["個人情報の保護に関する法律","27"]]},"2":{"t":true,"w":"個人信用情報機関を通じて会員企業にも提供されるため、提供する事業者が本人の同意を得ることとされています（金融分野ガイドライン第12条）。"},"3":{"t":false,"p":"共同利用者を個別に全て列挙することは「望ましい」とされているだけで、外延を示して本人に通知する方法も認められています。","w":"金融分野ガイドライン第12条：外延を示す場合は本人が容易に理解できるよう具体的に特定する必要があり、例として「有価証券報告書等に記載されている当社の子会社」が挙げられています。","r":[["個人情報の保護に関する法律","27"]]},"4":{"t":false,"p":"金融分野では、第三者提供の同意は原則として書面（電磁的記録を含む）で得ることとされています。","w":"金融分野ガイドライン第3条（同意の形式）。","r":[["個人情報の保護に関する法律","27"]]}}},"20-45":{"s":"利用目的による制限と、取得時の利用目的の通知・公表です。","items":{"1":{"t":true,"w":"個人情報保護法第18条第1項のとおりです。","r":[["個人情報の保護に関する法律","18"]]},"2":{"t":true,"w":"事業承継に伴う取得で、承継前の利用目的の範囲内で取り扱うなら同意は不要です（第18条第2項）。","r":[["個人情報の保護に関する法律","18"]]},"3":{"t":false,"p":"本人がインターネット上で自発的に公にしている個人情報でも、取得したら利用目的の通知又は公表が必要です（単に閲覧しただけの場合を除く）。","w":"第21条第1項。通則ガイドラインは、これを「本人への通知又は公表が必要な事例」に挙げています。","r":[["個人情報の保護に関する法律","21"]]},"4":{"t":true,"w":"第17条第2項のとおりです。","r":[["個人情報の保護に関する法律","17"]]}}},"20-46":{"s":"自主規制基本規則の勧誘ルールです。勧誘を断られた後に見合わせる期間は、拒否の内容によって3か月・6か月などに分かれます。","items":{"1":{"t":true,"w":"自主規制基本規則第54条第1項：債務者等に勧誘するときは、勧誘することについて承諾を得なければなりません。"},"2":{"t":true,"w":"同条第5項：勧誘リスト等に個人信用情報を記載等しないよう留意しなければなりません。"},"3":{"t":true,"w":"同条第4項：身体的・精神的な障害等で契約内容の理解が困難なことを認識した場合は、勧誘してはなりません。"},"4":{"t":false,"p":"単に契約しない意思を示した場合に勧誘を見合わせる期間は、1年ではなく最低3か月です。","w":"自主規制基本規則：「今はいらない」など一定期間の拒否を明示した場合は最低6か月、それ以外で契約しない意思を示した場合は最低3か月です。"}}},"20-47":{"s":"紛争解決等業務に関する規則の定義と、協会員等の義務です。","items":{"1":{"t":false,"p":"「貸金業務等関連苦情」は、単に「不満足の表明」をいいます。「自主的な交渉では解決ができないもので、和解ができるもの」は「貸金業務関連紛争」の定義です。","w":"紛争解決等業務に関する規則第2条第1号・第2号。"},"2":{"t":true,"w":"協会員等は、センターの紛争解決等業務の内容・手続の概要・受付窓口などを、ウェブサイトや店頭への掲示など適切な方法で公表しなければなりません。"},"3":{"t":true,"w":"協会員等との間で苦情を有する契約者等（個人・法人・代表者等の定めのある団体）は、苦情処理手続開始の申立てができます。"},"4":{"t":true,"w":"規則第47条：当事者である協会員等は、正当な理由なく事情の聴取及び資料提出の求めを拒むことはできません。"}}},"20-48":{"s":"損益計算書の区分と各段階の利益です。会社計算規則は取り込んでいないため、同じ考え方を定めた企業会計原則の損益計算書原則で確認します。","items":{"1":{"t":true,"w":"売上高・売上原価・販売費及び一般管理費・営業外収益・営業外費用・特別利益・特別損失に区分して表示します。"},"2":{"t":false,"p":"当期純利益は、経常利益からではなく、税引前当期純利益（経常利益＋特別利益－特別損失）から法人税等を控除した額です。","w":"企業会計原則 第二 損益計算書原則 七・八。"},"3":{"t":false,"p":"経常利益に特別利益・特別損失は入りません。経常利益は、営業利益に営業外収益を加え、営業外費用を控除した額です。","w":"企業会計原則 第二 損益計算書原則 五。"},"4":{"t":false,"p":"売上総利益は、売上高から売上原価だけを控除した額です。販売費及び一般管理費まで控除すると営業利益になります。","w":"企業会計原則 第二 損益計算書原則 三。"}}},"20-49":{"s":"企業会計原則の一般原則は7つです（真実性・正規の簿記・資本取引と損益取引の区分・明瞭性・継続性・保守主義・単一性）。","items":{"1":{"t":true,"w":"一般原則一（真実性の原則）です。"},"2":{"t":false,"p":"一般原則にあるのは「資本取引と損益取引とを明瞭に区別し、特に資本剰余金と利益剰余金とを混同してはならない」（資本取引・損益取引区分の原則）です。「事業・財務収益区分の原則」はありません。","w":"企業会計原則 第一 一般原則 三。"},"3":{"t":true,"w":"一般原則五（継続性の原則）です。"},"4":{"t":true,"w":"一般原則六（保守主義の原則）です。"}}},"20-50":{"s":"貸借対照表の区分です。会社計算規則は取り込んでいないため、企業会計原則の貸借対照表原則で確認します。","items":{"1":{"t":true,"w":"資産の部は、流動資産・固定資産・繰延資産に区分します（企業会計原則 第三 貸借対照表原則 二も同じ区分です）。"},"2":{"t":false,"p":"負債の部は、流動負債と固定負債に区分します。「引当金その他の負債」という区分はありません。","w":"企業会計原則 第三 貸借対照表原則 二：負債の部を流動負債及び固定負債に区分しなければならない。"},"3":{"t":true,"w":"株式会社の純資産の部は、株主資本・評価換算差額等・株式引受権・新株予約権に区分します（公式の正答で〇とされている肢です。会社計算規則は取り込んでいません）。"},"4":{"t":true,"w":"資産＝負債＋純資産なので、資産の合計から負債の合計を差し引いた額は純資産の合計と一致します（企業会計原則 第三 一Ｅ）。"}}}};
